It states that for each fixed $k\ge2$, there is a sharp threshold \emph{sequence} $\alpha_\textup{sat}(n)$
such that for all $\epsilon>0$,
	\begin{equation}\label{e:friedgut}
	\lim_{n\to\infty}\mathbb{P}^{n,\alpha_\textup{sat}(n)-\epsilon}(\textup{satisfiable})
	=1=\lim_{n\to\infty}
	\mathbb{P}^{n,\alpha_\textup{sat}(n)+\epsilon}(\textup{unsatisfiable}).
	\end{equation}

 The SK spin glass is defined as the probability measure on $\vec{x}\in\set{\SPIN{+},\SPIN{-}}^n$ given by
	\[\mu(\vec{x}) = \frac{1}{Z}
	\prod_{1\le i<j\le n}
	\exp\{ \beta g_{ij}
	x_ix_j\}\,,\]
where $Z$ is the partition function (normalizing constant).

One characterization of the condensation threshold is
	\[\alpha_\textup{cond}
	=\inf\set{\alpha : s_1\ne s_\star }\]
where $s_1$ and $s_\star$ are both functions of $\alpha$, defined by
	{\setlength{\jot}{0pt}\begin{align*}
	s_1 &= \textup{arg\,max}_s
		\set{ s +\Sigma(s) : 0\le s\le \ln2}\,,\\
	s_\star	&= \textup{arg\,max}_s
		\set{ s +\Sigma(s) :
		\textup{$0\le s\le \ln2$ and
		$\Sigma(s)\ge0$}
		}\,.
	\end{align*}}
For $\alpha<\alpha_\textup{cond}$, the solution space $\textup{\textsf{\footnotesize SOL}}$ is dominated by clusters of size $\exp\{ns_1\}$, of which there are exponentially many ($\exp\{n\Sigma(s_1)\}$).

\begin{align*}
	s_1 &= \textup{arg\,max}_s
		\set{ s +\Sigma(s) : 0\le s\le \ln2}\,,\\
	s_\star	&= \textup{arg\,max}_s
		\set{ s +\Sigma(s) :
		\textup{$0\le s\le \ln2$ and
		$\Sigma(s)\ge0$}
		}\,.
	\end{align*}

\label{p:phi} Given $k,\alpha$, let $\mu=\mu^{\infty,\alpha}$ be the fixed point of Proposition~\ref{p:fp}. Let $\smash{\vec{d}}$ and $\smash{\vec{\eta}}$ be as above, and let $\smash{\vec{\eta}}'\equiv(\eta_j)_{j\ge1}$ another sequence of i.i.d.\ samples from $\mu$ (independent of $\smash{\vec{d}},\smash{\vec{\eta}}$). Let
	\begin{equation}\label{e:phi.alpha}
	\Phi(\alpha)
	=\mathbb{E}\bigg[
	\ln\frac{ \Pi^\SPIN{+}+\Pi^\SPIN{-}-
		\Pi^\SPIN{+}\Pi^\SPIN{-} }
		{ (1- \prod_{j=1}^k \eta_j
			)^{\alpha(k-1)} }
	\bigg]\,,
	\end{equation}
where $\mathbb{E}$ indicates the expectation over $(\smash{\vec{d}},\smash{\vec{\eta}},\smash{\vec{\eta}}')$. For $k\ge k_0$, the function $\Phi$ is well-defined and strictly decreasing on the interval $\alpha_\textup{lbd}\le\alpha\le\alpha_\textup{ubd}$, with a unique zero $\alpha_\star\equiv\alpha_\star(k)$.

Let
