	\Phi(\alpha)
	=\mathbb{E}\bigg[
	\ln\frac{ \Pi^\SPIN{+}+\Pi^\SPIN{-}-
		\Pi^\SPIN{+}\Pi^\SPIN{-} }
		{ (1- \prod_{j=1}^k \eta_j
			)^{\alpha(k-1)} }
