where $\mathbb{E}$ indicates the expectation over $(\smash{\vec{d}},\smash{\vec{\eta}},\smash{\vec{\eta}}')$.

For any $\beta\in[0,\infty)$, it is proved \cite{MR2095932} that 
	\begin{equation}\label{e:fl.pt.ubd}
	\frac{\mathbb{E}[ \ln Z(\beta) ]}{n}
	\le \inf_{\zeta,m}
	\Phi_{\textup{1-\textsc{rsb}}}(\beta,\zeta,m)
	\end{equation}
where $\zeta$ runs over the space of probability measures over $\mathbb{R}$, $m$ is the $\textup{1-\textsc{rsb}}$ ``Parisi parameter''
which goes over $[0,1]$, and the functional $\Phi_{\textup{1-\textsc{rsb}}}$ is given explicitly in the statement of Theorem~\ref{t:free.energy} below.

\label{d:formal.random.ksat} To generate an instance of the \bemph{random $\textup{$k$-\textsc{sat}}$ model at clause density $\alpha$}, start with $n$ labelled variables $V = [n] \equiv \set{1,\ldots,n}$, as well as $M$ labelled clauses $F = [M]\equiv\set{1,\ldots,M}$, where $M$ is sampled from the $\textup{\textsf{Pois}}(n\alpha)$ distribution. Independently for each clause $a\in F$, sample its $k$-tuple of variables $\partial a$ uniformly at random from $V^k=[n]^k$, then sample the $k$-tuple of signs $(\SPIN{L}_e)_{e\in\delta a}$ uniformly at random from $\set{\SPIN{+},\SPIN{-}}^k$. This defines a family of probability measures $\mathbb{P}\equiv\mathbb{P}^{n,\alpha}$ over $\textup{$k$-\textsc{sat}}$ instances, indexed by $n$ and parametrized by the expected clause density $\alpha$. Writing $\mathbb{P}_{n,m}$ for the measure $\mathbb{P}$ conditioned on $M=m$, we can decompose
	\begin{equation}\label{e:poisson.erdos.renyi}
	\mathbb{P} \equiv \mathbb{P}^{n,\alpha}
	= \sum_{m\ge0} \textup{\textsf{pois}}_{n\alpha}(m)\mathbb{P}_{n,m}\,,\quad
	\textup{\textsf{pois}}_\lambda(m) \equiv \frac{e^{-\lambda}\lambda^m}{m!}\,.\end{equation}
Note that the conditional measure $\mathbb{P}_{n,m}$ does not depend on $\alpha$.

