\label{d:wp} For integers $K\ge1$ and $D\ge0$, define the mappings
	\begin{align*}
	\hat{W}(\dot{\SPIN{w}}_1,\ldots,\dot{\SPIN{w}}_K)
	&= \left\{\begin{array}{rl}
	\SPIN{+} &\textup{if }
	 \dot{\SPIN{w}}_i=\SPIN{-}
		\textup{ for all }1\le i\le K\,,\\
	\SPIN{f} & \textup{otherwise;}
	\end{array}\right. \\
	\dot{W}(\hat{\SPIN{w}}_1,\ldots,\hat{\SPIN{w}}_D)
	&=\left\{\begin{array}{rl}
	\SPIN{+} & \textup{if }
		\SPIN{+} \in \set{\hat{\SPIN{w}}_1,\ldots,\hat{\SPIN{w}}_D}
			\subseteq \set{\SPIN{+},\SPIN{f}}\,,\\
	\SPIN{-} & \textup{if }
		\SPIN{+} \in \set{\hat{\SPIN{w}}_1,\ldots,\hat{\SPIN{w}}_D}
			\subseteq \set{\SPIN{-},\SPIN{f}}\,,\\
	\SPIN{f} &\textup{if }
		\set{\hat{\SPIN{w}}_1,\ldots,\hat{\SPIN{w}}_D}
		\subseteq\set{\SPIN{f}}\,,\\
	\varnothing & \textup{otherwise}.
	\end{array}\right.
	\end{align*}
In the case $D=0$, the input to the function $\dot{W}$ is empty, and the output is $\SPIN{f}$. On a $\textup{$k$-\textsc{sat}}$ instance $\mathscr{G}\equiv(V,F,E)$, a \bemph{warning configuration} is a tuple $\vec{\SPIN{w}}$ of spins $\SPIN{w}_e \equiv(\dot{\SPIN{w}}_e,\hat{\SPIN{w}}_e) \in\set{\SPIN{+},\SPIN{-},\SPIN{f}}\times\set{\SPIN{+},\SPIN{f}}$, indexed by edges $e\in E$, such that the \bemph{warning propagation equations} are satisfied:
	\begin{align}\nonumber
	\hat{\SPIN{w}}_e
	=\widehat{\textup{\footnotesize\textsf{WP}}}_e[\dot{\SPIN{w}}]
	&\equiv\hat{W}_{k-1}
	\bigg(
	\dot{\SPIN{w}}_{e'} : e' \in \delta a(e)\setminus e
	\bigg)\,,\\
	\dot{\SPIN{w}}_e
	=\dot{\textup{\footnotesize\textsf{WP}}}_e[\hat{\SPIN{w}}]
	&\equiv \dot{W}
	\bigg( \SPIN{L}_{e'} \SPIN{L}_e\hat{\SPIN{w}}_{e'} 
	: e' \in \delta v(e)\setminus e \bigg)\,.
	\label{e:dot.WP}
	\end{align}
for all edges $e\in E$. (Note that for $\vec{\SPIN{w}}$ to be a valid warning configuration, we require each $\dot{\SPIN{w}}_e$ to be an element of $\set{\SPIN{+},\SPIN{-},\SPIN{f}}$, which means $\dot{\textup{\footnotesize\textsf{WP}}}_e$ must not output $\varnothing$ for any $e\in E$. We remark also that taking $\dot{\SPIN{w}}_e=\hat{\SPIN{w}}_e=\SPIN{f}$ for all $e\in E$
gives rise always to a valid warning configuration.)

\begin{align}\nonumber
	\hat{\SPIN{w}}_e
	=\widehat{\textup{\footnotesize\textsf{WP}}}_e[\dot{\SPIN{w}}]
	&\equiv\hat{W}_{k-1}
	\bigg(
	\dot{\SPIN{w}}_{e'} : e' \in \delta a(e)\setminus e
	\bigg)\,,\\
	\dot{\SPIN{w}}_e
	=\dot{\textup{\footnotesize\textsf{WP}}}_e[\hat{\SPIN{w}}]
	&\equiv \dot{W}
	\bigg( \SPIN{L}_{e'} \SPIN{L}_e\hat{\SPIN{w}}_{e'} 
	: e' \in \delta v(e)\setminus e \bigg)\,.
	\label{e:dot.WP}
	\end{align}

 \label{d:color.model}
Let $\textup{\textsf{proj}}$ be the mapping which sends warnings $\SPIN{w}\equiv(\dot{\SPIN{w}},\hat{\SPIN{w}})$ to \bemph{colors} $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$, according to the following rules:
	\[
	\textup{\textsf{proj}}(\dot{\SPIN{w}},\hat{\SPIN{w}})
	=\left\{
	\begin{array}{rll}
	\SSPIN{r}\equiv\SPIN{red}
	& \textup{if $\hat{\SPIN{w}}=\SPIN{+}$
	and $\dot{\SPIN{w}}\in\set{\SPIN{+},\SPIN{-}}$}
	& \textup{(clause forces this edge to be satisfied),}\\
	\SSPIN{y}\equiv\SSPIN{yellow}
	& \textup{if 
	$(\dot{\SPIN{w}},\hat{\SPIN{w}})=(\SPIN{-},\SPIN{f})$}
	&\textup{(variable forced to negate edge;
		clause not forcing on edge),}\\
	\SSPIN{g}\equiv\SSPIN{green}
	& \textup{if 
	$(\dot{\SPIN{w}},\hat{\SPIN{w}})=(\SPIN{f},\SPIN{f})$}
	&\textup{(no forcing warnings across this edge)},\\
	\SSPIN{b}\equiv\SSPIN{blue}
	&\textup{if 
	$(\dot{\SPIN{w}},\hat{\SPIN{w}})=(\SPIN{f},\SPIN{+})$}
	&\textup{(variable forced to affirm edge;
		clause not forcing on edge).}
	\end{array}
	\right.
	\]
A valid \bemph{coloring} of $\mathscr{G}=(V,F,E)$ is any
configuration $\smash{\vec{\sigma}}\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^E$ that can be obtained by taking a valid warning configuration $\vec{\SPIN{w}}$
and applying $\textup{\textsf{proj}}$ on each edge.

\[
	\textup{\textsf{proj}}(\dot{\SPIN{w}},\hat{\SPIN{w}})
	=\left\{
	\begin{array}{rll}
	\SSPIN{r}\equiv\SPIN{red}
	& \textup{if $\hat{\SPIN{w}}=\SPIN{+}$
	and $\dot{\SPIN{w}}\in\set{\SPIN{+},\SPIN{-}}$}
	& \textup{(clause forces this edge to be satisfied),}\\
	\SSPIN{y}\equiv\SSPIN{yellow}
	& \textup{if 
	$(\dot{\SPIN{w}},\hat{\SPIN{w}})=(\SPIN{-},\SPIN{f})$}
	&\textup{(variable forced to negate edge;
		clause not forcing on edge),}\\
	\SSPIN{g}\equiv\SSPIN{green}
	& \textup{if 
	$(\dot{\SPIN{w}},\hat{\SPIN{w}})=(\SPIN{f},\SPIN{f})$}
	&\textup{(no forcing warnings across this edge)},\\
	\SSPIN{b}\equiv\SSPIN{blue}
	&\textup{if 
	$(\dot{\SPIN{w}},\hat{\SPIN{w}})=(\SPIN{f},\SPIN{+})$}
	&\textup{(variable forced to affirm edge;
		clause not forcing on edge).}
	\end{array}
	\right.
	\]

\begin{equation}\label{e:EVAL.of.color}
	x_v = \textup{\textsf{eval}}_v(\smash{\vec{\sigma}}_{\delta v})
	\equiv\left\{\hspace{-5pt}\begin{array}{rll}
	\SPIN{+} & \text{if
