\label{d:coherence}
For a clause $a\in F$, suppose $\pi=(\pi_e)_{e\in\delta a}$ where each $\pi_e$ is any probability measure over $\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$. We say that $\pi$ is \bemph{weakly coherent} if it satisfies the following:
	\begin{equation}\label{e:cohere.y.for.r}
	\textup{\textsf{coher}}_e(\pi) \equiv
	\pi_e(\SSPIN{y})
	- \sum_{e' \in\delta a \setminus e}
	\pi_{e'}(\SSPIN{r}) \ge 0\,,
	\end{equation}
for each $e\in\delta a$; and with $\pi_e(\SSPIN{c}) \equiv \pi_e(\SSPIN{b})+\pi_e(\SSPIN{g})$ we have
	\begin{equation}\label{e:cohere.enough.cyan}
	\textup{\textsf{coher}}_a(\pi)
	\equiv \sum_{e\in\delta a}
	\pi_e(\SSPIN{c}) - 2\bigg\{
	1 - \sum_{e\in\delta a}\pi_e(\SSPIN{r})
	\bigg\} \ge 0\,.\end{equation}
We say that $\pi$ is \bemph{strictly coherent} if condition~\eqref{e:cohere.enough.cyan} holds with strict inequality, and condition~\eqref{e:cohere.y.for.r} holds with strict inequality for each $e\in\delta a$ where $\pi_e(\SSPIN{y})>0$. We then say that the clause $a$ is \bemph{weakly (strictly) coherent} if it is acyclic, and its canonical edge marginals ${}_\star\hspace{-1pt}\pi=({}_\star\hspace{-1pt}\pi_e)_{e\in\delta a}$ are weakly (strictly) coherent.

\label{d:stable}
Suppose the edge $e=(av)$ is acyclic (Definition~\ref{d:simple.types}), so that all the messages and marginals of Definition~\ref{d:canonical} are well-defined. As we noted above --- and will prove in Lemma~\ref{l:clause.based.marginals.cohere} below --- the measure ${}_{\scalebox{0.4}{$\square$}}\hspace{-1pt}\pi$ is strictly coherent, i.e., it satisfies all the conditions of Definition~\ref{d:coherence}. We say that the edge $e=(av)$ is \bemph{marginal-stable} if all the following bounds hold:
	\begin{align}
	\label{e:stable.yellow}
	\Big|{}_\star\hspace{-1pt}\pi_e(\SSPIN{y})-{}_{\scalebox{0.4}{$\square$}}\hspace{-1pt}\pi_e(\SSPIN{y})\Big| 
	&\le \frac{\textup{\textsf{coher}}_e({}_{\scalebox{0.4}{$\square$}}\hspace{-1pt}\pi)}{5k}\,,\\
	\label{e:stable.cyan}
	\Big|{}_\star\hspace{-1pt}\pi_e(\SSPIN{c})-{}_{\scalebox{0.4}{$\square$}}\hspace{-1pt}\pi_e(\SSPIN{c})\Big|
	&\le \frac{\textup{\textsf{coher}}_a({}_{\scalebox{0.4}{$\square$}}\hspace{-1pt}\pi)}{5k}\,,\\
	\label{e:stable.red}
	\Big|{}_\star\hspace{-1pt}\pi_e(\SSPIN{r})-{}_{\scalebox{0.4}{$\square$}}\hspace{-1pt}\pi_e(\SSPIN{r})\Big|
	&\le \frac1{5k}
	\min\bigg\{
	\textup{\textsf{coher}}_a({}_{\scalebox{0.4}{$\square$}}\hspace{-1pt}\pi),
	\min_{e'\in\delta a \setminus e} \textup{\textsf{coher}}_{e'}({}_{\scalebox{0.4}{$\square$}}\hspace{-1pt}\pi)
	\bigg\}\,,\\
	{}_\star\hspace{-1pt}\pi_e(\sigma) 
	&\ge \frac12 {}_{\scalebox{0.4}{$\square$}}\hspace{-1pt}\pi_e(\sigma)
	\quad\textup{for all }
	\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{b},\SSPIN{c}}\,.
	\label{e:stable.positivity}
	\end{align}
(We impose the last condition \eqref{e:stable.positivity} because it forces $\textup{supp}{}_\star\hspace{-1pt}\pi_e=\textup{supp}{}_\star\hspace{-1pt}\pi_e$, which is convenient for the analysis.) We say that $e$ is \bemph{message-stable} if
	\begin{equation}\label{e:message.stability}
	1-{}_\star\hspace{-1pt}\bm{\eta}_{va}(\SPIN{-})\ge \frac1{2^r}\,,\quad
	\max_{\sigma\in\set{\SSPIN{r},\SSPIN{b},\SSPIN{y}\SSPIN{g}}} \bigg|
	\frac{{}_\star\hspace{-1pt}\hat{q}_{av}(\sigma)}{\textup{\footnotesize\textsf{BP}}_{av}[{}_\star\hspace{-1pt}\dot{q}](\sigma)}
	-1\bigg| \le \frac1{k^r}\,.
	\end{equation}
(We take the convention $0/0=1$, so in the above it is permitted to have
 both ${}_\star\hspace{-1pt}\hat{q}_{av}(\sigma)$ and $\textup{\footnotesize\textsf{BP}}_{av}[{}_\star\hspace{-1pt}\dot{q}](\sigma)$ equal to zero.) We say that the edge is \bemph{stable} if it is both marginal- and message-stable. Finally, we say that an acyclic variable $v$ is \bemph{stable} if all its incident edges $e\in\delta v$ are stable.

 \label{d:nice}
An acyclic variable $v$ is \bemph{nice} if it has degrees 
	\begin{equation}\label{e:nice.degree.condition}
	\bigg||\partial v(\SPIN{\textpm})| - \frac{2^k k\ln 2}{2}\bigg|
	\le 2^{2k/3}\,,\end{equation}
and its incoming and outgoing canonical messages satisfy the bounds
	\begin{align}\label{e:nice.var.message.cond}
	\max\Bigg\{
	\bigg|{}_\star\hspace{-1pt}\dot{q}_{va}(\SSPIN{y})-\frac13\bigg|,
	\bigg|2^k {}_\star\hspace{-1pt}\dot{q}_{va}(\SSPIN{g})-\frac13\bigg|
	\Bigg\}
	&\le \frac1{2^{k/10}}\,,\\
	\label{e:nice.clause.message.cond}
	\max\Bigg\{
	\bigg|{}_\star\hspace{-1pt}\hat{q}_{av}(\SSPIN{y})-\frac13\bigg|,
	\bigg|2^{|\partial a|-1}
	{}_\star\hspace{-1pt}\hat{q}_{av}(\SSPIN{r})-\frac13\bigg|
	\Bigg\}
	&\le \frac1{2^{k/10}}\,,
	\end{align}
for all $a\in\partial v$.\footnote{Recall that we automatically have the identities ${}_\star\hspace{-1pt}\hat{q}_{av}(\SSPIN{y})={}_\star\hspace{-1pt}\hat{q}_{av}(\SSPIN{g})={}_\star\hspace{-1pt}\hat{q}_{av}(\SSPIN{b})$ and ${}_\star\hspace{-1pt}\dot{q}_{va}(\SSPIN{r})={}_\star\hspace{-1pt}\dot{q}_{va}(\SSPIN{b})+{}_\star\hspace{-1pt}\dot{q}_{va}(\SSPIN{g})$. Thus the conditions \eqref{e:nice.var.message.cond}
and \eqref{e:nice.clause.message.cond}
constrain ${}_\star\hspace{-1pt}\dot{q}_{va}(\sigma)$
and ${}_\star\hspace{-1pt}\hat{q}_{av}(\sigma)$ for all $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$.} (In condition \eqref{e:nice.clause.message.cond} we write $|\partial a|$, rather than simply $k$, because we will also use this definition in the processed graph where some clauses will have degree $k-1$.) Since the canonical messages are functions of $B_r(v)$, niceness is also a property of $B_r(v)$.

\label{d:j.stable}
We say an acyclic variable $v$ is \bemph{$1$-stable} if is stable, and remains stable after the removal of any one subtree descended from a variable $u \in B_r(v)\setminus v$. The \bemph{$1$-nice} property is analogously defined. We use \bemph{$0$-nice} to mean simply \bemph{nice}. For $\mathfrak{i}\in\set{0,1}$ we let
