\label{d:contained}
Let $\delta_*$ be a small absolute constant, to be determined later.\footnote{Ultimately we will require $\delta_* \le \min\set{\zeta/30, (\ln 2)/(2(\kappa_*)^{1/2})}$ (see Proposition~\ref{p:contraction.COMPOUND})
where $\zeta$ is the absolute constant from Definition~\ref{d:error.notation.edge}. Finally we will take $\zeta=\zeta_*/4$ where $\zeta_*$ is the absolute constant from Proposition~\ref{p:apriori}.} For an acyclic variable $v$, for $\mathfrak{i}\in\set{0,1}$, and for any integer $1\le t\le 2R'$, we define
	\begin{equation}\label{e:def.R.for.containment}
	\mathfrak{R}^\mathfrak{i}(v,t)
	\equiv
	\sum_{u : t \le d(u,v) < 2R'}
	\frac{
	\exp\{ k(\delta_*)^{-1} 
	\mathfrak{B}^\mathfrak{i}(u,v) \} }
	{ \exp\{
		(k\ln2)(1+\delta_*)
		d(u,v) 
		\}}\,.\end{equation}
Note that $\mathfrak{R}^\mathfrak{i}(v,2R')$ is zero, since it is an empty sum. We then define the \bemph{$\mathfrak{i}$-containment radius} of $v$ to be
	\begin{equation}\label{eq-def-rad}
	\textup{rad}^\mathfrak{i}(v)
	\equiv
	\min \bigg\{ t\ge 1:
	\mathfrak{R}^\mathfrak{i}(v,t)
	\le \frac14 \bigg\}
	\le 2R' \,,
	\end{equation}
so that $1 \le \textup{rad}^\mathfrak{i}(v) \le 2R'$. For $\mathfrak{i}\in\set{0,1}$, we say $v$ is \bemph{$\mathfrak{i}$-self-contained} if we have $\textup{rad}^\mathfrak{i}(u)\le d(u,v)$ for all $u$ with $1\le d(u,v)\le R'$. Note that the containment radius of any variable can be determined from its $3R'$-neighborhood. Whether a variable is $\mathfrak{i}$-self-contained can be determined from its $4R'$-neighborhood.

\label{d:good.exc}
A rooted tree $T$ of depth $10R'$ is \bemph{$\mathfrak{i}$-excellent} if, with
$\cong$ denoting isomorphism of rooted graphs,
and with ${\textup{\textbf{PGW}}}\equiv{\textup{\textbf{PGW}}}^\alpha$ as defined above (prior to Definition~\ref{d:simple.types}), we have 
	\begin{equation}\label{e:j.excellent}
	p_{\textup{ex},\mathfrak{i}}(T)\equiv
	{\textup{\textbf{PGW}}}\left( 
	\left.\begin{array}{c}
	B_{20R'}(u)
	\text{ contains 
	any}\\
	\text{variable which is not $\mathfrak{i}$-fair}
	\end{array}
	\, \right| \, B_{10R'}(u) \cong T
	\right) \le \frac1{\exp(k^3 R)}\,.
	\end{equation}
An acylic variable $v$ is termed \bemph{$\mathfrak{i}$-excellent} if its $10R'$-neighborhood $B_{10R'}(v)$ satisfies \eqref{e:j.excellent}. Lastly, we say that $v$ is \bemph{$\mathfrak{i}$-good} if (i) it is $\mathfrak{i}$-fair, and (ii) every length-$40R'$ path emanating from $v$ contains at least one $\mathfrak{i}$-excellent variable. Note that $\mathfrak{i}$-excellent implies $\mathfrak{i}$-good which in turn implies $\mathfrak{i}$-fair.

\begin{equation}\label{e:j.excellent}
	p_{\textup{ex},\mathfrak{i}}(T)\equiv
	{\textup{\textbf{PGW}}}\left( 
	\left.\begin{array}{c}
	B_{20R'}(u)
	\text{ contains 
	any}\\
	\text{variable which is not $\mathfrak{i}$-fair}
	\end{array}
	\, \right| \, B_{10R'}(u) \cong T
	\right) \le \frac1{\exp(k^3 R)}\,.
	\end{equation}

 \label{d:proc}
In a graph $\mathscr{G}=(V,F,E)$, define the \textbf{activated set}
	\begin{equation}\label{e:bspprime.activated.set}
	\textup{\textsf{Act}}(\mathscr{G})
	\equiv \left\{
	\begin{array}{c}
	\text{variables $v\in V$ such that
	$B_{3R/10}(v;\mathscr{G})$ contains}\\
	\text{at least two clauses of degree $k-1$, or}\\
	\text{at least one clause of degree
	$\le k-2$.}
		\end{array}\right\}\,.\end{equation}
Given an initial subset of variables $A\subseteq V$, let $\mathscr{G}_{-1}\equiv\mathscr{G}$, $A_{-1}\equiv A$, and denote
	\[\mathscr{G}_0 \equiv \textup{\textsf{pr}}_0 \mathscr{G} \equiv\mathscr{G}
	\,\bigg\backslash\,
	\Bigg\{ 	\bigcup_{v\in A} B_R(v;\mathscr{G})\Bigg\}
	= \mathscr{G}
	\,\bigg\backslash\, B_R(A;\mathscr{G})
	\,.\]
Then, for $t\ge0$, we use \eqref{e:bspprime.activated.set} to define inductively $A_t \equiv \textup{\textsf{Act}}(\mathscr{G}_t)$ and
	\[\mathscr{G}_{t+1} \equiv \textup{\textsf{pr}}_{t+1}\mathscr{G} \equiv \mathscr{G}_t
	\,\bigg\backslash\,
	\Bigg\{\bigcup_{v\in A_t}B_R(v; \mathscr{G}_t)\Bigg\}
	= \mathscr{G}_t \,\bigg\backslash\, B_R(A_t;\mathscr{G}_t)
	\,.\]
The process terminates at the first time $t$ that $\textup{\textsf{Act}}(\mathscr{G}_t)=\varnothing$, and we denote the terminal graph $\mathscr{G}_t \equiv \mathscr{G}_\infty$. We let $\textup{\textsf{BSP}}'(A;\mathscr{G})$ denote the set of all variables removed by this procedure,
	\[\textup{\textsf{BSP}}'(A;\mathscr{G})
	\equiv
	\bigcup_{t = -1}^\infty
	\Bigg\{ \bigcup_{v\in A_t}B_R(v;\mathscr{G}_t) \Bigg\}
	= \bigcup_{t = -1}^\infty B_R(A_t;\mathscr{G}_t)\,.
	\]
With a minor abuse of notation we will also let $\textup{\textsf{BSP}}'(A;\mathscr{G})$ denote the subgraph of $\mathscr{G}$ induced by these variables.
We hereafter refer to $\textup{\textsf{BSP}}'(A;\mathscr{G})$
as the \bemph{removal process in $\mathscr{G}$ with initial set $A$}.
We then define:
	\[
	\begin{array}{l} 
	\hline \vspace{-10pt} \\
	\textbf{Preprocessing algorithm 
		on $\mathscr{G}=(V,F,E)$:}\\
	\text{Let $A\subseteq V$ be the set of all 
	variables in $\mathscr{G}$ that are}\\
	\text{improper (Definition~\ref{d:simple.types}) or
	 not $1$-good (Definition~\ref{d:good.exc}).} \\
	\text{Delete $\textup{\textsf{BSP}}'(A;\mathscr{G})$
	and output the processed graph
	$\textup{\textsf{pr}}\mathscr{G} \equiv \mathscr{G}_\infty$.}
	\vspace{4pt}
	\\ \hline
	\end{array}
	\]
Throughout this paper, we use the terms ``preprocessing procedure'' or ``preprocessing algorithm'' to refer to this mapping $\mathscr{G}\mapsto\textup{\textsf{pr}}\mathscr{G}$.

\begin{equation}\label{e:bspprime.activated.set}
	\textup{\textsf{Act}}(\mathscr{G})
	\equiv \left\{
	\begin{array}{c}
	\text{variables $v\in V$ such that
	$B_{3R/10}(v;\mathscr{G})$ contains}\\
	\text{at least two clauses of degree $k-1$, or}\\
	\text{at least one clause of degree
	$\le k-2$.}
		\end{array}\right\}\,.\end{equation}

\label{d:degseq}
Let $\mathscr{G}'=(V',F',E')$ be a $\textup{$k$-\textsc{sat}}$ problem instance, and denote its processed version by $\mathscr{G}=(V,F,E)=\textup{\textsf{pr}}\mathscr{G}'$. Write $V=\set{v_1,\ldots,v_n}$ and $F=\set{a_1,\ldots,a_m}$. We then define the \bemph{processed neighborhood sequence of $\mathscr{G}'$} (equivalently, the \bemph{neighborhood sequence of $\mathscr{G}$}) as
	\[
	\mathcal{D}
	\equiv
	\mathcal{D}_{\mathscr{G}}
	\equiv
	\begin{pmatrix}
	(\bm{T}_{v_1},\ldots,\bm{T}_{v_n})\\
	(\bm{L}_{a_1},\ldots,\bm{L}_{a_m})
	\end{pmatrix}\,.
	\]
We then define $\mathscr{D}$ to be the same as $\mathcal{D}$ except that we forget the ordering of $V$ and of $F$. Thus $\mathscr{D}$ contains only the information of the empirical counts
	{\setlength{\jot}{0pt}\begin{align}
	n_{\bm{T}}
	&\equiv
	\textup{number of variables in $\textup{\textsf{pr}} V$ of total type $\bm{T}$;} \nonumber \\
	m_{\bm{L}}
	&\equiv
	\textup{number of clauses in $\textup{\textsf{pr}} F$ of total type $\bm{L}$;} \nonumber \\
	n_{\bm{t}}
	&\equiv
	\textup{number of edges in $\textup{\textsf{pr}} E$ of total type $\bm{t}$.}
	\label{e:empirical.counts.of.total.types}
	\end{align}}
The empirical count of edge types can be determined as a marginal of either the clause or variable counts:
	\begin{equation}\label{e:edge.marginal.of.types}
	\sum_{\bm{T}}
	n_{\bm{T}} \Ind{\bm{t} \in \bm{T}}
	= n_{\bm{t}}
	= \sum_{\bm{L}}
	m_{\bm{L}}
	\sum_j
	\Ind{\bm{L}(j)=\bm{t}}\,.
	\end{equation}
(Recall from Remark~\ref{r:acyclic.proper.multiset} that the simple type of any variable which survives preprocessing is a multi-set with no repeated elements --- thus, in \eqref{e:edge.marginal.of.types}, $\Ind{\bm{t}\in\bm{T}}$ is the same as the number of occurrences of $\bm{t}$ in $\bm{T}$.) We will sometimes abuse notation and use $\mathscr{D}$ to denote the normalized empirical measures
	\[
	\dot{\mathscr{D}}(\bm{T})
	= \frac{n_{\bm{T}}}{|V|},\quad
	\hat{\mathscr{D}}(\bm{L})
	= \frac{m_{\bm{L}}}{|F|},\quad
	\bar{\mathscr{D}}(\bm{t})
	= \frac{n_{\bm{t}}}{|E|}\,.
	\]
However, we emphasize that $\mathscr{D}$ encodes $|V|=n$ and $|F|=m$ in addition to the normalized empirical measures. We call $\mathscr{D}\equiv\mathscr{D}_{\mathscr{G}}$ the \bemph{processed neighborhood profile of $\mathscr{G}'$}
(equivalently, the 
\bemph{neighborhood profile of $\mathscr{G}$}).

\begin{align}
	n_{\bm{T}}
	&\equiv
	\textup{number of variables in $\textup{\textsf{pr}} V$ of total type $\bm{T}$;} \nonumber \\
	m_{\bm{L}}
	&\equiv
	\textup{number of clauses in $\textup{\textsf{pr}} F$ of total type $\bm{L}$;} \nonumber \\
	n_{\bm{t}}
	&\equiv
	\textup{number of edges in $\textup{\textsf{pr}} E$ of total type $\bm{t}$.}
	\label{e:empirical.counts.of.total.types}
	\end{align}

\label{r:processed.graph.types.CM} 
The processed graph $\mathscr{G}=\textup{\textsf{pr}}\mathscr{G}'$ is a subgraph of the original graph $\mathscr{G}'$, and therefore carries less information in general. For the rest of this paper, whenever we refer to the processed graph $\mathscr{G}$, we assume that each vertex and each edge of $\mathscr{G}$ \textbf{carries the information of its total type}. In particular, each variable in $\mathscr{G}$ does carry the information concerning its simple type (Definition~\ref{d:simple.types}), even if part of its original $R$-neighborhood is deleted during processing. However, $\mathscr{G}$ does \textbf{not} carry the information of the entire original graph $\mathscr{G}'$, so we still do allow for the possibility that $\textup{\textsf{pr}}\mathscr{G}'=\textup{\textsf{pr}}\mathscr{G}''$ for $\mathscr{G}'\ne\mathscr{G}''$. We let $\textup{\textbf{\textsf{CM}}}(\mathcal{D})$ denote the set of all graphs $\mathscr{G}$ consistent with a given neighborhood sequence $\mathcal{D}$ (where $\mathscr{G}$ is interpreted as we have just described). In particular,
	\begin{equation}\label{e:size.CM.D}
	|\textup{\textbf{\textsf{CM}}}(\mathcal{D})|
	= \prod_{\bm{t}} (n_{\bm{t}})!
	\,.
	\end{equation}
The notation $\textup{\textbf{\textsf{CM}}}$ stands for \textbf{configuration model}. A uniformly random element of $\textup{\textbf{\textsf{CM}}}(\mathcal{D})$ can be sampled by a generalization of the standard configuration model for graphs with given degree sequence --- this type of construction goes back to \cite{MR595929}, and we refer to \cite{MR1725006} for a survey. Generalized configuration models were analyzed in detail in \cite{MR3405616}, and the sampling procedure can be described as follows. Start with a collection of isolated vertices --- $n$ variables $V$ together with $m$ clauses $F$ --- labelled with total types according to $\mathcal{D}$. Each vertex is then equipped with the appropriate number of ``half-edges,'' all labelled with edge total types. The total number of half-edges incident to each vertex corresponds to its degree in the processed graph $\mathscr{G}$. Let $\delta V$ denote the variable-incident half-edges, and $\delta F$ the clause-incident half-edges. Then take a \textbf{uniformly random matching} between $\delta V$ and $\delta F$ that \bemph{respects edge total types}. (A full edge consists of one
variable-incident half-edge matched together with one clause-incident half-edge.) This procedure generates a uniformly random element of $\textup{\textbf{\textsf{CM}}}(\mathcal{D})$. This discussion is most relevant to the statement of Proposition~\ref{p:unif} below.

\label{p:unif}
Let $\mathscr{G}\sim\mathbb{P}\equiv\mathbb{P}_{n,m}$ for any $m$. Let $\textup{\textsf{pr}}\mathscr{G}$ be the processed graph given by Definition~\ref{d:proc}, with neighborhood sequence $\mathcal{D}_{\textup{\textsf{pr}}\mathscr{G}}$. For any $\mathcal{D}$ such that
$\mathcal{D}_{\textup{\textsf{pr}}\mathscr{G}}=\mathcal{D}$ with positive probability under $\mathbb{P}$, we have
	\[\mathbb{P}\Big(\textup{\textsf{pr}}\mathscr{G}=H \,\Big|\,
		\mathcal{D}_{\textup{\textsf{pr}}\mathscr{G}}=\mathcal{D}\Big)
	= \frac{\Ind{H\in\textup{\textbf{\textsf{CM}}}(\mathcal{D})}}
		{\textup{\textbf{\textsf{CM}}}(\mathcal{D})}
	\]
for all $H\in\textup{\textbf{\textsf{CM}}}(\mathcal{D})$. Moreover, conditional on the neighborhood profile
$\mathscr{D}_{\textup{\textsf{pr}}\mathscr{G}}=\mathscr{D}$, the law of the sequence $\mathcal{D}_{\textup{\textsf{pr}}\mathscr{G}}$ is uniformly random among all sequences $\mathcal{D}$ with empirical counts $\mathscr{D}$.

\label{d:empirical.measures.of.colors}
 Take any $\textup{$k$-\textsc{sat}}$ instance $\mathscr{G}'$,
and let $\mathscr{G}\equiv\textup{\textsf{pr}}\mathscr{G}'$ be its processed version (Definition~\ref{d:proc}),
with total types as in Definition~\ref{d:total.type}.
Given a valid 
$\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$-coloring $\smash{\vec{\sigma}}$ of 
$\mathscr{G}$ (Definition~\ref{d:color.model}), let $\pi$ be the \bemph{empirical measure of colors conditioned on edge type}:
for each $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$
and each edge total type $\bm{t}$,
	\begin{equation}\label{e:edge.msr.given.edge.type}
	\pi_{\bm{t}}(\sigma)
	\equiv
	\frac{|\set{e\in E:\bm{t}_e=\bm{t}\text{ and }
	\sigma_e=\sigma}|}
	{|\set{e\in E:\bm{t}_e=\bm{t}}|}
	= \frac{|\set{e\in E:\bm{t}_e=\bm{t}\text{ and }
	\sigma_e=\sigma}|}
	{n_{\bm{t}}}\,,
	\end{equation}
with $n_{\bm{t}}$ as in \eqref{e:empirical.counts.of.total.types}.
Further, let $\omega$ be the 
\bemph{empirical measure of colors conditioned on incident clause type}: for each $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$, each clause total type $\bm{L}$, and each index $1\le j\le k(\bm{L})$ (where $k(\bm{L})\in\set{k-1,k}$ is the degree in $\mathscr{G}=\textup{\textsf{pr}}\mathscr{G}'$ of a clause of type $\bm{L}$), let
	\begin{equation}\label{e:edge.msr.given.clause.type}
	\omega_{\bm{L},j}(\sigma)
	\equiv \frac{|\set{(av)\in E:
		\bm{L}_a=\bm{L},j(v;a)=j,
		\sigma_{av}=\sigma}|}{ m_{\bm{L}}}
		\,,\end{equation}
with $m_{\bm{L}}$ as in \eqref{e:empirical.counts.of.total.types}. Note that $\pi$ can be obtained as a marginal of $\omega$:
	\begin{equation}\label{e:pi.as.mgl.of.omega}
	n_{\bm{t}}
	\pi_{\bm{t}}(\sigma)
	= \sum_{j\in[k]}
	\sum_{\bm{L}} 
	m_{\bm{L}}
	\Ind{\bm{L}(j)=\bm{t}}\omega_{\bm{L},j}(\sigma)
	\end{equation}
for all $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$, since both sides count the total number of edges of type $\bm{t}$ with color $\sigma$ in $\mathscr{G}=\textup{\textsf{pr}}\mathscr{G}'$.

 \label{d:judicious}
Let $\mathscr{G}'$ be a $\textup{$k$-\textsc{sat}}$ instance, $\mathscr{G}\equiv\textup{\textsf{pr}}\mathscr{G}'$ the processed graph, and $\smash{\vec{\sigma}}$ any valid coloring of $\mathscr{G}$ (Definition~\ref{d:color.model}).
We say that $\smash{\vec{\sigma}}$ is \bemph{judicious}
if holds for all $\bm{L}$ and all $j$ that
	\[
	\omega_{\bm{L},j} = {}_\star\hspace{-1pt}\pi_{\bm{L}(j)} 
	\]
--- i.e., the empirical distribution of the edge color conditional on $(\bm{L},j)$ (the clause type and edge index) \bemph{depends only on $\bm{L}(j)$} (the edge type itself, which carries less information), and moreover agrees (up to rounding) with the canonical edge marginal ${}_\star\hspace{-1pt}\pi$ of Definition~\ref{e:defn.canonical.edge.marginal}. For this definition, ${}_\star\hspace{-1pt}\pi_{av}$ should be based on the $r$-neighborhood of $v$ with respect to the processed graph $\mathscr{G}$.

\begin{align}\nonumber
	\bm{Z}
	\equiv \bm{Z}(\mathscr{G})
	& \equiv \textup{number of 
		judicious colorings $\smash{\vec{\sigma}}$
		of $\mathscr{G}$;}\\ \nonumber
	\bm{Z}_\textup{sep}
	\equiv \bm{Z}_\textup{sep}(\mathscr{G})
	&\equiv \textup{number of 
		judicious separable
		colorings $\smash{\vec{\sigma}}$ of $\mathscr{G}$;}\\
	\bm{Z}_\textup{ext}
	\equiv \bm{Z}_\textup{ext}(\mathscr{G})
	&\equiv \textup{number of 
		judicious extendible
		colorings $\smash{\vec{\sigma}}$ of $\mathscr{G}$.}
\label{e:def.ZZ}
\end{align}

\label{p:first.moment.exponent}
Let $\Phi$ be the $\textup{1-\textsc{rsb}}$ free energy
from Proposition~\ref{p:phi}.
There exists $\epsilon_R$ which tends to zero as $R\to\infty$, such that
	\[\mathbb{E}_{\mathscr{D}} \bm{Z} \ge
	\exp\bigg\{
	n\Big[\Phi(\alpha)-\epsilon_R\Big]\bigg\}
	\]
holds with high probability over the random $R$-neighborhood profile $\mathscr{D}$.

Propositions~\ref{p:fp}~and~\ref{p:phi} together show that for random $\textup{$k$-\textsc{sat}}$ with $k\ge k_0$, the $\textup{1-\textsc{rsb}}$ free energy $\Phi(\alpha)$ is well-defined, with a unique root $\alpha_\star$ in the interval \eqref{e:alpha.regime}. It follows from Proposition~\ref{p:ubd} that $\alpha_\star$ upper bounds the satisfiability regime, so it remains to show the lower bound. To this end, let $\alpha<\alpha_\star$
(still within the regime \eqref{e:alpha.regime}),
so that $\Phi(\alpha)>0$. We divide the rest of the argument into two parts:\smallskip

\noindent\bemph{Step 1. Lower bound on separable colorings.}
Analogously to \eqref{e:second.mmt.decompose.by.z}, 
decompose 
	\[(\bm{Z}_\textup{sep})^2=\sum_z (\bm{Z}_\textup{sep})^2[z]\,.\]
Let $(\bm{Z}_\textup{sep})^2[I]$
denote the sum of $(\bm{Z}_\textup{sep})^2[z]$ over $z\in I\subseteq[0,1]$.
By the separability condition (Definition~\ref{d:separable}),
	\[(\bm{Z}_\textup{sep})^2\Big[[0,1]\setminus
	 I_0\Big]
	 \le e^{o(n)} \bm{Z}_\textup{sep}
	 \le e^{o(n)} \bm{Z}\]
almost surely. Recall the definition of $\mathscr{L}_\textup{girth}$ from \eqref{e:law.DD.girth}.
Proposition~\ref{p:second.moment.judicious}
gives the bound
	\[\mathscr{L}_\textup{girth}\Bigg(
	\mathbb{E}_{\mathscr{D}}\Big[(\bm{Z}_\textup{sep})^2[I_0]\Big]
	\le\mathbb{E}_{\mathscr{D}}\Big[\bm{Z}^2[I_0]\Big]
	\le C\Big(\mathbb{E}_{\mathscr{D}}\bm{Z}\Big)^2
	\Bigg) = 1-o_n(1)\]
for $C=C(k,R)$. Combining the above bounds gives
	\begin{equation}\label{e:t:second.moment}
	\mathscr{L}_\textup{girth}\Bigg( \mathbb{E}_{\mathscr{D}}\Big((\bm{Z}_\textup{sep})^2\Big)
	\le C \Big(\mathbb{E}_{\mathscr{D}}\bm{Z}\Big)^2
	+ e^{o(n)}\,\mathbb{E}_{\mathscr{D}}\bm{Z}
	\Bigg) = 1-o_n(1)\,.
	\end{equation}
On the other hand, it follows by Propositions~\ref{p:first.moment.exponent}~and~\ref{p:sep} that
	\begin{equation}\label{e:sep.compared.with.ZZ.first.mmt}
	\mathscr{L}
	\Bigg( \mathbb{E}_{\mathscr{D}}\bm{Z}_\textup{sep} \ge \frac{\mathbb{E}_{\mathscr{D}}\bm{Z}}{2}
		\ge 
		\frac12 \exp\bigg\{
	n\Big[\Phi(\alpha)-\epsilon_R\Big]\bigg\}
	\Bigg) = 1-o_n(1)\,.
	\end{equation}
Since we chose $\alpha<\alpha_\star$, we know that $\Phi(\alpha)$ is positive, and it follows for large enough $R$ (depending on $k,\alpha$) that $\mathbb{E}_{\mathscr{D}}\bm{Z}$ is exponentially large in $n$. It follows that
\eqref{e:t:second.moment} 
and \eqref{e:sep.compared.with.ZZ.first.mmt}
combine to yield
	\[
	\mathscr{L}_\textup{girth}\Bigg( \mathbb{E}_{\mathscr{D}}\Big((\bm{Z}_\textup{sep})^2\Big)
	\le 5C \Big(\mathbb{E}_{\mathscr{D}}(\bm{Z}_\textup{sep})\Big)^2
	\Bigg) = 1-o_n(1)\,.
	\]
Applying \eqref{e:second.mmt.method.with.const},
we see that there exists a positive constant $\delta=\delta(k,R)$ such that 
	\begin{equation}\label{e:sep.second.mmt.final.lbd}
	\mathscr{L}_\textup{girth}\Bigg(
	\mathbb{P}_{\mathscr{D}}\bigg[
	\bm{Z}_\textup{sep} \ge \delta \, \mathbb{E}_{\mathscr{D}}(\bm{Z}_\textup{sep})\bigg]
	\ge \delta
	\Bigg) = 1-o_n(1)\,.
	\end{equation}

\noindent\bemph{Step 2. Lower bound on extendible colorings.} It follows from Proposition~\ref{p:ext} 
and Markov's inequality that,
with $\delta=\delta(k,R)$ as above, we have
	\[
	\mathbb{P}_{\mathscr{D}} \bigg(
	\bm{Z}-\bm{Z}_\textup{ext} \ge \delta^2 \, \mathbb{E}_{\mathscr{D}}\bm{Z}
	\bigg)
	\le \frac{\mathbb{E}_{\mathscr{D}}(\bm{Z}-\bm{Z}_\textup{ext})}{\delta^2\,\mathbb{E}_{\mathscr{D}}\bm{Z}}
	= o_n(1)
	\]
with high probability over the random neighborhood profile $\mathscr{D}$. Combining with \eqref{e:sep.compared.with.ZZ.first.mmt}
and \eqref{e:sep.second.mmt.final.lbd} gives
	\[\mathscr{L}_\textup{girth}\Bigg(
	\mathbb{P}_{\mathscr{D}}\bigg[
	\bm{Z}_\textup{ext}
	\ge \bm{Z} - \delta^2 \, \mathbb{E}_{\mathscr{D}}\bm{Z}
	\ge \bm{Z}_\textup{sep} - \delta^2 \, \mathbb{E}_{\mathscr{D}}\bm{Z}
	\ge \frac{\delta(1-2\delta)}{2}
	\exp\bigg\{
	n\Big[\Phi(\alpha)-\epsilon_R\Big]\bigg\}
	>0
	\bigg] \ge \frac{\delta}{2}\Bigg) = 1-o_n(1)\,.\]
Recall the definition of $\mathscr{L}_\textup{girth}$ from \eqref{e:law.DD.girth}: since the graph $\mathscr{G}'\sim\mathbb{P}$ has $\textup{girth}(\mathscr{G}')>8R$ with asymptotically positive probability, we deduce from the above that
	\begin{equation}\label{e:ext.ZZ.cond.lbd}
	\mathscr{L}\Bigg(
	\mathbb{P}_{\mathscr{D}}\Big[\bm{Z}_\textup{ext}>0\Big]
	\ge \frac{\delta}{2}\Bigg)
	\ge \delta'= \delta'(k,R)\,.
	\end{equation}
As long as no connected component of $\mathscr{G}'\setminus\textup{\textsf{pr}}\mathscr{G}'$ contains a bicycle,
any satisfying assignment of 
$\mathscr{G}=\textup{\textsf{pr}}\mathscr{G}'$ extends to a satisfying assignment of $\mathscr{G}'$. It follows by combinding with
Definition~\ref{d:extendible} that
	\[
	\mathbf{1}\bigg\{
	\begin{array}{c}
	\textup{no connected component of}\\
	\textup{$\mathscr{G}'\setminus\textup{\textsf{pr}}\mathscr{G}'$ contains a bicycle}
	\end{array}
	\bigg\}
	\Ind{\bm{Z}_\textup{ext}>0}
	\le\Ind{\textup{$\mathscr{G}'$ is satisfiable}}\,.
	\]
From Proposition~\ref{p:small.fraction.removed.in.processing} that, with high probability, no connected component of
$\mathscr{G}'\setminus\textup{\textsf{pr}}\mathscr{G}'$ contains a bicycle.
Combining with \eqref{e:ext.ZZ.cond.lbd}
gives
	\[
	\mathbb{P}^{n,\alpha}\Big(\mathscr{G}'
		\textup{ is satisfiable}\Big)
	\ge
	\mathbb{E}\Bigg(
	\mathbf{1}\bigg\{
	\begin{array}{c}
	\textup{no connected component of}\\
	\textup{$\mathscr{G}'\setminus\textup{\textsf{pr}}\mathscr{G}'$ contains a bicycle}
	\end{array}
	\bigg\}
	\cdot
	\mathbb{P}_{\mathscr{D}}\Big[\bm{Z}_\textup{ext}>0\Big]\Bigg)
	\ge \delta''
	\]
for any $\alpha<\alpha_\star$ (where $\delta''$ depends on $k$ and $R$; and $R$ depends on $k$ and $\alpha$).
Combining with Friedgut's theorem \cite{Friedgut:99} gives $\alpha_\textup{sat}\ge \alpha$. 
The result follows by taking
$\alpha\uparrow\alpha_\star$
and $R\uparrow\infty$.

\[
	\mathbf{1}\bigg\{
	\begin{array}{c}
	\textup{no connected component of}\\
	\textup{$\mathscr{G}'\setminus\textup{\textsf{pr}}\mathscr{G}'$ contains a bicycle}
	\end{array}
	\bigg\}
	\Ind{\bm{Z}_\textup{ext}>0}
	\le\Ind{\textup{$\mathscr{G}'$ is satisfiable}}\,.
	\]

\[
	\mathbb{P}^{n,\alpha}\Big(\mathscr{G}'
		\textup{ is satisfiable}\Big)
	\ge
	\mathbb{E}\Bigg(
	\mathbf{1}\bigg\{
	\begin{array}{c}
	\textup{no connected component of}\\
	\textup{$\mathscr{G}'\setminus\textup{\textsf{pr}}\mathscr{G}'$ contains a bicycle}
	\end{array}
	\bigg\}
	\cdot
	\mathbb{P}_{\mathscr{D}}\Big[\bm{Z}_\textup{ext}>0\Big]\Bigg)
	\ge \delta''
	\]

\label{r:where.proc.results.used} 
Note that Propositions \ref{p:small.fraction.removed.in.processing}--\ref{p:unif} (stated in \S\ref{ss:introprep}, proved in Section~\ref{s:processing}) are not directly referenced in the above proof of Theorem~\ref{t:main}. Instead, they are used indirectly via the other propositions. In particular, for the first moment (Proposition~\ref{p:first.moment.exponent}), the uniformity result (Proposition~\ref{p:unif}) provides a simple combinatorial formula for $\mathbb{E}_{\mathscr{D}}\bm{Z}$. We then need the result that only $o_R(1)$ fraction of the variables are removed (Proposition~\ref{p:small.fraction.removed.in.processing}) to relate the combinatorial formula to the $\textup{1-\textsc{rsb}}$ free energy \eqref{e:phi.alpha}. The second moment (Proposition~\ref{p:second.moment.judicious}) similarly relies on Proposition~\ref{p:unif} for the combinatorial formula, but additionally requires the result that each type occurs linearly many times
(Proposition~\ref{p:posfrac}) to estimate the combinatorial formula up to a \emph{constant} multiplicative error.

\label{d:pi.omega.nu.notation}
As before, let $\mathscr{G}'$ be a $\textup{$k$-\textsc{sat}}$ instance, 
and denote its processed version
$\mathscr{G}\equiv\textup{\textsf{pr}}\mathscr{G}'$. 
Given a valid coloring $\smash{\vec{\sigma}}$ of $\mathscr{G}$, we define $\dot{\nu}$ to be the \bemph{empirical measure of variable colorings conditional on type},
	\begin{equation}\label{e:variable.color.cond.on.type}
	\dot{\nu}_{\bm{T}}(\smash{\vec{\sigma}}_{\delta v})
	\equiv
		\frac1{n_{\bm{T}}}
		\Bigg|\bigg\{w\in V: \textup{$\bm{T}_w=\bm{T}$
			and $\smash{\vec{\sigma}}_{\delta w}
				=\smash{\vec{\sigma}}_{\delta v}$}
				\bigg\}\Bigg|\,,
	\end{equation}
with $n_{\bm{T}}$ as in \eqref{e:empirical.counts.of.total.types}.
We define $\hat{\nu}$ \bemph{empirical measure of clause colorings conditional on type},
	\begin{equation}\label{e:clause.color.cond.on.type}
	\hat{\nu}_{\bm{L}}(\smash{\vec{\sigma}}_{\delta a})
	\equiv 
	\frac1{m_{\bm{L}}}
	\Bigg|
	\bigg\{b\in F:
		\textup{$\bm{L}_b=\bm{L}$
		and $\smash{\vec{\sigma}}_{\delta b}=\smash{\vec{\sigma}}_{\delta a}$}
		\bigg\}
	\Bigg|\,,\end{equation}
with $m_{\bm{L}}$ as in \eqref{e:empirical.counts.of.total.types}.
As a shorthand, we call $\nu\equiv(\dot{\nu},\hat{\nu})$ the \bemph{empirical measure (of vertex colorings)} associated to $\smash{\vec{\sigma}}$. Recall from \eqref{e:pi.as.mgl.of.omega} that $\pi$ can be obtained as a marginal of $\omega$. Now note that $\pi$ can also be obtained as a marginal of $\dot{\nu}$. Similarly, $\omega$ can be obtained as a marginal of $\hat{\nu}$. We say that $\nu$ is \bemph{judicious} if its marginal $\omega$ is judicious in the sense of Definition~\ref{d:judicious}. For $\bm{Z}$ as in \eqref{e:def.ZZ} and any judicious empirical measure $\nu\equiv(\dot{\nu},\hat{\nu})$, we let $\bm{Z}[\nu]$ denote the contribution to $\bm{Z}$
from colorings with empirical measure $\nu$.

For $\nu=(\dot{\nu},\hat{\nu})$ as in Definition~\ref{d:pi.omega.nu.notation}, define
	\begin{equation}\label{e:rate.function.given.gen.degseq}
	\bm{\Phi}_{\mathscr{D}}(\nu)
	=\frac1n \Bigg\{
	|V| \, \mathbb{E}_{\dot{\mathscr{D}}}[ \mathcal{H}(\dot{\nu}_{\bm{T}}) ]
	+|F| \, \mathbb{E}_{\hat{\mathscr{D}}}[ \mathcal{H}(\hat{\nu}_{\bm{L}}) ]
	-|E| \, \mathbb{E}_{\bar{\mathscr{D}}}
		[ \mathcal{H}(\pi_{\bm{t}}) ]
		\Bigg\}
	\end{equation}
(where $\mathcal{H}$ denotes the usual entropy function, $\mathcal{H}(p)=-\sum_x p_x \ln p_x$).

\label{l:combinatorial.mmt.simplification}
Let $\mathscr{G}'\sim\mathbb{P}_{n,m}$ be the random $\textup{$k$-\textsc{sat}}$ instance,
and let $\mathscr{G}=\textup{\textsf{pr}}\mathscr{G}'$ be its processed version,
with neighborhood profile $\mathscr{D}$ as in Definition~\ref{d:degseq}.
Let $\mathbb{P}_{\mathscr{D}}$ be the uniform measure over $\textup{\textbf{\textsf{CM}}}(\mathscr{D})$ (Remark~\ref{r:processed.graph.types.CM}), and $\mathbb{E}_{\mathscr{D}}$ the expectation with respect to $\mathbb{P}_{\mathscr{D}}$. For any $\mathscr{D}$ and any judicious $\nu$, we have,
with $\bm{\Phi}_{\mathscr{D}}(\nu)$ as in \eqref{e:rate.function.given.gen.degseq},
	\begin{equation}\label{e:stirling.with.poly.error}
	\mathbb{E}_{\mathscr{D}}\bm{Z}[\nu]
	= \frac1{n^{O(1)} }
	\exp\bigg\{ n\bm{\Phi}_{\mathscr{D}}(\nu)
		\bigg\}\,.
	\end{equation}
If $\mathscr{D}$ is bounded away from zero 
and $\nu$ lies in the interior of its simplex, then
	\begin{equation}\label{e:stirling.with.poly.error}
	\mathbb{E}_{\mathscr{D}} \bm{Z}[\nu]
	\asymp_R
	\frac1{ n^{\bm{s}/2}}
	\exp\bigg\{ n\bm{\Phi}_{\mathscr{D}}(\nu)\bigg\}
	\end{equation}
for $\bm{s}\equiv\bm{s}(\mathscr{D})$ as in \eqref{e:stirling.correction.number}.

\begin{proof}
It follows from the description of the configuration model (Remark~\ref{r:processed.graph.types.CM}) that
	\begin{equation}\label{e:config.model.first.moment.given.omega}
	\mathbb{E}_{\mathscr{D}}\bm{Z}[\nu]
	=\underbrace{
	\Bigg\{
	\prod_{\bm{T}} 
	\binom{n_{\bm{T}}}{n_{\bm{T}}\dot{\nu}_{\bm{T}}}
	\prod_{\bm{L}}
	\binom{m_{\bm{L}}}{m_{\bm{L}}\hat{\nu}_{\bm{L}}}
	\Bigg\}
	}_{\substack{
	\text{number of colorings}\\
	\text{prior to matching}
	}}
	\underbrace{\Bigg\{
	\prod_{\bm{t}} \binom{n_{\bm{t}}}
		{ n_{\bm{t}} \pi_{\bm{t}} }
		\Bigg\}^{-1}
		}_{\substack{\text{probability of matching}\\
			\text{to respect colorings}}}\,.
	\end{equation}
The first estimate \eqref{e:stirling.with.poly.error}
then follows by Stirling's formula, ignoring polynomial corrections.
The second estimate \eqref{e:stirling.with.poly.error} follows by taking the polynomial corrections into account.
\end{proof}

