\label{c:first.moment.exponent}
Let $\mathscr{G}'\sim\mathbb{P}_{n,m}$ be the random $\textup{$k$-\textsc{sat}}$ instance, and let $\mathscr{G}=\textup{\textsf{pr}}\mathscr{G}'$ be its processed version, with neighborhood profile $\mathscr{D}$ as in Definition~\ref{d:degseq}. If $\mathscr{D}$ is bounded away from zero in the sense of \eqref{e:pos.frac}, then
	\begin{equation}\label{e:first.mmt.poly}
	\mathbb{E}_{\mathscr{D}}\bm{Z} 
	\asymp_R
	\frac{\exp\{
		n\bm{\Psi}_{\mathscr{D}}({}_\star\hspace{-1pt}\omega) \}
	}{ n^{\wp/2} }
	\end{equation}
for $\bm{\Psi}_{\mathscr{D}}$ as in \eqref{e:nu.opt}, $\wp=\wp(\mathscr{D})$ as in \eqref{e:wp.of.R}, and ${}_\star\hspace{-1pt}\omega$ defined by $({}_\star\hspace{-1pt}\omega)_{\bm{L},j}={}_\star\hspace{-1pt}\pi_{\bm{L}(j)}$.

\begin{proof}
Again recall from \eqref{e:def.ZZ} that $\bm{Z}$ counts judicious colorings (Definition~\ref{d:judicious}) $\smash{\vec{\sigma}}$ of $\mathscr{G}$. For any such $\smash{\vec{\sigma}}$, the empirical measure $\omega$ (Definition~\ref{d:empirical.measures.of.colors}) is completely fixed by the judicious condition: it must agree (up to rounding) with the measure ${}_\star\hspace{-1pt}\omega$ defined by $({}_\star\hspace{-1pt}\omega)_{\bm{L},j} = {}_\star\hspace{-1pt}\pi_{\bm{L}(j)}$.\footnote{Recall from Definition~\ref{d:total.type} that $\bm{L}(j)$ encodes the neighborhoods in both the initial graph $\mathscr{G}'$ and the final graph $\mathscr{G}=\textup{\textsf{pr}}\mathscr{G}'$. However, ${}_\star\hspace{-1pt}\pi_{\bm{L}(j)}$ should be given by Definition~\ref{d:canonical} applied to the $r$-neighborhood of the variable \bemph{in the final graph} $\mathscr{G}$.} Let us abbreviate $\nu\sim{}_\star\hspace{-1pt}\omega$ if $\nu$ is consistent with ${}_\star\hspace{-1pt}\omega$. We will show in Lemma~\ref{l:dimension.count}
(this lemma is deferred to \S\ref{ss:coherence.weights}) that
	\begin{equation}\label{e:dim.nu.given.omega}
	d_1(\mathscr{D})
	\equiv \dim\bigg\{\nu : \nu\sim{}_\star\hspace{-1pt}\omega\bigg\}
	= \bm{s}(\mathscr{D})-\wp(\mathscr{D})\,,
	\end{equation}
for $\bm{s}(\mathscr{D})$ as in \eqref{e:stirling.correction.number} and $\wp(\mathscr{D})$ as in \eqref{e:wp.of.R}. It follows from Lemma~\ref{l:combinatorial.mmt.simplification} that
	\begin{equation}\label{e:prep.for.gaussian.sum}\mathbb{E}_{\mathscr{D}}\bm{Z}
	= \sum_{\nu: \nu\sim{}_\star\hspace{-1pt}\omega}
	\mathbb{E}_{\mathscr{D}}\bm{Z}[\nu]
	\asymp_R
	\sum_{\nu: \nu\sim{}_\star\hspace{-1pt}\omega}
	\frac{\exp\{ n\bm{\Phi}_{\mathscr{D}}(\nu) \}}
		{ n^{\bm{s}/2} }
	\end{equation}
Now recall the general fact that for any fixed dimension $d$, in the limit $n\to\infty$ we have
	\begin{equation}\label{e:gaussian.sum}
	\sum_{x \in (\mathbb{Z}/n)^d}
		\frac1{\exp(n\|x\|^2)}
	= \sum_{x \in (\mathbb{Z}/n^{1/2})^d}
		\frac1{\exp( \|x\|^2)}
	\asymp_d n^{d/2}\,.\end{equation}
Since we already noted above that $\bm{\Phi}_{\mathscr{D}}(\nu)$ is strictly concave in $\nu$ for fixed $\omega$, the claimed result follows by
applying \eqref{e:gaussian.sum}
to \eqref{e:prep.for.gaussian.sum},
with dimension $d$ given by $\bm{s}(\mathscr{D})-\wp(\mathscr{D})$ as in \eqref{e:dim.nu.given.omega}.
\end{proof}

Again recall from \eqref{e:def.ZZ} that $\bm{Z}$ counts judicious colorings (Definition~\ref{d:judicious}) $\smash{\vec{\sigma}}$ of $\mathscr{G}$. For any such $\smash{\vec{\sigma}}$, the empirical measure $\omega$ (Definition~\ref{d:empirical.measures.of.colors}) is completely fixed by the judicious condition: it must agree (up to rounding) with the measure ${}_\star\hspace{-1pt}\omega$ defined by $({}_\star\hspace{-1pt}\omega)_{\bm{L},j} = {}_\star\hspace{-1pt}\pi_{\bm{L}(j)}$.\footnote{Recall from Definition~\ref{d:total.type} that $\bm{L}(j)$ encodes the neighborhoods in both the initial graph $\mathscr{G}'$ and the final graph $\mathscr{G}=\textup{\textsf{pr}}\mathscr{G}'$. However, ${}_\star\hspace{-1pt}\pi_{\bm{L}(j)}$ should be given by Definition~\ref{d:canonical} applied to the $r$-neighborhood of the variable \bemph{in the final graph} $\mathscr{G}$.} Let us abbreviate $\nu\sim{}_\star\hspace{-1pt}\omega$ if $\nu$ is consistent with ${}_\star\hspace{-1pt}\omega$. We will show in Lemma~\ref{l:dimension.count}
(this lemma is deferred to \S\ref{ss:coherence.weights}) that
	\begin{equation}\label{e:dim.nu.given.omega}
	d_1(\mathscr{D})
	\equiv \dim\bigg\{\nu : \nu\sim{}_\star\hspace{-1pt}\omega\bigg\}
	= \bm{s}(\mathscr{D})-\wp(\mathscr{D})\,,
	\end{equation}
for $\bm{s}(\mathscr{D})$ as in \eqref{e:stirling.correction.number} and $\wp(\mathscr{D})$ as in \eqref{e:wp.of.R}. It follows from Lemma~\ref{l:combinatorial.mmt.simplification} that
	\begin{equation}\label{e:prep.for.gaussian.sum}\mathbb{E}_{\mathscr{D}}\bm{Z}
	= \sum_{\nu: \nu\sim{}_\star\hspace{-1pt}\omega}
	\mathbb{E}_{\mathscr{D}}\bm{Z}[\nu]
	\asymp_R
