	\frac{\exp\{ n\bm{\Phi}_{\mathscr{D}}(\nu) \}}
		{ n^{\bm{s}/2} }
	\end{equation}
Now recall the general fact that for any fixed dimension $d$, in the limit $n\to\infty$ we have
	\begin{equation}\label{e:gaussian.sum}
	\sum_{x \in (\mathbb{Z}/n)^d}
		\frac1{\exp(n\|x\|^2)}
	= \sum_{x \in (\mathbb{Z}/n^{1/2})^d}
		\frac1{\exp( \|x\|^2)}
	\asymp_d n^{d/2}\,.\end{equation}
Since we already noted above that $\bm{\Phi}_{\mathscr{D}}(\nu)$ is strictly concave in $\nu$ for fixed $\omega$, the claimed result follows by
applying \eqref{e:gaussian.sum}
to \eqref{e:prep.for.gaussian.sum},
with dimension $d$ given by $\bm{s}(\mathscr{D})-\wp(\mathscr{D})$ as in \eqref{e:dim.nu.given.omega}.

\label{l:nu.star.as.optimizer.for.starpi}
For any $\omega$ with marginals ${}_\star\hspace{-1pt}\pi$,
$\dot{\nu}^\textup{op}[\omega]$ is given by \eqref{e:lagrange.clause.tuple}
with $q_e={}_\star\hspace{-1pt}\hat{q}_e$ for all $e$, that is to say, by
	\begin{equation}\label{e:opt.variable.tuple.measure.star}
	{}_\star\hspace{-1pt}\dot{\nu}_v(\smash{\vec{\sigma}}_{\delta v})
	\equiv \frac1{\bm{\dot{z}}_v}
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	 \prod_{e\in\delta v} 
		{}_\star\hspace{-1pt}\hat{q}_e(\sigma_e)\end{equation}
where $\bm{\dot{z}}_v$ is the normalizing constant. 

\begin{proof}
It suffices to verify that
	\begin{align}\nonumber
	{}_\star\hspace{-1pt}\dot{\nu}_v(\sigma_{av}=\sigma)
	&\cong
	{}_\star\hspace{-1pt}\hat{q}_{av}(\sigma_{av})
	\sum_{\smash{\vec{\sigma}}_{\delta v}}
	\Ind{\sigma_{av}=\sigma}
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\prod_{b \in \partial v\setminus a}
		{}_\star\hspace{-1pt}\hat{q}_{bv}(\sigma_{bv})\\
	&\cong{}_\star\hspace{-1pt}\hat{q}_{av}(\sigma_{av})
	\bigg\{
	\Big(\textup{\footnotesize\textsf{BP}}_{va}[{}_\star\hspace{-1pt}\hat{q}]\Big)(\sigma_{av})
	\bigg\}
	={}_\star\hspace{-1pt}\hat{q}_{av}(\sigma_{av})
	{}_\star\hspace{-1pt}\dot{q}_{va}(\sigma_{av})
	\cong {}_\star\hspace{-1pt}\pi_{av}(\sigma)\,,
	\label{e:marginal.of.nu.BP}
	\end{align}
where $\textup{\footnotesize\textsf{BP}}$ is the belief propagation mapping for the color model (the unweighted version of \eqref{e:bp}),
and the last two identities follow from the fact that ${}_\star\hspace{-1pt}\pi_{av}$, ${}_\star\hspace{-1pt}\dot{q}_{va}$, and ${}_\star\hspace{-1pt}\hat{q}_{av}$ are all based on the \bemph{same} tree, namely,
the $r$-neighborhood of $v$ in $\mathscr{G}$
(see also Remark~\ref{r:first.rmk.coherence}).
This verifies that the marginals of ${}_\star\hspace{-1pt}\dot{\nu}$ are indeed consistent with ${}_\star\hspace{-1pt}\pi$. Since ${}_\star\hspace{-1pt}\dot{\nu}$ takes the form \eqref{e:lagrange.clause.tuple} given by the Lagrangian calculation, it follows that ${}_\star\hspace{-1pt}\dot{\nu}=\dot{\nu}^\textup{op}[\omega]$.
\end{proof}

It is important to note, however, that 
the analogue of Lemma~\ref{l:nu.star.as.optimizer.for.starpi} 
does \bemph{not} hold for the clause measure:
for $({}_\star\hspace{-1pt}\omega)_{\bm{L},j}={}_\star\hspace{-1pt}\pi_{\bm{L}(j)}$,
it is \bemph{not} necessarily the case
that $\hat{\nu}^\textup{op}[{}_\star\hspace{-1pt}\omega]$ is given by
(cf.\ \eqref{e:clause.tuple.measure.weighted})
	\begin{equation}\label{e:opt.clause.tuple.measure.star}
	{}_\star\hspace{-1pt}\hat{\nu}_a(\smash{\vec{\sigma}}_{\delta a})
	=
	\frac1{\bm{\hat{z}}_a}
	\hat{\varphi}_a(\smash{\vec{\sigma}}_{\delta a})
		\prod_{v\in\partial a}
		{}_\star\hspace{-1pt}\dot{q}_{va}(\sigma_{av})\,.
	\end{equation}

also define the vertex pair empirical measure $
u\equiv(\dot{
u},\hat{
u})$ as in \eqref{e:variable.

\label{d:judicious.pair}
As $\bm{Z}$ is defined to count only judicious configurations, in order for the contribution $\bm{Z}^2(\omega)$ to be non-zero, $\omega$ must satisfy two properties. First, the single-copy marginals of $\omega$
must agree with the measure ${}_\star\hspace{-1pt}\omega$
defined in the statement of Corollary~\ref{c:first.moment.exponent}: that is to say, for both $i=1,2$, we must have
	\begin{equation}\label{e:margin.judicious}
	{}_\star\hspace{-1pt}\omega_{\bm{L},j}(\sigma^i)
	= (\omega_{\bm{L},j})^j(\sigma^i)
	\equiv
	\sum_{\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2}
	\Ind{\tau^i=\sigma^i}
	\omega_{\bm{L},j}(\tau)
	\end{equation}
for all $\bm{L},j$. Secondly, $\omega$ must arise as the marginal of a valid vertex measure $\nu=(\dot{\nu},\hat{\nu})$. We say that $\omega$ is \bemph{judicious} if it satisfies both these properties. (The second property is important mainly for computing the dimension of the space of feasible $\omega$, as we will see in the proof of Lemma~\ref{l:dimension.count.two} below.)

\label{l:if.neg.def}
Denote ${}_{*}\omega\equiv{}_\star\hspace{-1pt}\omega\otimes{}_\star\hspace{-1pt}\omega$ for ${}_\star\hspace{-1pt}\omega$ as in Corollary~\ref{c:first.moment.exponent}.
Suppose that if we restrict to $\omega\in\bm{I}_0$,
the function
$\bm{\Psi}_{\mathscr{D},2}$ is uniquely maximized at ${}_{*}\omega$, with negative-definite Hessian.
Then 
	\[\mathbb{E}_{\mathscr{D}}\Big( \bm{Z}^2[I_0]\Big)
	\asymp_R \Big(\mathbb{E}_{\mathscr{D}}\bm{Z}\Big)^2\,,\]
i.e., the conclusion of Proposition~\ref{p:second.moment.judicious} holds.

\begin{proof} The same calculation leading to
\eqref{e:stirling.with.poly.error} gives
(in the interior of the simplex of feasible $\nu$)
a similar formula
	\[
	\mathbb{E}_{\mathscr{D}}\bm{Z}^2[\nu]
	\asymp_R
	\frac1{ n^{\bm{s}_2}}
	\exp\bigg\{n \bm{\Phi}_{\mathscr{D},2}(\nu)\bigg\}\,,
	\]
where $\bm{s}_2=\bm{s}_2(\mathscr{D})$ 
takes into account the polynomial corrections from the Stirling approximation,
and is the analogue of \eqref{e:stirling.correction.number} for the pair model:
	\begin{equation}\label{e:stirling.correction.two}
	\bm{s}_2=\bm{s}_2(\mathscr{D})
	=\sum_{\bm{T}}\bigg( (s_{\bm{T}})^2-1\bigg)
	+\sum_{\bm{L}}\bigg( (s_{\bm{L}})^2-1\bigg)
	-\sum_{\bm{t}}\bigg( (s_{\bm{t}})^2-1\bigg)\,.
	\end{equation}
Let us write $\nu\sim\omega$ if $\nu$ is consistent with $\omega$. In Lemma~\ref{l:dimension.count.two} (deferred to \S\ref{ss:coherence.weights}), we will calculate
	\begin{equation}\label{e:dimension.count.pair.model}
	d_2(\mathscr{D})
	\equiv\dim\bigg\{\nu : \nu\sim\omega\bigg\}\,.
	\end{equation}
for $\omega$ close to ${}_{*}\omega$. Then, similarly to
\eqref{e:first.mmt.poly}
and \eqref{e:prep.for.gaussian.sum}, we have
	\[
	\mathbb{E}_{\mathscr{D}}\bm{Z}^2(\omega)
	=
	\sum_{\nu:\nu\sim\omega}
	\mathbb{E}_{\mathscr{D}}\bm{Z}^2[\nu]
	\asymp_R
	\sum_{\nu:\nu\sim\omega}
	\frac1{n^{\bm{s}_2/2}}
	\exp\bigg\{n \bm{\Phi}_{\mathscr{D},2}(\nu)\bigg\}
	\asymp_R
	\frac{n^{d_2/2}}
		{n^{\bm{s}_2/2}}
	\exp\bigg\{
	\bm{\Psi}_{\mathscr{D},2}(\omega)
	\bigg\}\,.
	\]
Finally, we will show in Lemma~\ref{l:dimension.of.judicious.omega} (also deferred to \S\ref{ss:coherence.weights}) that
	\begin{equation}\label{e:dim.judicious.omega}
	j_2\equiv j_2(\mathscr{D})\equiv
	\dim\bigg\{\omega
		:\textup{$\omega$ is judicious}\bigg\}
	=
	\bm{s}_2(\mathscr{D})- d_2(\mathscr{D})- 2\wp(\mathscr{D})
	\end{equation}
for $\wp$ as in \eqref{e:wp.of.R}. If $\bm{\Psi}_{\mathscr{D},2}$ satisfies the conditions of the lemma, then the gaussian summation estimate
\eqref{e:gaussian.sum} gives
	\[\mathbb{E}_{\mathscr{D}}\bm{Z}^2[\bm{I}_0]
	\asymp_R
	\frac1{n^{\wp}}
	\exp\bigg\{
	\bm{\Psi}_{\mathscr{D},2}({}_{*}\omega)
	\bigg\}
	\stackrel{\odot}{=}
	\Bigg(
	\frac1{n^{\wp/2}}
	\exp\bigg\{
	\bm{\Psi}_{\mathscr{D}}({}_\star\hspace{-1pt}\omega)
	\bigg\}
	\Bigg)^2
	\asymp_R
	\Big(\mathbb{E}_{\mathscr{D}}\bm{Z}\Big)^2\,.
	\]
(The step marked $\odot$ uses the identity
$\bm{\Psi}_{\mathscr{D},2}({}_{*}\omega)
=2\bm{\Psi}_{\mathscr{D}}({}_\star\hspace{-1pt}\omega)$
which is easy to verify.)
\end{proof}

 The same calculation leading to
\eqref{e:stirling.with.poly.error} gives
(in the interior of the simplex of feasible $\nu$)
a similar formula
	\[
	\mathbb{E}_{\mathscr{D}}\bm{Z}^2[\nu]
	\asymp_R
	\frac1{ n^{\bm{s}_2}}
	\exp\bigg\{n \bm{\Phi}_{\mathscr{D},2}(\nu)\bigg\}\,,
	\]
where $\bm{s}_2=\bm{s}_2(\mathscr{D})$ 
takes into account the polynomial corrections from the Stirling approximation,
and is the analogue of \eqref{e:stirling.correction.number} for the pair model:
	\begin{equation}\label{e:stirling.correction.two}
	\bm{s}_2=\bm{s}_2(\mathscr{D})
	=\sum_{\bm{T}}\bigg( (s_{\bm{T}})^2-1\bigg)
	+\sum_{\bm{L}}\bigg( (s_{\bm{L}})^2-1\bigg)
	-\sum_{\bm{t}}\bigg( (s_{\bm{t}})^2-1\bigg)\,.
	\end{equation}
Let us write $\nu\sim\omega$ if $\nu$ is consistent with $\omega$. In Lemma~\ref{l:dimension.count.two} (deferred to \S\ref{ss:coherence.weights}), we will calculate
	\begin{equation}\label{e:dimension.count.pair.model}
	d_2(\mathscr{D})
	\equiv\dim\bigg\{\nu : \nu\sim\omega\bigg\}\,.
	\end{equation}
for $\omega$ close to ${}_{*}\omega$. Then, similarly to
\eqref{e:first.mmt.poly}
and \eqref{e:prep.for.gaussian.sum}, we have
	\[
	\mathbb{E}_{\mathscr{D}}\bm{Z}^2(\omega)
	=
	\sum_{\nu:\nu\sim\omega}
	\mathbb{E}_{\mathscr{D}}\bm{Z}^2[\nu]
