In the processed graph $\mathscr{G}=(V,F,E)=\textup{\textsf{pr}}\mathscr{G}'$, let $U\equiv (V_U,F_U,E_U)$ be any compound enclosure. Recall from Definition~\ref{d:enclosure}
that $U= U^\circ \cup \partial U^\circ$ where 
$\partial U^\circ\equiv\partial_\circ U$ is the set of perfect variables in $U$. Let $\delta U$ denote the edges in $U$ that are incident to $\partial_\circ U$, and decompose
	\[
	\omega
	\equiv\begin{pmatrix}
	\omega_\textup{in}\\
	\omega_{\delta U}\\
	\omega_\textup{out}
	\end{pmatrix}
	\equiv
	\begin{pmatrix}
	(\omega_{\bm{L},j}
	: \textup{some edge in $E_U\setminus \delta U$
		has type $(\bm{L},j)$})
	\\
	(\omega_{\bm{L},j}
	: \textup{some edge in $\delta U$
		has type $(\bm{L},j)$})\\
	(\omega_{\bm{L},j}
	: \textup{some edge in $E \setminus E_U$
		has type $(\bm{L},j)$})
	\end{pmatrix}\,.
	\]
(An edge $e=(av)$ has type $(\bm{L},j)$ if $\bm{L}_a=\bm{L}$ and $e$ is the $j$-th edge in $\delta a$.)
We also abbreviate 
$\omega_U\equiv(\omega_\textup{in},\omega_{\delta U})$ and
$\omega_\textup{bd}\equiv(\omega_{\delta U},\omega_\textup{out})$. Assume the neighborhood profile $\mathscr{D}$ of $\mathscr{G}$ is bounded away from zero in the sense of \eqref{e:pos.frac}. Then, using the notation of Definition~\ref{d:constrained.opt.compound.enclosure}, we have
	\begin{align}
	\label{e:max.over.acute.omega.compound}
	&\max_{\acute{\omega}}
	\Bigg\{
	\bm{\Psi}_{\mathscr{D},2}(\acute{\omega})
	-\bm{\Psi}_{\mathscr{D},2}(\omega)
	: 
	\textup{$\omega$ and $\acute{\omega}$
	are judicious,
	$\acute{\omega}_\textup{bd}=\omega_\textup{bd}$}
	\Bigg\}\\
	&=c_\textup{in}
	\Bigg( \max_\nu
	\Bigg\{ \mathcal{H}(\nu)
		: 	\nu \in
		\bm{J}(U,\omega_{\delta U})\Bigg\}
	- \max_\nu
	\Bigg\{ \mathcal{H}(\nu)
		: \nu \in \bm{\Delta}(U;\omega_U)\Bigg\}
	\Bigg)\,,
	\end{align}
where $c_\textup{in}$ depends only on $\mathscr{D}$ and on $U$, and is lower bounded by $c_1$.


\begin{proof} Recalling Remark~\ref{d:degseq},
let $\mathcal{D}$ be any neighborhood sequence that is consistent with $\mathscr{D}$. Since for any $\omega$ we have 
$\mathbb{E}_{\mathscr{D}}\bm{Z}^2(\omega)
=\mathbb{E}_\mathcal{D}\bm{Z}^2(\omega)$,
rather than working under $\mathbb{P}_{\mathscr{D}}$
we can instead work under $\mathbb{P}_\mathcal{D}$,
which can be sampled by the (generalized) configuration model described in
Remark~\ref{r:processed.graph.types.CM}.
Let $\bm{t}(U)$ denote the collection of all edge types $\bm{t}$ appearing on edges inside $U$; recall that these are all compound types.


Let $\mathfrak{M}$ denote the random matching of $\delta V$ to $\delta F$ (which defines the graph $\mathscr{G}$). We let $\mathfrak{m}$
denote the restriction of $\mathfrak{M}$ to 
half-edges with types in $\bm{t}(U)$; this defines a subgraph $\mathscr{U} \equiv(V_{\mathscr{U}},F_{\mathscr{U}},E_{\mathscr{U}}) \subseteq\mathscr{G}$ which consists of $n_U = n c_\textup{in}$ disjoint copies of $U$. Moreover, since $\mathscr{U}$ 
consists of $n_U$ disjoint copies of $U$ for any
valid realization of
$\mathfrak{m}$, we can condition on 
$\mathfrak{m}$ without changing the expected value of the partition function:
	\[\frac1{n^{O(1)}}
	\exp\Big\{
	n\bm{\Psi}_{\mathscr{D},2}(\omega)
	\Big\}= \mathbb{E}_{\mathscr{D}}\bm{Z}^2(\omega)
	=\mathbb{E}_\mathcal{D}\bm{Z}^2(\omega)
	=\mathbb{E}_\mathcal{D}\bigg(
		\bm{Z}^2(\omega)
		\,\bigg|\, \mathfrak{m}
		\bigg)\,.
	\]
Let $\partial_\circ\mathscr{U}$ denote the $n_U$ copies of $\partial_\circ U$ inside $\mathscr{U}$, and let $\delta\mathscr{U}$ denote the edges in $\mathscr{U}$ incident to $\partial_\circ\mathscr{U}$. Any (pair) coloring $\smash{\vec{\sigma}}$ on $\mathscr{G}$ can be decomposed as
	\[
	\smash{\vec{\sigma}}
	\equiv 
	\begin{pmatrix}
	\smash{\vec{\sigma}}_\textup{in} \\
	\smash{\vec{\sigma}}_{\delta\mathscr{U}} \\
	\smash{\vec{\sigma}}_\textup{out}
	\end{pmatrix}
	\equiv
	\begin{pmatrix}
	(\sigma_e : e \in E_{\mathscr{U}}\setminus \delta\mathscr{U}) \\
	(\sigma_e : e \in \delta\mathscr{U}) \\
	(\sigma_e : e \in E\setminus E_{\mathscr{U}}) 
	\end{pmatrix}\,.
	\]
Note that this corresponds precisely to the above decomposition of $\omega$: a coloring $\smash{\vec{\sigma}}$ has empirical measure $\omega$ (which we abbreviate $
\smash{\vec{\sigma}}\sim\omega$) if and only if
$\smash{\vec{\sigma}}_\textup{in}$,
$\smash{\vec{\sigma}}_{\delta\mathscr{U}}$, and
$\smash{\vec{\sigma}}_\textup{out}$
have empirical measures
$\omega_\textup{in}$,
$\omega_{\delta U}$, and
$\omega_\textup{out}$ respectively.
We also abbreviate
$\smash{\vec{\sigma}}_{\mathscr{U}}
	\equiv ( \smash{\vec{\sigma}}_\textup{in},
		\smash{\vec{\sigma}}_{\delta\mathscr{U}})$
	and 
	$\omega_U
	\equiv (\omega_\textup{in},
	\omega_{\delta U})$.
With this notation, we can decompose
$\bm{Z}^2(\omega)$ as
	\begin{equation}\label{e:partition.fn.tree.factorize}
	\bm{Z}^2(\omega)
	=
	\sum_{\smash{\vec{\sigma}}_{\mathscr{U}}}
		\Ind{\smash{\vec{\sigma}}_{\mathscr{U}} \sim \omega_U}
	\varphi_{\mathscr{U}}(\smash{\vec{\sigma}}_{\mathscr{U}})
	\Bigg\{
	\sum_{\smash{\vec{\sigma}}_\textup{out}}
		\Ind{\smash{\vec{\sigma}}_\textup{out} \sim\omega_\textup{out}}
	\varphi_\textup{out}
	(\smash{\vec{\sigma}}_{\delta\mathscr{U}},\smash{\vec{\sigma}}_\textup{out})
	\Bigg\}\,,
	\end{equation}
where, recalling the definition \eqref{e:pair.color.model.factors}
of the factors for the pair coloring model, we define
	\begin{align*}
	\varphi_{\mathscr{U}}(\smash{\vec{\sigma}}_{\mathscr{U}})
	&\equiv
	\prod_{v\in V_{\mathscr{U}}\setminus\partial_\circ U}
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\prod_{a\in F_{\mathscr{U}}}
	\hat{\varphi}_a(\smash{\vec{\sigma}}_{\delta a})\,, \\
	\varphi_\textup{out}
	(\smash{\vec{\sigma}}_{\delta\mathscr{U}},\smash{\vec{\sigma}}_\textup{out})
	&\equiv
	\prod_{v\in (V\setminus V_U) \cup \partial_\circ U}
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\prod_{a\in F\setminus F_{\mathscr{U}}}
	\hat{\varphi}_a(\smash{\vec{\sigma}}_{\delta a})\,.
	\end{align*}
Taking the expectation conditional on $\mathfrak{m}$ gives
	\[
	\mathbb{E}_\mathcal{D}\Big(\bm{Z}^2(\omega)\,\Big|\,\mathfrak{m}\Big)
	=
	\sum_{\smash{\vec{\sigma}}_{\mathscr{U}}}
		\Ind{\smash{\vec{\sigma}}_{\mathscr{U}} \sim \omega_U}
	\varphi_{\mathscr{U}}(\smash{\vec{\sigma}}_{\mathscr{U}})\\
	\overbrace{
	\mathbb{E}_\mathcal{D}
	\Bigg(
	\sum_{\smash{\vec{\sigma}}_\textup{out}}
		\Ind{\smash{\vec{\sigma}}_\textup{out} \sim\omega_\textup{out}}
	\varphi_\textup{out}
	(\smash{\vec{\sigma}}_{\delta\mathscr{U}},\smash{\vec{\sigma}}_\textup{out})
	\,\Bigg|\,\mathfrak{m}
	\Bigg)}^{X\equiv X(\omega_{\delta U},\omega_\textup{out})}\,,\]
where we emphasize that the value of 
$X$ is constant over all $\smash{\vec{\sigma}}_{\delta\mathscr{U}}\sim\omega_{\delta U}$. Now recall that $\mathscr{U}$ consists of a disjoint union of copies of $U$, which we denote $U_i$ for $1\le i\le n_U$. For any $\smash{\vec{\sigma}}_{\mathscr{U}}$ we can define its empirical measure over the copies of $U$, that is to say,
	\[
	\nu(\smash{\vec{\sigma}}_U)
	= \frac1{n_U}
	\sum_{i=1}^{n_U}
	\Ind{ \smash{\vec{\sigma}}_{ U_i} = \smash{\vec{\sigma}}_U}
	\]
We write $\smash{\vec{\sigma}}_{\mathscr{U}}\sim\nu$ if $\smash{\vec{\sigma}}_{\mathscr{U}}$ has empirical measure $\nu$. Then, with $\bm{\Delta}(U;\omega_U)$ as in Definition~\ref{d:constrained.opt.compound.enclosure}, we have
	\begin{align*}
	\sum_{\smash{\vec{\sigma}}_{\mathscr{U}}}
		\Ind{\smash{\vec{\sigma}}_{\mathscr{U}} \sim \omega_U}
	\varphi_{\mathscr{U}}(\smash{\vec{\sigma}}_{\mathscr{U}})
	&=
	\sum_{\nu\in\bm{\Delta}(U;\omega_U)}
	\sum_{\smash{\vec{\sigma}}_{\mathscr{U}}}
		\Ind{\smash{\vec{\sigma}}_{\mathscr{U}} \sim \nu}
	\varphi_{\mathscr{U}}(\smash{\vec{\sigma}}_{\mathscr{U}})
	=
	\sum_{\nu\in\bm{\Delta}(U;\omega_U)}
	\binom{n_U}{n_U\nu}\\
	&= n^{O(1)} \exp\Bigg\{ n_U
	\max_\nu \bigg\{
	\mathcal{H}(\nu) : \nu \in \bm{\Delta}(U;\omega_U)
		\bigg\}\Bigg\}\,,
	\end{align*}
where the last step is by Stirling's approximation. Altogether we conclude
	\begin{equation}\label{e:reduce.to.simplex.omega}
	\exp\bigg\{n \bm{\Psi}_{\mathscr{D},2}(\omega)\bigg\}
	= n^{O(1)}
	X\exp\Bigg\{ n_U
	\max_\nu \bigg\{
	\mathcal{H}(\nu) : \nu \in \bm{\Delta}(U;\omega_U)
		\bigg\}\Bigg\}
	\end{equation}
On the other hand, summing over all possibilities of $\omega_\textup{in}$ gives
	\begin{align}\nonumber
	&\frac1{n^{O(1)}}
	\exp\Bigg\{
		n\max\Big\{
	\bm{\Psi}_{\mathscr{D},2}(\acute{\omega})
	: \acute{\omega}_\textup{bd}=\omega_\textup{bd}
	\Big\}
	\Bigg\}
	=
	\sum_{\acute{\omega}}
	\Ind{\acute{\omega}_\textup{bd}=\omega_\textup{bd}}
	\mathbb{E}_\mathcal{D}\bigg(
		\bm{Z}^2(\acute{\omega})
		\,\bigg|\, \mathfrak{m}
		\bigg)\\
	&= X
	\sum_{\smash{\vec{\sigma}}_{\mathscr{U}}}
	\Ind{\smash{\vec{\sigma}}_{\delta\mathscr{U}} \sim \omega_{\delta U}}
	\varphi_{\mathscr{U}}(\smash{\vec{\sigma}}_{\mathscr{U}})
	= n^{O(1)}
	X
	\exp\Bigg\{ n_U
	\max_\nu \bigg\{
	\mathcal{H}(\nu) : \nu \in \bm{J}(U;\omega_{\delta U})
		\bigg\}\Bigg\}\,.
	\label{e:reduce.to.simplex.judicious}
	\end{align}
The claim follows by combining \eqref{e:reduce.to.simplex.omega} with \eqref{e:reduce.to.simplex.judicious}.
\end{proof}

