Let $v$ be a variable of total type $\bm{T}$, which we assume is not of compound type. Let $U\equiv U_{\bm{T}}$ be the depth-one neighborhood of $v$, in which each edge $e\in\delta v$ is labelled with its corresponding type $\bm{t}_e$. However, we \bemph{forget the total type labellings on the clauses and other edges of $U$,} and each boundary edge $e\in\delta U$ is labelled only with its index $j(e)\in[k]$. An \bemph{augmented (pair) coloring} on $U$ is a configuration $(\smash{\vec{\sigma}},\smash{\vec{\bm{L}}})$ which assigns to each edge $e\in U$ a spin $(\sigma_e,\bm{L}_e)$ where $\sigma_e\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$ and $\bm{L}_e$ is a clause total type. Recall \eqref{e:pair.color.model.factors} where we defined the variable and clause factors $\varphi_v$ and $\hat{\varphi}_a$ for the pair coloring model. The factors for the augmented pair coloring model are 
	\begin{align}\nonumber
	\varphi_v(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	&\equiv
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e\in\delta v}
	\Ind{\bm{L}_e\ni\bm{t}_e}\,,\\
	\hat{\varphi}_a(\smash{\vec{\sigma}}_{\delta a},\smash{\vec{\bm{L}}}_{\delta a})
	&\equiv
	\hat{\varphi}_a(\smash{\vec{\sigma}}_{\delta a})
	\mathbf{1}\bigg\{
	\textup{the $\bm{L}_e$ are the same for all
		$e\in\delta a$}
	\bigg\}\,.
	\label{e:augmented.model.factors}
	\end{align}
We say that $(\smash{\vec{\sigma}},\smash{\vec{\bm{L}}})$ is a valid
augmented coloring on $U$ as long as
	\[
	\varphi_v(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	\prod_{a\in\partial v}
	\hat{\varphi}_a(\smash{\vec{\sigma}}_{\delta a},\smash{\vec{\bm{L}}}_{\delta a})
	=1\,.
	\]
Analogously to the 
simplex $\bm{\Delta}(U)$ from
Definition~\ref{d:constrained.opt.compound.enclosure}, 
we now let
	\[
	\bm{\Delta}_\textup{aug}(U)
	\equiv\left\{
	\hspace{-3pt}\begin{array}{c}
	\textup{probability measures $\nu$
		on valid}\\
	\textup{augmented pair colorings
		$(\smash{\vec{\sigma}},\smash{\vec{\bm{L}}})$ of $U$}
	\end{array}\hspace{-3pt}
	\right\}\,.
	\]
For each edge $e$ in $U$, let $p(e)$ denote the edge in $\delta v$ that is closest to $e$. (If $e\in\delta v$ then $p(e)=e$.)
We then say that a measure $\nu\in\bm{\Delta}_\textup{aug}(U)$ is \bemph{fully judicious with respect to $\mathscr{D}$} if it holds for all edges $e$ in $U$ that
	\begin{equation}\label{e:pi.DD.first.appearance}
	\nu_e(\sigma,\bm{L})
	= \overbrace{
	\underbrace{
	\frac{\displaystyle
	\hat{\mathscr{D}}(\bm{L})\Ind{\bm{L}_{j(\bm{t}_{p(e)})}
		=\bm{t}_{p(e)}}}
		{	\displaystyle \sum_{\bm{L}'}
	\hat{\mathscr{D}}(\bm{L}')\Ind{(\bm{L}')_{j(\bm{t}_{p(e)})}
		=\bm{t}_{p(e)}}}
	}_{\textup{denote this }
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_{p(e)})}
	\tilde{\omega}_{\bm{L},j(e)}(\sigma)
	}^{\textup{denote this 
	$(\textup{\textsf{aug}}_{\mathscr{D}}(\tilde{\omega}))_e(\sigma,\bm{L})$}}
	\end{equation}
for some $\tilde{\omega}$ that is judicious
(in the sense of Definition~\ref{d:judicious.pair}). Given any particular $\omega$, we now write
