\begin{proof} As in the proof of Proposition~\ref{p:update.compound},
we can fix a neighborhood sequence $\mathcal{D}$ that is consistent with $\mathscr{D}$, and work under the measure $\mathbb{P}_\mathcal{D}$. Let $\bm{t}(\bm{T})$
denote the set of all edge types that can be incident to a variable of type $\bm{T}$. Let $\bm{L}(\bm{T})$ denote the set of all clause types that can neighbor a variable of type $\bm{T}$:
	\[
	\bm{L}(\bm{T})
	= \bigg\{ \bm{L}
	: \bm{t}\in\bm{L} \textup{ for some }
		\bm{t}\in \bm{t}(\bm{T}) \bigg\}\,.
	\]
Let $\mathfrak{M}$ denote the random matching of $\delta V$ to $\delta F$ (which defines the graph $\mathscr{G}$). We let $\mathfrak{m}_1$ denote the restriction of $\mathfrak{M}$ to the half-edges of types belonging to $\bm{t}(\bm{T})$. We then let $\mathfrak{m}_2$ denote the edges in $\mathfrak{M}\setminus\mathfrak{m}_1$ that are incident to the edges of $\mathfrak{m}_1$. Finally, we let $\mathfrak{m}_3=\mathfrak{M}\setminus(\mathfrak{m}_1\cup\mathfrak{m}_2)$.
The partial matching $(\mathfrak{m}_1,\mathfrak{m}_2)$ defines the subgraph $\mathscr{U}\subseteq\mathscr{G}$ consisting of the depth-one neighborhoods of all the variables of type $\bm{T}$. Analogously to \eqref{e:partition.fn.tree.factorize}, we have the decomposition
	\[\bm{Z}^2(\omega)
	=
	\sum_{\smash{\vec{\sigma}}_{\mathscr{U}}}
		\Ind{\smash{\vec{\sigma}}_{\mathscr{U}} \sim \omega_U}
	\varphi_{\mathscr{U}}(\smash{\vec{\sigma}}_{\mathscr{U}})
	\Bigg\{
	\sum_{\smash{\vec{\sigma}}_\textup{out}}
		\Ind{\smash{\vec{\sigma}}_\textup{out} \sim\omega_\textup{out}}
	\varphi_\textup{out}
	(\smash{\vec{\sigma}}_{\delta\mathscr{U}},\smash{\vec{\sigma}}_\textup{out})
	\Bigg\}\,.\]
Note that $\varphi_{\mathscr{U}}$ depends on $(\mathfrak{m}_1,\mathfrak{m}_2)$, while
$\varphi_\textup{out}$ depends on 
$(\mathfrak{m}_2,\mathfrak{m}_3)$. 
However, we have
	\[\mathbb{E}_\mathcal{D}\Bigg(
	\sum_{\smash{\vec{\sigma}}_\textup{out}}
		\Ind{\smash{\vec{\sigma}}_\textup{out} \sim\omega_\textup{out}}
	\varphi_\textup{out}
	(\smash{\vec{\sigma}}_{\delta\mathscr{U}},\smash{\vec{\sigma}}_\textup{out})
	\,\Bigg|\,\mathfrak{m}_2\Bigg)
	= X(\omega_{\delta U},\omega_\textup{out})
	\equiv X
	\]
for any $\smash{\vec{\sigma}}_{\delta\mathscr{U}}\sim\omega_{\delta U}$. 
Under $\mathbb{P}_\mathcal{D}$, the matching $\mathfrak{m}_1$
is independent of the pair $(\mathfrak{m}_2,\mathfrak{m}_3)$. The expected value of $\bm{Z}^2(\omega)$ under $\mathbb{P}_\mathcal{D}$ remains the same even after conditioning on $\mathfrak{m}_2$, so we have
	\begin{align*}
	\mathbb{E}_\mathcal{D}\bm{Z}^2(\omega)
	&=\mathbb{E}_\mathcal{D}\Big( \bm{Z}^2(\omega)\,\Big|\,
		\mathfrak{m}_2\Big)
	= X \cdot
	\mathbb{E}_\mathcal{D}\Bigg( \sum_{\smash{\vec{\sigma}}_{\mathscr{U}}}
		\Ind{\smash{\vec{\sigma}}_{\mathscr{U}} \sim \omega_U}
	\varphi_{\mathscr{U}}(\smash{\vec{\sigma}}_{\mathscr{U}})
	\,\Bigg|\,\mathfrak{m}_2
	\Bigg)\\
	&=
	X \cdot \sum_{\mathfrak{m}_1}
	\mathbb{P}_\mathcal{D}(\mathfrak{m}_1)
	\underbrace{
	\sum_{\smash{\vec{\sigma}}_{\mathscr{U}}}
		\Ind{\smash{\vec{\sigma}}_{\mathscr{U}} \sim \omega_U}
	\varphi_{\mathscr{U}}(\smash{\vec{\sigma}}_{\mathscr{U}})}_{\textup{depends on $(
		\mathfrak{m}_1,\mathfrak{m}_2)$}}\,.
	\end{align*}
Recall that $(\mathfrak{m}_1,\mathfrak{m}_2)$ defines the subgraph $\mathscr{U}$ consisting of the depth-one neighborhoods of all the variables of type $\bm{T}$; without loss we suppose those variables are labelled 
$\set{v_1,\ldots,v_{n_{\bm{T}}}}$. On the other hand, let $\mathcal{U
}$ denote the graph consisting of $n_{\bm{T}}$ disjoint copies $U_1,\ldots,U_{n_{\bm{T}}}$ of the tree $U$ from Definition~\ref{d:judicious.augmented.alphabet}. A tuple $(\mathfrak{m}_1,\mathfrak{m}_2,\smash{\vec{\sigma}}_{\mathscr{U}})$
with $\smash{\vec{\sigma}}_{\mathscr{U}}\sim\omega_U$ can be mapped bijectively to an augmented coloring
$(\smash{\vec{\sigma}}_\mathcal{U},\bm{L}_\mathcal{U})$
of $\mathcal{U}$ with edge empirical measures
$\textup{\textsf{aug}}(\omega_U)$. (The bijection goes as follows: given $(\mathfrak{m}_1,\mathfrak{m}_2)$ there is a unique graph isomorphism $g :\mathscr{U}\to \mathcal{U}$ which maps $v_i$ to the root of $U_i$ for each $i$, respects edge types $\bm{t}_e$ for all $e\in\delta v_i$ for all $i$, and respects the edge indices $j(e)$ for all $e\in\delta\mathscr{U}$. The coloring $\smash{\vec{\sigma}}_{\mathscr{U}}$ is mapped under $g$ to a coloring on $\mathscr{U}$. Finally, for each edge $e=(au)$ in $U$, we set $\SPIN{L}_e$ to be the clause type of $g^{-1}(a)$.) It follows that
	\[
	\sum_{\mathfrak{m}_1}
	\mathbb{P}_\mathcal{D}(\mathfrak{m}_1)
	\sum_{\smash{\vec{\sigma}}_{\mathscr{U}}}
		\Ind{\smash{\vec{\sigma}}_{\mathscr{U}} \sim \omega_U}
	\varphi_{\mathscr{U}}(\smash{\vec{\sigma}}_{\mathscr{U}})
	=
	\frac1{|\set{\mathfrak{m}_1}|}
	\sum_{(\smash{\vec{\sigma}}_\mathcal{U},\bm{L}_\mathcal{U})}
	\Ind{
	(\smash{\vec{\sigma}}_\mathcal{U},\bm{L}_\mathcal{U}) \sim
	\textup{\textsf{aug}}(\omega_U)}
	\varphi_{\mathcal{U}}(
	\smash{\vec{\sigma}}_\mathcal{U},\bm{L}_\mathcal{U})\,,\]
where $\set{\mathfrak{m}_1}$ denotes the set of all matchings $\mathfrak{m}_1$ that are consistent with $\mathcal{D}$. It follows analogously to 
\eqref{e:reduce.to.simplex.omega} that
	\[
	\exp\bigg\{
	n \bm{\Psi}_{\mathscr{D},2}(\omega)
	\bigg\}
	=\frac{n^{O(1)} X }{|\mathfrak{m}_1|}
	\exp\Bigg\{n_{\bm{T}}
	\max_\nu\bigg\{\mathcal{H}(\nu):
		\nu\in\bm{\Delta}_{\mathscr{D}}(U;\omega_U)
	\Bigg\}\,.\]
On the other hand, summing over all possibilities of $\omega_\textup{in}$ gives, analogously to \eqref{e:reduce.to.simplex.judicious},
	\[
	\exp\Bigg\{
	n \max\bigg\{
	\bm{\Psi}_{\mathscr{D},2}(\acute{\omega})
	: \acute{\omega}_\textup{bd}=\omega_\textup{bd}
	\bigg\}\Bigg\}
	=\frac{n^{O(1)} X }{|\mathfrak{m}_1|}
	\exp\Bigg\{n_{\bm{T}}
	\max_\nu\bigg\{\mathcal{H}(\nu):
		\nu\in \bm{J}_{\mathscr{D}}(U;\omega_{\delta U})
	\Bigg\}\,.
	\]
The claim follows.
\end{proof}

