	\bigg(|\set{\bm{t}:\bm{t}\in\bm{T}}|-1\bigg)
	+\sum_{\bm{L},j} (s_{\bm{L}(j)}-1)^2\,.
	\end{align*}
Now recall that 
$\bm{s}_2(\mathscr{D})$ is given in \eqref{e:stirling.correction.two},
and
$d_2(\mathscr{D})$ was calculated in Lemma~\ref{l:dimension.count.two}. 
Thus, if we abbreviate
$\wp_2(\mathscr{D})\equiv
\bm{s}_2(\mathscr{D})-d_2(\mathscr{D})-j_2(\mathscr{D})$, then we obtain
	\[
