	=
	\sum_{\bm{T}}\Bigg(
	(x_{\bm{T}})^2 |\set{\bm{t}:\bm{t}\in\bm{T}}|
	+ 2x_{\bm{T}}+(2x_{\bm{T}}+3)r_{\bm{T}}
	-\sum_{\bm{t}\in\bm{T}}
	\Big[ (s_{\bm{t}})^2-1\Big]
	\Bigg)
	+2\sum_{\bm{L},j} (s_{\bm{L}(j)}-1)\,.
