	\bigg( (s_{\bm{t}})^2-1\bigg)
	=\sum_{\bm{t}\in\bm{T}}
	\bigg( (x_{\bm{T}})^2 + 2x_{\bm{T}} +2x_{\bm{T}}r_{\bm{t}}
		+ 3r_{\bm{t}}\bigg)
	=\bigg((x_{\bm{T}})^2 + 2x_{\bm{T}}\bigg)
		|\set{\bm{t}:\bm{t}\in\bm{T}}|
		+(2x_{\bm{T}}+3)r_{\bm{T}}\,,
