\label{l:martingale.bound.PGW}
Let $\mathscr{T}\sim{\textup{\textbf{PGW}}}$, and consider the $\ell$-neighborhood of the root, $B_\ell(v_\textup{\textsc{rt}})\equiv B_\ell(v_\textup{\textsc{rt}};\mathscr{T})$. We have
	\begin{equation}\label{e:martingale.bound.PGW}
	e_\ell \equiv \int \exp\bigg\{
		\frac{|B_\ell(v_\textup{\textsc{rt}};\mathscr{T})|}{(\alpha k^2)^\ell}
		\bigg\} \,d{\textup{\textbf{PGW}}}(\mathscr{T}) \le e
	\end{equation}
for all $\ell\ge0$.

\begin{proof}
Let $S_\ell$ be the number of variables in $\mathscr{T}$ at distance exactly $\ell$ from the root $v_\textup{\textsc{rt}}$, with $S_0=1$. Then
	\[e_\ell = 
	\mathbb{E}\Bigg[ \exp\Bigg\{ \frac1{(\alpha k^2)^\ell}
		\sum_{j=0}^\ell S_j\Bigg\}\Bigg]\,.
	\]
Let $\mathscr{F}_\ell$ denote the $\sigma$-field generated by $B_{\ell-1}(v_\textup{\textsc{rt}})$: then
	\[
	\mathbb{E}\Bigg[\exp\Bigg\{ 
	\frac{S_\ell }{(\alpha k^2)^\ell} 
	\Bigg\}\,\Bigg|\,
		\mathscr{F}_{\ell-1}\Bigg]
	=\exp\Bigg\{
	S_{\ell-1}\Bigg[
	\exp \bigg( \frac{k-1}{(\alpha k^2)^\ell} \bigg) -1
	\Bigg] \alpha k
	\Bigg\}
	\le 
	\exp\Bigg\{ \frac{S_{\ell-1}
		[1-\Theta(1/k)]}{(\alpha k^2)^{\ell-1}}
	\Bigg\}\,.
	\]
It follows by iterated expectations that
	\[
	e_\ell
	\le
	\mathbb{E}\Bigg[ \exp\Bigg\{ \frac1{(\alpha k^2)^\ell}
		\sum_{j=0}^{\ell-2} S_j
		+ \frac{S_{\ell-1}}{(\alpha k^2)^\ell}
		+ \frac{S_{\ell-1}
		[1-\Theta(1/k)]}{(\alpha k^2)^{\ell-1}}
		\Bigg\}
		\Bigg]
	\le e_{\ell-1} \le e_0 = e\,.
	\]
This proves the claim.
\end{proof}

