\label{l:mu.ell.tail.bounds}
Let $\mu$ be any probability measure over $\eta\in[0,1)$ that satisfies the bounds
\begin{enumerate}[(I)]
\item \label{i:mu.ell.upper.tail.bound} 
$\mu(\eta \ge 1/2+s)
\le \mu(\ln[\eta/(1-\eta)] \ge 4 s)\le \exp(-9s2^{k/4})$ for all $s\ge 2^{-k/4}$;
\item \label{i:mu.ell.left.tail.bound}
$\mu(\eta\le 1/2-s) \le \exp(-9s2^{k/4})$
 for all $2^{-k/4} \le s \le 1/2$.
\end{enumerate}
Then the measure $\mu^{\ell,\epsilon}\equiv(\bm{R}_\epsilon)^\ell\mu$ satisfies the same bounds
\eqref{i:mu.ell.upper.tail.bound}~and~\eqref{i:mu.ell.left.tail.bound} for all $\ell\ge0$. In addition, for all $\ell\ge1$, the measure $\bm{\mu}^{\ell,\epsilon}=\mathcal{R}_\epsilon\mu^{\ell-1,\epsilon}$ satisfies the bound
	\begin{equation}\label{i:mu.ell.eta.of.free.estimate}
	\bm{\mu}^{\ell,\epsilon}\bigg(
	\Big|2^{k+1}\bm{\eta}(\SPIN{f})-1\Big|
	\ge \frac1{2^{k/4}} \bigg)
	\le \frac1{\exp(2^{k/4})}\,.
	\end{equation}
The estimates of this lemma hold for all $0\le\epsilon\le1$.

 \label{l:X.tail.bounds}
Let $\mu$ be any probability measure over $\eta\in[0,1)$, and let $\bm{\hat{\mu}}=\smash{\hat{\mathcal{R}}}_\epsilon\mu$
for $\smash{\hat{\mathcal{R}}}_\epsilon$ as given by Definition~\ref{d:distributional.clause.recursion}. Sample $\bm{\hat{u}}\sim\bm{\hat{\mu}}$, and note that $\bm{\hat{u}}(\SPIN{+})\in[0,1)$ almost surely. Let
	\[
	X \equiv \ln \frac1{1-\bm{\hat{u}}(\SPIN{+})}
	\ge \bm{\hat{u}}(\SPIN{+})
	\ge0\,.
	\]
Write $\mathbb{P}$ and $\mathbb{E}$ for probability and expectation over the law of $X$. If $\mu$ satisfies the conditions \eqref{i:mu.ell.upper.tail.bound} and \eqref{i:mu.ell.left.tail.bound} of Lemma~\ref{l:mu.ell.tail.bounds}, then $X$ satisfies the following estimates:
\begin{enumerate}[(a)]
\item \label{i:X.left.tail} $\mathbb{P}( X \le (2^{-\xi}/2)^{k-1}) \le \exp\{-\Omega(\xi 2^{k/4})\}$ for all $k/2^{k/4} \le \xi\le1$.
\item \label{i:X.right.tail.above.one}
For all $x\ge1$, $\mathbb{P}(X\ge x) \le \exp\{-\Omega(kx2^{k/4})\}$;
\item \label{i:X.right.tail.one.tenth}
$\mathbb{P}(X\ge (2^{1/10}/2)^{k-1}) \le \exp\{ -\Omega(k2^{k/4})\})$;

\item \label{i:e.X.estimate}
$\mathbb{E} X = [1 + O(k/2^{k/8})]/2^{k-1}$;
\item \label{i:e.X.truncation.estimate}
$\mathbb{E}[X\Ind{X \ge (2^{1/10}/2)^{k-1}}]\le \exp\{-\Omega(k2^{k/4})\}$.
\end{enumerate}
The estimates of this lemma hold uniformly over all $0\le\epsilon\le1$.


\begin{proof}
We can sample $X$ as follows: let $(\eta_j)_{j\ge1}$ be a sequence of i.i.d.\ samples from $\mu$, let $K\sim\textup{\textsf{cl}}_\epsilon$, and let
	\[X \equiv -\ln\bigg(1 - \prod_{j=1}^{K-1}\eta_j\bigg)
	\ge \prod_{j=1}^{K-1}\eta_j
	\equiv \hat{u} 
	\ge \prod_{j=1}^{k-1}\eta_j
	\ge0\,.\]
If $0\le \xi\le1$ then $2^{-\xi}/2 \le 1/2-\xi/4$. Consequently, for all 
$4/2^{k/4} \le \xi \le 1$, we find
	\[
	\mathbb{P}\bigg( 
	\hat{u} \le \bigg(\frac{2^{-\xi}}{2}\bigg)^{k-1} \bigg)
	\le
	\mathbb{P}\bigg(
	\min_{j\in[k-1]}
	\eta_j \le \frac{2^{-\xi}}{2}
	\bigg)
	\le k \mu\bigg(\eta \le \frac{2^{-\xi}}{2}\bigg)
	\le k\mu\bigg(
	\eta \le \frac12-\frac{\xi}{4}\bigg)
	\le \frac{k}{\exp\{ \Omega(\xi 2^{k/4}) \}}\,,\]
where the last step is by the assumed lower bound~\eqref{i:mu.ell.left.tail.bound}. 
Since $X\ge \hat{u}$, we obtain,
for all $4/2^{k/4}\le\xi\le1$, that
	\begin{equation}\label{e:X.left.tail}
	\mathbb{P}\bigg(X \le \bigg(\frac{2^{-\xi}}{2}\bigg)^{k-1} \bigg)
	\le
	\mathbb{P}\bigg( 
	\hat{u} \le \bigg(\frac{2^{-\xi}}{2}\bigg)^{k-1} \bigg)
	\le \frac{k}{\exp\{ \Omega(\xi 2^{k/4}) \}}\,.
	\end{equation}
This implies \eqref{i:X.left.tail}. We next consider the right tail of $X$. We have $x + \ln(1-e^{-x}) \ge \Omega(x)$ uniformly over $x\ge1$, so
	\begin{align*}
	\mathbb{P}(X \ge x)
	&=\mathbb{P}\bigg(\hat{u}=\prod_{j=1}^{K-1}\eta_j 
	\ge 1-e^{-x}\bigg)
	\le \mathbb{P}\bigg( 
		\max_{1\le j\le k-2} \eta_j \ge 1-e^{-x}
		\bigg) \\
	&= \mu\bigg(
		\ln\frac{\eta}{1-\eta}
		\ge x + \ln(1-e^{-x})
		\bigg)^{k-2}
		\le \frac1{\exp\{\Omega( kx 2^{k/4} ) \}}
	\end{align*}
for all $x\ge1$, where the last step follows by using the assumed upper bound \eqref{i:mu.ell.upper.tail.bound}. This proves \eqref{i:X.right.tail.above.one}; and we obtain
	\begin{equation}\label{e:X.above.one.expectation}
	\mathbb{E}\bigg(X \Ind{X\ge1}\bigg)
	\le \frac1{\exp\{\Omega( k 2^{k/4} ) \}}
	\end{equation}
by integrating \eqref{i:X.right.tail.above.one} over $x\ge1$. Next, for $0<\xi<1$, we have
	\[
	\mathbb{P}\bigg(\hat{u}\ge \bigg(\frac{2^\xi}{2}\bigg)^{k-1}
	\bigg)
	\le\mathbb{P}\bigg(
	\eta_j \ge \frac{2^{\xi/2}}{2}
	\textup{ for at least $\frac{(k-2)\xi}2$ indices
	$j\in[k-2]$}
	\bigg)
	\le k^{k\xi}
	\mu\bigg(
	\eta\ge \frac{2^{\xi/2}}{2}
	\bigg)^{(k-2)\xi/2}\,,\]
where the factor $k^{k\xi}$ upper bounds the choice of indices $j$. We then note that
	\[s(\xi)
	\equiv \ln\frac{2^\xi/2}{1-2^\xi/2}
	\ge (2\ln2)\xi\]
by calculus. Substituting into the previous bound gives,
for all $2^{-k/4} \le \xi<1$,
	\begin{equation}\label{e:hat.u.upper.tail.small}
	\mathbb{P}\bigg(\hat{u}\ge \bigg(\frac{2^\xi}{2}\bigg)^{k-1}
	\bigg)
	\le k^{k\xi}
	\mu\bigg(
	\ln \frac{\eta}{1-\eta} \ge (2\ln2)\xi
	\bigg)^{(k-2)\xi/2}
	\le
	\frac{k^{k\xi}}{\exp\{\Omega(k\xi^2 2^{k/4})\}}
	\,,
	\end{equation}
having again used the assumed upper bound \eqref{i:mu.ell.upper.tail.bound}. We next note that if $X \ge (2^{2\xi}/2)^{k-1}$, then
	\[
	\hat{u}=1-e^{-X}
	\ge 
	1-\exp\bigg\{-
		\bigg(\frac{2^{2\xi}}{2}\bigg)^{k-1}
	\bigg\}
	= \bigg(\frac{2^{2\xi}}{2}\bigg)^{k-1}
	\exp\bigg\{
	- O\bigg( \frac{2^{2\xi}}{2}\bigg)^{k-1} \bigg)
	\bigg\}
	\ge \bigg(\frac{2^\xi}{2}\bigg)^{k-1}\,,
	\]
where the last inequality holds if we restrict to $\xi\le1/4$. Combining with \eqref{e:hat.u.upper.tail.small} gives
	\begin{equation}\label{e:X.upper.tail.small}
	\mathbb{P}\bigg(X
	\ge \bigg(\frac{2^{2\xi}}{2}\bigg)^{k-1}\bigg)
	\le
	\frac{k^{k\xi}}{\exp\{\Omega(k\xi^2 2^{k/4})\}}
	\le
	\frac1{\exp\{\Omega(k\xi^2 2^{k/4})\}}
	\end{equation}
for all $k/2^{k/4} \le \xi \le 1/4$, of which a special case is the claimed bound \eqref{i:X.right.tail.one.tenth}. Combining \eqref{e:X.left.tail}, \eqref{e:X.above.one.expectation}, and \eqref{e:X.upper.tail.small} gives \eqref{i:e.X.estimate}. Finally, we can combine \eqref{i:X.right.tail.one.tenth} with \eqref{e:X.above.one.expectation} to bound
	\[0\le \mathbb{E}\bigg[X\mathbf{1}\bigg\{X \ge \bigg(
			\frac{2^{1/10}}{2}
		\bigg)^{k-1} \bigg\}\bigg]
	\le \mathbb{P}\bigg( X \ge 
		\bigg(
			\frac{2^{1/10}}{2}
		\bigg)^{k-1}\bigg)
		+\mathbb{E}\bigg( X \Ind{X\ge1} \bigg)\\
	\le \frac1{\exp\{ \Omega(k2^{k/4}) \}}\,,\]
which gives \eqref{i:e.X.truncation.estimate}.
\end{proof}

