		\\
	\textup{a $\mathfrak{c}$-perturbation
		of $\mathscr{T}_{v_\textup{\textsc{rt}}a_\textup{\textsc{rt}}}$}
	\end{array}
	\hspace{-3pt}
	\Bigg\}	\ge \frac1{2^{k/4}}
	\Bigg)
	\le \frac1{\exp(\Omega(k2^{k/4}))}
