for all $\ell\ge0$.

\begin{proof} Throughout this proof we will abbreviate $T\equiv T_{v_\textup{\textsc{rt}}a_\textup{\textsc{rt}}}$, $\mathscr{T}\equiv\mathscr{T}_{v_\textup{\textsc{rt}}a_\textup{\textsc{rt}}}$, and $\mathscr{Q}\equiv\mathscr{Q}_{v_\textup{\textsc{rt}}a_\textup{\textsc{rt}}}$. From the definitions (see, in particular, the discussion below \eqref{e:def.FF.of.tree}), the measure $\bm{\eta}\equiv\mathbf{F}_\ell(\mathscr{T})$ only depends on the tree up to depth $\ell$ below $v_\textup{\textsc{rt}}$. For $0\le \ell\le1$, any $\mathfrak{c}$-perturbation has $\bm{\eta}'=\bm{\eta}$, so there is nothing more to prove. We therefore assume $\ell\ge2$ for the rest of the proof.

We next describe a procedure to generate a sample of $\bm{\eta}$. In the fixed tree $T$, we partition the first layer of clauses (at depth $1/2$ below $v_\textup{\textsc{rt}}$) according to the signs on the edges from these clauses to $v_\textup{\textsc{rt}}$:
	\[
	(\partial^\SPIN{+} T,\partial^\SPIN{-} T)
	\equiv
	\bigg( T \cap \partial v_\textup{\textsc{rt}}(\SPIN{+}a_\textup{\textsc{rt}})\,,
	T \cap \partial v_\textup{\textsc{rt}}(\SPIN{-}a_\textup{\textsc{rt}})\bigg)\,.
	\]
Let $d^\SPIN{\textpm}(T)\equiv|\partial^\SPIN{\textpm} T|$; these are both upper bounded by $\mathfrak{c}$. (If $T=\varnothing$ we define $d^\SPIN{\textpm}(T)\equiv0$.) For $1\le i\le d^\SPIN{+}(T)$, the $i$-th clause in $\partial^\SPIN{+} T$ has $\mathfrak{c}^\SPIN{+}(i)$ child variables in $T$. Let $T(\SPIN{+},i,j)$ be the subtree of $T$ descended from the $j$-th child variable of the $i$-th clause in $\partial^\SPIN{+}(T)$. Define similarly $\mathfrak{c}^\SPIN{-}(i)$ and $T(\SPIN{-},i,j)$. Now define $\bm{\eta}$ by the following steps:
\begin{enumerate}[(i)]
\item Sample an array of independent random trees
$\mathscr{T}^\SPIN{\textpm}_{ij}\sim{\textup{\textsf{\footnotesize PGW}}}(T(\SPIN{\textpm},i,j))$,
and define the corresponding messages
	\[
	\eta^\SPIN{\textpm}_{ij}(T)\equiv
	\Big[
	\mathbf{F}_{\ell-1}(\mathscr{T}^\SPIN{\textpm}_{ij})
	\Big](\SPIN{-})\,,
	\]
for $1\le i\le d^\SPIN{\textpm}(T)$ and $1\le j\le \mathfrak{c}^\SPIN{\textpm}(i)$.

\item Let $\smash{\vec{\eta}}$ be an array (as in \eqref{e:defn.array.ueta}) of i.i.d.\ samples from $\mu^{\ell-1}=
\bm{R}^{\ell-1}\mu^0$, where $\mu^0=\delta_{1/2}$ as before. Let
	\[
	u^\SPIN{+}_i(T)
	\equiv \prod_{j=1}^{\mathfrak{c}^\SPIN{+}(i)} 
	\eta^\SPIN{+}_{ij}(T)
	\prod_{j=\mathfrak{c}^\SPIN{+}(i)+1}^{k-1}
	\eta^\SPIN{+}_{ij}\,,\quad
	u^\SPIN{+}_i
	\equiv \prod_{j=1}^{k-1} \eta^\SPIN{+}_{ij}\,.
	\]
Define similarly $u^\SPIN{-}_i(T)$ and $u^\SPIN{-}_i$.

\item Let $\smash{\vec{d}}\equiv(d^\SPIN{+},d^\SPIN{-})$ be an independent sample from $\textup{\textsf{po}}_{\SPIN{\textpm}}$, and define
	\begin{equation}\label{e:Pi.with.embedded.T}
	\Pi^\SPIN{+}(T)
	\equiv\prod_{i=1}^{d^\SPIN{+}(T)}
	\bigg(1-u^\SPIN{+}_i(T)\bigg)\,,\quad
	\Pi^\SPIN{+}
	\equiv\prod_{i=d^\SPIN{+}(T)+1}^{d^\SPIN{+}(T)+d^\SPIN{+}}
	\bigg(1-u^\SPIN{+}_i\bigg)\,,\quad
	\Pi^{*\SPIN{+}}
	\equiv
	\Pi^\SPIN{+}(T)\Pi^\SPIN{+}\,.
	\end{equation}
Define similarly $\Pi^\SPIN{-}(T)$, $\Pi^\SPIN{-}$, and $\Pi^{*\SPIN{-}}=\Pi^\SPIN{-}(T)\Pi^\SPIN{-}$.
\item Substitute the $\Pi^{*\SPIN{\textpm}}$ into \eqref{e:eta.in.terms.of.signed.Pis} to define $\bm{\eta}$:
	\[
	\bigg(
	\bm{\eta}(\SPIN{+}),\bm{\eta}(\SPIN{-}),\bm{\eta}(\SPIN{f})
	\bigg)
	=
	\bigg(\frac{\Pi^{*\SPIN{-}}(1-\Pi^{*\SPIN{+}})}
		{ \Pi^{*\SPIN{+}} + \Pi^{*\SPIN{-}} 
			- \Pi^{*\SPIN{+}} \Pi^{*\SPIN{-}} },
	\frac{\Pi^{*\SPIN{+}}(1-\Pi^{*\SPIN{-}})}
		{ \Pi^{*\SPIN{+}} + \Pi^{*\SPIN{-}} 
			- \Pi^{*\SPIN{+}} \Pi^{*\SPIN{-}} },
	\frac{\Pi^{*\SPIN{+}}\Pi^{*\SPIN{-}}}
		{ \Pi^{*\SPIN{+}} + \Pi^{*\SPIN{-}} 
			- \Pi^{*\SPIN{+}} \Pi^{*\SPIN{-}} }
	\bigg)\,.
	\]
\end{enumerate}
The $\bm{\eta}$ that results from this construction can be regarded as a sample of $\mathbf{F}_\ell(\mathscr{T})$ for $\mathscr{T}\sim{\textup{\textsf{\footnotesize PGW}}}(T)$, although we did not explicitly generate all of $\mathscr{T}$. Moreover, if $\bm{\eta}'=\mathbf{F}_\ell(\mathscr{Q})$ where $\mathscr{Q}$ is any $\mathfrak{c}$-perturbation of $\mathscr{T}$, then $\bm{\eta}'$ can also be obtained from the above procedure by modifying at most $\mathfrak{c}$ of the messages from depth one.

For convenience we will let $\vec{\theta}$ denote the messages that are actually used in the definition of $\bm{\eta}$, so
	\[
	\theta^\SPIN{+}_{ij}
	\equiv\left\{
	\begin{array}{cl}
	\eta^\SPIN{+}_{ij}(T)
	&\textup{if }1\le i\le d^\SPIN{+}(T)
	\textup{ and }1\le j\le \mathfrak{c}^\SPIN{+}(i);\\
		\eta^\SPIN{+}_{ij}
	&\textup{otherwise,}
	\end{array}
	\right.
	\]
and similarly $\theta^\SPIN{-}_{ij}$. To bound the different between $\bm{\eta}$ and $\bm{\eta}'$,
we first assume a \emph{fixed} set of affected indices: without loss of generality, let $\vec{\vartheta}$ denote a new set of messages such that
	\[
	\bigg\{
	(i,j):\vartheta^\SPIN{\textpm}_{ij}\ne\theta^\SPIN{\textpm}_{ij}
	\bigg\}
	\subseteq
	\bigg\{
	(i,j):
	1\le i\le 2\mathfrak{c},
	1\le j\le 2\mathfrak{c}
	\bigg\}\,.
	\]
Returning to \eqref{e:Pi.with.embedded.T},
let $\Sigma^\SPIN{\textpm}(T)\equiv-\ln \Pi^\SPIN{\textpm}(T)$,
$\Sigma^\SPIN{\textpm}\equiv-\ln \Pi^\SPIN{\textpm}$,
and $\Sigma^{*\SPIN{\textpm}}\equiv -\ln\Pi^{*\SPIN{\textpm}}$.
Let $\Xi^\SPIN{\textpm}(T)$, $\Xi^\SPIN{\textpm}$, and $\Xi^{*\SPIN{\textpm}}$
be defined analogously as the $\Sigma$ quantities,
but with $\vec{\vartheta}$ in place of $\vec{\theta}$. 
It is then straightforward to check that
	\begin{align*}
	|\Xi^{*\SPIN{+}}
		-\Sigma^\SPIN{+}|
	&\le
	\sum_{i=1}^{d^\SPIN{+}(T)}
	-\ln\bigg( 1-\prod_{j=1}^{k-1} \vartheta^\SPIN{+}_{ij}\bigg)
	+\sum_{i=d^\SPIN{+}(T)+1}^{2\mathfrak{c}}
	\bigg| \ln \bigg( 1-\prod_{j=1}^{k-1} \vartheta^\SPIN{+}_{ij}\bigg)
		-\ln\bigg( 1-\prod_{j=1}^{k-1} \theta^\SPIN{+}_{ij}
		\bigg)\bigg|\\
	&\le\sum_{i=1}^{2\mathfrak{c}}\bigg[\underbrace{
	-\ln\bigg( 1-\prod_{j=2\mathfrak{c}+1}^{k-1} \theta^\SPIN{+}_{ij} \bigg)}_{\Delta^\SPIN{+}(i)}\bigg]
	\equiv \sum_{i=1}^{2\mathfrak{c}} \Delta^\SPIN{+}(i)\,.
	\end{align*}
By the same argument as for the estimate~\eqref{e:X.upper.tail.small} from the proof of Lemma~\ref{l:X.tail.bounds}, we have
	\[
	\mathbb{P}\bigg(
	|\Xi^{*\SPIN{+}}-\Sigma^\SPIN{+}|
	\ge\bigg(\frac{2^{1/20}}{2}\bigg)^k
	\bigg)
	\le 2\mathfrak{c}\cdot \mathbb{P}\bigg(
	|\Delta^\SPIN{+}(i)|
	\ge\bigg(\frac{2^{1/21}}{2}\bigg)^k
	\bigg)
	\le \frac1{\exp\{\Omega(k2^{k/4})\}}\,,
	\]
and the same bound applies for $|\Xi^{*\SPIN{-}}-\Sigma^\SPIN{-}|$. Now recall the bound~\eqref{e:simple.bound.on.Sigma} from the proof of Lemma~\ref{l:mu.ell.tail.bounds}, which says that the $\Sigma^\SPIN{\textpm}$ are well concentrated around $k\ln2$. 
In particular, it holds with probability at least 
$1-\exp(-\Omega(k2^{k/4}))$
that $|\Sigma^\SPIN{\textpm}-k\ln2| \le k/2^{11k/40}$
and $|\Xi^{*\SPIN{\textpm}}-\Sigma^\SPIN{\textpm}| \le (2^{1/20}/2)^k$,
in which case
	\begin{align*}
	\bm{\eta}'(\SPIN{\textpm})
	&= \frac{\exp(\Xi^{*\SPIN{\textpm}})-1}
		{\exp(\Xi^{*\SPIN{\textpm}})+\exp(\Xi^{*\SPIN{\textpm}})-1}
	= \frac{1 + O(k/2^{11k/40})}2\,,\\
	\bm{\eta}'(\SPIN{f})
	&=\frac1
		{\exp(\Xi^{*\SPIN{\textpm}})+\exp(\Xi^{*\SPIN{\textpm}})-1}
	=\frac{1 + O(k/2^{11k/40})}{2^{k+1}}\,.
	\end{align*}
Thus, given a \emph{fixed} choice of at most $\mathfrak{c}$ perturbed indices, it holds with probability at least $1-\exp(-\Omega(k2^{k/4}))$ that any resulting message $\bm{\eta}'$ satisfies the above estimates, regardless of how those $\mathfrak{c}$ indices are perturbed. To conclude, we note that by \eqref{e:poisson.chernoff.bound} the event $\textup{\textsf{\footnotesize DEG}}^+\equiv\{ \{ d^\SPIN{+},d^\SPIN{-} \} \ge 4^k/k \}$ has probability upper bounded by $\exp(-\Omega(4^k))$. On the complement of $\textup{\textsf{\footnotesize DEG}}^+$, the number of distinct choices for the $\mathfrak{c}$ perturbed indices is $\exp(O(k))$,
so we can take a union bound over all choices to obtain the result.\end{proof}

 Let $\mathscr{T}$ be a sample of ${\textup{\textbf{PGW}}}(T)$, rooted at variable $v\equiv v_\textup{\textsc{rt}}$. Write $\partial v(\SPIN{+})$ and $\partial v(\SPIN{-})$ for the clauses neighboring the root $v$ in $\mathscr{T}$, and let
	\[
	\textup{\textsf{\footnotesize DEG}}'
	\equiv
	\max\bigg\{
	\bigg| |\partial v(\SPIN{+})| - \frac{2^k k\ln2}{2}
	\bigg|,
	\bigg| |\partial v(\SPIN{-})| - \frac{2^k k\ln2}{2}
	\bigg|
	\bigg\} \ge k2^{5k/8}
	\]
It follows from \eqref{e:poisson.chernoff.bound}
that $\mathbb{P}(\textup{\textsf{\footnotesize DEG}}') \le \exp(-\Omega(k2^{k/4}))$.

Now, recalling Definition~\ref{d:J.robust}, we want to show that (with very good probability) any $\mathfrak{c}$-modification $\mathscr{Q}$ of $\mathscr{T}$ is nice in the sense of Definition~\ref{d:nice}. On the complement of the event $\textup{\textsf{\footnotesize DEG}}'$, it is clear that every $\mathfrak{c}$-modification $\mathscr{Q}$ of $\mathscr{T}$ will satisfy the degree condition \eqref{e:nice.degree.condition}. It remains to determine whether the canonical messages ${}_\star\hspace{-1pt}\dot{q}(\mathscr{Q})$ and ${}_\star\hspace{-1pt}\hat{q}(\mathscr{Q})$ satisfy the bounds \eqref{e:nice.var.message.cond} and \eqref{e:nice.clause.message.cond}.

To this end, let us fix $\mathscr{Q}$ momentarily,
and abbreviate $q\equiv{}_\star\hspace{-1pt}\dot{q}(\mathscr{Q})$ and $\hat{q}\equiv{}_\star\hspace{-1pt}\hat{q}(\mathscr{Q})$. Note that $q$ and $\hat{q}$ are based the $r$-neighborhood $\mathscr{Q}_r$ of the root $v$ in $\mathscr{Q}$; see Definition~\ref{d:canonical}. For any edge $(au)$ in $\mathscr{Q}$, let us abbreviate
	{\setlength{\jot}{0pt}\begin{align*}
	\bm{\eta}_{ua}
	\equiv \bm{\eta}(\mathscr{Q})_{ua}
	&\equiv \mathbf{F}_{\mathscr{Q}_r,ua}\,,\\
	\bm{\hat{u}}_{au} \equiv\bm{\hat{u}}(\mathscr{Q})_{au}
	& \equiv\mathbf{F}_{\mathscr{Q}_r,au}\,.
	\end{align*}}
Recall from \eqref{e:color.recursions.eta} the
correspondence between $(\dot{q},\hat{q})$ and $(\bm{\eta},\bm{\hat{u}})$
for edges $(av)$ incident to the root $v$:
	\begin{align}
	\label{e:vtoc.q.given.eta}
	\Big(q_{va}(\SSPIN{r}),q_{va}(\SSPIN{y}),
		q_{va}(\SSPIN{g}),q_{va}(\SSPIN{b})\Big)
	&=\bigg(
	\frac{\bm{\eta}_{va}(\SPIN{+})+\bm{\eta}_{va}(\SPIN{f})}
		{2-\bm{\eta}_{va}(\SPIN{-})},
	\frac{\bm{\eta}_{va}(\SPIN{-})}{2-\bm{\eta}_{va}(\SPIN{-})},
	\frac{\bm{\eta}_{va}(\SPIN{f})}{2-\bm{\eta}_{va}(\SPIN{-})},
	\frac{\bm{\eta}_{va}(\SPIN{+})}{2-\bm{\eta}_{va}(\SPIN{-})}
	\bigg)\,,\\
	\Big(\hat{q}_{av}(\SSPIN{r}),\hat{q}_{av}(\SSPIN{y}),
		\hat{q}_{av}(\SSPIN{g}),\hat{q}_{av}(\SSPIN{b})\Big)
	&=\bigg(
	\frac{\bm{\hat{u}}_{av}(\SPIN{+})}{3-2\bm{\hat{u}}_{av}(\SPIN{+})},
	\frac{\bm{\hat{u}}_{av}(\SPIN{f})}{3-2\bm{\hat{u}}_{av}(\SPIN{+})},
	\frac{\bm{\hat{u}}_{av}(\SPIN{f})}{3-2\bm{\hat{u}}_{av}(\SPIN{+})},
	\frac{\bm{\hat{u}}_{av}(\SPIN{f})}{3-2\bm{\hat{u}}_{av}(\SPIN{+})}
	\bigg)\,.
	\label{e:ctov.hq.given.bhu}
	\end{align}
Recall also from \S\ref{ss:wp.recursions} that $\bm{\hat{u}}_{av}$ can be recursively computed as (cf.\ \eqref{e:first.defn.of.bhu})
	\begin{equation}\label{e:clauses.in.terms.of.depth.one.vars}
	\Big(\bm{\hat{u}}_{av}(\SPIN{+}),
	\bm{\hat{u}}_{av}(\SPIN{f})\Big)
	=\bigg(
	\prod_{u\in (\mathscr{Q} \cap \partial a) \setminus v}
	\bm{\eta}_{ua}(\SPIN{-}),
	1-\prod_{u\in (\mathscr{Q} \cap \partial a) \setminus v}
	\bm{\eta}_{ua}(\SPIN{-})
	\bigg)\,.
	\end{equation}
In view of these relations, for $\mathscr{Q}$ to be nice, it suffices to have
	\begin{align}
	\label{e:final.bound.up.from.depth.one}
	\max\bigg\{
	\bigg|
	\bm{\eta}(\mathscr{Q})_{ua}(\SPIN{-})-\frac12\bigg|
	\,\bigg| \,
	\begin{array}{c}
	a\in\mathscr{Q} \cap \partial v,\\
	u\in\partial a\setminus v
	\end{array}
	\bigg\}&\le \frac1{2^{k/5}}\,,\\
	\label{e:final.bound.out.from.root}
	\max
	\bigg\{
	\sum_{x\in\set{\SPIN{+},\SPIN{-},\SPIN{f}}}
	\bigg|2^{k\Ind{x=\SPIN{f}}}
	\bm{\eta}(\mathscr{Q})_{va}(x)-\frac12\bigg|
	\,\bigg|\, a\in\mathscr{Q} \cap \partial v
	\bigg\}
	&\le \frac1{2^{k/5}}\,.
	\end{align}
Indeed, substituting
\eqref{e:final.bound.up.from.depth.one}
into \eqref{e:clauses.in.terms.of.depth.one.vars}
and \eqref{e:ctov.hq.given.bhu}
shows that $\hat{q}={}_\star\hspace{-1pt}\hat{q}(\mathscr{Q})$ satisfies condition
\eqref{e:nice.clause.message.cond};
while substituting
\eqref{e:final.bound.out.from.root}
into \eqref{e:vtoc.q.given.eta}
shows that $q={}_\star\hspace{-1pt}\dot{q}(\mathscr{Q})$ satisfies condition
\eqref{e:nice.var.message.cond}.

It remains to bound, on the event $\textup{\textsf{\footnotesize DEG}}'$, the probability for \eqref{e:final.bound.up.from.depth.one} and \eqref{e:final.bound.out.from.root} to hold for every $\mathfrak{c}$-modification $\mathscr{Q}$ of the original random tree $\mathscr{T}\sim{\textup{\textbf{PGW}}}(T)$. For any such $\mathscr{Q}$, for all $a\in\mathscr{Q}\cap\partial v$ and all $u\in\partial a\setminus v$, the subtree $\mathscr{Q}_{ua}$ is a $\mathfrak{c}$-perturbation of $\mathscr{T}_{ua}$, so Lemma~\ref{l:perturb.below.variables} applies. For all $a\in\mathscr{Q}\cap\partial v$, the subtree $\mathscr{Q}_{va}$ is a $\mathfrak{c}$-perturbation of $\mathscr{T}_{va}$, so Lemma~\ref{l:perturb.below.variables} again applies. It follows by a simple union bound that for $\mathscr{T}\sim{\textup{\textbf{PGW}}}(T)$, with probability lower bounded by $1-\exp(-\Omega(k2^{k/4}))$, every $\mathfrak{c}$-modification $\mathscr{Q}$ of $\mathscr{T}$ satisfies the degree condition \eqref{e:nice.degree.condition} and the message conditions \eqref{e:final.bound.up.from.depth.one} and \eqref{e:final.bound.out.from.root}, and hence is nice. This concludes the proof.

