\label{c:exp.minus.p.times.X}
Let $\mu$ be any probability measure over $\eta\in[0,1)$
that satisfies condition~\eqref{i:mu.ell.left.tail.bound} from Lemma~\ref{l:mu.ell.tail.bounds}. Write $\mu^{\otimes}$ for the law of a sequence $\smash{\vec{\eta}}'\equiv(\eta_j)_{j\ge1}$ of i.i.d.\ samples from $\mu$. If $p=2^{k\delta}$ for any $1/100\le\delta\le 1/9$, then
	\[\int\bigg(
	1-\prod_{j=1}^{k-1} \eta_j\bigg)^p
	\,d\mu^{\otimes}(\smash{\vec{\eta}}')
	\le \exp\bigg\{ -\frac{p}{2^{k-1}}\bigg[1-
	\frac{k^3}{2^{k/4}}
	\bigg]\bigg\}\,.\]

\begin{proof}
Write $\mathbb{P}$ and $\mathbb{E}$ for probability and expectation over the law of
	\[
	X
	\equiv -\ln \bigg(
	1-\prod_{j=1}^{k-1} \eta_j\bigg)\,.
	\]
The quantity of interest is then $\mathbb{E}(e^{-pX})$. 
Recall that Lemma~\ref{l:X.tail.bounds}\eqref{i:X.left.tail} gives
	\[
	\mathbb{P}\bigg(
	X \le \bigg( \frac{2^{-\xi}}{2}\bigg)^{k-1}
	\bigg)
	\le \frac1{\exp\{\Omega(\xi 2^{k/4})\}}
	\]
for all $k/2^{k/4} \le\xi\le1$. It follows that
	\begin{align*}
	\mathbb{E}(e^{-pX})
	&\le
	\exp\bigg\{
	-\frac{p}{2^{k-1}}
	\bigg[1 - \frac{k^2\ln k}{2^{k/4}}\bigg]
	\bigg\}
	+\mathbb{P}\bigg(
	X \le \frac1{2^{k-1}}\bigg[1 - \frac{k^2\ln k}{2^{k/4}}\bigg]
	\bigg)\\
	&\le \exp\bigg\{
	-\frac{p}{2^{k-1}}
	\bigg[1 - \frac{k^2\ln k}{2^{k/4}}\bigg]
	\bigg\} + \frac1{\exp\{\Omega(k\ln k )\}}
	\le
	\exp\bigg\{
	-\frac{p}{2^{k-1}}
	\bigg[1 - \frac{O(k^2\ln k)}{2^{k/4}}
		\bigg]
	\bigg\}\,,
	\end{align*}
and this implies the claim.
\end{proof}

