\label{l:d.to.p.times.theta.to.d}
Let $D$ be a 
$\textup{\textsf{Pois}}(\alpha k/2)$ random variable,
and let $\mathbb{E}$ denote expectation over the law of $D$.
If $p=2^{k\delta}$ for $1/100\le\delta\le 1/9$, then
	\[\mathbb{E}\bigg\{
	D^p
	\exp\bigg\{
	-\frac{Dp}{2^{k-1}}
	\bigg[
	1-\frac{k^3}{2^{k/4}}
	\bigg]
	\bigg\}
	\bigg\}
	\le \bigg(\frac{3k}{8}\bigg)^p\,.\]

\begin{proof}
The quantity of interest can be written as
$\mathbb{E}[D^p /e^{\gamma D}]$ for
	\[
	\gamma
	\equiv \frac{p}{2^{k-1}}\bigg[
	1-\frac{k^3}{2^{k/4}}
	\bigg]\,.
	\]
We can check by differentiation
that $d^p / e^{\gamma d}$ is
decreasing with respect to $d$ for all
	\[
	d > \frac{p}{\gamma}
	= 2^{k-1} \bigg/ \bigg[
	1-\frac{k^3}{2^{k/4}}
	\bigg]\,.\]
For all $\alpha$ in the regime
\eqref{e:alpha.regime}, the mean 
$\mathbb{E} D=\alpha k/2$ is much larger than $p/\gamma$.
As in \eqref{e:alpha.regime} let $\alpha_\textup{ubd}\equiv 2^k\ln2$.
Then
	\begin{align*}
	\mathbb{E}\bigg[ \frac{D^p}{\exp(\gamma D)}
	; D \ge \frac{k\alpha_\textup{ubd}}{2}
	\bigg]
	&\le 
	\bigg(\frac{k\alpha_\textup{ubd}}{2}\bigg)^p
	\exp\bigg\{-\frac{\gamma k\alpha_\textup{ubd}}{2}\bigg\}\\
	&= \bigg(
	\frac{k 2^k \ln2}{2}
	\exp\bigg\{ -k\ln2
		\bigg[1-\frac{k^3}{2^{k/4}}\bigg] \bigg\}
	\bigg)^p
	\le O(1) \bigg(
		\frac{k\ln2}{2}\bigg)^p\,.
	\end{align*}
On the other hand, we can use the Poisson moment-generating function to bound
	\begin{align*}
	\mathbb{E}\bigg[ \frac{D^p}{\exp(\gamma D)}
	; D \le \frac{k\alpha_\textup{ubd}}{2}
	\bigg]
	&\le
	\bigg(\frac{k\alpha_\textup{ubd}}{2}\bigg)^p
	\mathbb{E}\bigg[\frac1{ \exp(\gamma D)}\bigg]\\
	&=\bigg(\frac{k\alpha_\textup{ubd}}{2}\bigg)^p
	\exp\bigg\{- \frac{\alpha k}{2}
		\bigg(1-\frac1{e^\gamma}\bigg)\bigg\}
	\le 
	O(1) \bigg( \frac{k\ln2}{2}\bigg)^p\,.
	\end{align*}
Combining the bounds gives the claim.
\end{proof}

\label{l:d.to.p.times.rare.event}
Let $D$ be a $\textup{\textsf{Pois}}(\alpha k/2)$ random variable, and let $\bm{F}_i$ be events such that
whenever $D \ge \alpha k/4$, we have
$\mathbb{P}(\bm{F}_i \,|\, D ) \le \exp(-2^{k/4})$
for all $1\le i\le D$. If $p=2^{k\delta}$ for $1/100\le\delta\le 1/9$, then
	\[\mathbb{E}\bigg[
	D^{p-1}\sum_{i=1}^{D} \mathbf{1}_{\bm{F}_i}
	\bigg] \le
	\frac1{\exp(2^{k/5})}
	\,.\]

\begin{proof} It follows from the Poisson Chernoff bound
\eqref{e:poisson.chernoff.bound} that
	\[
	\mathbb{E}\bigg[
	D^{p-1}\sum_{i=1}^{D} \mathbf{1}_{\bm{F}_i}
	; D \le \frac{\alpha k}{4}
	\bigg]
	\le \bigg( \frac{\alpha k}{4}\bigg)^p
	\mathbb{P}\bigg(D \le \frac{\alpha k}{4}\bigg)
	\le \bigg( \frac{\alpha k}{4}\bigg)^p
	\frac1{\exp(\Omega(k 2^k) )}
	\le \frac1{\exp(\Omega(k 2^k) )}\,.
	\]
We can use integration by parts
and \eqref{e:poisson.chernoff.bound} to bound
	\begin{align*}
	\mathbb{E}\bigg(D^p ; D \ge3^k\bigg)
	&\le 3^{kp} \mathbb{P}(D\ge3^k)
	+ \int_{3^k}^\infty pt^{p-1} \mathbb{P}(D\ge t)\,dt
	\le \frac{3^{kp}}{\exp(\Omega(k3^k))}
	+ p \int_{3^k}^\infty 
	\frac{t^{p-1} }{\exp(\Omega(kt)) }
		\,dt\\
	&\le \frac{3^{kp}}{\exp(\Omega(k3^k))}
	+ \frac{p}{\exp(\Omega(k3^k))}
	\le \frac1{\exp(\Omega(k3^k))}\,,
	\end{align*}
so we have $\mathbb{E}(D^p) \le O(3^{kp})$. It follows from the assumption on the $\bm{F}_i$ that
	\[
	\mathbb{E}\bigg[
	D^{p-1}\sum_{i=1}^{D} \mathbf{1}_{\bm{F}_i}
	; D \ge \frac{\alpha k}{4}
	\bigg]
	\le \frac{\mathbb{E}(D^p)}{\exp(2^{k/4})}
	\le \frac1{\exp(\Omega(2^{k/4}))}\,,
	\]
which implies the claim.
\end{proof}

