\label{l:F.bounds.calculus}
Let $F$ be as defined by \eqref{e:def.F.x.y}. If $0\le x_i \le 1$ and $y_i\in\mathbb{R}$ with $x_i e^{y_i}\le1$, then
	\begin{align}\label{e:F.bdd.derivs}
	\bigg|F(x_1,y_1)-F(x_2,y_2)\bigg|
	&\le \Big|x_1-x_2\Big| + \Big|y_1-y_2\Big|\,,\\
	\label{e:F.second.derivs}
	\Bigg|F(x_1,y_1)-F(x_2,y_2)
	-\bigg\langle
	\nabla F(x_1,y_1),
	\begin{pmatrix}
	x_1-x_2\\
	y_1-y_2
	\end{pmatrix}
	\bigg\rangle\Bigg|
	&\le c\bigg\{
	(x_1-x_2)^2+(y_1-y_2)^2\bigg\}\,,
	\end{align}
where $c$ is an absolute constant.


\begin{proof}
Write $F_{xx},F_{xy},F_{yy}$ for the second-order partial derivatives of $F$. It is straightforward to verify that for $0\le x\le 1$ and all $y\in\mathbb{R}$ we have
$|F_y|\le1$ and $|F_{yy}|\le1$. Further, under the additional restriction that $xe^y\le1$, we have
$|F_x|\le1$, $|F_{xx}|\le2$, and $|F_{xy}|\le1$. The bounds \eqref{e:F.bdd.derivs} and \eqref{e:F.second.derivs} directly follow. 
\end{proof}

\label{l:F.diff.ratio.bound}
Let $F$ be as defined by \eqref{e:def.F.x.y}. For any $0\le x_i\le1$ and $y_i\in\mathbb{R}$,
	\begin{equation}\label{e:F.ratios.bd}
	\bigg|\frac{F(x_1,y_1)-F(x_2,y_2)}
	{F(x_1,y_1)+F(x_2,y_2)}\bigg|
	\le \frac{|x_1-x_2|}{2-x_1-x_2}
		+ \frac{|y_1-y_2|}{2}\,.\end{equation}
(Unlike Lemma~\ref{l:F.bounds.calculus}, this does not require $x_i e^{y_i}\le1$.)

\begin{proof} Note that the function $G(z)\equiv z/(1+z)$ satisfies
	\begin{equation}\label{e:G.diff.ratio}
	\frac{|G(w)-G(z)|}{G(w)+G(z)}
	=\frac{|w-z|}{w+z+2wz}
	\le\frac{|w-z|}{w+z}
	\end{equation}
for any $w,z\ge0$. It follows from \eqref{e:G.diff.ratio} that for any $0\le x_i\le1$ and any fixed $y\in\mathbb{R}$,
	\begin{equation}\label{e:F.ratio.diff.fixed.y}
	\frac{|F(x_2,y)-F(x_1,y)|}
		{F(x_2,y)+F(x_1,y)}
	=
	\frac{|G((1-x_2)e^y)-G((1-x_1)e^y)|}
		{G((1-x_2)e^y)+G((1-x_1)e^y)}
	\le \frac{|x_2-x_1|}{2-x_1-x_2}\,.\end{equation}
A further consequence of 
\eqref{e:G.diff.ratio} is that for any $w,z\in\mathbb{R}$,
	\[\frac{|G(e^w)-G(e^z)|}{G(e^w)+G(e^z)}
	\le
	\frac{|e^w-e^z|}{e^w+e^z}
	=\textup{th}\bigg(\frac{|w-z|}{2}\bigg)
	\le \frac{|w-z|}{2}\,.
	\]
It follows from this that for any fixed
$0\le x\le 1$ and any $y_i\in\mathbb{R}$,
	\begin{equation}\label{e:F.ratio.diff.fixed.x}
	\frac{|F(x,y_1)-F(x,y_2)|}{F(x,y_1)+F(x,y_2)}
	= \frac{|G((1-x)e^{y_2})-G((1-x)e^{y_1})|}
		{G((1-x)e^{y_2})+G((1-x)e^{y_1})}
	\le \frac{|y_1-y_2|}2\,.\end{equation}
Combining \eqref{e:F.ratio.diff.fixed.y}~and~\eqref{e:F.ratio.diff.fixed.x} gives the claim.
\end{proof}

 Note that the function $G(z)\equiv z/(1+z)$ satisfies
	\begin{equation}\label{e:G.diff.ratio}
	\frac{|G(w)-G(z)|}{G(w)+G(z)}
	=\frac{|w-z|}{w+z+2wz}
	\le\frac{|w-z|}{w+z}
	\end{equation}
for any $w,z\ge0$. It follows from \eqref{e:G.diff.ratio} that for any $0\le x_i\le1$ and any fixed $y\in\mathbb{R}$,
	\begin{equation}\label{e:F.ratio.diff.fixed.y}
	\frac{|F(x_2,y)-F(x_1,y)|}
		{F(x_2,y)+F(x_1,y)}
	=
	\frac{|G((1-x_2)e^y)-G((1-x_1)e^y)|}
		{G((1-x_2)e^y)+G((1-x_1)e^y)}
	\le \frac{|x_2-x_1|}{2-x_1-x_2}\,.\end{equation}
A further consequence of 
\eqref{e:G.diff.ratio} is that for any $w,z\in\mathbb{R}$,
	\[\frac{|G(e^w)-G(e^z)|}{G(e^w)+G(e^z)}
	\le
	\frac{|e^w-e^z|}{e^w+e^z}
	=\textup{th}\bigg(\frac{|w-z|}{2}\bigg)
	\le \frac{|w-z|}{2}\,.
	\]
It follows from this that for any fixed
$0\le x\le 1$ and any $y_i\in\mathbb{R}$,
	\begin{equation}\label{e:F.ratio.diff.fixed.x}
	\frac{|F(x,y_1)-F(x,y_2)|}{F(x,y_1)+F(x,y_2)}
	= \frac{|G((1-x)e^{y_2})-G((1-x)e^{y_1})|}
		{G((1-x)e^{y_2})+G((1-x)e^{y_1})}
	\le \frac{|y_1-y_2|}2\,.\end{equation}
Combining \eqref{e:F.ratio.diff.fixed.y}~and~\eqref{e:F.ratio.diff.fixed.x} gives the claim.

\label{l:ratio.a.b.bound}
For any positive numbers $a_j$ and $b_j$,
	\begin{equation}\label{e:ratio.a.b.bound}
	\bigg|\frac{\prod_{j=1}^k a_j-\prod_{j=1}^k b_j}
	{\prod_{j=1}^k a_j+\prod_{j=1}^k b_j}
	\bigg|
	\le \sum_{\varnothing\subsetneq J\subseteq [k]}
		2^{|J|}
		\prod_{j\in J}
		\bigg|\frac{a_j-b_j}{a_j + b_j}\bigg|\,.
	\end{equation}

\begin{proof}
Partition the indices $[k]\equiv\set{1,\ldots,k}$
into $A\equiv\set{j : a_j \ge b_j}$
and $B\equiv[k]\setminus A$. Write $\delta\equiv a-b$. Then
	\begin{align*}
	N
	&\equiv \prod_{j=1}^k a_j-\prod_{j=1}^k b_j
	= \prod_{j\in A} (b_j+\delta_j)\prod_{j\in B} a_j
	 -\prod_{j\in B} (a_j-\delta_j) \prod_{j\in A} b_j\\
	&=\sum_{\varnothing\subsetneq J\subseteq A}
		\prod_{j\in J} \delta_j
		\prod_{j\in A\setminus J} b_j
		\prod_{j\in B} a_j
	-\sum_{\varnothing\subsetneq J\subseteq B}
		\prod_{j\in J} (-\delta_j)
		\prod_{j\in B\setminus J} a_j
		\prod_{j\in A} b_j\,.
	\end{align*}
It follows using the definition of $A$ and $B$ that
	\[
	|N|
	\le
	\sum_{\substack{\varnothing\subsetneq J\subseteq [k],\\
		J\subseteq A\textup{ or }J\subseteq B
		}}
		\prod_{j\in J} |\delta_j|
		\prod_{j\in[k]\setminus J} \min\set{a_j,b_j}\,,
	\]
On the other hand, for any $J\subseteq A$, we have
	\[
	D\equiv
	\prod_{j=1}^k a_j + \prod_{j=1}^k b_j
	\ge \prod_{j=1}^k a_j
	\ge \prod_{j\in J} \max\set{a_j,b_j}
	\prod_{j\in [k]\setminus J} \min\set{a_j,b_j}
	\ge
	\prod_{j\in J} \frac{a_j+b_j}{2}
	\prod_{j\in [k]\setminus J} \min\set{a_j,b_j}\,,
	\]
and the same bound holds for any $J\subseteq B$. Combining the last two bounds gives
	\[
	\frac{|N|}{D}
	\le
	\sum_{\substack{\varnothing\subsetneq J\subseteq [k],\\
		J\subseteq A\textup{ or }J\subseteq B
		}} \prod_{j\in J} 
		\frac{2|\delta_j|}{a_j+b_j}\,,
	\]
which implies the claim.
\end{proof}

\begin{equation}\label{e:ratio.a.b.bound}
	\bigg|\frac{\prod_{j=1}^k a_j-\prod_{j=1}^k b_j}
	{\prod_{j=1}^k a_j+\prod_{j=1}^k b_j}
	\bigg|
	\le \sum_{\varnothing\subsetneq J\subseteq [k]}
		2^{|J|}
		\prod_{j\in J}
		\bigg|\frac{a_j-b_j}{a_j + b_j}\bigg|\,.
