 \label{l:stability}
Write $\mathbb{P}_\epsilon$ for the law of the random sequence defined by \eqref{e:coupling.eta.with.eps.param}, and write $\mathbb{E}_\epsilon$ for expectation with respect to $\mathbb{P}_\epsilon$. Let $\eta^\ell\equiv\bm{\eta}^\ell(\SPIN{-})$. For $p= 2 \lceil 2^{k/10}\rceil$ we have the bound
	\[\mathbb{E}_\epsilon\Bigg[\bigg|
	\frac{\eta^{\ell+1}-\eta^\ell}{\eta^{\ell+1}+\eta^\ell}
	\bigg|^p\Bigg]
	\le
	\frac1{2^{kp/7} 2^{2kp\ell/5}}
	\le
	\frac1{2^{kp(\ell+1)/7}}\]
for all $\ell\ge0$. This holds for any $0\le\epsilon\le1$.


\begin{proof} We will prove the bound by induction, starting from the base case $\ell=0$:
by definition, we have $\eta^0=1/2$ (with probability one), and so
Corollary~\ref{c:stability.base.case} gives
	\[\mathbb{E}_\epsilon\bigg[\bigg|
	\frac{\eta^1-\eta^0}{\eta^1+\eta^0}
	\bigg|^p\bigg]
	=\mathbb{E}_\epsilon\bigg[\bigg|
	\frac{\eta^1-1/2}{\eta^1+1/2}
	\bigg|^p\bigg]
	\le \frac1{2^{kp/7}}\,.
	\]
Now suppose inductively that for some $\ell\ge1$ we have
	\begin{equation}\label{e:stability.inductive}
	\mathbb{E}_\epsilon\bigg[
	\bigg|\frac{\eta^\ell-\eta^{\ell-1}}{2}\bigg|^p
	\bigg]
	\le\mathbb{E}_\epsilon\bigg[\bigg|
	\frac{\eta^\ell-\eta^{\ell-1}}{\eta^\ell+\eta^{\ell-1}}
	\bigg|^p\bigg]
	\le
	I(\ell)^p
	\equiv
	\frac1{2^{kp/7} 2^{2kp\ell/5}}
	\,.\end{equation}
Let $A\equiv(H,h)$ denote a random variable with the same law as the pair $(\eta^\ell,\eta^{\ell-1})$. Let
	\[
	\vec{A}
	\equiv\Bigg( 
	A_j \equiv \begin{pmatrix}
		H_j \\ h_j
		\end{pmatrix},
	A^\SPIN{+}_{ij} \equiv \begin{pmatrix}
		H^\SPIN{+}_{ij} \\ h^\SPIN{+}_{ij}
		\end{pmatrix},
	A^\SPIN{-}_{ij}
		\equiv \begin{pmatrix}
		H^\SPIN{-}_{ij} \\ h^\SPIN{-}_{ij}
		\end{pmatrix}\Bigg)_{i,j\ge1}
	\]
be an array of i.i.d.\ copies of $A$. Let
$K$ denote a random variable which takes value $k$ with chance $1-\epsilon$, and takes value $k-1$ with chance $\epsilon$. Let $\vec{K} \equiv (K^\SPIN{+}_{ij},K^\SPIN{-}_{ij})_{i,j\ge1}$ be an array of i.i.d.\ copies of $K$, and let
	\[
	S^\SPIN{\textpm}_i
	\equiv 1-\prod_{j=1}^{K^\SPIN{\textpm}_i-1} H^\SPIN{\textpm}_{ij}
	\,,\quad
	s^\SPIN{\textpm}_i
	\equiv 1-\prod_{j=1}^{K^\SPIN{\textpm}_i-1} h^\SPIN{\textpm}_{ij}.
	\]
Note that by construction the $H$ and $h$ random variables lie in $[0,1)$ almost surely, so the $S$ and $s$ random variables lie in $(0,1]$ almost surely. Let $\smash{\vec{d}}\equiv(d^\SPIN{+},d^\SPIN{-})\sim\textup{\textsf{po}}_{\SPIN{\textpm}}$, and use this to define the random variables
	\begin{equation}\label{e:stability.notations}
	\Pi^\SPIN{\textpm}
	\equiv \prod_{i=1}^{d^\SPIN{\textpm}} S^\SPIN{\textpm}_i\,,\quad
	\pi^\SPIN{\textpm}
	\equiv \prod_{i=1}^{d^\SPIN{\textpm}} s^\SPIN{\textpm}_i\,,\quad
	\Sigma
	\equiv\ln \frac{\Pi^\SPIN{+}}{\Pi^\SPIN{-}}\,,\quad
	\sigma
	\equiv\ln \frac{\pi^\SPIN{+}}{\pi^\SPIN{-}}\,.\end{equation}
For the remainder of the proof we will abbreviate
$S_i\equiv S^\SPIN{-}_i$,
$s_i\equiv s^\SPIN{-}_i$,
$\Pi \equiv \Pi^\SPIN{-}$, $\pi\equiv \pi^\SPIN{-}$. 
With this notation, the pair $(\eta^{\ell+1},\eta^\ell)$ is equidistributed as
	\[\bigg(
	\frac{(1-\Pi)\exp(\Sigma)}{1+(1-\Pi)\exp(\Sigma)},
	\frac{(1-\pi)\exp(\sigma)}{1+(1-\pi)\exp(\sigma)}
	\bigg)
	=\bigg( F(\Pi,\Sigma),F(\pi,\sigma)\bigg)
	\,,
	\]
for $F$ as defined by \eqref{e:def.F.x.y}. To prove the result, it suffices to bound $\mathbb{E}(J^p)$ for
	\[
	J^p
	\equiv 
	\bigg|
	\frac{ F(\Pi,\Sigma)-F(\pi,\sigma)}
		{ F(\Pi,\Sigma)+F(\pi,\sigma)}\bigg|^p
	\le\bigg(\frac{2|\Pi-\pi|}{2-\Pi-\pi}\bigg)^p
	 + |\Sigma-\sigma|^p\,,\]
where the last bound follows by Lemma~\ref{l:F.diff.ratio.bound}.
Since each of $\Pi,\pi$ is a product over $d^\SPIN{-}$ terms, we can decompose their difference as a telescoping product:
	\[
	\Pi-\pi
	=\prod_{i=1}^{d^\SPIN{-}} S_i
	-\prod_{i=1}^{d^\SPIN{-}} s_i
	=\sum_{i=1}^{d^\SPIN{-}} 
		\Pi[i]
		(S_i-s_i)\,,\quad
	\Pi[i]\equiv
		\prod_{j=1}^{i-1} S_j
		\prod_{j=i+1}^{d^\SPIN{-}} s_j\,.
	\]
It follows from H\"older's inequality that
for any $\mathbf{u}\in\mathbb{R}^d$,
$|(\mathbf{1},\mathbf{u})|^p
\le d^{p-1} (\|\mathbf{u}\|_p)^p$. This implies
	\begin{equation}\label{e:diff.Pi.telescope}
	|\Pi-\pi|^p
	\le
	(d^\SPIN{-})^{p-1}
	\sum_{i=1}^{d^\SPIN{-}}
	\Pi[i]^p |S_i-s_i|^p\,.
	\end{equation}
Note that $0\le \Pi,\pi\le1$, and $\Pi\pi \le \Pi[i]$ for any $i$. Let $\bm{F}_i$ be the event that $\Pi[i]\ge 1/4$.
If $\bm{F}_i$ does not occur, then we must have
either $\Pi\le1/2$ or $\Pi\le1/2$, therefore $2-\Pi-\pi \ge 1/2$. It follows that
	\begin{equation}\label{e:stability.decomp}
	J^p\le
	\underbrace{\Bigg[
	4^p (d^\SPIN{-})^{p-1}
	\sum_{i=1}^{d^\SPIN{-}}
	\Pi[i]^p |S_i-s_i|^p\Bigg] }_{J_1(p)}
	+\underbrace{\Bigg[ 2^p (d^\SPIN{-})^{p-1}
	\sum_{i=1}^{d^\SPIN{-}}
	\mathbf{1}_{\bm{F}_i}
	\frac{\Pi[i]^p |S_i-s_i|^p}{(2-\Pi-\pi)^p}
	\Bigg]}_{J_2(p)}
	+|\Sigma-\sigma|^p\,.\end{equation}
Similarly to \eqref{e:diff.Pi.telescope}, we can expand $S-s \equiv S_i-s_i$ as a telescoping sum, then use H\"older's inequality to bound
	\begin{equation}\label{e:telescope.def.U.j}
	|S-s|^p
	=\bigg|
	\prod_{j=1}^{K-1} H_j
	-\prod_{j=1}^{K-1} h_j
	\bigg|^p
	\le k^{p-1}
	\sum_{j=1}^{K-1} U[j]^p
		|H_j-h_j|^p\,,\quad
		U[j]\equiv \prod_{t=1}^{j-1} H_t
		\prod_{t=j+1}^{K-1} h_t\,.
	\end{equation}
It follows by considerations of conditional independence that
	\[
	\mathbb{E} J_1(p)
	\le (4k)^p
	\mathbb{E}\bigg[ (d^\SPIN{-})^p
	(\max\set{\mathbb{E}(S^p),\mathbb{E}(s^p)})^{d^\SPIN{-}-1}\bigg]
	\bigg(\max\set{ \mathbb{E}(H^p),\mathbb{E}(h^p)}\bigg)^{k-3}
	\mathbb{E}(|H-h|^p)\,.
	\]
Both $\mathbb{E}(S^p)$ and $\mathbb{E}(s^p)$ satisfy the bound from Corollary~\ref{c:exp.minus.p.times.X}; and combining with Lemma~\ref{l:d.to.p.times.theta.to.d} gives a bound on the first expectation on the right-hand side above. Both $\mathbb{E}(H^p)$ and $\mathbb{E}(h^p)$ satisfy the bound from Corollary~\ref{c:pth.moment.of.eta}. The last factor
$\mathbb{E}(|H-h|^p)$ is bounded by
the inductive hypothesis \eqref{e:stability.inductive}. Altogether it gives
	\begin{equation}\label{e:stability.first.finalbound}
	\mathbb{E} J_1(p)
	\le O(1) (4k)^p
	\bigg(\frac{3k}{8}\bigg)^p
	\frac{\mathbb{E} (|H-h|^p)}{2^{p(k-3)}}
	\le
	\bigg( \frac{k^3}{2^k}\bigg)^p
	\frac1{2^{kp/7} 2^{2kp\ell/5}} 
	=\bigg( \frac{k^3 I(\ell)}{2^k} \bigg)^p
	\,.\end{equation}
Turning to $J_2(p)$, we note that (very crudely) we have
$0\le \Pi[i]\le1$ and $2-\Pi-\pi \ge 2-S_i-s_i$
for any $1\le i\le d^\SPIN{-}$. Therefore, again with considerations of conditional independence, we have
	\begin{equation}\label{e:J.2.p}
	\mathbb{E} J_2(p)
	\le 2^p
	\mathbb{E}\bigg[
	(d^\SPIN{-})^{p-1}
	\sum_{i=1}^{d^\SPIN{-}} \mathbf{1}_{\bm{F}_i}
	\bigg]
	\mathbb{E}\bigg[ \bigg|\frac{S-s}{2-S-s}\bigg|^p\bigg]
	\,.\end{equation}
Recall that $\bm{F}_i$ is the event that $\Pi[i]\ge1/4$, or equivalently that
	\[
	\Sigma[i]
	\equiv \ln\frac1{\Pi[i]}
	= \sum_{j=1}^{i-1} \ln \frac1{S_i}
		+\sum_{j=i+1}^{d^\SPIN{-}} \ln \frac1{s_i}
	\le \ln 4\,.
	\]
By essentially the same argument as for
\eqref{e:left.tail.Sigma}, as long as $d^\SPIN{-}\ge \alpha k/4$ we have $\mathbb{P}(\bm{F}_i\,|\,d^\SPIN{-})\le \exp(-\Omega(k2^{k/4}))$. We can then apply Lemma~\ref{l:d.to.p.times.rare.event} to bound the first expectation in \eqref{e:J.2.p}:
	\begin{equation}\label{e:stability.rare.event.bnd}
	\mathbb{E}\bigg[
	(d^\SPIN{-})^{p-1}
	\sum_{i=1}^{d^\SPIN{-}} \mathbf{1}_{\bm{F}_i}
	\bigg]
	\le \frac1{\exp(2^{k/5})}\,.
	\end{equation}
For the second expectation
in \eqref{e:J.2.p}, Lemma~\ref{l:ratio.a.b.bound} gives
	\[
	\mathbb{E}\bigg[ \bigg|\frac{S-s}{2-S-s}\bigg|^p\bigg]
	=
	\mathbb{E}\Bigg[ \Bigg|
	\frac{\prod_{j=1}^{K-1} H_j-\prod_{j=1}^{K-1} h_j}
		{\prod_{j=1}^{K-1} H_j+\prod_{j=1}^{K-1} h_j}
	\Bigg|^p\Bigg]
	\le
	\mathbb{E} \Bigg[\bigg(
	\sum_{\varnothing \subsetneq J\subseteq [k-1]}
	2^{|J|}
	\prod_{j\in J} 
	\bigg|\frac{H_j-h_j}{H_j+h_j}\bigg|\bigg)^p
	\Bigg]\,.
	\]
Let $\vec{J}\equiv(J_1,\ldots,J_p)$ denote any $p$-tuple of nonempty subsets of $[k-1]$. We abbreviate
$|\vec{J}| \equiv |J_1| + \ldots + |J_p| \ge p$.
For any $j\in[k-1]$, let
$n_j(\vec{J})$ denote the number of occurrences of $j$ in the sets $J_1,\ldots,J_p$:
	\[
	n_j(\vec{J})
	=\sum_{t=1}^p
	\Ind{j \in J_t}\,,\quad
	\sum_{j=1}^{k-1} n_j(\vec{J})
	= \sum_{t=1}^p |J_t| = |\vec{J}| \ge p\,.
	\]
With this notation, we can bound
	\[
	\mathbb{E}\bigg[ \bigg|\frac{S-s}{2-S-s}\bigg|^p\bigg]
	\le\sum_{\vec{J}}
	2^{|\vec{J}|}
	\prod_{j=1}^{k-1}
	\mathbb{E}\Bigg[
	\bigg|\frac{H_j-h_j}{H_j+h_j}\bigg|^{n_j(\vec{J})} \Bigg]
	\le
	\sum_{\vec{J}}
	2^{|\vec{J}|}
	\mathbb{E}\Bigg[
	\bigg|\frac{H-h}{H+h}\bigg|^p \Bigg]^{|\vec{J}|/p}\,,
	\]
where the last step is by Jensen's inequality. The number of choices of $\vec{J}\equiv(J_1,\ldots,J_p)$ with $|\vec{J}|=b$ is upper bounded by $k^b$. Combining with the inductive hypothesis \eqref{e:stability.inductive} gives
	\[\mathbb{E}\bigg[ \bigg|\frac{S-s}{2-S-s}\bigg|^p\bigg]
	\le
	\sum_{b\ge p}
	\Bigg( 2k
	\mathbb{E}\Bigg[
	\bigg|\frac{H-h}{H+h}\bigg|^p \Bigg]^{1/p}
	\Bigg)^b
	\le
	\sum_{b\ge p}
	\Bigg( \frac{2k}{2^{k/7} 2^{2k\ell/5}} \Bigg)^b
	\le \frac{k^{2p}}{ 2^{kp/7} 2^{2kp\ell/5} }\,.
	\]
Substituting this and \eqref{e:stability.rare.event.bnd}
into \eqref{e:J.2.p} gives
	\begin{equation}\label{e:stability.second.finalbound}
	\mathbb{E} J_2(p) \le
	\frac{k^{2p}}{\exp(2^{k/5})}
	\frac1{ 2^{kp/7} 2^{2kp\ell/5} }
	\le
	\bigg( \frac{k^2 I(\ell)}{\exp(2^{k/10})} \bigg)^p
	\,.\end{equation}
Finally we bound $\mathbb{E}(|\Sigma-\sigma|^p)$, where we recall from \eqref{e:stability.notations} that
	\[
	\Sigma
	=\ln \frac{\Pi^\SPIN{+}}{\Pi^\SPIN{-}}
	= \sum_{i=1}^{d^\SPIN{+}}\ln S^\SPIN{+}_i
	-\sum_{i=1}^{d^\SPIN{-}}\ln S^\SPIN{-}_i\,,
	\]
and similarly $\sigma=\ln(\pi^\SPIN{+}/\pi^\SPIN{-})$. Let $D\sim\textup{\textsf{Pois}}(\alpha k)$, and let $(\mathfrak{s}_i)_{i\ge1}$ be a sequence of i.i.d.\ symmetric random signs. Then, recalling that $p$ is an even integer, we have
	\begin{equation}\label{e:diff.Sigma.sigma.pth.mmt}
	\mathbb{E}(|\Sigma-\sigma|^p)
	= \mathbb{E}\Bigg[ \bigg(\sum_{i=1}^D
	\mathfrak{s}_i
	(\ln S_i-\ln s_i)
	\bigg)^p\Bigg]
	\le O(1) \bigg( \frac{dp}{e} \bigg)^{p/2}
		\mathbb{E}\bigg[\bigg|\ln \frac{S}{s}\bigg|^p\bigg]\,,
	\end{equation}
where the last step uses Lemma~\ref{l:wk.rademacher.bound}.
We then use a telescoping sum to bound
	\begin{equation}\label{e:telescoping.sum.u.h}
	\bigg|\ln \frac{S}{s}\bigg|
	=\bigg|
	\ln \frac{1-\prod_{j=1}^{K-1} H_j}
		{1-\prod_{j=1}^{K-1} h_j}
	\bigg|
	\le \sum_{j=1}^{K-1}
	\bigg|\ln
		\frac{1-U[j] H_j}
		{1-U[j] h_j}\bigg|
	\le
	\sum_{j=1}^{K-1}
	\frac{U[j]}{1-U[j]}
	\cdot
	|H_j-h_j|\,,
	\end{equation}
where the last step uses that the function $f_U(h)=\ln(1-Uh)$ has $|(f_U)'(h)| \le U/(1-U)$ for all $U,h\in[0,1]$. In the last expression above, we can further replace $U[j]$ (defined by \eqref{e:telescope.def.U.j}) with
	\[U_\circ[j]
	\equiv \prod_{t=1}^{j-1} H_t
		\prod_{t=j+1}^{k-2} h_t
	\ge U[j]\,.
	\]
It follows by H\"older's inequality, combined with the Cauchy-Schwarz inequality, that
	\begin{equation}\label{e:diff.log.S.log.s}
	\mathbb{E}\bigg[\bigg|\ln \frac{S}{s}\bigg|^p\bigg]
	\le k^p
	\bigg(\max\set{\mathbb{E}(H^{2p}),\mathbb{E}(h^{2p})}\bigg)^{(k-3)/2}
	\max_{j\le k-2}
	\mathbb{E}\bigg[\bigg(\frac{1}{1-U_\circ[j]}\bigg)^{2p}\bigg]^{1/2}
	\mathbb{E}(|H-h|^p)
	\end{equation}
For $x\ge 3$, we have
$\ln x + \ln(1-1/x) \ge (\ln x)/2$. It follows that
	\begin{align*}
	\mathbb{P}\bigg(\frac{1}{1-U_\circ[j]}\ge x\bigg)
	&=\mathbb{P}\bigg(U_\circ[j] \ge 1-\frac1x\bigg)
	\le\max\bigg\{
	\mathbb{P}\bigg(H\ge 1-\frac1x\bigg),
	\mathbb{P}\bigg(h\ge 1-\frac1x\bigg)\bigg\}^{k-3}\\
	&\le\max\bigg\{
	\mathbb{P}\bigg( \ln\frac{H}{1-H} \ge \frac{\ln x}2 \bigg),
	\mathbb{P}\bigg( \ln\frac{h}{1-h} \ge \frac{\ln x}2 \bigg)
	\bigg\}^{k-3}
	\le \frac1{\exp( k(\ln x) 2^{k/4})}\,,\end{align*}
where the last bound is by \eqref{i:mu.ell.upper.tail.bound} 
from Lemma~\ref{l:mu.ell.tail.bounds}. Integrating this bound gives
	\[\mathbb{E}\Bigg[\bigg(\frac{1}{1-U_\circ[j]}\bigg)^{2p}\Bigg]
	\le(3/2) \cdot 3^{2p}
		+ \int_3^\infty \frac{pt^{p-1}}{t^{k2^{k/4}}}\,dt
	\le 2 \cdot 3^{2p}\,.
	\]
The other factors in \eqref{e:diff.log.S.log.s}
are controlled by Corollary~\ref{c:pth.moment.of.eta} and \eqref{e:stability.inductive}. Substituting into
\eqref{e:diff.Sigma.sigma.pth.mmt} gives
	\begin{equation}\label{e:diff.Sigma.sigma.finalbound}
	\mathbb{E}|\Sigma-\sigma|^p
	\le
	O(1) \bigg( \frac{dp}{e} \bigg)^{p/2}
	\frac{k^{2p}}{2^{kp}}
	\frac1{2^{kp/7} 2^{2kp\ell/5}} 
	\le
	\bigg( \frac{k^2 I(\ell)}{2^{9k/20}} \bigg)^p
	\,.\end{equation}
Substituting
\eqref{e:stability.first.finalbound}, \eqref{e:stability.second.finalbound}, and \eqref{e:diff.Sigma.sigma.finalbound}
into \eqref{e:stability.decomp} gives
	\[
	\mathbb{E} \Bigg[
	\bigg|\frac{\eta^{\ell+1}-\eta^\ell}
		{\eta^{\ell+1}+\eta^\ell}\bigg|^p
		\Bigg]
	= \mathbb{E}(J^p) \le O(1) 
	\bigg( \frac{k^2 I(\ell)}{2^{9k/20}} \bigg)^p\,,
	\]
which verifies the induction \eqref{e:stability.inductive} and proves the result.
\end{proof}

 We will prove the bound by induction, starting from the base case $\ell=0$:
by definition, we have $\eta^0=1/2$ (with probability one), and so
Corollary~\ref{c:stability.base.case} gives
	\[\mathbb{E}_\epsilon\bigg[\bigg|
	\frac{\eta^1-\eta^0}{\eta^1+\eta^0}
	\bigg|^p\bigg]
	=\mathbb{E}_\epsilon\bigg[\bigg|
	\frac{\eta^1-1/2}{\eta^1+1/2}
	\bigg|^p\bigg]
	\le \frac1{2^{kp/7}}\,.
	\]
Now suppose inductively that for some $\ell\ge1$ we have
	\begin{equation}\label{e:stability.inductive}
	\mathbb{E}_\epsilon\bigg[
	\bigg|\frac{\eta^\ell-\eta^{\ell-1}}{2}\bigg|^p
	\bigg]
	\le\mathbb{E}_\epsilon\bigg[\bigg|
	\frac{\eta^\ell-\eta^{\ell-1}}{\eta^\ell+\eta^{\ell-1}}
	\bigg|^p\bigg]
	\le
	I(\ell)^p
	\equiv
	\frac1{2^{kp/7} 2^{2kp\ell/5}}
	\,.\end{equation}
Let $A\equiv(H,h)$ denote a random variable with the same law as the pair $(\eta^\ell,\eta^{\ell-1})$. Let
	\[
	\vec{A}
	\equiv\Bigg( 
	A_j \equiv \begin{pmatrix}
		H_j \\ h_j
		\end{pmatrix},
	A^\SPIN{+}_{ij} \equiv \begin{pmatrix}
		H^\SPIN{+}_{ij} \\ h^\SPIN{+}_{ij}
		\end{pmatrix},
	A^\SPIN{-}_{ij}
		\equiv \begin{pmatrix}
		H^\SPIN{-}_{ij} \\ h^\SPIN{-}_{ij}
		\end{pmatrix}\Bigg)_{i,j\ge1}
	\]
be an array of i.i.d.\ copies of $A$. Let
$K$ denote a random variable which takes value $k$ with chance $1-\epsilon$, and takes value $k-1$ with chance $\epsilon$. Let $\vec{K} \equiv (K^\SPIN{+}_{ij},K^\SPIN{-}_{ij})_{i,j\ge1}$ be an array of i.i.d.\ copies of $K$, and let
	\[
	S^\SPIN{\textpm}_i
	\equiv 1-\prod_{j=1}^{K^\SPIN{\textpm}_i-1} H^\SPIN{\textpm}_{ij}
	\,,\quad
	s^\SPIN{\textpm}_i
	\equiv 1-\prod_{j=1}^{K^\SPIN{\textpm}_i-1} h^\SPIN{\textpm}_{ij}.
	\]
Note that by construction the $H$ and $h$ random variables lie in $[0,1)$ almost surely, so the $S$ and $s$ random variables lie in $(0,1]$ almost surely. Let $\smash{\vec{d}}\equiv(d^\SPIN{+},d^\SPIN{-})\sim\textup{\textsf{po}}_{\SPIN{\textpm}}$, and use this to define the random variables
	\begin{equation}\label{e:stability.notations}
	\Pi^\SPIN{\textpm}
	\equiv \prod_{i=1}^{d^\SPIN{\textpm}} S^\SPIN{\textpm}_i\,,\quad
	\pi^\SPIN{\textpm}
	\equiv \prod_{i=1}^{d^\SPIN{\textpm}} s^\SPIN{\textpm}_i\,,\quad
	\Sigma
	\equiv\ln \frac{\Pi^\SPIN{+}}{\Pi^\SPIN{-}}\,,\quad
	\sigma
	\equiv\ln \frac{\pi^\SPIN{+}}{\pi^\SPIN{-}}\,.\end{equation}
For the remainder of the proof we will abbreviate
$S_i\equiv S^\SPIN{-}_i$,
$s_i\equiv s^\SPIN{-}_i$,
$\Pi \equiv \Pi^\SPIN{-}$, $\pi\equiv \pi^\SPIN{-}$. 
With this notation, the pair $(\eta^{\ell+1},\eta^\ell)$ is equidistributed as
	\[\bigg(
	\frac{(1-\Pi)\exp(\Sigma)}{1+(1-\Pi)\exp(\Sigma)},
	\frac{(1-\pi)\exp(\sigma)}{1+(1-\pi)\exp(\sigma)}
	\bigg)
	=\bigg( F(\Pi,\Sigma),F(\pi,\sigma)\bigg)
	\,,
	\]
for $F$ as defined by \eqref{e:def.F.x.y}. To prove the result, it suffices to bound $\mathbb{E}(J^p)$ for
	\[
	J^p
	\equiv 
	\bigg|
	\frac{ F(\Pi,\Sigma)-F(\pi,\sigma)}
		{ F(\Pi,\Sigma)+F(\pi,\sigma)}\bigg|^p
	\le\bigg(\frac{2|\Pi-\pi|}{2-\Pi-\pi}\bigg)^p
	 + |\Sigma-\sigma|^p\,,\]
where the last bound follows by Lemma~\ref{l:F.diff.ratio.bound}.
Since each of $\Pi,\pi$ is a product over $d^\SPIN{-}$ terms, we can decompose their difference as a telescoping product:
	\[
	\Pi-\pi
	=\prod_{i=1}^{d^\SPIN{-}} S_i
	-\prod_{i=1}^{d^\SPIN{-}} s_i
	=\sum_{i=1}^{d^\SPIN{-}} 
		\Pi[i]
		(S_i-s_i)\,,\quad
	\Pi[i]\equiv
		\prod_{j=1}^{i-1} S_j
		\prod_{j=i+1}^{d^\SPIN{-}} s_j\,.
	\]
It follows from H\"older's inequality that
for any $\mathbf{u}\in\mathbb{R}^d$,
$|(\mathbf{1},\mathbf{u})|^p
\le d^{p-1} (\|\mathbf{u}\|_p)^p$. This implies
	\begin{equation}\label{e:diff.Pi.telescope}
	|\Pi-\pi|^p
	\le
	(d^\SPIN{-})^{p-1}
	\sum_{i=1}^{d^\SPIN{-}}
	\Pi[i]^p |S_i-s_i|^p\,.
	\end{equation}
Note that $0\le \Pi,\pi\le1$, and $\Pi\pi \le \Pi[i]$ for any $i$. Let $\bm{F}_i$ be the event that $\Pi[i]\ge 1/4$.
If $\bm{F}_i$ does not occur, then we must have
either $\Pi\le1/2$ or $\Pi\le1/2$, therefore $2-\Pi-\pi \ge 1/2$. It follows that
	\begin{equation}\label{e:stability.decomp}
	J^p\le
	\underbrace{\Bigg[
	4^p (d^\SPIN{-})^{p-1}
	\sum_{i=1}^{d^\SPIN{-}}
	\Pi[i]^p |S_i-s_i|^p\Bigg] }_{J_1(p)}
	+\underbrace{\Bigg[ 2^p (d^\SPIN{-})^{p-1}
	\sum_{i=1}^{d^\SPIN{-}}
	\mathbf{1}_{\bm{F}_i}
	\frac{\Pi[i]^p |S_i-s_i|^p}{(2-\Pi-\pi)^p}
	\Bigg]}_{J_2(p)}
	+|\Sigma-\sigma|^p\,.\end{equation}
Similarly to \eqref{e:diff.Pi.telescope}, we can expand $S-s \equiv S_i-s_i$ as a telescoping sum, then use H\"older's inequality to bound
	\begin{equation}\label{e:telescope.def.U.j}
	|S-s|^p
	=\bigg|
	\prod_{j=1}^{K-1} H_j
	-\prod_{j=1}^{K-1} h_j
	\bigg|^p
	\le k^{p-1}
	\sum_{j=1}^{K-1} U[j]^p
		|H_j-h_j|^p\,,\quad
		U[j]\equiv \prod_{t=1}^{j-1} H_t
		\prod_{t=j+1}^{K-1} h_t\,.
	\end{equation}
It follows by considerations of conditional independence that
	\[
	\mathbb{E} J_1(p)
	\le (4k)^p
	\mathbb{E}\bigg[ (d^\SPIN{-})^p
	(\max\set{\mathbb{E}(S^p),\mathbb{E}(s^p)})^{d^\SPIN{-}-1}\bigg]
	\bigg(\max\set{ \mathbb{E}(H^p),\mathbb{E}(h^p)}\bigg)^{k-3}
	\mathbb{E}(|H-h|^p)\,.
	\]
Both $\mathbb{E}(S^p)$ and $\mathbb{E}(s^p)$ satisfy the bound from Corollary~\ref{c:exp.minus.p.times.X}; and combining with Lemma~\ref{l:d.to.p.times.theta.to.d} gives a bound on the first expectation on the right-hand side above. Both $\mathbb{E}(H^p)$ and $\mathbb{E}(h^p)$ satisfy the bound from Corollary~\ref{c:pth.moment.of.eta}. The last factor
$\mathbb{E}(|H-h|^p)$ is bounded by
the inductive hypothesis \eqref{e:stability.inductive}. Altogether it gives
	\begin{equation}\label{e:stability.first.finalbound}
	\mathbb{E} J_1(p)
	\le O(1) (4k)^p
	\bigg(\frac{3k}{8}\bigg)^p
	\frac{\mathbb{E} (|H-h|^p)}{2^{p(k-3)}}
	\le
	\bigg( \frac{k^3}{2^k}\bigg)^p
	\frac1{2^{kp/7} 2^{2kp\ell/5}} 
	=\bigg( \frac{k^3 I(\ell)}{2^k} \bigg)^p
	\,.\end{equation}
Turning to $J_2(p)$, we note that (very crudely) we have
$0\le \Pi[i]\le1$ and $2-\Pi-\pi \ge 2-S_i-s_i$
for any $1\le i\le d^\SPIN{-}$. Therefore, again with considerations of conditional independence, we have
	\begin{equation}\label{e:J.2.p}
	\mathbb{E} J_2(p)
	\le 2^p
	\mathbb{E}\bigg[
	(d^\SPIN{-})^{p-1}
	\sum_{i=1}^{d^\SPIN{-}} \mathbf{1}_{\bm{F}_i}
	\bigg]
	\mathbb{E}\bigg[ \bigg|\frac{S-s}{2-S-s}\bigg|^p\bigg]
	\,.\end{equation}
Recall that $\bm{F}_i$ is the event that $\Pi[i]\ge1/4$, or equivalently that
	\[
	\Sigma[i]
	\equiv \ln\frac1{\Pi[i]}
	= \sum_{j=1}^{i-1} \ln \frac1{S_i}
		+\sum_{j=i+1}^{d^\SPIN{-}} \ln \frac1{s_i}
	\le \ln 4\,.
	\]
By essentially the same argument as for
\eqref{e:left.tail.Sigma}, as long as $d^\SPIN{-}\ge \alpha k/4$ we have $\mathbb{P}(\bm{F}_i\,|\,d^\SPIN{-})\le \exp(-\Omega(k2^{k/4}))$. We can then apply Lemma~\ref{l:d.to.p.times.rare.event} to bound the first expectation in \eqref{e:J.2.p}:
	\begin{equation}\label{e:stability.rare.event.bnd}
	\mathbb{E}\bigg[
	(d^\SPIN{-})^{p-1}
	\sum_{i=1}^{d^\SPIN{-}} \mathbf{1}_{\bm{F}_i}
	\bigg]
	\le \frac1{\exp(2^{k/5})}\,.
	\end{equation}
For the second expectation
in \eqref{e:J.2.p}, Lemma~\ref{l:ratio.a.b.bound} gives
	\[
	\mathbb{E}\bigg[ \bigg|\frac{S-s}{2-S-s}\bigg|^p\bigg]
	=
	\mathbb{E}\Bigg[ \Bigg|
	\frac{\prod_{j=1}^{K-1} H_j-\prod_{j=1}^{K-1} h_j}
		{\prod_{j=1}^{K-1} H_j+\prod_{j=1}^{K-1} h_j}
	\Bigg|^p\Bigg]
	\le
	\mathbb{E} \Bigg[\bigg(
	\sum_{\varnothing \subsetneq J\subseteq [k-1]}
	2^{|J|}
	\prod_{j\in J} 
	\bigg|\frac{H_j-h_j}{H_j+h_j}\bigg|\bigg)^p
	\Bigg]\,.
	\]
Let $\vec{J}\equiv(J_1,\ldots,J_p)$ denote any $p$-tuple of nonempty subsets of $[k-1]$. We abbreviate
$|\vec{J}| \equiv |J_1| + \ldots + |J_p| \ge p$.
For any $j\in[k-1]$, let
$n_j(\vec{J})$ denote the number of occurrences of $j$ in the sets $J_1,\ldots,J_p$:
	\[
	n_j(\vec{J})
	=\sum_{t=1}^p
	\Ind{j \in J_t}\,,\quad
	\sum_{j=1}^{k-1} n_j(\vec{J})
	= \sum_{t=1}^p |J_t| = |\vec{J}| \ge p\,.
	\]
With this notation, we can bound
	\[
	\mathbb{E}\bigg[ \bigg|\frac{S-s}{2-S-s}\bigg|^p\bigg]
	\le\sum_{\vec{J}}
	2^{|\vec{J}|}
	\prod_{j=1}^{k-1}
	\mathbb{E}\Bigg[
	\bigg|\frac{H_j-h_j}{H_j+h_j}\bigg|^{n_j(\vec{J})} \Bigg]
	\le
	\sum_{\vec{J}}
	2^{|\vec{J}|}
	\mathbb{E}\Bigg[
	\bigg|\frac{H-h}{H+h}\bigg|^p \Bigg]^{|\vec{J}|/p}\,,
	\]
where the last step is by Jensen's inequality. The number of choices of $\vec{J}\equiv(J_1,\ldots,J_p)$ with $|\vec{J}|=b$ is upper bounded by $k^b$. Combining with the inductive hypothesis \eqref{e:stability.inductive} gives
	\[\mathbb{E}\bigg[ \bigg|\frac{S-s}{2-S-s}\bigg|^p\bigg]
	\le
	\sum_{b\ge p}
	\Bigg( 2k
	\mathbb{E}\Bigg[
	\bigg|\frac{H-h}{H+h}\bigg|^p \Bigg]^{1/p}
	\Bigg)^b
	\le
	\sum_{b\ge p}
	\Bigg( \frac{2k}{2^{k/7} 2^{2k\ell/5}} \Bigg)^b
	\le \frac{k^{2p}}{ 2^{kp/7} 2^{2kp\ell/5} }\,.
	\]
Substituting this and \eqref{e:stability.rare.event.bnd}
into \eqref{e:J.2.p} gives
	\begin{equation}\label{e:stability.second.finalbound}
	\mathbb{E} J_2(p) \le
	\frac{k^{2p}}{\exp(2^{k/5})}
	\frac1{ 2^{kp/7} 2^{2kp\ell/5} }
	\le
	\bigg( \frac{k^2 I(\ell)}{\exp(2^{k/10})} \bigg)^p
	\,.\end{equation}
Finally we bound $\mathbb{E}(|\Sigma-\sigma|^p)$, where we recall from \eqref{e:stability.notations} that
	\[
	\Sigma
	=\ln \frac{\Pi^\SPIN{+}}{\Pi^\SPIN{-}}
	= \sum_{i=1}^{d^\SPIN{+}}\ln S^\SPIN{+}_i
	-\sum_{i=1}^{d^\SPIN{-}}\ln S^\SPIN{-}_i\,,
	\]
and similarly $\sigma=\ln(\pi^\SPIN{+}/\pi^\SPIN{-})$. Let $D\sim\textup{\textsf{Pois}}(\alpha k)$, and let $(\mathfrak{s}_i)_{i\ge1}$ be a sequence of i.i.d.\ symmetric random signs. Then, recalling that $p$ is an even integer, we have
	\begin{equation}\label{e:diff.Sigma.sigma.pth.mmt}
	\mathbb{E}(|\Sigma-\sigma|^p)
	= \mathbb{E}\Bigg[ \bigg(\sum_{i=1}^D
	\mathfrak{s}_i
	(\ln S_i-\ln s_i)
	\bigg)^p\Bigg]
	\le O(1) \bigg( \frac{dp}{e} \bigg)^{p/2}
		\mathbb{E}\bigg[\bigg|\ln \frac{S}{s}\bigg|^p\bigg]\,,
	\end{equation}
where the last step uses Lemma~\ref{l:wk.rademacher.bound}.
We then use a telescoping sum to bound
	\begin{equation}\label{e:telescoping.sum.u.h}
	\bigg|\ln \frac{S}{s}\bigg|
	=\bigg|
	\ln \frac{1-\prod_{j=1}^{K-1} H_j}
		{1-\prod_{j=1}^{K-1} h_j}
	\bigg|
	\le \sum_{j=1}^{K-1}
	\bigg|\ln
		\frac{1-U[j] H_j}
		{1-U[j] h_j}\bigg|
	\le
	\sum_{j=1}^{K-1}
	\frac{U[j]}{1-U[j]}
	\cdot
	|H_j-h_j|\,,
	\end{equation}
where the last step uses that the function $f_U(h)=\ln(1-Uh)$ has $|(f_U)'(h)| \le U/(1-U)$ for all $U,h\in[0,1]$. In the last expression above, we can further replace $U[j]$ (defined by \eqref{e:telescope.def.U.j}) with
	\[U_\circ[j]
	\equiv \prod_{t=1}^{j-1} H_t
		\prod_{t=j+1}^{k-2} h_t
	\ge U[j]\,.
	\]
It follows by H\"older's inequality, combined with the Cauchy-Schwarz inequality, that
	\begin{equation}\label{e:diff.log.S.log.s}
	\mathbb{E}\bigg[\bigg|\ln \frac{S}{s}\bigg|^p\bigg]
	\le k^p
	\bigg(\max\set{\mathbb{E}(H^{2p}),\mathbb{E}(h^{2p})}\bigg)^{(k-3)/2}
	\max_{j\le k-2}
	\mathbb{E}\bigg[\bigg(\frac{1}{1-U_\circ[j]}\bigg)^{2p}\bigg]^{1/2}
	\mathbb{E}(|H-h|^p)
	\end{equation}
For $x\ge 3$, we have
$\ln x + \ln(1-1/x) \ge (\ln x)/2$. It follows that
	\begin{align*}
	\mathbb{P}\bigg(\frac{1}{1-U_\circ[j]}\ge x\bigg)
	&=\mathbb{P}\bigg(U_\circ[j] \ge 1-\frac1x\bigg)
	\le\max\bigg\{
	\mathbb{P}\bigg(H\ge 1-\frac1x\bigg),
	\mathbb{P}\bigg(h\ge 1-\frac1x\bigg)\bigg\}^{k-3}\\
	&\le\max\bigg\{
	\mathbb{P}\bigg( \ln\frac{H}{1-H} \ge \frac{\ln x}2 \bigg),
	\mathbb{P}\bigg( \ln\frac{h}{1-h} \ge \frac{\ln x}2 \bigg)
	\bigg\}^{k-3}
	\le \frac1{\exp( k(\ln x) 2^{k/4})}\,,\end{align*}
where the last bound is by \eqref{i:mu.ell.upper.tail.bound} 
from Lemma~\ref{l:mu.ell.tail.bounds}. Integrating this bound gives
	\[\mathbb{E}\Bigg[\bigg(\frac{1}{1-U_\circ[j]}\bigg)^{2p}\Bigg]
	\le(3/2) \cdot 3^{2p}
		+ \int_3^\infty \frac{pt^{p-1}}{t^{k2^{k/4}}}\,dt
	\le 2 \cdot 3^{2p}\,.
	\]
The other factors in \eqref{e:diff.log.S.log.s}
are controlled by Corollary~\ref{c:pth.moment.of.eta} and \eqref{e:stability.inductive}. Substituting into
\eqref{e:diff.Sigma.sigma.pth.mmt} gives
	\begin{equation}\label{e:diff.Sigma.sigma.finalbound}
	\mathbb{E}|\Sigma-\sigma|^p
	\le
	O(1) \bigg( \frac{dp}{e} \bigg)^{p/2}
	\frac{k^{2p}}{2^{kp}}
	\frac1{2^{kp/7} 2^{2kp\ell/5}} 
	\le
	\bigg( \frac{k^2 I(\ell)}{2^{9k/20}} \bigg)^p
	\,.\end{equation}
Substituting
\eqref{e:stability.first.finalbound}, \eqref{e:stability.second.finalbound}, and \eqref{e:diff.Sigma.sigma.finalbound}
into \eqref{e:stability.decomp} gives
	\[
	\mathbb{E} \Bigg[
	\bigg|\frac{\eta^{\ell+1}-\eta^\ell}
		{\eta^{\ell+1}+\eta^\ell}\bigg|^p
		\Bigg]
	= \mathbb{E}(J^p) \le O(1) 
	\bigg( \frac{k^2 I(\ell)}{2^{9k/20}} \bigg)^p\,,
	\]
which verifies the induction \eqref{e:stability.inductive} and proves the result.

