\begin{equation}\label{e:phi.onersb}
	\Phi(\alpha)
	\equiv \sum_{\vec d} \textup{\textsf{po}}_{\SPIN{\textpm}}(\vec d)
	\int
	\ln\frac{\Pi^\SPIN{+}(\vec d,\vec\eta)
		+\Pi^\SPIN{-}(\vec d,\vec\eta)-
		\Pi^\SPIN{+}(\vec d,\vec\eta)\Pi^\SPIN{-}(\vec d,\vec\eta) }
		{(1- \prod_{j=1}^k \eta_j)^{(k-1)\alpha} }
	\, d\mu^{\otimes}\Big(
	(\eta_j)_{j\ge1},\smash{\vec{\eta}}
	\Big)\,.
	\end{equation}

\label{t:free.energy} Let $\mathscr{M}_1$ denote the space of probability measures on $\mathbb{R}$, and $\mathscr{M}_2$ the space of probability measures on $\mathscr{M}_1$. For $\zeta\in\mathscr{M}_2$, let $\smash{\vec{\eta}}\equiv(\eta_{a,j})_{a,j\ge0}$ be an array of i.i.d.\ samples from $\zeta$. Conditioned on $\smash{\vec{\eta}}$, let $\vec\rho\equiv(\rho_{a,j})_{a,j\ge0}$ where each $\rho_{a,j}$ is a conditionally independent sample from $\eta_{a,j}$. For $x\in\set{\SPIN{\textpm}}$, define
	\[\bm{u}_a(x)
	= \sum_{\smash{\vec{x}} \in\set{\SPIN{\textpm}}^k}
		\Ind{x_k=x}\exp\{ -\beta\theta_a(\smash{\vec{x}})\}
		\prod_{j=1}^{k-1} 
	\frac{ \exp\{\rho_{a,j} x_j\}}
		{ 2 \mathrm{ch} \rho_{a,j} }\,,\]
with $\mathrm{ch}$ the hyperbolic cosine. Define also
	\[\bm{u}_a
	= \sum_{\smash{\vec{x}} \in\set{\SPIN{\textpm}}^k}
		\exp\{ -\beta\theta_a(\smash{\vec{x}})\}
		\prod_{j=1}^k \frac{\exp\{\rho_{a,j} x_j\}}
			{2\mathrm{ch} \rho_{a,j}}\,.\]
Note $\bm{u}_a(x)$ and $\bm{u}_a$ are random variables. Then, for any $0<m<1$ and for any $\zeta\in\mathscr{M}_2$,
	\[
	F_n(\beta)
	\le
	\Phi_{\textup{1-\textsc{rsb}}}(\beta,\zeta,m)
	\equiv \frac1m \mathbb{E}\ln
		\mathbb{E}'\bigg[
		\Big(
		\sum_{x\in\set{\SPIN{\textpm}}}
		\prod_{a=1}^d \bm{u}_a(x)
		\Big)^m
		\bigg]
	- \frac{(k-1)\alpha}{m}
		\mathbb{E}\ln\mathbb{E}'[(\bm{u}_0)^m]
	\]
where $\mathbb{E}'$ is expectation over $\vec\rho$ conditioned on $d,\vec\theta,\vec\eta$; and $\mathbb{E}$ is the overall expectation over $d,\vec\theta,\vec\eta,\vec\rho$.

We will deduce the bound from Theorem~\ref{t:free.energy} by taking a particular choice of $\zeta,m$ which is suggested by the survey propagation heuristic. Let $\mu\in\mathscr{P}$ be the fixed point given by Proposition~\ref{p:fp}. Let $\bm{\mu}=\mathcal{R}\mu$ for $\mathcal{R}\equiv\mathcal{R}_0$ as given by Definition~\ref{d:full.dist.recurs}. Now fix $\beta>0$, and let
	\begin{equation}\label{e:interpolation.rho}
	\Big(\rho_\SPIN{+},\rho_\SPIN{-},\rho_\SPIN{f}\Big)
		\equiv
		\Big(\beta,-\beta,0\Big)\,.
	\end{equation}
Let $\eta$ be defined as the law of $\rho_y$ where $y\in\set{\SPIN{+},\SPIN{-},\SPIN{f}}$ is distributed according to $\bm{\eta}$, and $\bm{\eta}$ is distributed according to $\bm{\mu}$: formally, for any Borel set $B\subseteq\mathbb{R}$ (where it suffices to consider $B\subseteq\set{\beta,-\beta,0}$),
	\[
	\eta(B)
	= \int \bm{\eta}(y) \mathbf{1}\Big\{\rho_y\in B\Big\}
	 \,d\bm{\mu}(\bm{\eta})\,.
	\]
Thus $\eta\in\mathscr{M}_1$ is an $\bm{\eta}$-measurable random measure supported on $\set{\rho_\SPIN{+},\rho_\SPIN{-},\rho_\SPIN{f}}=\set{\beta,-\beta,0}\subseteq\mathbb{R}$. Let $\zeta$ denote the law of $\eta$, so $\zeta\in\mathscr{M}_2$ and the randomness in $\zeta$ is the randomness of $\bm{\eta}$. For $x\in\set{\SPIN{-},\SPIN{+}}$ and $\smash{\vec{y}}_a\in\set{\SPIN{+},\SPIN{-},\SPIN{f}}^{k-1}$, let
	\[
	\bm{u}_a(x|\smash{\vec{y}}_a)
	\equiv \sum_{\smash{\vec{x}} \in\set{\SPIN{\textpm}}^k}
		\frac{\Ind{x_k=x}}
			{\exp(\beta\theta_a(\smash{\vec{x}}))}
		\prod_{j=1}^{k-1} 
		r(x_j | y_{a,j})\,,\quad
		r(x|y) \equiv 
		\frac{\exp\{\rho_y x\}}{2\mathrm{ch}\rho_y}\,.\]
Note it follows from the definition 
\eqref{e:interpolation.rho} that 
	\[
	r(\SPIN{+}|\SPIN{+})
	=r(\SPIN{-}|\SPIN{-})
	= \frac{e^\beta}{2\mathrm{ch}\beta}
	= 1-r(\SPIN{-}|\SPIN{+})
	= 1-r(\SPIN{+}|\SPIN{-})\,.
	\]
It follows by combining with the definition of $\theta_a$ that
	\begin{align*}
	\bm{u}_a\Big( \SPIN{-}\SPIN{L}_{a,k} \,\Big|\,
		(\SPIN{-}\SPIN{L}_{a,j})_{1\le j\le k-1}
		\Big)
	&= \frac1{e^\beta}
	\prod_{j=1}^{k-1}
	r( \SPIN{-}\SPIN{L}_{a,j}|\SPIN{-}\SPIN{L}_{a,j} )
	+ \bigg\{
	1-	\prod_{j=1}^{k-1}
	r( \SPIN{-}\SPIN{L}_{a,j}|\SPIN{-}\SPIN{L}_{a,j} )
	\bigg\} \\
	&=\frac1{e^\beta} \bigg(
		\frac{e^\beta}{2\mathrm{ch}\beta}\bigg)^{k-1}
	+\bigg\{ 1- \bigg(
		\frac{e^\beta}{2\mathrm{ch}\beta}\bigg)^{k-1}
		\bigg\}
	\le \frac1{e^{\beta/2}}\,,
	\end{align*}
where the last bound holds assuming $k$ is large enough and $\beta\ge k$. Thus, with $\mathbb{P}'$ denoting the law of $\vec\rho$
conditioned on $d,\vec\theta,\vec\eta$, for $x\in\set{\SPIN{\textpm}}$ we have
	\[
	\mathbb{P}'\bigg(
	\underbrace{\prod_{a=1}^d \bm{u}_a(x)
		> \frac1{e^{\beta/2}}}_{\textup{event }F_x}\bigg)
	\le \Pi^x
	\equiv\prod_{a : \SPIN{L}_{a,k}=x}
		\bigg( 1-\prod_{j=1}^{k-1}
		\bm{\eta}_{a,j}
			( \SPIN{-}\SPIN{L}_{a,j} )
		\bigg)\,.
	\]
Since $F_x$
can be decided by looking only at the clauses $\partial v(x)$, we have
	$\mathbb{P}'( F_\SPIN{+} \cup F_\SPIN{-} )
	\le 1 - (1-\Pi^\SPIN{+})(1-\Pi^\SPIN{-})$, so
	\[\mathbb{E}'\bigg[
		\Big(
		\sum_{x\in\set{\SPIN{\textpm}}}
		\prod_{a=1}^d \bm{u}_a(x)
		\Big)^m
		\bigg]
	\le 2^m \mathbb{P}'\Big(F_\SPIN{+} \cup F_\SPIN{-}\Big)
		+ \bigg( \frac{2}{e^{\beta/2}}\bigg)^m
	\le 2^m \bigg( \Pi^\SPIN{+}+\Pi^\SPIN{-}
		-\Pi^\SPIN{+}\Pi^\SPIN{-} 
		+ \frac1{e^{m\beta/2}}
		\bigg)\,.\]
Similar considerations give 
	\[
	\mathbb{E}'\Big[ (\bm{u}_a)^m \Big]
	\ge
	\frac1{2^m}
	\mathbb{P}'\bigg(\bm{u}_a\ge\frac12\bigg)
	\ge \frac1{2^m}\bigg(
	1 - \prod_{j=1}^k \eta_{a,j}
		(\SPIN{-}\SPIN{L}_{a,j})\bigg)\,.
	\]
Combining the above bounds gives
	\[
	m \Phi_{\textup{1-\textsc{rsb}}}(\beta,\zeta,m)
	\le m 4^k + 
	\mathbb{E}\ln \frac{\Pi^\SPIN{+}+\Pi^\SPIN{-}
		-\Pi^\SPIN{+}\Pi^\SPIN{-} 
		+ e^{-m\beta/2}}
		{ [1-\prod_{j=1}^{k-1} \eta_j]^{(k-1)\alpha} }.
	\]
Taking $m=1/\beta^{1/2}$, the right-hand side converges to the function $\Phi(\alpha)$ from \eqref{e:phi.onersb} in the limit $\beta\to\infty$. Now assume $\alpha>\alpha_\star$, so that $\Phi(\alpha)<0$ (of course, this uses Proposition~\ref{p:phi}). Then, for sufficiently large $\beta$, we will have
	\begin{equation}\label{e:neg.free.energy}
	F_n(\beta)
	\le
	\Phi_{\textup{1-\textsc{rsb}}}\bigg(\beta,\zeta,\frac1{\beta^{1/2}}\bigg)
	\le 4^k + 
	\frac{\beta^{1/2} \Phi(\alpha)}{2}
	\le \frac{\beta^{1/2} \Phi(\alpha)}{4} 
	< 0.
	\end{equation}
To conclude, recall that the log-partition function $\ln Z_n(\beta)$ is well concentrated about its expected value $nF_n(\beta)$ (take the Doob martingale of $\ln Z_n(\beta)$ with respect to the $\textup{$k$-\textsc{sat}}$ clause-revealing filtration, and apply the Azuma--Hoeffding inequality). Thus \eqref{e:neg.free.energy} implies that with high probability $\ln Z_n(\beta)$ is negative, i.e., the \textsc{sat} instance is unsatisfiable.

In Corollary~\ref{c:first.moment.exponent} we saw that
	\[
	\mathbb{E}_{\mathscr{D}}\bm{Z}
	= \exp\bigg\{ 
	n\bm{\Psi}_{\mathscr{D}}({}_\star\hspace{-1pt}\omega) - o(n)
	\bigg\}
	\]
where $\bm{\Psi}_{\mathscr{D}}({}_\star\hspace{-1pt}\omega)$ is defined by the constrained optimization problem
\eqref{e:nu.opt}.

\label{l:phi.equals.phi.col}
For $\alpha$ in the regime
\eqref{e:alpha.regime},
the $\textup{1-\textsc{rsb}}$ free energy of the $\textup{$k$-\textsc{sat}}$ model
($\Phi(\alpha)$ from \eqref{e:phi.alpha})
coincides with the replica symmetric
(Bethe) free energy of the coloring model
($\Phi^\textup{col}(\alpha)$
from Definition~\ref{d:Phi.col}).

\begin{proof}We will show that the form of $\Phi^\textup{col}(\alpha)$ given by \eqref{e:simplified.phi.col.terms}~and~\eqref{e:simplified.phi.col} is equivalent to $\Phi(\alpha)$. As in Definition~\ref{d:bethe.laws.of.color.messages}, let $\bm{\eta}_j$ be i.i.d.\ copies of $\bm{\eta}$, and let $\bm{\hat{u}}$ as in \eqref{e:second.defn.of.bhu}. Let $\dot{q}_j\equiv \dot{q}(\bm{\eta}_j)$ via the correspondence \eqref{e:color.recursions.eta.again}. Then the $\bar{z}$ in \eqref{e:simplified.phi.col.terms} can be re-written as
	\[
	\bar{z}
	= \sum_\sigma 
		\dot{q}_k(\sigma)
		\hat{q}(\sigma)
	= \dot{q}_k(\SSPIN{r}) \hat{q}(\SSPIN{r})
		+ [1-\dot{q}_k(\SSPIN{r})]\hat{q}(\SSPIN{y})
	=
	 \frac{1}
		{ [3-2\bm{\hat{u}} (\SPIN{+})]
			[2-\bm{\eta}_k(\SPIN{-})] }
			\Bigg(1 -
			\prod_{j=1}^k \bm{\eta}_j(\SPIN{-}) \Bigg)\,.\]
Similarly, the 
$\bm{\hat{z}}$ in \eqref{e:simplified.phi.col.terms}
can be re-written as
	\begin{align*}
	\bm{\hat{z}}
	&=\sum_{\smash{\vec{\sigma}}} \hat{\varphi}(\smash{\vec{\sigma}})
		\prod_{j=1}^k \dot{q}_j(\sigma_j)
	= \prod_{j=1}^k [1-\dot{q}_j(\SSPIN{r})]
	-\prod_{j=1}^k \dot{q}_j(\SSPIN{y})
	+ \sum_{j=1}^k [\dot{q}_j(\SSPIN{r})-\dot{q}_j(\SSPIN{c})]
		\prod_{l\ne j} \dot{q}_l(\SSPIN{y})\\
	&=\prod_{j=1}^k [1-\dot{q}_j(\SSPIN{r})]
		-\prod_{j=1}^k \dot{q}_j(\SSPIN{y})
	= \Bigg(1- \prod_{j=1}^k\bm{\eta}_j(\SPIN{-}) \bigg)
		\Bigg/
		\Bigg(
		\prod_{j=1}^k [2-\bm{\eta}_j(\SPIN{-})]
		\Bigg)\,.
	\end{align*}
For the $\bm{\dot{z}}$ in \eqref{e:simplified.phi.col.terms}, 
given $\smash{\vec{d}}=(d^\SPIN{+},d^\SPIN{-})$ let us abbreviate
	\[
	\smash{\vec{\sigma}} =
	\bigg(
	\Big(\sigma^\SPIN{+}_i\Big)_{1\le i\le d^\SPIN{+}},
	\Big(\sigma^\SPIN{-}_i\Big)_{1\le i\le d^\SPIN{-}}
	\bigg)\,,
	\]
and let $\varphi(\smash{\vec{\sigma}};\vec d)$ be the indicator that
$\smash{\vec{\sigma}}$ gives a valid coloring of a variable where the first $d^\SPIN{+}$ incident edges are of $\SPIN{+}$ sign
while the remaining $d^\SPIN{-}$ 
incident edges are of $\SPIN{-}$ sign. Then we can rewrite
	\begin{align*}
	\bm{\dot{z}}
	&= \sum_{\smash{\vec{\sigma}}}
		\varphi(\smash{\vec{\sigma}};\vec d)
		\prod_{i=1}^{d^\SPIN{+}} \hat{q}^\SPIN{+}_i(\sigma^\SPIN{+}_i)
		\prod_{i=1}^{d^\SPIN{-}}
		\hat{q}^\SPIN{-}_i(\sigma^\SPIN{-}_i)
	=\prod_{i=1}^{d^\SPIN{+}}
		\hat{q}^\SPIN{+}_i(\SSPIN{g})
		\prod_{i=1}^{d^\SPIN{-}}
		\hat{q}^\SPIN{-}_i(\SSPIN{g})\\ \nonumber
	&\qquad + \Bigg\{
		\prod_{i=1}^{d^\SPIN{+}}
		\hat{q}^\SPIN{+}_i(\SSPIN{p})
		-\prod_{i=1}^{d^\SPIN{+}}
		\hat{q}^\SPIN{+}_i(\SSPIN{b})\Bigg\}
		\prod_{i=1}^{d^\SPIN{-}}
		\hat{q}^\SPIN{-}_i(\SSPIN{y})
	+ \Bigg\{
		\prod_{i=1}^{d^\SPIN{+}}
		\hat{q}^\SPIN{+}_i(\SSPIN{p})
		-\prod_{i=1}^{d^\SPIN{+}}
		\hat{q}^\SPIN{+}_i(\SSPIN{b})\Bigg\}
		\prod_{i=1}^{d^\SPIN{-}}
		\hat{q}^\SPIN{-}_i(\SSPIN{y})\\
	&= \bigg(\Pi^\SPIN{+}+\Pi^\SPIN{-}
		-\Pi^\SPIN{+}\Pi^\SPIN{-}\bigg)
		\bigg/
		\Bigg\{
		\prod_{i=1}^{d^\SPIN{+}}
		[3-2\bm{\hat{u}}^\SPIN{+}_i(\SPIN{+})]
		\prod_{i=1}^{d^\SPIN{-}}
		[3-2\bm{\hat{u}}^\SPIN{-}_i(\SPIN{+})]
		\Bigg\}\,,\quad
		\bm{\hat{u}}^\SPIN{\textpm}_i(\SPIN{+})
		\equiv \prod_{j=1}^{k-1}
			\bm{\eta}^\SPIN{\textpm}_{ij}(\SPIN{-}).
	\end{align*}
Let us write simply $\mathbb{E}$ for expectation with respect to the law of the $\bm{\eta}_i$. Substituting the above into \eqref{e:simplified.phi.col.terms} gives
	\begin{align*}
	\Phi^{\textup{col},\textup{v}}(\alpha)
	&=\mathbb{E} \Bigg[\ln \bigg(\Pi^\SPIN{+}+\Pi^\SPIN{-}
		-\Pi^\SPIN{+}\Pi^\SPIN{-}\bigg)\Bigg]
	-k\alpha\,\mathbb{E}
		\Bigg[\ln\bigg(3-2\bm{\hat{u}}(\SPIN{+})\bigg)\Bigg]\,,\\
	\alpha\,\Phi^{\textup{col},\textup{cl}}(\alpha)
	&=
	\alpha\,\mathbb{E}\Bigg[
	\ln\bigg(1-\prod_{j=1}^k
	\bm{\eta}_j(\SPIN{-})\bigg)\Bigg]
	-k\alpha\,\mathbb{E}
	\bigg[\ln\bigg(2-\bm{\eta}_1(\SPIN{-})\bigg)\bigg]
	\,,\\
	-k\alpha\,\Phi^{\textup{col},\textup{e}}(\alpha)
	&\equiv
	-k\alpha\, \mathbb{E}\Bigg[
	\ln\bigg(1-\prod_{j=1}^k
	\bm{\eta}_j(\SPIN{-})\bigg)\Bigg]
	+k\alpha\,\mathbb{E}\Bigg[\ln
		\bigg(3-2\bm{\hat{u}}(\SPIN{+})\bigg)\Bigg]
	+k\alpha\,\mathbb{E}
	\Bigg[\ln\bigg(2-\bm{\eta}_1(\SPIN{-})\bigg)\Bigg]\,.
	\end{align*}
Substituting these into \eqref{e:simplified.phi.col}
we see that $\Phi^\textup{col}(\alpha)$ agrees with
$\Phi(\alpha)$ from \eqref{e:phi.alpha}.
\end{proof}

