\label{lem-local-D-0}
Let $\mathfrak{i}\in\set{0,1}$, and suppose $\mathfrak{c}\ge2$ is upper bounded by an absolute constant. Then, as long as $k$ exceeds an absolute constant $k_0$ (depending only on the bound on $\mathfrak{c}$), we have the bound
	\[
	{\textup{\textbf{PGW}}}\bigg( |D^{\kappa_*,\mathfrak{i}} \cap V_T| 
	\ge \ell\epsilon
	\text{ for some }
	T\in\bm{\Lambda}_{\mathfrak{c},\ell}\bigg)
	\le \frac{ \exp( k^2\ell)}
	{ \exp( 2^{k/4} \ell\epsilon) }
	\]
for all $\epsilon>0$ and all integer-valued $\ell\ge0$.


\begin{proof}
We divide the proof into three steps below. In the first step, we show that if some sparse subtree $T\subseteq\mathscr{T}$ has a nontrivial intersection with $D^{\kappa_*,\mathfrak{i}}$, then there must exist $T\subseteq T' \subseteq\mathscr{T}$ such that $T'$ is also sparse, and has a nontrivial intersection with $D^{*,\mathfrak{i}}$ --- this step is deterministic.
In the second step, we explain a general identity concerning the expected number of subtrees of $\mathscr{T}\sim{\textup{\textbf{PGW}}}$ satisfying a given property.
In the third step we bound this quantity to show that $T'$ is unlikely to occur. If $\ell\epsilon=0$ the bound is vacuous, so we assume without loss that $\ell\epsilon\ge1$. \smallskip

\noindent\bemph{Step 1. Construction of $T'$.}
Take any $T \in \bm{\Lambda}_{\mathfrak{c},\ell}(\mathscr{T})$ such that $A=D^{\kappa_*,\mathfrak{i}}\cap V_T$ has size $|A|\ge\ell\epsilon$.
For each variable $u\in A$, the number of variables 
in the $(4\kappa_*-1)$-neighborhood of $u$ in $T$ is at most
	\[
	|B_{4\kappa_*-1}(u) \cap V_T|
	=\sum_{\ell=0}^{4\kappa_*-1} \mathfrak{c}^{2\ell}
	= \frac{\mathfrak{c}^{8\kappa_*}}{\mathfrak{c}^2-1}
	\le \mathfrak{c}^{8\kappa_*}\,.
	\]
Therefore we can extract $A'\subseteq A$ of size $|A'| = \lceil \ell\epsilon/\mathfrak{c}^{8\kappa_*}\rceil$ such that variables in $A'$ lie at pairwise distance at least $4\kappa_*$. By definition, since $A'\subseteq A \subseteq D^{\kappa_*,\mathfrak{i}}$, every variable in $A'$ lies within distance $\kappa_*$ of $D^{*,\mathfrak{i}}$.
For each $u\in A'$, let $g(u)$ be any of the variables in $D^{*,\mathfrak{i}}$ which lies closest to $u$, and let $\gamma(u)$ be the path between $u$ and $g(u)$. The paths $\gamma(u)$, $u\in A'$, are of length at most $\kappa_*$, and are mutually disjoint. Let $T'$ be the union of $T$ with the paths $\gamma(u)$. Then we have $T'\in\bm{\Lambda}_{\ell',\mathfrak{c}+1}(\mathscr{T})$ for 
	\[
	\ell \le \ell' \le 
	\ell + \bigg\lceil \frac{\ell \epsilon}{\mathfrak{c}^{8\kappa_*}}
		 \bigg\rceil (\kappa_*-1)
		\le\ell\kappa_*\,.
	\]
Let $B'\equiv g(A')\subseteq D^{*,\mathfrak{i}}$, and note that $g:A'\to B'$ is a one-to-one mapping. We have thus shown that if there exists $T\in\bm{\Lambda}_{\mathfrak{c},\ell}(\mathscr{T})$ with at least $\ell\epsilon$ variables in $D^{\kappa_*,\mathfrak{i}}$,
then there must exist $T'\in\bm{\Lambda}_{\mathfrak{c}+1,\ell'}(\mathscr{T})$, for $\ell\le \ell'\le \ell\kappa_*$,
and a subset $B'\subseteq D^{*,\mathfrak{i}}\cap V_{T'}$
such that $B'=\lceil \ell\epsilon/\mathfrak{c}^{8\kappa_*} \rceil$,
and variables in $B'$ lie at pairwise distance at least $2\kappa_*$.\smallskip

\noindent\bemph{Step 2. Expected number of embedded subtrees.} 
Now fix any tree $T'\in\bm{\Lambda}_{\mathfrak{c}+1,\ell'}$
for $\ell\le\ell'\le\ell\kappa_*$, and a subset
$B'$ of variables in $T'$ such that $|B'|= \lceil \ell\epsilon/\mathfrak{c}^{8\kappa_*} \rceil$, and variables in $B'$ lie at pairwise distance at least $2\kappa_*$. For this fixed pair $(T',B')$ we will bound the probability
	\begin{align}\nonumber
	P(T',B') 
	&\equiv
	{\textup{\textbf{PGW}}}\bigg(
	\textup{there exists an embedding
	$\zeta:T'\hookrightarrow\mathscr{T}$ such that
	$\zeta(B')
	\subseteq D^{*,\mathfrak{i}}(\mathscr{T})$}
	\bigg)
	\\
	&\le \int
	\bigg|\bigg\{
	\textup{embeddings }
	\zeta : T'\hookrightarrow\mathscr{T}
	\textup{ such that }
	\zeta(B')
	\subseteq D^{*,\mathfrak{i}}(\mathscr{T})
	\bigg\}
	\bigg|
	\,d{\textup{\textbf{PGW}}}(\mathscr{T})\,.
	\label{e:expected.number.of.embeddings}
	\end{align}
(Later we will enumerate over $(T',B')$.) To calculate \eqref{e:expected.number.of.embeddings}, it is useful to take the following (equivalent) view of the random tree $\mathscr{T}\sim{\textup{\textbf{PGW}}}$: to each variable $v$ we attach $D(v)$ which is an independently sampled Poisson point process of unit rate on the interval $[0,\alpha k]$. The atoms of $D(v)$ correspond to the child clauses of $v$, and we write them in ascending order as
	\[
	D(v)= \bigg(
	a_i(v) : 1\le i\le |D(v)|
	\bigg)\,,\quad
	0\le a_1(v) \le \ldots \le a_{|D(v)|}(v) \le \alpha k
	\,.
	\]
Meanwhile, to each clause $a$ we attach $D(a)=\set{1,\ldots,k-1}$ to indicate the $k-1$ child variables of $a$. In this view, 
an embedding $\zeta:T'\hookrightarrow\mathscr{T}$ can be specified by giving $D_{T'}(v)\subseteq D(v)$ and $D_{T'}(a)\subseteq D(a)$ for the variables and clauses of $T'$.
Moreover, if $D$ is a Poisson point process of unit rate on $[0,\alpha k]$, and $D_\circ$ is a finite subset of $[0,\alpha k]$, then (by standard properties of Poisson point processes) the law of $D$ conditioned to contain $D_\circ$ is the same as the law of $D\cup D_\circ$. The volume (under Lebesgue measure) of all possible $D_{T'}(v)$ is given by
	\[\Bigg|\Bigg\{
	\bigg(a_i : 1\le i\le |D_{T'}(v)|\bigg) :
	0\le a_1 \le \ldots \le a_{|D_{T'}(v)|}
	\le \alpha k\Bigg\}\Bigg|
	= \frac{(\alpha k)^{|D_{T'}(v)|}}{|D_{T'}(v)|!}\,.
	\]
The volume (under counting measure) of all possible $D_{T'}(a)$ is given by
	\[\Bigg|
	\bigg(v_j : 1\le j\le D_{T'}(a)\bigg)
	: v_j \textup{ integer-valued},
	1\le v_1 \le \ldots \le v_{|D_{T'}(a)|} \le k
	\Bigg|
	= \binom{k}{|D_{T'}(a)|}\,.
	\]
It follows that the expected volume of all embeddings
$\zeta:T'\to\mathscr{T}$ is
	\begin{align}\nonumber
	\textup{\textsf{emb}}(T') &\equiv \int
	\bigg|\bigg\{
	\textup{embeddings }
	\zeta : T'\hookrightarrow\mathscr{T}
	\bigg\}
	\bigg|
	\,d{\textup{\textbf{PGW}}}(\mathscr{T})\\
	&=\prod_{v\in V_{T'}} 
	\frac{(\alpha k)^{|D_{T'}(v)|}}{|D_{T'}(v)|!}
	\prod_{a\in F_{T'}}
	\binom{k}{|D_{T'}(a)|}
	\le (\alpha k)^{|F_{T'}|}
	k^{|V_{T'}|-1} 
	\le (\alpha k^2)^{\ell'\mathfrak{c}}\,.
	\label{e:lebesgue.vol.of.embeddings}
	\end{align}
The law of $\mathscr{T}$ conditioned on any such embedding is equivalent to its law under the measure ${\textup{\textbf{PGW}}}(T')$ described in Definition~\ref{d:PGW.based.on.T}. The expectation 
\eqref{e:expected.number.of.embeddings} is then equal to
	\begin{equation}\label{e:embeddings.times.embedded.probab}
	\textup{\textsf{emb}}(T') \cdot
	\Big[{\textup{\textbf{PGW}}}(T')\Big]\bigg(
	B' \subseteq D^{*,\mathfrak{i}}
	\bigg)
	\end{equation}
where $\textup{\textsf{emb}}(T')\le (\alpha k^2)^{\ell'\mathfrak{c}}\le (\alpha k^2)^{\ell\kappa_*\mathfrak{c}}$.\smallskip

\noindent\bemph{Step 3. Probability bound for $T'$.} We now bound the last term in \eqref{e:embeddings.times.embedded.probab},
recalling that $T'\in\bm{\Lambda}_{\mathfrak{c}+1,\ell'}$
and $B'\subseteq V_{T'}$
with $|B'|=\lceil \ell\epsilon/\mathfrak{c}^{8\kappa_*}\rceil$. The main difficulty is that the neighborhoods $B_R(u)\subseteq\mathscr{T}$, for $u\in B'$, need not be disjoint, since we only ensure that variables in $B'$ have pairwise distance at least $2\kappa_*$ for $\kappa_*$ an absolute constant. This can be addressed by a simple modification: for $u\in B'$, consider $B_R(u)$ as a tree rooted as $u$. In this $u$-rooted tree, take each $w\in T'\cap \partial_2 u$ and delete the subtree descended from it (without deleting $w$ itself). Denote the result $B_R(u)^-\subseteq B_R(u)$. The modified neighborhoods $B_R(u)^-$, for $u\in B'$, are mutually disjoint. Define the depth-two subtree $T_u \equiv T' \cap B_2(u)$, and note that $B_R(u)^-$ has the same law as the random tree $\mathscr{T}_R(u)^-$ defined as follows: first sample $\mathscr{T}'\sim{\textup{\textbf{PGW}}}(T_u)$ (rooted at $u$), then form $\mathscr{T}''$ by deleting from $\mathscr{T}'$ the subtrees of depth-two variables in $T_u$, then form $\mathscr{T}_R(u)^-$ by taking the $R$-neighborhood of the root of $\mathscr{T}''$. If the root of $\mathscr{T}'$ is $(\mathfrak{c}+1)^4$-robust, then $\mathscr{T}_R(u)^-$ must be $1$-nice. It follows that
	\begin{equation}\label{e:product.over.disjoint.nbhds.around.sparse.tree}
	\Big[{\textup{\textbf{PGW}}}(T')\Big]\bigg(
	B' \subseteq D^{*,\mathfrak{i}}
	\bigg)
	\le
	\prod_{u\in B'}
	\Big[{\textup{\textbf{PGW}}}(T_u)\Big]
	\bigg(\textup{root of $\mathscr{T}'$
	is not $(\mathfrak{c}+1)^4$-robust}\bigg)
	\le 
	\frac1{\exp(\Omega(|B'| k2^{k/4}))}\end{equation}
--- in the intermediate expression we use $\mathscr{T}'$ to denote a random variable with law ${\textup{\textbf{PGW}}}(T_u)$, and the last bound is by Proposition~\ref{p:uPGW.is.J.robust}. We can substitute this last bound into 
\eqref{e:embeddings.times.embedded.probab},
which we recall is equal to \eqref{e:expected.number.of.embeddings}. Enumerating over all pairs $(T',B')$ 
(such that $T'\in\bm{\Lambda}_{\mathfrak{c}+1,\ell}$ for $\ell\le \ell'\le \ell\kappa_*$, and 
$B'\subseteq V_{T'}$
with $|B'|=\lceil \ell\epsilon/\mathfrak{c}^{8\kappa_*}\rceil$)
gives
	\begin{align*}
	&\sum_{T',B'}
	\int
	\bigg|\bigg\{
	\textup{embeddings }
	\zeta : T'\hookrightarrow\mathscr{T}
	\textup{ such that }
	\zeta(B')
	\subseteq D^{*,\mathfrak{i}}(\mathscr{T})
	\bigg\}
	\bigg|
	\,d{\textup{\textbf{PGW}}}(\mathscr{T})\\
	&\le 
	\sum_{\ell\le \ell'\le\ell\kappa_*}
	\frac{ (\mathfrak{c}+2)^{\ell'(\mathfrak{c}+2)}
		2^{\ell'}
		(\alpha k^2)^{\ell'\mathfrak{c}}
	}{\exp(
	\Omega(
	\lceil\ell\epsilon/\mathfrak{c}^{8\kappa_*}\rceil
	\cdot
	k2^{k/4}))}
	\le \frac{ \exp( \ell \kappa_* \mathfrak{c} k)}
	{ \exp(
	2^{k/4}\ell\epsilon 
	 ) }\,,
	\end{align*}
for $k$ exceeding an absolute constant. The claimed bound follows.
\end{proof}

