\label{d:thick}
For $T\in \bm{\Lambda}_{\mathfrak{c},\ell}(\mathscr{T})$ and $S\subseteq V_T$,
we say that the pair $(T,S)$ is \bemph{$\epsilon$-thick}
(in $\mathscr{T}$) if the neighborhoods $B_{\bar{\gamma}(u)}(u)$ for $u\in S$ are mutually disjoint with
	\[	\sum_{u\in S}
	\Big(\bar{\gamma}(u) -1\Big) 
	\ge \ell\epsilon\,.
	\]
(Note that variables $u$ with $\bar{\gamma}(u)=1$ give no contribution to the above sum.) We then say that $T$ is \bemph{$\epsilon$-thick} if $(T,S)$ is \bemph{$\epsilon$-thick} for some $S\subseteq V_T$.

\label{l:thick.sparse.subtree}
For $k\ge k_0$ (an absolute constant depending only on the absolute constant $\delta_*$), we have
		\[
	{\textup{\textbf{PGW}}}\bigg(
	\text{some $T\in\bm{\Lambda}_{3,\ell}(\mathscr{T})$
	is $\epsilon$-thick in $\mathscr{T}$}\bigg)
	\le \frac{\exp(k^2\ell) }
		{ \exp\{
		2^{ k\delta_*/2}
	\ell\epsilon/k^5
		\} }
	\]
for all $\epsilon\ge0$ and integer $\ell\ge0$.

\begin{proof}
We shall bound the expected number of $\epsilon$-thick subtrees of $\mathscr{T}$. To this end, first let us fix a sparse tree $T\in\bm{\Lambda}_{3,\ell}$ and a subset of variables $S\subseteq V_T$. Similarly as in the proof of Proposition~\ref{p:sparse.subtree.with.many.defects}
(cf.\ \eqref{e:expected.number.of.embeddings}~and~\eqref{e:embeddings.times.embedded.probab}), we 
use Markov's inequality to bound
	\begin{align}\nonumber
	&{\textup{\textbf{PGW}}}\bigg(
	\textup{there exists an
	 embedding $\zeta:T\hookrightarrow\mathscr{T}$
	such that $(\zeta(T),\zeta(S))$
	 is $\epsilon$-thick in $\mathscr{T}$}
	\bigg) \\ \nonumber
	&\le
	\int\bigg|\bigg\{
	\textup{embeddings
	$\zeta:T\hookrightarrow\mathscr{T}$
	such that $(\zeta(T),\zeta(S))$
	 is $\epsilon$-thick in $\mathscr{T}$}
	\bigg\}\bigg| \,d{\textup{\textbf{PGW}}}(\mathscr{T})\\
	&\le (\alpha k^2)^{3\ell}
	\cdot \Big[{\textup{\textbf{PGW}}}(T) \Big]\bigg(
		\textup{$(T,S)$ is $\epsilon$-thick
		in $\mathscr{T}$}\bigg)\,,
	\label{e:expected.number.of.thick.subtrees}
	\end{align}
where in the last line $(\alpha k^2)^{3\ell}$ is an upper bound on $\textup{\textsf{emb}}(T)$ (similar to \eqref{e:lebesgue.vol.of.embeddings}). Now let $\lambda$ denote any tuple of integers $(\lambda(u):u\in S)$ such that $\lambda(u)\ge 1$ for all $u\in S$, and 
	\[|\lambda|
	\equiv \sum_{u\in S}\lambda(u)
	\ge \ell\epsilon\,.
	\]
Recalling the definition \eqref{e:gamma.bar} of $\bar{\gamma}$, we see that if $\bar{\gamma}(u) -1 \ge\lambda(u)\ge1$ then the ball $|B_{\lambda(u)}(u)|\subseteq\mathscr{T}$ must be large. Therefore, writing $T_u$ for the tree $T \cap B_{\lambda(u)}(u)$ 
rerooted at $u$, we have
	\begin{align*}
	&\Big[{\textup{\textbf{PGW}}}(T) \Big]\Bigg(
		\textup{$(T,S)$ is $\epsilon$-thick
		in $\mathscr{T}$}\Bigg)\\
	&\le
	\sum_\lambda
	\Big[{\textup{\textbf{PGW}}}(T) \Big]
	\Bigg(
	\hspace{-3pt}\begin{array}{c}
	\textup{$|B_{\lambda(u)}(u)|
		\ge \exp\{(k\ln2) (1+\delta_*/2) \lambda(u) \}$}\\
	\textup{for all $u\in S$, and the $B_{\lambda(u)}(u)$
	 are mutually disjoint}
	\end{array}\hspace{-3pt}
	\Bigg)\\
	&\le
	\sum_\lambda
	\prod_{u\in S}
		\Big[ {\textup{\textbf{PGW}}}(T_u)\Big]
	\Bigg( 
	\Big|B_{\lambda(u)}(v_\textup{\textsc{rt}})\Big|
	\ge \exp\bigg\{
		(k\ln2) \bigg(1+\frac{\delta_*}2\bigg)
		\lambda(u)\bigg\}
	 \Bigg)\\
	&\le
	\sum_\lambda
	\prod_{u\in S}\Bigg\{ 
	2 \bigg( \frac{e}
		{ \exp\{ (2^{k\delta_*/2}/k^3)^{\lambda(u)}
			 \} }\bigg)^{1/2}
			 \Bigg\}\,,
	\end{align*}
where the last inequality follows by
Lemma~\ref{l:martingale.bound.PGW}, Lemma~\ref{l:radon.derivative.pgwT},
and the Cauchy--Schwarz inequality. Note that for all $A\ge e$ and $x\ge1$ we have $\ln x \le x-1 \le (\ln A)(x-1)$,
and rearranging gives $A^x\ge Ax$. It follows that
	\[\Big[{\textup{\textbf{PGW}}}(T) \Big]\bigg(
		\textup{$(T,S)$ is $\epsilon$-thick
		in $\mathscr{T}$}\bigg)
	\le\sum_\lambda
	\frac{\exp\{O(1)|S|\}}{ \exp\{
	(2^{k\delta_*/2}/k^3) |\lambda| / 2 
	\} }\]
(where, as always, $O(1)$ refers to an absolute constant). Note that $|S|\le\ell$,
and the number of distinct tuples $\lambda$
with $|\lambda|=L$ is crudely upper bounded by
	\[\binom{L-1}{|S|-1} \le 2^L\,.\]
Substituting these bounds into the preceding calculation gives
	\[\Big[{\textup{\textbf{PGW}}}(T) \Big]\bigg(
		\textup{$(T,S)$ is $\epsilon$-thick
		in $\mathscr{T}$}\bigg)
		\le 
	\sum_{L\ge \ell\epsilon}
	\frac{2^L \exp( O(\ell))}{
	\exp\{ (2^{k\delta_*/2}/k^3) L/2 \}
	}
	\le \frac{\exp(O(\ell))}
		{\exp\{2^{k\delta_*/2}\ell\epsilon /k^4
		 \} }\,.
	\]
The result follows by substituting this into \eqref{e:expected.number.of.thick.subtrees},
and then summing over all $(T,S)$. (The size of $\bm{\Lambda}_{3,\ell}$ is bounded by $\exp(O(\ell))$;
and for any given $T\in\bm{\Lambda}_{3,\ell}$,
the number of subsets $S\subseteq V_T$ is clearly at most $2^\ell$.)
