	\mathbb{P}_{n,m}\bigg(\zeta' : T' \hookrightarrow_{\bm{j}} \mathscr{G}\bigg)
	\mathbb{P}_{n,m}\bigg(\hspace{-3pt}\begin{array}{c}
	\textup{$\zeta'(B') \subseteq A(\mathscr{G})$ and}\\
	\textup{$\zeta'(T') \cup B_R( \zeta'(B');\mathscr{G})$ is acyclic}
	\end{array}\hspace{-3pt}
	\,\bigg|\,\zeta' : T' \hookrightarrow_{\bm{j}} \mathscr{G}\bigg)\,.
