	\[
	\frac{\mathbb{P}( \textup{Bin}(mk,1/n) =j)}
	{\mathbb{P}( \textup{\textsf{Pois}}(\alpha k) =j)}
	= \binom{mk}{j} \frac1{n^j} \bigg(1-\frac1n\bigg)^{mk-j}
