\label{l:nbhd.growth.in.erdos.renyi} If $1\le L \le (\ln n)/k^2$ and $\gamma \le \exp(-k^2 L)/k$, then
	\[
	\mathbb{P}\bigg( 
	\hspace{-3pt}\begin{array}{c}
	\textup{there exists a subset $S\subseteq V$ with}\\
	\textup{$|S|=n\gamma$ and $|B_L(S)|\ge n\gamma \exp(k^2 L)$}
	\end{array}\hspace{-3pt}
	\bigg)
	\le \frac1{\exp(n e^{kL} \gamma)}\,.
	\]

\begin{proof}
As in the proof of Lemma~\ref{l:corrupt.tree.in.erdos.renyi}, we fix $m$ satisfying \eqref{e:condition.on.number.of.clauses} and consider $\mathscr{G}\sim\mathbb{P}\equiv\mathbb{P}_{n,m}$. We then fix a subset $S\subseteq V$ of size $|S|=n\gamma$, and explore its neighborhood by breadth-first search. Let $Z_\ell(S)$ denote the number of variables at distance exactly $\ell$ from $S$. Note that
	\begin{equation}\label{e:bfs.in.graph.bound}
	\mathbb{E}\bigg( \exp \bigg\{\frac{ Z_\ell(S) }{(\alpha k^2)^\ell}\bigg\}
		\,\bigg|\, B_{\ell-1}(S) \bigg)
	\le
	\mathbb{E}\bigg( \exp \bigg\{\frac{
	\textup{Bin}\Big(mk, \frac{Z_{\ell-1}(S)}{n-|B_{\ell-1}(S)|} \Big) }{(\alpha k^2)^\ell}\bigg\}
		\,\bigg|\, B_{\ell-1}(S) \bigg)\,.\end{equation}
Let $F_\ell$ be the event that $|Z_\ell(S)| \le n\gamma \exp(k^{3/2}{L})$, and let $E_\ell \equiv F_1 \cap \cdots \cap F_\ell$. On the event $E_{\ell-1}$ the neighborhood $B_{\ell-1}(S)$ cannot be too large (crudely, by the assumption on $\gamma$, it contains less than $1/k$ fraction of $V$), and it follows from \eqref{e:bfs.in.graph.bound} that
	\[
	\mathbb{E}\bigg( \exp \bigg\{\frac{ Z_\ell(S) }{(\alpha k^2)^\ell}\bigg\}
		; E_{\ell-1} \bigg)
	\le 
	\mathbb{E}\bigg(
	\exp \bigg\{ \frac{ Z_{\ell-1}(S) O(1/k) }{(\alpha k^2)^{\ell-1}}
		\bigg\}
		; E_{\ell-1} \bigg)
	\le
	\mathbb{E}\bigg(
	\exp \bigg\{\frac{ Z_{\ell-1}(S) }{(\alpha k^2)^{\ell-1}}\bigg\}
		; E_{\ell-1} \bigg) \le e\,,
	\]
where the last bound holds by induction on $\ell$. It then follows by Markov's inequality that
	\[
	\mathbb{P}\Big( E_{\ell-1} \Big\backslash F_\ell \Big)
	\le \mathbb{P}\bigg( 
	\exp \bigg\{\frac{ Z_\ell(S) }{(\alpha k^2)^\ell}\bigg\}
	\ge \exp \bigg\{ \frac{n\gamma \exp(k^{3/2}L)}{(\alpha k^2)^\ell}\bigg\}
	 ; E_{\ell-1}\bigg)
	\le \frac{e}{\exp(n\gamma \exp(k^{3/2}L/2))}\,.
	\]
Summing the last bound over $1\le\ell\le L$ gives
	\[
	\mathbb{P}\Big((E_L)^c\Big)
	= \sum_{\ell=1}^L \mathbb{P}\Big( E_{\ell-1} \Big\backslash F_\ell\Big)
	\le 
		 \frac{L e}{\exp(n\gamma \exp(k^{3/2}L/2))}
	\le \frac1{\exp(n\gamma \exp(k^{3/2} L/3) )}\,.
	\]
The claim follows by enumerating over at most $2^{n\gamma}$ choices for the subset $S\subseteq V$.
\end{proof}

