	\textup{$v$ lies within distance $10R$ of 
	a connected component of}\\
	\textup{$\textup{\textsf{BSP}}'(A;\mathscr{G})$ having diameter at most 
	$L_{\textup{\textsf{BSP}}'}\equiv (\ln n)/2^{k\delta_*/5}$}
	\end{array}
	\bigg\}
	\le Y_v\,.
	\]
We first argue that, with high probability, $Y_v=\bar{Y}_v$ for all $v\in V$.
Indeed, Proposition~\ref{p:corrupted.tree.in.graph} implies that if 
$\textup{\textsf{BSP}}'(A;\mathscr{G})$ has a connected component of diameter more than $L_{\textup{\textsf{BSP}}'}$, then either (i) there is a connected subgraph $B'\subseteq\mathscr{G}$ with $\textup{diam} B' \le 11 L_{\textup{\textsf{BSP}}'}/5$ that contains more than one cycle, or (ii) there is a $1/(80R)$-corrupted subtree $T'\subseteq\mathscr{G}$ that has maximum degree at most four and $\textup{diam} T \ge L_{\textup{\textsf{BSP}}'}/5$. Thus
	\begin{align*}
	\mathbb{P}\bigg(
	\hspace{-3pt}\begin{array}{c}
	Y_v\ne \bar{Y}_v\\ \textup{ for any }v\in V
	\end{array}\hspace{-3pt}\bigg)
	&\le
	\sum_{v\in V} \bigg\{
	\mathbb{P}\bigg(\hspace{-3pt}\begin{array}{c}
	\textup{$B_{11L_{\textup{\textsf{BSP}}'}/5}(v)$ contains}\\
	\textup{more than one cycle}
	\end{array}\hspace{-3pt}\bigg)
	+\mathbb{P}\bigg(\hspace{-3pt}\begin{array}{c}
	\textup{some $T\in\bm{\Lambda}_{4, L_{\textup{\textsf{BSP}}'}/5 }(\mathscr{G}, v)$}\\
	\textup{is $1/(80R)$-corrupt}
	\end{array}\hspace{-3pt}\bigg)
	\bigg\}\\
	&\stackrel{\odot}{\le}
	n \bigg\{
	\bigg( \frac{\exp(5 L_{\textup{\textsf{BSP}}'} k^2)}{n}\bigg)^2
	+
	\frac1{\exp\{ 2^{k\delta_*/4} L_{\textup{\textsf{BSP}}'}/ k^2 \}}
	\bigg\}
	=o_n(1)\,,
	\end{align*}
where the bound marked $\odot$ follows from Lemma~\ref{l:corrupt.tree.in.erdos.renyi} together with very crude bounds on the chance to see more than one cycle in a neighborhood of $v$ of radius $5L_{\textup{\textsf{BSP}}'}$. This proves that $Y=\bar{Y}$ with high probability where
	\[
	Y\equiv\sum_{v\in V} Y_v\,,\quad
	\bar{Y}\equiv \sum_{v\in V} \bar{Y}_v\,.
	\]
We now turn to estimating $\bar{Y}$. Let $B'(\ell)$ be the union of all connected components of $\textup{\textsf{BSP}}'(A;\mathscr{G})$ of diameter $\ell$ that contain more than one cycle; and let $T'(\ell)$ be the union of all subtrees of $\textup{\textsf{BSP}}'(A;\mathscr{G})$ of diameter at least $\ell$ that are $1/(80R)$-corrupted. Let $A'(\ell)\equiv B'(\ell) \cup T'(\ell/5)$. Proposition~\ref{p:corrupted.tree.in.graph} implies that if $\bar{Y}_v=1$, then either $v$ lies within distance $2010R$ from $A$, or $v$ lies within distance $\ell+10R$ from $A'(\ell)$ for some $2000R\le\ell \le L_{\textup{\textsf{BSP}}'}$. Therefore
	\begin{equation}\label{e:expected.size.of.removed.component}
	\mathbb{E}\bar{Y}
	\le
	\mathbb{E} \Big|B_{2010R}(A)\Big|
	+\sum_{\ell= 2000R}^{L_{\textup{\textsf{BSP}}'}} \mathbb{E} \Big|B_{\ell+10R}(A'(\ell))\Big|\,.
	\end{equation}
Let $\gamma=\exp(-2^{k\delta_*/4} R / (2k))$, and note that 
Corollary~\ref{c:excellent.under.uPGW.T} together with Markov's inequality gives
	\[
	\mathbb{P}\Big(|A|\ge n\gamma\Big)
	\le
	\frac{\mathbb{E} A}{n\gamma}
	= \frac{\mathbb{P}(v\in A)}{\gamma}
	\le 
	\frac{\exp(2^{k\delta_*/4} R / (2k))}
	{\exp(2^{k\delta_*/4} R / k)}
	= \gamma\,.
	\]
Combining with Lemma~\ref{l:nbhd.growth.in.erdos.renyi}
gives, for $L=2010R$ and $\gamma=\exp(-2^{k\delta_*/4} R / (2k))$,
	\begin{align}\nonumber
	\mathbb{E} \Big|B_{2010R}(A)\Big|
	&\le 
	n\gamma \exp(k^2 L)
	+n\mathbb{P}\Big( |A| \ge n \gamma\Big)
	+n
	\mathbb{P}\bigg( 
	\hspace{-3pt}\begin{array}{c}
	\textup{there exists $S\subseteq V$ with $|S|=n\gamma$}\\
	\textup{and $|B_L(S)|\ge n\gamma \exp(k^2 L)$}
	\end{array}\hspace{-3pt}
	\bigg) \\
	&\le
	\frac{n \exp(2010k^2 R)}
		{\exp(2^{k\delta_*/4} R / (2k)) }
	+ \frac{n}{ \exp(2^{k\delta_*/4} R / (2k)) }
	+ \frac{n}{\exp(n e^{kL} \gamma)}
	\le \frac{n}{ \exp(2^{k\delta_*/4} R / (3k)) }\,.
	\label{e:bound.nbd.of.A}
	\end{align}
Similarly, if we take $\gamma_\ell=\exp(-2^{k\delta_*/4}\ell/ k^2)$, then Lemma~\ref{l:corrupt.tree.in.erdos.renyi} together with Markov's inequality gives
	\[
	\mathbb{P}(|A'(\ell)| \ge n\gamma_\ell)
	\le \frac{\mathbb{E}|A'(\ell)|}{n\gamma_\ell}
	\le \frac{\mathbb{P}(v\in A'(\ell))}{\gamma_\ell}
	\le o_n(1) + \frac{\exp( 2^{k\delta_*/4}\ell/ k^2 )}
				{\exp( 2^{k\delta_*/4} \Omega(\ell/ k ))}
	\le \gamma_\ell\,,
	\]
where the $o_n(1)$ error term accounts for the probability that $B_\ell(v)$ contains more than one cycle. Combining with Lemma~\ref{l:nbhd.growth.in.erdos.renyi} gives
	\begin{align}\nonumber
	\mathbb{E}\Big| B_{\ell+10R}(A'(\ell))\Big|
	&\le n\gamma_\ell \exp(k^2(\ell+10R))
	+n\mathbb{P}\Big(|A'(\ell)| \ge n\gamma_\ell\Big)
	+n\mathbb{P}\bigg( 
	\hspace{-3pt}\begin{array}{c}
	\textup{there exists $S\subseteq V$ with
		$|S|=n\gamma_\ell$ and}\\
	\textup{$|B_{\ell+10R}(S)|\ge n\gamma_\ell
		\exp(k^2(\ell+10R))$}
	\end{array}\hspace{-3pt}
	\bigg) \\
	&\le
	\frac{n \exp(k^2(\ell+10R))}{\exp(2^{k\delta_*/4}\ell/ k^2)}
	+ \frac{n}{\exp(2^{k\delta_*/4}\ell/ k^2)}
	+ \frac{n}{\exp(n e^{k(\ell+10R)} \gamma_\ell)}
	\le \frac{n}{\exp(2^{k\delta_*/4}\ell/ k^3)}\,,
	\label{e:bound.nbd.of.A.ell}
	\end{align}
for all $\ell\ge2000R$. Substituting \eqref{e:bound.nbd.of.A} and \eqref{e:bound.nbd.of.A.ell} into \eqref{e:expected.size.of.removed.component} gives
	\[
	\mathbb{E} \bar{Y}
	\le \frac{n}{\exp(2^{k\delta_*/4} R / k^4)}\,.
	\]
Next note that under $\mathbb{P}_{n,m}$, for any $u\ne v$ the radius-$(L_{\textup{\textsf{BSP}}'}+10R)$ neighborhoods of $u$ and $v$ intersect with chance $o_n(1)$, and so are nearly independent of one another. If follows that $\mathrm{Cov}(\bar{Y}_u,\bar{Y}_v) = o_n(1)$. Therefore
	\[
	\mathrm{Var}\bar{Y} \le n
	+ \sum_{u\ne v} \mathrm{Cov}(\bar{Y}_u,\bar{Y}_v) = o_n(n^2)\,.
	\]
We can then use Chebychev's inequality to conclude that
	\[
	\mathbb{P}\bigg(\bar{Y} \ge \frac{n}{\exp(2^{k\delta_*/5} R)} \bigg)
	\le
	\mathbb{P}\Big(\bar{Y} \ge 2 \mathbb{E}\bar{Y} \Big)
	\le \frac{\mathrm{Var} \bar{Y}}{ (\mathbb{E}\bar{Y})^2} = o_n(1)\,.
	\]
Since we already argued above that $\mathbb{P}(Y\ne\bar{Y})=o_n(1)$, the result follows.

