\label{d:tree.based.on.feasible.type}
Given a feasible clause total type $\bm{L}$, we now construct a corresponding tree $\mathscr{T}(\bm{L})$ as follows. Among all pairs $(\mathscr{H},a_\star)$ for which the conditions of Definition~\ref{d:feasible.clause.type} hold, fix one such that $\mathscr{H}$ has minimal size. Let $\mathscr{T}_\star$ be the $(4R)$-neighborhood of $a_\star$ in $\mathscr{H}$, which we regard as a tree rooted at $a_\star$. We regard $L_0,L_\infty$ as subtrees of $\mathscr{T}_\star$, and make the following definitions:
\begin{enumerate}[a.]
\item Let $V_1$ denote the set of variables of $L_0\setminus L_\infty$ which neighbor some clause in $L_\infty$. For each $v\in V_1$, let $\mathscr{T}_\star(v,\ell)$ be the subtree of $\mathscr{T}_\star$ induced by all the descendants of $v$ that lie within distance $\ell$ of $v$. Let $Y_\textup{out}(v)$ be the variables in $\mathscr{T}_\star(v)$ that lie at depth exactly $R$ below $v$ --- we will argue in the proof of Corollary~\ref{c:event.implies.desired.type} below that $Y_\textup{out}(v)$ is nonempty for all $v\in V_1$. We take a union over $V_1$ to define
	\begin{equation}\label{e:defn.Tout}
	\mathscr{T}_{\star,\textup{out}}
		\equiv\bigcup_{v\in V_1} \mathscr{T}_\star(v,2R)\,,\quad
	\mathscr{N}_\textup{out}\equiv\bigcup_{v\in V_1} \mathscr{T}_\star(v,R-1)\,,\quad
	Y_\textup{out}\equiv\bigcup_{v\in V_1} Y_\textup{out}(v)\,.
	\end{equation}
For each $y\in Y_\textup{out}$, let $Z_\textup{out}(y)$ be the variables that lie at depth exactly $R$ below $y$. If $Z_\textup{out}(y)$ is nonempty, then we fix an arbitrary $w\in Z_\textup{out}(v)$, and modify $w$ by redefining $\bm{l}(w)$ to be the same as $\bm{l}(v)$ where $v$ is the ancestor of $y$ in $V_1$. We let $\mathscr{T}_\textup{out}$ denote the resulting modification of $\mathscr{T}_{\star,\textup{out}}$ (the two graphs can differ only in the markings $\bm{l}$ at the last level).

\item Now let $\mathscr{T}_{\star\star}$ be the component of $\mathscr{T}_\star\setminus\mathscr{T}_\textup{out}$ that contains the root clause $a_\star$. Let $W$ denote the variables at the boundary of $L_\infty$. From the definition of the processing algorithm, each variable left in $\textup{\textsf{pr}}\mathscr{H}$ is $1$-good, which means (Definition~\ref{d:good.exc}) that any length-$(2R/5)$ path emanating from the variable must contain at least one variable that is $1$-excellent. This in turn means we can find a set $X$ of $1$-excellent variables that lie below $W$, at distance at most $2R/5$ from $W$, such that $X$ forms a cutset in $\mathscr{T}_{\star\star}$ that encloses $L_\infty$. Let $Y$ be the variables in $\mathscr{T}_{\star\star}$ that lie at depth exactly $R/10$ below $X$. Let $\mathscr{T}_\textup{in}$ be the subtree of $\mathscr{T}_{\star\star}$ enclosed by $Y$. 
\end{enumerate}
Let $\mathscr{T}(\bm{L})$ be the subtree of $\mathscr{T}_\star$ induced by the union of $\mathscr{T}_\textup{in}$ and $\mathscr{T}_\textup{out}$.

\label{d:pos.frac.events}
Fix a feasible type $\bm{L}$, and let $\mathscr{T}(\bm{L})$ be as given by Definition~\ref{d:tree.based.on.feasible.type}, rooted at clause $a_\star$. Let $\mathscr{G}=(V,F,E)$ be sampled from $\mathbb{P}_{n,m}$. For any clause $a\in F$, we let $\bm{E}_a\equiv\bm{E}_a(\bm{L})$ be the event that $\mathscr{T}'\equiv B_{4R}(a;\mathscr{G})$ is a tree, and there is an embedding $\phi:\mathscr{T}(\bm{L})\hookrightarrow\mathscr{T}'$ that maps $a_\star\mapsto a$, and satisfies the following:
\begin{enumerate}[(i)]
\item \label{Ea.i} For any variable $v\in \phi(\mathscr{T}(\bm{L}))\subseteq\mathscr{T}'$, either all or none of its child variables (with respect to $\mathscr{T}'$) lie in $\phi(\mathscr{T}(\bm{L}))$.

\item \label{Ea.ii} For any variable $v\in V_1$, the subtree of $v$ in $\mathscr{T}(\bm{L})$ agrees with the depth-$2R$ subtree of $\phi(v)$ in $\mathscr{T}'$.
\end{enumerate}
If $\bm{E}_a$ occurs, let $X'$ be the cutset of variables in $\mathscr{T}'$ lying at distance exactly $R/10$ below $\phi(Y)$. Let $Z$ be the cutset of
variables in $\mathscr{T}'$ lying at distance exactly $R$ below $\phi(Y)$. Let $\mathscr{U}$ be the subgraph of $\mathscr{T}'$ that lies sandwiched between $\phi(X)$ and $X'$ (inclusive). Let $\mathscr{N}$ be the subgraph of $\mathscr{T}'$ that lies sandwiched between $\phi(Y)$ and $Z$, including $\phi(Y)$ but not including $Z$. Let $\bm{G}_a\equiv\bm{G}_a(\bm{L})$ denote the event that $\mathscr{G}\in\bm{E}_a$, and moreover satisfies the following:
\begin{enumerate}[(I)]
\item \label{i:Tin.and.P.are.proper} All variables in $\phi(\mathscr{T}_\textup{in})\cup\mathscr{N}$ are proper;
\item \label{i:Tin.Tout.diff.labels} $\bm{l}(u)\ne\bm{l}(w)$
for any $u\in\phi(\mathscr{T}_\textup{out})$ and $w\in\phi(\mathscr{T}_\textup{in})\cup\mathscr{N}$; 
\item \label{i:U.is.fair} All variables in $\mathscr{U}$ are $1$-fair;
\item \label{i:Xprime.is.excellent} All variables in $X'$ are $1$-excellent.
\end{enumerate}
If $\bm{E}_a$ occurs, then we also define the subgraph
	\begin{equation}\label{e:Gprime.cavity}
