	\,\bigg|\, \bm{J} \bigg) = o_n(1)\,.\end{equation}
Recall that $|Y| \le \exp(O(k^2 R))$. It follows by combining \eqref{e:small.removal.with.girth.cond}~and~\eqref{e:exchangeability.Y} that 
	\begin{align*}
