	\,\Big|\, \bm{J} \Big)
	&\le o_n(1)
		+ \mathbb{P}_{n',m'}\bigg(Y' \cap S(\mathscr{G}') \ne\varnothing
	\,\bigg|\, \bm{J},|S(\mathscr{G}')| < \frac{n'}{\exp(2^{ck}R)} \bigg)
	\\
	&\le o_n(1)+ \frac{\exp(O(k^2 R))}{\exp(2^{ck}R)} \le \frac18\,.
	\end{align*}
The lemma follows by the equivalence \eqref{e:sample.cavity.graph.up.to.isom}.
\end{proof}

