\label{l:clause.bp.weights}
Let $\delta\in(0,1]$ be a fixed constant.
Suppose the clause $a$ receives incoming
variable-to-clause messages $\dot{q}_e$ ($e\in\delta a$)
 whose reweightings $Q_e$ (as defined by \eqref{e:reweighted.messages.single}) satisfy the bounds
	\begin{equation}\label{e:bds.on.red.yellow}
	\max
	\bigg\{ Q_e(y)-\frac12,
	Q_e(\SSPIN{r})
	\bigg\} \le \frac1{2^{k\delta}}
	\end{equation}
for all $e\in\delta a$. Suppose also we have outgoing messages $\tilde{q}_e$ such that, for all $e\in\delta a$, we have
	\begin{equation}\label{e:assumed.bp.error.eps}
	\bigg|\frac{[\textup{\footnotesize\textsf{BP}}_e[\dot{q}]](\sigma)}
		{\tilde{q}_e(\sigma)}-1\bigg|
	\le \begin{cases}
	\epsilon_e 
		&\textup{for }\sigma\in\set{\SSPIN{y},\SSPIN{c}}\,,\\
	\dot{\epsilon}_e
		&\textup{for }\sigma=\SSPIN{r}\,,
	\end{cases}
	\end{equation}
where all the errors $\epsilon_e,\dot{\epsilon_e}$ are at most $1/k^4$. Then there exist edge 
weights $\Gamma\equiv(\gamma_e:e\in\delta a)$
with $\gamma_e(\SSPIN{y})=1$ such that
	\begin{equation}\label{e:resulting.gamma.error.bound}
	\max_{e\in\delta a}
	\Bigg\{\sum_{\sigma\in\set{\SSPIN{r},\SSPIN{c}}}
	|\gamma_e(\sigma)-1|\Bigg\}
	\le k\sum_{e\in\delta a}
		\Big(\epsilon_e+\dot{\epsilon}_e\Big)\,,
	\end{equation}
and such that the $\Gamma$-weighted \textup{\textsc{bp}} recursion at clause $a$ maps $\dot{q}$ to $\tilde{q}$: that is, such that
$\tilde{q}_e=\textup{\footnotesize\textsf{BP}}_e[\dot{q};\Gamma]$ for all $e\in\delta a$.

\begin{proof}
We will iteratively define a sequence of weights $\Gamma^t \equiv (\gamma_{e,t}: e\in\delta a)$, started from $\Gamma^0\equiv1$ and converging in the limit $t\to\infty$ to the desired weights $\Gamma$. We will maintain for all $t$ that $\gamma_{e,t}(\SSPIN{y})=1$. Denote the output of the $\Gamma^t$-weighted recursion by
	\begin{equation}\label{e:weighted.bp}
	\tilde{q}_{e,t}(\sigma)
	\equiv \Big(\textup{\footnotesize\textsf{BP}}_e[\dot{q},\Gamma^t]\Big)(\sigma)
	\cong \gamma_{e,t}(\sigma)
		\bigg\{
		\Big(\textup{\footnotesize\textsf{BP}}_e[\gamma^t\dot{q}]\Big)(\sigma)
		\bigg\}
		\,.\end{equation}


\noindent
\bemph{Step 1. Definition of weights and errors between weights.}
In this step, we fix an edge $e$ and abbreviate
$\gamma\equiv\gamma_e$, 
$\tilde{q}\equiv\tilde{q}_e$, and so on.
Given $\gamma^t$ and $\tilde{q}^t$,
we define the next weight $\gamma^{t+1}$ by setting
	\[\gamma^{t+1}(\sigma)
	\equiv
	\gamma^t(\sigma)
	\cdot
	\frac{\tilde{q}(\sigma)/\tilde{q}(\SSPIN{y})}
	{\tilde{q}^t(\sigma)/\tilde{q}^t(\SSPIN{y})}
	\]
for each $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}$. Note this choice ensures $\gamma^{t+1}(\SSPIN{y})=1$. It remains to estimate the error between $\gamma^t$ and $\gamma^{t+1}$ on the other two colors $\set{\SSPIN{r},\SSPIN{c}}$. To this end, let us define the error quantities
	\begin{equation}\label{e:def.eps.t.sigma}
	\epsilon^t(\sigma)
	\equiv
	\Bigg|
	\frac{\gamma^{t+1}(\sigma)}{\gamma^t(\sigma)}-1
	\Bigg|
	=\Bigg|
	\frac{\tilde{q}(\sigma)/\tilde{q}(\SSPIN{y})}
	{\tilde{q}^t(\sigma)/\tilde{q}^t\SSPIN{y})}
	-1\Bigg|\,.
	\end{equation}
for $\sigma\in\set{\SSPIN{r},\SSPIN{c}}$. 
The error at the next iteration is then given 
(after a short algebraic manipulation) by
	\begin{equation}\label{e:single.iterate.error}
	\epsilon^{t+1}(\sigma)
	=\Bigg|
	\underbrace{\bigg\{
	\frac{\gamma^t(\sigma)}{\gamma^{t+1}(\sigma)}
	\frac{\tilde{q}(\sigma)/\tilde{q}(\SSPIN{y})}
	{\tilde{q}^t(\sigma)/\tilde{q}^t(\SSPIN{y})}
	\bigg\}}_{\textup{equals one}}
	\frac{\tilde{q}^t(\sigma)/(\gamma^t(\sigma)\tilde{q}^t(\SSPIN{y}))}
		{\tilde{q}^{t+1}(\sigma)/
			(\gamma^{t+1}(\sigma)
			\tilde{q}^{t+1}(\SSPIN{y}))}
	-1\Bigg]\,.\end{equation}
For the rest of this proof we use the shorthand
$\epsilon^t\equiv \epsilon^t(\SSPIN{c})$ and $\dot{\epsilon}^t\equiv \epsilon^t(\SSPIN{r})$.\smallskip

\noindent \bemph{Step 2. Errors for variable-to-clause quantities.} In this step we continue to consider a single edge $e\in\delta a$, which we suppress from the notation. As in \eqref{e:reweighted.messages.single},
let $Q^t$ be the reweighted version of $\gamma^t\dot{q}$ defined by
	\begin{equation}\label{e:def.Q.t}
	Q^t(\sigma)
	\equiv
	\frac{\gamma^t(\sigma) \dot{q}(\sigma)}
		{(2^{|\partial a|-1})^{\Ind{\sigma=\SSPIN{r}}}}
	\Bigg/\Bigg\{
	\frac{\gamma^t(\SSPIN{r})\dot{q}(\SSPIN{r})}{2^{|\partial a|-1}}
	+\dot{q}(\SSPIN{y})
	+ \gamma^t(\SSPIN{c})\dot{q}(\SSPIN{c})
	\Bigg\}\,.
	\end{equation}
Recall the assumption \eqref{e:bds.on.red.yellow} that
$Q(\SSPIN{r}) = Q_0(\SSPIN{r}) \le 2^{-k\delta}$. It will follow from the inductive analysis below that all the weights $\gamma^t$ are of constant order, so we will also have $Q^t(\SSPIN{r})\le O(2^{-k\delta})$. It follows that
	\begin{align*}
	\frac{\gamma^{t+1}(\SSPIN{r})\dot{q}(\SSPIN{r})}
