\label{l:sep.colors.given.defect}
Fix a pair $(S,P_S)\in\bm{\Pi}_*(\mathcal{D})$
as in Definition~\ref{d:sep.permissible}.
For the events of Definition~\ref{d:sep.events}, we have
	\[
	\mathbb{Q}_\mathcal{D}\Big(\bm{X}_B,\bm{Y}_B \,\Big|\,\bm{K}_D
	\Big)
	=\mathbb{Q}_\mathcal{D}(\bm{X}_B)
	\mathbb{Q}_\mathcal{D}(\bm{Y}_B)
	\le
	\bigg(\frac{O(1)}{2^k}\bigg)^{|B| + 2|F_B|}\,.
	\]

\begin{proof}
Let $V,F,\delta V,\delta F$ be fixed as in Remark~\ref{r:sample.planted.msr}. The
event $\bm{K}_D$ depends on the matching of half-edges internal to defects.
The event $\bm{X}_B$
concerns the coloring $\bm{\sigma}$
on variable-incident half-edges that will not be internal to defects.
The event $\bm{Y}_B$
concerns the coloring $\bm{\sigma}$
on clause-incident half-edges
that will not be internal to defects.
It follows that the three events are mutually independent, therefore
	\begin{equation}\label{e:sep.independence.across.types}
	\mathbb{Q}_\mathcal{D}\Big(\bm{X}_B,\bm{Y}_B \,\Big|\,\bm{K}_D
	\Big)
	=\mathbb{Q}_\mathcal{D}(\bm{X}_B)\mathbb{Q}_\mathcal{D}(\bm{Y}_B)\,.
	\end{equation}
It follows from Remark~\ref{r:sample.planted.msr} that
$\mathbb{Q}_\mathcal{D}(\bm{X}_B)$
is the probability that a uniformly random element $\bm{\sigma}$ from $
\mathcal{J}$ satisfies the conditions of $\bm{X}_B$.
Suppose we instead sample $\bm{\sigma}:\delta V \sqcup \delta F\to\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$ according to the measure
	\[\check{\mathbb{Q}}_\mathcal{D}(\bm{\sigma})
	=\Bigg\{\prod_{v\in V} 
	\dot{\nu}_v(\bm{\sigma}_{\delta v})
	\Bigg\}\Bigg\{\prod_{a\in F}
	\hat{\nu}_a(\bm{\sigma}_{\delta a})
	\Bigg\}\,,\]
where $(\dot{\nu},\hat{\nu})\equiv\nu\equiv\nu^\textup{op}[{}_\star\hspace{-1pt}\omega]$.
It follows from 
Lemma~\ref{l:nu.star.as.optimizer.for.starpi}
and Corollary~\ref{c:cohere.weights} that
	\[\check{\mathbb{Q}}_\mathcal{D}(\bm{\sigma})
	=\Bigg\{
	\prod_{v\in V} \Bigg(
	\frac{ \varphi_v(\bm{\sigma}_{\delta v}) }{\bm{\dot{z}}_v}
	\prod_{e\in\delta v}
	{}_\star\hspace{-1pt}\hat{q}_e(\bm{\sigma}_e)
	\Bigg)
	\Bigg\}\Bigg\{
	\prod_{a\in F}
	\Bigg(
	\frac{\hat{\varphi}_a(\bm{\sigma}_{\delta a}}
	{ \bm{\hat{z}}_a }
	\prod_{f \in \delta a}\bigg(
	\gamma_f(\bm{\sigma}_f)
	{}_\star\hspace{-1pt}\dot{q}_f(\bm{\sigma}_f)\bigg)
	\Bigg)\Bigg\}\,.\]
Moreover, if $a$ is a clause of type $\bm{L}$
and $e$ is the $j$-th edge in $\delta a$,
then $\gamma_e$ depends only on $(\bm{L},j)$.
Thus each $\bm{\sigma}$ in $\mathcal{J}$ receives precisely the same weight under the measure $\check{\mathbb{Q}}_\mathcal{D}$.
Moreover, if we sample $\bm{\sigma}\sim\check{\mathbb{Q}}_\mathcal{D}$, then the \emph{expected} empirical measure of $\bm{\sigma}$ is $\nu=\nu^\textup{op}$.
Since the total number of types is at most $C(k,R)$, it follows by the local central limit theorem that
$\check{\mathbb{Q}}_\mathcal{D}(\bm{\sigma}\in\mathcal{J}) = 1/n^{O(1)}$, so
	\[
	\mathbb{Q}_\mathcal{D}(\bm{X}_B)
	\le n^{O(1)}
	\check{\mathbb{Q}}_\mathcal{D}(\bm{X}_B)
	= n^{O(1)}
	\prod_{v\in B}
	\dot{\nu}_v( \bm{X}_v)\,.
	\]
A variable $v\in B$ must be non-defective, hence nice
(Definition~\ref{d:nice}). It follows that
	\begin{align*}
	\dot{\nu}_v( \bm{X}_v)
	&=\frac1{\bm{\dot{z}}_v}
	\prod_{e\in \delta v \cap P(v)}
		{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{r})
	\prod_{e\in \delta v(\SPIN{L}) \setminus P(v)}
		{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{b})
	\prod_{e\in \delta v(\SPIN{-}\SPIN{L})}
		{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{y})\\
	&\le O(1)
	\prod_{e\in \delta v \cap P(v)}
		\frac{{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{r})}{{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{b})}
	\prod_{e\in \delta v(\SPIN{L})}
		\frac{{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{b})}{{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{r},\SSPIN{b})}
	\le \frac{O(1)}
	{(2^k)^{1+|P(v)|}}\,.
	\end{align*}
Substituting into the previous calculation gives
	\begin{equation}\label{e:sep.colors.on.vars}
	\mathbb{Q}_\mathcal{D}(\bm{X}_B)
	\le 
	n^{O(1)}
	\bigg(\frac{O(1)}{2^k}\bigg)^{|B|+|F_B|}\,.
	\end{equation}
Similarly, a clause $a\in F_B$ can neighbor at most one defective variable, so it follows from 
Definition~\ref{d:j.defective}
that all the variables in the clause must be nice.
It then follows using 
Corollary~\ref{c:clause.bp.weights.explicit} that
	\[
	\hat{\nu}_a(\bm{Y}_a)
	=\frac1{\bm{\hat{z}}_a}
	\gamma_j(\SSPIN{r}) {}_\star\hspace{-1pt}\dot{q}_j(\SSPIN{r})
	\prod_{\ell\ne j}\bigg\{
	\gamma_\ell(\SSPIN{y})
	{}_\star\hspace{-1pt}\dot{q}_\ell(\SSPIN{y})\bigg\}
	\le
	O(1)
	\frac{{}_\star\hspace{-1pt}\dot{q}_j(\SSPIN{r})}
		{{}_\star\hspace{-1pt}\dot{q}_j(\set{\SSPIN{y},\SSPIN{g},\SSPIN{b}})}
	\prod_{\ell\ne j}
	\frac{{}_\star\hspace{-1pt}\dot{q}_\ell(\SSPIN{y})}
		{{}_\star\hspace{-1pt}\dot{q}_\ell(\set{\SSPIN{y},\SSPIN{g},\SSPIN{b}})}
	\le \frac{O(1)}{2^k}\,.
	\]
It follows by a similar argument as for $\bm{X}_B$ that
	\begin{equation}\label{e:sep.colors.on.clauses}
	\mathbb{Q}_\mathcal{D}(\bm{Y}_B)
	\le n^{O(1)}
	\check{\mathbb{Q}}_\mathcal{D}(\bm{Y}_B)
	\le n^{O(1)}
	\bigg(\frac{O(1)}{2^k}\bigg)^{|B|+|F_B|}\,.
	\end{equation}
The result follows by combining
\eqref{e:sep.independence.across.types},
\eqref{e:sep.colors.on.vars}, and \eqref{e:sep.colors.on.clauses}.
\end{proof}

