\label{l:sep.B.edges.match.bias}
Fix a pair $(S,P_S)\in\bm{\Pi}_*(\mathcal{D})$
as in Definition~\ref{d:sep.permissible}.
For the events of Definition~\ref{d:sep.events}, we have
	\[
	\frac{\mathbb{Q}_\mathcal{D}(\bm{K}_B \,|\, 
	\bm{X}_B,\bm{Y}_B,\bm{K}_D)}
		{\mathbb{P}_\mathcal{D}(\bm{K}_B \,|\, \bm{K}_D)}
	=\frac{\mathbb{Q}_\mathcal{D}(\bm{K}_B \,|\, \bm{X}_B,\bm{Y}_B)}
		{\mathbb{P}_\mathcal{D} (\bm{K}_B)}
	\le \Big(O(1) 2^k\Big)^{|F_B|}
	\,.
	\]

\begin{proof}
Recall from Definition~\ref{d:sep.permissible} that each tuple $(u,j_u,a,j_v,v)\in P_S$
distinguishes an initial half-edge $e_u\in\delta u$
and a final half-edge $e_v\in\delta v$.
For each edge type $\bm{t}$,
let $a_{\bm{t}}(\SSPIN{y})$
count the number of tuples in $P_S$
where the initial half-edge has type $\bm{t}$.
Let $a_{\bm{t}}(\SSPIN{r})$
count the number of tuples in $P_S$
where the final half-edge has type $\bm{t}$.
 Let $a_{\bm{t}}\equiv a_{\bm{t}}(\SSPIN{r})+a_{\bm{t}}(\SSPIN{y})$.
 Then note that
	\[
	\sum_{\bm{t}}
	a_{\bm{t}}(\SSPIN{y})
	=\sum_{\bm{t}}
	a_{\bm{t}}(\SSPIN{r})
	= \frac12\sum_{\bm{t}}a_{\bm{t}}
	= |F_B|\,.
	\]
Since we restricted to clauses in $F_B$, any type $\bm{t}$ with $a_{\bm{t}}>0$ must be nice. The events $\bm{K}_B$ and $\bm{K}_D$ involve edges of distinct types, so they are independent under $\mathbb{P}_\mathcal{D}$. It follows that
	\[
	\mathbb{P}_\mathcal{D}(\bm{K}_B\,|\,\bm{K}_D)
	=\mathbb{P}_\mathcal{D}(\bm{K}_B)
	=\prod_{\bm{t}}
	\Bigg\{
	\prod_{i=0}^{a_{\bm{t}}-1}
	\frac1{n_{\bm{t}}-i}
	\Bigg\}
	=\prod_{\bm{t}}
	\frac1{(n_{\bm{t}})_{a_{\bm{t}}}}
	\]
(using the standard notation for the falling factorial). On the other hand, under the measure $\mathbb{Q}_\mathcal{D}$, if we condition on the events 
$\bm{X}_B$ and $\bm{Y}_B$, then the event $\bm{K}_B$ is more likely to occur because we have conditioned the edges involved to have compatible colorings:
	\[\mathbb{Q}_\mathcal{D}\Big(\bm{K}_B\,\Big|\,
		\bm{X}_B,\bm{Y}_B,\bm{K}_D\Big)
	=\mathbb{Q}_\mathcal{D}\Big(\bm{K}_B\,\Big|\,
		\bm{X}_B,\bm{Y}_B\Big)
	= \prod_{\bm{t}}
	\frac1{
	(n_{\bm{t}}\cdot{}_\star\hspace{-1pt}\pi_{\bm{t}}(\SSPIN{y}))_{a_{\bm{t}}(\SSPIN{y})}
	(n_{\bm{t}}\cdot{}_\star\hspace{-1pt}\pi_{\bm{t}}(\SSPIN{r}))_{a_{\bm{t}}(\SSPIN{r})}
	}\,,
	\]
which is clearly larger than the quantity
$\mathbb{P}_\mathcal{D}(\bm{K}_B\,|\,\bm{K}_D)$ calculated just above. For any integers $0<a<b$ we have using Stirling's formula that
	\[
	b^a \ge (b)_a
	= \frac{b!}{(b-a)!}
	\asymp
	\frac{b^a}{e^a}
	\bigg(\frac{b}{b-a}\bigg)^{1/2+b-a}
	\ge 
	\frac{b^a}{e^a}\,.
	\]
It follows by combining the above that
	\[
		\frac{\mathbb{Q}_\mathcal{D}(\bm{K}_B \,|\, 
	\bm{X}_B,\bm{Y}_B,\bm{K}_D)}
		{\mathbb{P}_\mathcal{D}(\bm{K}_B \,|\, \bm{K}_D)}
	=\frac{\mathbb{Q}_\mathcal{D}(\bm{K}_B \,|\, \bm{X}_B,\bm{Y}_B)}
		{\mathbb{P}_\mathcal{D} (\bm{K}_B)}
	\le
	\prod_{\bm{t}}
	\frac{e^{a_{\bm{t}}}}{
	({}_\star\hspace{-1pt}\pi_{\bm{t}}(\SSPIN{y}))^{a_{\bm{t}}(\SSPIN{y})}
	({}_\star\hspace{-1pt}\pi_{\bm{t}}(\SSPIN{r}))^{a_{\bm{t}}(\SSPIN{r})}
	}
	\le \Big( O(1) 2^k\Big)^{|F_B|}\,,
	\]
as claimed.
\end{proof}

