 \label{d:nu.judicious} Let $T$ be a finite tree rooted at a clause $a_\textup{\textsc{rt}}$ with exactly one child, which we refer to as the root variable $v_\textup{\textsc{rt}}$. We use $\mathcal{L} T$ to denote the set of all leaf vertices of $T$ other than $a_\textup{\textsc{rt}}$, and we assume $\mathcal{L} T$ consists of variables only. We use $\delta T$ to denote the edges incident to $\mathcal{L} T$. From now on we will refer to $\mathcal{L} T$ and $\delta T$ respectively as the ``boundary variables'' and ``boundary edges'' of $T$. 
A small example appears in Figure~\ref{f:nice.subtree.of.compound.enclosure}. 
In the applications of this definition
in the analysis of Section~\ref{s:merge}, we will take $T$
to be a nice (Definition~\ref{d:nice}) subtree of a compound enclosure $U$. As a result, the notations that follow are purposefully similar to those of Definition~\ref{d:constrained.opt.compound.enclosure}. 
Let 
 	\[
	\bm{\Delta}(T)
	\equiv \left\{
	\hspace{-3pt}\begin{array}{c}
	\textup{probability measures $\nu$ over}\\
	\textup{pair colorings $(\smash{\vec{\sigma}}^1,\smash{\vec{\sigma}}^2)$
		of $T$}
	\end{array}\hspace{-3pt}\right\}\,.
	\]
We say that $\nu\in\bm{\Delta}(T)$ is \bemph{judicious}
if all of its edge marginals match the canonical marginals of Definition~\ref{d:canonical}: that is, for all edges $e$ in $T$ and for both $j=1,2$, 
we have $\nu((\sigma_e)^j=\sigma)={}_\star\hspace{-1pt}\pi_e(\sigma)$
for all $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$. Let $\omega_{\delta T}$ denote a tuple $(\omega_e)_{e\in\delta T}$ where each $\omega_e$ is a judicious probability measure on $\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$. We then let
	\[
	\bm{J}(T ; \omega_{\delta T})
	\equiv
	\left\{
	\hspace{-3pt}\begin{array}{c}
	\nu\in\bm{\Delta}(T):
	\textup{$\nu$ is judicious,}\\
	\textup{and
	$\nu_e=\omega_e$ for all $e\in\delta T$}
	\end{array}\hspace{-3pt}
	\right\}\,,
	\]
where $\nu_e$ denotes the marginal of $\nu$ on edge $e$. Define the constrained optimizer
	\begin{equation}\label{e:constrained.opt}
	\nu^\textup{op}(T;\omega_{\delta T})
	\equiv \textup{arg\,max}_\nu
		\bigg\{ \mathcal{H}(\nu)
		: \nu \in
		\bm{J}(T,\omega_{\delta T})\bigg\}\,.
	\end{equation}
Given weights $\Lambda$ on $T$, we also define the unconstrained optimizer
	\begin{equation}\label{e:weighted.unconstrained.opt}
	\nu[T;\Lambda]
	\equiv \textup{arg\,max}_\nu
		\bigg\{ \mathcal{H}(\nu)
			+ \langle \ln\Lambda,\nu\rangle
		: \nu \in \bm{\Delta}(T)\bigg\}\,,
	\end{equation}
where $\langle\ln\Lambda,\nu\rangle$ denotes the 
expected value of $\ln\Lambda(\smash{\vec{\sigma}})$ with $\smash{\vec{\sigma}}$ distributed according to $\nu$. Note that by elementary calculus, the solution
$\nu=\nu[T;\Lambda]$ of
\eqref{e:weighted.unconstrained.opt} is given explicitly by
	\begin{equation}\label{e:Lm.weighted.msr}
	\nu(\smash{\vec{\sigma}})
	= \frac{\Ind{\textup{$\smash{\vec{\sigma}}$
		is a valid coloring of $T$}
		} \Lambda(\smash{\vec{\sigma}})}{\bm{z}[T;\Lambda]}
	\end{equation}
where $\bm{z}[T;\Lambda]$ is the normalizing constant. Finally, we say that $\Lambda$ are \bemph{Lagrangian weights} (for the constrained optimization problem $\nu^\textup{op}(T;\omega_{\delta T}$ in \eqref{e:constrained.opt}) if $\langle\ln\Lambda,\nu\rangle$ is constant over $\nu\in\bm{J}(T;\omega_{\delta T})$. We will parametrize Lagrangian weights in a particular way, described in Definition~\ref{d:param.weights.Lambda} below.

\[
	\bm{J}(T ; \omega_{\delta T})
	\equiv
	\left\{
	\hspace{-3pt}\begin{array}{c}
	\nu\in\bm{\Delta}(T):
	\textup{$\nu$ is judicious,}\\
	\textup{and
	$\nu_e=\omega_e$ for all $e\in\delta T$}
	\end{array}\hspace{-3pt}
	\right\}\,,
	\]

\label{d:error.notation.edge}
On any edge $e$, denote ${}_{*}\omega_e\equiv{}_\star\hspace{-1pt}\pi_e\otimes{}_\star\hspace{-1pt}\pi_e$ where ${}_\star\hspace{-1pt}\pi_e$ is the canonical marginal on edge $e$ from Definition~\ref{d:canonical}. For any other probability measure $\omega_e$ on $\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$, we define the \bemph{discrepancy} of $\omega_e$ (relative to ${}_{*}\omega_e$) by
	\begin{equation}\label{e:def.discrepancy.measure.e}
	\textup{\textsf{disc}}(\omega_e)
	\equiv \textup{\textsf{disc}}_e(\omega)
	\equiv\sum_{\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2}
		(\vartheta_*)^{\Ind{ \SSPIN{r} \in\set{\sigma^1,\sigma^2} }}
		\Bigg| \frac{\omega_e(\sigma)}{{}_{*}\omega_e(\sigma)}
			-1
		\Bigg|\,.\end{equation}
where $\vartheta_*\equiv 2^{-k\zeta/6}$
for an absolute constant $0<\zeta\le1/20$.
We shall ultimately take $\zeta=\zeta_*/4$ where $\zeta_*$ is the absolute constant in Proposition~\ref{p:apriori} below.

\label{p:nice.tree.lagrange}
