\label{d:param.weights.Lambda}
Let $T$ be as in Definition~\ref{d:nu.judicious}.
We parametrize the Lagrangian weights $\Lambda$ on $T$ as follows. 
Given a pair $\smash{\vec{\sigma}}\equiv(\smash{\vec{\sigma}}^1,\smash{\vec{\sigma}}^2)$ of valid colorings of $T$, let $\smash{\vec{x}}\equiv(\smash{\vec{x}}^1,\smash{\vec{x}}^2)\equiv\smash{\vec{x}}(\smash{\vec{\sigma}})$ be the corresponding pair of frozen configurations on the variables of $T$. Recall from Remark~\ref{r:adjusted.bp.stability} that ${}_{*}q={}_\bullet\hspace{-1pt}q\otimes{}_\bullet\hspace{-1pt}q$. We then take the weights to be of form
	\[
	\Lambda(\smash{\vec{\sigma}})
	= {}_{*}\hat{q}_{a_\textup{\textsc{rt}}v_\textup{\textsc{rt}}}(\sigma_{a_\textup{\textsc{rt}}v_\textup{\textsc{rt}}})\Bigg\{
	 \prod_{v\in V_T\setminus \mathcal{L} T}
	 \Lambda_v(\smash{\vec{\sigma}}_{\delta v})
	 \Bigg\}
	\Bigg\{\prod_{e\in\delta T}
		\lambda_e(\sigma_e) \Bigg\}\,,
	\]
where for each internal variable $v\in V_T\setminus\mathcal{L} T$ the weight factorizes as
	\begin{equation}\label{e:factorize.internal.weights.in.cpd}
	\Lambda_v(\smash{\vec{\sigma}}_{\delta v})
	\equiv
	\overbrace{\Bigg(\prod_{j=1,2}
	(\lambda_v)^j((x_v)^j)\Bigg)}^{\lambda_v(x_v)}
	\prod_{e\in\delta v}
	\overbrace{\Bigg(
	\prod_{j=1,2}
	(\lambda_e)^j((\sigma_e)^j)
	\Bigg)}^{\lambda_e(\sigma_e)}\,.
	\end{equation}
We assume that $(\lambda_v)^j(\SPIN{+})=1$,
and $(\lambda_e)^j((\sigma_e)^j)=1$
for all $(\sigma_e)^j\ne\SSPIN{r}$;
we will often abbreviate
$(\lambda_e)^j\equiv(\lambda_e)^j(\SSPIN{r})$. If $\Lambda$ is any weight on $T$ of the functional form just described, then $\Lambda$ is a Lagrangian weight in the sense of Definition~\ref{d:nu.judicious}, meaning that $\langle\ln\Lambda,\nu\rangle$ is constant over $\nu\in\bm{J}(T;\omega_{\delta T})$. Conversely, it is easy to see that any Lagrangian weight can be expressed in this form. Next, recalling the discussion of \S\ref{ss:bp}, there is a unique solution $q=q_\textup{\textsc{bp}}(T;\Lambda)$ for the $\Lambda$-weighted \textsc{bp} recursions on $T$, obtained by recursing inwards from the leaves. In particular, for $e\in\delta T$ we have simply $\dot{q}_e=\lambda_e$, and at the root we have $\hat{q}_{a_\textup{\textsc{rt}}v_\textup{\textsc{rt}}}={}_{*}\hat{q}_{a_\textup{\textsc{rt}}v_\textup{\textsc{rt}}}$. Analogously~to~\eqref{e:var.tuple.measure.weighted}, the marginals of $\nu=\nu[T;\Lambda]$ (the $\Lambda$-weighted measure, see \eqref{e:weighted.unconstrained.opt} and \eqref{e:Lm.weighted.msr}) can be expressed in terms of $q=q_\textup{\textsc{bp}}(T;\Lambda)$: for instance,
the marginal law of $\smash{\vec{\sigma}}_{\delta v}$ under $\nu$ is given by 
	\begin{equation}\label{e:defn.nu.Lambda.q}
	\Big(
	\nu_{\delta v}[\Lambda_v;\hat{q}]
	\Big)(\smash{\vec{\sigma}}_{\delta v}) 
	\equiv \frac1{\bm{\dot{z}}_v}
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\Lambda_v(\smash{\vec{\sigma}}_{\delta v}) 
	\prod_{e\in\delta v}\hat{q}_e(\sigma_e)
	\,,\end{equation}
where $\bm{\dot{z}}_v$ is the normalization. (This holds even if $v\in \mathcal{L} T$, provided we define $\Lambda_v(\smash{\vec{\sigma}}_{\delta v})\equiv\lambda_e(\sigma_e)$ where $e$ is the one edge in $\delta v$.) Likewise, the marginal law on any edge $e$ of $T$ is given by $\nu_e(\sigma) \cong \dot{q}_e(\sigma) \hat{q}_e(\sigma)$ for $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$.

\begin{equation}\label{e:var.update.II.b}
	\nu_{\delta v, t}(\smash{\vec{\sigma}}_{\delta v}) 
	\equiv
	\frac{1}{\bm{\dot{z}}_{v,t}}
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\Lambda_{v,t}(\smash{\vec{\sigma}}_{\delta v})
	\Bigg\{
	\hat{q}_{av,t-1}(\sigma_{av})
	\prod_{b \in \partial v\setminus a}
	\hat{q}_{bv,t}(\sigma_{bv})
	\Bigg\}
	\end{equation}

\label{d:subsets.of.clause.colorings}
Given a clause $a\in F$, we now fix some notation for various subsets of colorings of $\delta a$. Abbreviate $K = |\delta a| \in \set{k,k-1}$. Let
$\SPIN{W} \equiv \set{\SSPIN{y},\SSPIN{c}}^{K-1}$
and $\SPIN{Y}\equiv \set{\SSPIN{y}}^{K-1}$. Then let
	\begin{align*}
	\SPIN{R}
		&\equiv
		\Bigg\{
		\smash{\vec{\sigma}}\in\set{\SSPIN{r},\SSPIN{y}}^{K-1}:
		\Big|\Big\{j\in [K]:\sigma_j=\SSPIN{r}\Big\}\Big|=1
		\Bigg\}\,,\\
	\SPIN{C}
		&\equiv
		\Bigg\{
		\smash{\vec{\sigma}}\in\set{\SSPIN{y},\SSPIN{c}}^{K-1}:
		\Big|\Big\{j\in [K]:\sigma_j=\SSPIN{c}\Big\}\Big|=1
		\Bigg\}\,,\\
	\SPIN{C}_{\ge j}
		&\equiv
		\Bigg\{
		\smash{\vec{\sigma}}\in\set{\SSPIN{y},\SSPIN{c}}^{K-1}:
		\Big|\Big\{j\in [K]:\sigma_j=\SSPIN{c}\Big\}\Big|
			\ge j
		\Bigg\}\,.
	\end{align*}
For any two subsets
$\SPIN{A}$ and $\SPIN{B}$ of $\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^{K-1}$, we 
will abbreviate $\SPIN{AB}\equiv \SPIN{A}\times\SPIN{B}$.

\label{p:clause.update}
Suppose the clause $a\in F$ receives two sets of incoming messages $p$ and $q$, with each message a probability measure over $\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$ satisfying the estimates~\eqref{e:first.update.at.boundary}, 
such that, in the notation of Definition~\ref{d:var.rel.error}, we have
	\[
	\dddot{\textup{\textsf{\footnotesize ERR}}}(p_e,q_e)
	\le\begin{pmatrix}
		\delta_e \\
		\dot{\delta}_e \\
		\ddot{\delta}_e \\
		{}^\textup{m}\hspace{-2pt}\delta_e \\
		{}^\textup{m}\hspace{-2pt}\dot{\delta}_e
		\end{pmatrix}
	\]
for each $e\in\delta a$.
Then the outgoing clause-to-variable messages $g\equiv\textup{\footnotesize\textsf{BP}}[p]$ and $h\equiv\textup{\footnotesize\textsf{BP}}[q]$ satisfy, for all $e'\in\delta a$,
	\begin{equation}\label{e:clause.output.rel.error.matrix}
	\widehat{\textup{\textsf{\footnotesize ERR}}}(g_{e'},h_{e'})
	\le
	O(k^2)
	\begin{pmatrix}2^{-k(1+\zeta)}
	& 4^{-k} & 2^{-k(1+\zeta)} & 2^{-k} & 2^{-k}\\
	2^{-k} & 2^{-k} & 2^{-k(1+\zeta)}
		& 1 & 2^{-k} \\
	1 & 4^{-k} & 2^{-k(1+\zeta)}
		& 2^{-k} & 2^{-k}
	\end{pmatrix}
	\sum_{e\in\delta a \setminus e'}
	\begin{pmatrix}
		\delta_e\\
		\dot{\delta}_e\\
		\min\set{\ddot{\delta}_e,1}\\
		{}^\textup{m}\hspace{-2pt}\delta_e\\
		{}^\textup{m}\hspace{-2pt}\dot{\delta}_e
	\end{pmatrix}\,.





	\end{equation}



\begin{proof} 
Throughout the proof, we fix an edge $e'=(av)$ on which to calculate the outgoing \textsc{bp} messages,
and suppress $e'$ from the notation when possible. We abbreviate
	\[
	\begin{pmatrix}
	\bm{\delta} \\
	\bm{\dot{\delta}} \\ 
	\bm{\ddot{\delta}} \\ 
	{}^\textup{m}\hspace{-2pt}\bm{\delta} \\
	{}^\textup{m}\hspace{-2pt}\bm{\dot{\delta}}
	\end{pmatrix}
	\equiv
	\sum_{e\in\delta a \setminus e'}
	\begin{pmatrix}
		\delta_e \\
		\dot{\delta}_e \\
		\min\set{\ddot{\delta}_e,1}	 \\
		{}^\textup{m}\hspace{-2pt}\delta_e \\
		{}^\textup{m}\hspace{-2pt}\dot{\delta}_e
		\end{pmatrix}\,.\smallskip
	\]
\bemph{Step 1. Rewriting of \textsc{bp} equations.}
For $e\in\delta a$ let $P_e,Q_e$ be the reweighted versions of $p_e,q_e$ defined by \eqref{e:reweighted.messages.v.to.c}. Let $\mathcal{X}$ and $\mathcal{Y}$ be the (non-normalized) measures over configurations $\smash{\vec{\sigma}}_{\delta a \setminus e'}$ defined by
	\begin{align*}
	\mathcal{X}(\smash{\vec{\sigma}}_{\delta a \setminus e'})
	&=\prod_{e\in\delta a \setminus e'}
		\bigg\{
		(2^{|\partial a|-1})^{\SSPIN{r}[\sigma_e]}
		P_e(\sigma_e)\bigg\}\,,\\
	\mathcal{Y}(\smash{\vec{\sigma}}_{\delta a \setminus e'})
	&=\prod_{e\in\delta a \setminus e'}
		\bigg\{
		(2^{|\partial a|-1})^{\SSPIN{r}[\sigma_e]}
		Q_e(\sigma_e)
		\bigg\}\,.
	\end{align*}
Then the equations $g\equiv g_{av} \equiv \textup{\footnotesize\textsf{BP}}_{av}[p]$ and $h\equiv h_{av} \equiv \textup{\footnotesize\textsf{BP}}_{av}[q]$ can be rewritten as
	\begin{align*}
	g(\sigma)
	&= \frac1{Z_g} \sum_{\smash{\vec{\sigma}}_{\delta a}:\sigma_{e'}=\sigma}
		\hat{\varphi}_a(\smash{\vec{\sigma}}_{\delta a})
		\mathcal{X}(\smash{\vec{\sigma}}_{\delta a\setminus e'})\,,\\
	h(\sigma)
	&=\frac1{Z_h} \sum_{\smash{\vec{\sigma}}_{\delta a}:\sigma_{e'}=\sigma}
		\hat{\varphi}_a(\smash{\vec{\sigma}}_{\delta a})
		\mathcal{Y}(\smash{\vec{\sigma}}_{\delta a\setminus e'})\,,
	\end{align*}
where $Z_g$ and $Z_h$ are the normalizing constants,
and $\hat{\varphi}_a$ denotes the factor 
for the pair coloring model, as in \eqref{e:pair.color.model.factors}.
In the remainder of the proof, we first obtain error bounds between $\mathcal{X}$ and $\mathcal{Y}$, then use this to deduce error bounds between $g$ and $h$.\smallskip

\noindent\bemph{Step 2. Error bounds between $\mathcal{X}$ and $\mathcal{Y}$.} Using the notation of Definition~\ref{d:subsets.of.clause.colorings}, we have
	\begin{align*}

	\mathcal{X}(\SPIN{Y}\SPIN{Y})
	&= \prod_{e\in\delta a \setminus e'}
		P_e(\SSPIN{y}\SSPIN{y})
	= \prod_{e\in\delta a \setminus e'}
		\Bigg\{
		Q_e(\SSPIN{y}\SSPIN{y})
		+ O(\delta_e)\Bigg\}
	=\mathcal{Y}(\SPIN{Y}\SPIN{Y})
		+ O\Bigg(\frac{\bm{\delta}}{4^k}\Bigg)
	=\Theta\Bigg(\frac1{4^k}\Bigg)\,,\\

	\mathcal{X}(\SPIN{R}\SPIN{Y})
	&=\sum_{e\in\delta a\setminus e'} \Bigg\{ 
		2^{|\partial a|-1}
		 Q_e(\SSPIN{r}\SSPIN{y})
			+ O(\dot{\delta}_e) \Bigg\}
		\prod_{e''\in\delta a
			\setminus\set{e,e'}} \Bigg\{
		Q_{e''}(\SSPIN{y}\SSPIN{y})
		+O(\delta_{e''})\Bigg\}
	= \mathcal{Y}(\SPIN{R}\SPIN{Y})
		+O\Bigg( \frac{\bm{\dot{\delta}}+k\bm{\delta}}{4^k} \Bigg)
		=\Theta\Bigg(\frac{k}{4^k}\Bigg)\,,\\
	\mathcal{X}(\SPIN{C}\SPIN{Y})
	&=\sum_{e\in\delta a\setminus e'}
	\Bigg\{Q_e(\SSPIN{c}\SSPIN{y}) + O(\delta_e)\Bigg\}
	\prod_{e''\in\delta a\setminus\set{e,e'}} \Bigg\{
		Q_{e''}(\SSPIN{y}\SSPIN{y})
		+O(\delta_{e''})\Bigg\}
	=\mathcal{Y}(\SPIN{C}\SPIN{Y})
	+O\Bigg( \frac{k\bm{\delta}}{4^k} \Bigg)
	=\Theta\Bigg(\frac{k}{4^k}\Bigg),.
	\end{align*}
Recall for $j=1,2$ we use $(P_e)^j$ to denote the marginal of $P_e$ on the $j$-th copy. Then
	\begin{align*}
	\mathcal{X}(\SPIN{Y}\SPIN{W})
	&=\prod_{e\in\delta a \setminus e'}
		\Bigg\{ (P_e)^1(\SSPIN{y})
		- P_e(\SSPIN{y}\SSPIN{r})\Bigg\}
	= \prod_{e\in\delta a \setminus e'}
		\Bigg\{ (Q_e)^1(\SSPIN{y})
			\Big( 1 + O({}^\textup{m}\hspace{-2pt}\delta_e)\Big)
		- Q_e(\SSPIN{y}\SSPIN{r})
			\Big( 1 + O(\dot{\delta}_e)\Big)
		\Bigg\}
		\\
	&=\prod_{e\in\delta a \setminus e'}
		\Bigg\{ 
			(Q_e)^1(\SSPIN{y})- Q_e(\SSPIN{y}\SSPIN{r})
			+ O\bigg(
			{}^\textup{m}\hspace{-2pt}\delta_e + \frac{\dot{\delta}_e}{2^k}
			\bigg)
		\Bigg\}
	=\mathcal{Y}(\SPIN{Y}\SPIN{W})
	+O\Bigg(
		\frac{{}^\textup{m}\hspace{-2pt}\bm{\delta}}{2^k} + \frac{\bm{\dot{\delta}}}{4^k}
	\Bigg)
	=\Theta\Bigg(\frac1{2^k}\Bigg)\,,
	\end{align*}
where the transition to the second line uses
the estimates \eqref{e:first.update.at.boundary}. 
By similar calculations, we have
	\begin{align*}
	\mathcal{X}(\SPIN{C}\SPIN{W})
	&=
	\sum_{e\in\delta a \setminus e'}
	\Bigg\{
	(P_e)^1 (\SSPIN{c}) - P_e(\SSPIN{c}\SSPIN{r}) \Bigg\}
	\prod_{e''\in\delta a \setminus \set{e,e'}} 
	\Bigg\{
	(P_e)^1(\SSPIN{y})-P_e(\SSPIN{y}\SSPIN{r})
	\Bigg\}\\
	&=\mathcal{Y}(\SPIN{C}\SPIN{W})
	+ O\Bigg(
	\frac{k{}^\textup{m}\hspace{-2pt}\bm{\delta}}{2^k} + \frac{k\bm{\dot{\delta}}}{4^k}
	\Bigg)
	 = \Theta\Bigg(\frac{k}{2^k}\Bigg) \\
	\nonumber
	\mathcal{X}(\SPIN{R}\SPIN{W})
	&=2^{|\partial a|-1}
	\sum_{e\in\delta a \setminus e'}
	\Bigg\{
	(P_e)^1 (\SSPIN{r}) - P_e(\SSPIN{r}\SSPIN{r}) \Bigg\}
	\prod_{e''\in\delta a \setminus \set{e,e'}} 
	\Bigg\{
	(P_e)^1(\SSPIN{y})-P_e(\SSPIN{y}\SSPIN{r})
	\Bigg\}
	\\
	&=
	\mathcal{Y}(\SPIN{R}\SPIN{W})
	+ O\Bigg(
	\frac{k{}^\textup{m}\hspace{-2pt}\bm{\delta}+{}^\textup{m}\hspace{-2pt}\bm{\dot{\delta}}}{2^k}
	+\frac{\bm{\ddot{\delta}}}{2^{k(1+\zeta)}}
	+\frac{k\bm{\dot{\delta}}}{4^k}
	\Bigg)
	 = \Theta\Bigg(\frac{k}{2^k}\Bigg)\,, \\
	\mathcal{X}(\SPIN{W}\SPIN{W})
	&=\prod_{e\in\delta a \setminus e'}
	\Bigg\{ 1
		-(Q_e)^1(\SSPIN{r})-(Q_e)^2(\SSPIN{r})
		+Q_e(\SSPIN{r}\SSPIN{r})
		+O\bigg(
		\frac{{}^\textup{m}\hspace{-2pt}\dot{\delta}_e}{2^k} + 
		\frac{ \min\set{\ddot{\delta}_e,1}}
			{2^{k(1+\zeta)}}
		\bigg)
		\Bigg\}\\
	&= \mathcal{Y}(\SPIN{W}\SPIN{W})
		+ O\Bigg( \frac{{}^\textup{m}\hspace{-2pt}\bm{\dot{\delta}}}{2^k}
	+ \frac{\bm{\ddot{\delta}}}
		{ 2^{k(1+\zeta)}}
		\Bigg) = \Theta(1)\,.
	\end{align*}
In the last calculation, the term involving 
$\min\set{\ddot{\delta}_e,1}$ arises because on the one hand the definition of $\ddot{\delta}_e$ implies
	\[
	Q_e(\SSPIN{r}\SSPIN{r})
	=P_e(\SSPIN{r}\SSPIN{r})\bigg\{ 1 + O(\ddot{\delta}_e)\bigg\}\,,
	\]
and on the other hand we assume that both $p$ and $q$ satisfy \eqref{e:first.update.at.boundary} which implies that
	\[
	\max\bigg\{P_e(\SSPIN{r}\SSPIN{r}),Q_e(\SSPIN{r}\SSPIN{r})\bigg\}
	\le \frac{O(1)}{2^{k(1+\zeta)}}\,.
	\]
We also comment that we have kept track of explicit powers of $k$, but this is not an important point; one could also write the proof with factors $k^{O(1)}$ where $O(1)$ stays bounded throughout. Lastly we have
	\begin{align*}
	\mathcal{X}(\SPIN{C}\SPIN{C})
	&=\sum_{e\in\delta a \setminus e'}
		P_e(\SSPIN{c}\SSPIN{c})
		\prod_{e''\in\delta a \setminus\set{e,e'}}
		P_{e''}(\SSPIN{y}\SSPIN{y})
	+\sum_{e\in\delta a \setminus e'}
		\sum_{e''\in\delta a \setminus\set{e,e'}}
		P_e(\SSPIN{c}\SSPIN{y})
		P_{e''}(\SSPIN{y}\SSPIN{c})
		\prod_{e'''\in\delta a \setminus\set{e,e',e''}}
		P_{e'''}(\SSPIN{y}\SSPIN{y})\\
	&=\mathcal{Y}(\SPIN{C}\SPIN{C})
		+O\Bigg( \frac{k^2\bm{\delta}}{4^k} \Bigg)
	= \Theta\Bigg( \frac{k^2}{4^k}\Bigg)
	\,,\\
	\mathcal{X}(\SPIN{R}\SPIN{C})
	&=2^{|\partial a|-1}
		\Bigg\{
		\sum_{e\in\delta a \setminus e'}
		P_e(\SSPIN{r}\SSPIN{c})
		\prod_{e''\in\delta a \setminus\set{e,e'}}
		P_{e''}(\SSPIN{y}\SSPIN{y})
	+
	\sum_{e\in\delta a \setminus e'}
		\sum_{e''\in\delta a \setminus\set{e,e'}}
		P_e(\SSPIN{r}\SSPIN{y})
		P_{e''}(\SSPIN{y}\SSPIN{c})
		\prod_{e'''\in\delta a \setminus\set{e,e',e''}}
		P_{e'''}(\SSPIN{y}\SSPIN{y})\Bigg\}\\

	&=\mathcal{Y}(\SPIN{R}\SPIN{C})
	+O\Bigg(
	\frac{k^2\bm{\delta} +k \bm{\dot{\delta}}}{4^k}
	\Bigg)= \Theta\Bigg( \frac{k^2}{4^k}\Bigg)\,,\\
	\mathcal{X}(\SPIN{R}\SPIN{R})
	&= 4^{|\partial a|-1}
	\Bigg\{
	\sum_{e\in\delta a\setminus e'}
		P_e(\SSPIN{r}\SSPIN{r})
		\prod_{e''\in\delta a \setminus\set{e,e'}}
			P_{e''}(\SSPIN{y}\SSPIN{y})
		+\sum_{e\in\delta a\setminus e'}
		\sum_{e''\in\delta a \setminus \set{e,e'}}
			P_e(\SSPIN{r}\SSPIN{y})
			P_{e''}(\SSPIN{y}\SSPIN{r})
			\prod_{e'''\in\delta a 
				\setminus\set{e,e',e''}}
			P_{e'''} (\SSPIN{y}\SSPIN{y})\Bigg\}\\
	&= \mathcal{Y}(\SPIN{R}\SPIN{R})
	+O\Bigg(
	\frac{k\bm{\delta}+\bm{\ddot{\delta}}}{2^{k(1+\zeta)}}
	+ \frac{k \bm{\dot{\delta}}+ k^2\bm{\delta}}{4^k}
	\Bigg)
	= \mathcal{Y}(\SPIN{R}\SPIN{R})
	+O\Bigg(
	\frac{k\bm{\delta} + \bm{\ddot{\delta}}}{2^{k(1+\zeta)}}
	+ \frac{k \bm{\dot{\delta}}}{4^k}
	\Bigg)
	= O\Bigg( \frac{k}{2^{k(1+\zeta)}}\Bigg)\,.
	\smallskip
	\end{align*}

\noindent\bemph{Step 3. Error bounds between $g$ and $h$.} Recall that in Step 1 we expressed $g$ and $h$ in terms of $\mathcal{X}$ and $\mathcal{Y}$. We now use the bounds from Step 2 on the error between $\mathcal{X}$ and $\mathcal{Y}$ to deduce bounds on the error between $g$ and $h$. 
The two easiest bounds are
	\begin{align*}
	Z_g g(\SSPIN{r}\SSPIN{r})
	&= \mathcal{X}(\SPIN{Y}\SPIN{Y})
	=\mathcal{Y}(\SPIN{Y}\SPIN{Y})
		\Bigg\{ 1 + O(\bm{\delta})
		\Bigg\}
	= Z_h h(\SSPIN{r}\SSPIN{r})
		\Bigg\{ 1 + O(\bm{\delta})
		\Bigg\}\,,\\
	Z_g g(\SSPIN{r}\SSPIN{c})
	&=\mathcal{X}(\SPIN{Y}\SPIN{C}_{\ge1})
	=\mathcal{X}(\SPIN{Y}\SPIN{W})-\mathcal{X}(\SPIN{Y}\SPIN{Y})
	=Z_h h(\SSPIN{r}\SSPIN{c})
	\Bigg\{1
	+O\bigg(
		{}^\textup{m}\hspace{-2pt}\bm{\delta}
		+\frac{\bm{\dot{\delta}} + \bm{\delta}}{2^k} \bigg)
	\Bigg\}\,.
	\end{align*}
The remaining estimates are similar, only slightly more complicated. We next have
	\begin{align*}
	Z_g g(\SSPIN{r}\SSPIN{y})
	&= \mathcal{X}\Big(\SPIN{Y}\times(\SPIN{R}\cup\SPIN{C}_{\ge2}) \Big)
	= \mathcal{X}(\SPIN{Y}\SPIN{R})
	+ \mathcal{X}(\SPIN{Y}\SPIN{W})
	-\mathcal{X}(\SPIN{Y}\SPIN{Y})
	-\mathcal{X}(\SPIN{Y}\SPIN{C}) 
	=Z_h h(\SSPIN{r}\SSPIN{y})
	\Bigg\{
	1 +O\bigg( {}^\textup{m}\hspace{-2pt}\bm{\delta} + \frac{ \bm{\dot{\delta}} + k\bm{\delta}}{2^k} \bigg)
	\Bigg\}
	\end{align*}
The calculations for the spins in $\set{\SSPIN{y},\SSPIN{c}}^2$ are all similar:
	\begin{align*}
	Z_g g(\SSPIN{c}\SSPIN{c})
	&= \mathcal{X}\Big( (\SPIN{C}_{\ge1})^2\Big)
	= \mathcal{X}(\SPIN{W}\SPIN{W})
	- \mathcal{X}(\SPIN{W}\SPIN{Y})- \mathcal{X}(\SPIN{Y}\SPIN{W})+\mathcal{X}(\SPIN{Y}\SPIN{Y})
	= Z_h h(\SSPIN{c}\SSPIN{c})
	\Bigg\{1 + O\bigg( 
		\frac{ {}^\textup{m}\hspace{-2pt}\bm{\delta}+{}^\textup{m}\hspace{-2pt}\bm{\dot{\delta}} }{2^k}
			+
			\frac{\bm{\ddot{\delta}}}
				{2^{k(1+\zeta)}}
			+ \frac{\bm{\delta} + \bm{\dot{\delta}}}{4^k }
			\bigg)\Bigg\}\,,\\
	Z_g g(\SSPIN{c}\SSPIN{y})
	&= \mathcal{X}\Big(
		\SPIN{C}_{\ge1} \times (\SPIN{R}\cup\SPIN{C}_{\ge2})
		\Big)
	= \Bigg( \mathcal{X}(\SPIN{W}\SPIN{R})-\mathcal{X}(\SPIN{Y}\SPIN{R})\Bigg)
		+\Bigg(
		\mathcal{X}\Big((\SPIN{C}_{\ge1})^2\Big)
		-\mathcal{X}(\SPIN{W}\SPIN{C})+\mathcal{X}(\SPIN{Y}\SPIN{C})
		\Bigg)\\
	&= Z_h h(\SSPIN{c}\SSPIN{y})
		\Bigg\{ 1 + O\bigg(
		\frac{k{}^\textup{m}\hspace{-2pt}\bm{\delta}+{}^\textup{m}\hspace{-2pt}\bm{\dot{\delta}}}{2^k}
		+\frac{\bm{\ddot{\delta}}}{2^{k(1+\zeta)}}
		+\frac{k^2\bm{\delta}+k\bm{\dot{\delta}}}{4^k}
		\bigg)
			\Bigg\}\,,\\
	Z_g g(\SSPIN{y}\SSPIN{y})
	&= \mathcal{X}\Big((\SPIN{R}\cup\SPIN{C}_{\ge2})^2\Big)
	= \mathcal{X}(\SPIN{R}\SPIN{R})
	+\bigg(
	\mathcal{X}(\SPIN{R}\SPIN{W})
	-\mathcal{X}(\SPIN{R}\SPIN{Y})-\mathcal{X}(\SPIN{R}\SPIN{C})
	\bigg)
	+\bigg(
	\mathcal{X}(\SPIN{W}\SPIN{R})
	-\mathcal{X}(\SPIN{Y}\SPIN{R})-\mathcal{X}(\SPIN{C}\SPIN{R})
	\bigg)\\
	&\qquad\qquad\qquad\qquad\qquad
	+
	\Bigg(
	\mathcal{X}(\SPIN{C}_{\ge1}\SPIN{C}_{\ge1})
	-(\mathcal{X}(\SPIN{C}\SPIN{W})-\mathcal{X}(\SPIN{C}\SPIN{Y}))
	-(\mathcal{X}(\SPIN{W}\SPIN{C})-\mathcal{X}(\SPIN{Y}\SPIN{C}))
	+\mathcal{X}(\SPIN{C}\SPIN{C})
	\Bigg)\\
	&=Z_h h(\SSPIN{y}\SSPIN{y})
	\Bigg\{1+O\bigg(
	\frac{k{}^\textup{m}\hspace{-2pt}\bm{\delta}+{}^\textup{m}\hspace{-2pt}\bm{\dot{\delta}}}{2^k}
	+ \frac{k\bm{\delta}+\bm{\ddot{\delta}}}{2^{k(1+\zeta)}}
	+ \frac{k\bm{\dot{\delta}}}{4^k}
	\bigg)\Bigg\}\,.
	\end{align*}
Combining these estimates gives
	\[
	Z_g=Z_h\Bigg\{1+O\bigg(
	\frac{k{}^\textup{m}\hspace{-2pt}\bm{\delta}+{}^\textup{m}\hspace{-2pt}\bm{\dot{\delta}}}{2^k}
	+ \frac{k\bm{\delta}+\bm{\ddot{\delta}}}{2^{k(1+\zeta)}}
	+ \frac{k\bm{\dot{\delta}}}{4^k}
	\bigg)\Bigg\}\,.
	\]
The claimed bounds directly follow.
\end{proof}


Throughout the proof, we fix an edge $e'=(av)$ on which to calculate the outgoing \textsc{bp} messages,
and suppress $e'$ from the notation when possible. We abbreviate
	\[
	\begin{pmatrix}
	\bm{\delta} \\
	\bm{\dot{\delta}} \\ 
	\bm{\ddot{\delta}} \\ 
	{}^\textup{m}\hspace{-2pt}\bm{\delta} \\
	{}^\textup{m}\hspace{-2pt}\bm{\dot{\delta}}
	\end{pmatrix}
	\equiv
	\sum_{e\in\delta a \setminus e'}
	\begin{pmatrix}
		\delta_e \\
		\dot{\delta}_e \\
		\min\set{\ddot{\delta}_e,1}	 \\
		{}^\textup{m}\hspace{-2pt}\delta_e \\
		{}^\textup{m}\hspace{-2pt}\dot{\delta}_e
		\end{pmatrix}\,.\smallskip
	\]
\bemph{Step 1. Rewriting of \textsc{bp} equations.}
