	\begin{align*}
	\mathcal{X}(\smash{\vec{\sigma}}_{\delta a \setminus e'})
	&=\prod_{e\in\delta a \setminus e'}
		\bigg\{
		(2^{|\partial a|-1})^{\SSPIN{r}[\sigma_e]}
		P_e(\sigma_e)\bigg\}\,,\\
	\mathcal{Y}(\smash{\vec{\sigma}}_{\delta a \setminus e'})
	&=\prod_{e\in\delta a \setminus e'}
		\bigg\{
