		Q_e(\sigma_e)
		\bigg\}\,.
	\end{align*}
Then the equations $g\equiv g_{av} \equiv \textup{\footnotesize\textsf{BP}}_{av}[p]$ and $h\equiv h_{av} \equiv \textup{\footnotesize\textsf{BP}}_{av}[q]$ can be rewritten as
	\begin{align*}
	g(\sigma)
	&= \frac1{Z_g} \sum_{\smash{\vec{\sigma}}_{\delta a}:\sigma_{e'}=\sigma}
		\hat{\varphi}_a(\smash{\vec{\sigma}}_{\delta a})
		\mathcal{X}(\smash{\vec{\sigma}}_{\delta a\setminus e'})\,,\\
