	\end{align*}
where $Z_g$ and $Z_h$ are the normalizing constants,
and $\hat{\varphi}_a$ denotes the factor 
for the pair coloring model, as in \eqref{e:pair.color.model.factors}.
In the remainder of the proof, we first obtain error bounds between $\mathcal{X}$ and $\mathcal{Y}$, then use this to deduce error bounds between $g$ and $h$.\smallskip

\noindent\bemph{Step 2. Error bounds between $\mathcal{X}$ and $\mathcal{Y}$.} Using the notation of Definition~\ref{d:subsets.of.clause.colorings}, we have
	\begin{align*}

	\mathcal{X}(\SPIN{Y}\SPIN{Y})
	&= \prod_{e\in\delta a \setminus e'}
		P_e(\SSPIN{y}\SSPIN{y})
