	=\mathcal{Y}(\SPIN{Y}\SPIN{Y})
		+ O\Bigg(\frac{\bm{\delta}}{4^k}\Bigg)
	=\Theta\Bigg(\frac1{4^k}\Bigg)\,,\\

	\mathcal{X}(\SPIN{R}\SPIN{Y})
	&=\sum_{e\in\delta a\setminus e'} \Bigg\{ 
		2^{|\partial a|-1}
		 Q_e(\SSPIN{r}\SSPIN{y})
			+ O(\dot{\delta}_e) \Bigg\}
		\prod_{e''\in\delta a
			\setminus\set{e,e'}} \Bigg\{
		Q_{e''}(\SSPIN{y}\SSPIN{y})
		+O(\delta_{e''})\Bigg\}
	= \mathcal{Y}(\SPIN{R}\SPIN{Y})
		+O\Bigg( \frac{\bm{\dot{\delta}}+k\bm{\delta}}{4^k} \Bigg)
		=\Theta\Bigg(\frac{k}{4^k}\Bigg)\,,\\
	\mathcal{X}(\SPIN{C}\SPIN{Y})
	&=\sum_{e\in\delta a\setminus e'}
	\Bigg\{Q_e(\SSPIN{c}\SSPIN{y}) + O(\delta_e)\Bigg\}
	\prod_{e''\in\delta a\setminus\set{e,e'}} \Bigg\{
		Q_{e''}(\SSPIN{y}\SSPIN{y})
		+O(\delta_{e''})\Bigg\}
