where the transition to the second line uses
the estimates \eqref{e:first.update.at.boundary}. 
By similar calculations, we have
	\begin{align*}
	\mathcal{X}(\SPIN{C}\SPIN{W})
	&=
	\sum_{e\in\delta a \setminus e'}
	\Bigg\{
	(P_e)^1 (\SSPIN{c}) - P_e(\SSPIN{c}\SSPIN{r}) \Bigg\}
	\prod_{e''\in\delta a \setminus \set{e,e'}} 
	\Bigg\{
	(P_e)^1(\SSPIN{y})-P_e(\SSPIN{y}\SSPIN{r})
	\Bigg\}\\
	&=\mathcal{Y}(\SPIN{C}\SPIN{W})
	+ O\Bigg(
	\frac{k{}^\textup{m}\hspace{-2pt}\bm{\delta}}{2^k} + \frac{k\bm{\dot{\delta}}}{4^k}
	\Bigg)
	 = \Theta\Bigg(\frac{k}{2^k}\Bigg) \\
	\nonumber
	\mathcal{X}(\SPIN{R}\SPIN{W})
	&=2^{|\partial a|-1}
	\sum_{e\in\delta a \setminus e'}
	\Bigg\{
	(P_e)^1 (\SSPIN{r}) - P_e(\SSPIN{r}\SSPIN{r}) \Bigg\}
	\prod_{e''\in\delta a \setminus \set{e,e'}} 
	\Bigg\{
	(P_e)^1(\SSPIN{y})-P_e(\SSPIN{y}\SSPIN{r})
	\Bigg\}
	\\
	&=
	\mathcal{Y}(\SPIN{R}\SPIN{W})
	+ O\Bigg(
	\frac{k{}^\textup{m}\hspace{-2pt}\bm{\delta}+{}^\textup{m}\hspace{-2pt}\bm{\dot{\delta}}}{2^k}
	+\frac{\bm{\ddot{\delta}}}{2^{k(1+\zeta)}}
	+\frac{k\bm{\dot{\delta}}}{4^k}
	\Bigg)
	 = \Theta\Bigg(\frac{k}{2^k}\Bigg)\,, \\
	\mathcal{X}(\SPIN{W}\SPIN{W})
	&=\prod_{e\in\delta a \setminus e'}
	\Bigg\{ 1
		-(Q_e)^1(\SSPIN{r})-(Q_e)^2(\SSPIN{r})
		+Q_e(\SSPIN{r}\SSPIN{r})
		+O\bigg(
		\frac{{}^\textup{m}\hspace{-2pt}\dot{\delta}_e}{2^k} + 
		\frac{ \min\set{\ddot{\delta}_e,1}}
			{2^{k(1+\zeta)}}
		\bigg)
		\Bigg\}\\
	&= \mathcal{Y}(\SPIN{W}\SPIN{W})
		+ O\Bigg( \frac{{}^\textup{m}\hspace{-2pt}\bm{\dot{\delta}}}{2^k}
	+ \frac{\bm{\ddot{\delta}}}
		{ 2^{k(1+\zeta)}}
		\Bigg) = \Theta(1)\,.
	\end{align*}
In the last calculation, the term involving 
$\min\set{\ddot{\delta}_e,1}$ arises because on the one hand the definition of $\ddot{\delta}_e$ implies
	\[
	Q_e(\SSPIN{r}\SSPIN{r})
	=P_e(\SSPIN{r}\SSPIN{r})\bigg\{ 1 + O(\ddot{\delta}_e)\bigg\}\,,
	\]
and on the other hand we assume that both $p$ and $q$ satisfy \eqref{e:first.update.at.boundary} which implies that
	\[
	\max\bigg\{P_e(\SSPIN{r}\SSPIN{r}),Q_e(\SSPIN{r}\SSPIN{r})\bigg\}
	\le \frac{O(1)}{2^{k(1+\zeta)}}\,.
	\]
We also comment that we have kept track of explicit powers of $k$, but this is not an important point; one could also write the proof with factors $k^{O(1)}$ where $O(1)$ stays bounded throughout. Lastly we have
	\begin{align*}
	\mathcal{X}(\SPIN{C}\SPIN{C})
	&=\sum_{e\in\delta a \setminus e'}
		P_e(\SSPIN{c}\SSPIN{c})
		\prod_{e''\in\delta a \setminus\set{e,e'}}
		P_{e''}(\SSPIN{y}\SSPIN{y})
	+\sum_{e\in\delta a \setminus e'}
		\sum_{e''\in\delta a \setminus\set{e,e'}}
		P_e(\SSPIN{c}\SSPIN{y})
		P_{e''}(\SSPIN{y}\SSPIN{c})
		\prod_{e'''\in\delta a \setminus\set{e,e',e''}}
		P_{e'''}(\SSPIN{y}\SSPIN{y})\\
	&=\mathcal{Y}(\SPIN{C}\SPIN{C})
		+O\Bigg( \frac{k^2\bm{\delta}}{4^k} \Bigg)
	= \Theta\Bigg( \frac{k^2}{4^k}\Bigg)
	\,,\\
	\mathcal{X}(\SPIN{R}\SPIN{C})
	&=2^{|\partial a|-1}
		\Bigg\{
		\sum_{e\in\delta a \setminus e'}
		P_e(\SSPIN{r}\SSPIN{c})
		\prod_{e''\in\delta a \setminus\set{e,e'}}
		P_{e''}(\SSPIN{y}\SSPIN{y})
	+
	\sum_{e\in\delta a \setminus e'}
		\sum_{e''\in\delta a \setminus\set{e,e'}}
		P_e(\SSPIN{r}\SSPIN{y})
		P_{e''}(\SSPIN{y}\SSPIN{c})
		\prod_{e'''\in\delta a \setminus\set{e,e',e''}}
		P_{e'''}(\SSPIN{y}\SSPIN{y})\Bigg\}\\

	&=\mathcal{Y}(\SPIN{R}\SPIN{C})
	+O\Bigg(
	\frac{k^2\bm{\delta} +k \bm{\dot{\delta}}}{4^k}
	\Bigg)= \Theta\Bigg( \frac{k^2}{4^k}\Bigg)\,,\\
	\mathcal{X}(\SPIN{R}\SPIN{R})
	&= 4^{|\partial a|-1}
	\Bigg\{
	\sum_{e\in\delta a\setminus e'}
		P_e(\SSPIN{r}\SSPIN{r})
		\prod_{e''\in\delta a \setminus\set{e,e'}}
			P_{e''}(\SSPIN{y}\SSPIN{y})
		+\sum_{e\in\delta a\setminus e'}
		\sum_{e''\in\delta a \setminus \set{e,e'}}
			P_e(\SSPIN{r}\SSPIN{y})
			P_{e''}(\SSPIN{y}\SSPIN{r})
			\prod_{e'''\in\delta a 
				\setminus\set{e,e',e''}}
			P_{e'''} (\SSPIN{y}\SSPIN{y})\Bigg\}\\
	&= \mathcal{Y}(\SPIN{R}\SPIN{R})
	+O\Bigg(
	\frac{k\bm{\delta}+\bm{\ddot{\delta}}}{2^{k(1+\zeta)}}
	+ \frac{k \bm{\dot{\delta}}+ k^2\bm{\delta}}{4^k}
	\Bigg)
	= \mathcal{Y}(\SPIN{R}\SPIN{R})
	+O\Bigg(
	\frac{k\bm{\delta} + \bm{\ddot{\delta}}}{2^{k(1+\zeta)}}
	+ \frac{k \bm{\dot{\delta}}}{4^k}
	\Bigg)
	= O\Bigg( \frac{k}{2^{k(1+\zeta)}}\Bigg)\,.
	\smallskip
	\end{align*}

\noindent\bemph{Step 3. Error bounds between $g$ and $h$.} Recall that in Step 1 we expressed $g$ and $h$ in terms of $\mathcal{X}$ and $\mathcal{Y}$. We now use the bounds from Step 2 on the error between $\mathcal{X}$ and $\mathcal{Y}$ to deduce bounds on the error between $g$ and $h$. 
The two easiest bounds are
	\begin{align*}
	Z_g g(\SSPIN{r}\SSPIN{r})
	&= \mathcal{X}(\SPIN{Y}\SPIN{Y})
	=\mathcal{Y}(\SPIN{Y}\SPIN{Y})
		\Bigg\{ 1 + O(\bm{\delta})
		\Bigg\}
	= Z_h h(\SSPIN{r}\SSPIN{r})
		\Bigg\{ 1 + O(\bm{\delta})
		\Bigg\}\,,\\
	Z_g g(\SSPIN{r}\SSPIN{c})
	&=\mathcal{X}(\SPIN{Y}\SPIN{C}_{\ge1})
	=\mathcal{X}(\SPIN{Y}\SPIN{W})-\mathcal{X}(\SPIN{Y}\SPIN{Y})
	=Z_h h(\SSPIN{r}\SSPIN{c})
	\Bigg\{1
	+O\bigg(
		{}^\textup{m}\hspace{-2pt}\bm{\delta}
		+\frac{\bm{\dot{\delta}} + \bm{\delta}}{2^k} \bigg)
	\Bigg\}\,.
	\end{align*}
The remaining estimates are similar, only slightly more complicated. We next have
	\begin{align*}
	Z_g g(\SSPIN{r}\SSPIN{y})
	&= \mathcal{X}\Big(\SPIN{Y}\times(\SPIN{R}\cup\SPIN{C}_{\ge2}) \Big)
	= \mathcal{X}(\SPIN{Y}\SPIN{R})
	+ \mathcal{X}(\SPIN{Y}\SPIN{W})
	-\mathcal{X}(\SPIN{Y}\SPIN{Y})
	-\mathcal{X}(\SPIN{Y}\SPIN{C}) 
	=Z_h h(\SSPIN{r}\SSPIN{y})
	\Bigg\{
	1 +O\bigg( {}^\textup{m}\hspace{-2pt}\bm{\delta} + \frac{ \bm{\dot{\delta}} + k\bm{\delta}}{2^k} \bigg)
	\Bigg\}
	\end{align*}
The calculations for the spins in $\set{\SSPIN{y},\SSPIN{c}}^2$ are all similar:
	\begin{align*}
	Z_g g(\SSPIN{c}\SSPIN{c})
	&= \mathcal{X}\Big( (\SPIN{C}_{\ge1})^2\Big)
	= \mathcal{X}(\SPIN{W}\SPIN{W})
	- \mathcal{X}(\SPIN{W}\SPIN{Y})- \mathcal{X}(\SPIN{Y}\SPIN{W})+\mathcal{X}(\SPIN{Y}\SPIN{Y})
	= Z_h h(\SSPIN{c}\SSPIN{c})
	\Bigg\{1 + O\bigg( 
		\frac{ {}^\textup{m}\hspace{-2pt}\bm{\delta}+{}^\textup{m}\hspace{-2pt}\bm{\dot{\delta}} }{2^k}
			+
			\frac{\bm{\ddot{\delta}}}
				{2^{k(1+\zeta)}}
			+ \frac{\bm{\delta} + \bm{\dot{\delta}}}{4^k }
			\bigg)\Bigg\}\,,\\
	Z_g g(\SSPIN{c}\SSPIN{y})
	&= \mathcal{X}\Big(
		\SPIN{C}_{\ge1} \times (\SPIN{R}\cup\SPIN{C}_{\ge2})
		\Big)
	= \Bigg( \mathcal{X}(\SPIN{W}\SPIN{R})-\mathcal{X}(\SPIN{Y}\SPIN{R})\Bigg)
		+\Bigg(
		\mathcal{X}\Big((\SPIN{C}_{\ge1})^2\Big)
		-\mathcal{X}(\SPIN{W}\SPIN{C})+\mathcal{X}(\SPIN{Y}\SPIN{C})
		\Bigg)\\
	&= Z_h h(\SSPIN{c}\SSPIN{y})
		\Bigg\{ 1 + O\bigg(
		\frac{k{}^\textup{m}\hspace{-2pt}\bm{\delta}+{}^\textup{m}\hspace{-2pt}\bm{\dot{\delta}}}{2^k}
		+\frac{\bm{\ddot{\delta}}}{2^{k(1+\zeta)}}
		+\frac{k^2\bm{\delta}+k\bm{\dot{\delta}}}{4^k}
		\bigg)
			\Bigg\}\,,\\
	Z_g g(\SSPIN{y}\SSPIN{y})
	&= \mathcal{X}\Big((\SPIN{R}\cup\SPIN{C}_{\ge2})^2\Big)
	= \mathcal{X}(\SPIN{R}\SPIN{R})
	+\bigg(
	\mathcal{X}(\SPIN{R}\SPIN{W})
	-\mathcal{X}(\SPIN{R}\SPIN{Y})-\mathcal{X}(\SPIN{R}\SPIN{C})
	\bigg)
	+\bigg(
	\mathcal{X}(\SPIN{W}\SPIN{R})
	-\mathcal{X}(\SPIN{Y}\SPIN{R})-\mathcal{X}(\SPIN{C}\SPIN{R})
	\bigg)\\
	&\qquad\qquad\qquad\qquad\qquad
	+
	\Bigg(
	\mathcal{X}(\SPIN{C}_{\ge1}\SPIN{C}_{\ge1})
	-(\mathcal{X}(\SPIN{C}\SPIN{W})-\mathcal{X}(\SPIN{C}\SPIN{Y}))
	-(\mathcal{X}(\SPIN{W}\SPIN{C})-\mathcal{X}(\SPIN{Y}\SPIN{C}))
	+\mathcal{X}(\SPIN{C}\SPIN{C})
	\Bigg)\\
	&=Z_h h(\SSPIN{y}\SSPIN{y})
	\Bigg\{1+O\bigg(
	\frac{k{}^\textup{m}\hspace{-2pt}\bm{\delta}+{}^\textup{m}\hspace{-2pt}\bm{\dot{\delta}}}{2^k}
	+ \frac{k\bm{\delta}+\bm{\ddot{\delta}}}{2^{k(1+\zeta)}}
	+ \frac{k\bm{\dot{\delta}}}{4^k}
	\bigg)\Bigg\}\,.
	\end{align*}
Combining these estimates gives
	\[
	Z_g=Z_h\Bigg\{1+O\bigg(
	\frac{k{}^\textup{m}\hspace{-2pt}\bm{\delta}+{}^\textup{m}\hspace{-2pt}\bm{\dot{\delta}}}{2^k}
	+ \frac{k\bm{\delta}+\bm{\ddot{\delta}}}{2^{k(1+\zeta)}}
	+ \frac{k\bm{\dot{\delta}}}{4^k}
	\bigg)\Bigg\}\,.
	\]
The claimed bounds directly follow.

