We first define a sequence of weights $\Gamma_t\equiv (\gamma_{e,t} : e\in\delta a)$, then show that they converge in the limit $t\to\infty$ to the desired weights $\Gamma_\infty=\Gamma$. We emphasize that this index $t$ is \bemph{purely local to the proof of this proposition}, and is not the same as the $t$ that indexes the up-and-down passes in
Definition~\ref{d:nice.lagrange.defn.weights}. \smallskip

\noindent\bemph{Step 1. Iterative definition of weights.} Recall that the goal is to find weights $\Gamma$ such that $\textup{\footnotesize\textsf{BP}}_{av}[\dot{q};\Gamma]=\hat{q}_{av,\infty}$
for all $v\in\partial a$. We initialize $\Gamma_0\equiv1$. 
For all $t\ge0$ let $h_t\equiv \textup{\footnotesize\textsf{BP}}[\dot{q};\Gamma_t]$
and $g_t\equiv \textup{\footnotesize\textsf{BP}}(\gamma_t\dot{q})$, so that $h_t$ is proportional to $\gamma_t g_t$ --- in this notation, the goal is to have in the limit
$\gamma_\infty g_\infty\cong\hat{q}_\infty$. We then recursively set
	\begin{equation}\label{e:clause.update.gamma.against.yy}
	\gamma_{t+1}(\sigma)
	=\gamma_t(\sigma) \cdot
	\frac{\hat{q}_\infty(\sigma)}
	{h_t(\sigma)}
	\bigg/\bigg(
	\frac{\hat{q}_\infty(\SSPIN{y}\SSPIN{y})}
	{h_t(\SSPIN{y}\SSPIN{y})}\bigg)
	\end{equation}
on all the edges of $\delta a$.
The rationale for this choice is that it keeps
$\gamma_t(\SSPIN{y}\SSPIN{y})=1$ for all $t\ge0$, and gives us
	\[
	\gamma_{t+1} g_t
	=
	\frac{\gamma_{t+1}}{\gamma_t} \gamma_t g_t
	\cong
	\frac{\hat{q}_\infty}{h_t} \gamma_t g_t
	\cong
	\frac{\hat{q}_\infty}{h_t} h_t
	\cong \hat{q}_\infty\,,
	\]
(which is, clearly, compatible with our eventual goal of $\gamma_\infty g_\infty\cong \hat{q}_\infty$).\smallskip

\noindent\bemph{Step 2. Analysis of weights.}
Suppose, in the notation of Definition~\ref{d:clause.rel.error}, that
for all $e\in\delta a$ we have
	\begin{equation}\label{e:clause.def.eps.t}
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\gamma_{e,t},\gamma_{e,t+1})
	= \begin{pmatrix}
		\epsilon_e(t)\\ \dot{\epsilon}_e(t) \\ \ddot{\epsilon}_e(t)
		\end{pmatrix}\,.\end{equation}
Recall that $\gamma_0\equiv1$
and $h_0\equiv \textup{\footnotesize\textsf{BP}}[\dot{q}]\equiv h$, so at $t=0$ 
the assumptions give
	\begin{equation}\label{e:g.to.gamma.matrix}
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\gamma_{e,0},\gamma_{e,1})
	=
	\widehat{\textup{\textsf{\footnotesize ERR}}}\bigg(1,
	\frac{\hat{q}_{e,\infty}}{h_e}
	\cdot
	\frac{h_e(\SSPIN{y}\SSPIN{y})}{\hat{q}_{e,\infty}(\SSPIN{y}\SSPIN{y})}
	\bigg)
	\le O(1)\begin{pmatrix}
	1 & 0 & 0 \\
	1 & 1 & 0\\
	1 & 0 & 1
	\end{pmatrix}
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\hat{q}_{e,\infty},h_e)
	= O(1)
	\begin{pmatrix}
	\epsilon_e \\ 
	\epsilon_e+\dot{\epsilon}_e \\ 
	\epsilon_e+\ddot{\epsilon}_e
	\end{pmatrix}\,.
	\end{equation}
For all $t\ge0$, it follows from 
\eqref{e:clause.update.gamma.against.yy} and
 the relation $h_t\cong\gamma_t g_t$ that
	\begin{align}\nonumber
	\frac{\gamma_{t+2}(\sigma)}{\gamma_{t+1}(\sigma)}
	&=\frac{\hat{q}_\infty(\sigma)/\hat{q}_\infty(\SSPIN{y}\SSPIN{y})}
	{h_{t+1}(\sigma)/h_{t+1}(\SSPIN{y}\SSPIN{y})}
	=\overbrace{\Bigg\{
	\frac{\gamma_t(\sigma)\hat{q}_\infty(\sigma)/\hat{q}_\infty(\SSPIN{y}\SSPIN{y})}
	{\gamma_{t+1}(\sigma)
	h_t(\sigma)/h_t(\SSPIN{y}\SSPIN{y})}
	\Bigg\}}^\textup{equals one
		by \eqref{e:clause.update.gamma.against.yy}}
	\frac{\gamma_{t+1}(\sigma) h_t(\sigma)/h_t(\SSPIN{y}\SSPIN{y})}{
		\gamma_t(\sigma)
		h_{t+1}(\sigma)/h_{t+1}(\SSPIN{y}\SSPIN{y})}\\
	&=
	\frac{[h_t(\sigma)/\gamma_t(\sigma)]
	/[h_t(\SSPIN{y}\SSPIN{y})/\gamma_t(\SSPIN{y}\SSPIN{y})]}
	{[h_{t+1}(\sigma)/\gamma_{t+1}(\sigma)]
	/[h_{t+1}(\SSPIN{y}\SSPIN{y})/\gamma_{t+1}(\SSPIN{y}\SSPIN{y})]}
	=	\frac{ g_t(\sigma)
		/g_t(\SSPIN{y}\SSPIN{y}) }
		{ g_{t+1}(\sigma)
		/g_{t+1}(\SSPIN{y}\SSPIN{y}) }\,.
	\label{e:relate.err.gamma.to.err.g}
	\end{align}
(the second-to-last step uses that $\gamma_t(\SSPIN{y}\SSPIN{y})\equiv1$). We can bound the error between $g_t=\textup{\footnotesize\textsf{BP}}[\gamma_t\dot{q}]$ and $g_{t+1}=\textup{\footnotesize\textsf{BP}}[\gamma_{t+1}\dot{q}]$ by applying Proposition~\ref{p:clause.update}, as follows: let $p_t$ denote the normalized measure corresponding to $\gamma_t\dot{q}$, so that, in the notation of Definition~\ref{d:var.rel.error},
	\[
	\dddot{\textup{\textsf{\footnotesize ERR}}}(p_{e,t},p_{e,t+1})
	\le O(1) \begin{pmatrix}
	\epsilon_e(t) \\
	\dot{\epsilon}_e(t)\\
	\ddot{\epsilon}_e(t)\\
	\epsilon_e(t) + \dot{\epsilon}_e(t)/2^k\\
	\dot{\epsilon_e}(t) + \ddot{\epsilon}_e(t) /2^{k\zeta}
	\end{pmatrix}
	+O\Bigg( \epsilon_e(t) +
		\frac{\dot{\epsilon}_e(t)}{2^k}
		 + \frac{\ddot{\epsilon}_e(t)}{2^{k(1+\zeta)}}
		 \Bigg)
	\mathbf{1}_5\,
	\]
--- on the right-hand side, the first term comes from the error between the non-normalized measures $\gamma_t q$ and $\gamma_{t+1}q$, while the second term comes from the normalization. In matrix notation,
	\[\dddot{\textup{\textsf{\footnotesize ERR}}}(p_{e,t},p_{e,t+1})
	\le O(1) 
	\begin{pmatrix}
	1 & 2^{-k} & 2^{-k(1+\zeta)}\\
	1 & 1 & 2^{-k(1+\zeta)}\\
	1 & 2^{-k} & 1 \\
	1 & 2^{-k} & 2^{-k(1+\zeta)}\\
	1 & 1 & 2^{-k\zeta}
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e(t) \\ \dot{\epsilon}_e(t) \\ \ddot{\epsilon}_e(t)
	\end{pmatrix}\,.
	\]
The message $p_0=\dot{q}$ satisfies the bounds \eqref{e:first.update.at.boundary} by assumption.
It follows from 
\eqref{e:g.to.gamma.matrix}
that the message $p_1$ (again, the normalization of $\gamma_1\dot{q}$) also satisfies
\eqref{e:first.update.at.boundary}, simply because the error between $\gamma_0$ and $\gamma_1$ is negligible. We will argue by induction that $p_t$ satisfies 
\eqref{e:first.update.at.boundary} 
for all $t\ge0$. First we note that by the definition~\eqref{e:clause.def.eps.t}
and by \eqref{e:relate.err.gamma.to.err.g}, we have
	\[\begin{pmatrix}
		\epsilon_e(t+1)\\ \dot{\epsilon}_e(t+1)
		\\ \ddot{\epsilon}_e(t+1)
		\end{pmatrix}
	=\widehat{\textup{\textsf{\footnotesize ERR}}}(\gamma_{e,t+2},\gamma_{e,t+1})
	\le O(1)
	\begin{pmatrix}
	1 & 0 & 0 \\
	1 & 1 & 0\\
	1 & 0 & 1
	\end{pmatrix}
	\widehat{\textup{\textsf{\footnotesize ERR}}}(g_{t+1},g_t)\,,\]
where the $3\times3$ matrix in the last expression is the same as the one in \eqref{e:g.to.gamma.matrix}.
Combining with Proposition~\ref{p:clause.update}
(more precisely, taking the product of the $3\times3$ matrix in the last display,
the $3\times5$ matrix in \eqref{e:clause.output.rel.error.matrix},
and the $5\times3$ matrix above), we find
	\begin{equation}\begin{pmatrix}
		\epsilon_e(t+1)\\ \dot{\epsilon}_e(t+1)
		\\ \ddot{\epsilon}_e(t+1)
		\end{pmatrix}
	\le 
	O(k^2)
	\begin{pmatrix}
	2^{-k} & 2^{-k} & 2^{-k(1+\zeta)}\\
	1 & 2^{-k} & 2^{-k(1+\zeta)}\\
	1 & 2^{-k} & 2^{-k(1+\zeta)}
	\end{pmatrix}
	\sum_{e'\in\delta a \setminus e}
	\begin{pmatrix}
		\epsilon_{e'}(t)\\ \dot{\epsilon}_{e'}(t) 
		\\ \ddot{\epsilon}_{e'}(t)
		\end{pmatrix}\,.
	\label{e:eps.t.to.next.step.matrix}
	\end{equation}
It is clear from this that
$p_t$ satisfies
\eqref{e:first.update.at.boundary} for all $t\ge0$, and moreover that the iteration defined in Step 1 converges as $t\to\infty$, with limiting weights $\gamma_\infty\equiv\gamma$. Quantitatively, it follows from \eqref{e:eps.t.to.next.step.matrix} that
	\[
	E(t+1)
	\equiv
	\begin{pmatrix}
	1 & 2^{-k/2}
	 & 2^{-k(1/2+\zeta)}
	 \end{pmatrix}
	\sum_{e\in\delta a}
	 \begin{pmatrix}
	 \epsilon_e(t+1)\\ \dot{\epsilon}_e(t+1)
	 	\\ \ddot{\epsilon}_e(t+1)
	 \end{pmatrix}
	\le
	\frac{O(k^3) E(t)}{2^{k/2}}\,,
	\]
(the $3\times1$ row vector in the definition of $E(t)$ is chosen because it is an approximate left eigenvector of the $3\times3$ matrix in the last bound of \eqref{e:eps.t.to.next.step.matrix}). We shall bound
	\[
	\widehat{\textup{\textsf{\footnotesize ERR}}}(1,\gamma_e)
	\le O(1)
	\sum_{t=0}^\infty
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\gamma_{e,t},
		\gamma_{e,t+1})
	\le O(1)\sum_{t=0}^1
	\begin{pmatrix}
	\epsilon_e(t)\\
	\dot{\epsilon}_e(t)\\
	\ddot{\epsilon}_e(t)
	\end{pmatrix}
	+O(1) \sum_{t=2}^\infty E(t)
	\begin{pmatrix}
	1 \\ 2^{k/2} \\ 2^{k(1/2+\zeta)}
	\end{pmatrix}\,.\]
On the right-hand side, the $t=0$ is bounded by 
\eqref{e:g.to.gamma.matrix},
and the $t=1$ term can be bounded by \eqref{e:eps.t.to.next.step.matrix}.
Thanks to the exponential decay of $E(t)$ in $t$, 
the sum over $t\ge2$ can be bounded by
	\begin{align*}
	\sum_{t=2}^\infty E(t)
	\begin{pmatrix}
	1 \\ 2^{k/2} \\ 2^{k(1/2+\zeta)}
	\end{pmatrix}
	&\le 
	\frac{O(k^6)}{2^k}
	E(0)
	\begin{pmatrix}
	1 \\ 2^{k/2} \\ 2^{k(1/2+\zeta)}
	\end{pmatrix}
	\le
	\frac{O(k^6)}{2^k}
	\begin{pmatrix}
	1 \\ 2^{k/2} \\ 2^{k(1/2+\zeta)}
	\end{pmatrix}
	\begin{pmatrix}
	1 & 2^{-k/2} & 2^{-k(1/2+\zeta)}
	\end{pmatrix}
	\sum_{e'\in\delta a}
	\begin{pmatrix}
	\epsilon_{e'}\\
	\epsilon_{e'}+\dot{\epsilon}_{e'}\\
	\epsilon_{e'}+\ddot{\epsilon}_{e'}
	\end{pmatrix}\\
	&=
	O(k^6)
	\begin{pmatrix}
	2^{-k} & 2^{-3k/2} & 2^{-k(3/2+\zeta)}\\
	2^{-k/2} & 2^{-k} & 2^{-k(1+\zeta)}\\
	2^{-k(1/2-\zeta)} & 2^{-k(1-\zeta)} & 2^{-k}\\
	\end{pmatrix}
	\sum_{e'\in\delta a}
	\begin{pmatrix}
	\epsilon_{e'}\\
	\epsilon_{e'}+\dot{\epsilon}_{e'}\\
	\epsilon_{e'}+\ddot{\epsilon}_{e'}
	\end{pmatrix}
	\end{align*}
Combining these bounds gives altogether
	\[
	\widehat{\textup{\textsf{\footnotesize ERR}}}(1,\gamma_e)
	\le
	O(1)
	\begin{pmatrix}
	\epsilon_e \\ 
	\epsilon_e+\dot{\epsilon}_e \\ 
	\epsilon_e+\ddot{\epsilon}_e
	\end{pmatrix}
	+
	O(k^6)
	\begin{pmatrix}
	2^{-k} & 2^{-k} & 2^{-k(1+\zeta)}\\
	1 & 2^{-k} & 2^{-k(1+\zeta)}\\
	1 & 2^{-k(1-\zeta)} & 2^{-k}
	\end{pmatrix}
		\sum_{e'\in\delta a}
	\begin{pmatrix}
	\epsilon_{e'}\\
	\epsilon_{e'}+\dot{\epsilon}_{e'}\\
	\epsilon_{e'}+\ddot{\epsilon}_{e'}
	\end{pmatrix}\,,\]
from which the claimed result follows.

\begin{align}\nonumber
	\frac{\gamma_{t+2}(\sigma)}{\gamma_{t+1}(\sigma)}
	&=\frac{\hat{q}_\infty(\sigma)/\hat{q}_\infty(\SSPIN{y}\SSPIN{y})}
	{h_{t+1}(\sigma)/h_{t+1}(\SSPIN{y}\SSPIN{y})}
	=\overbrace{\Bigg\{
	\frac{\gamma_t(\sigma)\hat{q}_\infty(\sigma)/\hat{q}_\infty(\SSPIN{y}\SSPIN{y})}
	{\gamma_{t+1}(\sigma)
	h_t(\sigma)/h_t(\SSPIN{y}\SSPIN{y})}
	\Bigg\}}^\textup{equals one
		by \eqref{e:clause.update.gamma.against.yy}}
	\frac{\gamma_{t+1}(\sigma) h_t(\sigma)/h_t(\SSPIN{y}\SSPIN{y})}{
		\gamma_t(\sigma)
		h_{t+1}(\sigma)/h_{t+1}(\SSPIN{y}\SSPIN{y})}\\
	&=
	\frac{[h_t(\sigma)/\gamma_t(\sigma)]
	/[h_t(\SSPIN{y}\SSPIN{y})/\gamma_t(\SSPIN{y}\SSPIN{y})]}
	{[h_{t+1}(\sigma)/\gamma_{t+1}(\sigma)]
	/[h_{t+1}(\SSPIN{y}\SSPIN{y})/\gamma_{t+1}(\SSPIN{y}\SSPIN{y})]}
	=	\frac{ g_t(\sigma)
		/g_t(\SSPIN{y}\SSPIN{y}) }
		{ g_{t+1}(\sigma)
		/g_{t+1}(\SSPIN{y}\SSPIN{y}) }\,.
	\label{e:relate.err.gamma.to.err.g}
	\end{align}

\label{p:var.update} Let $v$ be a nice variable with incoming messages $\hat{p}$ (in the pair coloring model). Recalling the notation of Definition~\ref{d:clause.rel.error}, assume that
for all $e\in\delta v$ we have 
	\begin{equation}\label{e:condition.on.hat.messages}
	\widehat{\textup{\textsf{\footnotesize ERR}}}({}_{*}\hat{q}_e,\hat{p}_e)
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix} 
	2^{-k}
	\\ 1 \\ 2^k
	\end{pmatrix}\,.\end{equation}
Suppose $v$ has weight $\Theta\equiv\Theta_v$, of the functional form \eqref{e:factorize.internal.weights.in.cpd} from Definition~\ref{d:param.weights.Lambda} (with $\theta$ in place of $\lambda$). Assume that the measure $\mu\equiv\nu_{\delta v}[\Theta;\hat{p}]$ (defined using the notation of \eqref{e:defn.nu.Lambda.q}) is judicious in the sense of 
Definition~\ref{d:nu.judicious},
and that
	\begin{equation}\label{e:assume.variable.weights.close.to.one}
	\adjustlimits
	\sum_{j=1,2}\sum_{x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}}
	\Big|\theta^j(x)-1\Big| \le
	\frac{k^{O(1)}}{2^{k\zeta}}\,,\quad
	\max_{e\in\delta v}\Bigg\{
	\sum_{j=1,2}
	\Big|(\theta_e)^j-1\Big|
	 \Bigg\}
	\le \frac{ k^{O(1)}}{2^{k\zeta}}\,.
	\end{equation}
Let $\hat{q}$ be another set of incoming messages,
also satisfying \eqref{e:condition.on.hat.messages}, such that for all $e\in\delta v$ we have
	\[
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\hat{p}_e,\hat{q}_e)
	\le \begin{pmatrix} 
		\epsilon_e \\ \dot{\epsilon}_e
		\\ \ddot{\epsilon}_e\end{pmatrix}
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix} 
	2^{-k}
	\\ 1 \\ 2^k
	\end{pmatrix}\,.
	\]
Then there exist weights $\Lambda\equiv\Lambda_v$
(also parametrized as 
\eqref{e:factorize.internal.weights.in.cpd} from
Definition~\ref{d:param.weights.Lambda}) 
such that
	\begin{align}
	\label{e:defn.of.err.v.notation}
	\sum_{j=1,2}
	\sum_{x\in\set{\SPIN{-},\SPIN{f}}}
	\Bigg|\frac{\lambda^j(x)}{\theta^j(x)}-1\Bigg|
	&\le k^{O(1)} \Bigg(
		\overbrace{
		\sum_{e'\in\delta v}\bigg\{
		\epsilon_{e'}
		+\frac{\dot{\epsilon}_{e'}}{2^k}
		+\frac{\min\set{\ddot{\epsilon}_{e'},1}}
		{2^{k(1+\zeta)}}
		\bigg\}
		}^{\textup{denote this }\textup{\textsf{err}}_v}
		\Bigg)\,,\\
	\sum_{j=1,2}
	\Bigg|
	\frac{(\lambda_e)^j}{(\theta_e)^j}-1
	\Bigg|
	&\le k^{O(1)}\Bigg(
	\dot{\epsilon}_e
	+\frac{\min\set{\ddot{\epsilon}_e,1}}{2^{k\zeta}}
	+ \textup{\textsf{err}}_v
	\Bigg) \nonumber
	\end{align}
and $\nu_{\delta v}[\Lambda;\hat{q}]$ is again judicious
in the sense of Definition~\ref{d:nu.judicious}.

Assume that the measure $\mu\equiv\nu_{\delta v}[\Theta;\hat{p}]$ (defined using the notation of \eqref{e:defn.nu.Lambda.q}) is judicious in the sense of 
Definition~\ref{d:nu.judicious},
and that
	\begin{equation}\label{e:assume.variable.weights.close.to.one}
	\adjustlimits
	\sum_{j=1,2}\sum_{x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}}
	\Big|\theta^j(x)-1\Big| \le
	\frac{k^{O(1)}}{2^{k\zeta}}\,,\quad
	\max_{e\in\delta v}\Bigg\{
	\sum_{j=1,2}
	\Big|(\theta_e)^j-1\Big|
	 \Bigg\}
	\le \frac{ k^{O(1)}}{2^{k\zeta}}\,.
	\end{equation}

Then there exist weights $\Lambda\equiv\Lambda_v$
(also parametrized as 
\eqref{e:factorize.internal.weights.in.cpd} from
Definition~\ref{d:param.weights.Lambda}) 
such that
	\begin{align}
	\label{e:defn.of.err.v.notation}
	\sum_{j=1,2}
	\sum_{x\in\set{\SPIN{-},\SPIN{f}}}
	\Bigg|\frac{\lambda^j(x)}{\theta^j(x)}-1\Bigg|
	&\le k^{O(1)} \Bigg(
		\overbrace{
		\sum_{e'\in\delta v}\bigg\{
		\epsilon_{e'}
		+\frac{\dot{\epsilon}_{e'}}{2^k}
		+\frac{\min\set{\ddot{\epsilon}_{e'},1}}
		{2^{k(1+\zeta)}}
		\bigg\}
		}^{\textup{denote this }\textup{\textsf{err}}_v}
		\Bigg)\,,\\
	\sum_{j=1,2}
	\Bigg|
	\frac{(\lambda_e)^j}{(\theta_e)^j}-1
	\Bigg|
	&\le k^{O(1)}\Bigg(
	\dot{\epsilon}_e
	+\frac{\min\set{\ddot{\epsilon}_e,1}}{2^{k\zeta}}
	+ \textup{\textsf{err}}_v
	\Bigg) \nonumber
	\end{align}
and $\nu_{\delta v}[\Lambda;\hat{q}]$ is again judicious
in the sense of Definition~\ref{d:nu.judicious}.

\label{l:variable.close.to.product}
Let $v$ be a nice variable with incoming messages $\hat{q}$ (in the pair model)
satisfying condition \eqref{e:condition.on.hat.messages}.
Let $\nu$ be the resulting 
probability measure on the frozen spin $x_v\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$. 
Then $\nu$ is close to a product measure:
	\begin{equation}\label{e:frozen.product.approx}
	\nu(x)
	=\Bigg\{ 1 + O\bigg(\frac{1}{2^{k\zeta}}\bigg)
		\Bigg\} \cdot
	\begin{cases}
	1/4 & \textup{for } x\in \set{\SPIN{-},\SPIN{+}}^2\,,\\
	1/(4 \cdot 2^k)
		&\textup{for }x\in\set{\SPIN{-}\SPIN{f},\SPIN{+}\SPIN{f},
			\SPIN{f}\SPIN{-},\SPIN{f}\SPIN{+}}\,, \\ 
	1/(4 \cdot 4^k)
		&\textup{for }
			x=\SPIN{f}\SPIN{f}
	\end{cases}\end{equation}
for an absolute constant $0<\zeta\le1/20$.

\begin{proof}
This is a fairly direct calculation. 
Recall that $v$ is a nice variable,
so by Remark~\ref{r:adjusted.bp.stability}, condition~\eqref{e:condition.on.hat.messages} also holds with ${}_{\star\star}\hspace{-1pt}\hat{q}_e\equiv {}_\star\hspace{-1pt}\hat{q}_e\otimes{}_\star\hspace{-1pt}\hat{q}_e$ in place of ${}_{*}\hat{q}_e \equiv {}_\bullet\hspace{-1pt}\hat{q}_e\otimes{}_\bullet\hspace{-1pt}\hat{q}_e$. The degrees $|\delta v(\SPIN{\textpm})|$ are constrained by Definition~\ref{d:nice}, as are the canonical messages ${}_\star\hspace{-1pt}\hat{q}$; recall moreover that ${}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{y})={}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{g})={}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{b})$. We will use these facts repeatedly in what follows.
Recall moreover from \eqref{e:cyan.purple} that we defined $\SSPIN{p}\equiv\SPIN{purple}\equiv\set{\SSPIN{r},\SSPIN{b}}$. \smallskip


\noindent\bemph{Step 1. Estimates in single-copy model.} Consider the variable $v$ with incoming messages ${}_\star\hspace{-1pt}\hat{q}$, and let $\pi$ denote the resulting law of the 
frozen spin $x_v\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}$. Then, for a normalizing constant $z_\star$, we have
	\[ \pi(\SPIN{f})
	=\frac1{z_\star}
	\Bigg\{\prod_{e\in\delta v(\SPIN{+})}
	{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{g})\Bigg\}\Bigg\{
	\prod_{e\in\delta v(\SPIN{-})}
	{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{g})\Bigg\}
	=\frac1{z_\star}
	\Bigg\{\prod_{e\in\delta v(\SPIN{+})}
	{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{b})\Bigg\}\Bigg\{
	\prod_{e\in\delta v(\SPIN{-})}
	{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{b})\Bigg\}\]
Then, using the conditions from Definition~\ref{d:nice}, we have
	\begin{align*}
	\frac{\pi(\SPIN{+})}{\pi(\SPIN{f})}
	&=\Bigg\{1 - O\bigg(\frac1{2^k}\bigg)\Bigg\}
	\Bigg\{
	\prod_{e\in\delta v(\SPIN{+})}
	\frac{{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{p})}{{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{g})}
	\Bigg\}\Bigg\{\prod_{e\in\delta v(\SPIN{-})}
	\frac{{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{y})}{{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{g})}
	\Bigg\} \\
	&=\Bigg\{1 - O\bigg(\frac1{2^k}\bigg)\Bigg\}
	\prod_{e\in\delta v(\SPIN{+})}
	\bigg( 1 + \frac{1 + O(2^{-k/10})}
	{2^{|\partial a(e)|-1}} \bigg)
	=2^k
	\Bigg\{ 1 + O\bigg( \frac{k}{2^{k/10}}\bigg)\Bigg\}\,,
	\end{align*}
where $a(e)$ refers to the clause incident to edge $e$. The same estimate holds for $\pi(\SPIN{-})$. It follows that
	\[
	\pi(x)
	= \Bigg\{ 1 + O\bigg( \frac{k}{2^{k/10}}\bigg)\Bigg\}
	\times
	\begin{cases}
	1/2 &\textup{for }x\in\set{\SPIN{-},\SPIN{+}}\,,\\
	1/2^{k+1}
		&\textup{for }x=\SPIN{f}\,.
	\end{cases}\smallskip
	\]

\noindent\bemph{Step 2. Estimates in pair model.}
Let $\nu_\star\equiv\pi\otimes\pi$. Let $z,z_\star$ be the normalizing constant such that
	\[
	\nu(\SPIN{f}\SPIN{f})
	= \frac1{z}
	\prod_{e\in\delta v}
	\hat{q}_e(\SSPIN{g}\SSPIN{g})\,,\quad
	\nu_\star(\SPIN{f}\SPIN{f})
	=\frac1{z_\star}
	\prod_{e\in\delta v}
	{}_{\star\star}\hspace{-1pt}\hat{q}_e(\SSPIN{g}\SSPIN{g})\,.\]
Taking the ratio between the two and using the assumption \eqref{e:condition.on.hat.messages} gives
	\[
	\frac{z\nu(\SPIN{f}\SPIN{f})}{z_\star\nu_\star(\SPIN{f}\SPIN{f})}
	=\prod_{e\in \delta v} \Bigg(
	1 + \frac{k^{O(1)}}{2^{k(1+\zeta)}}\Bigg)
	=1 + O\bigg( \frac{k^{O(1)}}{2^{k\zeta}}\bigg)\,.
	\]
Similarly, we use \eqref{e:condition.on.hat.messages} again to calculate that
	\begin{align*}
	z\nu(\SPIN{+}\SPIN{f})
	&= \Bigg\{
	\prod_{e\in\delta v(\SPIN{+})} \hat{q}_e(\SSPIN{p}\SSPIN{g})
	\Bigg\}\Bigg\{
	\prod_{e\in\delta v(\SPIN{-})} \hat{q}_e(\SSPIN{y}\SSPIN{g})
	\Bigg\}
	\Bigg\{
	1-\prod_{e\in\delta v(\SPIN{+})}
	\bigg(
	1-\frac{\hat{q}_e(\SSPIN{r}\SSPIN{g})}{\hat{q}_e(\SSPIN{p}\SSPIN{g})}
	\bigg)
	\Bigg\} \\
	&= \Bigg\{
	\prod_{e\in\delta v(\SPIN{+})} \hat{q}_e(\SSPIN{p}\SSPIN{g})
	\Bigg\}\Bigg\{
	\prod_{e\in\delta v(\SPIN{-})} \hat{q}_e(\SSPIN{y}\SSPIN{g})
	\Bigg\}
	\Bigg\{
	1-\prod_{e\in\delta v(\SPIN{+})}
	\bigg(
	1-\frac{ 1 + O(k^{O(1)}/2^{k\zeta})
		}{2^{|\partial a(e)|-1}}
	\bigg)
	\Bigg\} \\
	&=
	\Bigg\{
	\prod_{e\in\delta v(\SPIN{+})} \hat{q}_e(\SSPIN{p}\SSPIN{g})
	\Bigg\}\Bigg\{
	\prod_{e\in\delta v(\SPIN{-})} \hat{q}_e(\SSPIN{y}\SSPIN{g})
	\Bigg\}
	\Bigg\{
	1 + O\bigg(\frac1{2^k}\bigg)\Bigg\}
	=z_\star\nu_\star(\SPIN{+}\SPIN{f})
	\Bigg\{ 1 + O\bigg(\frac{k^{O(1)}}{2^{k\zeta}}
	\bigg)\Bigg\}
	\,.
	\end{align*}
The same estimate holds for the spins in
$\set{\SPIN{f}\SPIN{+},\SPIN{-}\SPIN{f},\SPIN{f}\SPIN{-}}$. A similar calculation gives
	\begin{align*}
	z\nu(\SPIN{+}\SPIN{+})
	&= \Bigg\{
	\prod_{e\in\delta v(\SPIN{+})} \hat{q}_e(\SSPIN{p}\SSPIN{p})
	\Bigg\}\Bigg\{
	\prod_{e\in\delta v(\SPIN{-})} \hat{q}_e(\SSPIN{y}\SSPIN{y})
	\Bigg\}
	\Bigg\{
	1
	-\prod_{e\in\delta v(\SPIN{+})}
	\bigg(1-
	\frac{\hat{q}_e(\SSPIN{r}\SSPIN{p})}{\hat{q}_e(\SSPIN{p}\SSPIN{p})}
	\bigg)
	-\prod_{e\in\delta v(\SPIN{+})}
	\bigg(
	1-\frac{\hat{q}_e(\SSPIN{p}\SSPIN{r})}{\hat{q}_e(\SSPIN{p}\SSPIN{p})}
	\bigg)
	+\prod_{e\in\delta v(\SPIN{+})}
	\frac{\hat{q}_e(\SSPIN{b}\SSPIN{b})}{\hat{q}_e(\SSPIN{p}\SSPIN{p})}
	\Bigg\} \\
	&=
	\Bigg\{
	\prod_{e\in\delta v(\SPIN{+})} \hat{q}_e(\SSPIN{p}\SSPIN{p})
	\Bigg\}\Bigg\{
	\prod_{e\in\delta v(\SPIN{-})} \hat{q}_e(\SSPIN{y}\SSPIN{y})
	\Bigg\}
	\Bigg\{ 1 + O\bigg(\frac{k^{O(1)}}{2^{k\zeta}}
	\bigg)\Bigg\}
	= z_\star\nu_\star(\SPIN{+}\SPIN{+})
	\Bigg\{ 1 + O\bigg(\frac{k^{O(1)}}{2^{k\zeta}}
	\bigg)\Bigg\}\,,
	\end{align*}
and the same estimate holds for the other spins in $\set{\SPIN{+}\SPIN{-},\SPIN{-}\SPIN{+},\SPIN{-}\SPIN{-}}$. Therefore
	\begin{equation}\label{e:frozen.product.approx.pi}
	\nu(x)
	= \pi(x^1)\pi(x^2)
\Bigg\{ 1 + O\bigg(\frac{k^{O(1)}}{2^{k\zeta}}\bigg)
		\Bigg\} \,,
	\end{equation}
and the claim follows.
\end{proof}

This is a fairly direct calculation. 
Recall that $v$ is a nice variable,
so by Remark~\ref{r:adjusted.bp.stability}, condition~\eqref{e:condition.on.hat.messages} also holds with ${}_{\star\star}\hspace{-1pt}\hat{q}_e\equiv {}_\star\hspace{-1pt}\hat{q}_e\otimes{}_\star\hspace{-1pt}\hat{q}_e$ in place of ${}_{*}\hat{q}_e \equiv {}_\bullet\hspace{-1pt}\hat{q}_e\otimes{}_\bullet\hspace{-1pt}\hat{q}_e$. The degrees $|\delta v(\SPIN{\textpm})|$ are constrained by Definition~\ref{d:nice}, as are the canonical messages ${}_\star\hspace{-1pt}\hat{q}$; recall moreover that ${}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{y})={}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{g})={}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{b})$. We will use these facts repeatedly in what follows.
Recall moreover from \eqref{e:cyan.purple} that we defined $\SSPIN{p}\equiv\SPIN{purple}\equiv\set{\SSPIN{r},\SSPIN{b}}$. \smallskip


\noindent\bemph{Step 1. Estimates in single-copy model.} Consider the variable $v$ with incoming messages ${}_\star\hspace{-1pt}\hat{q}$, and let $\pi$ denote the resulting law of the 
frozen spin $x_v\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}$. Then, for a normalizing constant $z_\star$, we have
	\[ \pi(\SPIN{f})
	=\frac1{z_\star}
	\Bigg\{\prod_{e\in\delta v(\SPIN{+})}
	{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{g})\Bigg\}\Bigg\{
	\prod_{e\in\delta v(\SPIN{-})}
	{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{g})\Bigg\}
	=\frac1{z_\star}
	\Bigg\{\prod_{e\in\delta v(\SPIN{+})}
	{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{b})\Bigg\}\Bigg\{
	\prod_{e\in\delta v(\SPIN{-})}
	{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{b})\Bigg\}\]
Then, using the conditions from Definition~\ref{d:nice}, we have
	\begin{align*}
	\frac{\pi(\SPIN{+})}{\pi(\SPIN{f})}
	&=\Bigg\{1 - O\bigg(\frac1{2^k}\bigg)\Bigg\}
	\Bigg\{
	\prod_{e\in\delta v(\SPIN{+})}
	\frac{{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{p})}{{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{g})}
	\Bigg\}\Bigg\{\prod_{e\in\delta v(\SPIN{-})}
	\frac{{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{y})}{{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{g})}
	\Bigg\} \\
	&=\Bigg\{1 - O\bigg(\frac1{2^k}\bigg)\Bigg\}
	\prod_{e\in\delta v(\SPIN{+})}
	\bigg( 1 + \frac{1 + O(2^{-k/10})}
	{2^{|\partial a(e)|-1}} \bigg)
	=2^k
	\Bigg\{ 1 + O\bigg( \frac{k}{2^{k/10}}\bigg)\Bigg\}\,,
	\end{align*}
where $a(e)$ refers to the clause incident to edge $e$. The same estimate holds for $\pi(\SPIN{-})$. It follows that
	\[
	\pi(x)
	= \Bigg\{ 1 + O\bigg( \frac{k}{2^{k/10}}\bigg)\Bigg\}
	\times
	\begin{cases}
	1/2 &\textup{for }x\in\set{\SPIN{-},\SPIN{+}}\,,\\
	1/2^{k+1}
		&\textup{for }x=\SPIN{f}\,.
	\end{cases}\smallskip
	\]

\noindent\bemph{Step 2. Estimates in pair model.}
Let $\nu_\star\equiv\pi\otimes\pi$. Let $z,z_\star$ be the normalizing constant such that
