\label{l:perturb.red.weights}
Let $v$ be a nice variable. Suppose we are given two sets of weights for $v$, $\Theta$ and $\Lambda$, both 
 of the functional form \eqref{e:factorize.internal.weights.in.cpd} from
Definition~\ref{d:param.weights.Lambda}, satisfying the bound
\eqref{e:bound.on.frozen.weights} from Lemma~\ref{l:transfer.error}, and additionally such that
	\begin{equation}\label{e:cond.on.msg.for.edge.weight.perturb}
	\max_{e\in\delta v}\Bigg\{
	\sum_{j=1,2}
	\bigg(
	\Big|(\theta_e)^j-1\Big|
	+\Big|(\lambda_e)^j-1\Big|
	\bigg)
	\Bigg\}
	\le \frac{k^{O(1)}}{2^{k\zeta}}\,.
	\end{equation}
Assume that the weights on the frozen spin agree, i.e., $\lambda^j(x)=\theta^j(x)$ for $j=1,2$
and all $x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}$, so that only the edge weights can differ betweeen $\Theta$ and $\Lambda$. 
Denote the error in the edge weights by
	\[
	(\rho_e)^j
	\equiv
	\frac{(\lambda_e)^j}{(\theta_e)^j}-1
	\equiv
	\frac{(\lambda_e)^j(\SSPIN{r})}{(\theta_e)^j(\SSPIN{r})}-1\,.
	\]
Let $v$ have incoming messages $\hat{q}$ (in the pair model) satisfying \eqref{e:condition.on.hat.messages}.
Let $\mu=\nu_{\delta v}[\Theta;\hat{q}]$
and $\nu=\nu_{\delta v}[\Lambda;\hat{q}]$,
with edge marginals $\mu_e$ and $\nu_e$
for $e\in\delta v$. Then
it holds for all $e\in\delta v$ that
	\[\frac{(\nu_e)^1(\SSPIN{r})}{(\nu_e)^1(\SSPIN{b})}
	=
	\frac{(\lambda_e)^1}{(\theta_e)^1}
	\cdot
	\frac{(\mu_e)^1(\SSPIN{r})}{(\mu_e)^1(\SSPIN{b})}
	\Bigg\{
	1 + O\Bigg(
	k^{O(1)}\bigg[
	{\frac{(\rho_e)^2}{2^{k\zeta}} }+
	\sum_{j=1,2}
		\sum_{e'\in\delta v \setminus e}
		\frac{|(\rho_{e'})^j|}{2^{k(1+\zeta)}}
	\bigg]\Bigg)
	\Bigg\}\,.\]
This says that the marginal $\SPIN{red}$-to-$\SPIN{blue}$ ratio in the first copy is changed by a factor of approximately $(\lambda_e)^1/(\theta_e)^1$
--- i.e., for the first-copy marginal on $e$, changing the edge weights in both copies on all of $\delta v$ has approximately the same effect as changing the edge weight in the first copy only, on $e$ alone.
The analogous bound holds exchanging the copy indices $j=1,2$.


\begin{proof} For $e\in\delta v$ 
let $g_e,h_e$ be the non-normalized measures
on $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$ defined by
	\begin{align*}
	g_e(\sigma)
	&\equiv \hat{q}_e(\sigma)\theta_e(\sigma)
	=\hat{q}_e(\sigma)
	\Bigg\{
	\prod_{j=1,2}
	( (\theta_e)^j)^{\Ind{\sigma^1=\SSPIN{r}}}
	\Bigg\}\,,\\
	h_e(\sigma)
	&\equiv \hat{q}_e(\sigma)\lambda_e(\sigma)
	= g_e(\sigma)
	\Bigg\{
	\prod_{j=1,2}
	\bigg(
	 1 + ((\rho_e)^j)^{\Ind{\sigma^j=\SSPIN{r}}}
	 \bigg)
	\Bigg\}\,.
	\end{align*}
Similarly as in \eqref{e:incident.edges.of.same.sign}, 
let $\delta v(\SPIN{\textpm} e)
\equiv \set{e'\in\delta v\setminus e : \SPIN{L}_e=\SPIN{\textpm} \SPIN{L}_{e'}}$. Then, for some normalizing constants $z_e,\bar{z}_e$ we have
	\begin{align*}
			\frac{\bar{z}_e\mu_e(\SSPIN{r}\SSPIN{r})}
		{\theta^1(\SPIN{L}_e)\theta^2(\SPIN{L}_e)}
	&=
	(\theta_e)^1(\theta_e)^2
	\hat{q}_e(\SSPIN{r}\SSPIN{r})
	\Bigg\{
	\prod_{e'\in\delta v(\SPIN{+} e)}
	g_{e'}(\SSPIN{p}\SSPIN{p})
	\Bigg\}\Bigg\{
	\prod_{e'\in\delta v(\SPIN{-} e)}
	g_{e'}(\SSPIN{y}\SSPIN{y})\Bigg\}
	\,,\\
	\frac{z_e\nu_e(\SSPIN{r}\SSPIN{r})}
		{\theta^1(\SPIN{L}_e)\theta^2(\SPIN{L}_e)}
	&=
	(\lambda_e)^1 (\lambda_e)^2 
	\hat{q}_e(\SSPIN{r}\SSPIN{r})
	\Bigg\{
	\prod_{e'\in\delta v(\SPIN{+} e)}
	h_{e'}(\SSPIN{p}\SSPIN{p})
	\Bigg\}\Bigg\{
	\prod_{e'\in\delta v(\SPIN{-} e)}
	h_{e'}(\SSPIN{y}\SSPIN{y})\Bigg\}
	\,.\end{align*}
Note that $g_{e'}(\SSPIN{y}\SSPIN{y})=\hat{q}_{e'}(\SSPIN{y}\SSPIN{y})=h_{e'}(\SSPIN{y}\SSPIN{y})$ for all $e'\in\delta v$. On the other hand, we can estimate
	\begin{align*}
	&\prod_{e'\in\delta v(\SPIN{+} e)}
	\frac{h_{e'}(\SSPIN{p}\SSPIN{p})}
	{g_{e'}(\SSPIN{p}\SSPIN{p})}
	=\prod_{e'\in\delta v(\SPIN{+} e)}
	\Bigg\{
	1+
	\frac{
	(\rho_{e'})^1 g_{e'}(\SSPIN{r}\SSPIN{p})
	+(\rho_{e'})^2 g_{e'}(\SSPIN{p}\SSPIN{r})
	+(\rho_{e'})^1(\rho_{e'})^2 g_{e'}(\SSPIN{r}\SSPIN{r})
	}
	{g_{e'}(\SSPIN{p}\SSPIN{p})}\Bigg\} \\










	&\quad
	\stackrel{\eqref{e:cond.on.msg.for.edge.weight.perturb}}{=}
	\prod_{e'\in\delta v(\SPIN{+} e)}
	\Bigg\{
	1+
	\bigg(1 + \frac{k^{O(1)}}{2^{k\zeta}}\bigg)
	\frac{
	(\rho_{e'})^1 \hat{q}_{e'}(\SSPIN{r}\SSPIN{p})
	+(\rho_{e'})^2 \hat{q}_{e'}(\SSPIN{p}\SSPIN{r})
	}
	{ \hat{q}_{e'}(\SSPIN{p}\SSPIN{p})}
	+O\bigg(\frac{(\rho_{e'})^1(\rho_{e'})^2}
		{ 2^{k(1+\zeta)} }
		\bigg)
	\Bigg\}\\
	&\quad
	\stackrel{\eqref{e:condition.on.hat.messages}}{=}
	1 +
	\sum_{j=1,2}\Bigg(
	\underbrace{\sum_{e'\in\delta v(\SPIN{+} e)}
			\frac{(\rho_{e'})^j {}_\star\hspace{-1pt}\hat{q}_{e'}(\SSPIN{r})}
				{{}_\star\hspace{-1pt}\hat{q}_{e'}(\SSPIN{b})}
				}_{\textup{denote this }A^j(\SPIN{+})}
				\Bigg)
	+ O\Bigg(\underbrace{
	\sum_{j=1,2}\sum_{e'\in\delta v\setminus e}
	\frac{k^{O(1)} |(\rho_{e'})^j|}{2^{k(1+\zeta)}}
	}_{\textup{denote this }R_0}
	\Bigg)
	\end{align*}
(having implicitly used Remark~\ref{r:adjusted.bp.stability} together with
\eqref{e:condition.on.hat.messages}). It follows that
	\[
	\frac{z_e\nu_e(\SSPIN{r}\SSPIN{r})}
		{\bar{z}_e\mu_e(\SSPIN{r}\SSPIN{r})}
	\Bigg\{\prod_{j=1,2}
	\frac{(\theta_e)^j}{(\lambda_e)^j}
	\Bigg\}
