	\frac{(\theta_e)^j}{(\lambda_e)^j}
	\bigg)^{\Ind{\sigma^j=\SSPIN{r}}}
	\Bigg\}
	=
	1 + A^1(\SPIN{+})+ A^2(\SPIN{+}) + O(R_0)\,.\]
Let $A^j(\SPIN{-})$ be define analogously to
$A^j(\SPIN{+})$, except that we sum over $e'\in\delta v(\SPIN{-} e)$ rather than 
$e'\in\delta v(\SPIN{+} e)$. Then similar calculations as above give the estimates
	\begin{align*}
	\frac{z_e\nu_e(\SSPIN{r}\SSPIN{y})}
		{\bar{z}_e\mu_e(\SSPIN{r}\SSPIN{y})}
	\frac{(\theta_e)^1}{(\lambda_e)^1}
	&= 
	1 + A^1(\SPIN{+})+ A^2(\SPIN{-}) + O(R_0)
	=\frac{z_e\nu_e(\SSPIN{b}\SSPIN{y})}
		{\bar{z}_e\mu_e(\SSPIN{b}\SSPIN{y})}\,,\\
	\frac{z_e\nu_e(\SSPIN{r}\SSPIN{g})}
		{\bar{z}_e\mu_e(\SSPIN{r}\SSPIN{g})}
	\frac{(\theta_e)^1}{(\lambda_e)^1}
	&=
	1 + A^1(\SPIN{+}) + O(R_0)
	=\frac{z_e\nu_e(\SSPIN{b}\SSPIN{g})}
		{\bar{z}_e\mu_e(\SSPIN{b}\SSPIN{g})}\,.
	\end{align*}
Combining these estimates gives 
	\begin{align*}
	\frac{(\nu_e)^1(\SSPIN{r})}
	{(\nu_e)^1(\SSPIN{b})}
	&=\frac{(\lambda_e)^1}{(\theta_e)^1}
	\frac{(\mu_e)^1(\SSPIN{r})[1+A^1(\SPIN{+})]
	+\mu_e(\SSPIN{r}\SSPIN{p})A^2(\SPIN{+})
	+\mu_e(\SSPIN{r}\SSPIN{y})A^2(\SPIN{-})
	+O(\mu_e(\SSPIN{r}\SSPIN{r}) (\rho_e)^2)}
	{(\mu_e)^1(\SSPIN{b})[1+A^1(\SPIN{+})]
	+\mu_e(\SSPIN{b}\SSPIN{p})A^2(\SPIN{+})
	+\mu_e(\SSPIN{b}\SSPIN{y})A^2(\SPIN{-})
	+O(\mu_e(\SSPIN{b}\SSPIN{r})(\rho_e)^2)
	}\Bigg\{1+O(R_0)\Bigg\}\\
	&=
	\frac{(\lambda_e)^1}{(\theta_e)^1}
	\frac{(\mu_e)^1(\SSPIN{r})}{(\mu_e)^1(\SSPIN{b})}
	\frac{\displaystyle 1
	+ \frac{\mu_e(\SSPIN{r}\SSPIN{p})A^2(\SPIN{+})}
		{(\mu_e)^1(\SSPIN{r})[1+A^1(\SPIN{+})]}
	+\frac{\mu_e(\SSPIN{r}\SSPIN{y})A^2(\SPIN{-})}
		{(\mu_e)^1(\SSPIN{r})[1+A^1(\SPIN{+})]}
	+ O\bigg( \frac{k^{O(1)}(\rho_e)^2}{2^{k\zeta}}\bigg)
	}{\displaystyle 1
	+ \frac{\mu_e(\SSPIN{b}\SSPIN{p})A^2(\SPIN{+})}
		{(\mu_e)^1(\SSPIN{b})[1+A^1(\SPIN{+})]}
	+\frac{\mu_e(\SSPIN{b}\SSPIN{y})A^2(\SPIN{-})}
		{(\mu_e)^1(\SSPIN{b})[1+A^1(\SPIN{+})]}
	+ O\bigg( \frac{(\rho_e)^2}{2^k}\bigg)
	}\Bigg\{1+O(R_0)\Bigg\}\\
	&=\frac{(\lambda_e)^1}{(\theta_e)^1}
	\frac{(\mu_e)^1(\SSPIN{r})}{(\mu_e)^1(\SSPIN{b})}
	\Bigg\{1+O\bigg(
	\frac{k^{O(1)}(\rho_e)^2}{2^{k\zeta}}+R_0 
		\bigg)\Bigg\}\,.
	\end{align*}
In the last step we used the assumptions
 \eqref{e:condition.on.hat.messages},
 \eqref{e:bound.on.frozen.weights}, and \eqref{e:cond.on.msg.for.edge.weight.perturb}, which together guarantee that
	\begin{align*}
	\frac{\mu_e(\SSPIN{r}\SSPIN{p})}
	{(\mu_e)^1(\SSPIN{r})}
	&={}_\star\hspace{-1pt}\pi_e(\SSPIN{p})\Bigg\{ 1 + O\bigg(
		\frac{k^{O(1)}}{2^{k\zeta}}
		\bigg)\Bigg\}
	=\frac{\mu_e(\SSPIN{b}\SSPIN{p})}
	{(\mu_e)^1(\SSPIN{b})}\,,\\
	\frac{\mu_e(\SSPIN{r}\SSPIN{y})}
	{(\mu_e)^1(\SSPIN{r})}
	&={}_\star\hspace{-1pt}\pi_e(\SSPIN{y})\Bigg\{ 1 + O\bigg(
		\frac{k^{O(1)}}{2^{k\zeta}}
		\bigg)\Bigg\}
	=\frac{\mu_e(\SSPIN{b}\SSPIN{y})}
	{(\mu_e)^1(\SSPIN{b})}\,.
	\end{align*}
The claim follows.
\end{proof}

