We first define a sequence of weights $\Lambda_t$, then analyze the construction to show that they converge to the desired weights $\Lambda_\infty=\Lambda$. We emphasize that this index $t$ is \bemph{purely local to the proof of this proposition}, and is not the same as the $t$ that indexes the up-and-down passes in
Definition~\ref{d:nice.lagrange.defn.weights}. The proof below is divided into a few numbered parts.
\smallskip

\noindent\bemph{Part~1. Iterative definition of weights.} Initialize $\Lambda_0=\Theta$. For all $t\ge0$, given the weights $\Lambda_t$, let $\nu_t\equiv\nu_{\delta v}[\Lambda_t;\hat{q}]$. Then, for all $e\in\delta v$, update the edge weights by setting, for both $j=1,2$,
\begin{equation}\label{e:var.update.edgeupdate}
	(\lambda_{e,t+1})^j
	=(\lambda_{e,t})^j \cdot \frac{
	 {}_\star\hspace{-1pt}\pi_e(\SSPIN{r}) / {}_\star\hspace{-1pt}\pi_e(\SSPIN{b})}
	{ (\nu_{e,t})^j (\SSPIN{r}) / (\nu_{e,t})^j(\SSPIN{b})}\,.
	\end{equation}
Let $\nu_{t+1/2}$
be the measure 
that results from
incoming messages $\hat{q}$,
frozen spin weights $\lambda_t$,
and edge weights $\lambda_{e,t+1}$
for all $e\in\delta v$.
Let $\pi_{t+1/2}$ be the
induced measure on the frozen spin
$x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$.
Let $\pi$ be the measure on
the single spin $x^j\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}$ that
is induced by ${}_\star\hspace{-1pt}\pi$.
Then update the frozen spin weights by setting, for both $j=1,2$,
	\begin{equation}\label{e:var.update.frozenupdate}
	(\lambda_{t+1})^j(x^j)
	=(\lambda_t)^j(x^j)
	\cdot
	\frac{\pi(x^j) / \pi(\SPIN{+})}
	{(\pi_{t+1/2})^j(x^j) / (\pi_{t+1/2})^j(\SPIN{+})}\,.
	\end{equation}
This concludes the definition of the weights $\Lambda_{t+1}$.\smallskip

\noindent\bemph{Part~2. Definition of error quantities.} Define the error quantities
	\[
	(\delta_t)^j
	\equiv
	\sum_{x\in\set{\SPIN{-},\SPIN{f}}}
	\Bigg|
	\frac{\pi(x^j)/\pi(\SPIN{+})}
		{
		(\pi_t)^j(x^j)/(\pi_t)^j(\SPIN{+})
		}-1
	\Bigg|\,,\quad
	(\rho_{e,t})^j
	\equiv
	\bigg|
	\frac{
	 {}_\star\hspace{-1pt}\pi_e(\SSPIN{r}) / {}_\star\hspace{-1pt}\pi_e(\SSPIN{b})}
	{ (\nu_{e,t})^j (\SSPIN{r}) / (\nu_{e,t})^j(\SSPIN{b})}
	-1
	\bigg|\,.
	\]
We will keep track of the aggregate errors
	\[
	\bm{\delta}_t
	\equiv\sum_{j=1,2} (\delta_t)^j\,,\quad
	\rho_{e,t}
	\equiv
	\sum_{j=1,2}
	(\rho_{e,t})^j\,,\quad
	\bm{\rho}_t
	\equiv \sum_{e\in\delta v}
		\rho_{e,t}\,.
	\]
For the initial measure $\nu_0=\nu_{\delta v}[\Lambda_0;\hat{q}]=\nu_{\delta v}[\Theta;\hat{q}]$,
it follows by straightforward calculations that
	\begin{align*}
	(\delta_0)^j
	&\le O\Bigg(\sum_{e'\in\delta v}\bigg\{
		\epsilon_{e'}
		+\frac{\dot{\epsilon}_{e'}}{2^k}
		+\frac{\min\set{\ddot{\epsilon}_{e'},1}
		}{2^{k(1+\zeta)}}
		\bigg\}
		\Bigg) = O(\textup{\textsf{err}}_v)\,,\\
	(\rho_{e,0})^j
	&\le O\Bigg(
	\dot{\epsilon}_e
	+\frac{\min\set{\ddot{\epsilon}_e,1}}{2^{k\zeta}}
	+\textup{\textsf{err}}_v
	\Bigg)
	\end{align*}
for both $j=1,2$ ---
this makes use of the assumptions~\eqref{e:condition.on.hat.messages} and \eqref{e:assume.variable.weights.close.to.one}.\smallskip

\noindent\bemph{Part~3. Effect of update on edge weights (from $t$ to $t+1/2$).} Recall that for each integer $t\ge0$, the procedure described in Part~1 goes from $t$ to $t+1/2$ by the update
\eqref{e:var.update.edgeupdate} on all the edge weights, leaving the frozen spin weights unchanged. For this update, Lemma~\ref{l:perturb.red.weights} gives
	\begin{equation}\label{e:redblue.update.on.updated.edge}
	(\rho_{e,t+1/2})^1
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{(\rho_{e,t})^2
	+ \frac{\bm{\rho}_t}{2^k}
	\Bigg\}\,,\end{equation}
with the analogous bound if we exchange $j=1,2$. 
Summing 
\eqref{e:redblue.update.on.updated.edge}
 over $j=1,2$ and over all $e\in\delta v$ gives
	\begin{equation}\label{e:redblue.update.on.updated.edge.simp}
	\bm{\rho}_{t+1/2}
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\bm{\rho}_t\,.
	\end{equation}
Meanwhile, the error in the frozen spin marginals can change by at most
	\begin{equation}\label{e:redblue.update.on.frozen}
	\bm{\delta}_{t+1/2}
	\le \bm{\delta}_t 
	+\frac{k^{O(1)} }{2^{k(1+\zeta)}}
	\bm{\rho}_t
	\,,\end{equation}
by a very similar calculation.\smallskip

\noindent\bemph{Part~4. Effect of update on frozen spin weights (from $t+1/2$ to $t+1$.} Next recall that for each integer $t\ge0$, the procedure of Part~1 goes from $t+1/2$ to $t+1$ by the update 
\eqref{e:var.update.frozenupdate}
on the frozen spin weights,
leaving the edge weights unchanged.
As a result the $\SPIN{red}$-to-$\SPIN{blue}$ ratios
are unaffected, so $(\rho_{e,t+1})^j=(\rho_{e,t})^j$.









As for the frozen spin marginals, the result of 
Lemma~\ref{l:transfer.error} gives
	\begin{equation}\label{e:frozen.update.frozen.result}
	\bm{\delta}_{t+1} 
	\le \frac{k^{O(1)}\bm{\delta}_{t+1/2}}{2^{k\zeta}}
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
		\bm{\delta}_t
		+
		\frac{\bm{\rho}_t}{2^{k(1+\zeta)}}
		\Bigg\}
	\end{equation}
where the last step is by \eqref{e:redblue.update.on.frozen}.\smallskip


\noindent\bemph{Part~5. Conclusion.}
For each integer $t\ge0$, when we go from $t$ to $t+1$ in the procedure of Part~1,
it follows by combining
\eqref{e:redblue.update.on.updated.edge.simp} and \eqref{e:frozen.update.frozen.result} that
	\[
	\begin{pmatrix}
	\bm{\delta}_{t+1}\\
	\bm{\rho}_{t+1}
	\end{pmatrix}
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	1 & 2^{-k(1+\zeta)} \\
	0 & 1
	\end{pmatrix}
	\begin{pmatrix}
	\bm{\delta}_t \\ \bm{\rho}_t
	\end{pmatrix}
	\]
(having used also that $\bm{\rho}_{t+1/2}=\bm{\rho}_t$). This implies
	\[
	\Upsilon_{t+1}
	\equiv
	\bm{\delta}_{t+1}
	+\frac{\bm{\rho}_{t+1}}{2^k}
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	\bm{\delta}_t 
	+ \frac{\bm{\rho}_t}{2^k}
	\Bigg\}
	= \frac{k^{O(1)}}{2^{k\zeta}} \Upsilon_t\,.
	\]
It follows that the iteration defined in Part~1 converges. The error on the frozen spin weights can be bounded as
	\begin{align*}
	\sum_{j=1,2}
	\sum_{x\in\set{\SPIN{-},\SPIN{f}}}
	\Bigg|\frac{\lambda^j(x)}{\theta^j(x)}-1\Bigg|
	&\le O\Bigg(
	\sum_{t=0}^\infty
	\sum_{j=1,2}
	\sum_{x\in\set{\SPIN{-},\SPIN{f}}}
	\bigg|\frac{(\lambda_{t+1})^j(x)}{(\lambda_t)^j(x)}-1\bigg|
	\Bigg)\\
	&\le O\Bigg(
		\sum_{t=0}^\infty \bm{\delta}_t\Bigg)
	\le O\Bigg(
		\sum_{t=0}^\infty\Upsilon_t\Bigg)
	\le O(\Upsilon_0) \le O(\textup{\textsf{err}}_v)\,.
	\end{align*}
To bound the error on the edge weights, let us first note that for any $e\in\delta v$, 
\eqref{e:redblue.update.on.updated.edge} implies
	\[
	\sum_{t\ge1} \rho_{e,t}
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\sum_{t\ge0}\Bigg\{
	\rho_{e,t} + \frac{\bm{\rho}_t}{2^k}
	\Bigg\}
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	\sum_{t\ge1} \rho_{e,t}
	+\bigg(
	\rho_{e,0}
	+\sum_{t\ge0} \Upsilon_t\bigg)\Bigg\}\,,
	\]
and rearranging the inequality gives
	\[
	\sum_{t\ge1} \rho_{e,t}
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	\rho_{e,0} + \sum_{t\ge0} \Upsilon_t\Bigg\}
	\le	\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	\rho_{e,0} + \textup{\textsf{err}}_v\Bigg\}\,.
	\]
It follows from this that the total error on the edge weights can be bounded as
	\begin{align*}
	\sum_{j=1,2}
	\Bigg|\frac{(\lambda_e)^j}
		{(\theta_e)^j}-1\Bigg|
	&\le O\Bigg(\sum_{t=0}^\infty
	\rho_{e,t}\Bigg)
	\le
	 O\Bigg( \rho_{e,0}
	 	+ \frac{k^{O(1)}}{2^{k\zeta}}
		\textup{\textsf{err}}_v
		\Bigg)
	\le
	O\Bigg(
	\dot{\epsilon}_e
	+\frac{\min\set{\ddot{\epsilon}_e,1}}{2^{k\zeta}}
	+\textup{\textsf{err}}_v
	\Bigg)\,.
	\end{align*}
This concludes the proof.

Let $P,Q$ be the reweightings of $\dot{p},\dot{q}$ defined by \eqref{e:reweighted.messages.v.to.c}.\smallskip

\noindent\bemph{Step 1. Non-marginal errors between $P$ and $Q$.} We claim that
Proposition~\ref{p:var.update} implies,
for each $e\in\delta v$,
	\begin{equation}\label{e:reweighted.var.msg.prelim.bd}
	\Bigg|\frac{Q_e(\sigma)}
		{P_e(\sigma)}-1\Bigg|
	\le k^{O(1)}
		\Bigg( \textup{\textsf{err}}_v
	+ \Ind{\SSPIN{r}[\sigma]\ge1}
	\bigg\{ \dot{\epsilon}_e
	+ \frac{\min\set{\ddot{\epsilon}_e,1}}
	{2^{k\zeta}}
	\bigg\}\Bigg)
	\end{equation}
We will only briefly sketch the proof of
\eqref{e:reweighted.var.msg.prelim.bd}:
let
$g_e(\sigma)=\theta_e(\sigma)\hat{q}_e(\sigma)$
and $h_e(\sigma)=\lambda_e(\sigma)\hat{p}_e(\sigma)$,
and let $Z_{Q,e}$
and $Z_{P,e}$ be the normalizing constants such that
	\[
	\frac{Z_{Q,e}Q_e(\SSPIN{r}\SSPIN{r})}{Z_{P,e}P_e(\SSPIN{r}\SSPIN{r})}
	=\Bigg\{
	\prod_{j=1,2}
	\frac{\lambda^j(\SPIN{L}_e) \cdot (\lambda_e)^j}
		{\theta^j(\SPIN{L}_e) \cdot (\theta_e)^j}
	\Bigg\}
	\prod_{e'\in\delta v(\SPIN{+} e)}
	\frac{h_{e'}(\SSPIN{p}\SSPIN{p})}{g_{e'}(\SSPIN{p}\SSPIN{p})}
	\prod_{e'\in\delta v(\SPIN{-} e)}
	\frac{h_{e'}(\SSPIN{y}\SSPIN{y})}{g_{e'}(\SSPIN{y}\SSPIN{y})}\,.
	\]
By the assumptions of
Proposition~\ref{p:var.update} together with the resulting bounds on the error between $\theta_e$ and $\lambda_e$, we have
	\[\Bigg|\frac{h_e(\SSPIN{p}\SSPIN{p})}{g_e(\SSPIN{p}\SSPIN{p})}-1\Bigg|
	\le
	k^{O(1)}
	\Bigg(\epsilon_e 
	+ \frac1{2^k}
	\bigg( \dot{\epsilon}_e+
	\frac{\min\set{\ddot{\epsilon}_e,1}}
		{2^{k\zeta}}
	+\textup{\textsf{err}}_v\bigg) \Bigg)
	\]
for all $e\in\delta v$.
Substituting into the previous expression, and using 
Proposition~\ref{p:var.update} again, we conclude
	\begin{align*}
	\Bigg|
	\frac{Z_{Q,e}Q_e(\SSPIN{r}\SSPIN{r})}{Z_{P,e}P_e(\SSPIN{r}\SSPIN{r})}-1
	\Bigg|
	&\le k^{O(1)}
	\Bigg(
	\textup{\textsf{err}}_v
	+\bigg\{ \dot{\epsilon}_e
	+\frac{\min\set{\ddot{\epsilon}_e,1}}
		{2^{k\zeta}}
	+\textup{\textsf{err}}_v\bigg\}
	+\sum_{e'\in\delta v}
	\bigg\{ \epsilon_{e'}
	+ \frac1{2^k}
	\bigg( \dot{\epsilon}_{e'}+
	\frac{\min\set{\ddot{\epsilon}_{e'},1}}
	{(2^{k\zeta})_{e'}}
	+ \textup{\textsf{err}}_v\bigg) \bigg\}
	\Bigg) \\
	&\le k^{O(1)}
	\Bigg( \textup{\textsf{err}}_v
	+ \dot{\epsilon}_e
	+\frac{\min\set{\ddot{\epsilon}_e,1}}
		{2^{k\zeta}}
	\Bigg)\,.
	\end{align*}
A similar calculation can be made for the other spins in $\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$, and \eqref{e:reweighted.var.msg.prelim.bd} straightforwardly follows.\smallskip

\noindent\bemph{\hypertarget{c:var.update.BETTER.MGL.BOUND}{Step 2}. Marginal errors between $P$ and $Q$.} Fix an edge $e\in\delta v$. Let $\hat{s}_e=\hat{p}_e$, and $\hat{s}_{e'}=\hat{q}_{e'}$ for $e'\in\delta v\setminus e$. We first apply Proposition~\ref{p:var.update} with $\hat{s}$ in place of $\hat{q}$: let $\Gamma$ be the resulting weights such that 
$\nu_{\delta v}[\Gamma;\hat{s}]$ is judicious, and let $\dot{s}\equiv\textup{\footnotesize\textsf{BP}}[\Gamma;\hat{s}]$ denote the corresponding outgoing messages from the variable, with reweighted versions $S$ as defined by \eqref{e:reweighted.messages.v.to.c}. Then we are exactly in the situation of Lemma~\ref{l:marginal.error}. The reweighting $W$ of $\hat{r}_e=\hat{p}_e$ satisfies
	\[
	\bigg\| W-\frac19\bigg\|_\infty \le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\]
by assumption~\eqref{e:condition.on.hat.messages}. We also note that $P(\sigma) \le O(1)/2^{k\SSPIN{r}[\sigma]}$,
and likewise for $S(\sigma)$. It follows from
\eqref{e:reweighted.var.msg.prelim.bd} that
	\[
	\bigg\| \frac{S}{P}-1\bigg\|_\infty
	\le k^{O(1)} \textup{\textsf{err}}_v\,.
	\]
Combining this with the result of Lemma~\ref{l:marginal.error} gives
the marginal error bound between $S$ and $P$,
	\begin{equation}\label{e:marginal.error.P.to.S}
	\bigg\| \frac{S^j}{P^j}-1\bigg\|_\infty
	\le 
	O(1)
	\bigg\| W-\frac19\bigg\|_\infty
	\bigg\| \frac{S}{P}-1\bigg\|_\infty
	\le
	\frac{k^{O(1)} \textup{\textsf{err}}_v}
	{2^{k\zeta}}
	\end{equation}
for both $j=1,2$. It also follows from 
\eqref{e:reweighted.var.msg.prelim.bd} that
	\begin{equation}\label{e:S.Q.error}
	\bigg|\frac{Q(\sigma)}{S(\sigma)}-1\bigg|
	\le k^{O(1)} \Bigg( 
	\epsilon_e 
	+\frac1{(2^k)^{\Ind{\SSPIN{r}[\sigma]=0}}}
	\bigg\{ \dot{\epsilon}_e
	+ \frac{\min\set{\ddot{\epsilon}_e,1}}{2^{k\zeta}}
	\bigg\}\Bigg)\,,
	\end{equation}
from which we obtain the marginal error bound
	\begin{equation}\label{e:marginal.error.S.to.Q}
	\bigg|\frac{Q^j(\tau)}{S^j(\tau)}-1\bigg|
	\le k^{O(1)}\Bigg( 
	\epsilon_e 
	+\frac1{(2^k)^{\Ind{\tau\ne\SSPIN{r}}}}
	\bigg\{ \dot{\epsilon}_e
	+ \frac{\min\set{\ddot{\epsilon}_e,1}}{2^{k\zeta}}
	\bigg\}\Bigg)\,.
	\end{equation}
The result follows by combining
\eqref{e:reweighted.var.msg.prelim.bd},
\eqref{e:marginal.error.P.to.S}, and \eqref{e:marginal.error.S.to.Q}.

