\label{l:sum.around.clause}
In the setting of Propositions~\ref{p:nice.tree.lagrange}~and~\ref{p:induct}, if $N(a)$ denotes the clauses in $T$ at unit distance from a clause $a$ in $T$, then
we have the bound
	\[
	\sum_{b\in N(a)}
	\xi_b(T;\omega_{\delta T})
	\le O\Bigg( \frac{k^{O(1)} 2^k
		\xi_a(T;\omega_{\delta T})}{(\vartheta_*)^{1/4}}
	\Bigg)\,.
	\]

\begin{proof}
All the variables in $T$ are assumed to be non-defective, hence nice. Let $d_{\max} = O(k 2^k)$ denote the maximum degree of a nice variable
(Definition~\ref{d:nice}). Then, for any edge $e\in\delta T$ and any clause $a$ in $T$, we have
	\begin{align*}
	\bigg|\Big\{
		b\in N(a) : \mathfrak{b}_T(e,b) = \mathfrak{b}_T(e,a)-1
		\Big\}\bigg|
		&\le1\,,\\
	\bigg|\Big\{
	b\in N(a) : \mathfrak{b}_T(e,b) = \mathfrak{b}_T(e,a)
	\Big\}\bigg|
		&\le d_{\max}\,,\\
	\bigg|\Big\{
	b\in N(a) : \mathfrak{b}_T(e,b) = \mathfrak{b}_T(e,a)+1
		\Big\}\bigg|
		&\le k d_{\max}\,.
	\end{align*}
Combining these bounds with the definition \eqref{e:clause.xi} gives
	\[
	\sum_{b\in N(a)}
	\xi_b(T;\omega_{\delta T})
	\le
	\sum_{e\in\delta T}
	\textup{\textsf{disc}}_e(\omega)
	\bigg(\frac{(\vartheta_*)^{1/4}}{2^k}\bigg)^{\mathfrak{b}_T(e,a)}
	\bigg\{
	\frac{2^k}{(\vartheta_*)^{1/4}}
	+ d_{\max}
	+ kd_{\max}
	\cdot \frac{(\vartheta_*)^{1/4}}{2^k}
	\bigg\}
	\le
	O\Bigg(
	\frac{2^k \xi_a(T;\omega_{\delta T})}{(\vartheta_*)^{1/4}}
	\Bigg)\,,
	\]
as claimed.
\end{proof}

