\label{l:first.update.at.boundary}
Recall the notations of Definitions~\ref{d:clause.rel.error}~and~\ref{d:var.rel.error}.
In the setting of
Propositions~\ref{p:nice.tree.lagrange}~and~\ref{p:induct}, 
for any boundary edge $e=(av)\in\delta T$,
suppose that 
we have,
for an absolute constant $0<\zeta\le1/20$, the bounds
	\begin{equation}\label{e:assume.omega.error.gamma}
	\widehat{\textup{\textsf{\footnotesize ERR}}}({}_{*}\omega_e,\omega_e)
	\le \begin{pmatrix} \gamma_e \\ \dot{\gamma}_e\\
		\ddot{\gamma}_e
		\end{pmatrix}
	\le
	k^{O(1)}
	\min\left\{
	\textup{\textsf{disc}}_e(\omega)
	\begin{pmatrix}
	1 \\ (\vartheta_*)^{-1} \\ (\vartheta_*)^{-1}
	\end{pmatrix}
	,
	 \frac{1}{2^{2k\zeta}}
	\begin{pmatrix} 1 \\ 1 \\ 2^k \end{pmatrix}
	\right\}
	\,,
	\end{equation}
where the last bound follows from the definition
\eqref{e:def.discrepancy.measure.e}
together with the assumption
\eqref{e:apriori.assump.omega}
(taking the entrywise minimum of the two vectors). Then, after the first round of boundary updates
(i.e., after applying
Definition~\ref{d:nice.lagrange.defn.weights}
Step~I), we have
	\[
	\dddot{\textup{\textsf{\footnotesize ERR}}}(\dot{q}_{e,0},\dot{q}_{e,1})
	\le k^{O(1)} \begin{pmatrix}
	1 & 2^{-k} & 4^{-k} \\
	1 & 1 & 4^{-k} \\
	1 & 2^{-k} & 1 \\
	2^{-k/10} & 2^{-k/10} 2^{-k} & 2^{-k/10}4^{-k} \\
	2^{-k/10} & 2^{-k/10} & 2^{-k/10} 2^{-k}
	\end{pmatrix}
	\begin{pmatrix} \gamma_e \\ \dot{\gamma}_e\\
		\ddot{\gamma}_e
		\end{pmatrix}
	\le k^{O(1)} \min\left\{
	\textup{\textsf{disc}}_e(\omega)
	\begin{pmatrix}
	1 \\ (\vartheta_*)^{-1} \\ (\vartheta_*)^{-1}\\
	2^{-k/10}(\vartheta_*)^{-1}\\
	2^{-k/10}(\vartheta_*)^{-1}
	\end{pmatrix},
	\frac1{2^{k\zeta}}
	\begin{pmatrix}
	1\\1\\ 2^k \\ 1\\ 1
	\end{pmatrix}
	\right\}\,.
	\]
Moreover, if $Q_{e,1}$ is the reweighted version of
$\dot{q}_{e,1}$ defined by
 \eqref{e:reweighted.messages.v.to.c},
 then it satisfies the bounds 
\eqref{e:first.update.at.boundary}.

\begin{proof}
Recall that $\dot{q}_{e,0}={}_{*}\dot{q}_e={}_\bullet\hspace{-1pt}\dot{q}_e\otimes{}_\bullet\hspace{-1pt}\dot{q}_e$.
From Definition~\ref{d:nice.lagrange.defn.weights},
the first updates (Step~I) yield boundary messages
	\[
	\dot{q}_{e,1}(\sigma)
	\cong \frac{\omega_e(\sigma)}{{}_{*}\hat{q}_e(\sigma)}
	= \frac{\omega_e(\sigma)}
		{{}_\bullet\hspace{-1pt}\hat{q}_e(\sigma^1)
		{}_\bullet\hspace{-1pt}\hat{q}_e(\sigma^2)}
	\,.
	\]
We use \eqref{e:reweighted.messages.v.to.c} to define the reweighted versions
	\[
	Q_{e,1}(\sigma)
	\cong
	\frac1{(2^{|\partial a|-1})^{\SSPIN{r}[\sigma]}}
	\frac{\omega_e(\sigma)}
		{{}_{*}\hat{q}_e(\sigma)}
	\cong
	\frac{\omega_e(\sigma)}{{}_{*}\omega_e(\sigma)}
	\frac{{}_{*}\dot{q}_e(\sigma)}
		{(2^{|\partial a|-1})^{\SSPIN{r}[\sigma]}}
	\cong
	\frac{\omega_e(\sigma)}{{}_{*}\omega_e(\sigma)}
	{}_{*}Q_e(\sigma)\,,
	\]
where the second-to-last step uses that 
${}_{*}\omega_e(\sigma)\cong{}_{*}\dot{q}_e(\sigma){}_{*}\hat{q}_e(\sigma)$, and ${}_{*}Q_e = Q_{e,0}$ is the reweighting of ${}_{*}\dot{q}$ by \eqref{e:reweighted.messages.v.to.c}. Therefore, there exists a normalizing constant $Z_e$ such that
	\[
	Z_e Q_{e,1}(\sigma)
	= \frac{\omega_e(\sigma)}{{}_{*}\omega_e(\sigma)}
	{}_{*}Q_e(\sigma)\,.
	\]
Summing the equation over $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$, and recalling the assumption
\eqref{e:assume.omega.error.gamma}, we find
	\begin{align*}
	Z_e
	&= \sum_{\sigma:\SSPIN{r}[\sigma]=0}
	{}_{*}Q_e(\sigma)
	\Big(1 + O(\gamma_e)\Big)
	+ \sum_{\sigma:\SSPIN{r}[\sigma]=1}
	{}_{*}Q_e(\sigma)
	\Big(1 + O(\dot{\gamma}_e)\Big)
	+{}_{*}Q_e(\SSPIN{r}\SSPIN{r})
	\Big(1 + O(\ddot{\gamma}_e)\Big)\\
	&=
	1 + O\bigg(
	\gamma_e + \frac{\dot{\gamma}_e}{2^k}
	+ \frac{\ddot{\gamma}_e}{4^k}\bigg)\,.
	\end{align*}
Recalling that $Q_{e,0}={}_{*}Q_e$, it follows by combining the above estimates that
	\[\Bigg|
	\frac{Q_{e,1}(\sigma)}{Q_{e,0}(\sigma)}
	-1\Bigg|
	\le 
	k^{O(1)}
	\Bigg(
	\gamma_e + \frac{\dot{\gamma}_e}{2^k}
	+ \frac{\ddot{\gamma}_e}{4^k}
	+ \Ind{\SSPIN{r}[\sigma]=1} \dot{\gamma_e}
	+ \Ind{\SSPIN{r}[\sigma]=2} \ddot{\gamma_e}
	\Bigg)\,.
	\]
Next recall that from the initialization of Definition~\ref{d:nice.lagrange.defn.weights} we have ${}_{*}\omega_e\cong{}_{*}\hat{q}_e{}_{*}\dot{q}_e= \hat{q}_{e,0}\dot{q}_{e,0}$; and
after the first round of boundary updates we have
$\omega_e\cong
\hat{q}_{e,0}\dot{q}_{e,1}$. Both ${}_{*}\omega_e$ and $\omega_e$ have single-copy marginals ${}_\star\hspace{-1pt}\pi_e$, so we are precisely in 
the situation of Lemma~\ref{l:marginal.error}
with $h={}_{*}\hat{q}_e$. Applying Lemma~\ref{l:marginal.error} gives, for both $j=1,2$,
	\[
	\Bigg|
	\frac{(Q_{e,1})^j(\sigma)}
	{(Q_{e,0})^j(\sigma)}
	-1\Bigg|
	\le
	\frac{k^{O(1)}}{2^{k/10}}
	\begin{cases}
	\gamma_e + \dot{\gamma}_e/2^k
		+\ddot{\gamma}_e/4^k
	&\textup{for }\sigma\ne\SSPIN{r}\,,\\
	\gamma_e+\dot{\gamma}_e + \ddot{\gamma}_e/2^k
	&\textup{for }\sigma=\SSPIN{r}\,.\\
	\end{cases}
	\]
This proves the first claimed bound on
$\dddot{\textup{\textsf{\footnotesize ERR}}}(\dot{q}_{e,0},\dot{q}_{e,1})$.
The remaining bounds follow using 
\eqref{e:assume.omega.error.gamma}.
\end{proof}

