		{{}_{*}\hat{q}_e(\sigma)}
	\cong
	\frac{\omega_e(\sigma)}{{}_{*}\omega_e(\sigma)}
	\frac{{}_{*}\dot{q}_e(\sigma)}
		{(2^{|\partial a|-1})^{\SSPIN{r}[\sigma]}}
	\cong
	\frac{\omega_e(\sigma)}{{}_{*}\omega_e(\sigma)}
	{}_{*}Q_e(\sigma)\,,
	\]
where the second-to-last step uses that 
${}_{*}\omega_e(\sigma)\cong{}_{*}\dot{q}_e(\sigma){}_{*}\hat{q}_e(\sigma)$, and ${}_{*}Q_e = Q_{e,0}$ is the reweighting of ${}_{*}\dot{q}$ by \eqref{e:reweighted.messages.v.to.c}. Therefore, there exists a normalizing constant $Z_e$ such that
	\[
	Z_e Q_{e,1}(\sigma)
	= \frac{\omega_e(\sigma)}{{}_{*}\omega_e(\sigma)}
	{}_{*}Q_e(\sigma)\,.
	\]
Summing the equation over $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$, and recalling the assumption
\eqref{e:assume.omega.error.gamma}, we find
	\begin{align*}
	Z_e
	&= \sum_{\sigma:\SSPIN{r}[\sigma]=0}
	{}_{*}Q_e(\sigma)
	\Big(1 + O(\gamma_e)\Big)
	+ \sum_{\sigma:\SSPIN{r}[\sigma]=1}
	{}_{*}Q_e(\sigma)
	\Big(1 + O(\dot{\gamma}_e)\Big)
	+{}_{*}Q_e(\SSPIN{r}\SSPIN{r})
	\Big(1 + O(\ddot{\gamma}_e)\Big)\\
	&=
	1 + O\bigg(
	\gamma_e + \frac{\dot{\gamma}_e}{2^k}
	+ \frac{\ddot{\gamma}_e}{4^k}\bigg)\,.
	\end{align*}
Recalling that $Q_{e,0}={}_{*}Q_e$, it follows by combining the above estimates that
	\[\Bigg|
	\frac{Q_{e,1}(\sigma)}{Q_{e,0}(\sigma)}
	-1\Bigg|
	\le 
	k^{O(1)}
	\Bigg(
	\gamma_e + \frac{\dot{\gamma}_e}{2^k}
	+ \frac{\ddot{\gamma}_e}{4^k}
	+ \Ind{\SSPIN{r}[\sigma]=1} \dot{\gamma_e}
	+ \Ind{\SSPIN{r}[\sigma]=2} \ddot{\gamma_e}
	\Bigg)\,.
	\]
Next recall that from the initialization of Definition~\ref{d:nice.lagrange.defn.weights} we have ${}_{*}\omega_e\cong{}_{*}\hat{q}_e{}_{*}\dot{q}_e= \hat{q}_{e,0}\dot{q}_{e,0}$; and
after the first round of boundary updates we have
$\omega_e\cong
\hat{q}_{e,0}\dot{q}_{e,1}$. Both ${}_{*}\omega_e$ and $\omega_e$ have single-copy marginals ${}_\star\hspace{-1pt}\pi_e$, so we are precisely in 
the situation of Lemma~\ref{l:marginal.error}
with $h={}_{*}\hat{q}_e$. Applying Lemma~\ref{l:marginal.error} gives, for both $j=1,2$,
	\[
	\Bigg|
	\frac{(Q_{e,1})^j(\sigma)}
	{(Q_{e,0})^j(\sigma)}
	-1\Bigg|
	\le
	\frac{k^{O(1)}}{2^{k/10}}
	\begin{cases}
	\gamma_e + \dot{\gamma}_e/2^k
		+\ddot{\gamma}_e/4^k
	&\textup{for }\sigma\ne\SSPIN{r}\,,\\
	\gamma_e+\dot{\gamma}_e + \ddot{\gamma}_e/2^k
	&\textup{for }\sigma=\SSPIN{r}\,.\\
	\end{cases}
	\]
This proves the first claimed bound on
$\dddot{\textup{\textsf{\footnotesize ERR}}}(\dot{q}_{e,0},\dot{q}_{e,1})$.
The remaining bounds follow using 
\eqref{e:assume.omega.error.gamma}.

\label{c:first.clause.update.round}
In the setting of Propositions~\ref{p:nice.tree.lagrange}~and~\ref{p:induct},
after the first update of the clauses just above the boundary variables
(i.e., after applying
Definition~\ref{d:nice.lagrange.defn.weights}
Step~I at each boundary edge,
followed by Step II(a) at each clause incident to a boundary edge), we have
	\[
	\widehat{\textup{\textsf{\footnotesize ERR}}}( \hat{q}_{e',1},\hat{q}_{e',0})
	\le k^{O(1)}
	\begin{pmatrix} 
		2^{-k(1+\zeta)}\\ 
		2^{-k\zeta}\\ 
		2^{-k\zeta}
		\end{pmatrix}
	\]
for every edge $e'\in\delta a \setminus\delta T$ for any clause $a$ incident to $\delta T$.

\begin{proof} 
For all $e\in\delta T$,
the error
$\dddot{\textup{\textsf{\footnotesize ERR}}}(\dot{q}_{e,1},\dot{q}_{e,0})$
is bounded by Lemma~\ref{l:first.update.at.boundary}.
Applying Proposition~\ref{p:clause.update} gives, after applying Step II(a) at the clauses above the boundary variables,
	\[
	\widehat{\textup{\textsf{\footnotesize ERR}}}( \hat{q}_{e',1},\hat{q}_{e',0})
	\le
	k^{O(1)}
	\begin{pmatrix}
	2^{-k(1+\zeta)}
	& 4^{-k} & 2^{-k(1+\zeta)} & 2^{-k} & 2^{-k}\\
	2^{-k} & 2^{-k} & 2^{-k(1+\zeta)}
		& 1 & 2^{-k} \\
	1 & 4^{-k} & 2^{-k(1+\zeta)}
		& 2^{-k} & 2^{-k}
	\end{pmatrix}
	\begin{pmatrix}
	2^{-k\zeta}\\
	2^{-k\zeta}\\
	\min\set{2^{k(1-\zeta)},1} \\
	2^{-k\zeta}\\
	2^{-k\zeta}
	\end{pmatrix}
	\le k^{O(1)}
	\begin{pmatrix}
	2^{-k(1+\zeta)} \\
	2^{-k\zeta}\\2^{-k\zeta}
	\end{pmatrix}
	\]
for the edges $e'$ just above $\delta T$.
This proves the claim.
\end{proof}


For all $e\in\delta T$,
the error
$\dddot{\textup{\textsf{\footnotesize ERR}}}(\dot{q}_{e,1},\dot{q}_{e,0})$
is bounded by Lemma~\ref{l:first.update.at.boundary}.
Applying Proposition~\ref{p:clause.update} gives, after applying Step II(a) at the clauses above the boundary variables,
	\[
	\widehat{\textup{\textsf{\footnotesize ERR}}}( \hat{q}_{e',1},\hat{q}_{e',0})
	\le
	k^{O(1)}
	\begin{pmatrix}
	2^{-k(1+\zeta)}
	& 4^{-k} & 2^{-k(1+\zeta)} & 2^{-k} & 2^{-k}\\
	2^{-k} & 2^{-k} & 2^{-k(1+\zeta)}
		& 1 & 2^{-k} \\
	1 & 4^{-k} & 2^{-k(1+\zeta)}
		& 2^{-k} & 2^{-k}
	\end{pmatrix}
	\begin{pmatrix}
	2^{-k\zeta}\\
	2^{-k\zeta}\\
	\min\set{2^{k(1-\zeta)},1} \\
	2^{-k\zeta}\\
	2^{-k\zeta}
	\end{pmatrix}
	\le k^{O(1)}
	\begin{pmatrix}
	2^{-k(1+\zeta)} \\
	2^{-k\zeta}\\2^{-k\zeta}
	\end{pmatrix}
	\]
for the edges $e'$ just above $\delta T$.
This proves the claim.

We will prove the result by induction. We divide the proof into a few steps, indicated by Arabic numerals below. We use Roman numerals to refer to the steps of Definition~\ref{d:nice.lagrange.defn.weights}.\smallskip

\noindent\bemph{Step 1. Verification of base case.}
By Lemma~\ref{l:first.update.at.boundary},
for any boundary edge $e=(av)\in\delta T$, we have
	\begin{equation}\label{e:initialization.rel.to.eigenvec}
	\bm{\delta}_{va}(1)
	\equiv\begin{pmatrix}
	\delta_{va,1}\\
	\dot{\delta}_{va,1}\\
	\ddot{\delta}_{va,1}\\
	{}^\textup{m}\hspace{-2pt}\delta_{va,1}\\
	{}^\textup{m}\hspace{-2pt}\dot{\delta}_{va,1}\\
	\end{pmatrix}
	\le k^{O(1)}
	\textup{\textsf{disc}}_e(\omega)
	\begin{pmatrix}
	1 \\ (\vartheta_*)^{-1} \\ (\vartheta_*)^{-1}\\
	2^{-k/10}(\vartheta_*)^{-1}\\
	2^{-k/10}(\vartheta_*)^{-1}
	\end{pmatrix}
	\le k^{O(1)} \xi_a
	\begin{pmatrix}
	1 \\ (\vartheta_*)^{-1} \\ (\vartheta_*)^{-1}\\
	(\vartheta_*)^2\\ \vartheta_*
	\end{pmatrix}
	= k^{O(1)} \xi_a \vec{\delta}\,,
	\end{equation}
which verifies the bound 
\eqref{e:induction.variable.error} for $t=1$.\smallskip

\noindent\bemph{Step 2. Bounds for clause updates.}
For any clause $a\ne a_\textup{\textsc{rt}}$ in the tree $T$, for both steps II(a) and III(b), our earlier result Proposition~\ref{p:clause.update} implies the bound
	\[\bm{\epsilon}_{av}(t)\equiv
	\begin{pmatrix}
	\epsilon_{av,t}\\
	\dot{\epsilon}_{av,t}\\
	\ddot{\epsilon}_{av,t}
	\end{pmatrix}
	\le k^{O(1)}
	\begin{pmatrix}
	2^{-k(1+\zeta)}
	& 4^{-k} & 2^{-k(1+\zeta)} & 2^{-k} & 2^{-k}\\
	2^{-k} & 2^{-k} & 2^{-k(1+\zeta)}
		& 1 & 2^{-k} \\
	1 & 4^{-k} & 2^{-k(1+\zeta)}
		& 2^{-k} & 2^{-k}
	\end{pmatrix}
	\sum_{u\in\partial a \setminus v}
	\begin{pmatrix}
		\delta_{ua,t-1}\\
		\dot{\delta}_{ua,t-1}\\
		\min\set{\ddot{\delta}_{ua,t-1},1}\\
		{}^\textup{m}\hspace{-2pt}\delta_{ua,t-1}\\
		{}^\textup{m}\hspace{-2pt}\dot{\delta}_{ua,t-1}
	\end{pmatrix}\,.\]
(On the right-hand side of 
the above, 
for Step~III(b) one can omit the contribution from the parent variable of $a$; but we will not use this fact.) Substituting the inductive hypothesis
\eqref{e:induction.variable.error} gives the simplified bound
	\begin{equation}\label{e:simplified.clause.update.bound}
	\bm{\epsilon}_{av}(t)
	\le k^{O(1)}
	\xi_a (k^{O(1)}(\vartheta_*)^{1/3})^{t-2}
	\underbrace{
	\begin{pmatrix}
	2^{-k(1+\zeta)}
	& 4^{-k} & 2^{-k(1+\zeta)} & 2^{-k} & 2^{-k}\\
	2^{-k} & 2^{-k} & 2^{-k(1+\zeta)}
		& 1 & 2^{-k} \\
	1 & 4^{-k} & 2^{-k(1+\zeta)}
		& 2^{-k} & 2^{-k}
	\end{pmatrix}
	}_{\textup{denote this }\widehat{\textup{\textsf{M}}}}
	\vec{\delta}\,.\end{equation}
At the root clause $a_\textup{\textsc{rt}}$ we make the trivial update
\eqref{e:message.from.top.always.product}, so
$\widehat{\textup{\textsf{\footnotesize ERR}}}(\hat{q}_{a_\textup{\textsc{rt}}v_\textup{\textsc{rt}},t-1},\hat{q}_{a_\textup{\textsc{rt}}v_\textup{\textsc{rt}},t})
=(0,0,0)\in\mathbb{R}^3$.\smallskip

\noindent\bemph{Step 3. Bounds for internal variable updates.}
For any internal variable $v$ in $T$, for both steps II(b) and III(a), applying Corollary~\ref{c:var.update} gives the bound 
	\begin{align*}
	\bm{\delta}_{va}(t)
	\equiv
	\begin{pmatrix}
	\delta_{va,t} \\
	\dot{\delta}_{va,t} \\
	\ddot{\delta}_{va,t} \\
	{}^\textup{m}\hspace{-2pt}\delta_{va,t}\\
	{}^\textup{m}\hspace{-2pt}\dot{\delta}_{va,t}
	\end{pmatrix}
	&\le k^{O(1)}
	\sum_{c\in\partial v\setminus a}
	\begin{pmatrix}
	1\\1\\1\\ 2^{-k\zeta} \\ 2^{-k\zeta}
	\end{pmatrix} 
	\begin{pmatrix}
	1 & 2^{-k} & 2^{-k(1+\zeta)}
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_{cv,t-1}\\
	\dot{\epsilon}_{cv,t-1}\\
	\min\set{\ddot{\epsilon}_{cv,t-1},1}
	\end{pmatrix}\\
	&\qquad+k^{O(1)}
	\begin{pmatrix}
	0&0&0\\
	0&1&2^{-k\zeta}\\
	0&1&2^{-k\zeta}\\
	1&2^{-k}&2^{-k(1+\zeta)}\\
	1&1&2^{-k\zeta}\\
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_{av,t-1}\\
	\dot{\epsilon}_{av,t-1}\\
	\min\set{\ddot{\epsilon}_{av,t-1},1} 
	\end{pmatrix}
	\,.\end{align*}
(On the right-hand side of the above,
for Step~II(b) one only needs the first term that sums over $c\in\partial v\setminus a$. For Step~III(a) one can omit the contribution to the sum from the parent clause of $v$. We will not use this fact.) We will bound the above sum over $c\in\partial v\setminus a$ by the sum over all $c\in N(a)$. Then, substituting the inductive hypothesis
\eqref{e:induction.clause.error}
and combining with Lemma~\ref{l:sum.around.clause} gives the simplified bound
	\begin{align}\nonumber
	\bm{\delta}_{va}(t)
	&\le k^{O(1)}\xi_a
	(k^{O(1)}(\vartheta_*)^{1/3})^t
	\left\{
	\frac{2^k}{(\vartheta_*)^{1/4}}
	\begin{pmatrix}
	1\\1\\1\\ 2^{-k\zeta} \\2^{-k\zeta}
	\end{pmatrix} 
	\begin{pmatrix}
	1 & 2^{-k} & 2^{-k(1+\zeta)}
	\end{pmatrix}
	+\begin{pmatrix}
	0&0&0\\
	0&1&2^{-k\zeta}\\
	0&1&2^{-k\zeta}\\
	1&2^{-k}&2^{-k(1+\zeta)}\\
	1&1&2^{-k\zeta}\\
	\end{pmatrix}
	\right\} \vec{\epsilon}\\
	&\le k^{O(1)} \xi_a
	(k^{O(1)}(\vartheta_*)^{1/3})^t
	\underbrace{
	\frac1{(\vartheta_*)^{1/4}}
	\begin{pmatrix}
	2^k & 1 & 2^{-k\zeta} \\
	2^k & 1 & 2^{-k\zeta} \\
	2^k & 1 & 2^{-k\zeta} \\
	2^{k(1-\zeta)}&2^{-k\zeta}&2^{-2k\zeta} \\
	2^{k(1-\zeta)}& (\vartheta_*)^{1/4} & (\vartheta_*)^{1/4} 2^{-k\zeta}
	\end{pmatrix}
	}_{\textup{denote this $\dot{M}_\textup{int}$}}
	\vec{\epsilon}\,.
	\label{e:simplified.var.update.bound}
	\end{align}\smallskip

\noindent\bemph{Step 4. Bounds for boundary updates.} For each boundary variable $v$ in $T$ with parent clause $a$, in Step~I we have
	\begin{equation}\label{e:simplified.boundary.update.bound}
	\bm{\delta}_{va}(t)
	\le k^{O(1)}
	\begin{pmatrix}
	1 & 2^{-k} & 2^{-k(1+\zeta)}\\
	1 & 1 & 2^{-k(1+\zeta)}\\
	1 & 2^{-k} & 1\\
	1 & 2^{-k} & 2^{-k(1+\zeta)}\\
	1 & 1 & 2^{-k\zeta}
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_{av,t-1}\\
	\dot{\epsilon}_{av,t-1}\\
	\ddot{\epsilon}_{av,t-1}
	\end{pmatrix}
	\le k^{O(1)}\xi_a
	(k^{O(1)}(\vartheta_*)^{1/3})^t
	\underbrace{
	\begin{pmatrix}
	1 & 2^{-k} & 2^{-k(1+\zeta)}\\
	1 & 1 & 2^{-k(1+\zeta)}\\
	1 & 2^{-k} & 1\\
	1 & 2^{-k} & 2^{-k(1+\zeta)}\\
	1 & 1 & 2^{-k\zeta}
	\end{pmatrix}
	}_{\textup{denote this }\dot{\textup{\textsf{M}}}_\textup{bd}}
	\vec{\epsilon}\,,
	\end{equation}
where the last bound again uses the inductive hypothesis \eqref{e:induction.clause.error}.\smallskip

\noindent\bemph{Step 5. Verification of induction.}
For the matrices defined in \eqref{e:simplified.clause.update.bound},
\eqref{e:simplified.var.update.bound}, and \eqref{e:simplified.boundary.update.bound}, we have
	\begin{equation}\label{e:approx.eigenvector.bounds}
	\widehat{\textup{\textsf{M}}}
	\vec{\delta}
	\le k^{O(1)} \vartheta_*\vec{\epsilon}\,,\quad
	\Big(\dot{\textup{\textsf{M}}}_\textup{int}
	+\dot{\textup{\textsf{M}}}_\textup{bd}\Big)
	\vec{\epsilon}
	\le
	\frac{k^{O(1)}}{(\vartheta_*)^{1/4}}
	\begin{pmatrix}
	1\\1\\1\\k^c/2^{k\zeta}\\(\vartheta_*)^{5/4}
	\end{pmatrix}
	+ k^{O(1)}
	\begin{pmatrix}
	2^{-k}\\
	\vartheta_*\\
	(\vartheta_*)^{-1}\\
	2^{-k}\\
	\vartheta_*
	\end{pmatrix}
	\le \frac{k^{O(1)}}{(\vartheta_*)^{1/4}}
	\vec{\delta}\,.
	\end{equation}
Using these inequalities, the bounds
\eqref{e:simplified.clause.update.bound},
\eqref{e:simplified.var.update.bound}, and \eqref{e:simplified.boundary.update.bound}
simplify to 
	\begin{align*}
	\bm{\epsilon}_{av}(t)
	&\le k^{O(1)}\xi_a
	(k^{O(1)}(\vartheta_*)^{1/3})^{t-2}
	\vartheta_*\vec{\epsilon}
	\le k^{O(1)}\xi_a
	(k^{O(1)}(\vartheta_*)^{1/3})^{t+1}
	\vec{\epsilon}
	\,, \\
	\bm{\delta}_{va}(t)
	&\le k^{O(1)}\xi_a 
	(k^{O(1)}(\vartheta_*)^{1/3})^t
	(\vartheta_*)^{-1/4} \vec{\delta}
	\le k^{O(1)}\xi_a 
	(k^{O(1)}(\vartheta_*)^{1/3})^{t-1}
	\vec{\delta}\,.
	\end{align*}
This verifies the inductive hypotheses
\eqref{e:induction.variable.error}~and~\eqref{e:induction.clause.error}.\smallskip

\noindent\bemph{Step 6. Conclusion.} We conclude the proof by briefly addressing some points which we neglected in the above. In Step~2, in order to apply Proposition~\ref{p:clause.update}
we needed to check that the
messages incoming to the clauses
satisfy the estimates
\eqref{e:first.update.at.boundary}.
This can be seen by induction, with the base case given directly by Lemma~\ref{l:first.update.at.boundary}.
Similarly, in Step~3, in order to apply Corollary~\ref{c:var.update}
we needed to check that the messages incoming to the internal variables satisfy the estimates
\eqref{e:condition.on.hat.messages}. This can also be seen by induction, with the base case given directly by Corollary~\ref{c:first.clause.update.round}. This finishes the proof of the proposition.

In this remark we give some explanation for the choice of the vectors
$\vec{\delta}$ and $\vec{\epsilon}$
in Proposition~\ref{p:induct}.
If we take the product of the $3\times 5$ matrix in \eqref{e:simplified.clause.update.bound}
with the $5\times3$ matrix in
\eqref{e:simplified.var.update.bound}, the result can be (entrywise) upper bounded as
	\[
	\hat{\textup{\textsf{M}}}
	\dot{\textup{\textsf{M}}}_\textup{int}
	\le
	k^{O(1)}
	\begin{pmatrix}
	2^{-k\zeta} & (\vartheta_*)^{1/4} 2^{-k} &
		(\vartheta_*)^{1/4} 2^{-k(1+\zeta)}\\
	2^{k(1-\zeta)} & 2^{-k\zeta} & 2^{-k\zeta}\\
	2^k & 1 & 2^{-k\zeta}
	\end{pmatrix}
	\le k^{O(1)}
	\begin{pmatrix}
	2^{-k} \\
	\vartheta_* \\
	(\vartheta_*)^{-1}
	\end{pmatrix}
	\begin{pmatrix}
	2^k\vartheta_* & (\vartheta_*)^{1/4} & (\vartheta_*)^5
	\end{pmatrix}\,.
	\]
For the last bound on the right-hand side,
the vector $\vec{\epsilon}$
from \eqref{e:induction.clause.error} from Proposition~\ref{p:induct} is a right eigenvector with eigenvalue $O(\vartheta_*)$. This explains why
$\vec{\epsilon}$ is a good choice for our purposes (although it is certainly not the unique choice that would give a sufficiently good bound). On the other hand, given $\vec{\epsilon}$, we chose the vector $\vec{\delta}$ to satisfy the bounds
\eqref{e:approx.eigenvector.bounds}
and
\eqref{e:initialization.rel.to.eigenvec}.
(Again, it is certainly not the unique one that suffices for our purposes.)

\label{d:param.weights.Augmented}
Let $U$ be the depth-one tree from Definition~\ref{d:judicious.augmented.alphabet}, rooted at a variable $v$ of (non-compound) total type $\bm{T}$. For an augmented pair coloring $(\smash{\vec{\sigma}},\smash{\vec{\bm{L}}})$ of $U$, we will define weight functions $\Psi\equiv\Psi_U$ parametrized as
	\[
	\Psi(\smash{\vec{\sigma}},\smash{\vec{\bm{L}}})
	=
	\Psi_v(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	\cdot
	\Bigg\{
	\prod_{e\in\delta U}
	\psi_e(\sigma_e,\bm{L}_e)
	\Bigg\}\,,\]
where the root variable weight $\Psi_v$ takes the form
	\begin{equation}\label{e:non.compound.weight.functional.form}
	\Psi_v(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	\equiv
	\underbrace{
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\Bigg\{ \prod_{j=1,2}
	\psi^j(x^j)\Bigg\}
	\Bigg\{
	\prod_{e\in\delta v}
	\prod_{j=1,2}
	(\psi_e)^j((\sigma_e)^j)
	\Bigg\}
	}_{\textup{denote this }
		\psi_v(\smash{\vec{\sigma}}_{\delta v})}
	\Bigg\{
	\prod_{e\in\delta v}
	\underbrace{\Bigg(
	\psi_e(\bm{L}_e)
	\prod_{j=1,2}
	(\psi_e)^j((\sigma_e)^j \,|\,\bm{L}_e)
	\Bigg)}_{
	\textup{denote this }
	\psi_e(\sigma_e,\bm{L}_e)}
	\Bigg\}\,,\end{equation}
--- in the above, $\varphi_v(\smash{\vec{\sigma}}_{\delta v})$ is the indicator of a valid pair coloring $\smash{\vec{\sigma}}_{\delta v}$ (i.e., the pair version of \eqref{e:color.model.variable.factor}),
and $x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$ denotes 
the pair frozen spin corresponding to
$\smash{\vec{\sigma}}_{\delta v}$. If $\Psi$ is any weight on $U$ of the functional form just described, then $\Psi$ is a Lagrangian weight
for the optimization problem from Proposition~\ref{p:block.update.non.compound}, meaning that $\langle \ln\Lambda,\nu\rangle$ is constant over $\nu\in\bm{J}_{\mathscr{D}}(U;\omega_{\delta U})$. Conversely, it is easy to see that any Lagrangian weight can be expressed in this form. Moreover, for our convenience we have chosen weights that are somewhat over-parametrized, since we have 
edge weights $(\psi_e)^j((\sigma_e)^j)$
as well as 
$(\psi_e)^j((\sigma_e)^j\,|\,\bm{L}_e)$.

\begin{equation}\label{e:non.compound.weight.functional.form}
	\Psi_v(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	\equiv
	\underbrace{
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\Bigg\{ \prod_{j=1,2}
	\psi^j(x^j)\Bigg\}
	\Bigg\{
	\prod_{e\in\delta v}
	\prod_{j=1,2}
	(\psi_e)^j((\sigma_e)^j)
	\Bigg\}
	}_{\textup{denote this }
		\psi_v(\smash{\vec{\sigma}}_{\delta v})}
	\Bigg\{
	\prod_{e\in\delta v}
	\underbrace{\Bigg(
	\psi_e(\bm{L}_e)
	\prod_{j=1,2}
	(\psi_e)^j((\sigma_e)^j \,|\,\bm{L}_e)
	\Bigg)}_{
	\textup{denote this }
	\psi_e(\sigma_e,\bm{L}_e)}
	\Bigg\}\,,\end{equation}

\label{d:lagrange.defn.Augmented}
In the setting of Proposition~\ref{p:contraction.for.simple.var},
we again let $U$ be the depth-one tree from Definition~\ref{d:judicious.augmented.alphabet}.
We now define a sequence of weights $\Psi_t$ on $U$
(parametrized as in Definition~\ref{d:param.weights.Augmented} for each $t\ge0$), which will be shown to converge as $t\to\infty$ to the Lagrangian weights $\Psi_\infty\equiv \Psi_{\mathscr{D}}(U;\omega_{\delta U})$ of Proposition~\ref{p:contraction.for.simple.var}. At the same time we will define messages 
$q_t$ which will converge
as $t\to\infty$ to the \textsc{bp} solution
$q\equiv q_\textup{\textsc{bp}}(U;\Psi_\infty)$ for the $\Psi_\infty$-weighted
model on $U$. (On each edge $e$ of $U$, the \textsc{bp} messages $\dot{q}_{e,t}$ and $\hat{q}_{e,t}$
will now be probability measures on tuple $(\sigma,\bm{L})$ where 
$\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$ while $\bm{L}$ ranges over all possible types for the clause incident to $e$.)

To start the construction, let ${}_\star\hspace{-1pt}\Lambda_U$ denote the single-copy weights on $U$ given by Corollary~\ref{c:clause.bp.weights} (and explicitly constructed in Corollary~\ref{c:clause.bp.weights.explicit}) ---
 similarly to \eqref{e:explicit.Lmstar.T}, if $\smash{\vec{\tau}}\equiv\smash{\vec{\tau}}_U$ is a single-copy coloring of $U$, then
	\[
	{}_\star\hspace{-1pt}\Lambda_U(\smash{\vec{\tau}})
	=\overbrace{
	\Bigg\{{}_\star\hspace{-1pt}\lambda_v(x_v)
	\prod_{e\in\delta v} {}_\star\hspace{-1pt}\lambda_e(\tau_e)
	\Bigg\}
	}^{{}_\star\hspace{-1pt}\Lambda_v(\smash{\vec{\tau}}_{\delta v})}
	\Bigg\{
	\prod_{e\in\delta U} {}_\star\hspace{-1pt}\lambda_e(\tau_e)
	\Bigg\}
	\]
where $x_v\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}$ denotes the frozen spin corresponding to $\smash{\vec{\tau}}_{\delta v}$,
and for $e\in\delta U$ we take
${}_\star\hspace{-1pt}\lambda_e={}_\bullet\hspace{-1pt}\dot{q}_e$ as defined by \eqref{e:redistributed.bp.messages}. Next, recalling \eqref{e:pi.DD.first.appearance}, we define ${}_\star\hspace{-1pt}\psi_e(\bm{L})\equiv \pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)$.
We initialize our construction at $t=0$ with 
	\[
	\Psi_0(\smash{\vec{\sigma}},\smash{\vec{\bm{L}}})
	\equiv
	\Bigg\{ \prod_{j=1,2}
	{}_\star\hspace{-1pt}\Lambda_U(\smash{\vec{\sigma}}^j)\Bigg\}
	\Bigg\{ \prod_{e\in\delta v}
	{}_\star\hspace{-1pt}\psi_e(\bm{L}_e)\Bigg\}\,,\]
where $(\smash{\vec{\sigma}},\smash{\vec{\bm{L}}})\equiv(\smash{\vec{\sigma}}_U,\smash{\vec{\bm{L}}}_U)$
denotes an augmented pair coloring of $U$.
This fits the functional form prescribed
in Definition~\ref{d:param.weights.Augmented} above, since we can rewrite
	\begin{align*}
	\Psi_0(\smash{\vec{\sigma}},\smash{\vec{\bm{L}}})
	&=
	\Psi_{v,0}(\smash{\vec{\sigma}}_{\delta v},\bm{L}_{\delta v})
	\cdot\Bigg\{
	\prod_{e\in\delta U} 
	\overbrace{\Bigg(
	\prod_{j=1,2}
	{}_\star\hspace{-1pt}\lambda_e((\sigma_e)^j)
	\Bigg)}^{\psi_{e,0}(\sigma_e,\bm{L}_e)}
	\Bigg\}\,,\\
	\Psi_{v,0}(\smash{\vec{\sigma}}_{\delta v},\bm{L}_{\delta v})
	&=\underbrace{
	\Bigg\{\prod_{j=1,2}
	{}_\star\hspace{-1pt}\Lambda_v((\smash{\vec{\sigma}}_{\delta v})^j)
	\Bigg\}}_{\psi_{v,0}(\smash{\vec{\sigma}}_{\delta v})}
	\Bigg\{
	\prod_{e\in\delta v}
	{}_\star\hspace{-1pt}\psi_e(\bm{L}_e)
	\Bigg\}\,,\end{align*}
which is consistent with
\eqref{e:non.compound.weight.functional.form}
if for all $e\in\delta v$ we take
$\psi_{e,0}(\sigma,\bm{L})
	\equiv{}_\star\hspace{-1pt}\psi_e(\sigma,\bm{L})$, where
	\begin{equation}\label{e:psistar.joint.defn}
	{}_\star\hspace{-1pt}\psi_e(\sigma,\bm{L})
	\equiv{}_\star\hspace{-1pt}\psi_e(\bm{L})
	\Bigg\{\prod_{j=1,2}
		({}_\star\hspace{-1pt}\psi_e)^j(\sigma^j\,|\,\bm{L})
		\Bigg\}
	= {}_\star\hspace{-1pt}\psi_e(\bm{L})
	= \pi(\bm{L}\,|\,\bm{t}_e)\,.\end{equation}
Having defined $\Psi_0$, we let $q_0\equiv q_\textup{\textsc{bp}}(U;\Psi_0)$. 
Recall that $\omega_{\delta U}$ is given, and abbreviate $\Omega\equiv\textup{\textsf{aug}}(\omega)$,
as defined by
\eqref{e:pi.DD.first.appearance}. For $t\ge1$, given $\Psi_{t-1}$ we define updated weights $\Psi_t$ by making the following series of updates, started from the boundary $\delta U$ and working up to the root $v$, then working back down to $\delta U$:
\begin{enumerate}[I.]
\item \bemph{Boundary updates.} For each leaf edge $e=(au)\in \delta U$, we update its weight by setting
	\[
	\psi_{e,t}(\sigma,\bm{L})
	\equiv
	\dot{q}_{e,t}(\sigma,\bm{L})
	\equiv
	\frac{\Omega_e(\sigma,\bm{L})}{\hat{q}_{e,t}(\sigma,\bm{L})}
	\Bigg/
	\Bigg(\sum_{\sigma',\bm{L}'}
	\frac{\Omega_e(\sigma',\bm{L}')}
		{\hat{q}_{e,t}(\sigma',\bm{L}')}
	\Bigg)\,.
	\]


\item \bemph{Upward pass through clauses.}
For each clause $a$ in $U$,
update $\hat{q}_{av,t}\equiv\textup{\footnotesize\textsf{BP}}_{av}[\dot{q}_t]$.

\item \bemph{Root variable update.}
Recall \eqref{e:augmented.model.factors}
that $\varphi_v(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})$
denotes the indicator of a valid augmented pair coloring of $\delta v$. Suppose inductively that the measure 
	\begin{equation}\label{e:var.tuple.measure.augmented}
	\Big(\nu_{\delta v}[\Psi_{v,t-1};\hat{q}_{t-1}]
	\Big)
	(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	\equiv
	\frac1{\bm{\dot{z}}_{v,t-1}}
	\varphi_v(\smash{\vec{\sigma}}_{\delta v};\smash{\vec{\bm{L}}}_{\delta v})
	\Psi_{v,t-1}
	(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	\prod_{e\in\delta v}
	\hat{q}_{e,t-1}(\sigma_e,\bm{L}_e)
	\end{equation}
is fully judicious on $\delta v$. We will show below, in Proposition~\ref{p:ctypes.varupdate}, how to define updated weights $\Psi_{v,t}$ such that
$\nu_{\delta v}[\Psi_{v,t};\hat{q}_t]$
is also fully judicious on $\delta v$.
We then use this to update
$\dot{q}_{va,t}\equiv\textup{\footnotesize\textsf{BP}}_{va}[\hat{q}_t;\Psi_{v,t}]$
for all $a\in\partial v$.

\item \bemph{Downward pass through clauses.}
For each clause $a$ in $U$, update
	\[\hat{q}_{au,t}\equiv
	\textup{\footnotesize\textsf{BP}}_{au} \bigg[\Big( \dot{q}_{va,t-1},
	(\dot{q}_{wa,t})_{w\in\partial a\setminus \set{u,v}}
	\Big)
	\bigg]
	\]
for each child variable $u\in\partial a\setminus v$. 
This completes the definition of $\Psi_t$ and $q_t$.
\end{enumerate}
In summary, by iterating the above steps, we obtain
$(\Psi_t,q_t)$ for all $t\ge0$ on $T$.
The remainder of this subsection
is devoted to analyzing this iteration under the assumptions of Proposition~\ref{p:contraction.for.simple.var}.

\begin{align*}
	\Psi_0(\smash{\vec{\sigma}},\smash{\vec{\bm{L}}})
	&=
	\Psi_{v,0}(\smash{\vec{\sigma}}_{\delta v},\bm{L}_{\delta v})
	\cdot\Bigg\{
	\prod_{e\in\delta U} 
	\overbrace{\Bigg(
	\prod_{j=1,2}
	{}_\star\hspace{-1pt}\lambda_e((\sigma_e)^j)
	\Bigg)}^{\psi_{e,0}(\sigma_e,\bm{L}_e)}
	\Bigg\}\,,\\
	\Psi_{v,0}(\smash{\vec{\sigma}}_{\delta v},\bm{L}_{\delta v})
	&=\underbrace{
	\Bigg\{\prod_{j=1,2}
	{}_\star\hspace{-1pt}\Lambda_v((\smash{\vec{\sigma}}_{\delta v})^j)
	\Bigg\}}_{\psi_{v,0}(\smash{\vec{\sigma}}_{\delta v})}
	\Bigg\{
	\prod_{e\in\delta v}
	{}_\star\hspace{-1pt}\psi_e(\bm{L}_e)
	\Bigg\}\,,\end{align*}

\begin{equation}\label{e:var.tuple.measure.augmented}
	\Big(\nu_{\delta v}[\Psi_{v,t-1};\hat{q}_{t-1}]
	\Big)
	(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	\equiv
	\frac1{\bm{\dot{z}}_{v,t-1}}
	\varphi_v(\smash{\vec{\sigma}}_{\delta v};\smash{\vec{\bm{L}}}_{\delta v})
	\Psi_{v,t-1}
	(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	\prod_{e\in\delta v}
	\hat{q}_{e,t-1}(\sigma_e,\bm{L}_e)
	\end{equation}

\label{p:ctypes.varupdate} Let $v$ be a nice variable with incoming messages $\hat{p}$ (in the augmented pair coloring model). Recalling the notation of Definition~\ref{d:rel.error.notation.w.types},
assume that for all $e\in\delta v$ we have (cf.\ \eqref{e:condition.on.hat.messages})
	\begin{equation}\label{e:condition.on.hat.msg.with.L}
	\widehat{\textup{\textbf{\textsf{ERR}}}}(
		{}_{*}\hat{Q}_e
		,\hat{p}_e)
	\le	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	2^{-k} \\ 1 \\ 2^k
	\end{pmatrix}\,.\end{equation}
Suppose $v$ has weight $\Phi_v$, of the functional form \eqref{e:non.compound.weight.functional.form},
such that the measure $\mu\equiv \nu_{\delta v}[\Phi_v;\hat{p}]$
(defined using the notation of
\eqref{e:var.tuple.measure.augmented})
is fully judicious. For the variable weights that do not depend on the clause types, assume that
(cf.\ \eqref{e:assume.variable.weights.close.to.one})
	\[
	\adjustlimits
	\sum_{j=1,2}
	\sum_{x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}}
	\Big|\phi^j(x)-1\Big|
	\le \frac{k^{O(1)}}{2^{k\zeta}}\,,\quad
	\max_{e\in\delta v}\Bigg\{
	\sum_{j=1,2}
	\Big|(\phi_e)^j(\SSPIN{r})-1\Big|
	\Bigg\}
	\le \frac{ k^{O(1)}}{2^{k\zeta}}
	\,.\]
For the variable weights that do depend on the clause types, assume that 
	\begin{equation}\label{e:bound.edge.weights.cond.on.L}
	\widehat{\textup{\textbf{\textsf{ERR}}}}({}_\star\hspace{-1pt}\psi_e,\phi_e)
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix} 2^{-k} \\ 1 \\ 2^k
	\end{pmatrix}\end{equation}
for ${}_\star\hspace{-1pt}\psi_e$ as defined by
\eqref{e:psistar.joint.defn}. Now suppose we have a new set of messages $\hat{q}_e$,
such that
 \eqref{e:condition.on.hat.msg.with.L}
 also holds with $\hat{q}$ in place of $\hat{p}$, such that
	\begin{equation}\label{e:crelerr.cond.on.L}
	\widehat{\textup{\textbf{\textsf{ERR}}}}(\hat{p}_e,\hat{q}_e)
	\le \begin{pmatrix}
	\epsilon_e\\
	\dot{\epsilon}_e\\
	\ddot{\epsilon}_e
	\end{pmatrix}
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	2^{-k} \\ 1 \\ 2^k
	\end{pmatrix}
	\end{equation}
for each $e\in\delta v$.
Then there exists a new set of weights
$\Psi_v$, also of the functional form \eqref{e:non.compound.weight.functional.form}, such that
$\nu_{\delta v}[\Psi_v;\hat{q}]$ is fully judicious.
In addition, the clause-independent weights in $\Psi_v$ satisfy the bounds
\eqref{e:defn.of.err.v.notation}
from Proposition~\ref{p:var.update}.
The clause-dependent weights in $\Psi_v$ satisfy
	\begin{align}\nonumber
	\max_{\bm{L}}
	\Bigg\{
	\Bigg|\frac{\psi_e(\bm{L})}{\phi_e(\bm{L})}-1\Bigg|
	+
	\adjustlimits\max_{j=1,2}
	\max_{\tau\ne\SSPIN{r}}
	\Bigg|\frac{(\psi_e)^j(\tau\,|\,\bm{L})}
		{(\phi_e)^j(\tau\,|\,\bm{L})}
		-1\Bigg|
	\Bigg\}
	&\le
	\epsilon_e 
	+\frac{\dot{\epsilon}_e}{2^k}
	+\frac{\min\set{\ddot{\epsilon}_e,1}}{2^{k(1+\zeta)}}
	+\frac{\textup{\textsf{err}}_v}{2^{k(1+\zeta)}}\,,\\
	\adjustlimits
	\max_{\bm{L}}
	\max_{j=1,2}
	\Bigg|\frac{(\psi_e)^j(\SSPIN{r}\,|\,\bm{L})}
		{(\phi_e)^j(\SSPIN{r}\,|\,\bm{L})}
		-1\Bigg|
	&\le
	\epsilon_e 
	+\dot{\epsilon}_e
	+\frac{\min\set{\ddot{\epsilon}_e,1}}{2^{k\zeta}}
	+\frac{\textup{\textsf{err}}_v}{2^{k\zeta}}
	\label{e:ctypes.varupdate.MAINBOUND}
	\end{align}
If $\dot{p}_e$ are the original outgoing messages
and $\dot{q}_e$ are the new ones, then
(cf.\ Corollary~\ref{c:var.update})
	\begin{equation}\label{e:ctypes.varupdate.OUTMSG}
	\dddot{\textup{\textbf{\textsf{ERR}}}}(\dot{p}_e,\dot{q}_e)
	\le
	k^{O(1)}
	\begin{pmatrix}
	1\\1\\1\\ 
	2^{-k\zeta} \\
	2^{-k\zeta}
	\end{pmatrix} \textup{\textsf{err}}_v
	+k^{O(1)}
	\begin{pmatrix}
	0&0&0\\
	0&1&1\\
	0&1&1\\
	1&2^{-k}&2^{-k}\\
	1&1&1\\
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e\\
	\dot{\epsilon}_e\\
	\min\set{\ddot{\epsilon}_e,1}/2^{k\zeta}
	\end{pmatrix}\,,
	\end{equation}
again using the notation from Definition~\ref{d:rel.error.notation.w.types}.

\begin{proof}
Since the proof is somewhat involved, we divide it into a few numbered parts. We again recall from
 \eqref{e:augmented.model.factors}
that $\varphi_v(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})$
denotes the indicator of a valid augmented pair coloring of $\delta v$. It can be expressed as
	\[
	\varphi_v(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	= \varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e\in\delta v}
	\Ind{\bm{L}_e\ni \bm{t}_e}\,,
	\]
where $\varphi_v(\smash{\vec{\sigma}}_{\delta v})$ is the indicator of a valid pair coloring on $\delta v$ (not augmented with clause types) as defined in \eqref{e:color.model.variable.factor};
and we write $\bm{L}\ni\bm{t}$ to indicate that $\bm{L}_j=\bm{t}$ for $j=j(\bm{t})$.\smallskip



\noindent
\bemph{\hypertarget{p:ctypes.varupdate.ITERATIVE.CONSTRUCTION}{Part~1}. Iterative construction of $\Psi_v$.}
We first give an iterative definition for a sequence of weights $\Psi_{v,t}$ ($t\ge0$),
all of the functional form \eqref{e:non.compound.weight.functional.form}.
We emphasize that this index $t$ is \bemph{purely local to the proof of this proposition}, and is not the same as the $t$ that indexes the up-and-down passes in
Definition~\ref{d:lagrange.defn.Augmented}. 
We will show in the remainder of the proof that this sequence converges as $t\to\infty$ to the desired weights $\Psi_v=\Psi_{v,\infty}$. Initialize $\Psi_{v,0}\equiv\Phi_v$. For each $t\ge0$, we will update from $\Psi_{v,t}$ to $\Psi_{v,t+1}$ in three stages, summarized by the following table:
	\begin{equation}\label{e:update.table}
	\begin{array}{c|ccc}
	& \psi_v(\smash{\vec{\sigma}}_{\delta v}) 
	& (\psi_e)^j(\sigma^j\,|\,\bm{L})
	& \psi_e(\bm{L}) \\
	\hline
	\Psi_{v,t} & t & t & t \\
	\Psi_{v,t+1/3}	& t+1 & t & t \\
	\Psi_{v,t+2/3}	& t+1 & t+1 & t 
	\end{array}
	\end{equation}
--- e.g., the last row of the table indicates that the weight $\Psi_{v,t+2/3}$ 
is defined by
\eqref{e:non.compound.weight.functional.form}
with the $(t+1)$-versions of 
$\psi_v(\smash{\vec{\sigma}}_{\delta v})$
and $(\psi_e)^j(\sigma^j\,|\,\bm{L})$
(for both $j=1,2$ and all $e\in\delta v$), but with the $t$-version of $\psi_e(\bm{L})$ (again for all $e\in\delta v$). For notational convenience,
we also define $\Psi_t\equiv \Phi$ for all $t<0$, and
	\begin{equation}\label{e:hq.of.t.notation}
	\hat{q}_{e,t}(\sigma,\bm{L})
	\equiv\begin{cases}
	\hat{p}_e(\sigma,\bm{L})
	&\textup{if }t<0\,,\\
	\hat{q}_e(\sigma,\bm{L})
	&\textup{if }t\ge0\,.\\
	\end{cases}
	\end{equation}
We then abbreviate $\nu_t\equiv\nu_{\delta v}[\Psi_{v,t};\hat{q}_t]$, using the notation of \eqref{e:var.tuple.measure.augmented}; in particular this means $\nu_t=\nu_{\delta v}[\Phi;\hat{p}]$ for all $t<0$, while $\nu_0=\nu_{\delta v}[\Phi;\hat{q}]$.
For $t>0$, the weights
of \eqref{e:update.table} are defined by the following procedure (with $t$ denoting an integer time from now on):
\begin{enumerate}[A.]
\item From $t$ to $t+1/3$: 
we will suppose inductively that the measure
$\nu_{t-2/3}$ is judicious on average (in the terminology of Definition~\ref{d:judicious.with.types}).
(For $t=0$, recall that we defined
$\nu_{-2/3}\equiv\nu_{\delta v}[\Phi,\hat{p}]$,
which by hypothesis is fully judicious and therefore also judicious on average.)
 At time $t$ (for $t\ge0$) we have
	\[
	\nu_t(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	= \frac1{\bm{\dot{z}}_{v,t}}
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\psi_{v,t}(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e\in\delta v}
	\Bigg\{
	\Ind{ \bm{L}_e\ni\bm{t}_e }
	\psi_{e,t}(\sigma_e,\bm{L}_e)
	\hat{q}_e(\sigma_e,\bm{L}_e)
	\Bigg\}\,.
	\]
The marginal law of $\smash{\vec{\sigma}}_{\delta v}$ under $\nu_t$ can then be expressed as
	\begin{equation}\label{e:t.avg.no.longer.judicious.on.avg}
	\bar{\nu}_t(\smash{\vec{\sigma}}_{\delta v})
	\cong
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\psi_{v,t}(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e\in\delta v}
	\bar{q}_{e,t}(\sigma_e)\,,
	\end{equation}
where $\bar{q}_{e,t}$ denotes the message at time $t$ averaged over $\bm{L}$:
	\begin{equation}\label{e:defn.avhq.t}
	\bar{q}_{e,t}(\sigma)
	\equiv
	\frac1{\bar{z}_{e,t}}
	\sum_{\bm{L}}
	\Ind{\bm{L}\ni\bm{t}_e}
	\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_{e,t}(\sigma,\bm{L})\,,
	\end{equation}
where $\hat{q}_{e,t}$ is defined by \eqref{e:hq.of.t.notation}. Since we also defined $\psi_{e,t}\equiv\phi_e$ for negative $t$, this means that $\bar{q}_{e,t}(\sigma_e)$ is also well-defined for negative $t$. For instance, the marginal law of $\smash{\vec{\sigma}}_{\delta v}$ at time 
$t-2/3$ is
	\begin{equation}\label{e:t.minus.two.thirds.avg}
	\bar{\nu}_{t-2/3}(\smash{\vec{\sigma}}_{\delta v})
	\cong
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\psi_{v,t}(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e\in\delta v}
	\bar{q}_{e,t-1}(\sigma_e)\,,
	\end{equation}
including in the case $t=0$. Now, from the inductive assumption, $\nu_{t-2/3}$ is judicious on average, which means that the measure
$\bar{\nu}_{t-2/3}$ in
\eqref{e:t.minus.two.thirds.avg}
is judicious in the sense of Definition~\ref{d:constrained.opt.compound.enclosure}.
Comparing \eqref{e:t.avg.no.longer.judicious.on.avg} with \eqref{e:t.minus.two.thirds.avg},
we see that we can
apply Proposition~\ref{p:var.update}
--- with the variable weight function $\psi_{v,t}(\smash{\vec{\sigma}}_{\delta v})$
and the two sets of incoming messages
$\bar{q}_{e,t-1}$ and $\bar{q}_{e,t}$
--- to define a new variable weight function $\psi_{v,t+1}(\smash{\vec{\sigma}}_{\delta v})$ such that the measure
	\[
	\bar{\nu}_{t+1/3}(\smash{\vec{\sigma}}_{\delta v})
	\cong
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\psi_{v,t+1}(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e\in\delta v}
	\bar{q}_{e,t}(\sigma_e)
	\]
is judicious in the sense of Definition~\ref{d:constrained.opt.compound.enclosure},
i.e., such that $\nu_{t+1/3}$ is judicious on average.
Note that, since $t+1/3=(t+1)-2/3$,
this verifies the inductive assumption that
$\nu_{t-2/3}$ is judicious on average.

\item From $t+1/3$ to $t+2/3$:
for all $e\in\delta v$ and both $j=1,2$, update
	\begin{equation}\label{e:cond.judicious.update}
	\frac{(\psi_{e,t+1})^j
		(\tau\,|\,\bm{L})}
		{(\psi_{e,t})^j(
		\tau\,|\,\bm{L})}
	=
	\frac{{}_\star\hspace{-1pt}\pi_e(\tau)}
		{ (\nu_{e,t+1/3})^j(\tau\,|\,\bm{L}) }
	\end{equation}
for all $\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$.

\item From $t+2/3$ to $t+1$: for all $e\in\delta v$ and both $j=1,2$, update 
	\begin{equation}\label{e:clause.frac.update}
	\frac{\psi_{e,t+1}(\bm{L})}{\psi_{e,t}(\bm{L})}
	= \frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
		{ \nu_{e,t+2/3}
		(\bm{L}_e) }\,,
	\end{equation}
using the notation from \eqref{e:pi.DD.first.appearance}.
\end{enumerate}
The rest of the proof is devoted to the analysis of this iterative procedure. For the calculations that follow, it is useful to note that if $\bm{L}\not\ni\bm{t}_e$, then we must have $\psi_{e,t}(\bm{L})=0$ for all $t$. 
\smallskip

\noindent\bemph{\hypertarget{p:ctypes.varupdate.ERROR.NOTATIONS}{Part~2}. Error notations.}
In the proof we will track the following error quantities for all times $t$. Let $\kappa$ measure the deviation from being conditionally judicious:
for $e\in\delta v$, $j=1,2$, 
and $\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$, let
	\begin{equation}\label{e:defn.cdel.kappa}
	(\kappa_{e,t})^j(\tau\,|\,\bm{L})
	\equiv
	\frac{(\nu_{e,t})^j
	( \tau\,|\,\bm{L}) }{{}_\star\hspace{-1pt}\pi_e(\tau)}
	-1\,.\end{equation}
Taking the marginal over $\bm{L}$ gives
	\begin{align*}
	(\nu_{e,t})^j(\tau)
	&= \sum_{\bm{L}}
	\nu_{e,t}(\bm{L})
	\cdot
	(\nu_{e,t})^j
		( \tau\,|\,\bm{L})
	= \sum_{\bm{L}}
	\nu_{e,t}(\bm{L})
	{}_\star\hspace{-1pt}\pi_e(\tau)
	\Bigg\{ 1 + 
	(\kappa_{e,t})^j
		(\tau\,|\,\bm{L})
	\Bigg\}\\
	&=
	{}_\star\hspace{-1pt}\pi_e(\tau)
	\Bigg\{
	1 + 
	\underbrace{\bigg[\sum_{\bm{L}}
	\nu_{e,t}(\bm{L})
	\cdot (\kappa_{e,t})^j(\tau\,|\,\bm{L})
	\bigg]}_{\textup{denote this }
	(\chi_{e,t})^j(\tau)}
	\Bigg\}\,.
	\end{align*}
Notice also that since ${}_\star\hspace{-1pt}\pi_e$
and $(\nu_{e,t})^j(\cdot\,|\,\bm{L})$
are both probability measures over $\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$, we must have
	\begin{equation}\label{e:cdel.avg.to.zero}
	\sum_\tau
	{}_\star\hspace{-1pt}\pi_e(\tau)
	(\kappa_{e,t})^j(\tau\,|\,\bm{L})
	=0
	=\sum_\tau
	{}_\star\hspace{-1pt}\pi_e(\tau)
	(\chi_{e,t})^j(\tau)\,.
	\end{equation}
Next let $\rho$ measure the deviations in the clause proportions: for $e\in\delta v$,
	\begin{equation}\label{e:fdel.defn}
	\rho_{e,t}(\bm{L})
	\equiv
	\frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
	{\nu_{e,t}(\bm{L})}-1\,.\end{equation}
Next, recall the definition \eqref{e:prod.hQ.with.L} of ${}_{*}\hat{Q}_e(\sigma,\bm{L})$, and let
	\begin{equation}\label{e:alpha.e.t.defn}
	\alpha_{e,t}(\sigma,\bm{L})
	\equiv
	\frac{\psi_{e,t}(\sigma,\bm{L})\hat{q}_e(\sigma,\bm{L})}
	{ \psi_{e,0}(\sigma,\bm{L}) {}_{*}\hat{Q}_e(\sigma,\bm{L}) }
	-1
	=\frac{\psi_{e,t}(\sigma,\bm{L})\hat{q}_e(\sigma,\bm{L})}
	{ {}_\star\hspace{-1pt}\psi_e(\bm{L}) {}_{*}\hat{q}_e(\sigma) /\hat{Z}_e}
	-1\,.\end{equation}
Lastly, let $\xi$ measure the deviation from being a product measure: for $e\in\delta v$,
	\[
	\xi_{e,t}(\sigma\,|\,\bm{L})
	\equiv
	\frac{\nu_{e,t}(\sigma\,|\,\bm{L})}
		{{}_{*}\omega_e(\sigma)}-1
	\]
We will also make some shorthand notation for the maximum absolute values of the above quantities: let
	\begin{equation}\label{e:cdel.max.notation}
	\kappa_{e,t}(\tau)
	\equiv
	\max_{\bm{L},j}\Bigg\{
	\Big|(\kappa_{e,t})^j(\tau\,|\,\bm{L})\Big|
	\Bigg\}
	\,,\quad
	\begin{pmatrix}
	\kappa_{e,t}\\
	\dot{\kappa}_{e,t}
	\end{pmatrix}
	\equiv\begin{pmatrix}
	\max\set{\kappa_{e,t}(\tau):\tau\ne\SSPIN{r}}\\
	\kappa_{e,t}(\SSPIN{r})
	\end{pmatrix}\,,\end{equation}
and let $\rho_{e,t}
\equiv \max_{\bm{L}}\set{|\rho_{e,t}(\bm{L})|}$.
Finally let
	\begin{equation}\label{e:he.max.notation}
	\alpha_{e,t}(\sigma)
	\equiv
	\max_{\bm{L}}\Bigg\{
		\Big|\alpha_{e,t}(\sigma\,|\,\bm{L})\Big|
			\Bigg\}
	\,,\quad
	\begin{pmatrix}
	\alpha_{e,t}\\
	\dot{\alpha}_{e,t}\\
	\ddot{\alpha}_{e,t}
	\end{pmatrix}
	=\begin{pmatrix}
	\max\set{\alpha_{e,t}(\sigma) : \SSPIN{r}[\sigma]=0}\\
	\max\set{\alpha_{e,t}(\sigma) : \SSPIN{r}[\sigma]=1}\\
	\max\set{\alpha_{e,t}(\sigma) : \SSPIN{r}[\sigma]=2}
	\end{pmatrix}\,,
	\end{equation}
and make the analogous notation with $\xi$ in place of $\alpha$.
We will show by induction that for all $e\in\delta v$,
	\begin{equation}\label{e:rough.inductive.bounds.forall.t}
	\sum_{t\in\mathbb{Z}/3,t\ge1/3}
	\begin{pmatrix}
	\rho_{e,t}+\kappa_{e,t} + \alpha_{e,t}
		\\
	\dot{\kappa}_{e,t}+\dot{\alpha}_{e,t}
		+\xi_{e,t}
		+ \dot{\xi}_{e,t}\\
	\ddot{\alpha}_{e,t}
		+\ddot{\xi}_{e,t}
	\end{pmatrix}
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix} 2^{-k} \\ 1 
		\\ 2^k \end{pmatrix}\end{equation}
for all $t\ge 1/3$. We also record a calculation that we will use repeatedly in what follows: for any integer $t$, at time $t+1/3$, according to the table \eqref{e:update.table} we have
	\[
	\nu_{t+1/3}(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	\cong
	\varphi_v(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	\psi_{v,t+1}(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e\in\delta v}\Bigg\{
	\psi_{e,t}(\sigma_e,\bm{L}_e)
	\hat{q}_{e,t}(\sigma_e,\bm{L}_e)\Bigg\}\,,
	\]
where we recall that $\hat{q}_{e,t}$ is defined by \eqref{e:hq.of.t.notation} for all $t$.
From this it is straightforward to verify that the marginal on an edge $e\in\delta v$ is given by
\begin{equation}\label{e:first.defn.of.u}
	\nu_{e,t+1/3}(\sigma,\bm{L})
	=\frac1{\bm{\bar{z}}_{e,t+1/3}}
	\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_{e,t}(\sigma,\bm{L})
	\overbrace{\Bigg[
	\frac1{\dot{z}_{e,t+1/3}}
	\sum_{\smash{\vec{\sigma}}_{\delta v\setminus e}}
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\psi_{v,t+1}(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e'}
	\bar{q}_{e,t}(\sigma_{e'})
	\Bigg]}^{\textup{denote this }u_{e,t+1/3}(\sigma)}
	\end{equation}
where $\dot{z}_{e,t+1/3}$ is the normalizing constant that makes $u_{e,t+1/3}$ a probability measure over $\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$, and $\bm{\bar{z}}_{e,t+1/3}$ is the normalizing constant that makes $\nu_{e,t+1/3}$ a probability measure over pairs $(\sigma,\bm{L})$. For integers $t$ we will compare the following measures:
	\begin{align}\nonumber
	\bm{\bar{z}}_{e,t-2/3}\nu_{e,t-2/3}(\sigma,\bm{L})
	&=\hat{q}_{e,t-1}(\sigma,\bm{L})
		\psi_{e,t-1}(\bm{L})
		\psi_{e,t-1}(\sigma\,|\,\bm{L})
		u_{e,t-2/3}(\sigma,\bm{L})\,,\\
	\nonumber
	\bm{\bar{z}}_{e,t-1/3}\nu_{e,t-1/3}(\sigma,\bm{L})
	&=\hat{q}_{e,t-1}(\sigma,\bm{L})
		\psi_{e,t-1}(\bm{L})
		\psi_{e,t}(\sigma\,|\,\bm{L})
		u_{e,t-1/3}(\sigma,\bm{L})\,,\\
	\nonumber
	\bm{\bar{z}}_{e\bullet,t}
		\nu_{e\bullet,t}(\sigma,\bm{L})
	&=\hat{q}_{e,t}(\sigma,\bm{L})
		\psi_{e,t}(\bm{L})
		\psi_{e,t}(\sigma\,|\,\bm{L})
		u_{e,t-2/3}(\sigma,\bm{L})\,,\\
	\nonumber
	\bm{\bar{z}}_{e,t}\nu_{e,t}(\sigma,\bm{L})
	&=\hat{q}_{e,t}(\sigma,\bm{L})
		\psi_{e,t}(\bm{L})
		\psi_{e,t}(\sigma\,|\,\bm{L})
		u_{e,t}(\sigma,\bm{L})\,,\\
	\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\sigma,\bm{L})
	&=\hat{q}_{e,t}(\sigma,\bm{L})
		\psi_{e,t}(\bm{L})
		\psi_{e,t}(\sigma\,|\,\bm{L})
		u_{e,t+1/3}(\sigma,\bm{L})\,.
	\label{e:table.of.all.measures}
	\end{align}
The remaining parts of the proof are organized as follows:
\begin{enumerate}[--]
\item
\hyperlink{p:ctypes.varupdate.PRELIM.BOUNDS}{Part~3a}
proves some preliminary bounds.

\item 
\hyperlink{p:ctypes.varupdate.UPDATE.A.GENERAL}{Part~3b} controls $\nu_{e,t+1/3}$ 
in terms of $\nu_{e\bullet,t}$ 
for integers $t\ge0$, in the bounds \eqref{e:fdel.bounds.from.update.A}~and~\eqref{e:cdel.bounds.from.update.A}.
The bounds also depend on the error $\vec{\epsilon}(t)$ (see \eqref{e:update.A.def.epsilon})
between
$\bar{q}_{e,t-2/3}$ and $\bar{q}_{e,t}$.

\item
\hyperlink{p:ctypes.varupdate.UPDATE.B.MSG}{Part~4a} 
controls 
 $\bar{q}_{e,t-1/3}$ in terms of
 $\nu_{e,t-2/3}$ and $\bar{q}_{e,t-2/3}$,
in the bound \eqref{e:ctypes.one.two.crelerr}.

\item
\hyperlink{p:ctypes.varupdate.UPDATE.C.MSG}{Part~4b} controls
$\bar{q}_{e,t}$ in terms of
$\nu_{e,t-1/3}$ and $\bar{q}_{e,t-1/3}$,
in the bound \eqref{e:error.in.avhq.from.update.C}.
\item \hyperlink{p:ctypes.varupdate.UPDATE.B.MGL}{Part~5a} controls
	$\nu_{e,t-1/3}$
	in terms of $\nu_{e,t-2/3}$
	 for integers $t\ge1$
	 (in the bounds \eqref{e:one.to.two.thirds.clause}
and \eqref{e:ctypes.one.two.cond}).
\item \hyperlink{p:ctypes.varupdate.UPDATE.C.MGL}{Part~5b} compares
	$\nu_{e,t-1/3}$
	with $\nu_{e\bullet,t}$
	and $\nu_{e,t}$ for integers $t\ge1$
	(in the bounds \eqref{e:update.C.single.edge}
and \eqref{e:update.C.single.edge.back.to.bullet}).

\item 
\hyperlink{p:ctypes.varupdate.CONCLUSION}{Part~6} 
combines the results of the preceding parts to show that the iteration of Part~1 converges to the desired weights $\Psi_v\equiv\Psi_{v,\infty}$, and moreover that these weights satisfy the claimed bounds
\eqref{e:defn.of.err.v.notation}~and~\eqref{e:ctypes.varupdate.MAINBOUND}.

\item \hyperlink{p:ctypes.varupdate.OUTMSG}{Part~7}
shows that the messages outgoing from the variable
satisfy the claimed bound
\eqref{e:ctypes.varupdate.OUTMSG}, thereby concluding the proof.


\end{enumerate}\smallskip


\noindent\bemph{\hypertarget{p:ctypes.varupdate.PRELIM.BOUNDS}{Part~3a}. Preliminary bounds.} Recall the definition \eqref{e:alpha.e.t.defn}
of $\alpha_{e,t}$, and observe that
$\alpha_{e,1/3}=\alpha_{e,0}$. It follows from the assumptions 
\eqref{e:condition.on.hat.msg.with.L} and
\eqref{e:bound.edge.weights.cond.on.L} that
	\[
	\Big|\alpha_{e,1/3}(\sigma,\bm{L})\Big|
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{cases}
	2^{-k} & \textup{if $\SSPIN{r}[\sigma]=0$,}\\
	1 & \textup{if $\SSPIN{r}[\sigma]=1$,}\\
	2^k & \textup{if $\SSPIN{r}[\sigma]=2$,}\\
	\end{cases}\]
which verifies that 
$\alpha_{e,1/3}(\sigma)$
 satisfies the bound from \eqref{e:rough.inductive.bounds.forall.t}.
The marginal on $\bm{L}$ at time $t=1/3$ satisfies
	\begin{align}\nonumber
	\nu_{e,1/3}(\bm{L})
	&\stackrel{\eqref{e:first.defn.of.u}}{=}
	\frac1{\bm{\bar{z}}_{e,1/3}} \sum_\sigma
		\phi_e(\sigma,\bm{L})
		\hat{q}_e(\sigma,\bm{L})
		u_{e,1/3}(\sigma)
	\\
	&\stackrel{\eqref{e:alpha.e.t.defn}}{=}
	\frac{{}_\star\hspace{-1pt}\psi_e(\bm{L})}{\bm{\bar{z}}_{e,1/3}
		\hat{Z}_e}
	\sum_\sigma
	{}_{*}\hat{q}_e(\sigma)
	\Bigg(1+\alpha_e(\sigma,\bm{L})\Bigg)
	u_{e,1/3}(\sigma)
	= {}_\star\hspace{-1pt}\psi_e(\bm{L})
	\Bigg\{ 1 + \frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\}\,,
	\label{e:prod.of.zs.is.close.to.one}
	\end{align}
which proves that $\rho_{e,1/3}$
also satisfies the bound
from \eqref{e:rough.inductive.bounds.forall.t}.
Next, the marginal on $\sigma$ at time $t=1/3$ is given by
	\begin{equation}\label{e:one.third.on.sigma}
	\nu_{e,1/3}(\sigma)
	= \frac{\bar{z}_{e,1/3}}{\bm{\bar{z}}_{e,1/3}}
	\overbrace{\Bigg[
	\frac1{\bar{z}_{e,1/3}}
	\sum_{\bm{L}}
	\Ind{\bm{L}\ni\bm{t}_e}
	\phi_e(\sigma,\bm{L})\hat{q}_e(\sigma,\bm{L})
	\Bigg]}^{\bar{q}_{e,0}(\sigma)
		=\bar{q}_{e,1/3}(\sigma)}
	u_{e,1/3}(\sigma)\,,
	\end{equation}
where we recall that $\bar{q}_{e,t}$ is defined by
 \eqref{e:defn.avhq.t}. It follows from 
the assumptions \eqref{e:condition.on.hat.msg.with.L} and \eqref{e:bound.edge.weights.cond.on.L}
that
	\begin{equation}\label{e:avhq.rel.err.rough.bound.BASECASE}
	\widehat{\textup{\textsf{\footnotesize ERR}}}({}_{*}\hat{q}_e,\bar{q}_{e,1/3})
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix} 2^{-k} \\ 1 \\ 2^k
		\end{pmatrix}\,.
	\end{equation}
Substituting
\eqref{e:avhq.rel.err.rough.bound.BASECASE}
into \eqref{e:one.third.on.sigma}
shows that $\nu_{e,1/3}(\sigma)$
is very close to the 
normalization of the 
measure
${}_{*}\hat{q}_e(\sigma) u_{e,1/3}(\sigma)$.
On the other hand, the same must be true for the conditional measure $\nu_{e,1/3}(\sigma\,|\,\bm{L})$, since
	\begin{align*}
	\nu_{e,1/3}(\sigma\,|\,\bm{L})
	&\stackrel{\eqref{e:first.defn.of.u}}{=}
	\frac{
	\phi_e(\sigma,\bm{L})\hat{q}_e(\sigma,\bm{L}) u_{e,1/3}(\sigma) }
	{ \bm{\bar{z}}_{e,1/3}\nu_{e,1/3}(\bm{L})}
	\stackrel{\eqref{e:alpha.e.t.defn}}{=}
	\frac{{}_\star\hspace{-1pt}\psi_e(\bm{L})
	{}_{*}\hat{q}_e(\sigma)
	u_{e,1/3}(\sigma)}{ \bm{\bar{z}}_{e,1/3} \hat{Z}_e
	\nu_{e,1/3}(\bm{L})}
	\Bigg\{ 1 + \alpha_e(\sigma,\bm{L})\Bigg\}\\
	&\stackrel{\eqref{e:prod.of.zs.is.close.to.one}}
		{=}
	{}_\star\hspace{-1pt}\psi_e(\bm{L})
	{}_{*}\hat{q}_e(\sigma)
	u_{e,1/3}(\sigma)
	\Bigg\{ 1 + \alpha_e(\sigma,\bm{L})\Bigg\}
	\Bigg\{ 1 + \frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\}\,.
	\end{align*}
Thus, by comparing both $\nu_{e,1/3}(\sigma)$
and $\nu_{e,1/3}(\sigma\,|\,\bm{L})$
with the normalization of
${}_{*}\hat{q}_e(\sigma)u_{e,1/3}(\sigma)$, we deduce that
	\begin{equation}\label{e:conditional.vs.avg.error.BASECASE}
	\Bigg|
	\frac{\nu_{e,1/3}(\sigma\,|\,\bm{L})}
		{\nu_{e,1/3}(\sigma)}-1\Bigg|
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\begin{cases}
	2^{-k} & \textup{if $\SSPIN{r}[\sigma]=0$,}\\
	1 & \textup{if $\SSPIN{r}[\sigma]=1$,}\\
	2^k & \textup{if $\SSPIN{r}[\sigma]=2$.}\\
	\end{cases}\end{equation}
Since the measure
$\nu_{e,1/3}$ is judicious by construction, 
this implies that $\kappa_{e,1/3}(\tau)$
satisfies the bounds from \eqref{e:rough.inductive.bounds.forall.t}. 
Finally, we note that the variable \textsc{bp} recursion
together with \eqref{e:avhq.rel.err.rough.bound.BASECASE} implies
	\[\Bigg|
	\frac{u_{e,1/3}(\sigma)}
		{{}_{*}\dot{q}_e(\sigma)}-1\Bigg|
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\]
for all $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$. Combining this with \eqref{e:condition.on.hat.msg.with.L}
and \eqref{e:bound.edge.weights.cond.on.L} gives
	\[
	\Bigg|
	\frac{\nu_{e,1/3}(\sigma\,|\,\bm{L})}
		{{}_{*}\omega_e(\sigma)
		}-1\Bigg|\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\times
	\begin{cases}
	1& \textup{if $\SSPIN{r}[\sigma]\le1$,}\\
	2^k & \textup{if $\SSPIN{r}[\sigma]=2$.}\\
	\end{cases}
	\]
This implies that $\xi_{e,1/3}(\sigma)$ satisfy the bounds from \eqref{e:rough.inductive.bounds.forall.t}.
Thus we have proved \eqref{e:rough.inductive.bounds.forall.t}
for the case $t=1/3$. We note for later use that
the inductive hypothesis \eqref{e:rough.inductive.bounds.forall.t} 
implies that \eqref{e:avhq.rel.err.rough.bound.BASECASE} and \eqref{e:conditional.vs.avg.error.BASECASE}
hold more generally:
	\begin{equation}\label{e:avhq.rel.err.rough.bound}
	\widehat{\textup{\textsf{\footnotesize ERR}}}({}_{*}\hat{q}_e,\bar{q}_{e,t})
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix} 2^{-k} \\ 1 \\ 2^k
		\end{pmatrix}
	\end{equation}
for all $t\ge1/3$, and likewise
	\begin{equation}\label{e:conditional.vs.avg.error}
	\Bigg|
	\frac{\nu_{e,t}(\sigma\,|\,\bm{L})}
		{\nu_{e,t}(\sigma)}-1\Bigg|
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\begin{cases}
	2^{-k} & \textup{if $\SSPIN{r}[\sigma]=0$,}\\
	1 & \textup{if $\SSPIN{r}[\sigma]=1$,}\\
	2^k & \textup{if $\SSPIN{r}[\sigma]=2$}\\
	\end{cases}\end{equation}
for all $t\ge1/3$.\smallskip 

\noindent\bemph{\hypertarget{p:ctypes.varupdate.UPDATE.A.GENERAL}{Part~3b}. Analysis of general applications of update A.} We next analyze the update from $t-2/3$ to $t+1/3$ for integer times $t\ge0$. 
At times $t-2/3$ and $t+1/3$ we have
(cf.\ \eqref{e:first.defn.of.u},
and using the notation from \eqref{e:hq.of.t.notation})
	\begin{align}\nonumber
	\bm{\bar{z}}_{e,t-2/3}
	\nu_{e,t-2/3}(\sigma,\bm{L})
	&= 
	\psi_{e,t-1}(\sigma,\bm{L})
	\hat{q}_{e,t-1}(\sigma,\bm{L})
	\overbrace{\Bigg[
	\frac1{\dot{z}_{e,t-2/3}}
	\sum_{\smash{\vec{\sigma}}_{\delta v\setminus e}}
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\psi_{v,t}(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e'\in\delta v\setminus e}
	\bar{q}_{e',t-1}(\sigma_{e'})
	\Bigg]}^{u_{e,t-2/3}(\sigma) }\,,\\
	\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\sigma,\bm{L})
	&= 
	\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_{e,t}(\sigma,\bm{L})
	\underbrace{\Bigg[
	\frac1{\dot{z}_{e,t+1/3}}
	\sum_{\smash{\vec{\sigma}}_{\delta v\setminus e}}
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\psi_{v,t+1}(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e'\in\delta v\setminus e}
	\bar{q}_{e',t}(\sigma_{e'})
	\Bigg]}_{u_{e,t+1/3}(\sigma) }\,.
	\label{e:compare.tplusthird.to.tminustwothirds}
	\end{align}
We then estimate the error between $u_{e,t-2/3}$ and $u_{e,t+1/3}$. Recall the notation of Definition~\ref{d:clause.rel.error}, and let 
	\begin{equation}\label{e:update.A.def.epsilon}
	\vec{\epsilon}(t)
	\equiv\begin{pmatrix}
	\epsilon_e(t)\\
	\dot{\epsilon}_e(t)\\
	\ddot{\epsilon}_e(t)
	\end{pmatrix}
	\equiv
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\bar{q}_{t-2/3},
	\bar{q}_{t-1/3})
	+\widehat{\textup{\textsf{\footnotesize ERR}}}(\bar{q}_{t-1/3},
	\bar{q}_{t})\,.\end{equation}
(Note that $\bar{q}_t=\bar{q}_{t+1/3}$.)
Recall also the notation of Definition~\ref{d:var.rel.error}, and let
	\begin{equation}\label{e:delta.vec.of.t}
	\vec{\delta}(t+1/3)
	\equiv
	\begin{pmatrix}
	\delta_e(t)\\
	\dot{\delta}_e(t+1/3)\\
	\ddot{\delta}_e(t+1/3)\\
	{}^\textup{m}\hspace{-2pt}\delta_e(t+1/3)\\
	{}^\textup{m}\hspace{-2pt}\dot{\delta}_e(t+1/3)
	\end{pmatrix}
	\equiv\dddot{\textup{\textsf{\footnotesize ERR}}}(
	u_{e,t-2/3},
	u_{e,t+1/3})\,.
	\end{equation}
The measure $\nu_{e,t-2/3}$ is judicious on average for all $t\ge0$ (and fully judicious for $t=0$).
It then follows by Corollary~\ref{c:var.update} (whose conditions are satisfied, in view of 
\eqref{e:avhq.rel.err.rough.bound}) that
	\begin{equation}\label{e:vec.delta.bound.with.L}
	\vec{\delta}(t+1/3)
	\le
	k^{O(1)}
	\begin{pmatrix}
	1\\1\\1\\ 2^{-k\zeta} \\2^{-k\zeta}
	\end{pmatrix} \textup{\textsf{err}}_v(t)
	+ k^{O(1)}
	\begin{pmatrix}
	0&0&0\\
	0&1&1\\
	0&1&1\\
	1&2^{-k}&2^{-k}\\
	1&1&1\\
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e(t)\\
	\dot{\epsilon}_e(t)\\
	\min\set{\ddot{\epsilon}_e(t),1}/2^{k\zeta}
	\end{pmatrix}\,,
	\end{equation}
with $\textup{\textsf{err}}_v(t)$ defined analogously to \eqref{e:defn.of.err.v.notation}. Now,
recalling \eqref{e:compare.tplusthird.to.tminustwothirds}, we will consider also an intermediate measure $\nu_{e\bullet,t}$, which we define by
	\begin{equation}\label{e:intermediate.bullet.measure}
	\nu_{e\bullet,t}(\sigma,\bm{L})
	=\frac1{\bm{\bar{z}}_{e\bullet,t}}
		\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_{e,t}(\sigma,\bm{L})
	 u_{e,t-2/3}(\sigma)\,.\end{equation}
Let $\chi_{e\bullet,t}$,
$\kappa_{e\bullet,t}$, etc.\
be defined analogously to the quantities in 
\hyperlink{p:ctypes.varupdate.ERROR.NOTATIONS}{Part~2}
with $\nu_{e\bullet,t}$
in place of $\nu_{e,t}$. 
In this part of the proof we shall abbreviate
(recalling \eqref{e:cdel.max.notation} and \eqref{e:he.max.notation})
	\begin{equation}\label{e:max.time.t.notation}
	\begin{pmatrix}
	\kappa_{e\bullet}(\tau)\\
	\alpha_{e\bullet}(\sigma)
	\end{pmatrix}
	\equiv\begin{pmatrix}
	\max_{\bm{L},j}\set{|(
		\kappa_{e\bullet,t}
		)^j(\tau\,|\,\bm{L})|}\\
	\max_{\bm{L}}\set{|
		\alpha_{e\bullet,t}
		(\sigma\,|\,\bm{L})|}
	\end{pmatrix}\,,
	\end{equation}
Comparing with $\nu_{e,t+1/3}$ gives
	\begin{equation}\label{e:Upsilon.t.in.terms.of.u}
	\gamma_{e,t}(\sigma)
	\equiv
	\frac{\nu_{e,t+1/3}(\sigma,\bm{L})}
	{\nu_{e\bullet,t}(\sigma,\bm{L})} -1
	= 
	\frac{ \bm{\bar{z}}_{e\bullet,t}}{\bm{\bar{z}}_{e,t+1/3}}
	\cdot
	\frac{ u_{e,t+1/3}(\sigma)}
	{ u_{e,t-2/3}(\sigma)} - 1\,,
	\end{equation}
where we emphasize that this error does not depend on $\bm{L}$. As a result, marginally on $\sigma$ we also have
	\begin{equation}\label{e:marginal.relation.for.gamma}
	\gamma_{e,t}(\sigma)
	=
	\frac{\nu_{e,t+1/3}(\sigma)}
	{\nu_{e\bullet,t}(\sigma)} -1\,.\end{equation}
Substituting \eqref{e:vec.delta.bound.with.L} into the expression \eqref{e:Upsilon.t.in.terms.of.u} for $\gamma_{e,t}$ gives
	\begin{equation}\label{e:bound.Upsilon.in.terms.of.eps}
	\Big|\gamma_{e,t}(\sigma)\Big|
	\le 
	k^{O(1)}\Bigg\{
	\textup{\textsf{err}}_v(t)
	+ \Ind{\SSPIN{r}[\sigma]\ge1}\Bigg(
	\dot{\epsilon}_e(t)
	+\frac{\min\set{\ddot{\epsilon}_e(t),1}}
		{2^{k\zeta}}
	\Bigg)
	\Bigg\}\,.
	\end{equation}
We then compare the marginal laws of $(\sigma^1,\bm{L})$ 
under $\nu_{e\bullet,t}$ and $\nu_{e,t+1/3}$:
by the definition of $\gamma_{e,t}$, we have
	\begin{align}\nonumber
	&\nu_{e,t+1/3}(\sigma^1,\bm{L})
	-\nu_{e\bullet,t}(\sigma^1,\bm{L})
	=
	\sum_{\sigma^2}
	\nu_{e\bullet,t}(\sigma,\bm{L})
	\gamma_{e,t}(\sigma)\\
	&=
	\nu_{e\bullet,t}(\bm{L})
	{}_\star\hspace{-1pt}\pi_e(\sigma^1)
	\Bigg\{
	\underbrace{
	\Bigg[
	\sum_{\sigma^2}
	\frac{\nu_{e\bullet,t}(\sigma)}
		{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	\gamma_{e,t}(\sigma)
	\Bigg]
	}_{\textup{denote this }
	(X_{e,t})^1(\sigma^1)}
	+
	\underbrace{\Bigg[
	\sum_{\sigma^2}
	\frac{\nu_{e\bullet,t}(\sigma\,|\,\bm{L})
	-\nu_{e\bullet,t}(\sigma)}{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	\gamma_{e,t}(\sigma)
	\Bigg]}_{\textup{denote this }
		(Y_{e,t})^1
		(\sigma^1\,|\,\bm{L} )}
	\Bigg\}\,.
	\label{e:zero.to.one.third.errors}
	\end{align}
We note that the $X$ term
in \eqref{e:zero.to.one.third.errors} can be simplified
using \eqref{e:marginal.relation.for.gamma}
and the fact that $\nu_{e,t+1/3}$ is judicious on average:
	\[
	(X_{e,t})^1(\sigma^1)
	=\sum_{\sigma^2}	
	\frac{
	\nu_{e,t+1/3}(\sigma)
	-\nu_{e\bullet,t}(\sigma)
	}{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	= 1 -
	\frac{(\nu_{e\bullet,t})^1(\sigma^1)
	}{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	=- (\chi_{e\bullet,t})^1(\sigma^1)\,.
	\]
It follows from the definition of $\chi$ that for all $\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$ we have
	\[
	\Big|
	(X_{e,t})^1(\tau)\Big|
	= \Big|
	(\chi_{e\bullet,t})^1(\tau)
	\Big|
	\le
	\max_{\bm{L}}
	\Bigg\{\Big|
	(\kappa_{e\bullet,t})^1(\tau\,|\,\bm{L})
	\Big|\Bigg\}
	=\kappa_{e\bullet}(\tau)\,.
	\]
Summing \eqref{e:zero.to.one.third.errors} over $\sigma^1=\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$
and recalling \eqref{e:cdel.avg.to.zero} gives
	\begin{equation}\label{e:zero.to.one.third.errors.mgl.on.L}
	\nu_{e,t+1/3}(\bm{L})
	-\nu_{e\bullet,t}(\bm{L})
	= \nu_{e\bullet,t}(\bm{L})
	\Bigg\{\sum_{\tau}
	{}_\star\hspace{-1pt}\pi_e(\tau)
	(Y_{e,t})^1(\tau\,|\,\bm{L} )
	\Bigg\}\,.
	\end{equation}
Now, the $Y$ term in \eqref{e:zero.to.one.third.errors} can be bounded as 
	\[\Big|(Y_{e,t})^1
		(\sigma^1\,|\,\bm{L})\Big|
	\le \sum_{\sigma^2}
	\frac{\nu_{e\bullet,t}(\sigma)}{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	\Bigg|
	\frac{\nu_{e\bullet,t}(\sigma\,|\,\bm{L})}
	{\nu_{e\bullet,t}(\sigma)}-1
	\Bigg|
	\gamma_{e,t}(\sigma)\,.\]
It follows from \eqref{e:conditional.vs.avg.error} and \eqref{e:bound.Upsilon.in.terms.of.eps} that 
if $\sigma^1\ne\SSPIN{r}$,
	\[
	\Big|(Y_{e,t})^1
		(\sigma^1\,|\,\bm{L})\Big|
	\le
	\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\bigg(\gamma_{e,t}+\dot{\gamma}_{e,t}
		\bigg)
	\le
	\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\{
	\textup{\textsf{err}}_v(t) + \dot{\epsilon}_e(t)
		+ \frac{\min\set{\dot{\epsilon}_e(t),1}}
			{2^{k\zeta}}
	\Bigg\}\,.
	\]
If $\sigma^1=\SSPIN{r}$ then we recall from
\eqref{e:table.of.all.measures}
 that $\nu_{e\bullet,t}\cong
 \hat{q}_{e,t} \psi_{e,t} u_{e\bullet,t}$,
 from which it follows that
 $\nu_{e\bullet,t}(\SSPIN{r}\SSPIN{r}\,|\,\bm{L}) \le 
 k^{O(1)}/2^{-(1+\zeta)}$. 
It then follows that
	\begin{align*}
	\Big|(Y_{e,t})^1
		(\sigma^1\,|\,\bm{L})\Big|
	&\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\dot{\gamma}_{e,t}
	+O\Bigg(
	\frac{\max_{\bm{L}}\set{
	\nu_{e\bullet,t}(\SSPIN{r}\SSPIN{r}\,|\,\bm{L})}}
	{{}_\star\hspace{-1pt}\pi_e(\SSPIN{r})}
	\ddot{\gamma}_{e,t}
	\Bigg)
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\bigg(
	\dot{\gamma}_{e,t}
	+\ddot{\gamma}_{e,t}\bigg)
	\\
	&\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	\textup{\textsf{err}}_v(t) + \dot{\epsilon}_e(t)
		+ \frac{\min\set{\dot{\epsilon}_e(t),1}}
			{2^{k\zeta}}
	\Bigg\}
	\end{align*}
Substituting these bounds for $Y$ back into
\eqref{e:zero.to.one.third.errors.mgl.on.L} gives, for $t\ge1$, 
	\begin{equation}\label{e:fdel.bounds.from.update.A}
	\rho_{e,t+1/3}
	= \max_{\bm{L}}\Bigg\{ \Big|
	\rho_{e,t+1/3}(\bm{L})\Big|\Bigg\}
	\le 
	\rho_{e\bullet,t}
	+\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\{
	\textup{\textsf{err}}_v(t) + \dot{\epsilon}_e(t)
		+ \frac{\min\set{\dot{\epsilon}_e(t),1}}
			{2^{k\zeta}}
	\Bigg\}\,.
	\end{equation}
Substituting the bounds for $X$ and $Y$ back into \eqref{e:zero.to.one.third.errors},
and combining with \eqref{e:zero.to.one.third.errors.mgl.on.L}, gives
	\begin{align}
	\nonumber
	\kappa_{e,t+1/3}
	&\le 
	\rho_{e\bullet,t}
	+\kappa_{e\bullet,t}
	+\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\{
	 \textup{\textsf{err}}_v(t)+\dot{\epsilon}_e(t)
	+\frac{\min\set{\ddot{\epsilon}_e(t),1}}
		{2^{k\zeta}}
	\Bigg\}\,,\\
	\dot{\kappa}_{e,t+1/3}
	&\le
	\rho_{e\bullet,t}
	+\dot{\kappa}_{e\bullet,t}+
	\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	 \textup{\textsf{err}}_v(t)
	+\dot{\epsilon}_e(t)
	+\frac{\min\set{\ddot{\epsilon}_e(t),1}}
		{2^{k\zeta}}
	\Bigg\}\,.
	\label{e:cdel.bounds.from.update.A}
	\end{align}
for all $t\ge0$.
We next turn to the question of bounding $\vec{\epsilon}(t)$ (as defined by \eqref{e:update.A.def.epsilon}) for $t\ge1$.\smallskip



\noindent\bemph{\hypertarget{p:ctypes.varupdate.UPDATE.B.MSG}{Part~4a}. Errors in averaged messages incurred by update B.} We now estimate the error between the averaged messages 
$\bar{q}_{e,t+1/3}$ and $\bar{q}_{e,t+2/3}$ for $t\ge0$. Between times $t+1/3$ and $t+2/3$ we only make the update
\eqref{e:cond.judicious.update}. In this part of the proof we will fix $e\in\delta v$ and abbreviate
(recalling
\eqref{e:cdel.max.notation} and \eqref{e:he.max.notation})
	\[
	\begin{pmatrix}
	\kappa_e(\tau) \\ \alpha_e(\sigma)
	\end{pmatrix}
	\equiv
	\begin{pmatrix}
	\kappa_{e,t+1/3}(\tau) \\ 
	\alpha_{e,t+1/3}(\sigma)
	\end{pmatrix}
	=\begin{pmatrix}
	\kappa_{e,t+1/3}(\tau) \\ 
	\alpha_{e,t}(\sigma)
	\end{pmatrix}
	\,.
	\]
By the definition
\eqref{e:defn.cdel.kappa} of $\kappa$, it holds for all $\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$ that
	\begin{equation}\label{e:orth}
	0=
	\sum_{\bm{L}}\nu_{e,t+1/3}(\bm{L})
	\Bigg\{
	(\nu_{e,t+1/3})^j(\tau\,|\,\bm{L})
	-{}_\star\hspace{-1pt}\pi_e(\tau)\Bigg\}
	=\sum_{\bm{L}}\nu_{e,t+1/3}(\bm{L})
	{}_\star\hspace{-1pt}\pi_e(\tau)
	(\kappa_{e,t+1/3})^j(\tau\,|\,\bm{L})\,,
	\end{equation}
where the first equality holds because $\nu_{e,t+1/3}$ is judicious on average. We now turn to comparing the messages. At time $t+1/3$ we have
$\bar{q}_{e,t+1/3}=\bar{q}_{e,t}$, defined by
 \eqref{e:defn.avhq.t}. More explicitly, it follows using
\eqref{e:first.defn.of.u} that
	\begin{equation}\label{e:relation.of.normalizing.constants}
	\bar{z}_{e,t}\bar{q}_{e,t}(\sigma)
	=\sum_{\bm{L}}
	\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})
	= \frac{\bm{\bar{z}}_{e,t+1/3}
		\nu_{e,t+1/3}(\sigma)
		}{u_{e,t+1/3}(\sigma)}
	\,,\end{equation}
On the other hand, at time $t+2/3$ we have (by Taylor expansion)
	\begin{align}\nonumber
	&\bar{z}_{e,t+2/3}\bar{q}_{e,t+2/3}(\sigma)
	=\sum_{\bm{L}}
	\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})
	\prod_{j=1,2}
	\frac1{1 +( \kappa_{e,t+1/3})^j(\sigma^j\,|\,\bm{L})
	}\\
	&\qquad
	=\bar{z}_{e,t}
	\Bigg\{
	\bar{q}_{e,t}(\sigma)
	\bigg\{
	1 + O \bigg(
		\sum_{j=1,2} \kappa_e(\sigma^j)^2
			\bigg)
	\bigg\}
	-\sum_{j=1,2}
	\underbrace{\Bigg[
	\sum_{\bm{L}}
	\frac{\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})}{\bar{z}_{e,t}}
	( \kappa_{e,t+1/3})^j(\sigma^j\,|\,\bm{L})
	\Bigg]}_{\textup{denote this }K^j(\sigma)}
	\Bigg\}
	\label{e:K.j.defn}
	\end{align} 
From the definition of $K^j(\sigma)$ we can easily deduce the bound 
	\begin{equation}\label{e:first.bound.K.j}
	\Big|K^j(\sigma)\Big|
	\le 
	O\Bigg(
	\frac{\kappa_e(\sigma^j)}{\bar{z}_{e,t}\hat{Z}_e}
	\bar{q}_{e,t}(\sigma)
	\sum_{\bm{L}} {}_\star\hspace{-1pt}\psi_e(\bm{L})
	\Bigg)
	= O\bigg(
	\bar{q}_{e,t}(\sigma)
	\cdot \kappa_e(\sigma^j) \bigg)\,,\end{equation}
where the last step uses that
$\bar{z}_{e,t}\hat{Z}_e=\Theta(1)$ by a similar calculation as in \eqref{e:prod.of.zs.is.close.to.one}.
On the other hand, we also have
	\begin{align}\nonumber
	\Big|K^j(\sigma)\Big|
	&=\Bigg|
	\frac{{}_{*}\hat{q}_e(\sigma)}{\hat{Z}_e}
	\sum_{\bm{L}}{}_\star\hspace{-1pt}\psi_e(\bm{L})
	\Bigg(1 + 
	\alpha_{e,t}(\sigma,\bm{L})
		\Bigg)
	( \kappa_{e,t+1/3})^j(\sigma^j\,|\,\bm{L})
	\Bigg|\\
	&\stackrel{\eqref{e:orth}}{\le}
	O\bigg( {}_{*}\hat{q}_e(\sigma) \cdot \kappa_e(\sigma^j) \cdot \alpha_e(\sigma) \bigg)\,.
	\label{e:second.bound.K.j}
	\end{align}
Combining \eqref{e:first.bound.K.j} with \eqref{e:second.bound.K.j} gives 
	\[
	K^j(\sigma)
	= O\Bigg(
	\bar{q}_{e,t}(\sigma)\cdot
	\kappa_e(\sigma^j)\cdot
	\min\bigg\{
	\frac{\alpha_e(\sigma) {}_{*}\hat{q}_e(\sigma)}
		{\bar{q}_{e,t}(\sigma)},
	1\bigg\}
	\Bigg)\,.
	\]
Substituting this bound into \eqref{e:K.j.defn} gives 
	\begin{align*}
	\bar{z}_{e,t+2/3}\bar{q}_{e,t+2/3}(\sigma)
	&= \bar{z}_{e,t}\bar{q}_{e,t}(\sigma)
	\Bigg\{
	1+\sum_{j=1,2}\kappa_e(\sigma^j)
	\cdot \min\bigg\{
		\frac{\alpha_e(\sigma) {}_{*}\hat{q}_e(\sigma)}
		{\bar{q}_{e,t}(\sigma)},1\bigg\}
	\Bigg\}\,.
	\end{align*}
It then follows using the hypothesis 
\eqref{e:rough.inductive.bounds.forall.t} 
 that
	\[\Bigg|
	\frac{\bar{z}_{e,t+2/3}\bar{q}_{e,t+2/3}(\sigma)}
	{\bar{z}_{e,t}\bar{q}_{e,t}(\sigma)}-1\Bigg|
	\le
	k^{O(1)}
	\begin{cases} \displaystyle
	\frac{\kappa}{2^{k(1+\zeta)}}
	&\textup{if }\SSPIN{r}[\sigma]=0\,,\medskip\\
	\displaystyle
	\frac{\kappa+\dot{\kappa}}
		{2^{k\zeta}}
	&\textup{if }\SSPIN{r}[\sigma]=1\,,\medskip\\
	\displaystyle \dot{\kappa}
	&\textup{if }\SSPIN{r}[\sigma]=2\,.
	\end{cases}
	\]
Altogether, the error in averaged messages
between times $t+1/3$
and $t+2/3$ satisfies
	\begin{equation}\label{e:ctypes.one.two.crelerr}
	\widehat{\textup{\textsf{\footnotesize ERR}}}
	(\bar{q}_{e,t+1/3},
	\bar{q}_{e,t+2/3})
	=\widehat{\textup{\textsf{\footnotesize ERR}}}
	(\bar{q}_{e,t},
	\bar{q}_{e,t+2/3})
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	2^{-k} & 2^{-k}\\
	1 & 1 \\
	2^{-k}&2^{k\zeta}
	\end{pmatrix}
	\begin{pmatrix}
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}\,.
	\end{equation}
Substituting \eqref{e:ctypes.one.two.crelerr}
into the definition of $u$ from \eqref{e:first.defn.of.u} gives
	\begin{equation}\label{e:ctypes.one.two.vrelerr}
	\Bigg|
	\frac{u_{e,t+2/3}(\sigma)}
		{u_{e,t+1/3}(\sigma)}
	-1\Bigg|
	\le
	\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\{
	\underbrace{\sum_{e\in\delta v}
	\kappa_{e,t+1/3}
	}_{\textup{denote this }\bm{\kappa}_{t+1/3}}
	+\underbrace{
	\sum_{e\in\delta v}
	\dot{\kappa}_{e,t+1/3}
	}_{\textup{denote this }\bm{\dot{\kappa}}_{t+1/3}}
	\Bigg\}
	\equiv
	\frac{k^{O(1)}
		(\bm{\kappa}_{t+1/3}+\bm{\dot{\kappa}}_{t+1/3})
	}{2^{k(1+\zeta)}}
	\end{equation}
for all $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$.\smallskip


\noindent\bemph{\hypertarget{p:ctypes.varupdate.UPDATE.C.MSG}{Part~4b}. Errors in averaged messages incurred by update C.} By a similar (but somewhat simpler) calculation, we can also estimate the error between the averaged messages $\bar{q}_{e,t+2/3}$ and $\bar{q}_{e,t+1}$ for $t\ge0$. Between times $t+2/3$ and $t+1$ we only make the update \eqref{e:clause.frac.update}. 
In this part of the proof we will fix $e\in\delta v$ and abbreviate
	\[
	\begin{pmatrix}
	\kappa_e(\tau) \\ \alpha_e(\sigma) \\ \rho_e
	\end{pmatrix}
	\equiv
	\begin{pmatrix}
	\kappa_{e,t+2/3}(\tau) \\ 
	\alpha_{e,t+2/3}(\sigma) \\ 
	\rho_{e,t+2/3}
	\end{pmatrix}\,.
	\]
By the definition \eqref{e:fdel.defn} of $\rho$, we have
	\begin{equation}\label{e:fdel.orth}	0=
	\sum_{\bm{L}}\Bigg\{
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
	-\nu_{e,t+2/3}(\bm{L})
	\Bigg\}
	=\sum_{\bm{L}}
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
	\Bigg\{
	\rho_{e,t+2/3}(\bm{L})
	+O\Big((\rho_e)^2\Big)\Bigg\}\,.\end{equation}








We now turn to the comparison of the messages:
by the update rule \eqref{e:clause.frac.update},
	\begin{align*}
	\bar{z}_{e,t+1}\bar{q}_{e,t+1}(\sigma)
	&= \sum_{\bm{L}}
	\psi_{e,t+2/3}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})
	\bigg\{1 + \rho_{e,t+2/3}(\bm{L}) \bigg\} \\
	&=\bar{z}_{e,t+2/3}
	\Bigg\{\bar{q}_{e,t+2/3}(\sigma)
	+\underbrace{
	\Bigg[\sum_{\bm{L}}
	\frac{\psi_{e,t+2/3}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})}{\bar{z}_{e,t+2/3}}
	\rho_{e,t+2/3}(\bm{L}) 
	\Bigg]}_{\textup{denote this }R(\sigma)}\Bigg\}\,.
	\end{align*}
From the definition of $R(\sigma)$ we can easily deduce the bound
	\[
	\Big|R(\sigma)\Big|
	\le
	O\bigg( \bar{q}_{e,t+2/3}(\sigma)
		\cdot \rho_e\bigg)\,.
	\]
On the other hand we also have
	\begin{align*}
	R(\sigma)
	&=
	\frac{{}_{*}\hat{q}_e(\sigma)
	}{\bar{z}_{e,t+2/3} \hat{Z}_e}
	\sum_{\bm{L}}
	{}_\star\hspace{-1pt}\psi_e(\bm{L})
	\bigg(1 + \alpha_{e,t+1/3}(\sigma,\bm{L})\bigg)
	\rho_{e,t+2/3}(\bm{L}) \\
	&=
	O\Bigg(
	{}_{*}\hat{q}_e(\sigma)\cdot
	\rho_e 
	\cdot\Big(\rho_e+\alpha_e(\sigma)\Big)\Bigg)\,,
	\end{align*}
where the last step uses \eqref{e:fdel.orth}.
Substituting back into the preceding calculation gives
	\[
	\bar{z}_{e,t+1}\bar{q}_{e,t+1}(\sigma)
	=\bar{z}_{e,t+2/3}\bar{q}_{e,t+2/3}(\sigma)
	\Bigg\{
	1 + O\bigg(
	\rho_e \cdot
	\min\bigg\{
	\frac{(\rho_e+\alpha_e(\sigma)){}_{*}\hat{q}_e(\sigma)}
		{\bar{q}_{e,t+2/3}(\sigma)} ,1
	\bigg\}\bigg)
	\Bigg\}\,.\]
It follows using the inductive bounds \eqref{e:rough.inductive.bounds.forall.t} that
	\begin{equation}\label{e:error.in.avhq.from.update.C}
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\bar{q}_{e,t+2/3},\bar{q}_{e,t+1})
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\rho_{e,t+2/3}
	\begin{pmatrix} 2^{-k} \\ 1 \\ 2^{k\zeta}
	\end{pmatrix}\,.
	\end{equation}
Substituting this again into the definition \eqref{e:first.defn.of.u} of $u$ gives
	\begin{equation}\label{e:ctypes.two.three.vrelerr}
	\Bigg|
	\frac{u_{e,t+1}(\sigma)}
	{u_{e,t+2/3}(\sigma)}-1
	\Bigg|
	\le
	\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\sum_{e\in\delta v}
	\rho_{e,t+2/3}
	\equiv
	\frac{k^{O(1)} }{2^{k(1+\zeta)}}
		\bm{\rho}_{t+2/3}
	\end{equation}
for all $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$.\smallskip

\noindent\bemph{\hypertarget{p:ctypes.varupdate.UPDATE.B.MGL}{Part 5a}. Errors in marginals incurred by update B.} We now estimate the change in the edge marginals between times $t+1/3$ and $t+2/3$, resulting from update \eqref{e:cond.judicious.update}. To this end we introduce an intermediate measure $\nu_{e,t+1/2}$, in which we use the new weight $\psi_{e,t+1}(\sigma\,|\,\bm{L})$ but the old message $u_{e,t+1/3}$. Thus, recalling \eqref{e:first.defn.of.u}, we have
	\begin{align*}
	\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\sigma,\bm{L})
	&= 
	\hat{q}_e(\sigma,\bm{L})\psi_{e,t}(\bm{L})
	\psi_{e,t}(\sigma\,|\,\bm{L})
	u_{e,t+1/3}(\sigma)\,,\\
	\bm{\bar{z}}_{e,t+1/2}\nu_{e,t+1/2}(\sigma,\bm{L})
	&= 
	\hat{q}_e(\sigma,\bm{L})\psi_{e,t}(\bm{L})
	\psi_{e,t+1}(\sigma\,|\,\bm{L})
	u_{e,t+1/3}(\sigma)\,,\\
	\bm{\bar{z}}_{e,t+2/3}\nu_{e,t+2/3}(\sigma,\bm{L})
	&=\hat{q}_e(\sigma,\bm{L}) \psi_{e,t}(\bm{L})
	\psi_{e,t+1}(\sigma\,|\,\bm{L})
	u_{e,t+2/3}(\sigma)\,.
	\end{align*}
We first estimate the error between times $t+1/3$ and $t+2/3$. For this purpose, note that \eqref{e:defn.cdel.kappa} implies
(similarly to the relation \eqref{e:cdel.avg.to.zero} that was used earlier) that for all $\bm{L}$,
	\begin{align}\nonumber
	0&=\sum_\tau
	\Bigg\{ (\nu_{e,t+1/3})^j(\tau\,|\,\bm{L})
	-{}_\star\hspace{-1pt}\pi_e(\tau)\Bigg\}
	=\sum_\tau\Bigg\{
	(\nu_{e,t+1/3})^j(\tau\,|\,\bm{L})
	-\frac{ (\nu_{e,t+1/3})^j(\tau\,|\,\bm{L})}
		{1 + (\kappa_{e,t+1/3})^j(\tau\,|\,\bm{L})}
	\Bigg\} \\
	&=\sum_\tau
	(\nu_{e,t+1/3})^j(\tau\,|\,\bm{L})
	(\kappa_{e,t+1/3})^j(\tau\,|\,\bm{L})
	+ O\Bigg(\sum_\tau
		{}_\star\hspace{-1pt}\pi_e(\tau) \kappa_{e,t+1/3}(\tau)^2\Bigg)\,.
		\label{e:orth.sigma}
	\end{align}
It follows using \eqref{e:orth.sigma} that the marginal error on $\bm{L}$ between times $t+1/3$ and $t+1/2$ is given by
	\begin{align}\nonumber
	\bm{\bar{z}}_{e,t+1/2}\nu_{e,t+1/2}(\bm{L})
	&=\sum_\sigma
	\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\sigma,\bm{L})
	\prod_{j=1,2}
	\frac1{1+(\kappa_{e,t+1/3})^j(\sigma^j\,|\,\bm{L})} \\
	&=\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\bm{L})
	\Bigg\{1 +
	O\Bigg(\sum_\tau
		{}_\star\hspace{-1pt}\pi_e(\tau) \kappa_{e,t+1/3}
		(\tau)^2\Bigg)\Bigg\}\,.
	\label{e:one.third.to.one.half.rho.comparison}
	\end{align}
We note the error term can be simplified
using \eqref{e:rough.inductive.bounds.forall.t} as
	\[
	\sum_\tau
		{}_\star\hspace{-1pt}\pi_e(\tau) \kappa_{e,t+1/3}
		(\tau)^2
	\le k^{O(1)}\Bigg(
	(\kappa_{e,t+1/3})^2
	+\frac{(\dot{\kappa}_{e,t+1/3})^2}{2^k}
	\Bigg)
	\le
	\frac{k^{O(1)}
		(\kappa_{e,t+1/3}+\dot{\kappa}_{e,t+1/3})}
		{ 2^{k(1+\zeta)}}\,.
	\]
The error between $u_{e,t+1/3}$ and $u_{e,t+2/3}$
is bounded by \eqref{e:ctypes.one.two.vrelerr}, and this gives the marginal error on $\bm{L}$ between times $t+1/2$ and $t+2/3$. Combining these bounds gives altogether
	\begin{equation}\label{e:one.to.two.thirds.clause}
	\rho_{e,t+2/3}
	-\rho_{e,t+1/3}
	\le
	\Bigg|\frac{\nu_{e,t+2/3}(\bm{L})}
	{\nu_{e,t+1/3}(\bm{L})}-1\Bigg|
	\le \frac{k^{O(1)}
		(\bm{\kappa}_{t+1/3}+\bm{\dot{\kappa}}_{t+1/3})
	}{2^{k(1+\zeta)}}\,.
	\end{equation}
Next we argue that the update \eqref{e:cond.judicious.update} in fact brings the measures closer to being conditionally judicious. Indeed, focusing on the first copy $j=1$,
we can express
	\[
	\frac{\bm{\bar{z}}_{e,t+1/2}
	\nu_{e,t+1/2}(\sigma,\bm{L})}
	{\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\bm{L})}
	=
	\frac{
	{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	{ (\nu_{e,t+1/3})^1(\sigma^1\,|\,\bm{L}) }
	\frac{\nu_{e,t+1/3}(\sigma\,|\,\bm{L})}
	{1+(\kappa_{e,t+1/3})^2(\sigma^2\,|\,\bm{L})}\,,
	\]
and summing over $\sigma^2$ gives
	\begin{align*}
	&\frac{\bm{\bar{z}}_{e,t+1/2}
	\nu_{e,t+1/2}(\sigma^1,\bm{L})}
	{\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\bm{L})}
	=\frac{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	{ (\nu_{e,t+1/3})^1(\sigma^1\,|\,\bm{L}) }
	\sum_{\sigma^2}
	\nu_{e,t+1/3}(\sigma\,|\,\bm{L})
	\Bigg\{
	1 + O(\kappa_{e,t+1/3}(\sigma^2)^2) - 
	(\kappa_{e,t+1/3})^2(\sigma^2\,|\,\bm{L})
	\Bigg\}\\
	&\qquad=
	{}_\star\hspace{-1pt}\pi_e(\sigma^1)
	\Bigg\{
	1+ 
	O\Bigg(\sum_\tau
		{}_\star\hspace{-1pt}\pi_e(\tau) \kappa_{e,t+1/3}
		(\tau)^2\Bigg)
	-\sum_{\sigma^2}
	\frac{
	\nu_{e,t+1/3}(\sigma\,|\,\bm{L})}
	{ (\nu_{e,t+1/3})^1(\sigma^1\,|\,\bm{L}) }
	(\kappa_{e,t+1/3})^2(\sigma^2\,|\,\bm{L})
	\Bigg\}\\
	&\qquad=
	{}_\star\hspace{-1pt}\pi_e(\sigma^1)
	\Bigg\{
	1+ 
	O\Bigg(\sum_\tau
		{}_\star\hspace{-1pt}\pi_e(\tau) \kappa_{e,t+1/3}
		(\tau)^2\Bigg)
	-\underbrace{\sum_{\sigma^2}
	\frac{
	\nu_{e,t+1/3}(\sigma\,|\,\bm{L})}
	{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	(\kappa_{e,t+1/3})^2(\sigma^2\,|\,\bm{L})
	}_{\textup{denote this }S^1(\sigma^1\,|\,\bm{L})}
	\Bigg\}\,.
	\end{align*}
We then use 
\eqref{e:rough.inductive.bounds.forall.t}
and \eqref{e:orth} to estimate (with $\kappa\equiv \kappa_{e,t+1/3}$
and $\xi\equiv \xi_{e,t+1/3}$)
	\begin{align*}
	S(\sigma^1\,|\,\bm{L})
	&=
	\sum_{\sigma^2}
	\bigg\{
	1+\xi_{e,t+1/3}(\sigma\,|\,\bm{L})\bigg\}
	{}_\star\hspace{-1pt}\pi_e(\sigma^2)
	(\kappa_{e,t+1/3})^2(\sigma^2\,|\,\bm{L})\\
	&\le
	\begin{cases}\displaystyle
	k^{O(1)}\bigg(
	\kappa\xi + \frac{\dot{\kappa}\dot{\xi}}{ 2^k}\bigg)
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\bigg(
	\kappa
	+	\frac{\dot{\kappa}}{2^k}
		\bigg)
	& \textup{if }\sigma^1\ne\SSPIN{r}\,,\medskip\\
	\displaystyle
	k^{O(1)}\bigg(
	\kappa\dot{\xi} + \frac{\dot{\kappa} \ddot{\xi}}{2^k}
		\bigg)
	\le \frac{k^{O(1)}}{2^{k\zeta}}
		(\kappa + \dot{\kappa})
	& \textup{if }\sigma^1=\SSPIN{r}\,.
	\end{cases}
	\end{align*}
By substituting this into the preceding calculation
 and combining with
\eqref{e:one.third.to.one.half.rho.comparison}, 
we conclude that
	\[
	\begin{pmatrix}
	\kappa_{e,t+1/2}\\
	\dot{\kappa}_{e,t+1/2}
	\end{pmatrix}
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	1 & 2^{-k} \\
	1 & 1
	\end{pmatrix}
	\begin{pmatrix}
	\kappa_{e,t+1/3} \\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}\,.
	\]
We combine this with the error incurred by going from time $t+1/2$ to $t+2/3$ --- this results from the change in the message $u$, which again is bounded by \eqref{e:ctypes.one.two.vrelerr}. Altogether we conclude
	\begin{equation}\label{e:ctypes.one.two.cond}
	\begin{pmatrix}
	\kappa_{e,t+2/3}\\
	\dot{\kappa}_{e,t+2/3}
	\end{pmatrix}
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	1& 2^{-k} \\
	1 &1
	\end{pmatrix}
	\begin{pmatrix}
	\kappa_{e,t+1/3} \\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	+	\frac{k^{O(1)}
		(\bm{\kappa}_{t+1/3}+\bm{\dot{\kappa}}_{t+1/3})
	}{2^{k(1+\zeta)}}
	\begin{pmatrix}1\\1\end{pmatrix}
	\end{equation}
for all $e\in\delta v$.\smallskip


\noindent\bemph{\hypertarget{p:ctypes.varupdate.UPDATE.C.MGL}{Part~5b}. Errors in marginals incurred by update C.} We now estimate the change in edge marginals between times $t+2/3$ and $t+1$, resulting from update \eqref{e:clause.frac.update}. To this end, we can express
	\begin{align*}
	\bm{\bar{z}}_{e,t+1}\nu_{e,t+1}(\sigma,\bm{L})
	&= \bm{\bar{z}}_{e,t+2/3}\nu_{e,t+2/3}(\sigma,\bm{L})
	\frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}{\nu_{e,t+2/3}(\bm{L})}
	\frac{u_{e,t+1}(\sigma)}{u_{e,t+2/3}(\sigma)}\\
	&=\bm{\bar{z}}_{e,t+2/3}\nu_{e,t+2/3}(\sigma,\bm{L})
	\frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}{\nu_{e,t+2/3}(\bm{L})}
	\Bigg\{ 1 + O\bigg( 
	\frac{k^{O(1)} \bm{\rho}_{t+2/3}}{2^{k(1+\zeta)}}
		\bigg)\Bigg\}\,,
	\end{align*}
where the last estimate comes from \eqref{e:ctypes.two.three.vrelerr}. Summing over $\sigma$ gives
	\begin{equation}\label{e:ctypes.two.three.clause}
	\nu_{e,t+1}(\bm{L})
	= \frac{\bm{\bar{z}}_{e,t+2/3}
		\cdot \pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
		{\bm{\bar{z}}_{e,t+1}}
	\Bigg\{ 1 + O\bigg( 
	\frac{k^{O(1)} \bm{\rho}_{t+2/3}}{2^{k(1+\zeta)}}
		\bigg)\Bigg\}
	=\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
	\Bigg\{ 1 + O\bigg( 
	\frac{k^{O(1)} \bm{\rho}_{t+2/3}}{2^{k(1+\zeta)}}
		\bigg)\Bigg\}\,,
	\end{equation}
where the last equality is because both 
$\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)$
and $\nu_{e,t+1}(\bm{L})$ are probability measures over $\bm{L}$. On the other hand, the conditional measures given $\bm{L}$ change very little as a result of update \eqref{e:clause.frac.update}: it follows from the above that
	\begin{equation}\label{e:ctypes.two.three.cond}
	\nu_{e,t+1}(\sigma\,|\,\bm{L})
	=\nu_{e,t+2/3}(\sigma\,|\,\bm{L})
	\Bigg\{ 1 + O\bigg( 
	\frac{k^{O(1)} \bm{\rho}_{t+2/3}}{2^{k(1+\zeta)}}
		\bigg)\Bigg\}
	\end{equation}
for all $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$. 
Combining \eqref{e:ctypes.two.three.clause} and \eqref{e:ctypes.two.three.cond} gives
	\begin{equation}\label{e:update.C.single.edge}
	\begin{pmatrix}
	\rho_{e,t+1}\\
	\kappa_{e,t+1}\\
	\dot{\kappa}_{e,t+1}\end{pmatrix}
	\le
	\begin{pmatrix}
	0\\
	\kappa_{e,t+2/3}\\
	\dot{\kappa}_{e,t+2/3}\end{pmatrix}
	+ \frac{k^{O(1)}}{2^{k(1+\zeta)}} \bm{\rho}_{t+2/3}
		\begin{pmatrix}1\\1\\1\end{pmatrix}\,.
	\end{equation}
Finally,
recalling
\eqref{e:intermediate.bullet.measure}, we compare the measures
	\begin{align*}
	\bm{\bar{z}}_{e,t+1}\nu_{e,t+1}(\sigma,\bm{L})
	&= \psi_{e,t+1}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})
	u_{e,t+1}(\sigma)\,,\\
	\bm{\bar{z}}_{e\bullet,t+1}
		\nu_{e\bullet,t+1}(\sigma,\bm{L})
	&= \psi_{e,t+1}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})
	u_{e,t+1/3}(\sigma)\,.
	\end{align*}
It follows by combining
\eqref{e:ctypes.one.two.vrelerr} and \eqref{e:ctypes.two.three.vrelerr} that
	\begin{equation}\label{e:update.C.single.edge.back.to.bullet}
	\begin{pmatrix}
	\rho_{e\bullet,t+1}\\
	\kappa_{e\bullet,t+1}\\
	\dot{\kappa}_{e\bullet,t+1}
	\end{pmatrix}
	\le\begin{pmatrix}
	\rho_{e,t+1}\\
	\kappa_{e,t+1}\\
	\dot{\kappa}_{e,t+1}\end{pmatrix}
	+\frac{k^{O(1)}
	}{2^{k(1+\zeta)}}
	\bigg(\bm{\kappa}_{t+1/3}+\bm{\dot{\kappa}}_{t+1/3}
	+\bm{\rho}_{t+2/3}\bigg)
	\begin{pmatrix}1\\1\\1\end{pmatrix}\,.
	\end{equation}
This concludes our analysis of update C.\smallskip

\noindent\bemph{\hypertarget{p:ctypes.varupdate.CONCLUSION}{Part~6}. Convergence of iterative procedure.} We now collect the bounds obtained above to prove that the iterative procedure described in \hyperlink{p:ctypes.varupdate.ITERATIVE.CONSTRUCTION}{Part~1} converges. Recall from \eqref{e:update.A.def.epsilon} the definition of $\vec{\epsilon}(t)$. For $t\ge1$, it follows by combining \eqref{e:ctypes.one.two.crelerr} (from \hyperlink{p:ctypes.varupdate.UPDATE.B.MSG}{Part~4a}) and \eqref{e:error.in.avhq.from.update.C} (from \hyperlink{p:ctypes.varupdate.UPDATE.C.MSG}{Part~4b}) that we have
	\begin{equation}\label{e:vec.eps.t.bound}
	\vec{\epsilon}(t)
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	2^{-k} & 2^{-k} & 2^{-k}\\
	1 & 1 & 1\\
	2^{k\zeta}
	&2^{-k}&2^{k\zeta} 
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e,t-1/3}\\
	\kappa_{e,t-2/3}\\
	\dot{\kappa}_{e,t-2/3}
	\end{pmatrix}\,.
	\end{equation}
It will be useful to abbreviate $\bm{K}\equiv\bm{\kappa}+\bm{\dot{\kappa}}$.
Recall that $\textup{\textsf{err}}_v(t)$ is defined analogously to
\eqref{e:defn.of.err.v.notation}, so
	\[\textup{\textsf{err}}_v(t)\le
	\sum_{e\in\delta v}
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	1 & 2^{-k} & 2^{-k(1+\zeta)}
	\end{pmatrix}
	\begin{pmatrix}
	2^{-k} & 2^{-k} & 2^{-k}\\
	1 & 1 & 1\\
	2^{k\zeta} & 2^{-k} &2^{k\zeta}
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e,t-1/3}\\
	\kappa_{e,t-2/3}\\
	\dot{\kappa}_{e,t-2/3}
	\end{pmatrix}






	\le \frac{k^{O(1)}
		(\bm{K}_{t-2/3}
		+\bm{\rho}_{t-1/3}
	)}{2^{k(1+\zeta)}}
	\,.\]
We then substitute these bounds into the analysis of update A, from \hyperlink{p:ctypes.varupdate.UPDATE.A.GENERAL}{Part~3b}: from \eqref{e:fdel.bounds.from.update.A} 
and \eqref{e:cdel.bounds.from.update.A} we obtain
	\begin{equation}\label{e:update.A.single.edge}
	\begin{pmatrix}
	\rho_{e,t+1/3}\\
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	\le
	\begin{pmatrix}
	1&0&0\\
	1&1&0\\
	1&0&1
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e\bullet,t}\\
	\kappa_{e\bullet,t}\\
	\dot{\kappa}_{e\bullet,t}
	\end{pmatrix}
	+\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\{
	\frac{\bm{\rho}_{t-1/3}+\bm{K}_{t-2/3}}
		{2^{k(1+\zeta)}} 
	+ \frac{\kappa_{e,t-2/3}
	+\dot{\kappa}_{e,t-2/3}
	+\rho_{e,t-1/3}}{2^{k\zeta}}
	\Bigg\}
	\begin{pmatrix}
	1\\1\\2^k
	\end{pmatrix}\,.
	\end{equation}
Next, from the analysis of the marginal errors resulting from update B (\hyperlink{p:ctypes.varupdate.UPDATE.B.MGL}{Part~5a}), we have
the bounds
 \eqref{e:one.to.two.thirds.clause} and
\eqref{e:ctypes.one.two.cond}, which we recall give
	\begin{equation}\label{e:update.B.single.edge}
	\begin{pmatrix}
	\rho_{e,t+2/3}\\
	\kappa_{e,t+2/3}\\
	\dot{\kappa}_{e,t+2/3}
	\end{pmatrix}
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	2^{k\zeta} &0&0\\
	0&1& 2^{-k} \\
	0&1 &1
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e,t+1/3} \\
	\kappa_{e,t+1/3} \\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	+	\frac{k^{O(1)} \bm{K}_{t+1/3}
	}{2^{k(1+\zeta)}}
	\begin{pmatrix}1\\1\\1\end{pmatrix}\,.
	\end{equation}

















From the analysis of marginal errors resulting from update C (\hyperlink{p:ctypes.varupdate.UPDATE.C.MGL}{Part~5b}), we have the bounds 
\eqref{e:update.C.single.edge}
and \eqref{e:update.C.single.edge.back.to.bullet},
which combine to give
	\begin{equation}\label{e:update.C.single.edge.combined.final}
	\begin{pmatrix}
	\rho_{e\bullet,t+1}\\
	\kappa_{e\bullet,t+1}\\
	\dot{\kappa}_{e\bullet,t+1}
	\end{pmatrix}
	\le\begin{pmatrix}
	0\\
	\kappa_{e,t+2/3}\\
	\dot{\kappa}_{e,t+2/3}\end{pmatrix}
	+\frac{k^{O(1)}
	}{2^{k(1+\zeta)}}
	\bigg(
	\bm{\rho}_{t+2/3}
	+\bm{K}_{t+1/3}
	\bigg)
	\begin{pmatrix}1\\1\\1\end{pmatrix}\,.
	\end{equation}
Combining the above bounds gives, for all $t\ge1$,
	\begin{align*}
	\begin{pmatrix}
	\rho_{e\bullet,t}\\
	\kappa_{e\bullet,t}\\
	\dot{\kappa}_{e\bullet,t}
	\end{pmatrix}
	&\stackrel{
	\eqref{e:update.C.single.edge.combined.final}
	}{\le}
	\begin{pmatrix}
	0\\
	\kappa_{e,t-1/3}\\
	\dot{\kappa}_{e,t-1/3}\end{pmatrix}
	+\frac{k^{O(1)}
	}{2^{k(1+\zeta)}}
	\bigg(
	\bm{\rho}_{t-1/3}
	+\bm{K}_{t-2/3}\bigg)
	\begin{pmatrix}1\\1\\1\end{pmatrix}\\
	&\stackrel{\eqref{e:update.B.single.edge}}{\le}
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	0 &0&0\\
	0&1& 2^{-k} \\
	0&1 &1
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e,t-2/3} \\
	\kappa_{e,t-2/3} \\
	\dot{\kappa}_{e,t-2/3}
	\end{pmatrix}
	+\frac{k^{O(1)}
	}{2^{k(1+\zeta)}}
	\bigg(
	\bm{\rho}_{t-1/3}
	+\bm{K}_{t-2/3}\bigg)
	\begin{pmatrix}1\\1\\1\end{pmatrix}\,.
	\end{align*}
Substituting these bounds 
(along with \eqref{e:update.B.single.edge})
into \eqref{e:update.A.single.edge} gives
	\begin{equation}\label{e:fdel.cdel.single.edge.bound}
	\begin{pmatrix}
	\rho_{e,t+1/3}\\
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\left\{
	\begin{pmatrix} 
	0&0&0\\
	0&1&0\\
	0&1&1
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e,t-2/3}\\
	\kappa_{e,t-2/3}\\
	\dot{\kappa}_{e,t-2/3}
	\end{pmatrix}
	+\frac{\bm{\Upsilon}_{t-2/3}}{2^k}
	\begin{pmatrix}1\\1\\1
	\end{pmatrix}
	\right\}\,,
	\end{equation}
where $\bm{\Upsilon}\equiv\bm{\rho}+\bm{K}$.
(In the $3\times3$ matrix on the right-hand side of \eqref{e:fdel.cdel.single.edge.bound}, some entries are zero because we absorbed the errors into the $\bm{\Upsilon}_{t-2/3}$ term.)
Aggregating the last bound over $e\in\delta v$ gives
	\[
	\bm{\Upsilon}_{t+1/3}
	\equiv
	\bm{\rho}_{t+1/3}+\bm{K}_{t+1/3}
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{\bm{\rho}_{t+1/3}+\bm{K}_{t+1/3}\Bigg\}
	= \frac{k^{O(1)}}{2^{k\zeta}}
	\bm{\Upsilon}_{t-2/3}\,,
	\]
for all $t\ge1$. This implies that the iterative procedure of \hyperlink{p:ctypes.varupdate.ITERATIVE.CONSTRUCTION}{Part~1} converges to the desired weights
$\Psi_v\equiv\Psi_{v,\infty}$. We now turn to proving
that the weights satisfy the bounds \eqref{e:defn.of.err.v.notation} and \eqref{e:ctypes.varupdate.MAINBOUND}. 
Summing \eqref{e:fdel.cdel.single.edge.bound} over $t\ge1$ gives
	\begin{align*}
	S_{\ge1} &\equiv
	\begin{pmatrix}
	1&0\\1&1
	\end{pmatrix}
	\sum_{t\ge1}
	\begin{pmatrix}
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	\le
	\begin{pmatrix}
	1&0\\1&1
	\end{pmatrix}
	\sum_{t\ge1}
	\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	\begin{pmatrix} 
	1&0\\
	1&1
	\end{pmatrix}
	\begin{pmatrix}
	\kappa_{e,t-2/3}\\
	\dot{\kappa}_{e,t-2/3}
	\end{pmatrix}
	+\frac{\bm{\Upsilon}_{t-2/3}}{2^k}
	\begin{pmatrix}1\\1\end{pmatrix}
	\Bigg\}\\
	&\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	\begin{pmatrix}
	1&0\\1&1
	\end{pmatrix}
	\sum_{t\ge1}
	\begin{pmatrix}
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	+ \frac{\bm{\Upsilon}_{1/3}}{2^k}
	\begin{pmatrix}1\\1\end{pmatrix}
	+ S_{\ge1}
	\Bigg\}\,,
	\end{align*}
and rearranging this inequality gives an upper bound on $S_{\ge1}$. It follows using
\eqref{e:fdel.cdel.single.edge.bound} again that
	\begin{align*}
	\sum_{t\ge1}\begin{pmatrix}
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	&\le
	\begin{pmatrix}
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	+\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	\begin{pmatrix} 
	1&0\\
	1&1
	\end{pmatrix}
	\begin{pmatrix}
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	+\frac{\bm{\Upsilon}_{1/3}}{2^k}
	\begin{pmatrix}1\\1\end{pmatrix}
	+S_{\ge1}
	\Bigg\}\\
	&\le
	k^{O(1)}\Bigg\{
	\begin{pmatrix}
	1 & 0 \\ 2^{-k\zeta} & 1
	\end{pmatrix}
	\begin{pmatrix}
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	+\frac{\bm{\Upsilon}_{1/3}}{2^{k(1+\zeta)}}
		\begin{pmatrix}1\\1\end{pmatrix}
	\Bigg\}\,,
	\end{align*}
where the last step makes use of the upper bound on $S_{\ge1}$. We can also use 
\eqref{e:update.B.single.edge}
and \eqref{e:fdel.cdel.single.edge.bound}
to bound the sum of $\rho_{e,t+2/3}$ over all $t\ge1$, so altogether we have
	\begin{equation}\label{e:sum.over.t.positive}
	\sum_{t\ge1}\begin{pmatrix}
	\rho_{e,t+2/3}\\
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	\le
	k^{O(1)}\Bigg\{
	\begin{pmatrix}
	0&0&0\\
	0&1&0\\
	0&2^{-k\zeta} & 1
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e,1/3}\\
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	+\frac{\bm{\Upsilon}_{1/3}}{2^{k(1+\zeta)}}
		\begin{pmatrix} 1\\ 1\\1\end{pmatrix}
	\Bigg\}
	\end{equation}
We can then apply 
\eqref{e:fdel.bounds.from.update.A} and \eqref{e:cdel.bounds.from.update.A} with $t=0$ to obtain
	\[
	\begin{pmatrix}
	\rho_{e,1/3}\\
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	\le
	\begin{pmatrix}
	1&0&0\\
	1&1&0\\
	1&0&1
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e\bullet,0}\\
	\kappa_{e\bullet,0}\\
	\dot{\kappa}_{e\bullet,0}
	\end{pmatrix}
	+\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\{
	 \textup{\textsf{err}}_v
	+\dot{\epsilon}_e
	+\frac{\min\set{\ddot{\epsilon}_e,1}}
		{2^{k(1+\zeta)}}
	\Bigg\}
	\begin{pmatrix}
	1 \\ 1\\ 2^k
	\end{pmatrix}\,.
	\]
Finally, since we see from \eqref{e:table.of.all.measures}
that $\nu_{e,-2/3}
\cong \hat{p}_e \phi_e u_{e,-2/3}$
while
$\nu_{e\bullet,0}
\cong \hat{q}_e \phi_e u_{e,-2/3}$, we conclude
that 
	\[\begin{pmatrix}
	\rho_{e\bullet,0}\\
	\kappa_{e\bullet,0}\\
	\dot{\kappa}_{e\bullet,0}
	\end{pmatrix}
	\le
	\underbrace{\begin{pmatrix}
	\rho_{e,-2/3}\\
	\kappa_{e,-2/3}\\
	\dot{\kappa}_{e,-2/3}
	\end{pmatrix}
	}_{\textup{zero}}
	+
	\begin{pmatrix}
	1 & 2^{-k} & 2^{-k}\\
	1 & 2^{-k} & 2^{-k}\\
	1 & 1 & 1
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e \\
	\dot{\epsilon}_e\\
	\min\set{\ddot{\epsilon}_e,1}/2^{k\zeta}
	\end{pmatrix}\,,
	\]
where the first term on the right-hand side vanishes because $\nu_{e,-2/3}$ is fully judicious by the assumption. Combining the last two bounds gives
	\[\begin{pmatrix}
	\rho_{e,1/3}\\
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	\le\begin{pmatrix}
	1 & 2^{-k} & 2^{-k}\\
	1 & 2^{-k} & 2^{-k}\\
	1 & 1 & 1
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e \\
	\dot{\epsilon}_e\\
	\min\set{\ddot{\epsilon}_e,1}/2^{k\zeta}
	\end{pmatrix}
	+\frac{k^{O(1)} \textup{\textsf{err}}_v}
		{2^{k(1+\zeta)}}
	\begin{pmatrix}
	1 \\ 1\\ 2^k
	\end{pmatrix}\,.
	\]
This implies $\bm{\Upsilon}_{1/3} \le O(\textup{\textsf{err}}_v)$. It follows by combining with
\eqref{e:sum.over.t.positive} that
	\begin{equation}\label{e:final.sum.bound}
	\sum_{t\in\mathbb{Z},t\ge 0}
	\begin{pmatrix}
	\rho_{e,t+2/3}\\
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	\le
	\begin{pmatrix}
	1 & 2^{-k} & 2^{-k}\\
	1 & 2^{-k} & 2^{-k}\\
	1 & 1 & 1
	\end{pmatrix}
		\begin{pmatrix}
	\epsilon_e \\
	\dot{\epsilon}_e\\
	\min\set{\ddot{\epsilon}_e,1}/2^{k\zeta}
	\end{pmatrix}
	+\frac{k^{O(1)}\textup{\textsf{err}}_v}{2^{k(1+\zeta)}}
	\begin{pmatrix}
	1 \\ 1\\ 2^k
	\end{pmatrix}\,.
	\end{equation}
We remark that 
\eqref{e:final.sum.bound}
implies that the quantities $\rho,\kappa,\dot{\kappa}$ satisfy the claimed bound 
\eqref{e:rough.inductive.bounds.forall.t}.
The quantities $\alpha,\xi$ can be bounded in terms 
of $\rho,\kappa,\dot{\kappa}$, so it is straightforward to deduce that 
\eqref{e:rough.inductive.bounds.forall.t} indeed holds.
To conclude, it follows by recalling \eqref{e:cond.judicious.update}
and \eqref{e:defn.cdel.kappa}
that
	\[\Bigg|\frac{(\psi_{e,\infty})^j
		(\tau\,|\,\bm{L})}
		{(\phi_e)^j(
		\tau\,|\,\bm{L})}-1\Bigg|
	\le
	O\Bigg(
	\sum_{t\in\mathbb{Z},t\ge 0}
	\Bigg|
	\frac{(\psi_{e,t+1})^j
		(\tau\,|\,\bm{L})}
		{(\psi_{e,t})^j(
		\tau\,|\,\bm{L})}-1\Bigg|
		\Bigg)
	\le O\Bigg(
	\sum_{t\ge0}
	\kappa_{e,t+1/3}(\tau)
	\Bigg)\,.\]
It follows by recalling
\eqref{e:clause.frac.update}
and \eqref{e:fdel.defn}
that
	\[\sum_{t\in\mathbb{Z},t\ge 0}
	\Bigg|
	\frac{\psi_{e,t+1}(\bm{L})}{\psi_{e,t}(\bm{L})}-1\Bigg|
	\le O(1)
	\sum_{t\ge0}
	\rho_{e,t+2/3}\,.
	\]
These quantities are bounded by \eqref{e:final.sum.bound}, and 
this implies the claimed bound 
\eqref{e:ctypes.varupdate.MAINBOUND} for the clause-dependent weights. 
The errors in the clause-independent weights $\psi_v(\smash{\vec{\sigma}}_{\delta v})$ can be bounded by applying
Proposition~\ref{p:var.update} with input errors $\vec{\epsilon}(t)$ for integers $t\ge0$, where
(recalling \eqref{e:update.A.def.epsilon}) we have
	\begin{align}\nonumber
	\vec{E}
	&\equiv \sum_{t\in\mathbb{Z},t\ge0} \vec{\epsilon}(t)
	=\sum_{t\in\mathbb{Z},t\ge0}
	\Bigg\{\widehat{\textup{\textsf{\footnotesize ERR}}}(\bar{q}_{t-2/3},
	\bar{q}_{t-1/3})
	+\widehat{\textup{\textsf{\footnotesize ERR}}}(\bar{q}_{t-1/3},
	\bar{q}_{t})
	\Bigg\}\\
	&\stackrel{\eqref{e:vec.eps.t.bound}}{\le}
	\vec{\epsilon}(0)
	+\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	2^{-k} & 2^{-k} & 2^{-k}\\
	1 & 1 & 1\\
	2^{k\zeta} & 2^{-k} & 2^{k\zeta} 
	\end{pmatrix}
	\sum_{t\in\mathbb{Z},t\ge0} 
	\begin{pmatrix}
	\rho_{e,t+2/3}\\
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix} \nonumber \\
	&\stackrel{\eqref{e:final.sum.bound}}{\le}
	k^{O(1)}
	\begin{pmatrix}
	1 & 2^{-k} & 2^{-k} \\
	1 & 1 & 1 \\
	1 & 1 & 1 
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e\\
	\dot{\epsilon}_e\\
	\min\set{\ddot{\epsilon}_e,1}/2^{k\zeta}
	\end{pmatrix}
	+\frac{k^{O(1)}\textup{\textsf{err}}_v}{2^{k\zeta}}
	\begin{pmatrix}
	2^{-k}\\ 1 \\ 2^{k\zeta}
	\end{pmatrix}\,.
	\label{e:final.bound.sum.eps.over.t}
	\end{align}
It follows from this that 
	\begin{align*}
	E_e + \frac{\dot{E}_e}{2^k}
	+ \frac{\min\set{\ddot{E}_e,1}}{2^{k(1+\zeta)}}
	&\le k^{O(1)}
	\Bigg\{
	\epsilon_e + \frac{\dot{\epsilon}_e}{2^k}
	+ \frac{\min\set{\ddot{\epsilon}_e,1}}{2^{k(1+\zeta)}}
	 + \frac{\textup{\textsf{err}}_v}{2^{k(1+\zeta)}}
	\Bigg\}\,,\\
	\dot{E}_e
	+\frac{\min\set{\ddot{E}_e,1}}{2^{k\zeta}}
	&\le
	k^{O(1)}
	\Bigg\{
	\epsilon_e + \dot{\epsilon}_e
	+ \min\set{\ddot{\epsilon}_e,1}
	 + \frac{\textup{\textsf{err}}_v}{2^{k\zeta}}
	\Bigg\}\,.
	\end{align*}
Thus, if we apply the bound Proposition~\ref{p:var.update}
with input errors $\vec{\epsilon}(t)$ 
summed over all $t\ge0$, the final bound
will still be of the form \eqref{e:defn.of.err.v.notation}, as claimed.\smallskip


\noindent\bemph{\hypertarget{p:ctypes.varupdate.OUTMSG}{Part~7}. Error bound for outgoing messages.}
It remains to verify \eqref{e:ctypes.varupdate.OUTMSG}. This follows by a similar argument as in \hyperlink{c:var.update.BETTER.MGL.BOUND}{Step~2 of the proof of Corollary~\ref{c:var.update}}. 
Fix an edge $e\in\delta v$, and define $\hat{s}_e = \hat{p}_e$ and $\hat{s}_e=\hat{q}_{e'}$ for $e'\in\delta v\setminus e$. We can apply the above result to obtain weights $\Theta_v$
such that $\nu_{\delta v}[\Theta_v;\hat{s}]$
is fully judicious. On the same edge $e$, the outgoing \textsc{bp} messages for the measures
$\nu_{\delta v}[\Phi_v;\hat{p}]$,
$\nu_{\delta v}[\Theta_v;\hat{s}]$, and 
$\nu_{\delta v}[\Psi_v;\hat{q}]$ are given by
	\begin{align*}
	\dot{p}_e(\sigma,\bm{L})
	&\cong \phi_e(\sigma,\bm{L}) u_p(\sigma)\\
	\dot{s}_e(\sigma,\bm{L})
	&\cong \theta_e(\sigma,\bm{L}) u_s(\sigma)\\
	\dot{q}_e(\sigma,\bm{L})
	&\cong \psi_e(\sigma,\bm{L}) u_q(\sigma)
	\end{align*}
where $u_p \equiv u_{e,-2/3}$, $u_q \equiv u_{e,\infty}$, and analogously
	\[
	u_s(\sigma_e)
	\cong \sum_{\smash{\vec{\sigma}}_{\delta a \setminus e}}
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\theta_v(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e'\in\delta a \setminus e}\Bigg\{
	\sum_{\bm{L}}
	\theta_{e'}(\sigma_{e'},\bm{L}_{e'})
	\hat{s}_{e'}(\sigma_{e'},\bm{L}_{e'})
	\Bigg\}\,.
	\]
Conditional on $\bm{L}$, we use \eqref{e:reweighted.messages.v.to.c} to define the reweighted messages 
$P_e(\sigma\,|\,\bm{L})$,
$S_e(\sigma\,|\,\bm{L})$,
$Q_e(\sigma\,|\,\bm{L})$.
Recall \eqref{e:delta.vec.of.t}, and note that
	\[
	\vec{D} 
	\equiv
	\dddot{\textup{\textsf{\footnotesize ERR}}}(u_p,u_q)
	\le O\Bigg(
	\sum_{t\in\mathbb{Z},t\ge0}
	\dddot{\textup{\textsf{\footnotesize ERR}}}
	(u_{e,t-2/3},u_{e,t+1/3})
	\Bigg)
	=O\Bigg( 
	\sum_{t\in\mathbb{Z},t\ge0}
	\vec{\delta}(t+1/3)\Bigg)\,.\]
Let $\vec{D}'$ denote the first three entries of $\vec{D}$. Then 
	\begin{align*}
	\vec{D}'
	&
	\stackrel{\eqref{e:vec.delta.bound.with.L}}{\le}
	k^{O(1)}
	\sum_{t\in\mathbb{Z},t\ge0}
	\left\{
	\begin{pmatrix}
	1\\1\\1
	\end{pmatrix} \textup{\textsf{err}}_v(t)
	+ 
	\begin{pmatrix}
	0&0&0\\
	0&1&1\\
	0&1&1
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e(t)\\
	\dot{\epsilon}_e(t)\\
	\min\set{\ddot{\epsilon}_e(t),1}/2^{k\zeta}
	\end{pmatrix}
	\right\} \\
	&\stackrel{\eqref{e:final.bound.sum.eps.over.t}}{\le} k^{O(1)}\left\{
	\begin{pmatrix}
	1\\1\\1
	\end{pmatrix} \textup{\textsf{err}}_v
	+ 
	\begin{pmatrix}
	0&0&0\\
	0&1&1\\
	0&1&1
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e\\
	\dot{\epsilon}_e\\
	\min\set{\ddot{\epsilon}_e,1}/2^{k\zeta}
	\end{pmatrix}\right\}
	\end{align*}
Meanwhile, the errors between the edge weights
$\phi_e(\sigma,\bm{L})$,
$\theta_e(\sigma,\bm{L})$, and $\psi_e(\sigma,\bm{L})$ are bounded by \eqref{e:ctypes.varupdate.MAINBOUND}.
From this it is easy to see that
	\[
	\max_{\bm{L}}\Bigg\{
	\Bigg|
	\frac{\dot{s}_e(\bm{L})}{\dot{p}_e(\bm{L})}-1
	\Bigg|+ 
	\Bigg|
	\frac{\dot{q}_e(\bm{L})}{\dot{p}_e(\bm{L})}-1
	\Bigg|
	+\Bigg\|
	\frac{S_e(\cdot\,|\,\bm{L})}{P_e(\cdot\,|\,\bm{L})}-1
	\Bigg\|_\infty
	\Bigg\}
	\le
	k^{O(1)}
	\textup{\textsf{err}}_v\,.
	\]
Combining with the result of 
Lemma~\ref{l:marginal.error} gives
(cf.\ \eqref{e:marginal.error.P.to.S})
	\[
	\max_{\bm{L}}\Bigg\{\Bigg|
	\frac{(S_e)^j(\tau\,|\,\bm{L})}
		{(P_e)^j(\tau\,|\,\bm{L})}-1
	\Bigg|\Bigg\}
	\le \frac{k^{O(1)}\textup{\textsf{err}}_v}{2^{k\zeta}}\,.
	\]
The error between $S_e$ and $Q_e$ is bounded by
(cf.\ \eqref{e:S.Q.error} and \eqref{e:marginal.error.S.to.Q})
	\begin{align*}
	\max_{\bm{L}}\Bigg\{
	\Bigg|
	\frac{Q_e(\sigma\,|\,\bm{L})}{S_e(\sigma\,|\,\bm{L})}-1
	\Bigg|\Bigg\}
	&\le 
	k^{O(1)} \Bigg(
	\textup{\textsf{err}}_v
	+\Ind{\SSPIN{r}[\sigma]\ge1}
	\bigg(
	\dot{\epsilon}_e+
	\frac{\min\set{\ddot{\epsilon}_e,1}}{2^{k\zeta}}
	\bigg)\Bigg\} \\
	\max_{\bm{L}}\Bigg\{\Bigg|
	\frac{(Q_e)^j(\tau\,|\,\bm{L})}
		{(S_e)^j(\tau\,|\,\bm{L})}-1
	\Bigg|\Bigg\}
	&\le k^{O(1)}\Bigg( 
	\epsilon_e 
	+\frac1{(2^k)^{\Ind{\tau\ne\SSPIN{r}}}}
	\bigg\{ \dot{\epsilon}_e
	+ \frac{\min\set{\ddot{\epsilon}_e,1}}{2^{k\zeta}}
	\bigg\}\Bigg)\,.
	\end{align*}
Combining these bounds gives the claim \eqref{e:ctypes.varupdate.OUTMSG}.
\end{proof}

Recalling the notation of Definition~\ref{d:rel.error.notation.w.types},
assume that for all $e\in\delta v$ we have (cf.\ \eqref{e:condition.on.hat.messages})
	\begin{equation}\label{e:condition.on.hat.msg.with.L}
	\widehat{\textup{\textbf{\textsf{ERR}}}}(
		{}_{*}\hat{Q}_e
		,\hat{p}_e)
	\le	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	2^{-k} \\ 1 \\ 2^k
	\end{pmatrix}\,.\end{equation}

For the variable weights that do depend on the clause types, assume that 
	\begin{equation}\label{e:bound.edge.weights.cond.on.L}
	\widehat{\textup{\textbf{\textsf{ERR}}}}({}_\star\hspace{-1pt}\psi_e,\phi_e)
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix} 2^{-k} \\ 1 \\ 2^k
	\end{pmatrix}\end{equation}
for ${}_\star\hspace{-1pt}\psi_e$ as defined by
\eqref{e:psistar.joint.defn}.

Since the proof is somewhat involved, we divide it into a few numbered parts. We again recall from
 \eqref{e:augmented.model.factors}
that $\varphi_v(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})$
denotes the indicator of a valid augmented pair coloring of $\delta v$. It can be expressed as
	\[
	\varphi_v(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	= \varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e\in\delta v}
	\Ind{\bm{L}_e\ni \bm{t}_e}\,,
	\]
where $\varphi_v(\smash{\vec{\sigma}}_{\delta v})$ is the indicator of a valid pair coloring on $\delta v$ (not augmented with clause types) as defined in \eqref{e:color.model.variable.factor};
and we write $\bm{L}\ni\bm{t}$ to indicate that $\bm{L}_j=\bm{t}$ for $j=j(\bm{t})$.\smallskip



\noindent
\bemph{\hypertarget{p:ctypes.varupdate.ITERATIVE.CONSTRUCTION}{Part~1}. Iterative construction of $\Psi_v$.}
We first give an iterative definition for a sequence of weights $\Psi_{v,t}$ ($t\ge0$),
all of the functional form \eqref{e:non.compound.weight.functional.form}.
We emphasize that this index $t$ is \bemph{purely local to the proof of this proposition}, and is not the same as the $t$ that indexes the up-and-down passes in
Definition~\ref{d:lagrange.defn.Augmented}. 
We will show in the remainder of the proof that this sequence converges as $t\to\infty$ to the desired weights $\Psi_v=\Psi_{v,\infty}$. Initialize $\Psi_{v,0}\equiv\Phi_v$. For each $t\ge0$, we will update from $\Psi_{v,t}$ to $\Psi_{v,t+1}$ in three stages, summarized by the following table:
	\begin{equation}\label{e:update.table}
	\begin{array}{c|ccc}
	& \psi_v(\smash{\vec{\sigma}}_{\delta v}) 
	& (\psi_e)^j(\sigma^j\,|\,\bm{L})
	& \psi_e(\bm{L}) \\
	\hline
	\Psi_{v,t} & t & t & t \\
	\Psi_{v,t+1/3}	& t+1 & t & t \\
	\Psi_{v,t+2/3}	& t+1 & t+1 & t 
	\end{array}
	\end{equation}
--- e.g., the last row of the table indicates that the weight $\Psi_{v,t+2/3}$ 
is defined by
\eqref{e:non.compound.weight.functional.form}
with the $(t+1)$-versions of 
$\psi_v(\smash{\vec{\sigma}}_{\delta v})$
and $(\psi_e)^j(\sigma^j\,|\,\bm{L})$
(for both $j=1,2$ and all $e\in\delta v$), but with the $t$-version of $\psi_e(\bm{L})$ (again for all $e\in\delta v$). For notational convenience,
we also define $\Psi_t\equiv \Phi$ for all $t<0$, and
	\begin{equation}\label{e:hq.of.t.notation}
	\hat{q}_{e,t}(\sigma,\bm{L})
	\equiv\begin{cases}
	\hat{p}_e(\sigma,\bm{L})
	&\textup{if }t<0\,,\\
	\hat{q}_e(\sigma,\bm{L})
	&\textup{if }t\ge0\,.\\
	\end{cases}
	\end{equation}
We then abbreviate $\nu_t\equiv\nu_{\delta v}[\Psi_{v,t};\hat{q}_t]$, using the notation of \eqref{e:var.tuple.measure.augmented}; in particular this means $\nu_t=\nu_{\delta v}[\Phi;\hat{p}]$ for all $t<0$, while $\nu_0=\nu_{\delta v}[\Phi;\hat{q}]$.
For $t>0$, the weights
of \eqref{e:update.table} are defined by the following procedure (with $t$ denoting an integer time from now on):
\begin{enumerate}[A.]
\item From $t$ to $t+1/3$: 
we will suppose inductively that the measure
$\nu_{t-2/3}$ is judicious on average (in the terminology of Definition~\ref{d:judicious.with.types}).
(For $t=0$, recall that we defined
$\nu_{-2/3}\equiv\nu_{\delta v}[\Phi,\hat{p}]$,
which by hypothesis is fully judicious and therefore also judicious on average.)
 At time $t$ (for $t\ge0$) we have
	\[
	\nu_t(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	= \frac1{\bm{\dot{z}}_{v,t}}
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\psi_{v,t}(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e\in\delta v}
	\Bigg\{
	\Ind{ \bm{L}_e\ni\bm{t}_e }
	\psi_{e,t}(\sigma_e,\bm{L}_e)
	\hat{q}_e(\sigma_e,\bm{L}_e)
	\Bigg\}\,.
	\]
The marginal law of $\smash{\vec{\sigma}}_{\delta v}$ under $\nu_t$ can then be expressed as
	\begin{equation}\label{e:t.avg.no.longer.judicious.on.avg}
	\bar{\nu}_t(\smash{\vec{\sigma}}_{\delta v})
	\cong
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\psi_{v,t}(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e\in\delta v}
	\bar{q}_{e,t}(\sigma_e)\,,
	\end{equation}
where $\bar{q}_{e,t}$ denotes the message at time $t$ averaged over $\bm{L}$:
	\begin{equation}\label{e:defn.avhq.t}
	\bar{q}_{e,t}(\sigma)
	\equiv
	\frac1{\bar{z}_{e,t}}
	\sum_{\bm{L}}
	\Ind{\bm{L}\ni\bm{t}_e}
	\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_{e,t}(\sigma,\bm{L})\,,
	\end{equation}
where $\hat{q}_{e,t}$ is defined by \eqref{e:hq.of.t.notation}. Since we also defined $\psi_{e,t}\equiv\phi_e$ for negative $t$, this means that $\bar{q}_{e,t}(\sigma_e)$ is also well-defined for negative $t$. For instance, the marginal law of $\smash{\vec{\sigma}}_{\delta v}$ at time 
$t-2/3$ is
	\begin{equation}\label{e:t.minus.two.thirds.avg}
	\bar{\nu}_{t-2/3}(\smash{\vec{\sigma}}_{\delta v})
	\cong
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\psi_{v,t}(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e\in\delta v}
	\bar{q}_{e,t-1}(\sigma_e)\,,
	\end{equation}
including in the case $t=0$. Now, from the inductive assumption, $\nu_{t-2/3}$ is judicious on average, which means that the measure
$\bar{\nu}_{t-2/3}$ in
\eqref{e:t.minus.two.thirds.avg}
is judicious in the sense of Definition~\ref{d:constrained.opt.compound.enclosure}.
Comparing \eqref{e:t.avg.no.longer.judicious.on.avg} with \eqref{e:t.minus.two.thirds.avg},
we see that we can
apply Proposition~\ref{p:var.update}
--- with the variable weight function $\psi_{v,t}(\smash{\vec{\sigma}}_{\delta v})$
and the two sets of incoming messages
$\bar{q}_{e,t-1}$ and $\bar{q}_{e,t}$
--- to define a new variable weight function $\psi_{v,t+1}(\smash{\vec{\sigma}}_{\delta v})$ such that the measure
	\[
	\bar{\nu}_{t+1/3}(\smash{\vec{\sigma}}_{\delta v})
	\cong
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\psi_{v,t+1}(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e\in\delta v}
	\bar{q}_{e,t}(\sigma_e)
	\]
is judicious in the sense of Definition~\ref{d:constrained.opt.compound.enclosure},
i.e., such that $\nu_{t+1/3}$ is judicious on average.
Note that, since $t+1/3=(t+1)-2/3$,
this verifies the inductive assumption that
$\nu_{t-2/3}$ is judicious on average.

\item From $t+1/3$ to $t+2/3$:
for all $e\in\delta v$ and both $j=1,2$, update
	\begin{equation}\label{e:cond.judicious.update}
	\frac{(\psi_{e,t+1})^j
		(\tau\,|\,\bm{L})}
		{(\psi_{e,t})^j(
		\tau\,|\,\bm{L})}
	=
	\frac{{}_\star\hspace{-1pt}\pi_e(\tau)}
		{ (\nu_{e,t+1/3})^j(\tau\,|\,\bm{L}) }
	\end{equation}
for all $\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$.

\item From $t+2/3$ to $t+1$: for all $e\in\delta v$ and both $j=1,2$, update 
	\begin{equation}\label{e:clause.frac.update}
	\frac{\psi_{e,t+1}(\bm{L})}{\psi_{e,t}(\bm{L})}
	= \frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
		{ \nu_{e,t+2/3}
		(\bm{L}_e) }\,,
	\end{equation}
using the notation from \eqref{e:pi.DD.first.appearance}.
\end{enumerate}
The rest of the proof is devoted to the analysis of this iterative procedure. For the calculations that follow, it is useful to note that if $\bm{L}\not\ni\bm{t}_e$, then we must have $\psi_{e,t}(\bm{L})=0$ for all $t$. 
\smallskip

\noindent\bemph{\hypertarget{p:ctypes.varupdate.ERROR.NOTATIONS}{Part~2}. Error notations.}
In the proof we will track the following error quantities for all times $t$. Let $\kappa$ measure the deviation from being conditionally judicious:
for $e\in\delta v$, $j=1,2$, 
and $\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$, let
	\begin{equation}\label{e:defn.cdel.kappa}
	(\kappa_{e,t})^j(\tau\,|\,\bm{L})
	\equiv
	\frac{(\nu_{e,t})^j
	( \tau\,|\,\bm{L}) }{{}_\star\hspace{-1pt}\pi_e(\tau)}
	-1\,.\end{equation}
Taking the marginal over $\bm{L}$ gives
	\begin{align*}
	(\nu_{e,t})^j(\tau)
	&= \sum_{\bm{L}}
	\nu_{e,t}(\bm{L})
	\cdot
	(\nu_{e,t})^j
		( \tau\,|\,\bm{L})
	= \sum_{\bm{L}}
	\nu_{e,t}(\bm{L})
	{}_\star\hspace{-1pt}\pi_e(\tau)
	\Bigg\{ 1 + 
	(\kappa_{e,t})^j
		(\tau\,|\,\bm{L})
	\Bigg\}\\
	&=
	{}_\star\hspace{-1pt}\pi_e(\tau)
	\Bigg\{
	1 + 
	\underbrace{\bigg[\sum_{\bm{L}}
	\nu_{e,t}(\bm{L})
	\cdot (\kappa_{e,t})^j(\tau\,|\,\bm{L})
	\bigg]}_{\textup{denote this }
	(\chi_{e,t})^j(\tau)}
	\Bigg\}\,.
	\end{align*}
Notice also that since ${}_\star\hspace{-1pt}\pi_e$
and $(\nu_{e,t})^j(\cdot\,|\,\bm{L})$
are both probability measures over $\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$, we must have
	\begin{equation}\label{e:cdel.avg.to.zero}
	\sum_\tau
	{}_\star\hspace{-1pt}\pi_e(\tau)
	(\kappa_{e,t})^j(\tau\,|\,\bm{L})
	=0
	=\sum_\tau
	{}_\star\hspace{-1pt}\pi_e(\tau)
	(\chi_{e,t})^j(\tau)\,.
	\end{equation}
Next let $\rho$ measure the deviations in the clause proportions: for $e\in\delta v$,
	\begin{equation}\label{e:fdel.defn}
	\rho_{e,t}(\bm{L})
	\equiv
	\frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
	{\nu_{e,t}(\bm{L})}-1\,.\end{equation}
Next, recall the definition \eqref{e:prod.hQ.with.L} of ${}_{*}\hat{Q}_e(\sigma,\bm{L})$, and let
	\begin{equation}\label{e:alpha.e.t.defn}
	\alpha_{e,t}(\sigma,\bm{L})
	\equiv
	\frac{\psi_{e,t}(\sigma,\bm{L})\hat{q}_e(\sigma,\bm{L})}
	{ \psi_{e,0}(\sigma,\bm{L}) {}_{*}\hat{Q}_e(\sigma,\bm{L}) }
	-1
	=\frac{\psi_{e,t}(\sigma,\bm{L})\hat{q}_e(\sigma,\bm{L})}
	{ {}_\star\hspace{-1pt}\psi_e(\bm{L}) {}_{*}\hat{q}_e(\sigma) /\hat{Z}_e}
	-1\,.\end{equation}
Lastly, let $\xi$ measure the deviation from being a product measure: for $e\in\delta v$,
	\[
	\xi_{e,t}(\sigma\,|\,\bm{L})
	\equiv
	\frac{\nu_{e,t}(\sigma\,|\,\bm{L})}
		{{}_{*}\omega_e(\sigma)}-1
	\]
We will also make some shorthand notation for the maximum absolute values of the above quantities: let
	\begin{equation}\label{e:cdel.max.notation}
	\kappa_{e,t}(\tau)
	\equiv
	\max_{\bm{L},j}\Bigg\{
	\Big|(\kappa_{e,t})^j(\tau\,|\,\bm{L})\Big|
	\Bigg\}
	\,,\quad
	\begin{pmatrix}
	\kappa_{e,t}\\
	\dot{\kappa}_{e,t}
	\end{pmatrix}
	\equiv\begin{pmatrix}
	\max\set{\kappa_{e,t}(\tau):\tau\ne\SSPIN{r}}\\
	\kappa_{e,t}(\SSPIN{r})
	\end{pmatrix}\,,\end{equation}
and let $\rho_{e,t}
\equiv \max_{\bm{L}}\set{|\rho_{e,t}(\bm{L})|}$.
Finally let
	\begin{equation}\label{e:he.max.notation}
	\alpha_{e,t}(\sigma)
	\equiv
	\max_{\bm{L}}\Bigg\{
		\Big|\alpha_{e,t}(\sigma\,|\,\bm{L})\Big|
			\Bigg\}
	\,,\quad
	\begin{pmatrix}
	\alpha_{e,t}\\
	\dot{\alpha}_{e,t}\\
	\ddot{\alpha}_{e,t}
	\end{pmatrix}
	=\begin{pmatrix}
	\max\set{\alpha_{e,t}(\sigma) : \SSPIN{r}[\sigma]=0}\\
	\max\set{\alpha_{e,t}(\sigma) : \SSPIN{r}[\sigma]=1}\\
	\max\set{\alpha_{e,t}(\sigma) : \SSPIN{r}[\sigma]=2}
	\end{pmatrix}\,,
	\end{equation}
and make the analogous notation with $\xi$ in place of $\alpha$.
We will show by induction that for all $e\in\delta v$,
	\begin{equation}\label{e:rough.inductive.bounds.forall.t}
	\sum_{t\in\mathbb{Z}/3,t\ge1/3}
	\begin{pmatrix}
	\rho_{e,t}+\kappa_{e,t} + \alpha_{e,t}
		\\
	\dot{\kappa}_{e,t}+\dot{\alpha}_{e,t}
		+\xi_{e,t}
		+ \dot{\xi}_{e,t}\\
	\ddot{\alpha}_{e,t}
		+\ddot{\xi}_{e,t}
	\end{pmatrix}
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix} 2^{-k} \\ 1 
		\\ 2^k \end{pmatrix}\end{equation}
for all $t\ge 1/3$. We also record a calculation that we will use repeatedly in what follows: for any integer $t$, at time $t+1/3$, according to the table \eqref{e:update.table} we have
	\[
	\nu_{t+1/3}(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	\cong
	\varphi_v(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	\psi_{v,t+1}(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e\in\delta v}\Bigg\{
	\psi_{e,t}(\sigma_e,\bm{L}_e)
	\hat{q}_{e,t}(\sigma_e,\bm{L}_e)\Bigg\}\,,
	\]
where we recall that $\hat{q}_{e,t}$ is defined by \eqref{e:hq.of.t.notation} for all $t$.
From this it is straightforward to verify that the marginal on an edge $e\in\delta v$ is given by
\begin{equation}\label{e:first.defn.of.u}
	\nu_{e,t+1/3}(\sigma,\bm{L})
	=\frac1{\bm{\bar{z}}_{e,t+1/3}}
	\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_{e,t}(\sigma,\bm{L})
	\overbrace{\Bigg[
	\frac1{\dot{z}_{e,t+1/3}}
	\sum_{\smash{\vec{\sigma}}_{\delta v\setminus e}}
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\psi_{v,t+1}(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e'}
	\bar{q}_{e,t}(\sigma_{e'})
	\Bigg]}^{\textup{denote this }u_{e,t+1/3}(\sigma)}
	\end{equation}
where $\dot{z}_{e,t+1/3}$ is the normalizing constant that makes $u_{e,t+1/3}$ a probability measure over $\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$, and $\bm{\bar{z}}_{e,t+1/3}$ is the normalizing constant that makes $\nu_{e,t+1/3}$ a probability measure over pairs $(\sigma,\bm{L})$. For integers $t$ we will compare the following measures:
	\begin{align}\nonumber
	\bm{\bar{z}}_{e,t-2/3}\nu_{e,t-2/3}(\sigma,\bm{L})
	&=\hat{q}_{e,t-1}(\sigma,\bm{L})
		\psi_{e,t-1}(\bm{L})
		\psi_{e,t-1}(\sigma\,|\,\bm{L})
		u_{e,t-2/3}(\sigma,\bm{L})\,,\\
	\nonumber
	\bm{\bar{z}}_{e,t-1/3}\nu_{e,t-1/3}(\sigma,\bm{L})
	&=\hat{q}_{e,t-1}(\sigma,\bm{L})
		\psi_{e,t-1}(\bm{L})
		\psi_{e,t}(\sigma\,|\,\bm{L})
		u_{e,t-1/3}(\sigma,\bm{L})\,,\\
	\nonumber
	\bm{\bar{z}}_{e\bullet,t}
		\nu_{e\bullet,t}(\sigma,\bm{L})
	&=\hat{q}_{e,t}(\sigma,\bm{L})
		\psi_{e,t}(\bm{L})
		\psi_{e,t}(\sigma\,|\,\bm{L})
		u_{e,t-2/3}(\sigma,\bm{L})\,,\\
	\nonumber
	\bm{\bar{z}}_{e,t}\nu_{e,t}(\sigma,\bm{L})
	&=\hat{q}_{e,t}(\sigma,\bm{L})
		\psi_{e,t}(\bm{L})
		\psi_{e,t}(\sigma\,|\,\bm{L})
		u_{e,t}(\sigma,\bm{L})\,,\\
	\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\sigma,\bm{L})
	&=\hat{q}_{e,t}(\sigma,\bm{L})
		\psi_{e,t}(\bm{L})
		\psi_{e,t}(\sigma\,|\,\bm{L})
		u_{e,t+1/3}(\sigma,\bm{L})\,.
	\label{e:table.of.all.measures}
	\end{align}
The remaining parts of the proof are organized as follows:
\begin{enumerate}[--]
\item
\hyperlink{p:ctypes.varupdate.PRELIM.BOUNDS}{Part~3a}
proves some preliminary bounds.

\item 
\hyperlink{p:ctypes.varupdate.UPDATE.A.GENERAL}{Part~3b} controls $\nu_{e,t+1/3}$ 
in terms of $\nu_{e\bullet,t}$ 
for integers $t\ge0$, in the bounds \eqref{e:fdel.bounds.from.update.A}~and~\eqref{e:cdel.bounds.from.update.A}.
The bounds also depend on the error $\vec{\epsilon}(t)$ (see \eqref{e:update.A.def.epsilon})
between
$\bar{q}_{e,t-2/3}$ and $\bar{q}_{e,t}$.

\item
\hyperlink{p:ctypes.varupdate.UPDATE.B.MSG}{Part~4a} 
controls 
 $\bar{q}_{e,t-1/3}$ in terms of
 $\nu_{e,t-2/3}$ and $\bar{q}_{e,t-2/3}$,
in the bound \eqref{e:ctypes.one.two.crelerr}.

\item
\hyperlink{p:ctypes.varupdate.UPDATE.C.MSG}{Part~4b} controls
$\bar{q}_{e,t}$ in terms of
$\nu_{e,t-1/3}$ and $\bar{q}_{e,t-1/3}$,
in the bound \eqref{e:error.in.avhq.from.update.C}.
\item \hyperlink{p:ctypes.varupdate.UPDATE.B.MGL}{Part~5a} controls
	$\nu_{e,t-1/3}$
	in terms of $\nu_{e,t-2/3}$
	 for integers $t\ge1$
	 (in the bounds \eqref{e:one.to.two.thirds.clause}
and \eqref{e:ctypes.one.two.cond}).
\item \hyperlink{p:ctypes.varupdate.UPDATE.C.MGL}{Part~5b} compares
	$\nu_{e,t-1/3}$
	with $\nu_{e\bullet,t}$
	and $\nu_{e,t}$ for integers $t\ge1$
	(in the bounds \eqref{e:update.C.single.edge}
and \eqref{e:update.C.single.edge.back.to.bullet}).

\item 
\hyperlink{p:ctypes.varupdate.CONCLUSION}{Part~6} 
combines the results of the preceding parts to show that the iteration of Part~1 converges to the desired weights $\Psi_v\equiv\Psi_{v,\infty}$, and moreover that these weights satisfy the claimed bounds
\eqref{e:defn.of.err.v.notation}~and~\eqref{e:ctypes.varupdate.MAINBOUND}.

\item \hyperlink{p:ctypes.varupdate.OUTMSG}{Part~7}
shows that the messages outgoing from the variable
satisfy the claimed bound
\eqref{e:ctypes.varupdate.OUTMSG}, thereby concluding the proof.


\end{enumerate}\smallskip


\noindent\bemph{\hypertarget{p:ctypes.varupdate.PRELIM.BOUNDS}{Part~3a}. Preliminary bounds.} Recall the definition \eqref{e:alpha.e.t.defn}
of $\alpha_{e,t}$, and observe that
$\alpha_{e,1/3}=\alpha_{e,0}$. It follows from the assumptions 
\eqref{e:condition.on.hat.msg.with.L} and
\eqref{e:bound.edge.weights.cond.on.L} that
	\[
	\Big|\alpha_{e,1/3}(\sigma,\bm{L})\Big|
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{cases}
	2^{-k} & \textup{if $\SSPIN{r}[\sigma]=0$,}\\
	1 & \textup{if $\SSPIN{r}[\sigma]=1$,}\\
	2^k & \textup{if $\SSPIN{r}[\sigma]=2$,}\\
	\end{cases}\]
which verifies that 
$\alpha_{e,1/3}(\sigma)$
 satisfies the bound from \eqref{e:rough.inductive.bounds.forall.t}.
The marginal on $\bm{L}$ at time $t=1/3$ satisfies
	\begin{align}\nonumber
	\nu_{e,1/3}(\bm{L})
	&\stackrel{\eqref{e:first.defn.of.u}}{=}
	\frac1{\bm{\bar{z}}_{e,1/3}} \sum_\sigma
		\phi_e(\sigma,\bm{L})
		\hat{q}_e(\sigma,\bm{L})
		u_{e,1/3}(\sigma)
	\\
	&\stackrel{\eqref{e:alpha.e.t.defn}}{=}
	\frac{{}_\star\hspace{-1pt}\psi_e(\bm{L})}{\bm{\bar{z}}_{e,1/3}
		\hat{Z}_e}
	\sum_\sigma
	{}_{*}\hat{q}_e(\sigma)
	\Bigg(1+\alpha_e(\sigma,\bm{L})\Bigg)
	u_{e,1/3}(\sigma)
	= {}_\star\hspace{-1pt}\psi_e(\bm{L})
	\Bigg\{ 1 + \frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\}\,,
	\label{e:prod.of.zs.is.close.to.one}
	\end{align}
which proves that $\rho_{e,1/3}$
also satisfies the bound
from \eqref{e:rough.inductive.bounds.forall.t}.
Next, the marginal on $\sigma$ at time $t=1/3$ is given by
	\begin{equation}\label{e:one.third.on.sigma}
	\nu_{e,1/3}(\sigma)
	= \frac{\bar{z}_{e,1/3}}{\bm{\bar{z}}_{e,1/3}}
	\overbrace{\Bigg[
	\frac1{\bar{z}_{e,1/3}}
	\sum_{\bm{L}}
	\Ind{\bm{L}\ni\bm{t}_e}
	\phi_e(\sigma,\bm{L})\hat{q}_e(\sigma,\bm{L})
	\Bigg]}^{\bar{q}_{e,0}(\sigma)
		=\bar{q}_{e,1/3}(\sigma)}
	u_{e,1/3}(\sigma)\,,
	\end{equation}
where we recall that $\bar{q}_{e,t}$ is defined by
 \eqref{e:defn.avhq.t}. It follows from 
the assumptions \eqref{e:condition.on.hat.msg.with.L} and \eqref{e:bound.edge.weights.cond.on.L}
that
	\begin{equation}\label{e:avhq.rel.err.rough.bound.BASECASE}
	\widehat{\textup{\textsf{\footnotesize ERR}}}({}_{*}\hat{q}_e,\bar{q}_{e,1/3})
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix} 2^{-k} \\ 1 \\ 2^k
		\end{pmatrix}\,.
	\end{equation}
Substituting
\eqref{e:avhq.rel.err.rough.bound.BASECASE}
into \eqref{e:one.third.on.sigma}
shows that $\nu_{e,1/3}(\sigma)$
is very close to the 
normalization of the 
measure
${}_{*}\hat{q}_e(\sigma) u_{e,1/3}(\sigma)$.
On the other hand, the same must be true for the conditional measure $\nu_{e,1/3}(\sigma\,|\,\bm{L})$, since
	\begin{align*}
	\nu_{e,1/3}(\sigma\,|\,\bm{L})
	&\stackrel{\eqref{e:first.defn.of.u}}{=}
	\frac{
	\phi_e(\sigma,\bm{L})\hat{q}_e(\sigma,\bm{L}) u_{e,1/3}(\sigma) }
	{ \bm{\bar{z}}_{e,1/3}\nu_{e,1/3}(\bm{L})}
	\stackrel{\eqref{e:alpha.e.t.defn}}{=}
	\frac{{}_\star\hspace{-1pt}\psi_e(\bm{L})
	{}_{*}\hat{q}_e(\sigma)
	u_{e,1/3}(\sigma)}{ \bm{\bar{z}}_{e,1/3} \hat{Z}_e
	\nu_{e,1/3}(\bm{L})}
	\Bigg\{ 1 + \alpha_e(\sigma,\bm{L})\Bigg\}\\
	&\stackrel{\eqref{e:prod.of.zs.is.close.to.one}}
		{=}
	{}_\star\hspace{-1pt}\psi_e(\bm{L})
	{}_{*}\hat{q}_e(\sigma)
	u_{e,1/3}(\sigma)
	\Bigg\{ 1 + \alpha_e(\sigma,\bm{L})\Bigg\}
	\Bigg\{ 1 + \frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\}\,.
	\end{align*}
Thus, by comparing both $\nu_{e,1/3}(\sigma)$
and $\nu_{e,1/3}(\sigma\,|\,\bm{L})$
with the normalization of
${}_{*}\hat{q}_e(\sigma)u_{e,1/3}(\sigma)$, we deduce that
	\begin{equation}\label{e:conditional.vs.avg.error.BASECASE}
	\Bigg|
	\frac{\nu_{e,1/3}(\sigma\,|\,\bm{L})}
		{\nu_{e,1/3}(\sigma)}-1\Bigg|
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\begin{cases}
	2^{-k} & \textup{if $\SSPIN{r}[\sigma]=0$,}\\
	1 & \textup{if $\SSPIN{r}[\sigma]=1$,}\\
	2^k & \textup{if $\SSPIN{r}[\sigma]=2$.}\\
	\end{cases}\end{equation}
Since the measure
$\nu_{e,1/3}$ is judicious by construction, 
this implies that $\kappa_{e,1/3}(\tau)$
satisfies the bounds from \eqref{e:rough.inductive.bounds.forall.t}. 
Finally, we note that the variable \textsc{bp} recursion
together with \eqref{e:avhq.rel.err.rough.bound.BASECASE} implies
	\[\Bigg|
	\frac{u_{e,1/3}(\sigma)}
		{{}_{*}\dot{q}_e(\sigma)}-1\Bigg|
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\]
for all $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$. Combining this with \eqref{e:condition.on.hat.msg.with.L}
and \eqref{e:bound.edge.weights.cond.on.L} gives
	\[
	\Bigg|
	\frac{\nu_{e,1/3}(\sigma\,|\,\bm{L})}
		{{}_{*}\omega_e(\sigma)
		}-1\Bigg|\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\times
	\begin{cases}
	1& \textup{if $\SSPIN{r}[\sigma]\le1$,}\\
	2^k & \textup{if $\SSPIN{r}[\sigma]=2$.}\\
	\end{cases}
	\]
This implies that $\xi_{e,1/3}(\sigma)$ satisfy the bounds from \eqref{e:rough.inductive.bounds.forall.t}.
Thus we have proved \eqref{e:rough.inductive.bounds.forall.t}
for the case $t=1/3$. We note for later use that
the inductive hypothesis \eqref{e:rough.inductive.bounds.forall.t} 
implies that \eqref{e:avhq.rel.err.rough.bound.BASECASE} and \eqref{e:conditional.vs.avg.error.BASECASE}
hold more generally:
	\begin{equation}\label{e:avhq.rel.err.rough.bound}
	\widehat{\textup{\textsf{\footnotesize ERR}}}({}_{*}\hat{q}_e,\bar{q}_{e,t})
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix} 2^{-k} \\ 1 \\ 2^k
		\end{pmatrix}
	\end{equation}
for all $t\ge1/3$, and likewise
	\begin{equation}\label{e:conditional.vs.avg.error}
	\Bigg|
	\frac{\nu_{e,t}(\sigma\,|\,\bm{L})}
		{\nu_{e,t}(\sigma)}-1\Bigg|
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\begin{cases}
	2^{-k} & \textup{if $\SSPIN{r}[\sigma]=0$,}\\
	1 & \textup{if $\SSPIN{r}[\sigma]=1$,}\\
	2^k & \textup{if $\SSPIN{r}[\sigma]=2$}\\
	\end{cases}\end{equation}
for all $t\ge1/3$.\smallskip 

\noindent\bemph{\hypertarget{p:ctypes.varupdate.UPDATE.A.GENERAL}{Part~3b}. Analysis of general applications of update A.} We next analyze the update from $t-2/3$ to $t+1/3$ for integer times $t\ge0$. 
At times $t-2/3$ and $t+1/3$ we have
(cf.\ \eqref{e:first.defn.of.u},
and using the notation from \eqref{e:hq.of.t.notation})
	\begin{align}\nonumber
	\bm{\bar{z}}_{e,t-2/3}
	\nu_{e,t-2/3}(\sigma,\bm{L})
	&= 
	\psi_{e,t-1}(\sigma,\bm{L})
	\hat{q}_{e,t-1}(\sigma,\bm{L})
	\overbrace{\Bigg[
	\frac1{\dot{z}_{e,t-2/3}}
	\sum_{\smash{\vec{\sigma}}_{\delta v\setminus e}}
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\psi_{v,t}(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e'\in\delta v\setminus e}
	\bar{q}_{e',t-1}(\sigma_{e'})
	\Bigg]}^{u_{e,t-2/3}(\sigma) }\,,\\
	\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\sigma,\bm{L})
	&= 
	\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_{e,t}(\sigma,\bm{L})
	\underbrace{\Bigg[
	\frac1{\dot{z}_{e,t+1/3}}
	\sum_{\smash{\vec{\sigma}}_{\delta v\setminus e}}
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\psi_{v,t+1}(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e'\in\delta v\setminus e}
	\bar{q}_{e',t}(\sigma_{e'})
	\Bigg]}_{u_{e,t+1/3}(\sigma) }\,.
	\label{e:compare.tplusthird.to.tminustwothirds}
	\end{align}
We then estimate the error between $u_{e,t-2/3}$ and $u_{e,t+1/3}$. Recall the notation of Definition~\ref{d:clause.rel.error}, and let 
	\begin{equation}\label{e:update.A.def.epsilon}
	\vec{\epsilon}(t)
	\equiv\begin{pmatrix}
	\epsilon_e(t)\\
	\dot{\epsilon}_e(t)\\
	\ddot{\epsilon}_e(t)
	\end{pmatrix}
	\equiv
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\bar{q}_{t-2/3},
	\bar{q}_{t-1/3})
	+\widehat{\textup{\textsf{\footnotesize ERR}}}(\bar{q}_{t-1/3},
	\bar{q}_{t})\,.\end{equation}
(Note that $\bar{q}_t=\bar{q}_{t+1/3}$.)
Recall also the notation of Definition~\ref{d:var.rel.error}, and let
	\begin{equation}\label{e:delta.vec.of.t}
	\vec{\delta}(t+1/3)
	\equiv
	\begin{pmatrix}
	\delta_e(t)\\
	\dot{\delta}_e(t+1/3)\\
	\ddot{\delta}_e(t+1/3)\\
	{}^\textup{m}\hspace{-2pt}\delta_e(t+1/3)\\
	{}^\textup{m}\hspace{-2pt}\dot{\delta}_e(t+1/3)
	\end{pmatrix}
	\equiv\dddot{\textup{\textsf{\footnotesize ERR}}}(
	u_{e,t-2/3},
	u_{e,t+1/3})\,.
	\end{equation}
The measure $\nu_{e,t-2/3}$ is judicious on average for all $t\ge0$ (and fully judicious for $t=0$).
It then follows by Corollary~\ref{c:var.update} (whose conditions are satisfied, in view of 
\eqref{e:avhq.rel.err.rough.bound}) that
	\begin{equation}\label{e:vec.delta.bound.with.L}
	\vec{\delta}(t+1/3)
	\le
	k^{O(1)}
	\begin{pmatrix}
	1\\1\\1\\ 2^{-k\zeta} \\2^{-k\zeta}
	\end{pmatrix} \textup{\textsf{err}}_v(t)
	+ k^{O(1)}
	\begin{pmatrix}
	0&0&0\\
	0&1&1\\
	0&1&1\\
	1&2^{-k}&2^{-k}\\
	1&1&1\\
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e(t)\\
	\dot{\epsilon}_e(t)\\
	\min\set{\ddot{\epsilon}_e(t),1}/2^{k\zeta}
	\end{pmatrix}\,,
	\end{equation}
with $\textup{\textsf{err}}_v(t)$ defined analogously to \eqref{e:defn.of.err.v.notation}. Now,
recalling \eqref{e:compare.tplusthird.to.tminustwothirds}, we will consider also an intermediate measure $\nu_{e\bullet,t}$, which we define by
	\begin{equation}\label{e:intermediate.bullet.measure}
	\nu_{e\bullet,t}(\sigma,\bm{L})
	=\frac1{\bm{\bar{z}}_{e\bullet,t}}
		\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_{e,t}(\sigma,\bm{L})
	 u_{e,t-2/3}(\sigma)\,.\end{equation}
Let $\chi_{e\bullet,t}$,
$\kappa_{e\bullet,t}$, etc.\
be defined analogously to the quantities in 
\hyperlink{p:ctypes.varupdate.ERROR.NOTATIONS}{Part~2}
with $\nu_{e\bullet,t}$
in place of $\nu_{e,t}$. 
In this part of the proof we shall abbreviate
(recalling \eqref{e:cdel.max.notation} and \eqref{e:he.max.notation})
	\begin{equation}\label{e:max.time.t.notation}
	\begin{pmatrix}
	\kappa_{e\bullet}(\tau)\\
	\alpha_{e\bullet}(\sigma)
	\end{pmatrix}
	\equiv\begin{pmatrix}
	\max_{\bm{L},j}\set{|(
		\kappa_{e\bullet,t}
		)^j(\tau\,|\,\bm{L})|}\\
	\max_{\bm{L}}\set{|
		\alpha_{e\bullet,t}
		(\sigma\,|\,\bm{L})|}
	\end{pmatrix}\,,
	\end{equation}
Comparing with $\nu_{e,t+1/3}$ gives
	\begin{equation}\label{e:Upsilon.t.in.terms.of.u}
	\gamma_{e,t}(\sigma)
	\equiv
	\frac{\nu_{e,t+1/3}(\sigma,\bm{L})}
	{\nu_{e\bullet,t}(\sigma,\bm{L})} -1
	= 
	\frac{ \bm{\bar{z}}_{e\bullet,t}}{\bm{\bar{z}}_{e,t+1/3}}
	\cdot
	\frac{ u_{e,t+1/3}(\sigma)}
	{ u_{e,t-2/3}(\sigma)} - 1\,,
	\end{equation}
where we emphasize that this error does not depend on $\bm{L}$. As a result, marginally on $\sigma$ we also have
	\begin{equation}\label{e:marginal.relation.for.gamma}
	\gamma_{e,t}(\sigma)
	=
	\frac{\nu_{e,t+1/3}(\sigma)}
	{\nu_{e\bullet,t}(\sigma)} -1\,.\end{equation}
Substituting \eqref{e:vec.delta.bound.with.L} into the expression \eqref{e:Upsilon.t.in.terms.of.u} for $\gamma_{e,t}$ gives
	\begin{equation}\label{e:bound.Upsilon.in.terms.of.eps}
	\Big|\gamma_{e,t}(\sigma)\Big|
	\le 
	k^{O(1)}\Bigg\{
	\textup{\textsf{err}}_v(t)
	+ \Ind{\SSPIN{r}[\sigma]\ge1}\Bigg(
	\dot{\epsilon}_e(t)
	+\frac{\min\set{\ddot{\epsilon}_e(t),1}}
		{2^{k\zeta}}
	\Bigg)
	\Bigg\}\,.
	\end{equation}
We then compare the marginal laws of $(\sigma^1,\bm{L})$ 
under $\nu_{e\bullet,t}$ and $\nu_{e,t+1/3}$:
by the definition of $\gamma_{e,t}$, we have
	\begin{align}\nonumber
	&\nu_{e,t+1/3}(\sigma^1,\bm{L})
	-\nu_{e\bullet,t}(\sigma^1,\bm{L})
	=
	\sum_{\sigma^2}
	\nu_{e\bullet,t}(\sigma,\bm{L})
	\gamma_{e,t}(\sigma)\\
	&=
	\nu_{e\bullet,t}(\bm{L})
	{}_\star\hspace{-1pt}\pi_e(\sigma^1)
	\Bigg\{
	\underbrace{
	\Bigg[
	\sum_{\sigma^2}
	\frac{\nu_{e\bullet,t}(\sigma)}
		{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	\gamma_{e,t}(\sigma)
	\Bigg]
	}_{\textup{denote this }
	(X_{e,t})^1(\sigma^1)}
	+
	\underbrace{\Bigg[
	\sum_{\sigma^2}
	\frac{\nu_{e\bullet,t}(\sigma\,|\,\bm{L})
	-\nu_{e\bullet,t}(\sigma)}{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	\gamma_{e,t}(\sigma)
	\Bigg]}_{\textup{denote this }
		(Y_{e,t})^1
		(\sigma^1\,|\,\bm{L} )}
	\Bigg\}\,.
	\label{e:zero.to.one.third.errors}
	\end{align}
We note that the $X$ term
in \eqref{e:zero.to.one.third.errors} can be simplified
using \eqref{e:marginal.relation.for.gamma}
and the fact that $\nu_{e,t+1/3}$ is judicious on average:
	\[
	(X_{e,t})^1(\sigma^1)
	=\sum_{\sigma^2}	
	\frac{
	\nu_{e,t+1/3}(\sigma)
	-\nu_{e\bullet,t}(\sigma)
	}{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	= 1 -
	\frac{(\nu_{e\bullet,t})^1(\sigma^1)
	}{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	=- (\chi_{e\bullet,t})^1(\sigma^1)\,.
	\]
It follows from the definition of $\chi$ that for all $\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$ we have
	\[
	\Big|
	(X_{e,t})^1(\tau)\Big|
	= \Big|
	(\chi_{e\bullet,t})^1(\tau)
	\Big|
	\le
	\max_{\bm{L}}
	\Bigg\{\Big|
	(\kappa_{e\bullet,t})^1(\tau\,|\,\bm{L})
	\Big|\Bigg\}
	=\kappa_{e\bullet}(\tau)\,.
	\]
Summing \eqref{e:zero.to.one.third.errors} over $\sigma^1=\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$
and recalling \eqref{e:cdel.avg.to.zero} gives
	\begin{equation}\label{e:zero.to.one.third.errors.mgl.on.L}
	\nu_{e,t+1/3}(\bm{L})
	-\nu_{e\bullet,t}(\bm{L})
	= \nu_{e\bullet,t}(\bm{L})
	\Bigg\{\sum_{\tau}
	{}_\star\hspace{-1pt}\pi_e(\tau)
	(Y_{e,t})^1(\tau\,|\,\bm{L} )
	\Bigg\}\,.
	\end{equation}
Now, the $Y$ term in \eqref{e:zero.to.one.third.errors} can be bounded as 
	\[\Big|(Y_{e,t})^1
		(\sigma^1\,|\,\bm{L})\Big|
	\le \sum_{\sigma^2}
	\frac{\nu_{e\bullet,t}(\sigma)}{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	\Bigg|
	\frac{\nu_{e\bullet,t}(\sigma\,|\,\bm{L})}
	{\nu_{e\bullet,t}(\sigma)}-1
	\Bigg|
	\gamma_{e,t}(\sigma)\,.\]
It follows from \eqref{e:conditional.vs.avg.error} and \eqref{e:bound.Upsilon.in.terms.of.eps} that 
if $\sigma^1\ne\SSPIN{r}$,
	\[
	\Big|(Y_{e,t})^1
		(\sigma^1\,|\,\bm{L})\Big|
	\le
	\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\bigg(\gamma_{e,t}+\dot{\gamma}_{e,t}
		\bigg)
	\le
	\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\{
	\textup{\textsf{err}}_v(t) + \dot{\epsilon}_e(t)
		+ \frac{\min\set{\dot{\epsilon}_e(t),1}}
			{2^{k\zeta}}
	\Bigg\}\,.
	\]
If $\sigma^1=\SSPIN{r}$ then we recall from
\eqref{e:table.of.all.measures}
 that $\nu_{e\bullet,t}\cong
 \hat{q}_{e,t} \psi_{e,t} u_{e\bullet,t}$,
 from which it follows that
 $\nu_{e\bullet,t}(\SSPIN{r}\SSPIN{r}\,|\,\bm{L}) \le 
 k^{O(1)}/2^{-(1+\zeta)}$. 
It then follows that
	\begin{align*}
	\Big|(Y_{e,t})^1
		(\sigma^1\,|\,\bm{L})\Big|
	&\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\dot{\gamma}_{e,t}
	+O\Bigg(
	\frac{\max_{\bm{L}}\set{
	\nu_{e\bullet,t}(\SSPIN{r}\SSPIN{r}\,|\,\bm{L})}}
	{{}_\star\hspace{-1pt}\pi_e(\SSPIN{r})}
	\ddot{\gamma}_{e,t}
	\Bigg)
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\bigg(
	\dot{\gamma}_{e,t}
	+\ddot{\gamma}_{e,t}\bigg)
	\\
	&\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	\textup{\textsf{err}}_v(t) + \dot{\epsilon}_e(t)
		+ \frac{\min\set{\dot{\epsilon}_e(t),1}}
			{2^{k\zeta}}
	\Bigg\}
	\end{align*}
Substituting these bounds for $Y$ back into
\eqref{e:zero.to.one.third.errors.mgl.on.L} gives, for $t\ge1$, 
	\begin{equation}\label{e:fdel.bounds.from.update.A}
	\rho_{e,t+1/3}
	= \max_{\bm{L}}\Bigg\{ \Big|
	\rho_{e,t+1/3}(\bm{L})\Big|\Bigg\}
	\le 
	\rho_{e\bullet,t}
	+\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\{
	\textup{\textsf{err}}_v(t) + \dot{\epsilon}_e(t)
		+ \frac{\min\set{\dot{\epsilon}_e(t),1}}
			{2^{k\zeta}}
	\Bigg\}\,.
	\end{equation}
Substituting the bounds for $X$ and $Y$ back into \eqref{e:zero.to.one.third.errors},
and combining with \eqref{e:zero.to.one.third.errors.mgl.on.L}, gives
	\begin{align}
	\nonumber
	\kappa_{e,t+1/3}
	&\le 
	\rho_{e\bullet,t}
	+\kappa_{e\bullet,t}
	+\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\{
	 \textup{\textsf{err}}_v(t)+\dot{\epsilon}_e(t)
	+\frac{\min\set{\ddot{\epsilon}_e(t),1}}
		{2^{k\zeta}}
	\Bigg\}\,,\\
	\dot{\kappa}_{e,t+1/3}
	&\le
	\rho_{e\bullet,t}
	+\dot{\kappa}_{e\bullet,t}+
	\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	 \textup{\textsf{err}}_v(t)
	+\dot{\epsilon}_e(t)
	+\frac{\min\set{\ddot{\epsilon}_e(t),1}}
		{2^{k\zeta}}
	\Bigg\}\,.
	\label{e:cdel.bounds.from.update.A}
	\end{align}
for all $t\ge0$.
We next turn to the question of bounding $\vec{\epsilon}(t)$ (as defined by \eqref{e:update.A.def.epsilon}) for $t\ge1$.\smallskip



\noindent\bemph{\hypertarget{p:ctypes.varupdate.UPDATE.B.MSG}{Part~4a}. Errors in averaged messages incurred by update B.} We now estimate the error between the averaged messages 
$\bar{q}_{e,t+1/3}$ and $\bar{q}_{e,t+2/3}$ for $t\ge0$. Between times $t+1/3$ and $t+2/3$ we only make the update
\eqref{e:cond.judicious.update}. In this part of the proof we will fix $e\in\delta v$ and abbreviate
(recalling
\eqref{e:cdel.max.notation} and \eqref{e:he.max.notation})
	\[
	\begin{pmatrix}
	\kappa_e(\tau) \\ \alpha_e(\sigma)
	\end{pmatrix}
	\equiv
	\begin{pmatrix}
	\kappa_{e,t+1/3}(\tau) \\ 
	\alpha_{e,t+1/3}(\sigma)
	\end{pmatrix}
	=\begin{pmatrix}
	\kappa_{e,t+1/3}(\tau) \\ 
	\alpha_{e,t}(\sigma)
	\end{pmatrix}
	\,.
	\]
By the definition
\eqref{e:defn.cdel.kappa} of $\kappa$, it holds for all $\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$ that
	\begin{equation}\label{e:orth}
	0=
	\sum_{\bm{L}}\nu_{e,t+1/3}(\bm{L})
	\Bigg\{
	(\nu_{e,t+1/3})^j(\tau\,|\,\bm{L})
	-{}_\star\hspace{-1pt}\pi_e(\tau)\Bigg\}
	=\sum_{\bm{L}}\nu_{e,t+1/3}(\bm{L})
	{}_\star\hspace{-1pt}\pi_e(\tau)
	(\kappa_{e,t+1/3})^j(\tau\,|\,\bm{L})\,,
	\end{equation}
where the first equality holds because $\nu_{e,t+1/3}$ is judicious on average. We now turn to comparing the messages. At time $t+1/3$ we have
$\bar{q}_{e,t+1/3}=\bar{q}_{e,t}$, defined by
 \eqref{e:defn.avhq.t}. More explicitly, it follows using
\eqref{e:first.defn.of.u} that
	\begin{equation}\label{e:relation.of.normalizing.constants}
	\bar{z}_{e,t}\bar{q}_{e,t}(\sigma)
	=\sum_{\bm{L}}
	\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})
	= \frac{\bm{\bar{z}}_{e,t+1/3}
		\nu_{e,t+1/3}(\sigma)
		}{u_{e,t+1/3}(\sigma)}
	\,,\end{equation}
On the other hand, at time $t+2/3$ we have (by Taylor expansion)
	\begin{align}\nonumber
	&\bar{z}_{e,t+2/3}\bar{q}_{e,t+2/3}(\sigma)
	=\sum_{\bm{L}}
	\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})
	\prod_{j=1,2}
	\frac1{1 +( \kappa_{e,t+1/3})^j(\sigma^j\,|\,\bm{L})
	}\\
	&\qquad
	=\bar{z}_{e,t}
	\Bigg\{
	\bar{q}_{e,t}(\sigma)
	\bigg\{
	1 + O \bigg(
		\sum_{j=1,2} \kappa_e(\sigma^j)^2
			\bigg)
	\bigg\}
	-\sum_{j=1,2}
	\underbrace{\Bigg[
	\sum_{\bm{L}}
	\frac{\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})}{\bar{z}_{e,t}}
	( \kappa_{e,t+1/3})^j(\sigma^j\,|\,\bm{L})
	\Bigg]}_{\textup{denote this }K^j(\sigma)}
	\Bigg\}
	\label{e:K.j.defn}
	\end{align} 
From the definition of $K^j(\sigma)$ we can easily deduce the bound 
	\begin{equation}\label{e:first.bound.K.j}
	\Big|K^j(\sigma)\Big|
	\le 
	O\Bigg(
	\frac{\kappa_e(\sigma^j)}{\bar{z}_{e,t}\hat{Z}_e}
	\bar{q}_{e,t}(\sigma)
	\sum_{\bm{L}} {}_\star\hspace{-1pt}\psi_e(\bm{L})
	\Bigg)
	= O\bigg(
	\bar{q}_{e,t}(\sigma)
	\cdot \kappa_e(\sigma^j) \bigg)\,,\end{equation}
where the last step uses that
$\bar{z}_{e,t}\hat{Z}_e=\Theta(1)$ by a similar calculation as in \eqref{e:prod.of.zs.is.close.to.one}.
On the other hand, we also have
	\begin{align}\nonumber
	\Big|K^j(\sigma)\Big|
	&=\Bigg|
	\frac{{}_{*}\hat{q}_e(\sigma)}{\hat{Z}_e}
	\sum_{\bm{L}}{}_\star\hspace{-1pt}\psi_e(\bm{L})
	\Bigg(1 + 
	\alpha_{e,t}(\sigma,\bm{L})
		\Bigg)
	( \kappa_{e,t+1/3})^j(\sigma^j\,|\,\bm{L})
	\Bigg|\\
	&\stackrel{\eqref{e:orth}}{\le}
	O\bigg( {}_{*}\hat{q}_e(\sigma) \cdot \kappa_e(\sigma^j) \cdot \alpha_e(\sigma) \bigg)\,.
	\label{e:second.bound.K.j}
	\end{align}
Combining \eqref{e:first.bound.K.j} with \eqref{e:second.bound.K.j} gives 
	\[
	K^j(\sigma)
	= O\Bigg(
	\bar{q}_{e,t}(\sigma)\cdot
	\kappa_e(\sigma^j)\cdot
	\min\bigg\{
	\frac{\alpha_e(\sigma) {}_{*}\hat{q}_e(\sigma)}
		{\bar{q}_{e,t}(\sigma)},
	1\bigg\}
	\Bigg)\,.
	\]
Substituting this bound into \eqref{e:K.j.defn} gives 
	\begin{align*}
	\bar{z}_{e,t+2/3}\bar{q}_{e,t+2/3}(\sigma)
	&= \bar{z}_{e,t}\bar{q}_{e,t}(\sigma)
	\Bigg\{
	1+\sum_{j=1,2}\kappa_e(\sigma^j)
	\cdot \min\bigg\{
		\frac{\alpha_e(\sigma) {}_{*}\hat{q}_e(\sigma)}
		{\bar{q}_{e,t}(\sigma)},1\bigg\}
	\Bigg\}\,.
	\end{align*}
It then follows using the hypothesis 
\eqref{e:rough.inductive.bounds.forall.t} 
 that
	\[\Bigg|
	\frac{\bar{z}_{e,t+2/3}\bar{q}_{e,t+2/3}(\sigma)}
	{\bar{z}_{e,t}\bar{q}_{e,t}(\sigma)}-1\Bigg|
	\le
	k^{O(1)}
	\begin{cases} \displaystyle
	\frac{\kappa}{2^{k(1+\zeta)}}
	&\textup{if }\SSPIN{r}[\sigma]=0\,,\medskip\\
	\displaystyle
	\frac{\kappa+\dot{\kappa}}
		{2^{k\zeta}}
	&\textup{if }\SSPIN{r}[\sigma]=1\,,\medskip\\
	\displaystyle \dot{\kappa}
	&\textup{if }\SSPIN{r}[\sigma]=2\,.
	\end{cases}
	\]
Altogether, the error in averaged messages
between times $t+1/3$
and $t+2/3$ satisfies
	\begin{equation}\label{e:ctypes.one.two.crelerr}
	\widehat{\textup{\textsf{\footnotesize ERR}}}
	(\bar{q}_{e,t+1/3},
	\bar{q}_{e,t+2/3})
	=\widehat{\textup{\textsf{\footnotesize ERR}}}
	(\bar{q}_{e,t},
	\bar{q}_{e,t+2/3})
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	2^{-k} & 2^{-k}\\
	1 & 1 \\
	2^{-k}&2^{k\zeta}
	\end{pmatrix}
	\begin{pmatrix}
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}\,.
	\end{equation}
Substituting \eqref{e:ctypes.one.two.crelerr}
into the definition of $u$ from \eqref{e:first.defn.of.u} gives
	\begin{equation}\label{e:ctypes.one.two.vrelerr}
	\Bigg|
	\frac{u_{e,t+2/3}(\sigma)}
		{u_{e,t+1/3}(\sigma)}
	-1\Bigg|
	\le
	\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\{
	\underbrace{\sum_{e\in\delta v}
	\kappa_{e,t+1/3}
	}_{\textup{denote this }\bm{\kappa}_{t+1/3}}
	+\underbrace{
	\sum_{e\in\delta v}
	\dot{\kappa}_{e,t+1/3}
	}_{\textup{denote this }\bm{\dot{\kappa}}_{t+1/3}}
	\Bigg\}
	\equiv
	\frac{k^{O(1)}
		(\bm{\kappa}_{t+1/3}+\bm{\dot{\kappa}}_{t+1/3})
	}{2^{k(1+\zeta)}}
	\end{equation}
for all $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$.\smallskip


\noindent\bemph{\hypertarget{p:ctypes.varupdate.UPDATE.C.MSG}{Part~4b}. Errors in averaged messages incurred by update C.} By a similar (but somewhat simpler) calculation, we can also estimate the error between the averaged messages $\bar{q}_{e,t+2/3}$ and $\bar{q}_{e,t+1}$ for $t\ge0$. Between times $t+2/3$ and $t+1$ we only make the update \eqref{e:clause.frac.update}. 
In this part of the proof we will fix $e\in\delta v$ and abbreviate
	\[
	\begin{pmatrix}
	\kappa_e(\tau) \\ \alpha_e(\sigma) \\ \rho_e
	\end{pmatrix}
	\equiv
	\begin{pmatrix}
	\kappa_{e,t+2/3}(\tau) \\ 
	\alpha_{e,t+2/3}(\sigma) \\ 
	\rho_{e,t+2/3}
	\end{pmatrix}\,.
	\]
By the definition \eqref{e:fdel.defn} of $\rho$, we have
	\begin{equation}\label{e:fdel.orth}	0=
	\sum_{\bm{L}}\Bigg\{
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
	-\nu_{e,t+2/3}(\bm{L})
	\Bigg\}
	=\sum_{\bm{L}}
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
	\Bigg\{
	\rho_{e,t+2/3}(\bm{L})
	+O\Big((\rho_e)^2\Big)\Bigg\}\,.\end{equation}








We now turn to the comparison of the messages:
by the update rule \eqref{e:clause.frac.update},
	\begin{align*}
	\bar{z}_{e,t+1}\bar{q}_{e,t+1}(\sigma)
	&= \sum_{\bm{L}}
	\psi_{e,t+2/3}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})
	\bigg\{1 + \rho_{e,t+2/3}(\bm{L}) \bigg\} \\
	&=\bar{z}_{e,t+2/3}
	\Bigg\{\bar{q}_{e,t+2/3}(\sigma)
	+\underbrace{
	\Bigg[\sum_{\bm{L}}
	\frac{\psi_{e,t+2/3}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})}{\bar{z}_{e,t+2/3}}
	\rho_{e,t+2/3}(\bm{L}) 
	\Bigg]}_{\textup{denote this }R(\sigma)}\Bigg\}\,.
	\end{align*}
From the definition of $R(\sigma)$ we can easily deduce the bound
	\[
	\Big|R(\sigma)\Big|
	\le
	O\bigg( \bar{q}_{e,t+2/3}(\sigma)
		\cdot \rho_e\bigg)\,.
	\]
On the other hand we also have
	\begin{align*}
	R(\sigma)
	&=
	\frac{{}_{*}\hat{q}_e(\sigma)
	}{\bar{z}_{e,t+2/3} \hat{Z}_e}
	\sum_{\bm{L}}
	{}_\star\hspace{-1pt}\psi_e(\bm{L})
	\bigg(1 + \alpha_{e,t+1/3}(\sigma,\bm{L})\bigg)
	\rho_{e,t+2/3}(\bm{L}) \\
	&=
	O\Bigg(
	{}_{*}\hat{q}_e(\sigma)\cdot
	\rho_e 
	\cdot\Big(\rho_e+\alpha_e(\sigma)\Big)\Bigg)\,,
	\end{align*}
where the last step uses \eqref{e:fdel.orth}.
Substituting back into the preceding calculation gives
	\[
	\bar{z}_{e,t+1}\bar{q}_{e,t+1}(\sigma)
	=\bar{z}_{e,t+2/3}\bar{q}_{e,t+2/3}(\sigma)
	\Bigg\{
	1 + O\bigg(
	\rho_e \cdot
	\min\bigg\{
	\frac{(\rho_e+\alpha_e(\sigma)){}_{*}\hat{q}_e(\sigma)}
		{\bar{q}_{e,t+2/3}(\sigma)} ,1
	\bigg\}\bigg)
	\Bigg\}\,.\]
It follows using the inductive bounds \eqref{e:rough.inductive.bounds.forall.t} that
	\begin{equation}\label{e:error.in.avhq.from.update.C}
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\bar{q}_{e,t+2/3},\bar{q}_{e,t+1})
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\rho_{e,t+2/3}
	\begin{pmatrix} 2^{-k} \\ 1 \\ 2^{k\zeta}
	\end{pmatrix}\,.
	\end{equation}
Substituting this again into the definition \eqref{e:first.defn.of.u} of $u$ gives
	\begin{equation}\label{e:ctypes.two.three.vrelerr}
	\Bigg|
	\frac{u_{e,t+1}(\sigma)}
	{u_{e,t+2/3}(\sigma)}-1
	\Bigg|
	\le
	\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\sum_{e\in\delta v}
	\rho_{e,t+2/3}
	\equiv
	\frac{k^{O(1)} }{2^{k(1+\zeta)}}
		\bm{\rho}_{t+2/3}
	\end{equation}
for all $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$.\smallskip

\noindent\bemph{\hypertarget{p:ctypes.varupdate.UPDATE.B.MGL}{Part 5a}. Errors in marginals incurred by update B.} We now estimate the change in the edge marginals between times $t+1/3$ and $t+2/3$, resulting from update \eqref{e:cond.judicious.update}. To this end we introduce an intermediate measure $\nu_{e,t+1/2}$, in which we use the new weight $\psi_{e,t+1}(\sigma\,|\,\bm{L})$ but the old message $u_{e,t+1/3}$. Thus, recalling \eqref{e:first.defn.of.u}, we have
	\begin{align*}
	\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\sigma,\bm{L})
	&= 
	\hat{q}_e(\sigma,\bm{L})\psi_{e,t}(\bm{L})
	\psi_{e,t}(\sigma\,|\,\bm{L})
	u_{e,t+1/3}(\sigma)\,,\\
	\bm{\bar{z}}_{e,t+1/2}\nu_{e,t+1/2}(\sigma,\bm{L})
	&= 
	\hat{q}_e(\sigma,\bm{L})\psi_{e,t}(\bm{L})
	\psi_{e,t+1}(\sigma\,|\,\bm{L})
	u_{e,t+1/3}(\sigma)\,,\\
	\bm{\bar{z}}_{e,t+2/3}\nu_{e,t+2/3}(\sigma,\bm{L})
	&=\hat{q}_e(\sigma,\bm{L}) \psi_{e,t}(\bm{L})
	\psi_{e,t+1}(\sigma\,|\,\bm{L})
	u_{e,t+2/3}(\sigma)\,.
	\end{align*}
We first estimate the error between times $t+1/3$ and $t+2/3$. For this purpose, note that \eqref{e:defn.cdel.kappa} implies
(similarly to the relation \eqref{e:cdel.avg.to.zero} that was used earlier) that for all $\bm{L}$,
	\begin{align}\nonumber
	0&=\sum_\tau
	\Bigg\{ (\nu_{e,t+1/3})^j(\tau\,|\,\bm{L})
	-{}_\star\hspace{-1pt}\pi_e(\tau)\Bigg\}
	=\sum_\tau\Bigg\{
	(\nu_{e,t+1/3})^j(\tau\,|\,\bm{L})
	-\frac{ (\nu_{e,t+1/3})^j(\tau\,|\,\bm{L})}
		{1 + (\kappa_{e,t+1/3})^j(\tau\,|\,\bm{L})}
	\Bigg\} \\
	&=\sum_\tau
	(\nu_{e,t+1/3})^j(\tau\,|\,\bm{L})
	(\kappa_{e,t+1/3})^j(\tau\,|\,\bm{L})
	+ O\Bigg(\sum_\tau
		{}_\star\hspace{-1pt}\pi_e(\tau) \kappa_{e,t+1/3}(\tau)^2\Bigg)\,.
		\label{e:orth.sigma}
	\end{align}
It follows using \eqref{e:orth.sigma} that the marginal error on $\bm{L}$ between times $t+1/3$ and $t+1/2$ is given by
	\begin{align}\nonumber
	\bm{\bar{z}}_{e,t+1/2}\nu_{e,t+1/2}(\bm{L})
	&=\sum_\sigma
	\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\sigma,\bm{L})
	\prod_{j=1,2}
	\frac1{1+(\kappa_{e,t+1/3})^j(\sigma^j\,|\,\bm{L})} \\
	&=\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\bm{L})
	\Bigg\{1 +
	O\Bigg(\sum_\tau
		{}_\star\hspace{-1pt}\pi_e(\tau) \kappa_{e,t+1/3}
		(\tau)^2\Bigg)\Bigg\}\,.
	\label{e:one.third.to.one.half.rho.comparison}
	\end{align}
We note the error term can be simplified
using \eqref{e:rough.inductive.bounds.forall.t} as
	\[
	\sum_\tau
		{}_\star\hspace{-1pt}\pi_e(\tau) \kappa_{e,t+1/3}
		(\tau)^2
	\le k^{O(1)}\Bigg(
	(\kappa_{e,t+1/3})^2
	+\frac{(\dot{\kappa}_{e,t+1/3})^2}{2^k}
	\Bigg)
	\le
	\frac{k^{O(1)}
		(\kappa_{e,t+1/3}+\dot{\kappa}_{e,t+1/3})}
		{ 2^{k(1+\zeta)}}\,.
	\]
The error between $u_{e,t+1/3}$ and $u_{e,t+2/3}$
is bounded by \eqref{e:ctypes.one.two.vrelerr}, and this gives the marginal error on $\bm{L}$ between times $t+1/2$ and $t+2/3$. Combining these bounds gives altogether
	\begin{equation}\label{e:one.to.two.thirds.clause}
	\rho_{e,t+2/3}
	-\rho_{e,t+1/3}
	\le
	\Bigg|\frac{\nu_{e,t+2/3}(\bm{L})}
	{\nu_{e,t+1/3}(\bm{L})}-1\Bigg|
	\le \frac{k^{O(1)}
		(\bm{\kappa}_{t+1/3}+\bm{\dot{\kappa}}_{t+1/3})
	}{2^{k(1+\zeta)}}\,.
	\end{equation}
Next we argue that the update \eqref{e:cond.judicious.update} in fact brings the measures closer to being conditionally judicious. Indeed, focusing on the first copy $j=1$,
we can express
	\[
	\frac{\bm{\bar{z}}_{e,t+1/2}
	\nu_{e,t+1/2}(\sigma,\bm{L})}
	{\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\bm{L})}
	=
	\frac{
	{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	{ (\nu_{e,t+1/3})^1(\sigma^1\,|\,\bm{L}) }
	\frac{\nu_{e,t+1/3}(\sigma\,|\,\bm{L})}
	{1+(\kappa_{e,t+1/3})^2(\sigma^2\,|\,\bm{L})}\,,
	\]
and summing over $\sigma^2$ gives
	\begin{align*}
	&\frac{\bm{\bar{z}}_{e,t+1/2}
	\nu_{e,t+1/2}(\sigma^1,\bm{L})}
	{\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\bm{L})}
	=\frac{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	{ (\nu_{e,t+1/3})^1(\sigma^1\,|\,\bm{L}) }
	\sum_{\sigma^2}
	\nu_{e,t+1/3}(\sigma\,|\,\bm{L})
	\Bigg\{
	1 + O(\kappa_{e,t+1/3}(\sigma^2)^2) - 
	(\kappa_{e,t+1/3})^2(\sigma^2\,|\,\bm{L})
	\Bigg\}\\
	&\qquad=
	{}_\star\hspace{-1pt}\pi_e(\sigma^1)
	\Bigg\{
	1+ 
	O\Bigg(\sum_\tau
		{}_\star\hspace{-1pt}\pi_e(\tau) \kappa_{e,t+1/3}
		(\tau)^2\Bigg)
	-\sum_{\sigma^2}
	\frac{
	\nu_{e,t+1/3}(\sigma\,|\,\bm{L})}
	{ (\nu_{e,t+1/3})^1(\sigma^1\,|\,\bm{L}) }
	(\kappa_{e,t+1/3})^2(\sigma^2\,|\,\bm{L})
	\Bigg\}\\
	&\qquad=
	{}_\star\hspace{-1pt}\pi_e(\sigma^1)
	\Bigg\{
	1+ 
	O\Bigg(\sum_\tau
		{}_\star\hspace{-1pt}\pi_e(\tau) \kappa_{e,t+1/3}
		(\tau)^2\Bigg)
	-\underbrace{\sum_{\sigma^2}
	\frac{
	\nu_{e,t+1/3}(\sigma\,|\,\bm{L})}
	{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	(\kappa_{e,t+1/3})^2(\sigma^2\,|\,\bm{L})
	}_{\textup{denote this }S^1(\sigma^1\,|\,\bm{L})}
	\Bigg\}\,.
	\end{align*}
We then use 
\eqref{e:rough.inductive.bounds.forall.t}
and \eqref{e:orth} to estimate (with $\kappa\equiv \kappa_{e,t+1/3}$
and $\xi\equiv \xi_{e,t+1/3}$)
	\begin{align*}
	S(\sigma^1\,|\,\bm{L})
	&=
	\sum_{\sigma^2}
	\bigg\{
	1+\xi_{e,t+1/3}(\sigma\,|\,\bm{L})\bigg\}
	{}_\star\hspace{-1pt}\pi_e(\sigma^2)
	(\kappa_{e,t+1/3})^2(\sigma^2\,|\,\bm{L})\\
	&\le
	\begin{cases}\displaystyle
	k^{O(1)}\bigg(
	\kappa\xi + \frac{\dot{\kappa}\dot{\xi}}{ 2^k}\bigg)
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\bigg(
	\kappa
	+	\frac{\dot{\kappa}}{2^k}
		\bigg)
	& \textup{if }\sigma^1\ne\SSPIN{r}\,,\medskip\\
	\displaystyle
	k^{O(1)}\bigg(
	\kappa\dot{\xi} + \frac{\dot{\kappa} \ddot{\xi}}{2^k}
		\bigg)
	\le \frac{k^{O(1)}}{2^{k\zeta}}
		(\kappa + \dot{\kappa})
	& \textup{if }\sigma^1=\SSPIN{r}\,.
	\end{cases}
	\end{align*}
By substituting this into the preceding calculation
 and combining with
\eqref{e:one.third.to.one.half.rho.comparison}, 
we conclude that
	\[
	\begin{pmatrix}
	\kappa_{e,t+1/2}\\
	\dot{\kappa}_{e,t+1/2}
	\end{pmatrix}
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	1 & 2^{-k} \\
	1 & 1
	\end{pmatrix}
	\begin{pmatrix}
	\kappa_{e,t+1/3} \\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}\,.
	\]
We combine this with the error incurred by going from time $t+1/2$ to $t+2/3$ --- this results from the change in the message $u$, which again is bounded by \eqref{e:ctypes.one.two.vrelerr}. Altogether we conclude
	\begin{equation}\label{e:ctypes.one.two.cond}
	\begin{pmatrix}
	\kappa_{e,t+2/3}\\
	\dot{\kappa}_{e,t+2/3}
	\end{pmatrix}
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	1& 2^{-k} \\
	1 &1
	\end{pmatrix}
	\begin{pmatrix}
	\kappa_{e,t+1/3} \\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	+	\frac{k^{O(1)}
		(\bm{\kappa}_{t+1/3}+\bm{\dot{\kappa}}_{t+1/3})
	}{2^{k(1+\zeta)}}
	\begin{pmatrix}1\\1\end{pmatrix}
	\end{equation}
for all $e\in\delta v$.\smallskip


\noindent\bemph{\hypertarget{p:ctypes.varupdate.UPDATE.C.MGL}{Part~5b}. Errors in marginals incurred by update C.} We now estimate the change in edge marginals between times $t+2/3$ and $t+1$, resulting from update \eqref{e:clause.frac.update}. To this end, we can express
	\begin{align*}
	\bm{\bar{z}}_{e,t+1}\nu_{e,t+1}(\sigma,\bm{L})
	&= \bm{\bar{z}}_{e,t+2/3}\nu_{e,t+2/3}(\sigma,\bm{L})
	\frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}{\nu_{e,t+2/3}(\bm{L})}
	\frac{u_{e,t+1}(\sigma)}{u_{e,t+2/3}(\sigma)}\\
	&=\bm{\bar{z}}_{e,t+2/3}\nu_{e,t+2/3}(\sigma,\bm{L})
	\frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}{\nu_{e,t+2/3}(\bm{L})}
	\Bigg\{ 1 + O\bigg( 
	\frac{k^{O(1)} \bm{\rho}_{t+2/3}}{2^{k(1+\zeta)}}
		\bigg)\Bigg\}\,,
	\end{align*}
where the last estimate comes from \eqref{e:ctypes.two.three.vrelerr}. Summing over $\sigma$ gives
	\begin{equation}\label{e:ctypes.two.three.clause}
	\nu_{e,t+1}(\bm{L})
	= \frac{\bm{\bar{z}}_{e,t+2/3}
		\cdot \pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
		{\bm{\bar{z}}_{e,t+1}}
	\Bigg\{ 1 + O\bigg( 
	\frac{k^{O(1)} \bm{\rho}_{t+2/3}}{2^{k(1+\zeta)}}
		\bigg)\Bigg\}
	=\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
	\Bigg\{ 1 + O\bigg( 
	\frac{k^{O(1)} \bm{\rho}_{t+2/3}}{2^{k(1+\zeta)}}
		\bigg)\Bigg\}\,,
	\end{equation}
where the last equality is because both 
$\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)$
and $\nu_{e,t+1}(\bm{L})$ are probability measures over $\bm{L}$. On the other hand, the conditional measures given $\bm{L}$ change very little as a result of update \eqref{e:clause.frac.update}: it follows from the above that
	\begin{equation}\label{e:ctypes.two.three.cond}
	\nu_{e,t+1}(\sigma\,|\,\bm{L})
	=\nu_{e,t+2/3}(\sigma\,|\,\bm{L})
	\Bigg\{ 1 + O\bigg( 
	\frac{k^{O(1)} \bm{\rho}_{t+2/3}}{2^{k(1+\zeta)}}
		\bigg)\Bigg\}
	\end{equation}
for all $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$. 
Combining \eqref{e:ctypes.two.three.clause} and \eqref{e:ctypes.two.three.cond} gives
	\begin{equation}\label{e:update.C.single.edge}
	\begin{pmatrix}
	\rho_{e,t+1}\\
	\kappa_{e,t+1}\\
	\dot{\kappa}_{e,t+1}\end{pmatrix}
	\le
	\begin{pmatrix}
	0\\
	\kappa_{e,t+2/3}\\
	\dot{\kappa}_{e,t+2/3}\end{pmatrix}
	+ \frac{k^{O(1)}}{2^{k(1+\zeta)}} \bm{\rho}_{t+2/3}
		\begin{pmatrix}1\\1\\1\end{pmatrix}\,.
	\end{equation}
Finally,
recalling
\eqref{e:intermediate.bullet.measure}, we compare the measures
	\begin{align*}
	\bm{\bar{z}}_{e,t+1}\nu_{e,t+1}(\sigma,\bm{L})
	&= \psi_{e,t+1}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})
	u_{e,t+1}(\sigma)\,,\\
	\bm{\bar{z}}_{e\bullet,t+1}
		\nu_{e\bullet,t+1}(\sigma,\bm{L})
	&= \psi_{e,t+1}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})
	u_{e,t+1/3}(\sigma)\,.
	\end{align*}
It follows by combining
\eqref{e:ctypes.one.two.vrelerr} and \eqref{e:ctypes.two.three.vrelerr} that
	\begin{equation}\label{e:update.C.single.edge.back.to.bullet}
	\begin{pmatrix}
	\rho_{e\bullet,t+1}\\
	\kappa_{e\bullet,t+1}\\
	\dot{\kappa}_{e\bullet,t+1}
	\end{pmatrix}
	\le\begin{pmatrix}
	\rho_{e,t+1}\\
	\kappa_{e,t+1}\\
	\dot{\kappa}_{e,t+1}\end{pmatrix}
	+\frac{k^{O(1)}
	}{2^{k(1+\zeta)}}
	\bigg(\bm{\kappa}_{t+1/3}+\bm{\dot{\kappa}}_{t+1/3}
	+\bm{\rho}_{t+2/3}\bigg)
	\begin{pmatrix}1\\1\\1\end{pmatrix}\,.
	\end{equation}
This concludes our analysis of update C.\smallskip

\noindent\bemph{\hypertarget{p:ctypes.varupdate.CONCLUSION}{Part~6}. Convergence of iterative procedure.} We now collect the bounds obtained above to prove that the iterative procedure described in \hyperlink{p:ctypes.varupdate.ITERATIVE.CONSTRUCTION}{Part~1} converges. Recall from \eqref{e:update.A.def.epsilon} the definition of $\vec{\epsilon}(t)$. For $t\ge1$, it follows by combining \eqref{e:ctypes.one.two.crelerr} (from \hyperlink{p:ctypes.varupdate.UPDATE.B.MSG}{Part~4a}) and \eqref{e:error.in.avhq.from.update.C} (from \hyperlink{p:ctypes.varupdate.UPDATE.C.MSG}{Part~4b}) that we have
	\begin{equation}\label{e:vec.eps.t.bound}
	\vec{\epsilon}(t)
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	2^{-k} & 2^{-k} & 2^{-k}\\
	1 & 1 & 1\\
	2^{k\zeta}
	&2^{-k}&2^{k\zeta} 
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e,t-1/3}\\
	\kappa_{e,t-2/3}\\
	\dot{\kappa}_{e,t-2/3}
	\end{pmatrix}\,.
	\end{equation}
It will be useful to abbreviate $\bm{K}\equiv\bm{\kappa}+\bm{\dot{\kappa}}$.
Recall that $\textup{\textsf{err}}_v(t)$ is defined analogously to
\eqref{e:defn.of.err.v.notation}, so
	\[\textup{\textsf{err}}_v(t)\le
	\sum_{e\in\delta v}
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	1 & 2^{-k} & 2^{-k(1+\zeta)}
	\end{pmatrix}
	\begin{pmatrix}
	2^{-k} & 2^{-k} & 2^{-k}\\
	1 & 1 & 1\\
	2^{k\zeta} & 2^{-k} &2^{k\zeta}
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e,t-1/3}\\
	\kappa_{e,t-2/3}\\
	\dot{\kappa}_{e,t-2/3}
	\end{pmatrix}






	\le \frac{k^{O(1)}
		(\bm{K}_{t-2/3}
		+\bm{\rho}_{t-1/3}
	)}{2^{k(1+\zeta)}}
	\,.\]
We then substitute these bounds into the analysis of update A, from \hyperlink{p:ctypes.varupdate.UPDATE.A.GENERAL}{Part~3b}: from \eqref{e:fdel.bounds.from.update.A} 
and \eqref{e:cdel.bounds.from.update.A} we obtain
	\begin{equation}\label{e:update.A.single.edge}
	\begin{pmatrix}
	\rho_{e,t+1/3}\\
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	\le
	\begin{pmatrix}
	1&0&0\\
	1&1&0\\
	1&0&1
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e\bullet,t}\\
	\kappa_{e\bullet,t}\\
	\dot{\kappa}_{e\bullet,t}
	\end{pmatrix}
	+\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\{
	\frac{\bm{\rho}_{t-1/3}+\bm{K}_{t-2/3}}
		{2^{k(1+\zeta)}} 
	+ \frac{\kappa_{e,t-2/3}
	+\dot{\kappa}_{e,t-2/3}
	+\rho_{e,t-1/3}}{2^{k\zeta}}
	\Bigg\}
	\begin{pmatrix}
	1\\1\\2^k
	\end{pmatrix}\,.
	\end{equation}
Next, from the analysis of the marginal errors resulting from update B (\hyperlink{p:ctypes.varupdate.UPDATE.B.MGL}{Part~5a}), we have
the bounds
 \eqref{e:one.to.two.thirds.clause} and
\eqref{e:ctypes.one.two.cond}, which we recall give
	\begin{equation}\label{e:update.B.single.edge}
	\begin{pmatrix}
	\rho_{e,t+2/3}\\
	\kappa_{e,t+2/3}\\
	\dot{\kappa}_{e,t+2/3}
	\end{pmatrix}
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	2^{k\zeta} &0&0\\
	0&1& 2^{-k} \\
	0&1 &1
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e,t+1/3} \\
	\kappa_{e,t+1/3} \\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	+	\frac{k^{O(1)} \bm{K}_{t+1/3}
	}{2^{k(1+\zeta)}}
	\begin{pmatrix}1\\1\\1\end{pmatrix}\,.
	\end{equation}

















From the analysis of marginal errors resulting from update C (\hyperlink{p:ctypes.varupdate.UPDATE.C.MGL}{Part~5b}), we have the bounds 
\eqref{e:update.C.single.edge}
and \eqref{e:update.C.single.edge.back.to.bullet},
which combine to give
	\begin{equation}\label{e:update.C.single.edge.combined.final}
	\begin{pmatrix}
	\rho_{e\bullet,t+1}\\
	\kappa_{e\bullet,t+1}\\
	\dot{\kappa}_{e\bullet,t+1}
	\end{pmatrix}
	\le\begin{pmatrix}
	0\\
	\kappa_{e,t+2/3}\\
	\dot{\kappa}_{e,t+2/3}\end{pmatrix}
	+\frac{k^{O(1)}
	}{2^{k(1+\zeta)}}
	\bigg(
	\bm{\rho}_{t+2/3}
	+\bm{K}_{t+1/3}
	\bigg)
	\begin{pmatrix}1\\1\\1\end{pmatrix}\,.
	\end{equation}
Combining the above bounds gives, for all $t\ge1$,
	\begin{align*}
	\begin{pmatrix}
	\rho_{e\bullet,t}\\
	\kappa_{e\bullet,t}\\
	\dot{\kappa}_{e\bullet,t}
	\end{pmatrix}
	&\stackrel{
	\eqref{e:update.C.single.edge.combined.final}
	}{\le}
	\begin{pmatrix}
	0\\
	\kappa_{e,t-1/3}\\
	\dot{\kappa}_{e,t-1/3}\end{pmatrix}
	+\frac{k^{O(1)}
	}{2^{k(1+\zeta)}}
	\bigg(
	\bm{\rho}_{t-1/3}
	+\bm{K}_{t-2/3}\bigg)
	\begin{pmatrix}1\\1\\1\end{pmatrix}\\
	&\stackrel{\eqref{e:update.B.single.edge}}{\le}
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	0 &0&0\\
	0&1& 2^{-k} \\
	0&1 &1
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e,t-2/3} \\
	\kappa_{e,t-2/3} \\
	\dot{\kappa}_{e,t-2/3}
	\end{pmatrix}
	+\frac{k^{O(1)}
	}{2^{k(1+\zeta)}}
	\bigg(
	\bm{\rho}_{t-1/3}
	+\bm{K}_{t-2/3}\bigg)
	\begin{pmatrix}1\\1\\1\end{pmatrix}\,.
	\end{align*}
Substituting these bounds 
(along with \eqref{e:update.B.single.edge})
into \eqref{e:update.A.single.edge} gives
	\begin{equation}\label{e:fdel.cdel.single.edge.bound}
	\begin{pmatrix}
	\rho_{e,t+1/3}\\
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\left\{
	\begin{pmatrix} 
	0&0&0\\
	0&1&0\\
	0&1&1
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e,t-2/3}\\
	\kappa_{e,t-2/3}\\
	\dot{\kappa}_{e,t-2/3}
	\end{pmatrix}
	+\frac{\bm{\Upsilon}_{t-2/3}}{2^k}
	\begin{pmatrix}1\\1\\1
	\end{pmatrix}
	\right\}\,,
	\end{equation}
where $\bm{\Upsilon}\equiv\bm{\rho}+\bm{K}$.
(In the $3\times3$ matrix on the right-hand side of \eqref{e:fdel.cdel.single.edge.bound}, some entries are zero because we absorbed the errors into the $\bm{\Upsilon}_{t-2/3}$ term.)
Aggregating the last bound over $e\in\delta v$ gives
	\[
	\bm{\Upsilon}_{t+1/3}
	\equiv
	\bm{\rho}_{t+1/3}+\bm{K}_{t+1/3}
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{\bm{\rho}_{t+1/3}+\bm{K}_{t+1/3}\Bigg\}
	= \frac{k^{O(1)}}{2^{k\zeta}}
	\bm{\Upsilon}_{t-2/3}\,,
	\]
for all $t\ge1$. This implies that the iterative procedure of \hyperlink{p:ctypes.varupdate.ITERATIVE.CONSTRUCTION}{Part~1} converges to the desired weights
$\Psi_v\equiv\Psi_{v,\infty}$. We now turn to proving
that the weights satisfy the bounds \eqref{e:defn.of.err.v.notation} and \eqref{e:ctypes.varupdate.MAINBOUND}. 
Summing \eqref{e:fdel.cdel.single.edge.bound} over $t\ge1$ gives
	\begin{align*}
	S_{\ge1} &\equiv
	\begin{pmatrix}
	1&0\\1&1
	\end{pmatrix}
	\sum_{t\ge1}
	\begin{pmatrix}
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	\le
	\begin{pmatrix}
	1&0\\1&1
	\end{pmatrix}
	\sum_{t\ge1}
	\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	\begin{pmatrix} 
	1&0\\
	1&1
	\end{pmatrix}
	\begin{pmatrix}
	\kappa_{e,t-2/3}\\
	\dot{\kappa}_{e,t-2/3}
	\end{pmatrix}
	+\frac{\bm{\Upsilon}_{t-2/3}}{2^k}
	\begin{pmatrix}1\\1\end{pmatrix}
	\Bigg\}\\
	&\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	\begin{pmatrix}
	1&0\\1&1
	\end{pmatrix}
	\sum_{t\ge1}
	\begin{pmatrix}
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	+ \frac{\bm{\Upsilon}_{1/3}}{2^k}
	\begin{pmatrix}1\\1\end{pmatrix}
	+ S_{\ge1}
	\Bigg\}\,,
	\end{align*}
and rearranging this inequality gives an upper bound on $S_{\ge1}$. It follows using
\eqref{e:fdel.cdel.single.edge.bound} again that
	\begin{align*}
	\sum_{t\ge1}\begin{pmatrix}
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	&\le
	\begin{pmatrix}
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	+\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	\begin{pmatrix} 
	1&0\\
	1&1
	\end{pmatrix}
	\begin{pmatrix}
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	+\frac{\bm{\Upsilon}_{1/3}}{2^k}
	\begin{pmatrix}1\\1\end{pmatrix}
	+S_{\ge1}
	\Bigg\}\\
	&\le
	k^{O(1)}\Bigg\{
	\begin{pmatrix}
	1 & 0 \\ 2^{-k\zeta} & 1
	\end{pmatrix}
	\begin{pmatrix}
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	+\frac{\bm{\Upsilon}_{1/3}}{2^{k(1+\zeta)}}
		\begin{pmatrix}1\\1\end{pmatrix}
	\Bigg\}\,,
	\end{align*}
where the last step makes use of the upper bound on $S_{\ge1}$. We can also use 
\eqref{e:update.B.single.edge}
and \eqref{e:fdel.cdel.single.edge.bound}
to bound the sum of $\rho_{e,t+2/3}$ over all $t\ge1$, so altogether we have
	\begin{equation}\label{e:sum.over.t.positive}
	\sum_{t\ge1}\begin{pmatrix}
	\rho_{e,t+2/3}\\
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	\le
	k^{O(1)}\Bigg\{
	\begin{pmatrix}
	0&0&0\\
	0&1&0\\
	0&2^{-k\zeta} & 1
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e,1/3}\\
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	+\frac{\bm{\Upsilon}_{1/3}}{2^{k(1+\zeta)}}
		\begin{pmatrix} 1\\ 1\\1\end{pmatrix}
	\Bigg\}
	\end{equation}
We can then apply 
\eqref{e:fdel.bounds.from.update.A} and \eqref{e:cdel.bounds.from.update.A} with $t=0$ to obtain
	\[
	\begin{pmatrix}
	\rho_{e,1/3}\\
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	\le
	\begin{pmatrix}
	1&0&0\\
	1&1&0\\
	1&0&1
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e\bullet,0}\\
	\kappa_{e\bullet,0}\\
	\dot{\kappa}_{e\bullet,0}
	\end{pmatrix}
	+\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\{
	 \textup{\textsf{err}}_v
	+\dot{\epsilon}_e
	+\frac{\min\set{\ddot{\epsilon}_e,1}}
		{2^{k(1+\zeta)}}
	\Bigg\}
	\begin{pmatrix}
	1 \\ 1\\ 2^k
	\end{pmatrix}\,.
	\]
Finally, since we see from \eqref{e:table.of.all.measures}
that $\nu_{e,-2/3}
\cong \hat{p}_e \phi_e u_{e,-2/3}$
while
$\nu_{e\bullet,0}
\cong \hat{q}_e \phi_e u_{e,-2/3}$, we conclude
that 
	\[\begin{pmatrix}
	\rho_{e\bullet,0}\\
	\kappa_{e\bullet,0}\\
	\dot{\kappa}_{e\bullet,0}
	\end{pmatrix}
	\le
	\underbrace{\begin{pmatrix}
	\rho_{e,-2/3}\\
	\kappa_{e,-2/3}\\
	\dot{\kappa}_{e,-2/3}
	\end{pmatrix}
	}_{\textup{zero}}
	+
	\begin{pmatrix}
	1 & 2^{-k} & 2^{-k}\\
	1 & 2^{-k} & 2^{-k}\\
	1 & 1 & 1
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e \\
	\dot{\epsilon}_e\\
	\min\set{\ddot{\epsilon}_e,1}/2^{k\zeta}
	\end{pmatrix}\,,
	\]
where the first term on the right-hand side vanishes because $\nu_{e,-2/3}$ is fully judicious by the assumption. Combining the last two bounds gives
	\[\begin{pmatrix}
	\rho_{e,1/3}\\
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	\le\begin{pmatrix}
	1 & 2^{-k} & 2^{-k}\\
	1 & 2^{-k} & 2^{-k}\\
	1 & 1 & 1
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e \\
	\dot{\epsilon}_e\\
	\min\set{\ddot{\epsilon}_e,1}/2^{k\zeta}
	\end{pmatrix}
	+\frac{k^{O(1)} \textup{\textsf{err}}_v}
		{2^{k(1+\zeta)}}
	\begin{pmatrix}
	1 \\ 1\\ 2^k
	\end{pmatrix}\,.
	\]
This implies $\bm{\Upsilon}_{1/3} \le O(\textup{\textsf{err}}_v)$. It follows by combining with
\eqref{e:sum.over.t.positive} that
	\begin{equation}\label{e:final.sum.bound}
	\sum_{t\in\mathbb{Z},t\ge 0}
	\begin{pmatrix}
	\rho_{e,t+2/3}\\
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	\le
	\begin{pmatrix}
	1 & 2^{-k} & 2^{-k}\\
	1 & 2^{-k} & 2^{-k}\\
	1 & 1 & 1
	\end{pmatrix}
		\begin{pmatrix}
	\epsilon_e \\
	\dot{\epsilon}_e\\
	\min\set{\ddot{\epsilon}_e,1}/2^{k\zeta}
	\end{pmatrix}
	+\frac{k^{O(1)}\textup{\textsf{err}}_v}{2^{k(1+\zeta)}}
	\begin{pmatrix}
	1 \\ 1\\ 2^k
	\end{pmatrix}\,.
	\end{equation}
We remark that 
\eqref{e:final.sum.bound}
implies that the quantities $\rho,\kappa,\dot{\kappa}$ satisfy the claimed bound 
\eqref{e:rough.inductive.bounds.forall.t}.
The quantities $\alpha,\xi$ can be bounded in terms 
of $\rho,\kappa,\dot{\kappa}$, so it is straightforward to deduce that 
\eqref{e:rough.inductive.bounds.forall.t} indeed holds.
To conclude, it follows by recalling \eqref{e:cond.judicious.update}
and \eqref{e:defn.cdel.kappa}
that
	\[\Bigg|\frac{(\psi_{e,\infty})^j
		(\tau\,|\,\bm{L})}
		{(\phi_e)^j(
		\tau\,|\,\bm{L})}-1\Bigg|
	\le
	O\Bigg(
	\sum_{t\in\mathbb{Z},t\ge 0}
	\Bigg|
	\frac{(\psi_{e,t+1})^j
		(\tau\,|\,\bm{L})}
		{(\psi_{e,t})^j(
		\tau\,|\,\bm{L})}-1\Bigg|
		\Bigg)
	\le O\Bigg(
	\sum_{t\ge0}
	\kappa_{e,t+1/3}(\tau)
	\Bigg)\,.\]
It follows by recalling
\eqref{e:clause.frac.update}
and \eqref{e:fdel.defn}
that
	\[\sum_{t\in\mathbb{Z},t\ge 0}
	\Bigg|
	\frac{\psi_{e,t+1}(\bm{L})}{\psi_{e,t}(\bm{L})}-1\Bigg|
	\le O(1)
	\sum_{t\ge0}
	\rho_{e,t+2/3}\,.
	\]
These quantities are bounded by \eqref{e:final.sum.bound}, and 
this implies the claimed bound 
\eqref{e:ctypes.varupdate.MAINBOUND} for the clause-dependent weights. 
The errors in the clause-independent weights $\psi_v(\smash{\vec{\sigma}}_{\delta v})$ can be bounded by applying
Proposition~\ref{p:var.update} with input errors $\vec{\epsilon}(t)$ for integers $t\ge0$, where
(recalling \eqref{e:update.A.def.epsilon}) we have
	\begin{align}\nonumber
	\vec{E}
	&\equiv \sum_{t\in\mathbb{Z},t\ge0} \vec{\epsilon}(t)
	=\sum_{t\in\mathbb{Z},t\ge0}
	\Bigg\{\widehat{\textup{\textsf{\footnotesize ERR}}}(\bar{q}_{t-2/3},
	\bar{q}_{t-1/3})
	+\widehat{\textup{\textsf{\footnotesize ERR}}}(\bar{q}_{t-1/3},
	\bar{q}_{t})
	\Bigg\}\\
	&\stackrel{\eqref{e:vec.eps.t.bound}}{\le}
	\vec{\epsilon}(0)
	+\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	2^{-k} & 2^{-k} & 2^{-k}\\
	1 & 1 & 1\\
	2^{k\zeta} & 2^{-k} & 2^{k\zeta} 
	\end{pmatrix}
	\sum_{t\in\mathbb{Z},t\ge0} 
	\begin{pmatrix}
	\rho_{e,t+2/3}\\
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix} \nonumber \\
	&\stackrel{\eqref{e:final.sum.bound}}{\le}
	k^{O(1)}
	\begin{pmatrix}
	1 & 2^{-k} & 2^{-k} \\
	1 & 1 & 1 \\
	1 & 1 & 1 
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e\\
	\dot{\epsilon}_e\\
	\min\set{\ddot{\epsilon}_e,1}/2^{k\zeta}
	\end{pmatrix}
	+\frac{k^{O(1)}\textup{\textsf{err}}_v}{2^{k\zeta}}
	\begin{pmatrix}
	2^{-k}\\ 1 \\ 2^{k\zeta}
	\end{pmatrix}\,.
	\label{e:final.bound.sum.eps.over.t}
	\end{align}
It follows from this that 
	\begin{align*}
	E_e + \frac{\dot{E}_e}{2^k}
	+ \frac{\min\set{\ddot{E}_e,1}}{2^{k(1+\zeta)}}
	&\le k^{O(1)}
	\Bigg\{
	\epsilon_e + \frac{\dot{\epsilon}_e}{2^k}
	+ \frac{\min\set{\ddot{\epsilon}_e,1}}{2^{k(1+\zeta)}}
	 + \frac{\textup{\textsf{err}}_v}{2^{k(1+\zeta)}}
	\Bigg\}\,,\\
	\dot{E}_e
	+\frac{\min\set{\ddot{E}_e,1}}{2^{k\zeta}}
	&\le
	k^{O(1)}
	\Bigg\{
	\epsilon_e + \dot{\epsilon}_e
	+ \min\set{\ddot{\epsilon}_e,1}
	 + \frac{\textup{\textsf{err}}_v}{2^{k\zeta}}
	\Bigg\}\,.
	\end{align*}
Thus, if we apply the bound Proposition~\ref{p:var.update}
with input errors $\vec{\epsilon}(t)$ 
summed over all $t\ge0$, the final bound
will still be of the form \eqref{e:defn.of.err.v.notation}, as claimed.\smallskip


\noindent\bemph{\hypertarget{p:ctypes.varupdate.OUTMSG}{Part~7}. Error bound for outgoing messages.}
It remains to verify \eqref{e:ctypes.varupdate.OUTMSG}. This follows by a similar argument as in \hyperlink{c:var.update.BETTER.MGL.BOUND}{Step~2 of the proof of Corollary~\ref{c:var.update}}. 
Fix an edge $e\in\delta v$, and define $\hat{s}_e = \hat{p}_e$ and $\hat{s}_e=\hat{q}_{e'}$ for $e'\in\delta v\setminus e$. We can apply the above result to obtain weights $\Theta_v$
such that $\nu_{\delta v}[\Theta_v;\hat{s}]$
is fully judicious. On the same edge $e$, the outgoing \textsc{bp} messages for the measures
$\nu_{\delta v}[\Phi_v;\hat{p}]$,
$\nu_{\delta v}[\Theta_v;\hat{s}]$, and 
$\nu_{\delta v}[\Psi_v;\hat{q}]$ are given by
	\begin{align*}
	\dot{p}_e(\sigma,\bm{L})
	&\cong \phi_e(\sigma,\bm{L}) u_p(\sigma)\\
	\dot{s}_e(\sigma,\bm{L})
	&\cong \theta_e(\sigma,\bm{L}) u_s(\sigma)\\
	\dot{q}_e(\sigma,\bm{L})
	&\cong \psi_e(\sigma,\bm{L}) u_q(\sigma)
	\end{align*}
where $u_p \equiv u_{e,-2/3}$, $u_q \equiv u_{e,\infty}$, and analogously
	\[
	u_s(\sigma_e)
	\cong \sum_{\smash{\vec{\sigma}}_{\delta a \setminus e}}
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\theta_v(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e'\in\delta a \setminus e}\Bigg\{
	\sum_{\bm{L}}
	\theta_{e'}(\sigma_{e'},\bm{L}_{e'})
	\hat{s}_{e'}(\sigma_{e'},\bm{L}_{e'})
	\Bigg\}\,.
	\]
Conditional on $\bm{L}$, we use \eqref{e:reweighted.messages.v.to.c} to define the reweighted messages 
$P_e(\sigma\,|\,\bm{L})$,
$S_e(\sigma\,|\,\bm{L})$,
$Q_e(\sigma\,|\,\bm{L})$.
Recall \eqref{e:delta.vec.of.t}, and note that
	\[
	\vec{D} 
	\equiv
	\dddot{\textup{\textsf{\footnotesize ERR}}}(u_p,u_q)
	\le O\Bigg(
	\sum_{t\in\mathbb{Z},t\ge0}
	\dddot{\textup{\textsf{\footnotesize ERR}}}
	(u_{e,t-2/3},u_{e,t+1/3})
	\Bigg)
	=O\Bigg( 
	\sum_{t\in\mathbb{Z},t\ge0}
	\vec{\delta}(t+1/3)\Bigg)\,.\]
Let $\vec{D}'$ denote the first three entries of $\vec{D}$. Then 
	\begin{align*}
	\vec{D}'
	&
	\stackrel{\eqref{e:vec.delta.bound.with.L}}{\le}
	k^{O(1)}
	\sum_{t\in\mathbb{Z},t\ge0}
	\left\{
	\begin{pmatrix}
	1\\1\\1
	\end{pmatrix} \textup{\textsf{err}}_v(t)
	+ 
	\begin{pmatrix}
	0&0&0\\
	0&1&1\\
	0&1&1
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e(t)\\
	\dot{\epsilon}_e(t)\\
	\min\set{\ddot{\epsilon}_e(t),1}/2^{k\zeta}
	\end{pmatrix}
	\right\} \\
	&\stackrel{\eqref{e:final.bound.sum.eps.over.t}}{\le} k^{O(1)}\left\{
	\begin{pmatrix}
	1\\1\\1
	\end{pmatrix} \textup{\textsf{err}}_v
	+ 
	\begin{pmatrix}
	0&0&0\\
	0&1&1\\
	0&1&1
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e\\
	\dot{\epsilon}_e\\
	\min\set{\ddot{\epsilon}_e,1}/2^{k\zeta}
	\end{pmatrix}\right\}
	\end{align*}
Meanwhile, the errors between the edge weights
$\phi_e(\sigma,\bm{L})$,
$\theta_e(\sigma,\bm{L})$, and $\psi_e(\sigma,\bm{L})$ are bounded by \eqref{e:ctypes.varupdate.MAINBOUND}.
From this it is easy to see that
	\[
	\max_{\bm{L}}\Bigg\{
	\Bigg|
	\frac{\dot{s}_e(\bm{L})}{\dot{p}_e(\bm{L})}-1
	\Bigg|+ 
	\Bigg|
	\frac{\dot{q}_e(\bm{L})}{\dot{p}_e(\bm{L})}-1
	\Bigg|
	+\Bigg\|
	\frac{S_e(\cdot\,|\,\bm{L})}{P_e(\cdot\,|\,\bm{L})}-1
	\Bigg\|_\infty
	\Bigg\}
	\le
	k^{O(1)}
	\textup{\textsf{err}}_v\,.
	\]
Combining with the result of 
Lemma~\ref{l:marginal.error} gives
(cf.\ \eqref{e:marginal.error.P.to.S})
	\[
	\max_{\bm{L}}\Bigg\{\Bigg|
	\frac{(S_e)^j(\tau\,|\,\bm{L})}
		{(P_e)^j(\tau\,|\,\bm{L})}-1
	\Bigg|\Bigg\}
	\le \frac{k^{O(1)}\textup{\textsf{err}}_v}{2^{k\zeta}}\,.
	\]
The error between $S_e$ and $Q_e$ is bounded by
(cf.\ \eqref{e:S.Q.error} and \eqref{e:marginal.error.S.to.Q})
	\begin{align*}
	\max_{\bm{L}}\Bigg\{
	\Bigg|
	\frac{Q_e(\sigma\,|\,\bm{L})}{S_e(\sigma\,|\,\bm{L})}-1
	\Bigg|\Bigg\}
	&\le 
	k^{O(1)} \Bigg(
	\textup{\textsf{err}}_v
	+\Ind{\SSPIN{r}[\sigma]\ge1}
	\bigg(
	\dot{\epsilon}_e+
	\frac{\min\set{\ddot{\epsilon}_e,1}}{2^{k\zeta}}
	\bigg)\Bigg\} \\
	\max_{\bm{L}}\Bigg\{\Bigg|
	\frac{(Q_e)^j(\tau\,|\,\bm{L})}
		{(S_e)^j(\tau\,|\,\bm{L})}-1
	\Bigg|\Bigg\}
	&\le k^{O(1)}\Bigg( 
	\epsilon_e 
	+\frac1{(2^k)^{\Ind{\tau\ne\SSPIN{r}}}}
	\bigg\{ \dot{\epsilon}_e
	+ \frac{\min\set{\ddot{\epsilon}_e,1}}{2^{k\zeta}}
	\bigg\}\Bigg)\,.
	\end{align*}
Combining these bounds gives the claim \eqref{e:ctypes.varupdate.OUTMSG}.

