\label{d:diverse} For a variable $v$ of type $\bm{T}$,
let $\pi_v\equiv\pi_{\bm{T}}$ denote the marginal on the (pair) frozen configuration spin $x_v$. Thus $\pi_v$ is a probability measure on $\set{\SPIN{+},\SPIN{-},\SPIN{f}}^2$, which can be computed from $\pi_e$ for any $e\in\delta v$: for example,
$\pi_v(\SPIN{+}\SPIN{+})=\pi_e(\SSPIN{y}\SSPIN{y})$ for any $e\in\delta v(\SPIN{-})$.
We define a \bemph{diverse variable} to be a variable $v$ of type $\bm{T}$ such that
	\[
	\pi_v\Big(\set{\SPIN{+}\SPIN{-},\SPIN{-}\SPIN{+}}\Big)
	\equiv
	\pi_{\bm{T}}\Big(\set{\SPIN{+}\SPIN{-},\SPIN{-}\SPIN{+}}\Big)
	=2\pi_{\bm{T}}(\SPIN{+}\SPIN{-})
	\ge\frac14\,.
	\]
We then define a \bemph{diverse clause} to be a clause that neighbors at least $k/10$ diverse variables --- equivalently, it is a clause of type $\bm{L}$ such that
	\[
	\sum_{j=1}^{k(\bm{L})}
	\mathbf{1}\bigg\{
	\pi_{\bm{L}(j)}\Big(\set{\SSPIN{y}\SSPIN{p},
	\SSPIN{p}\SSPIN{y}}\Big) \ge\frac14
	\bigg\}
	=\sum_{j=1}^{k(\bm{L})}
	\mathbf{1}\bigg\{
	\pi_{\bm{L}(j)}(\SSPIN{y}\SSPIN{p}) \ge\frac18
	\bigg\}
	\ge \frac{k}{10}\,.
	\]
The definition of diversity depends only on type, so we can also speak of \bemph{diverse variable types} and \bemph{diverse clause types}. Let $\mathbb{D}$ denote the collection of all diverse clause types. For a variable $v$ of type $\bm{T}$, we write
	\begin{equation}\label{e:exp.num.nondiv.nbr.clauses}
	\cancel{\mathbb{D}}(v)
	\equiv\cancel{\mathbb{D}}(\bm{T})
	\equiv\sum_{\bm{t}\in\bm{T}}
	\sum_{\bm{L}}
	\Ind{\bm{L}\notin\mathbb{D}}
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t})
	\end{equation}
for the expected number of non-diverse clauses incident to $v$ under $\mathbb{P}_{\mathscr{D}}$.

\label{l:lotsOfAs} 
Let $a$ be a nice clause of type $\bm{L}$ (meaning all its incident edges are nice in the sense of Definition~\ref{d:nice}). Given $\omega\in\bm{I}_0$, let $\hat{\nu}_{\bm{L}}$ be the probability measure on valid (pair) colorings $\smash{\vec{\sigma}}_{\delta a}$ which maximizes entropy subject to edge marginals $(\omega_{\bm{L},j})_j$. By Definition~\ref{d:white.violet},
each $\smash{\vec{\sigma}}_{\delta a}$ maps to a configuration
$\smash{\vec{\varsigma}}_{\delta a}$, so $\hat{\nu}_{\bm{L}}$ also induces a probability measure on $(\mathscr{S}^2)^{\delta a}$. Under this measure we have
	\[
	\bm{\varpi}_{\bm{L},j}\Big(\varsigma=\SSPIN{w}\SSPIN{w}\Big)
	=\hat{\nu}_{\bm{L}}\Big(\varsigma_j=\SSPIN{w}\SSPIN{w}\Big)
	\ge 1-O\bigg(\frac{k^2}{2^k}\bigg)
	\]
for all $1\le j\le k(\bm{L})$.

\begin{proof} For the proof we will mostly suppress $\bm{L}$ from the notation, and write $\hat{\nu}\equiv\hat{\nu}_{\bm{L}}$. We claim that for this proof it suffices to take $\sigma$ in the reduced alphabet $\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}$. Indeed, each $\omega_{\bm{L},j}$ is a measure over $\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$, and naturally induces a measure $\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$, which we temporarily denote $\tilde{\omega}_{\bm{L},j}$. Let
$\tilde{\nu}\equiv\tilde{\nu}_{\bm{L}}$ be the probability measure on valid (pair) colorings $\tilde{\smash{\vec{\sigma}}}_{\delta a}\in(\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^{\delta a})^2$ which maximizes entropy subject to edge marginals $(\tilde{\omega}_{\bm{L},j})_j$.
Since the clause factor \eqref{e:indicator.of.valid.clause.coloring} does not distinguish between \SPIN{green} and \SPIN{blue}, the optimal $\hat{\nu}\equiv\hat{\nu}_{\bm{L}}$ must take the form
	\begin{equation}\label{e:bg.given.cyan}
	\hat{\nu}_{\bm{L}}(\smash{\vec{\sigma}}_{\delta a})
	= \tilde{\nu}(\tilde{\smash{\vec{\sigma}}}_{\delta a})
	\prod_{j=1}^{k(\bm{L})}
	\frac{\omega_{\bm{L},j}(\sigma_j)}
	{\tilde{\omega}_{\bm{L},j}(\tilde{\sigma}_j)}\,,
	\end{equation}
where $\smash{\vec{\sigma}}_{\delta a}\in(\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^{\delta a})^2$ and $\tilde{\smash{\vec{\sigma}}}_{\delta a}$ is its representative in $(\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^{\delta a})^2$. Thus it suffices to study $\tilde{\nu}$. For the remainder of the proof we will abuse notation slightly and write $\hat{\nu},\smash{\vec{\sigma}}_{\delta a}$ when we technically mean $\tilde{\nu},\tilde{\smash{\vec{\sigma}}}_{\delta a}$. The remainder of the proof is divided into a few numbered steps. \smallskip 

\noindent\bemph{Step 1. Reduction to consideration of non-forcing clause colorings.}
The single-copy marginals of $\omega$ are given by the canonical measure ${}_\star\hspace{-1pt}\pi$. Since $\bm{L}$ is assumed to be nice, it follows from Definition~\ref{d:nice} that
	\begin{equation}\label{e:lotsOfAs.hyp}
	{}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\SSPIN{r})
	\le\frac{O(1)}{2^k}\,,\quad
	\bigg|{}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\SSPIN{c})
	-\frac12\bigg|
	\le O\bigg(
	\frac{1}{2^{k/10}}\bigg)\,.
	\end{equation}
Let $\SPIN{U}$ denote the set of all \bemph{valid} pair colorings $\smash{\vec{\sigma}}_{\delta a} \in\set{\SSPIN{y},\SSPIN{c}}^{2K}$, where we abbreviate $K\equiv k(\bm{L})$. Note that if $\smash{\vec{\sigma}}_{\delta a}$ is a valid coloring belonging to the complement $\SPIN{U}^c$, then $\smash{\vec{\sigma}}_{\delta a}$ must have at least one edge colored $\SPIN{red}$ in at least one of the two copies. It follows by the judicious condition together with \eqref{e:lotsOfAs.hyp} that
	\begin{equation}\label{e:any.red.is.unlikely}
	\hat{\nu}(\SPIN{U}^c)
	\le
	\sum_{i=1,2}
	\sum_{j=1}^K
	(\omega_{\bm{L},j})^i(\SSPIN{r})
	= 2 \sum_{j=1}^K
	{}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\SSPIN{r})
	\stackrel{\eqref{e:lotsOfAs.hyp}}{\le}
	O\bigg( \frac{k}{2^k}\bigg)\,.
	\end{equation}
Define the conditional measure $\mu(\smash{\vec{\sigma}}_{\delta a})\equiv\hat{\nu}(\smash{\vec{\sigma}}_{\delta a}\,|\,\SPIN{U})$. Let $\mu_j$ be the marginal of $\mu$ on the $j$-th edge in $\delta a$, so $\mu_j$ is a probability measure on $\set{\SSPIN{y},\SSPIN{c}}^2$. Since $\hat{\nu}(\SPIN{U})$ is close to one by \eqref{e:any.red.is.unlikely},
the single-copy marginals of $\mu_j$ must be close to ${}_\star\hspace{-1pt}\pi_{\bm{L}(j)}$; in particular, we must have
	\begin{equation}\label{e:cond.yb.single.copy.mgls}
	(\mu_j)^i(\SSPIN{c})
	=\frac{ {}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\SSPIN{c})
		-\hat{\nu}(\SPIN{U}^c) \hat{\nu}( (\sigma_j)^i=\SSPIN{c}\,|\,\SPIN{U}^c )}{1 - \hat{\nu}(\SPIN{U}^c)}
	\stackrel{\eqref{e:any.red.is.unlikely}}{=} 
	{}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\SSPIN{c}) + O\bigg(\frac1{2^k}\bigg)
	\stackrel{\eqref{e:lotsOfAs.hyp}}{=}
	\frac12 +O\bigg(
	\frac{1}{2^{k/10}}\bigg)\,.
	\end{equation}
Since $\hat{\nu}=\hat{\nu}_{\bm{L}}$ maximizes entropy subject to marginals $(\omega_{\bm{L},j})_j$, it must be that $\mu$ maximizes entropy subject to marginals $(\mu_j)_j$. Consequently, by the method of Lagrange multipliers, there must exist probability measures $q_j$ over $\set{\SSPIN{y},\SSPIN{c}}^2$ (for $1\le j\le K$) such that
	\begin{equation}\label{e:cond.yb.q}
	\mu(\smash{\vec{\sigma}}_{\delta a})
	=
	\frac{\Ind{\smash{\vec{\sigma}}_{\delta a}\in\SPIN{U}}
	Q(\smash{\vec{\sigma}}_{\delta a})}{Q(\SPIN{U})},
	\quad
	Q(\smash{\vec{\sigma}}_{\delta a})
	\equiv\prod_{j=1}^K q_j(\sigma_e)\,.
	\end{equation}
In the next step we will estimate the $q_j$ to show that under $\mu$, each edge is $\SSPIN{w}\SSPIN{w}$ with probability close to one. Since $\mu$ takes up most of the mass of $\hat{\nu}$ by \eqref{e:any.red.is.unlikely}, the result will follow.\smallskip

\noindent\bemph{Step 2. Construction of Lagrangian weights.} We will iteratively construct a sequence $q_{j,t}$ that converges to the desired $q_j$
of \eqref{e:cond.yb.q} in the limit $t\to\infty$. We initialize $q_{j,0}=\mu_j$ for all $1\le j\le K$. Analogously to \eqref{e:cond.yb.q} let
	\[\mu_t(\smash{\vec{\sigma}}_{\delta a})
	=
	\frac{\Ind{\smash{\vec{\sigma}}_{\delta a}\in\SPIN{U}}
	Q_t(\smash{\vec{\sigma}}_{\delta a})}{Q_t(\SPIN{U})},
	\quad
	Q_t(\smash{\vec{\sigma}}_{\delta a})
	\equiv\prod_{j=1}^K q_{j,t}(\sigma_e)\,.
	\]
Let $\mu_{j,t}$ denote the marginal of $\mu_t$ on the $j$-th edge. Writing 
$\smash{\vec{\sigma}}_{-j}\equiv (\sigma_\ell)_{\ell\in[K]\setminus j}$, we have
	\begin{equation}\label{e:q.times.prob.of.remainder}
	\mu_{j,t}(\sigma)
	= \frac1{\bar{z}_{j,t}}
	q_{j,t}(\sigma)
	\overbrace{
	\sum_{\smash{\vec{\sigma}}_{-j}}
	\Ind{\smash{\vec{\sigma}}\in\SPIN{U}}
	\prod_{\ell\in[K]\setminus j}
	q_{\ell,t}(\sigma_\ell)
	}^{\textup{denote this }\xi_{j,t}(\sigma)}\,.
	\end{equation}
Note that $\xi_{j,t}(\sigma)$ has a simple expression for each $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$: for instance, for $\sigma=\SSPIN{c}\SSPIN{c}$ we have
	\[
	\xi_{j,t}(\SSPIN{c}\SSPIN{c})
	=1
	-\sum_{i=1,2}
	\prod_{\ell\in[K]\setminus j}
	(q_{\ell,t})^i(\SSPIN{y})
	+\prod_{\ell\in[K]\setminus j}
	q_{\ell,t}(\SSPIN{y}\SSPIN{y})\,,
	\]
and we have similar expressions for $\sigma\in\set{\SSPIN{y}\SSPIN{y},\SSPIN{y}\SSPIN{c},\SSPIN{c}\SSPIN{y}}$. It is easily verified that
$1-k^{O(1)}/2^k\le \xi_{j,0}(\sigma)\le1$
for all $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$, and substituting this estimate into \eqref{e:q.times.prob.of.remainder} gives (crudely)
	\begin{equation}\label{c:lotsOfAs.base.case}
	\bigg\| \frac{\mu_{j,0}}{\mu_j}-1
		\bigg\|_\infty
	\stackrel{\eqref{e:q.times.prob.of.remainder}}{=}
	\bigg\| \frac{\xi_{j,0}}{ \bar{z}_{j,0}}-1
	\bigg\|_\infty \le \frac1{2^{2k/3}}\,.
	\end{equation}
Moreover, it follows by a straightforward calculation that 
	\begin{equation}\label{e:d.xi.d.q.bound}
	\bigg|\frac{\partial \xi_{j,t}(\sigma)}
	{ \partial q_{\ell,t}(\sigma') }\bigg|
	\le \frac{k^{O(1)}}{2^k}
	\end{equation}
for all $j\ne \ell$ and all $\sigma,\sigma'\in\set{\SSPIN{y},\SSPIN{c}}^2$. We now define
$q_{j,t+1}$ to be the probability measure such that
	\begin{equation}\label{e:q.mu.update.rule}
	q_{j,t+1}(\sigma)
	\cong \frac{\mu_j(\sigma)}{\xi_{j,t}(\sigma)}
	\stackrel{\eqref{e:q.times.prob.of.remainder}}
		{\cong}
	\frac{\mu_j(\sigma)}{\mu_{j,t}(\sigma)}
		q_{j,t}(\sigma)\,.
	\end{equation}
Let $z_{j,t+1}$ denote the normalizing constant such that
	\begin{equation}\label{e:z.j.t.plus.one}
	q_{j,t+1}(\sigma)
	=\frac{\mu_j(\sigma)}{\mu_{j,t}(\sigma)}
		\frac{q_{j,t}(\sigma)}{z_{j,t+1}}\,.
	\end{equation}
Now suppose inductively that for all $t\ge0$ we have
	\begin{equation}\label{c:lotsOfAs.induction}
	\bigg\|
	\frac{\mu_{j,t} }{ \mu_j}
	-1\bigg\|_\infty
	\le \frac1{(2^{2k/3})^{t+1}}\,,\end{equation}
where the base case $t=0$ is given by \eqref{c:lotsOfAs.base.case}. Note that substituting \eqref{c:lotsOfAs.induction} into \eqref{e:z.j.t.plus.one} implies that $q_{j,t}$ is close to $z_{j,t+1}q_{j,t+1}$; since all the $q$'s are probability measures, it further implies that $z_{j,t+1}$ is close to one. Thus, for $t\ge0$,
the inductive hypothesis \eqref{c:lotsOfAs.induction} leads to
	\begin{equation}\label{e:induction.implies.xi.err.bound}
	\Big\|\xi_{j,t+1}-\xi_{j,t}\Big\|_\infty
	\stackrel{\eqref{e:d.xi.d.q.bound}}{\le}
	\frac{k^{O(1)}}{2^k}
	\Big\|q_{j,t+1}-q_{j,t}\Big\|_\infty
	\stackrel{\eqref{e:z.j.t.plus.one}}{=}
	\frac{k^{O(1)}}{2^k}
	\Bigg\|q_{j,t}
	\bigg(
	\frac{\mu_j}{\mu_{j,t}}
		\frac{1}{z_{j,t+1}}
	-1\bigg)\Bigg\|_\infty
	\stackrel{\eqref{c:lotsOfAs.induction}}{\le}
	\frac{k^{O(1)}}{2^k}
	\frac1{(2^{2k/3})^{t+1}}\,.
	\end{equation}
Recall that $\mu_{j,t+1} = q_{j,t+1} \xi_{j,t+1} / \bar{z}_{j,t+1}$ by \eqref{e:q.times.prob.of.remainder}, while
\eqref{e:q.mu.update.rule} implies that
there exists a normalizing constant $\acute{z}_{j,t+1}$ such that $\mu_j = q_{j,t+1} \xi_{j,t}/\acute{z}_{j,t+1}$. It follows that
	\[
	\bigg\| \frac{\mu_{j,t+1}}{\mu_j}-1\bigg\|_\infty
	=
	\bigg\| 
	\frac{\xi_{j,t+1} / \bar{z}_{j,t+1}}
		{\xi_{j,t} / \acute{z}_{j,t+1}}-1
	\bigg\|_\infty
	\stackrel{\eqref{e:induction.implies.xi.err.bound}}
		{\le}
	\frac1{(2^{2k/3})^{t+2}}\,,
	\]
which verifies the inductive hypothesis \eqref{c:lotsOfAs.induction}.\smallskip

\noindent
\bemph{Step 3. Conclusion.}
Let $q_j=\lim_{t\to\infty} q_{j,t}$, where it is clear from \eqref{c:lotsOfAs.induction} that the limit is well-defined. Moreover, summing \eqref{c:lotsOfAs.induction} over $t\ge0$ implies
	\begin{align*}
	\bigg\|\frac{q_j}{\mu_j}-1\bigg\|_\infty
	&=\bigg\|\frac{q_j}{q_{j,0}}-1\bigg\|_\infty
	\le
	\sum_{t\ge0}
	\bigg\|\frac{q_{j,t+1}}{q_{j,t}}-1\bigg\|_\infty\\
	&\stackrel{\eqref{e:z.j.t.plus.one}}
		{\le} O\Bigg(
	\sum_{t\ge0}
	\bigg\|\frac{\mu_{j,t}}{\mu_j}
		-1\bigg\|_\infty
		\Bigg)
	\stackrel{\eqref{c:lotsOfAs.induction}}{\le}
	O\Bigg(
	\sum_{t\ge0}
	\frac1{(2^{2k/3})^{t+1}}\Bigg)
	\le \frac1{2^{k/2}}\,.
	\end{align*}
We can then straightforwardly derive from
\eqref{e:cond.yb.single.copy.mgls}, \eqref{e:cond.yb.q}, and
the last bound that 	
	\[\mu\Big(\varsigma_j=\SSPIN{w}\SSPIN{w}\Big)
	\ge 1- O\bigg(\frac{k^2}{2^k}\bigg)\]
for all $1\le j\le K$. The result follows since $\mu$ is the measure $\hat{\nu}$ conditioned on event $\SPIN{U}$,
and we know that
 $\hat{\nu}(\SPIN{U}^c)$ is negligible by \eqref{e:any.red.is.unlikely}.
\end{proof}

 For the proof we will mostly suppress $\bm{L}$ from the notation, and write $\hat{\nu}\equiv\hat{\nu}_{\bm{L}}$. We claim that for this proof it suffices to take $\sigma$ in the reduced alphabet $\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}$. Indeed, each $\omega_{\bm{L},j}$ is a measure over $\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2$, and naturally induces a measure $\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$, which we temporarily denote $\tilde{\omega}_{\bm{L},j}$. Let
$\tilde{\nu}\equiv\tilde{\nu}_{\bm{L}}$ be the probability measure on valid (pair) colorings $\tilde{\smash{\vec{\sigma}}}_{\delta a}\in(\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^{\delta a})^2$ which maximizes entropy subject to edge marginals $(\tilde{\omega}_{\bm{L},j})_j$.
Since the clause factor \eqref{e:indicator.of.valid.clause.coloring} does not distinguish between \SPIN{green} and \SPIN{blue}, the optimal $\hat{\nu}\equiv\hat{\nu}_{\bm{L}}$ must take the form
	\begin{equation}\label{e:bg.given.cyan}
	\hat{\nu}_{\bm{L}}(\smash{\vec{\sigma}}_{\delta a})
	= \tilde{\nu}(\tilde{\smash{\vec{\sigma}}}_{\delta a})
	\prod_{j=1}^{k(\bm{L})}
	\frac{\omega_{\bm{L},j}(\sigma_j)}
	{\tilde{\omega}_{\bm{L},j}(\tilde{\sigma}_j)}\,,
	\end{equation}
where $\smash{\vec{\sigma}}_{\delta a}\in(\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^{\delta a})^2$ and $\tilde{\smash{\vec{\sigma}}}_{\delta a}$ is its representative in $(\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^{\delta a})^2$. Thus it suffices to study $\tilde{\nu}$. For the remainder of the proof we will abuse notation slightly and write $\hat{\nu},\smash{\vec{\sigma}}_{\delta a}$ when we technically mean $\tilde{\nu},\tilde{\smash{\vec{\sigma}}}_{\delta a}$. The remainder of the proof is divided into a few numbered steps. \smallskip 

\noindent\bemph{Step 1. Reduction to consideration of non-forcing clause colorings.}
The single-copy marginals of $\omega$ are given by the canonical measure ${}_\star\hspace{-1pt}\pi$. Since $\bm{L}$ is assumed to be nice, it follows from Definition~\ref{d:nice} that
	\begin{equation}\label{e:lotsOfAs.hyp}
	{}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\SSPIN{r})
	\le\frac{O(1)}{2^k}\,,\quad
	\bigg|{}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\SSPIN{c})
	-\frac12\bigg|
	\le O\bigg(
	\frac{1}{2^{k/10}}\bigg)\,.
	\end{equation}
Let $\SPIN{U}$ denote the set of all \bemph{valid} pair colorings $\smash{\vec{\sigma}}_{\delta a} \in\set{\SSPIN{y},\SSPIN{c}}^{2K}$, where we abbreviate $K\equiv k(\bm{L})$. Note that if $\smash{\vec{\sigma}}_{\delta a}$ is a valid coloring belonging to the complement $\SPIN{U}^c$, then $\smash{\vec{\sigma}}_{\delta a}$ must have at least one edge colored $\SPIN{red}$ in at least one of the two copies. It follows by the judicious condition together with \eqref{e:lotsOfAs.hyp} that
	\begin{equation}\label{e:any.red.is.unlikely}
	\hat{\nu}(\SPIN{U}^c)
	\le
	\sum_{i=1,2}
	\sum_{j=1}^K
	(\omega_{\bm{L},j})^i(\SSPIN{r})
	= 2 \sum_{j=1}^K
	{}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\SSPIN{r})
	\stackrel{\eqref{e:lotsOfAs.hyp}}{\le}
	O\bigg( \frac{k}{2^k}\bigg)\,.
	\end{equation}
Define the conditional measure $\mu(\smash{\vec{\sigma}}_{\delta a})\equiv\hat{\nu}(\smash{\vec{\sigma}}_{\delta a}\,|\,\SPIN{U})$. Let $\mu_j$ be the marginal of $\mu$ on the $j$-th edge in $\delta a$, so $\mu_j$ is a probability measure on $\set{\SSPIN{y},\SSPIN{c}}^2$. Since $\hat{\nu}(\SPIN{U})$ is close to one by \eqref{e:any.red.is.unlikely},
the single-copy marginals of $\mu_j$ must be close to ${}_\star\hspace{-1pt}\pi_{\bm{L}(j)}$; in particular, we must have
	\begin{equation}\label{e:cond.yb.single.copy.mgls}
	(\mu_j)^i(\SSPIN{c})
	=\frac{ {}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\SSPIN{c})
		-\hat{\nu}(\SPIN{U}^c) \hat{\nu}( (\sigma_j)^i=\SSPIN{c}\,|\,\SPIN{U}^c )}{1 - \hat{\nu}(\SPIN{U}^c)}
	\stackrel{\eqref{e:any.red.is.unlikely}}{=} 
	{}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\SSPIN{c}) + O\bigg(\frac1{2^k}\bigg)
	\stackrel{\eqref{e:lotsOfAs.hyp}}{=}
	\frac12 +O\bigg(
	\frac{1}{2^{k/10}}\bigg)\,.
	\end{equation}
Since $\hat{\nu}=\hat{\nu}_{\bm{L}}$ maximizes entropy subject to marginals $(\omega_{\bm{L},j})_j$, it must be that $\mu$ maximizes entropy subject to marginals $(\mu_j)_j$. Consequently, by the method of Lagrange multipliers, there must exist probability measures $q_j$ over $\set{\SSPIN{y},\SSPIN{c}}^2$ (for $1\le j\le K$) such that
	\begin{equation}\label{e:cond.yb.q}
	\mu(\smash{\vec{\sigma}}_{\delta a})
	=
	\frac{\Ind{\smash{\vec{\sigma}}_{\delta a}\in\SPIN{U}}
	Q(\smash{\vec{\sigma}}_{\delta a})}{Q(\SPIN{U})},
	\quad
	Q(\smash{\vec{\sigma}}_{\delta a})
	\equiv\prod_{j=1}^K q_j(\sigma_e)\,.
	\end{equation}
In the next step we will estimate the $q_j$ to show that under $\mu$, each edge is $\SSPIN{w}\SSPIN{w}$ with probability close to one. Since $\mu$ takes up most of the mass of $\hat{\nu}$ by \eqref{e:any.red.is.unlikely}, the result will follow.\smallskip

\noindent\bemph{Step 2. Construction of Lagrangian weights.} We will iteratively construct a sequence $q_{j,t}$ that converges to the desired $q_j$
of \eqref{e:cond.yb.q} in the limit $t\to\infty$. We initialize $q_{j,0}=\mu_j$ for all $1\le j\le K$. Analogously to \eqref{e:cond.yb.q} let
	\[\mu_t(\smash{\vec{\sigma}}_{\delta a})
	=
	\frac{\Ind{\smash{\vec{\sigma}}_{\delta a}\in\SPIN{U}}
	Q_t(\smash{\vec{\sigma}}_{\delta a})}{Q_t(\SPIN{U})},
	\quad
	Q_t(\smash{\vec{\sigma}}_{\delta a})
	\equiv\prod_{j=1}^K q_{j,t}(\sigma_e)\,.
	\]
Let $\mu_{j,t}$ denote the marginal of $\mu_t$ on the $j$-th edge. Writing 
$\smash{\vec{\sigma}}_{-j}\equiv (\sigma_\ell)_{\ell\in[K]\setminus j}$, we have
	\begin{equation}\label{e:q.times.prob.of.remainder}
	\mu_{j,t}(\sigma)
	= \frac1{\bar{z}_{j,t}}
	q_{j,t}(\sigma)
	\overbrace{
	\sum_{\smash{\vec{\sigma}}_{-j}}
	\Ind{\smash{\vec{\sigma}}\in\SPIN{U}}
	\prod_{\ell\in[K]\setminus j}
	q_{\ell,t}(\sigma_\ell)
	}^{\textup{denote this }\xi_{j,t}(\sigma)}\,.
	\end{equation}
Note that $\xi_{j,t}(\sigma)$ has a simple expression for each $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$: for instance, for $\sigma=\SSPIN{c}\SSPIN{c}$ we have
	\[
	\xi_{j,t}(\SSPIN{c}\SSPIN{c})
	=1
	-\sum_{i=1,2}
	\prod_{\ell\in[K]\setminus j}
	(q_{\ell,t})^i(\SSPIN{y})
	+\prod_{\ell\in[K]\setminus j}
	q_{\ell,t}(\SSPIN{y}\SSPIN{y})\,,
	\]
and we have similar expressions for $\sigma\in\set{\SSPIN{y}\SSPIN{y},\SSPIN{y}\SSPIN{c},\SSPIN{c}\SSPIN{y}}$. It is easily verified that
$1-k^{O(1)}/2^k\le \xi_{j,0}(\sigma)\le1$
for all $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$, and substituting this estimate into \eqref{e:q.times.prob.of.remainder} gives (crudely)
	\begin{equation}\label{c:lotsOfAs.base.case}
	\bigg\| \frac{\mu_{j,0}}{\mu_j}-1
		\bigg\|_\infty
	\stackrel{\eqref{e:q.times.prob.of.remainder}}{=}
	\bigg\| \frac{\xi_{j,0}}{ \bar{z}_{j,0}}-1
	\bigg\|_\infty \le \frac1{2^{2k/3}}\,.
	\end{equation}
Moreover, it follows by a straightforward calculation that 
	\begin{equation}\label{e:d.xi.d.q.bound}
	\bigg|\frac{\partial \xi_{j,t}(\sigma)}
	{ \partial q_{\ell,t}(\sigma') }\bigg|
	\le \frac{k^{O(1)}}{2^k}
	\end{equation}
for all $j\ne \ell$ and all $\sigma,\sigma'\in\set{\SSPIN{y},\SSPIN{c}}^2$. We now define
$q_{j,t+1}$ to be the probability measure such that
	\begin{equation}\label{e:q.mu.update.rule}
	q_{j,t+1}(\sigma)
	\cong \frac{\mu_j(\sigma)}{\xi_{j,t}(\sigma)}
	\stackrel{\eqref{e:q.times.prob.of.remainder}}
		{\cong}
	\frac{\mu_j(\sigma)}{\mu_{j,t}(\sigma)}
		q_{j,t}(\sigma)\,.
	\end{equation}
Let $z_{j,t+1}$ denote the normalizing constant such that
	\begin{equation}\label{e:z.j.t.plus.one}
	q_{j,t+1}(\sigma)
	=\frac{\mu_j(\sigma)}{\mu_{j,t}(\sigma)}
		\frac{q_{j,t}(\sigma)}{z_{j,t+1}}\,.
	\end{equation}
Now suppose inductively that for all $t\ge0$ we have
	\begin{equation}\label{c:lotsOfAs.induction}
	\bigg\|
	\frac{\mu_{j,t} }{ \mu_j}
	-1\bigg\|_\infty
	\le \frac1{(2^{2k/3})^{t+1}}\,,\end{equation}
where the base case $t=0$ is given by \eqref{c:lotsOfAs.base.case}. Note that substituting \eqref{c:lotsOfAs.induction} into \eqref{e:z.j.t.plus.one} implies that $q_{j,t}$ is close to $z_{j,t+1}q_{j,t+1}$; since all the $q$'s are probability measures, it further implies that $z_{j,t+1}$ is close to one. Thus, for $t\ge0$,
the inductive hypothesis \eqref{c:lotsOfAs.induction} leads to
	\begin{equation}\label{e:induction.implies.xi.err.bound}
	\Big\|\xi_{j,t+1}-\xi_{j,t}\Big\|_\infty
	\stackrel{\eqref{e:d.xi.d.q.bound}}{\le}
	\frac{k^{O(1)}}{2^k}
	\Big\|q_{j,t+1}-q_{j,t}\Big\|_\infty
	\stackrel{\eqref{e:z.j.t.plus.one}}{=}
	\frac{k^{O(1)}}{2^k}
	\Bigg\|q_{j,t}
	\bigg(
	\frac{\mu_j}{\mu_{j,t}}
		\frac{1}{z_{j,t+1}}
	-1\bigg)\Bigg\|_\infty
	\stackrel{\eqref{c:lotsOfAs.induction}}{\le}
	\frac{k^{O(1)}}{2^k}
	\frac1{(2^{2k/3})^{t+1}}\,.
	\end{equation}
Recall that $\mu_{j,t+1} = q_{j,t+1} \xi_{j,t+1} / \bar{z}_{j,t+1}$ by \eqref{e:q.times.prob.of.remainder}, while
\eqref{e:q.mu.update.rule} implies that
there exists a normalizing constant $\acute{z}_{j,t+1}$ such that $\mu_j = q_{j,t+1} \xi_{j,t}/\acute{z}_{j,t+1}$. It follows that
	\[
	\bigg\| \frac{\mu_{j,t+1}}{\mu_j}-1\bigg\|_\infty
	=
	\bigg\| 
	\frac{\xi_{j,t+1} / \bar{z}_{j,t+1}}
		{\xi_{j,t} / \acute{z}_{j,t+1}}-1
	\bigg\|_\infty
	\stackrel{\eqref{e:induction.implies.xi.err.bound}}
		{\le}
	\frac1{(2^{2k/3})^{t+2}}\,,
	\]
which verifies the inductive hypothesis \eqref{c:lotsOfAs.induction}.\smallskip

\noindent
\bemph{Step 3. Conclusion.}
Let $q_j=\lim_{t\to\infty} q_{j,t}$, where it is clear from \eqref{c:lotsOfAs.induction} that the limit is well-defined. Moreover, summing \eqref{c:lotsOfAs.induction} over $t\ge0$ implies
	\begin{align*}
	\bigg\|\frac{q_j}{\mu_j}-1\bigg\|_\infty
	&=\bigg\|\frac{q_j}{q_{j,0}}-1\bigg\|_\infty
	\le
	\sum_{t\ge0}
	\bigg\|\frac{q_{j,t+1}}{q_{j,t}}-1\bigg\|_\infty\\
	&\stackrel{\eqref{e:z.j.t.plus.one}}
		{\le} O\Bigg(
	\sum_{t\ge0}
	\bigg\|\frac{\mu_{j,t}}{\mu_j}
		-1\bigg\|_\infty
		\Bigg)
	\stackrel{\eqref{c:lotsOfAs.induction}}{\le}
	O\Bigg(
	\sum_{t\ge0}
	\frac1{(2^{2k/3})^{t+1}}\Bigg)
	\le \frac1{2^{k/2}}\,.
	\end{align*}
We can then straightforwardly derive from
\eqref{e:cond.yb.single.copy.mgls}, \eqref{e:cond.yb.q}, and
the last bound that 	
	\[\mu\Big(\varsigma_j=\SSPIN{w}\SSPIN{w}\Big)
	\ge 1- O\bigg(\frac{k^2}{2^k}\bigg)\]
for all $1\le j\le K$. The result follows since $\mu$ is the measure $\hat{\nu}$ conditioned on event $\SPIN{U}$,
and we know that
 $\hat{\nu}(\SPIN{U}^c)$ is negligible by \eqref{e:any.red.is.unlikely}.

