\label{l:indifferent} Suppose $\omega\in\bm{I}_0$, and let $\pi\equiv(\pi_{\bm{t}})_{\bm{t}}$ be the marginal of $\omega$ --- each $\pi_{\bm{t}}$ is obtained by averaging over $\omega_{\bm{L},j}$ such that $\bm{L}\ni\bm{t}$ (see Definition~\ref{d:empirical.measures.of.colors}). Let
	\[
	\nu^\textup{op}[\pi]
	\equiv
	\textup{arg\,max}_\nu
	\bigg\{
	\bm{\Phi}_{\mathscr{D},2}(\nu):
	\textup{$\nu$ is consistent with $\pi$}
	\bigg\}\,.
	\]
This is a relaxation of
\eqref{e:nu.opt.given.omega.pair}, since if $\nu$ is consistent with $\omega$ then it is also consistent with $\pi$. The relaxation is also a strictly convex problem, so the maximizer $\nu^\textup{op}[\pi]$ is uniquely defined. Let $\acute{\omega}$ denote the marginals of $\nu^\textup{op}[\pi]$. Then, for every $\sigma\in\set{\SSPIN{y},\SSPIN{b}}^2$ and every non-compound edge $\bm{t}$ with $\pi_{\bm{t}}(\sigma)\ge 2^{-k/15}$, we have
	\[\min\bigg\{
	\frac{\acute{\omega}_{\bm{L},j}(\sigma)}{\pi_{\bm{t}}(\sigma)}
	:\bm{L}(j)=\bm{t}\bigg\}
	\ge \frac18\,,
	\]
where $j\equiv j(\bm{t})$. (If $\bm{t}$ is a compound edge type then there is only one clause type $\bm{L}$ with $\bm{L}(j)=\bm{t}$, so in this case $\omega_{\bm{L},j}=\pi_{\bm{t}}$ and there is nothing to prove.)

\begin{proof} The proof follows a familiar outline: we first reduce to a simplified constrained entropy maximization problem, then estimate the Lagrangian weights solving that problem to derive the conclusion.\smallskip

\noindent
\bemph{Step 1. Simplified entropy maximization problem.}
From the expression \eqref{e:rate.function.pair.model}
for $\bm{\Phi}_{\mathscr{D},2}$, we see that to optimize
$\bm{\Phi}_{\mathscr{D},2}(\nu)$ given fixed $\pi$, we can optimize separately over the variable and clause empirical measures, $\dot{\nu}$ and $\hat{\nu}$. We can therefore consider $\hat{\nu}$ alone, since it determines $\acute{\omega}$. The optimal $\hat{\nu}$ is given by
	\begin{equation}\label{e:max.entropy.hbh.given.pi}
	\hat{\nu}=\textup{arg\,max}_{\hat{\nu}}
	\Bigg\{
	\mathbb{E}_{\hat{\mathscr{D}}}[\mathcal{H}(\hat{\nu}_{\bm{L}})]
	\equiv
	\sum_{\bm{L}}\hat{\mathscr{D}}(\bm{L}) \mathcal{H}(\hat{\nu}_{\bm{L}})
	: \textup{$\hat{\nu}$ is judicious and 
	consistent with $\pi$}
	\Bigg\}
	\end{equation}
--- this is because $\mathbb{E}_{\hat{\mathscr{D}}}[\mathcal{H}(\hat{\nu}_{\bm{L}})]$ is the only term of \eqref{e:rate.function.pair.model} that varies with $\hat{\nu}$ when $\pi$ is fixed. Equivalently, recalling the combinatorial calculation \eqref{e:config.model.pair.version}, 
$\hat{\nu}$ must satisfy
	\begin{equation}\label{e:max.entropy.hbh.given.pi.comb}
	\hat{\nu}=\textup{arg\,max}_{\hat{\nu}}
	\Bigg\{
	\prod_{\bm{L}}
	\binom{m_{\bm{L}}}{m_{\bm{L}}\hat{\nu}_{\bm{L}}}
	\Bigg\}\,,
	\end{equation}
that is to say, $\hat{\nu}$ is the empirical measure of clause colorings $\smash{\vec{\sigma}}_{\delta a}$ that maximizes entropy subject to marginals $\pi$.

Now, as in the statement of the lemma, let us fix a non-compound edge type $\bm{t}$ such that $\pi_{\bm{t}}(\sigma)\ge 2^{-k/20}$. Denote $j=j(\bm{t})$, and recall that we write $\bm{L}\ni\bm{t}$ if and only if $\bm{L}(j)=\bm{t}$. 
Given $\mathscr{G}=(V,F,E)$, define the subset of clauses
	\[
	F(\bm{t})
	= \bigg\{ a\in F : \bm{L}_a \ni\bm{t}\bigg\}
	\subseteq F\,.
	\]
Note for all $\bm{L}\ni\bm{t}$
the clause width $k(\bm{L})$ equals the same value $K\in\set{k-1,k}$, since $\bm{L}$ must be compatible with $\bm{t}$. Recall from Definition~\ref{d:white.violet} that a clause coloring
$\smash{\vec{\sigma}}\in(\mathscr{X}^K)^2$
defines an element
$\smash{\vec{\varsigma}}\in(\mathscr{S}^K)^2$. Let
	\[
	\SPIN{N}
	\equiv
	\SPIN{N}_j
	\equiv\bigg\{
	\smash{\vec{\sigma}} \in (\mathscr{X}^K)^2
	: \sigma_j \in\set{\SSPIN{y},\SSPIN{b}}^2
	\textup{ and }
	\varsigma_j = \SSPIN{w}\SSPIN{w}
	\bigg\}\,.
	\]
Then, for any (pair) coloring $\smash{\vec{\sigma}}$ on $\mathscr{G}$, let
	\[
	F(\bm{t},\smash{\vec{\sigma}})
	\equiv
	\bigg\{ a\in F(\bm{t}) : 
		\smash{\vec{\sigma}}_{\delta a}\in\SPIN{N}\bigg\}
	\subseteq F(\bm{t})\,.
	\]
\bemph{Within $F(\bm{t},\smash{\vec{\sigma}})$ only,} because each clause has $\varsigma_j=\SSPIN{w}\SSPIN{w}$, we are free to reassign the value of $\sigma_j$ to any other color in $\set{\SSPIN{y},\SSPIN{b}}^2$, provided we continue to respect $\pi$ and the judicious constraints. Let $\mathbf{P}\equiv\mathbf{P}_{\bm{t}}$ be the probability measure
	\[
	\mathbf{P}\bigg(\bm{L},\smash{\vec{\sigma}}_{\delta a}=\smash{\vec{\sigma}}\bigg)
	=\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t})
	\cdot \hat{\nu}_{\bm{L}}\bigg(\smash{\vec{\sigma}}_{\delta a}=\smash{\vec{\sigma}}
		\bigg)\,,
	\]
so $\mathbf{P}$ represents the empirical measure of clause types and colorings within $F(\bm{t})$. 
Note that marginal of $\mathbf{P}$ on $\bm{L}$ is $\mathbf{P}(\bm{L})=\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t})$, while the marginal on $\sigma_j$ (for $j=j(\bm{t})$) is $\bm{L}(\sigma_j=\sigma)=\pi_{\bm{t}}(\sigma)$. Let $\zeta$ be the empirical measure for the $j$-th edges of the clauses in $F(\bm{t},\smash{\vec{\sigma}})$, i.e.,
	\[
	\zeta(\sigma,\bm{L})
	= \mathbf{P}\bigg(
		\bm{L},\sigma_j=\sigma
		\,\bigg|\,\SPIN{N}
		\bigg)\,,
	\]
where $\SPIN{N}$ is shorthand for the event that $\smash{\vec{\sigma}}\in\SPIN{N}$. If $\hat{\nu}$ is the maximizer as in \eqref{e:max.entropy.hbh.given.pi} or \eqref{e:max.entropy.hbh.given.pi.comb}, then $\zeta$ must satisfy
	\begin{equation}\label{e:final.reduction.for.going.from.t.to.L}
	\zeta=\textup{arg\,max}_\zeta\left\{
	\begin{array}{c}\mathcal{H}(\zeta):
	\zeta(\bm{L}) = \mathbf{P}(\bm{L}\,|\,\SPIN{N}) \ \forall \bm{L},\\
	\zeta(\sigma) = \mathbf{P}(\sigma_j=\sigma\,|\,\SPIN{N})
		\ \forall \sigma\in\set{\SSPIN{y},\SSPIN{b}}^2,\\
	\zeta(\tau\,|\,\bm{L})
		=\mathbf{P}((\sigma_j)^i=\tau\,|\,\SPIN{N},\bm{L})
		\ \forall \tau\in\set{\SSPIN{y},\SSPIN{b}}
	\end{array}\right\}\,.
	\end{equation}
By the method of Lagrange multipliers, there exist (real-valued) weights
$\gamma$, $\beta(\bm{L})$ , $(\beta_{\bm{L}})^1$, $(\beta_{\bm{L}})^2$ 
such that
	\begin{equation}\label{e:zeta.lagrangian}
	\zeta(\bm{L},\sigma)\cong\exp\Bigg\{
		\gamma\Ind{\sigma^1\ne\sigma^2}
			+\beta(\bm{L})
		+2\sum_{i=1,2}
			(\beta_{\bm{L}})^i
				\Ind{\sigma^i=\SSPIN{b}}
		\Bigg\}\,,
	\end{equation}
where $\gamma$ can be chosen independently of $\bm{L}$ since its purpose is to enforce the constraint on $\zeta(\sigma)$. (The weights $(\beta_{\bm{L}})^i$ are multiplied by a factor of two for convenience in subsequent calculations.)\smallskip

\noindent\bemph{Step 2. Estimation of marginals for \eqref{e:zeta.lagrangian}.} Note that since $\bm{t}$ was assumed to be a non-compound edge type, any clause type $\bm{L}\ni\bm{t}$ must be nice. It then follows from the judicious condition, Definition~\ref{d:nice}, and Lemma~\ref{l:lotsOfAs} that for all $\bm{L}\ni\bm{t}$ we have
	\begin{equation}\label{e:mostly.N}
	1\ge \hat{\nu}_{\bm{L}}(\SPIN{N})
	\ge
	\hat{\nu}_{\bm{L}}\Big(\varsigma_j=\SSPIN{w}\SSPIN{w}\Big)
	-\sum_{i=1,2}
	\overbrace{\hat{\nu}_{\bm{L}}\Big( (\sigma_j)^i=\SSPIN{g}\Big)}^{{}_\star\hspace{-1pt}\pi_{\bm{t}}(\SSPIN{g})}
	\ge
	1-O\bigg(\frac{k^2}{2^k}\bigg)\,.
	\end{equation}
As a result, the quantities appearing in \eqref{e:final.reduction.for.going.from.t.to.L} can be written more explicitly and estimated as follows:
	\[\zeta(\bm{L})=\mathbf{P}(\bm{L}\,|\,\SPIN{N})
	=\frac{ \pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t})
		\hat{\nu}_{\bm{L}}(\SPIN{N})}
		{\sum_{\bm{L}'} \pi_{\mathscr{D}}(\bm{L}'\,|\,\bm{t})
		\hat{\nu}_{\bm{L}'}(\SPIN{N})}
	\stackrel{\eqref{e:mostly.N}}{=}
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t})
	\Bigg\{ 1- O\bigg( \frac{k^2}{2^k}\bigg)\Bigg\}\,,
	\]
i.e., the clause type proportions within $F(\bm{t},\smash{\vec{\sigma}})$ are close to those within $F(\bm{t})$. Next, for each $\sigma\in\set{\SSPIN{y},\SSPIN{b}}^2$, we have
	\[\zeta(\sigma)=
	\mathbf{P}\Big(\sigma_j=\sigma\,\Big|\,\SPIN{N}\Big)



	= \frac{\pi_{\bm{t}}(\sigma)
		-\mathbf{P}(\sigma_j=\sigma,\SPIN{N}^c)}
		{\mathbf{P}(\SPIN{N})}
	\stackrel{\eqref{e:mostly.N}}{=}
	\pi_{\bm{t}}(\sigma)
	-O\bigg( \frac{k^2}{2^k}\bigg)\,,
	\]
where we note that the right-hand side
must be positive by the assumption that $\pi_{\bm{t}}\ge 2^{-k/20}$. 
Finally, for each $\sigma\in\set{\SSPIN{y},\SSPIN{b}}^2$ and each $\bm{L}$, we have
	\begin{equation}\label{e:zeta.close.to.omega}
	\zeta(\sigma\,|\,\bm{L})=
	\mathbf{P}\Big(\sigma_j=\sigma
		\,\Big|\,\SPIN{N},\bm{L}\Big)



	= \frac{\omega_{\bm{L},j}(\sigma) 
		-\mathbf{P}(\sigma_j=\sigma,\SPIN{N}^c\,|\,\bm{L})
		}{\mathbf{P}(\SPIN{N}\,|\,\bm{L})}
	\stackrel{\eqref{e:mostly.N}}{=} 
	\omega_{\bm{L},j}(\sigma) 
	-O\bigg( \frac{k^2}{2^k}\bigg)\,,\end{equation}
where we have not yet shown the right-hand side to be positive. Taking the marginal on the $i$-th copy gives
	\[
	\zeta( \sigma^i=\tau\,|\,\bm{L})=
	\mathbf{P}\Big((\sigma_j)^i=\tau
		\,\Big|\,\SPIN{N},\bm{L}\Big)
	= \frac{{}_\star\hspace{-1pt}\pi_{\bm{t}}(\tau)
		-\mathbf{P}((\sigma_j)^i=\tau,\SPIN{N}^c\,|\,\bm{L})
		}{\mathbf{P}(\SPIN{N}\,|\,\bm{L})}
	\stackrel{\eqref{e:mostly.N}}{=} 
	{}_\star\hspace{-1pt}\pi_{\bm{t}}(\tau)
	-O\bigg( \frac{k^2}{2^k}\bigg)
	\]
for each $\tau\in\set{\SSPIN{y},\SSPIN{b}}$.
This concludes our estimates for the quantities appearing in \eqref{e:final.reduction.for.going.from.t.to.L}. Next, we note that by the judicious condition, for all $\bm{L},j$ we have
	\[\omega_{\bm{L},j}(\SSPIN{y}\SSPIN{b})-\omega_{\bm{L},j}(\SSPIN{b}\SSPIN{y})
	=\bigg\{
	\omega_{\bm{L},j}(\SSPIN{y}\SSPIN{b})+\omega_{\bm{L},j}(\SSPIN{y}\SSPIN{y})
	\bigg\}
	-\bigg\{
	\omega_{\bm{L},j}(\SSPIN{b}\SSPIN{y})+\omega_{\bm{L},j}(\SSPIN{y}\SSPIN{y})
	\bigg\}
	={}_\star\hspace{-1pt}\pi_{\bm{t}}(\SSPIN{y})-{}_\star\hspace{-1pt}\pi(\SSPIN{y})
	=0\,.
	\]
By the judicious condition together with the assumption that $\bm{t}=\bm{L}(j)$ is nice, we also have
	\[
	\omega_{\bm{L},j}(\SSPIN{y}\SSPIN{y})-\omega_{\bm{L},j}(\SSPIN{b}\SSPIN{b})
	=\bigg\{\omega_{\bm{L},j}(\SSPIN{y}\SSPIN{y})
	+\omega_{\bm{L},j}(\SSPIN{b}\SSPIN{y})\bigg\}
	-\bigg\{\omega_{\bm{L},j}(\SSPIN{b}\SSPIN{b})
		+\omega_{\bm{L},j}(\SSPIN{b}\SSPIN{y})
		\bigg\}
	={}_\star\hspace{-1pt}\pi(\SSPIN{y})-{}_\star\hspace{-1pt}\pi(\SSPIN{b})
	=O\bigg( \frac1{2^{k/10}}\bigg)\,.
	\]
Combining with \eqref{e:zeta.close.to.omega} gives,
for all $\bm{L},j$ with $\bm{L}(j)=\bm{t}$, the bound
	\begin{equation}\label{e:zeta.additive.error.small}
	\bigg|\zeta(\SSPIN{y}\SSPIN{y}\,|\,\bm{L})-\zeta(\SSPIN{b}\SSPIN{b}\,|\,\bm{L})\bigg|
	+\bigg|\zeta(\SSPIN{y}\SSPIN{b}\,|\,\bm{L})-\zeta(\SSPIN{b}\SSPIN{y}\,|\,\bm{L})\bigg|
	\le O\bigg( \frac1{2^{k/10}}\bigg)\,.\end{equation}
With these estimates in hand, we now turn to estimating the weights in \eqref{e:zeta.lagrangian}.\smallskip

\noindent\bemph{Step 3. Estimation of Lagrangian weights.}
If $\bm{L}$ satisfies $\zeta(\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}}\,|\,\bm{L})\ge 2^{-k/15}$, then it follows by combining with \eqref{e:zeta.additive.error.small} that
	\[
	\bigg|\frac{\zeta(\SSPIN{y}\SSPIN{b}\,|\,\bm{L})}{\zeta(\SSPIN{b}\SSPIN{y}\,|\,\bm{L})}-1\bigg|
	\le
	\frac{|\zeta(\SSPIN{y}\SSPIN{b}\,|\,\bm{L})-\zeta(\SSPIN{b}\SSPIN{y}\,|\,\bm{L})|
	}{
	\min\set{
	\zeta(\SSPIN{y}\SSPIN{b}\,|\,\bm{L}),\zeta(\SSPIN{b}\SSPIN{y}\,|\,\bm{L})}}
	\stackrel{\eqref{e:zeta.additive.error.small}}{\le}
	O\bigg(\frac{2^{-k/10}}{2^{-k/15}}\bigg)
	=O\bigg( \frac1{2^{k/30}}\bigg)\,.
	\]
On the other hand, from the Lagrangian solution \eqref{e:zeta.lagrangian}, we have
	\[
	\frac{\zeta(\SSPIN{y}\SSPIN{b}\,|\,\bm{L})}{\zeta(\SSPIN{b}\SSPIN{y}\,|\,\bm{L})}
	= \frac{\exp\{\beta(\bm{L})+\gamma+2(\beta_{\bm{L}})^2 \}}
	{\exp\{\beta(\bm{L})+\gamma+2(\beta_{\bm{L}})^1 \}}
	= \exp\bigg\{ 
	2\Big[
	(\beta_{\bm{L}})^2-(\beta_{\bm{L}})^1\Big]\bigg\}\,.
	\]
Comparing the last two displays, we see that
	\begin{equation}\label{e:big.zeta.implies.small.beta}
	\max\bigg\{
	\Big|(\beta_{\bm{L}})^2-(\beta_{\bm{L}})^1\Big| 
	:\bm{L}\ni\bm{t} \textup{ and }\zeta(\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}}\,|\,\bm{L})
		\ge \frac1{2^{k/15}}
	\bigg\}
	\le
	O\bigg( \frac1{2^{k/30}}\bigg)\,.\end{equation}
An entirely similar argument gives
	\begin{equation}\label{e:big.zeta.implies.small.beta.bb}
	\max\bigg\{
	\Big|(\beta_{\bm{L}})^2+(\beta_{\bm{L}})^1\Big| 
	:\bm{L}\ni\bm{t} \textup{ and }\zeta(\set{\SSPIN{y}\SSPIN{y},\SSPIN{b}\SSPIN{b}}\,|\,\bm{L})
		\ge \frac1{2^{k/15}}\bigg\}
	\le
	O\bigg( \frac1{2^{k/30}}\bigg)\,.\end{equation}
Now suppose $\bm{t}$ is such that $\pi_{\bm{t}}(\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}})\ge \chi$
for some $2^{-k/15}\le\chi\le 1/2$. It implies that for \bemph{some} clause type $\bm{L}\ni\bm{t}$, we have
$\zeta(\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}}\,|\,\bm{L}) \ge \chi$. For this particular $\bm{L}$, 
writing $\mathrm{ch}$ for the hyperbolic cosine function, we have
	\begin{align}\nonumber
	\chi &\le \frac{\chi}{1-\chi}
	\le
	\frac{\zeta(\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}}\,|\,\bm{L})}
	{\zeta(\set{\SSPIN{y}\SSPIN{y},\SSPIN{b}\SSPIN{b}}\,|\,\bm{L})}
	= e^\gamma
	\frac{\exp\{2 (\beta_{\bm{L}})^2\}+\exp\{ 2(\beta_{\bm{L}})^1\}}
	{1 + \exp\{2 (\beta_{\bm{L}})^1+2(\beta_{\bm{L}})^2\}}
	= e^\gamma
	\frac{\mathrm{ch}((\beta_{\bm{L}})^1-(\beta_{\bm{L}})^2) }
	{\mathrm{ch}((\beta_{\bm{L}})^1+(\beta_{\bm{L}})^2) }\\
	&\stackrel{\eqref{e:big.zeta.implies.small.beta}}{\le}
	\frac{ e^\gamma
	[1 +O(2^{-k/30})]
	}{\mathrm{ch}((\beta_{\bm{L}})^1+(\beta_{\bm{L}})^2) }
	\le e^\gamma
	\bigg( 1 + O\bigg(\frac1{2^{k/30}}\bigg)\bigg)
	\,.\label{e:gamma.chi.lbd}
	\end{align}
Next, for \bemph{every} clause type $\bm{L}$ such that $\bm{L}\ni\bm{t}$,
since we assumed $\chi\le1/2$,
at least one of the two quantities
$\zeta(\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}}\,|\,\bm{L})$ and
$\zeta(\set{\SSPIN{y}\SSPIN{y},\SSPIN{b}\SSPIN{b}}\,|\,\bm{L})$ must be $\ge\chi$.
If $\zeta(\set{\SSPIN{y}\SSPIN{y},\SSPIN{b}\SSPIN{b}}\,|\,\bm{L})\ge\chi$, then
	\begin{align*}
	\frac{\zeta(\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}}\,|\,\bm{L})}
		{\zeta(\set{\SSPIN{y}\SSPIN{y},\SSPIN{b}\SSPIN{b}}\,|\,\bm{L})}
	&=e^\gamma
	\frac{\mathrm{ch}((\beta_{\bm{L}})^1-(\beta_{\bm{L}})^2) }
	{\mathrm{ch}((\beta_{\bm{L}})^1+(\beta_{\bm{L}})^2) }
	\ge 
	\frac{e^\gamma}{\mathrm{ch}((\beta_{\bm{L}})^1+(\beta_{\bm{L}})^2) }\\
	&\stackrel{\eqref{e:big.zeta.implies.small.beta.bb}}{\ge}
	\frac{e^\gamma}{1+O(2^{-k/30})}
	\stackrel{\eqref{e:gamma.chi.lbd}}{\ge}
	\chi\bigg( 1 - O\bigg(\frac1{2^{k/30}}\bigg)\bigg)
	\,.
	\end{align*}
Combining the two cases
$\zeta(\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}}\,|\,\bm{L})\ge\chi$ and
$\zeta(\set{\SSPIN{y}\SSPIN{y},\SSPIN{b}\SSPIN{b}}\,|\,\bm{L})\ge\chi$ gives
	\[
	\zeta(\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}}\,|\,\bm{L})
	\ge
	\min\bigg\{
	\chi, \frac{\chi[1 -O(2^{-k/30})]}{1
		+\chi[1 -O(2^{-k/30})]}
	\bigg\}
	\ge \frac{2\chi}{3}
	\bigg( 1- O\bigg(\frac1{2^{k/30}}\bigg)\bigg)\,.
	\]
Recalling \eqref{e:zeta.close.to.omega} again, this proves that 
if $\pi_{\bm{t}}(\sigma)\ge 2^{-k/15}$ for $\sigma\in\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}}$,
then
	\[
	\omega_{\bm{L},j}(\sigma)
	\ge \frac{\chi}{4}
	\ge \frac{\pi_{\bm{t}}(\sigma)}{8}\,,
	\]
where the last bound follows by taking
$\chi=\min\set{\pi_{\bm{t}}(\sigma),1/2}$.
The analogous result for
$\sigma\in\set{\SSPIN{y}\SSPIN{y},\SSPIN{b}\SSPIN{b}}$ by a symmetric argument, and this concludes the proof.
\end{proof}

 The proof follows a familiar outline: we first reduce to a simplified constrained entropy maximization problem, then estimate the Lagrangian weights solving that problem to derive the conclusion.\smallskip

\noindent
\bemph{Step 1. Simplified entropy maximization problem.}
From the expression \eqref{e:rate.function.pair.model}
for $\bm{\Phi}_{\mathscr{D},2}$, we see that to optimize
$\bm{\Phi}_{\mathscr{D},2}(\nu)$ given fixed $\pi$, we can optimize separately over the variable and clause empirical measures, $\dot{\nu}$ and $\hat{\nu}$. We can therefore consider $\hat{\nu}$ alone, since it determines $\acute{\omega}$. The optimal $\hat{\nu}$ is given by
	\begin{equation}\label{e:max.entropy.hbh.given.pi}
	\hat{\nu}=\textup{arg\,max}_{\hat{\nu}}
	\Bigg\{
	\mathbb{E}_{\hat{\mathscr{D}}}[\mathcal{H}(\hat{\nu}_{\bm{L}})]
	\equiv
	\sum_{\bm{L}}\hat{\mathscr{D}}(\bm{L}) \mathcal{H}(\hat{\nu}_{\bm{L}})
	: \textup{$\hat{\nu}$ is judicious and 
	consistent with $\pi$}
	\Bigg\}
	\end{equation}
--- this is because $\mathbb{E}_{\hat{\mathscr{D}}}[\mathcal{H}(\hat{\nu}_{\bm{L}})]$ is the only term of \eqref{e:rate.function.pair.model} that varies with $\hat{\nu}$ when $\pi$ is fixed. Equivalently, recalling the combinatorial calculation \eqref{e:config.model.pair.version}, 
$\hat{\nu}$ must satisfy
	\begin{equation}\label{e:max.entropy.hbh.given.pi.comb}
	\hat{\nu}=\textup{arg\,max}_{\hat{\nu}}
	\Bigg\{
	\prod_{\bm{L}}
	\binom{m_{\bm{L}}}{m_{\bm{L}}\hat{\nu}_{\bm{L}}}
	\Bigg\}\,,
	\end{equation}
that is to say, $\hat{\nu}$ is the empirical measure of clause colorings $\smash{\vec{\sigma}}_{\delta a}$ that maximizes entropy subject to marginals $\pi$.

Now, as in the statement of the lemma, let us fix a non-compound edge type $\bm{t}$ such that $\pi_{\bm{t}}(\sigma)\ge 2^{-k/20}$. Denote $j=j(\bm{t})$, and recall that we write $\bm{L}\ni\bm{t}$ if and only if $\bm{L}(j)=\bm{t}$. 
Given $\mathscr{G}=(V,F,E)$, define the subset of clauses
	\[
	F(\bm{t})
	= \bigg\{ a\in F : \bm{L}_a \ni\bm{t}\bigg\}
	\subseteq F\,.
	\]
Note for all $\bm{L}\ni\bm{t}$
the clause width $k(\bm{L})$ equals the same value $K\in\set{k-1,k}$, since $\bm{L}$ must be compatible with $\bm{t}$. Recall from Definition~\ref{d:white.violet} that a clause coloring
$\smash{\vec{\sigma}}\in(\mathscr{X}^K)^2$
defines an element
$\smash{\vec{\varsigma}}\in(\mathscr{S}^K)^2$. Let
	\[
	\SPIN{N}
	\equiv
	\SPIN{N}_j
	\equiv\bigg\{
	\smash{\vec{\sigma}} \in (\mathscr{X}^K)^2
	: \sigma_j \in\set{\SSPIN{y},\SSPIN{b}}^2
	\textup{ and }
	\varsigma_j = \SSPIN{w}\SSPIN{w}
	\bigg\}\,.
	\]
Then, for any (pair) coloring $\smash{\vec{\sigma}}$ on $\mathscr{G}$, let
	\[
	F(\bm{t},\smash{\vec{\sigma}})
	\equiv
	\bigg\{ a\in F(\bm{t}) : 
		\smash{\vec{\sigma}}_{\delta a}\in\SPIN{N}\bigg\}
	\subseteq F(\bm{t})\,.
	\]
\bemph{Within $F(\bm{t},\smash{\vec{\sigma}})$ only,} because each clause has $\varsigma_j=\SSPIN{w}\SSPIN{w}$, we are free to reassign the value of $\sigma_j$ to any other color in $\set{\SSPIN{y},\SSPIN{b}}^2$, provided we continue to respect $\pi$ and the judicious constraints. Let $\mathbf{P}\equiv\mathbf{P}_{\bm{t}}$ be the probability measure
	\[
	\mathbf{P}\bigg(\bm{L},\smash{\vec{\sigma}}_{\delta a}=\smash{\vec{\sigma}}\bigg)
	=\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t})
	\cdot \hat{\nu}_{\bm{L}}\bigg(\smash{\vec{\sigma}}_{\delta a}=\smash{\vec{\sigma}}
		\bigg)\,,
	\]
so $\mathbf{P}$ represents the empirical measure of clause types and colorings within $F(\bm{t})$. 
Note that marginal of $\mathbf{P}$ on $\bm{L}$ is $\mathbf{P}(\bm{L})=\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t})$, while the marginal on $\sigma_j$ (for $j=j(\bm{t})$) is $\bm{L}(\sigma_j=\sigma)=\pi_{\bm{t}}(\sigma)$. Let $\zeta$ be the empirical measure for the $j$-th edges of the clauses in $F(\bm{t},\smash{\vec{\sigma}})$, i.e.,
	\[
	\zeta(\sigma,\bm{L})
	= \mathbf{P}\bigg(
		\bm{L},\sigma_j=\sigma
		\,\bigg|\,\SPIN{N}
		\bigg)\,,
	\]
where $\SPIN{N}$ is shorthand for the event that $\smash{\vec{\sigma}}\in\SPIN{N}$. If $\hat{\nu}$ is the maximizer as in \eqref{e:max.entropy.hbh.given.pi} or \eqref{e:max.entropy.hbh.given.pi.comb}, then $\zeta$ must satisfy
	\begin{equation}\label{e:final.reduction.for.going.from.t.to.L}
	\zeta=\textup{arg\,max}_\zeta\left\{
	\begin{array}{c}\mathcal{H}(\zeta):
	\zeta(\bm{L}) = \mathbf{P}(\bm{L}\,|\,\SPIN{N}) \ \forall \bm{L},\\
	\zeta(\sigma) = \mathbf{P}(\sigma_j=\sigma\,|\,\SPIN{N})
		\ \forall \sigma\in\set{\SSPIN{y},\SSPIN{b}}^2,\\
	\zeta(\tau\,|\,\bm{L})
		=\mathbf{P}((\sigma_j)^i=\tau\,|\,\SPIN{N},\bm{L})
		\ \forall \tau\in\set{\SSPIN{y},\SSPIN{b}}
	\end{array}\right\}\,.
	\end{equation}
By the method of Lagrange multipliers, there exist (real-valued) weights
$\gamma$, $\beta(\bm{L})$ , $(\beta_{\bm{L}})^1$, $(\beta_{\bm{L}})^2$ 
such that
	\begin{equation}\label{e:zeta.lagrangian}
	\zeta(\bm{L},\sigma)\cong\exp\Bigg\{
		\gamma\Ind{\sigma^1\ne\sigma^2}
			+\beta(\bm{L})
		+2\sum_{i=1,2}
			(\beta_{\bm{L}})^i
				\Ind{\sigma^i=\SSPIN{b}}
		\Bigg\}\,,
	\end{equation}
where $\gamma$ can be chosen independently of $\bm{L}$ since its purpose is to enforce the constraint on $\zeta(\sigma)$. (The weights $(\beta_{\bm{L}})^i$ are multiplied by a factor of two for convenience in subsequent calculations.)\smallskip

\noindent\bemph{Step 2. Estimation of marginals for \eqref{e:zeta.lagrangian}.} Note that since $\bm{t}$ was assumed to be a non-compound edge type, any clause type $\bm{L}\ni\bm{t}$ must be nice. It then follows from the judicious condition, Definition~\ref{d:nice}, and Lemma~\ref{l:lotsOfAs} that for all $\bm{L}\ni\bm{t}$ we have
	\begin{equation}\label{e:mostly.N}
	1\ge \hat{\nu}_{\bm{L}}(\SPIN{N})
	\ge
	\hat{\nu}_{\bm{L}}\Big(\varsigma_j=\SSPIN{w}\SSPIN{w}\Big)
	-\sum_{i=1,2}
	\overbrace{\hat{\nu}_{\bm{L}}\Big( (\sigma_j)^i=\SSPIN{g}\Big)}^{{}_\star\hspace{-1pt}\pi_{\bm{t}}(\SSPIN{g})}
	\ge
	1-O\bigg(\frac{k^2}{2^k}\bigg)\,.
	\end{equation}
As a result, the quantities appearing in \eqref{e:final.reduction.for.going.from.t.to.L} can be written more explicitly and estimated as follows:
	\[\zeta(\bm{L})=\mathbf{P}(\bm{L}\,|\,\SPIN{N})
	=\frac{ \pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t})
		\hat{\nu}_{\bm{L}}(\SPIN{N})}
		{\sum_{\bm{L}'} \pi_{\mathscr{D}}(\bm{L}'\,|\,\bm{t})
		\hat{\nu}_{\bm{L}'}(\SPIN{N})}
	\stackrel{\eqref{e:mostly.N}}{=}
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t})
	\Bigg\{ 1- O\bigg( \frac{k^2}{2^k}\bigg)\Bigg\}\,,
	\]
i.e., the clause type proportions within $F(\bm{t},\smash{\vec{\sigma}})$ are close to those within $F(\bm{t})$. Next, for each $\sigma\in\set{\SSPIN{y},\SSPIN{b}}^2$, we have
	\[\zeta(\sigma)=
	\mathbf{P}\Big(\sigma_j=\sigma\,\Big|\,\SPIN{N}\Big)



	= \frac{\pi_{\bm{t}}(\sigma)
		-\mathbf{P}(\sigma_j=\sigma,\SPIN{N}^c)}
		{\mathbf{P}(\SPIN{N})}
	\stackrel{\eqref{e:mostly.N}}{=}
	\pi_{\bm{t}}(\sigma)
	-O\bigg( \frac{k^2}{2^k}\bigg)\,,
	\]
where we note that the right-hand side
must be positive by the assumption that $\pi_{\bm{t}}\ge 2^{-k/20}$. 
Finally, for each $\sigma\in\set{\SSPIN{y},\SSPIN{b}}^2$ and each $\bm{L}$, we have
	\begin{equation}\label{e:zeta.close.to.omega}
	\zeta(\sigma\,|\,\bm{L})=
	\mathbf{P}\Big(\sigma_j=\sigma
		\,\Big|\,\SPIN{N},\bm{L}\Big)



	= \frac{\omega_{\bm{L},j}(\sigma) 
		-\mathbf{P}(\sigma_j=\sigma,\SPIN{N}^c\,|\,\bm{L})
		}{\mathbf{P}(\SPIN{N}\,|\,\bm{L})}
	\stackrel{\eqref{e:mostly.N}}{=} 
	\omega_{\bm{L},j}(\sigma) 
	-O\bigg( \frac{k^2}{2^k}\bigg)\,,\end{equation}
where we have not yet shown the right-hand side to be positive. Taking the marginal on the $i$-th copy gives
	\[
	\zeta( \sigma^i=\tau\,|\,\bm{L})=
	\mathbf{P}\Big((\sigma_j)^i=\tau
		\,\Big|\,\SPIN{N},\bm{L}\Big)
	= \frac{{}_\star\hspace{-1pt}\pi_{\bm{t}}(\tau)
		-\mathbf{P}((\sigma_j)^i=\tau,\SPIN{N}^c\,|\,\bm{L})
		}{\mathbf{P}(\SPIN{N}\,|\,\bm{L})}
	\stackrel{\eqref{e:mostly.N}}{=} 
	{}_\star\hspace{-1pt}\pi_{\bm{t}}(\tau)
	-O\bigg( \frac{k^2}{2^k}\bigg)
	\]
for each $\tau\in\set{\SSPIN{y},\SSPIN{b}}$.
This concludes our estimates for the quantities appearing in \eqref{e:final.reduction.for.going.from.t.to.L}. Next, we note that by the judicious condition, for all $\bm{L},j$ we have
	\[\omega_{\bm{L},j}(\SSPIN{y}\SSPIN{b})-\omega_{\bm{L},j}(\SSPIN{b}\SSPIN{y})
	=\bigg\{
	\omega_{\bm{L},j}(\SSPIN{y}\SSPIN{b})+\omega_{\bm{L},j}(\SSPIN{y}\SSPIN{y})
	\bigg\}
	-\bigg\{
	\omega_{\bm{L},j}(\SSPIN{b}\SSPIN{y})+\omega_{\bm{L},j}(\SSPIN{y}\SSPIN{y})
	\bigg\}
	={}_\star\hspace{-1pt}\pi_{\bm{t}}(\SSPIN{y})-{}_\star\hspace{-1pt}\pi(\SSPIN{y})
	=0\,.
	\]
By the judicious condition together with the assumption that $\bm{t}=\bm{L}(j)$ is nice, we also have
	\[
	\omega_{\bm{L},j}(\SSPIN{y}\SSPIN{y})-\omega_{\bm{L},j}(\SSPIN{b}\SSPIN{b})
	=\bigg\{\omega_{\bm{L},j}(\SSPIN{y}\SSPIN{y})
	+\omega_{\bm{L},j}(\SSPIN{b}\SSPIN{y})\bigg\}
	-\bigg\{\omega_{\bm{L},j}(\SSPIN{b}\SSPIN{b})
		+\omega_{\bm{L},j}(\SSPIN{b}\SSPIN{y})
		\bigg\}
	={}_\star\hspace{-1pt}\pi(\SSPIN{y})-{}_\star\hspace{-1pt}\pi(\SSPIN{b})
	=O\bigg( \frac1{2^{k/10}}\bigg)\,.
	\]
Combining with \eqref{e:zeta.close.to.omega} gives,
for all $\bm{L},j$ with $\bm{L}(j)=\bm{t}$, the bound
	\begin{equation}\label{e:zeta.additive.error.small}
	\bigg|\zeta(\SSPIN{y}\SSPIN{y}\,|\,\bm{L})-\zeta(\SSPIN{b}\SSPIN{b}\,|\,\bm{L})\bigg|
	+\bigg|\zeta(\SSPIN{y}\SSPIN{b}\,|\,\bm{L})-\zeta(\SSPIN{b}\SSPIN{y}\,|\,\bm{L})\bigg|
	\le O\bigg( \frac1{2^{k/10}}\bigg)\,.\end{equation}
With these estimates in hand, we now turn to estimating the weights in \eqref{e:zeta.lagrangian}.\smallskip

\noindent\bemph{Step 3. Estimation of Lagrangian weights.}
If $\bm{L}$ satisfies $\zeta(\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}}\,|\,\bm{L})\ge 2^{-k/15}$, then it follows by combining with \eqref{e:zeta.additive.error.small} that
	\[
	\bigg|\frac{\zeta(\SSPIN{y}\SSPIN{b}\,|\,\bm{L})}{\zeta(\SSPIN{b}\SSPIN{y}\,|\,\bm{L})}-1\bigg|
	\le
	\frac{|\zeta(\SSPIN{y}\SSPIN{b}\,|\,\bm{L})-\zeta(\SSPIN{b}\SSPIN{y}\,|\,\bm{L})|
	}{
	\min\set{
	\zeta(\SSPIN{y}\SSPIN{b}\,|\,\bm{L}),\zeta(\SSPIN{b}\SSPIN{y}\,|\,\bm{L})}}
	\stackrel{\eqref{e:zeta.additive.error.small}}{\le}
	O\bigg(\frac{2^{-k/10}}{2^{-k/15}}\bigg)
	=O\bigg( \frac1{2^{k/30}}\bigg)\,.
	\]
On the other hand, from the Lagrangian solution \eqref{e:zeta.lagrangian}, we have
	\[
	\frac{\zeta(\SSPIN{y}\SSPIN{b}\,|\,\bm{L})}{\zeta(\SSPIN{b}\SSPIN{y}\,|\,\bm{L})}
	= \frac{\exp\{\beta(\bm{L})+\gamma+2(\beta_{\bm{L}})^2 \}}
	{\exp\{\beta(\bm{L})+\gamma+2(\beta_{\bm{L}})^1 \}}
	= \exp\bigg\{ 
	2\Big[
	(\beta_{\bm{L}})^2-(\beta_{\bm{L}})^1\Big]\bigg\}\,.
	\]
Comparing the last two displays, we see that
	\begin{equation}\label{e:big.zeta.implies.small.beta}
	\max\bigg\{
	\Big|(\beta_{\bm{L}})^2-(\beta_{\bm{L}})^1\Big| 
	:\bm{L}\ni\bm{t} \textup{ and }\zeta(\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}}\,|\,\bm{L})
		\ge \frac1{2^{k/15}}
	\bigg\}
	\le
	O\bigg( \frac1{2^{k/30}}\bigg)\,.\end{equation}
An entirely similar argument gives
	\begin{equation}\label{e:big.zeta.implies.small.beta.bb}
	\max\bigg\{
	\Big|(\beta_{\bm{L}})^2+(\beta_{\bm{L}})^1\Big| 
	:\bm{L}\ni\bm{t} \textup{ and }\zeta(\set{\SSPIN{y}\SSPIN{y},\SSPIN{b}\SSPIN{b}}\,|\,\bm{L})
		\ge \frac1{2^{k/15}}\bigg\}
	\le
	O\bigg( \frac1{2^{k/30}}\bigg)\,.\end{equation}
Now suppose $\bm{t}$ is such that $\pi_{\bm{t}}(\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}})\ge \chi$
for some $2^{-k/15}\le\chi\le 1/2$. It implies that for \bemph{some} clause type $\bm{L}\ni\bm{t}$, we have
$\zeta(\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}}\,|\,\bm{L}) \ge \chi$. For this particular $\bm{L}$, 
writing $\mathrm{ch}$ for the hyperbolic cosine function, we have
	\begin{align}\nonumber
	\chi &\le \frac{\chi}{1-\chi}
	\le
	\frac{\zeta(\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}}\,|\,\bm{L})}
	{\zeta(\set{\SSPIN{y}\SSPIN{y},\SSPIN{b}\SSPIN{b}}\,|\,\bm{L})}
	= e^\gamma
	\frac{\exp\{2 (\beta_{\bm{L}})^2\}+\exp\{ 2(\beta_{\bm{L}})^1\}}
	{1 + \exp\{2 (\beta_{\bm{L}})^1+2(\beta_{\bm{L}})^2\}}
	= e^\gamma
	\frac{\mathrm{ch}((\beta_{\bm{L}})^1-(\beta_{\bm{L}})^2) }
	{\mathrm{ch}((\beta_{\bm{L}})^1+(\beta_{\bm{L}})^2) }\\
	&\stackrel{\eqref{e:big.zeta.implies.small.beta}}{\le}
	\frac{ e^\gamma
	[1 +O(2^{-k/30})]
	}{\mathrm{ch}((\beta_{\bm{L}})^1+(\beta_{\bm{L}})^2) }
	\le e^\gamma
	\bigg( 1 + O\bigg(\frac1{2^{k/30}}\bigg)\bigg)
	\,.\label{e:gamma.chi.lbd}
	\end{align}
Next, for \bemph{every} clause type $\bm{L}$ such that $\bm{L}\ni\bm{t}$,
since we assumed $\chi\le1/2$,
at least one of the two quantities
$\zeta(\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}}\,|\,\bm{L})$ and
$\zeta(\set{\SSPIN{y}\SSPIN{y},\SSPIN{b}\SSPIN{b}}\,|\,\bm{L})$ must be $\ge\chi$.
If $\zeta(\set{\SSPIN{y}\SSPIN{y},\SSPIN{b}\SSPIN{b}}\,|\,\bm{L})\ge\chi$, then
	\begin{align*}
	\frac{\zeta(\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}}\,|\,\bm{L})}
		{\zeta(\set{\SSPIN{y}\SSPIN{y},\SSPIN{b}\SSPIN{b}}\,|\,\bm{L})}
	&=e^\gamma
	\frac{\mathrm{ch}((\beta_{\bm{L}})^1-(\beta_{\bm{L}})^2) }
	{\mathrm{ch}((\beta_{\bm{L}})^1+(\beta_{\bm{L}})^2) }
	\ge 
	\frac{e^\gamma}{\mathrm{ch}((\beta_{\bm{L}})^1+(\beta_{\bm{L}})^2) }\\
	&\stackrel{\eqref{e:big.zeta.implies.small.beta.bb}}{\ge}
	\frac{e^\gamma}{1+O(2^{-k/30})}
	\stackrel{\eqref{e:gamma.chi.lbd}}{\ge}
	\chi\bigg( 1 - O\bigg(\frac1{2^{k/30}}\bigg)\bigg)
	\,.
	\end{align*}
Combining the two cases
$\zeta(\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}}\,|\,\bm{L})\ge\chi$ and
$\zeta(\set{\SSPIN{y}\SSPIN{y},\SSPIN{b}\SSPIN{b}}\,|\,\bm{L})\ge\chi$ gives
	\[
	\zeta(\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}}\,|\,\bm{L})
	\ge
	\min\bigg\{
	\chi, \frac{\chi[1 -O(2^{-k/30})]}{1
		+\chi[1 -O(2^{-k/30})]}
	\bigg\}
	\ge \frac{2\chi}{3}
	\bigg( 1- O\bigg(\frac1{2^{k/30}}\bigg)\bigg)\,.
	\]
Recalling \eqref{e:zeta.close.to.omega} again, this proves that 
if $\pi_{\bm{t}}(\sigma)\ge 2^{-k/15}$ for $\sigma\in\set{\SSPIN{y}\SSPIN{b},\SSPIN{b}\SSPIN{y}}$,
then
	\[
	\omega_{\bm{L},j}(\sigma)
	\ge \frac{\chi}{4}
	\ge \frac{\pi_{\bm{t}}(\sigma)}{8}\,,
	\]
where the last bound follows by taking
$\chi=\min\set{\pi_{\bm{t}}(\sigma),1/2}$.
The analogous result for
$\sigma\in\set{\SSPIN{y}\SSPIN{y},\SSPIN{b}\SSPIN{b}}$ by a symmetric argument, and this concludes the proof.

\label{l:lotsOfAsDiverse}
Let $a$ be a clause of type $\bm{L}$ which is both nice
(meaning $\bm{t}$ is nice for all $\bm{t}\in\bm{L}$) and diverse (Definition~\ref{d:diverse}). Given $\omega\in\bm{I}_0$, let $\hat{\nu}_{\bm{L}}$ be the probability measure on valid (pair) colorings $\smash{\vec{\sigma}}_{\delta a}$ which maximizes entropy subject to edge marginals $(\omega_{\bm{L},j})_j$. Recall from Definition~\ref{d:white.violet} that
each $\smash{\vec{\sigma}}_{\delta a}$ maps to a configuration
$\smash{\vec{\varsigma}}_{\delta a}\in(\mathscr{S}^2)^{\delta a}$. Let
	{\setlength{\jot}{0pt}\begin{align*}
	\SPIN{A}
	&\equiv \{\smash{\vec{\sigma}}_{\delta a}
	: \sigma_e\ne\SSPIN{r}\SSPIN{r} \textup{ for all }e\in\delta a\}\,,\\
	\SPIN{W}^i
	&\equiv \{\smash{\vec{\sigma}}_{\delta a}
	: (\varsigma_e)^i
	=\SSPIN{w} \textup{ for all }e\in\delta a\}\,.
	\end{align*}}
There exists an absolute constant $\epsilon_1>0$ such that
	\begin{equation}\label{e:lotsOfAsDiverse.conditional}
	1-\hat{\nu}_{\bm{L}}
	\Big(\SPIN{W}^1 \cup \SPIN{W}^2
	\,\Big|\, \SPIN{A}\Big)
	\le \frac1{2^{k(1+\epsilon_1)}}\,.
	\end{equation}
If in addition $\bm{L}$ is light (Definition~\ref{d:heavy}), then it follows immediately that
	\begin{equation}\label{e:lotsOfAsDiverse.uncond}
	1-\hat{\nu}_{\bm{L}}\Big(\SPIN{W}^1 \cup \SPIN{W}^2\Big)
	\le \frac1{2^{k(1+\epsilon_1)}}
	+ \frac{k}{2^{k(1+\epsilon_\circ)}}
	\le O\bigg(\frac{k}{2^{k(1+\epsilon_\circ)}}\bigg)\,,
	\end{equation}
where we can assume that $\epsilon_\circ\le\epsilon_1$.

\begin{proof} 
It is an immediate consequence of Lemma~\ref{l:indifferent}
that if $\bm{L}$ is both nice and diverse, then
	\begin{equation}\label{e:diverse.clause}
	\sum_{j=1}^{k(\bm{L})}
	\mathbf{1}\bigg\{
		\omega_{\bm{L},j}\Big(
		\set{\SSPIN{b}\SSPIN{y},\SSPIN{y}\SSPIN{b}}\Big)
	\ge \frac1{33}
	\bigg\}
	\ge \sum_{j=1}^{k(\bm{L})}
	\mathbf{1}\bigg\{\omega_{\bm{L},j}(\SSPIN{y}\SSPIN{b})
		\ge \frac1{65}
	\bigg\}
	\ge \frac{k}{10}\,.
	\end{equation}
In this proof, by the same reasoning as in the proof of Lemma~\ref{l:lotsOfAs} (see \eqref{e:bg.given.cyan}), it suffices to take $\sigma$ in the reduced alphabet $\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}$. We also abbreviate $\SSPIN{u}\equiv\set{\SSPIN{y},\SSPIN{c}}$. Throughout the following, $\epsilon_1$ denotes a small positive number, whose value may change from one occurrence to the next, but ultimately is taken as an absolute constant. We denote the clause width by $K\equiv k(\bm{L})\in\set{k-1,k}$.
\smallskip

\noindent\bemph{Step 1. Reduction to entropy maximization for a conditional measure.} As in the statement of the lemma, let $\hat{\nu}_{\bm{L}}$ be the optimizer given marginals $\omega$. Note that since $\omega$ is judicious and $\bm{L}$ is nice,
	\[
	\hat{\nu}_{\bm{L}}(\SPIN{A}^c)
	\le\sum_{j=1}^K
	\omega_{\bm{L},j}(\SSPIN{r}\SSPIN{r})
	\le\sum_{i=1,2}
	\sum_{j=1}^K
	(\omega_{\bm{L},j})^i(\SSPIN{r})
	= 2\sum_{j=1}^K {}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\SSPIN{r})
	\le O\bigg( \frac{k}{2^k}\bigg)\,.
	\]
Let $\mu(\smash{\vec{\sigma}})\equiv \hat{\nu}_{\bm{L}}(\smash{\vec{\sigma}}\,|\, \SPIN{A})$
for $\smash{\vec{\sigma}}\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^{2K}$. For each edge $1\le j\le K$, let $\mu_j$ be the marginal of $\mu$ on the $j$-th edge in $\delta a$. Thus $\mu_j$ is a probability measure over $\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2\setminus\set{\SSPIN{r}\SSPIN{r}}$, and the preceding estimate implies
	\begin{equation}\label{e:cond.on.A.mgl.effect}
	\mu_j(\sigma)
	=\frac{\hat{\nu}_{\bm{L}}(\sigma_j=\sigma)
		-\hat{\nu}_{\bm{L}}(\sigma_j=\sigma;\SPIN{A}^c)}
		{1-\hat{\nu}_{\bm{L}}(\SPIN{A}^c)}
	= \begin{cases}
	\omega_{\bm{L},j}(\sigma) +O(k/2^k)
		&\textup{if $\SSPIN{r}[\sigma]=0$,} \\
	\omega_{\bm{L},j}(\sigma) +O(1/2^k)
		&\textup{if $\SSPIN{r}[\sigma]=1$,}
	\end{cases}
	\end{equation}
where the last bound uses that $\hat{\nu}_{\bm{L}}(\sigma_j=\sigma)\le O(1/2^k)$ if $\SSPIN{r}[\sigma]=1$. The measure $\mu$ maximizes entropy subject to the edge marginals $\mu_j$. Similarly as in the preceding proofs of this section, we shall construct a sequence of Lagrangian weights $b_{j,t}$ such that the measure
	\begin{equation}\label{e:mu.t.as.fn.of.b.t}
	 \mu_t(\smash{\vec{\sigma}})
	= \frac{ \Ind{\smash{\vec{\sigma}}\in\SPIN{A}}}{Z_t}
	\prod_{j=1}^K b_{j,t}(\sigma_j)\end{equation}
converges to the desired $\mu$ as $t\to\infty$, where $Z_t$ is the normalizing constant. Let $\mu_{j,t}$ denote the marginals of the measure $\mu_t$.\smallskip

\noindent\bemph{Step 2. Initalization of Lagrangian weights.} We initialize the construction with
	\begin{equation}\label{e:burnin.reweight.power.of.two}
	b_{j,0}(\sigma)
	\equiv
	\frac{\mu_j(\sigma)}{1/ (2^{K-1})^{\SSPIN{r}[\sigma]}}\,,\quad
	\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2\setminus\set{\SSPIN{r}\SSPIN{r}}\,.
	\end{equation}
We first estimate the marginals $\mu_{j,0}$ of the resulting measure $\mu_0$. Recall that we denote $\SSPIN{u}\equiv\set{\SSPIN{y},\SSPIN{c}}$. Note that \eqref{e:cond.on.A.mgl.effect}, together with the judicious condition and the assumption that $\bm{L}$ is nice, gives
	\begin{equation}\label{e:zeta.u.u.estimates}
	\mu_j(\SSPIN{u}\SSPIN{u})=1-O\bigg(\frac{k}{2^k}\bigg)\,,\quad
	\sum_{\tau\in\set{\SSPIN{y},\SSPIN{c}}}
	\Bigg\{
	\bigg|\mu_j(\tau\SSPIN{u})-\frac12\bigg|
	+\bigg|\mu_j(\SSPIN{u}\tau)-\frac12\bigg|\Bigg\}
	 \le \frac1{2^{k\epsilon_1}}\,.
	\end{equation}
Moreover, it follows from the diverse clause condition \eqref{e:burnin.reweight.power.of.two} together with \eqref{e:cond.on.A.mgl.effect} that
	\begin{equation}\label{e:diverse.clause.zeta}
	\sum_{j=1}^{k(\bm{L})}
	\mathbf{1}\bigg\{
	\min\Big\{	 \mu_j(\SSPIN{y}\SSPIN{b}),\mu_j(\SSPIN{b}\SSPIN{y})\Big\}
	\ge \frac1{65}
	\bigg\}
	\ge \frac{k}{10}\,.
	\end{equation}
Without loss of generality we now focus on the marginal on the edge indexed $j=1$: at time $t=0$, 
	\[
	Z_0\mu_{1,0}(\SSPIN{c}\SSPIN{c})
	= \mu_1(\SSPIN{c}\SSPIN{c})
	\Bigg\{
	\prod_{\ell=2}^K\mu_\ell(\SSPIN{u}\SSPIN{u})
	-\prod_{\ell=2}^K\mu_\ell(\SSPIN{u}\SSPIN{y})
	-\prod_{\ell=2}^K\mu_\ell(\SSPIN{y}\SSPIN{u})
	+\prod_{\ell=2}^K\mu_\ell(\SSPIN{y}\SSPIN{y})
	\Bigg\}
	\stackrel{\eqref{e:zeta.u.u.estimates}}{=}
	\mu_1(\SSPIN{c}\SSPIN{c})\Bigg\{ 1 +O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}\,,
	\]
Similar calculations, again using \eqref{e:zeta.u.u.estimates}, give the analogous estimate for $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$.
Next, for $\sigma=\SSPIN{r}\SSPIN{c}$, it follows from \eqref{e:zeta.u.u.estimates}
together with the diversity bound \eqref{e:diverse.clause.zeta} gives
	\begin{align*}
	Z_0\mu_{1,0}(\SSPIN{r}\SSPIN{c})
	&= \Big( \mu_1(\SSPIN{r}\SSPIN{c}) 2^{K-1}\Big)
	\Bigg\{\prod_{\ell=2}^K
	\mu_\ell(\SSPIN{y}\SSPIN{u})
	-\prod_{\ell=2}^K\mu_\ell(\SSPIN{y}\SSPIN{y})\Bigg\}\\
	&=\Big( \mu_1(\SSPIN{r}\SSPIN{c}) 2^{K-1}\Big)
	\frac{1+O(k/2^{k\epsilon_1})}{2^{K-1}}\Bigg\{1
	-\bigg(1-\frac{2}{65}\bigg)^{k/10}
	\Bigg\}
	= \mu_1(\SSPIN{r}\SSPIN{c}) 
	\Bigg\{ 1 +O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}
	\end{align*}
(recalling our convention that $\epsilon_1$ can change from one expression to the next, but remains bounded below by a positive absolute constant). A similar calculation (again using
\eqref{e:zeta.u.u.estimates} and \eqref{e:diverse.clause.zeta}) gives
an analogous estimate for $\sigma=\SSPIN{r}\SSPIN{y}$. Altogether we conclude
	\begin{equation}\label{e:mu.mgl.zeta.base.case}
	\mu_{1,0}(\sigma)
	=\frac{\mu_1(\sigma)}{Z_0}
		\Bigg\{ 1 +O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}
	= \mu_1(\sigma)
		\Bigg\{ 1 +O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}\,.
	\end{equation}
for all $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2\setminus\set{\SSPIN{r}\SSPIN{r}}$.\smallskip

\noindent\bemph{Step 3. Iterative analysis of Lagrangian weights.} Suppose at time $t$ that we have weights $b_{j,t}$, which define a measure $\mu_t$ as in \eqref{e:mu.t.as.fn.of.b.t} with edge marginals $\mu_{j,t}$. We define the updated weights at time $t+1$ by
	\begin{equation}\label{e:lotsOfAsDiverse.beta.update.rule}
	\frac{b_{j,t+1}(\sigma)}{b_{j,t}(\sigma)}
	= \frac{\mu_j(\sigma)}{\mu_{j,t}(\sigma)}\,.
	\end{equation}
We will prove by induction that for all $t\ge0$, all $1\le j\le k(\bm{L})$, and all $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2\setminus\set{\SSPIN{r}\SSPIN{r}}$,
	\begin{equation}\label{e:lotsOfAsDiverse.induct}
	\Bigg|
	\frac{b_{j,t+1}(\sigma)}
		{b_{j,t}(\sigma)}-1 \Bigg|
	=\Bigg|
	\frac{\mu_j(\sigma)}{\mu_{j,t}(\sigma)}-1
	\Bigg|
	\le \frac{ y_{\SSPIN{r}[\sigma]}}{2^{k(t+1)\epsilon_1/3}}\,,\quad
	\begin{pmatrix}y_0 \\ y_1\end{pmatrix}
	= \frac1{2^{3k\epsilon_1/2}}
	\begin{pmatrix}1 \\ 2^{k\epsilon_1/2} \end{pmatrix}\,,
	\end{equation}
where the base case $t=0$ is implied by \eqref{e:mu.mgl.zeta.base.case} (adjusting $\epsilon_1$ appropriately). Suppose then that \eqref{e:lotsOfAsDiverse.induct} holds up to time $t-1\ge0$, and note it implies that for all $j,\sigma$ we have
	\begin{equation}\label{e:lotsOfAsDiverse.induction}
	\Bigg|\ln \frac{b_{j,t}(\sigma)}
		{\mu_j(\sigma) (2^{K-1})^{\SSPIN{r}[\sigma]}}
		\Bigg|
	=\Bigg|\ln \frac{b_{j,t}(\sigma)}{b_{j,0}(\sigma)}
		\Bigg|
	\le \sum_{s=0}^{t-1}
	\Bigg|\ln \frac{b_{j,s+1}(\sigma)}{b_{j,s}(\sigma)}
		\Bigg|
	\stackrel{\eqref{e:lotsOfAsDiverse.induct}}{\le}
		O\bigg( \frac1{2^{k\epsilon_1}}\bigg)\,.
	\end{equation}
To analyze the update \eqref{e:lotsOfAsDiverse.beta.update.rule}, let us focus on the first two edges in the clause, and note that
	\begin{equation}\label{e:derivative.is.covariance}
	\frac{\partial \mu_{1,t}(\sigma)}
		{\partial \ln b_{2,t}(\sigma')}
	=\mathrm{Cov}_{\mu_t}\bigg(
	\Ind{\sigma_1=\sigma},
	\Ind{\sigma_2=\sigma'}
	\bigg)
	\end{equation}
for all $\sigma,\sigma'\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2\setminus\set{\SSPIN{r}\SSPIN{r}}$ (by direct calculation). We therefore define
	\[
	C_t(\sigma,\sigma')
	\equiv
	\frac{Z_t \mu_t(\sigma_1=\sigma,\sigma_2=\sigma')}
		{\mu_{j=1}(\sigma)
		\mu_{j'=2}(\sigma')}\,,
	\]
and proceed to estimate this quantity. In the simplest case $\sigma=\sigma'=\SSPIN{c}\SSPIN{c}$, we have
	\[
	C_t(\SSPIN{c}\SSPIN{c},\SSPIN{c}\SSPIN{c})
	=\frac{b_{1,t}(\SSPIN{c}\SSPIN{c})
	b_{2,t}(\SSPIN{c}\SSPIN{c})}
	{\mu_1(\SSPIN{c}\SSPIN{c})
	\mu_2(\SSPIN{c}\SSPIN{c})}
	\prod_{j=3}^K b_{j,t}(\SSPIN{u}\SSPIN{u})
	\stackrel{\eqref{e:lotsOfAsDiverse.induction}}{=}
	\Bigg\{
	\prod_{j=3}^K \mu_j(\SSPIN{u}\SSPIN{u})
	\Bigg\}
	\Bigg\{1 + O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}
	\stackrel{\eqref{e:zeta.u.u.estimates}}{=}
	1 + O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\,.\]
A similar estimate holds for all cases where
$\SSPIN{r}[\sigma]+\SSPIN{r}[\sigma']=0$. Next,
	\[
	C_t(\SSPIN{r}\SSPIN{c},\SSPIN{y}\SSPIN{c})
	=\frac{ b_{1,t}(\SSPIN{r}\SSPIN{c})b_{2,t}(\SSPIN{y}\SSPIN{c})}
		{\mu_1(\SSPIN{r}\SSPIN{c})\mu_2(\SSPIN{y}\SSPIN{c})}
	\prod_{j=3}^K b_{j,t}(\SSPIN{y}\SSPIN{u})
	\stackrel{\eqref{e:lotsOfAsDiverse.induction}}{=}
	\Bigg\{ 2^{K-1} \prod_{j=3}^K \mu_j(\SSPIN{y}\SSPIN{u})
	\Bigg\}
	\Bigg\{1 + O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}
	\stackrel{\eqref{e:zeta.u.u.estimates}}{=}
	2 \Bigg\{1 + O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}\,,
	\]
and a similar estimate holds for $C_t(\sigma,\sigma')$ in all cases where $\SSPIN{r}[\sigma]+\SSPIN{r}[\sigma']=1$. Finally,
	\[
	C_t(\SSPIN{r}\SSPIN{y},\SSPIN{y}\SSPIN{r})
	= \frac{b_{1,t}(\SSPIN{r}\SSPIN{y}) b_{2,t}(\SSPIN{y}\SSPIN{r})}
		{\mu_1(\SSPIN{r}\SSPIN{y})\mu_2(\SSPIN{y}\SSPIN{r})}
	\prod_{j=3}^K b_{j,t}(\SSPIN{y}\SSPIN{y})
	\stackrel{\eqref{e:lotsOfAsDiverse.induction}}{=}
	(2^{K-1})^2
	\prod_{j=3}^K b_{j,t}(\SSPIN{y}\SSPIN{y})
	\Bigg\{1 + O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}
	\le \frac{2^k}{2^{k\epsilon_1}}\,,
	\]
where the last bound uses the diversity bound \eqref{e:diverse.clause.zeta}. Combining with \eqref{e:derivative.is.covariance} gives
	\begin{align*}
	\Bigg|\frac{\partial \mu_{1,t}(\sigma) /
		\partial \ln b_{2,t}(\sigma')}
		{\mu_{1,t}(\sigma)
		\mu_{2,t}(\sigma')}
		\Bigg|
	&=\Bigg| \overbrace{\Bigg\{
		\frac{Z_t\mu_t(\sigma_1=\sigma,\sigma_2=\sigma')}
		{\mu_1(\sigma)\mu_2(\sigma')}
		\Bigg\}}^{C_t(\sigma,\sigma')}
	\overbrace{\Bigg\{
	\frac{\mu_1(\sigma)\mu_2(\sigma')}
		{Z_t \mu_{1,t}(\sigma)
		\mu_{2,t}(\sigma')}
		\Bigg\}}^{1 + O(2^{-k\epsilon_1})}
		{} -1 \Bigg| \\
	&\le O(1) \begin{cases}
	2^{-k\epsilon_1} & \textup{if 
		$\SSPIN{r}[\sigma]+\SSPIN{r}[\sigma']=0$,}\\
	1 & \textup{if $\SSPIN{r}[\sigma]+\SSPIN{r}[\sigma']=1$,}\\
	2^{k(1-\epsilon_1)} & \textup{if 
		$\SSPIN{r}[\sigma]=\SSPIN{r}[\sigma']=1$.}
	\end{cases}
	\end{align*}
Rewriting the above in a more convenient form gives
	\begin{equation}\label{e:partial.deriv.covar.bound}
	\frac1{\mu_1(\sigma)}
	\Bigg|\frac{\partial \mu_{1,t}(\sigma)}
		{\partial\ln b_{2,t}(\sigma')}
		\Bigg|
	\le O\Big( A_{\SSPIN{r}[\sigma],\SSPIN{r}[\sigma']}
		\Big)\,,\quad
	A = \begin{pmatrix} A_{0,0} & A_{0,1}\\
		A_{1,0} & A_{1,1} \end{pmatrix}
	= \begin{pmatrix} 2^{-k\epsilon_1} & 2^{-k} \\
		1 & 2^{-k\epsilon_1} \end{pmatrix}\,.\end{equation}
Now recall the definition \eqref{e:mu.t.as.fn.of.b.t}
of $\mu_t$, and define
	\[
	\tilde{\mu}_t(\smash{\vec{\sigma}})
	= \frac{ \Ind{\smash{\vec{\sigma}}\in\SPIN{A}}}{Z_t}
	b_{1,t}(\sigma_1)
	\prod_{j=2}^K b_{j,t-1}(\sigma_j)\,.
	\]
It follows from the update rule \eqref{e:lotsOfAsDiverse.beta.update.rule} that the marginal of $\tilde{\mu}_t$ on the first edge is precisely $\mu_1$. Consequently,
	\begin{align*}
	\Bigg|
	\frac{b_{1,t+1}(\sigma)}
		{b_{1,t}(\sigma)}-1 \Bigg|
	&\stackrel{\eqref{e:lotsOfAsDiverse.beta.update.rule}}{=}\Bigg|
	\frac{\tilde{\mu}_t(\sigma_1=\sigma)}
		{\mu_t(\sigma_1=\sigma)}-1
	\Bigg|
	\le \frac{O(1)}{\mu_1(\sigma)}
	\sum_{j=2}^K\sum_{\sigma'}
	\Bigg| \frac{\partial\mu_{1,t}(\sigma)}
		{\partial \ln b_{j,t}(\sigma')}\Bigg|
	\cdot
	\Bigg|\ln \frac{b_{j,t}(\sigma')}
		{b_{j,t-1}(\sigma')}\Bigg|\\
	&\stackrel{\eqref{e:partial.deriv.covar.bound}}{\le}
	\sum_{\sigma'} A_{\SSPIN{r}[\sigma],\SSPIN{r}[\sigma']}
	\sum_{j=2}^K\sum_{\sigma'}
	\Bigg|\ln \frac{b_{j,t}(\sigma')}
		{b_{j,t-1}(\sigma')}\Bigg|
	\stackrel{\eqref{e:lotsOfAsDiverse.induct}}{\le}
	\frac{k}{2^{kt\epsilon_1/3}} \frac1{2^{3k\epsilon_1/2}}
	\sum_{\sigma'}
	A_{\SSPIN{r}[\sigma],\SSPIN{r}[\sigma']}
	(2^{k\epsilon_1/2})^{\SSPIN{r}[\sigma]}\\
	&\stackrel{\eqref{e:partial.deriv.covar.bound}}{\le}
	\frac1{2^{k(t+1)\epsilon_1/3}}
	\frac{(2^{k\epsilon_1/2})^{\SSPIN{r}[\sigma]}}{2^{3k\epsilon_1/2}} \,.
	\end{align*}
This verifies the induction and proves
\eqref{e:lotsOfAsDiverse.induct} for all $t\ge0$.
Taking $t\to\infty$ gives the weights $b=b_\infty$ for the optimal measure $\mu$. We can then use this to estimate
	\begin{align*}
	1-\mu\Big(\SPIN{W}^1 \cup \SPIN{W}^2\Big)
	&\le
	\mu\bigg( \sum_{j=1}^K
	\mathbf{1}\Big\{\sigma_j
		\in\set{\SSPIN{c}\SSPIN{c},\SSPIN{c}\SSPIN{y},\SSPIN{y}\SSPIN{c}}\Big\} \le4
	\bigg)
	\le
	\mu\bigg( \sum_{j=1}^K
	\Ind{\sigma_j=\SSPIN{y}\SSPIN{y}} \ge K-6\bigg)
	\\
	&\le \sum_{|S| \le 6} \prod_{j\in[K]\setminus S}
			 b_j(\SSPIN{y}\SSPIN{y})
	\le \frac1{2^{k(1+\epsilon_1)}}\,,
	\end{align*}
where the last bound follows from \eqref{e:lotsOfAsDiverse.induct} together with the diversity bound \eqref{e:diverse.clause.zeta}. This implies the first assertion
\eqref{e:lotsOfAsDiverse.conditional} of the lemma. The second assertion 
\eqref{e:lotsOfAsDiverse.uncond}
(removing the conditioning on $\SPIN{A}$)
follows trivially, since the assumption that $\bm{L}$ is light means (by Definition~\ref{d:heavy}) that
$\omega_{\bm{L},j}(\SSPIN{r}\SSPIN{r})\le 2^{-k(1+\epsilon_\circ)}$
for all $j$, and so a union bound gives
	\[\hat{\nu}_{\bm{L}}(\SPIN{A}^c )\le
	\sum_{j=1}^{k(\bm{L})} \omega_{\bm{L},j}(\SSPIN{r}\SSPIN{r})
	\le \frac{k}{ 2^{k(1+\epsilon_\circ)}}\,.
	\]
It follows by combining with \eqref{e:lotsOfAsDiverse.conditional} that
	\[
	\hat{\nu}_{\bm{L}}\bigg(
		(\SPIN{W}^1 \cup \SPIN{W}^2)^c\bigg)
	\le
	\hat{\nu}_{\bm{L}}(\SPIN{A}^c )
	+\hat{\nu}_{\bm{L}}\bigg(
	(\SPIN{W}^1 \cup \SPIN{W}^2)^c \,\bigg|\,\SPIN{A}^c
	\bigg)
	\le \frac1{2^{k(1+\epsilon_1)}}
	+ \frac{k}{2^{k(1+\epsilon_\circ)}}\,,
	\]
as claimed.\end{proof}

\begin{align*}
	\SPIN{A}
	&\equiv \{\smash{\vec{\sigma}}_{\delta a}
	: \sigma_e\ne\SSPIN{r}\SSPIN{r} \textup{ for all }e\in\delta a\}\,,\\
	\SPIN{W}^i
	&\equiv \{\smash{\vec{\sigma}}_{\delta a}
	: (\varsigma_e)^i
	=\SSPIN{w} \textup{ for all }e\in\delta a\}\,.
	\end{align*}


It is an immediate consequence of Lemma~\ref{l:indifferent}
that if $\bm{L}$ is both nice and diverse, then
	\begin{equation}\label{e:diverse.clause}
	\sum_{j=1}^{k(\bm{L})}
	\mathbf{1}\bigg\{
		\omega_{\bm{L},j}\Big(
		\set{\SSPIN{b}\SSPIN{y},\SSPIN{y}\SSPIN{b}}\Big)
	\ge \frac1{33}
	\bigg\}
	\ge \sum_{j=1}^{k(\bm{L})}
	\mathbf{1}\bigg\{\omega_{\bm{L},j}(\SSPIN{y}\SSPIN{b})
		\ge \frac1{65}
	\bigg\}
	\ge \frac{k}{10}\,.
	\end{equation}
In this proof, by the same reasoning as in the proof of Lemma~\ref{l:lotsOfAs} (see \eqref{e:bg.given.cyan}), it suffices to take $\sigma$ in the reduced alphabet $\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}$. We also abbreviate $\SSPIN{u}\equiv\set{\SSPIN{y},\SSPIN{c}}$. Throughout the following, $\epsilon_1$ denotes a small positive number, whose value may change from one occurrence to the next, but ultimately is taken as an absolute constant. We denote the clause width by $K\equiv k(\bm{L})\in\set{k-1,k}$.
\smallskip

\noindent\bemph{Step 1. Reduction to entropy maximization for a conditional measure.} As in the statement of the lemma, let $\hat{\nu}_{\bm{L}}$ be the optimizer given marginals $\omega$. Note that since $\omega$ is judicious and $\bm{L}$ is nice,
	\[
	\hat{\nu}_{\bm{L}}(\SPIN{A}^c)
	\le\sum_{j=1}^K
	\omega_{\bm{L},j}(\SSPIN{r}\SSPIN{r})
	\le\sum_{i=1,2}
	\sum_{j=1}^K
	(\omega_{\bm{L},j})^i(\SSPIN{r})
	= 2\sum_{j=1}^K {}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\SSPIN{r})
	\le O\bigg( \frac{k}{2^k}\bigg)\,.
	\]
Let $\mu(\smash{\vec{\sigma}})\equiv \hat{\nu}_{\bm{L}}(\smash{\vec{\sigma}}\,|\, \SPIN{A})$
for $\smash{\vec{\sigma}}\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^{2K}$. For each edge $1\le j\le K$, let $\mu_j$ be the marginal of $\mu$ on the $j$-th edge in $\delta a$. Thus $\mu_j$ is a probability measure over $\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2\setminus\set{\SSPIN{r}\SSPIN{r}}$, and the preceding estimate implies
	\begin{equation}\label{e:cond.on.A.mgl.effect}
	\mu_j(\sigma)
	=\frac{\hat{\nu}_{\bm{L}}(\sigma_j=\sigma)
		-\hat{\nu}_{\bm{L}}(\sigma_j=\sigma;\SPIN{A}^c)}
		{1-\hat{\nu}_{\bm{L}}(\SPIN{A}^c)}
	= \begin{cases}
	\omega_{\bm{L},j}(\sigma) +O(k/2^k)
		&\textup{if $\SSPIN{r}[\sigma]=0$,} \\
	\omega_{\bm{L},j}(\sigma) +O(1/2^k)
		&\textup{if $\SSPIN{r}[\sigma]=1$,}
	\end{cases}
	\end{equation}
where the last bound uses that $\hat{\nu}_{\bm{L}}(\sigma_j=\sigma)\le O(1/2^k)$ if $\SSPIN{r}[\sigma]=1$. The measure $\mu$ maximizes entropy subject to the edge marginals $\mu_j$. Similarly as in the preceding proofs of this section, we shall construct a sequence of Lagrangian weights $b_{j,t}$ such that the measure
	\begin{equation}\label{e:mu.t.as.fn.of.b.t}
	 \mu_t(\smash{\vec{\sigma}})
	= \frac{ \Ind{\smash{\vec{\sigma}}\in\SPIN{A}}}{Z_t}
	\prod_{j=1}^K b_{j,t}(\sigma_j)\end{equation}
converges to the desired $\mu$ as $t\to\infty$, where $Z_t$ is the normalizing constant. Let $\mu_{j,t}$ denote the marginals of the measure $\mu_t$.\smallskip

\noindent\bemph{Step 2. Initalization of Lagrangian weights.} We initialize the construction with
	\begin{equation}\label{e:burnin.reweight.power.of.two}
	b_{j,0}(\sigma)
	\equiv
	\frac{\mu_j(\sigma)}{1/ (2^{K-1})^{\SSPIN{r}[\sigma]}}\,,\quad
	\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2\setminus\set{\SSPIN{r}\SSPIN{r}}\,.
	\end{equation}
We first estimate the marginals $\mu_{j,0}$ of the resulting measure $\mu_0$. Recall that we denote $\SSPIN{u}\equiv\set{\SSPIN{y},\SSPIN{c}}$. Note that \eqref{e:cond.on.A.mgl.effect}, together with the judicious condition and the assumption that $\bm{L}$ is nice, gives
	\begin{equation}\label{e:zeta.u.u.estimates}
	\mu_j(\SSPIN{u}\SSPIN{u})=1-O\bigg(\frac{k}{2^k}\bigg)\,,\quad
	\sum_{\tau\in\set{\SSPIN{y},\SSPIN{c}}}
	\Bigg\{
	\bigg|\mu_j(\tau\SSPIN{u})-\frac12\bigg|
	+\bigg|\mu_j(\SSPIN{u}\tau)-\frac12\bigg|\Bigg\}
	 \le \frac1{2^{k\epsilon_1}}\,.
	\end{equation}
Moreover, it follows from the diverse clause condition \eqref{e:burnin.reweight.power.of.two} together with \eqref{e:cond.on.A.mgl.effect} that
	\begin{equation}\label{e:diverse.clause.zeta}
	\sum_{j=1}^{k(\bm{L})}
	\mathbf{1}\bigg\{
	\min\Big\{	 \mu_j(\SSPIN{y}\SSPIN{b}),\mu_j(\SSPIN{b}\SSPIN{y})\Big\}
	\ge \frac1{65}
	\bigg\}
	\ge \frac{k}{10}\,.
	\end{equation}
Without loss of generality we now focus on the marginal on the edge indexed $j=1$: at time $t=0$, 
	\[
	Z_0\mu_{1,0}(\SSPIN{c}\SSPIN{c})
	= \mu_1(\SSPIN{c}\SSPIN{c})
	\Bigg\{
	\prod_{\ell=2}^K\mu_\ell(\SSPIN{u}\SSPIN{u})
	-\prod_{\ell=2}^K\mu_\ell(\SSPIN{u}\SSPIN{y})
	-\prod_{\ell=2}^K\mu_\ell(\SSPIN{y}\SSPIN{u})
	+\prod_{\ell=2}^K\mu_\ell(\SSPIN{y}\SSPIN{y})
	\Bigg\}
	\stackrel{\eqref{e:zeta.u.u.estimates}}{=}
	\mu_1(\SSPIN{c}\SSPIN{c})\Bigg\{ 1 +O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}\,,
	\]
Similar calculations, again using \eqref{e:zeta.u.u.estimates}, give the analogous estimate for $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$.
Next, for $\sigma=\SSPIN{r}\SSPIN{c}$, it follows from \eqref{e:zeta.u.u.estimates}
together with the diversity bound \eqref{e:diverse.clause.zeta} gives
	\begin{align*}
	Z_0\mu_{1,0}(\SSPIN{r}\SSPIN{c})
	&= \Big( \mu_1(\SSPIN{r}\SSPIN{c}) 2^{K-1}\Big)
	\Bigg\{\prod_{\ell=2}^K
	\mu_\ell(\SSPIN{y}\SSPIN{u})
	-\prod_{\ell=2}^K\mu_\ell(\SSPIN{y}\SSPIN{y})\Bigg\}\\
	&=\Big( \mu_1(\SSPIN{r}\SSPIN{c}) 2^{K-1}\Big)
	\frac{1+O(k/2^{k\epsilon_1})}{2^{K-1}}\Bigg\{1
	-\bigg(1-\frac{2}{65}\bigg)^{k/10}
	\Bigg\}
	= \mu_1(\SSPIN{r}\SSPIN{c}) 
	\Bigg\{ 1 +O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}
	\end{align*}
(recalling our convention that $\epsilon_1$ can change from one expression to the next, but remains bounded below by a positive absolute constant). A similar calculation (again using
\eqref{e:zeta.u.u.estimates} and \eqref{e:diverse.clause.zeta}) gives
an analogous estimate for $\sigma=\SSPIN{r}\SSPIN{y}$. Altogether we conclude
	\begin{equation}\label{e:mu.mgl.zeta.base.case}
	\mu_{1,0}(\sigma)
	=\frac{\mu_1(\sigma)}{Z_0}
		\Bigg\{ 1 +O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}
	= \mu_1(\sigma)
		\Bigg\{ 1 +O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}\,.
	\end{equation}
for all $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2\setminus\set{\SSPIN{r}\SSPIN{r}}$.\smallskip

\noindent\bemph{Step 3. Iterative analysis of Lagrangian weights.} Suppose at time $t$ that we have weights $b_{j,t}$, which define a measure $\mu_t$ as in \eqref{e:mu.t.as.fn.of.b.t} with edge marginals $\mu_{j,t}$. We define the updated weights at time $t+1$ by
	\begin{equation}\label{e:lotsOfAsDiverse.beta.update.rule}
	\frac{b_{j,t+1}(\sigma)}{b_{j,t}(\sigma)}
	= \frac{\mu_j(\sigma)}{\mu_{j,t}(\sigma)}\,.
	\end{equation}
We will prove by induction that for all $t\ge0$, all $1\le j\le k(\bm{L})$, and all $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2\setminus\set{\SSPIN{r}\SSPIN{r}}$,
	\begin{equation}\label{e:lotsOfAsDiverse.induct}
	\Bigg|
	\frac{b_{j,t+1}(\sigma)}
		{b_{j,t}(\sigma)}-1 \Bigg|
	=\Bigg|
	\frac{\mu_j(\sigma)}{\mu_{j,t}(\sigma)}-1
	\Bigg|
	\le \frac{ y_{\SSPIN{r}[\sigma]}}{2^{k(t+1)\epsilon_1/3}}\,,\quad
	\begin{pmatrix}y_0 \\ y_1\end{pmatrix}
	= \frac1{2^{3k\epsilon_1/2}}
	\begin{pmatrix}1 \\ 2^{k\epsilon_1/2} \end{pmatrix}\,,
	\end{equation}
where the base case $t=0$ is implied by \eqref{e:mu.mgl.zeta.base.case} (adjusting $\epsilon_1$ appropriately). Suppose then that \eqref{e:lotsOfAsDiverse.induct} holds up to time $t-1\ge0$, and note it implies that for all $j,\sigma$ we have
	\begin{equation}\label{e:lotsOfAsDiverse.induction}
	\Bigg|\ln \frac{b_{j,t}(\sigma)}
		{\mu_j(\sigma) (2^{K-1})^{\SSPIN{r}[\sigma]}}
		\Bigg|
	=\Bigg|\ln \frac{b_{j,t}(\sigma)}{b_{j,0}(\sigma)}
		\Bigg|
	\le \sum_{s=0}^{t-1}
	\Bigg|\ln \frac{b_{j,s+1}(\sigma)}{b_{j,s}(\sigma)}
		\Bigg|
	\stackrel{\eqref{e:lotsOfAsDiverse.induct}}{\le}
		O\bigg( \frac1{2^{k\epsilon_1}}\bigg)\,.
	\end{equation}
To analyze the update \eqref{e:lotsOfAsDiverse.beta.update.rule}, let us focus on the first two edges in the clause, and note that
	\begin{equation}\label{e:derivative.is.covariance}
	\frac{\partial \mu_{1,t}(\sigma)}
		{\partial \ln b_{2,t}(\sigma')}
	=\mathrm{Cov}_{\mu_t}\bigg(
	\Ind{\sigma_1=\sigma},
	\Ind{\sigma_2=\sigma'}
	\bigg)
	\end{equation}
for all $\sigma,\sigma'\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2\setminus\set{\SSPIN{r}\SSPIN{r}}$ (by direct calculation). We therefore define
	\[
	C_t(\sigma,\sigma')
	\equiv
	\frac{Z_t \mu_t(\sigma_1=\sigma,\sigma_2=\sigma')}
		{\mu_{j=1}(\sigma)
		\mu_{j'=2}(\sigma')}\,,
	\]
and proceed to estimate this quantity. In the simplest case $\sigma=\sigma'=\SSPIN{c}\SSPIN{c}$, we have
	\[
	C_t(\SSPIN{c}\SSPIN{c},\SSPIN{c}\SSPIN{c})
	=\frac{b_{1,t}(\SSPIN{c}\SSPIN{c})
	b_{2,t}(\SSPIN{c}\SSPIN{c})}
	{\mu_1(\SSPIN{c}\SSPIN{c})
	\mu_2(\SSPIN{c}\SSPIN{c})}
	\prod_{j=3}^K b_{j,t}(\SSPIN{u}\SSPIN{u})
	\stackrel{\eqref{e:lotsOfAsDiverse.induction}}{=}
	\Bigg\{
	\prod_{j=3}^K \mu_j(\SSPIN{u}\SSPIN{u})
	\Bigg\}
	\Bigg\{1 + O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}
	\stackrel{\eqref{e:zeta.u.u.estimates}}{=}
	1 + O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\,.\]
A similar estimate holds for all cases where
$\SSPIN{r}[\sigma]+\SSPIN{r}[\sigma']=0$. Next,
	\[
	C_t(\SSPIN{r}\SSPIN{c},\SSPIN{y}\SSPIN{c})
	=\frac{ b_{1,t}(\SSPIN{r}\SSPIN{c})b_{2,t}(\SSPIN{y}\SSPIN{c})}
		{\mu_1(\SSPIN{r}\SSPIN{c})\mu_2(\SSPIN{y}\SSPIN{c})}
	\prod_{j=3}^K b_{j,t}(\SSPIN{y}\SSPIN{u})
	\stackrel{\eqref{e:lotsOfAsDiverse.induction}}{=}
	\Bigg\{ 2^{K-1} \prod_{j=3}^K \mu_j(\SSPIN{y}\SSPIN{u})
	\Bigg\}
	\Bigg\{1 + O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}
	\stackrel{\eqref{e:zeta.u.u.estimates}}{=}
	2 \Bigg\{1 + O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}\,,
	\]
and a similar estimate holds for $C_t(\sigma,\sigma')$ in all cases where $\SSPIN{r}[\sigma]+\SSPIN{r}[\sigma']=1$. Finally,
	\[
	C_t(\SSPIN{r}\SSPIN{y},\SSPIN{y}\SSPIN{r})
	= \frac{b_{1,t}(\SSPIN{r}\SSPIN{y}) b_{2,t}(\SSPIN{y}\SSPIN{r})}
		{\mu_1(\SSPIN{r}\SSPIN{y})\mu_2(\SSPIN{y}\SSPIN{r})}
	\prod_{j=3}^K b_{j,t}(\SSPIN{y}\SSPIN{y})
	\stackrel{\eqref{e:lotsOfAsDiverse.induction}}{=}
	(2^{K-1})^2
	\prod_{j=3}^K b_{j,t}(\SSPIN{y}\SSPIN{y})
	\Bigg\{1 + O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}
	\le \frac{2^k}{2^{k\epsilon_1}}\,,
	\]
where the last bound uses the diversity bound \eqref{e:diverse.clause.zeta}. Combining with \eqref{e:derivative.is.covariance} gives
	\begin{align*}
	\Bigg|\frac{\partial \mu_{1,t}(\sigma) /
		\partial \ln b_{2,t}(\sigma')}
		{\mu_{1,t}(\sigma)
		\mu_{2,t}(\sigma')}
		\Bigg|
	&=\Bigg| \overbrace{\Bigg\{
		\frac{Z_t\mu_t(\sigma_1=\sigma,\sigma_2=\sigma')}
		{\mu_1(\sigma)\mu_2(\sigma')}
		\Bigg\}}^{C_t(\sigma,\sigma')}
	\overbrace{\Bigg\{
	\frac{\mu_1(\sigma)\mu_2(\sigma')}
		{Z_t \mu_{1,t}(\sigma)
		\mu_{2,t}(\sigma')}
		\Bigg\}}^{1 + O(2^{-k\epsilon_1})}
		{} -1 \Bigg| \\
	&\le O(1) \begin{cases}
	2^{-k\epsilon_1} & \textup{if 
		$\SSPIN{r}[\sigma]+\SSPIN{r}[\sigma']=0$,}\\
	1 & \textup{if $\SSPIN{r}[\sigma]+\SSPIN{r}[\sigma']=1$,}\\
	2^{k(1-\epsilon_1)} & \textup{if 
		$\SSPIN{r}[\sigma]=\SSPIN{r}[\sigma']=1$.}
	\end{cases}
	\end{align*}
Rewriting the above in a more convenient form gives
	\begin{equation}\label{e:partial.deriv.covar.bound}
	\frac1{\mu_1(\sigma)}
	\Bigg|\frac{\partial \mu_{1,t}(\sigma)}
		{\partial\ln b_{2,t}(\sigma')}
		\Bigg|
	\le O\Big( A_{\SSPIN{r}[\sigma],\SSPIN{r}[\sigma']}
		\Big)\,,\quad
	A = \begin{pmatrix} A_{0,0} & A_{0,1}\\
		A_{1,0} & A_{1,1} \end{pmatrix}
	= \begin{pmatrix} 2^{-k\epsilon_1} & 2^{-k} \\
		1 & 2^{-k\epsilon_1} \end{pmatrix}\,.\end{equation}
Now recall the definition \eqref{e:mu.t.as.fn.of.b.t}
of $\mu_t$, and define
	\[
	\tilde{\mu}_t(\smash{\vec{\sigma}})
	= \frac{ \Ind{\smash{\vec{\sigma}}\in\SPIN{A}}}{Z_t}
	b_{1,t}(\sigma_1)
	\prod_{j=2}^K b_{j,t-1}(\sigma_j)\,.
	\]
It follows from the update rule \eqref{e:lotsOfAsDiverse.beta.update.rule} that the marginal of $\tilde{\mu}_t$ on the first edge is precisely $\mu_1$. Consequently,
	\begin{align*}
	\Bigg|
	\frac{b_{1,t+1}(\sigma)}
		{b_{1,t}(\sigma)}-1 \Bigg|
	&\stackrel{\eqref{e:lotsOfAsDiverse.beta.update.rule}}{=}\Bigg|
	\frac{\tilde{\mu}_t(\sigma_1=\sigma)}
		{\mu_t(\sigma_1=\sigma)}-1
	\Bigg|
	\le \frac{O(1)}{\mu_1(\sigma)}
	\sum_{j=2}^K\sum_{\sigma'}
	\Bigg| \frac{\partial\mu_{1,t}(\sigma)}
		{\partial \ln b_{j,t}(\sigma')}\Bigg|
	\cdot
	\Bigg|\ln \frac{b_{j,t}(\sigma')}
		{b_{j,t-1}(\sigma')}\Bigg|\\
	&\stackrel{\eqref{e:partial.deriv.covar.bound}}{\le}
	\sum_{\sigma'} A_{\SSPIN{r}[\sigma],\SSPIN{r}[\sigma']}
	\sum_{j=2}^K\sum_{\sigma'}
	\Bigg|\ln \frac{b_{j,t}(\sigma')}
		{b_{j,t-1}(\sigma')}\Bigg|
	\stackrel{\eqref{e:lotsOfAsDiverse.induct}}{\le}
	\frac{k}{2^{kt\epsilon_1/3}} \frac1{2^{3k\epsilon_1/2}}
	\sum_{\sigma'}
	A_{\SSPIN{r}[\sigma],\SSPIN{r}[\sigma']}
	(2^{k\epsilon_1/2})^{\SSPIN{r}[\sigma]}\\
	&\stackrel{\eqref{e:partial.deriv.covar.bound}}{\le}
	\frac1{2^{k(t+1)\epsilon_1/3}}
	\frac{(2^{k\epsilon_1/2})^{\SSPIN{r}[\sigma]}}{2^{3k\epsilon_1/2}} \,.
	\end{align*}
This verifies the induction and proves
\eqref{e:lotsOfAsDiverse.induct} for all $t\ge0$.
Taking $t\to\infty$ gives the weights $b=b_\infty$ for the optimal measure $\mu$. We can then use this to estimate
	\begin{align*}
	1-\mu\Big(\SPIN{W}^1 \cup \SPIN{W}^2\Big)
	&\le
	\mu\bigg( \sum_{j=1}^K
	\mathbf{1}\Big\{\sigma_j
		\in\set{\SSPIN{c}\SSPIN{c},\SSPIN{c}\SSPIN{y},\SSPIN{y}\SSPIN{c}}\Big\} \le4
	\bigg)
	\le
	\mu\bigg( \sum_{j=1}^K
	\Ind{\sigma_j=\SSPIN{y}\SSPIN{y}} \ge K-6\bigg)
	\\
	&\le \sum_{|S| \le 6} \prod_{j\in[K]\setminus S}
			 b_j(\SSPIN{y}\SSPIN{y})
	\le \frac1{2^{k(1+\epsilon_1)}}\,,
	\end{align*}
where the last bound follows from \eqref{e:lotsOfAsDiverse.induct} together with the diversity bound \eqref{e:diverse.clause.zeta}. This implies the first assertion
\eqref{e:lotsOfAsDiverse.conditional} of the lemma. The second assertion 
\eqref{e:lotsOfAsDiverse.uncond}
(removing the conditioning on $\SPIN{A}$)
follows trivially, since the assumption that $\bm{L}$ is light means (by Definition~\ref{d:heavy}) that
$\omega_{\bm{L},j}(\SSPIN{r}\SSPIN{r})\le 2^{-k(1+\epsilon_\circ)}$
for all $j$, and so a union bound gives
	\[\hat{\nu}_{\bm{L}}(\SPIN{A}^c )\le
	\sum_{j=1}^{k(\bm{L})} \omega_{\bm{L},j}(\SSPIN{r}\SSPIN{r})
	\le \frac{k}{ 2^{k(1+\epsilon_\circ)}}\,.
	\]
