for $j=j(\bm{t})$ and all clause types $\bm{L}$ such that 
$\bm{L}(j)=\bm{t}$.

\begin{proof} Throughout the proof, $\epsilon_3$ denotes a small positive number, whose value may change from one occurrence to the next, but ultimately is taken as an absolute constant that depends only on $\epsilon_2$.\smallskip

\noindent\bemph{Step 1. Reduction to entropy maximization for a conditional measure.}
Note from \eqref{e:Psi.of.Omega} that if we fix
$\Omega_{\bm{t}}$, then we obtain separate entropy maximization problems over $\Omega_{\bm{T}}$ and $\Omega_{\bm{L}}$. Let us therefore fix $\Omega_{\bm{t}}=(\textup{\textsf{aug}}_{\mathscr{D}}(\omega))_{\bm{t}}$, and consider the optimization over $\Omega_{\bm{T}}$. Let $v$ denote a variable of type $\bm{T}$, and write $\Omega_v\equiv\Omega_{\bm{T}}$.
By the method of Lagrange multipliers, the optimal $\Omega_v$ must take the form
	\[
	\Omega_v\Big( (\smash{\vec{\sigma}},\bm{L})_{\delta v}\Big)
	= \frac{\varphi_v(\smash{\vec{\sigma}}_{\delta v})}{\bm{\dot{z}}} 
		\prod_{e\in\delta v}
		\hat{q}_e(\sigma_e,\bm{L}_e)\,,\]
where each $\hat{q}_e$ is a probability measure over elements $(\sigma,\bm{L})$, chosen such that $\Omega_v$ has marginals $\Omega_e\equiv\Omega_{\bm{t}}$ for $e\in\delta v$ and $\bm{t}\equiv\bm{t}_e$. The marginal of $\Omega_v$ on $(\smash{\vec{\sigma}}_{\delta v},\bm{L}_e)$ is
	\[
	\Omega_v(\smash{\vec{\sigma}}_{\delta v},\bm{L}_e)
	= \frac{\varphi_v(\smash{\vec{\sigma}}_{\delta v})}{\bm{\dot{z}}}
	\hat{q}_e(\sigma_e,\bm{L}_e)
	\prod_{e'\in\delta v\setminus e}
	\bar{q}_{e'}(\sigma_{e'})\,,
	\]
where $\bar{q}_{e'}$ denotes the marginal of $\hat{q}_{e'}$ on $\sigma_{e'}$ alone. It follows that
	\begin{equation}\label{e:var.spins.types.cond.indep}
	\Omega_{\bm{T}}\bigg(\smash{\vec{\sigma}}_{\delta v\setminus e}
		\,\bigg|\, (\sigma_e,\bm{L}_e)\bigg)
	= \dot{\nu}_{\bm{T}}
		\Big(\smash{\vec{\sigma}}_{\delta v\setminus e}
		\,\Big|\,\sigma_e\Big)
	\cong 
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e'\in\delta v\setminus e}
	\bar{q}_{e'}(\sigma_{e'}).
	\end{equation}
Thus, for the purposes of this lemma, it suffices to estimate only $\dot{\nu}_{\bm{T}}(\cdot\,|\,\sigma_e)$. To this end, assume without loss $x=\SPIN{+}$, and consider the event $x_v=\SPIN{+}\SPIN{+}$. In this case 
$\sigma_e\in\set{\SSPIN{r},\SSPIN{b}}^2$ for all $e\in\delta v(\SPIN{+})$, and
$\sigma_e=\SSPIN{y}\SSPIN{y}$ for all $e\in\delta v(\SPIN{-})$. Let
	\begin{equation}\label{e:def.mu.cond.on.plus.plus}
	\mu(\smash{\vec{\sigma}})
	\equiv
	\dot{\nu}_{\bm{T}}\bigg(\smash{\vec{\sigma}}_{\delta v(\SPIN{+})}=\smash{\vec{\sigma}}
		\,\bigg|\,x_v=\SPIN{+}\SPIN{+}\bigg)\,.\end{equation}
Denote $D \equiv |\delta v(\SPIN{+})|$.
Then $\mu$ is a probability measure over colorings $\smash{\vec{\sigma}}\in\set{\SSPIN{r},\SSPIN{b}}^{2D}$ with at least one $\SPIN{red}$ spin in each copy $i=1,2$. Moreover, $\mu$ must maximize entropy subject to its marginals 
$\mu_\ell$. It 
follows by the method of Lagrange multipliers that there exist probability measures $h_\ell$
over $\set{\SSPIN{r},\SSPIN{b}}^2$ such that
	\begin{equation}\label{e:rrUnforced.mu.q}
	\mu(\smash{\vec{\sigma}})
	\cong
	\Bigg\{
	\prod_{i=1,2}\Ind{\SSPIN{r}[\smash{\vec{\sigma}}^i]\ge1}\Bigg\}
	\Bigg\{
	\prod_{\ell=1}^D h_\ell(\sigma_\ell)
	\Bigg\}\,.
	\end{equation}
We now turn to the construction and estimation of the $h_\ell$.\smallskip

\noindent\bemph{Step 2. Construction of Lagrangian weights.} As usual, we will construct $h_{\ell,t}\to h_\ell$ in the limit $t\to\infty$. We initialize the construction with $h_{\ell,0}\equiv\mu_\ell$. Let $\mu_t$
be defined by \eqref{e:rrUnforced.mu.q} with $h_{\ell,t}$ in place of $h_\ell$, and let $\mu_{\ell,t}$ denote the marginal of $\mu_t$ on the $\ell$-th edge in $\delta v(\SPIN{+})$. Similarly
to \eqref{e:q.times.prob.of.remainder} we have
	\begin{equation}\label{e:def.xi.ell.t}
	\mu_{\ell,t}(\sigma)
	\cong
	h_{\ell,t}(\sigma) \overbrace{
	\sum_{\smash{\vec{\sigma}}_{-\ell}}
	\Bigg\{
	\prod_{i=1,2}\Ind{\SSPIN{r}[\smash{\vec{\sigma}}^i]\ge1}\Bigg\}
	\prod_{\ell'\ne\ell}
	h_{\ell',t}(\sigma_{\ell'})
	}^{\textup{denote this }\xi_{\ell,t}(\sigma)}\,.
	\end{equation}
For the remainder of the proof, we assume without loss that $\ell=1$. Then at $t=0$ we have
	\begin{equation}
	0\le 1-\xi_{1,0}(\SSPIN{r}\SSPIN{b})
	= \prod_{\ell=2}^D \bigg\{
		1- \mu_\ell(\SSPIN{p}\SSPIN{r})
		\bigg\}
	\le \exp\Bigg\{ - \sum_{\ell=2}^D
		\mu_\ell(\SSPIN{p}\SSPIN{r})\Bigg\}
	\stackrel{\eqref{e:def.mu.cond.on.plus.plus}}{\le}
		\frac{e}{\exp(\gamma^2)}
	\stackrel{\eqref{e:assumption.rr.avg}}
		{\le} \frac1{2^{k\epsilon_3}}\,.
	\label{e:mostly.const.over.rb}\end{equation}
By similar calculations, $0\le 1-\xi_{1,0}(\sigma) \le 2^{-k\epsilon_3}$ for all $\sigma\in\set{\SSPIN{r},\SSPIN{b}}^2$. (In fact $\xi_{1,0}(\SSPIN{r}\SSPIN{r})=1$.) Given $h_{\ell,t}$ we define $h_{\ell,t+1}$ to be the probability measure such that
	\begin{equation}\label{e:update.rule.h}
	h_{\ell,t+1}(\sigma)
	\cong \frac{\mu_\ell(\sigma)}{\xi_{\ell,t}(\sigma)}
	\stackrel{\eqref{e:def.xi.ell.t}}{\cong}
		h_{\ell,t}(\sigma)
		\frac{\mu_\ell(\sigma)}{\mu_{\ell,t}(\sigma)}
	\end{equation}
for all $\sigma\in\set{\SSPIN{r},\SSPIN{b}}^2$.\smallskip

\noindent\bemph{Step 3. Estimation of Lagrangian weights.} Suppose inductively that
	\begin{equation}\label{e:rr.induct}
	\bigg\|\frac{\mu_{\ell,t}}{\mu_\ell}-1 \bigg\|_\infty
	\le \frac1{2^{k\epsilon_3(t+1)/3}}\end{equation}
for all $1\le\ell\le D$, where the base case $t=0$ follows from the above bounds (see \eqref{e:mostly.const.over.rb}) on $\xi_{\ell,0}$. 
If we assume \eqref{e:rr.induct} holds up to $t$, then taking a telescoping sum gives
	\begin{align}\nonumber
	&\Big|\xi_{1,t+1}(\SSPIN{r}\SSPIN{b})
	-\xi_{1,t}(\SSPIN{r}\SSPIN{b})\Big|
	= \Bigg| \prod_{j=2}^D
		\Big\{1-h_{\ell,t+1}(\SSPIN{p}\SSPIN{r})\Big\}
	-\prod_{j=2}^D
		\Big\{ 1-h_{\ell,t}(\SSPIN{p}\SSPIN{r})\Big\}
	\Bigg| \\ \nonumber
	&\qquad\le \sum_{\ell=2}^D
	h_{\ell,t}(\SSPIN{p}\SSPIN{r})
	\Bigg| \frac{h_{\ell,t+1}(\SSPIN{p}\SSPIN{r})}
		{h_{\ell,t}(\SSPIN{p}\SSPIN{r})}-1\Bigg|
	\prod_{j=2}^{\ell-1}
	\bigg\{1-h_{j,t+1}(\SSPIN{p}\SSPIN{r})\bigg\}
	\prod_{j=\ell+1}^D
	\bigg\{1-h_{j,t}(\SSPIN{p}\SSPIN{r})\bigg\}\\ \nonumber
	&\qquad\le O(1)\Bigg\{
	\max_{1\le\ell\le D}
	\bigg| \frac{h_{\ell,t+1}(\SSPIN{p}\SSPIN{r})}
		{h_{\ell,t}(\SSPIN{p}\SSPIN{r})}-1
	\bigg|\Bigg\}\Bigg\{
	\sum_{\ell=1}^D h_{\ell,t}(\SSPIN{p}\SSPIN{r})
	\Bigg\}\Bigg/
	\exp\Bigg\{
	\sum_{\ell=1}^D h_{\ell,t}(\SSPIN{p}\SSPIN{r})
	\Bigg\} \\
	&\qquad\stackrel{\eqref{e:rr.induct}}{\le}
	O\Bigg( \frac{\gamma^2}{\exp(\gamma^2)}\Bigg)
	\Bigg\{
	\max_{1\le\ell\le D}
	\bigg| \frac{h_{\ell,t+1}(\SSPIN{p}\SSPIN{r})}
		{h_{\ell,t}(\SSPIN{p}\SSPIN{r})}-1
	\bigg|\Bigg\}
	\stackrel{\eqref{e:update.rule.h}}{=}
	O\bigg( \frac{\gamma^2}{\exp(\gamma^2)}\bigg)
	\max_{1\le\ell\le D}
	\bigg| \frac{\mu_\ell(\SSPIN{p}\SSPIN{r})}{\mu_{\ell,t}(\SSPIN{p}\SSPIN{r})} -1
	\bigg|
	\stackrel{\eqref{e:rr.induct}}{\le}
	\frac{2^{-k\epsilon_3}}{2^{k\epsilon_3(t+1)/3}}\,.
	\label{e:d.xi.d.h}
	\end{align}
A similar estimate holds for
$\xi_{1,t+1}(\sigma)-\xi_{1,t}(\sigma)$ for all $\sigma\in\set{\SSPIN{r},\SSPIN{b}}^2$.
Next note that if we let $\tilde{\mu}_{t+1}$ be defined by
\eqref{e:rrUnforced.mu.q} with weights 
$h_{1,t+1}$ and $h_{\ell,t}$ for $\ell\ge2$, then
the marginal on the first edge is, similarly to \eqref{e:def.xi.ell.t},
	\[
	\tilde{\mu}_{1,t+1}(\sigma)
	\cong h_{1,t+1}(\sigma)
		\xi_{1,t}(\sigma)
	\stackrel{\eqref{e:update.rule.h}}{\cong}
	\frac{\mu_1(\sigma)}{\xi_{1,t}(\sigma)}
		\xi_{1,t}(\sigma)
	=\mu_1(\sigma)\,.
	\]
It follows from this that 
	\begin{align*}
	\bigg\|\frac{\mu_{1,t+1}}{\mu_1}
		-1 \bigg\|_\infty
	&=\bigg\|
		\frac{\mu_{1,t+1}}{\tilde{\mu}_{1,t+1}}
		-1 \bigg\|_\infty
	\stackrel{\eqref{e:update.rule.h}}{=} \bigg\|
		\frac{\xi_{1,t+1}}{\xi_{1,t}}
		-1 \bigg\|_\infty
	\stackrel{\eqref{e:d.xi.d.h}}{\le}
	O\bigg(\frac{2^{-k\epsilon_3}}{2^{k\epsilon_3(t+1)/3}}\bigg)
	\le \frac1{2^{k\epsilon_3(t+2)/3}}\,,
	\end{align*}
which verifies the induction. We then take $t\to\infty$ to obtain the limiting weights $h_\ell\equiv h_{\ell,\infty}$ that define the optimal measure $\mu$ by \eqref{e:rrUnforced.mu.q}. Suppose $e$ corresponds to the first edge in $\delta v(\SPIN{+})$. Then, for all $\sigma_e\in\set{\SSPIN{r},\SSPIN{b}}^2$,
	\[
	\dot{\nu}_{\bm{T}}\bigg(
	\sum_{e'\in\delta v(\SPIN{+})\setminus e}
	\Ind{ (\sigma_{e'})^2=\SSPIN{r}} =0
	\,\bigg|\,\sigma_e
	\bigg)
	\stackrel{\eqref{e:def.mu.cond.on.plus.plus}}{=}
	\mu\bigg(
	\smash{\vec{\sigma}}_{-1}\in\set{\SSPIN{p}\SSPIN{b}}^D \,\bigg|\,\sigma_1
	\bigg)
	\stackrel{\eqref{e:rr.induct}}{\le}
	O\Bigg(
	\prod_{\ell=2}^D
		\bigg\{ 1-h_\ell(\SSPIN{p}\SSPIN{r})\bigg\}
		\Bigg) \le \frac1{2^{k\epsilon_3}}\,.
	\]
The lemma follows by recalling \eqref{e:var.spins.types.cond.indep}.
\end{proof}

