A similar estimate holds for
$\xi_{1,t+1}(\sigma)-\xi_{1,t}(\sigma)$ for all $\sigma\in\set{\SSPIN{r},\SSPIN{b}}^2$.
Next note that if we let $\tilde{\mu}_{t+1}$ be defined by
\eqref{e:rrUnforced.mu.q} with weights 
$h_{1,t+1}$ and $h_{\ell,t}$ for $\ell\ge2$, then
the marginal on the first edge is, similarly to \eqref{e:def.xi.ell.t},
	\[
	\tilde{\mu}_{1,t+1}(\sigma)
	\cong h_{1,t+1}(\sigma)
		\xi_{1,t}(\sigma)
	\stackrel{\eqref{e:update.rule.h}}{\cong}
	\frac{\mu_1(\sigma)}{\xi_{1,t}(\sigma)}
		\xi_{1,t}(\sigma)
	=\mu_1(\sigma)\,.
	\]
It follows from this that 
	\begin{align*}
	\bigg\|\frac{\mu_{1,t+1}}{\mu_1}
		-1 \bigg\|_\infty
	&=\bigg\|
		\frac{\mu_{1,t+1}}{\tilde{\mu}_{1,t+1}}
		-1 \bigg\|_\infty
	\stackrel{\eqref{e:update.rule.h}}{=} \bigg\|
		\frac{\xi_{1,t+1}}{\xi_{1,t}}
		-1 \bigg\|_\infty
	\stackrel{\eqref{e:d.xi.d.h}}{\le}
	O\bigg(\frac{2^{-k\epsilon_3}}{2^{k\epsilon_3(t+1)/3}}\bigg)
	\le \frac1{2^{k\epsilon_3(t+2)/3}}\,,
	\end{align*}
which verifies the induction. We then take $t\to\infty$ to obtain the limiting weights $h_\ell\equiv h_{\ell,\infty}$ that define the optimal measure $\mu$ by \eqref{e:rrUnforced.mu.q}. Suppose $e$ corresponds to the first edge in $\delta v(\SPIN{+})$. Then, for all $\sigma_e\in\set{\SSPIN{r},\SSPIN{b}}^2$,
	\[
	\dot{\nu}_{\bm{T}}\bigg(
	\sum_{e'\in\delta v(\SPIN{+})\setminus e}
	\Ind{ (\sigma_{e'})^2=\SSPIN{r}} =0
	\,\bigg|\,\sigma_e
	\bigg)
	\stackrel{\eqref{e:def.mu.cond.on.plus.plus}}{=}
	\mu\bigg(
	\smash{\vec{\sigma}}_{-1}\in\set{\SSPIN{p}\SSPIN{b}}^D \,\bigg|\,\sigma_1
	\bigg)
	\stackrel{\eqref{e:rr.induct}}{\le}
	O\Bigg(
	\prod_{\ell=2}^D
		\bigg\{ 1-h_\ell(\SSPIN{p}\SSPIN{r})\bigg\}
		\Bigg) \le \frac1{2^{k\epsilon_3}}\,.
	\]
The lemma follows by recalling \eqref{e:var.spins.types.cond.indep}.

\begin{equation}\label{e:var.spins.types.cond.indep}
	\Omega_{\bm{T}}\bigg(\smash{\vec{\sigma}}_{\delta v\setminus e}
		\,\bigg|\, (\sigma_e,\bm{L}_e)\bigg)
	= \dot{\nu}_{\bm{T}}
		\Big(\smash{\vec{\sigma}}_{\delta v\setminus e}
		\,\Big|\,\sigma_e\Big)
	\cong 
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e'\in\delta v\setminus e}
	\bar{q}_{e'}(\sigma_{e'}).
	\end{equation}

\begin{align}\nonumber
	&\Big|\xi_{1,t+1}(\SSPIN{r}\SSPIN{b})
	-\xi_{1,t}(\SSPIN{r}\SSPIN{b})\Big|
	= \Bigg| \prod_{j=2}^D
		\Big\{1-h_{\ell,t+1}(\SSPIN{p}\SSPIN{r})\Big\}
	-\prod_{j=2}^D
		\Big\{ 1-h_{\ell,t}(\SSPIN{p}\SSPIN{r})\Big\}
	\Bigg| \\ \nonumber
	&\qquad\le \sum_{\ell=2}^D
	h_{\ell,t}(\SSPIN{p}\SSPIN{r})
	\Bigg| \frac{h_{\ell,t+1}(\SSPIN{p}\SSPIN{r})}
		{h_{\ell,t}(\SSPIN{p}\SSPIN{r})}-1\Bigg|
	\prod_{j=2}^{\ell-1}
	\bigg\{1-h_{j,t+1}(\SSPIN{p}\SSPIN{r})\bigg\}
	\prod_{j=\ell+1}^D
	\bigg\{1-h_{j,t}(\SSPIN{p}\SSPIN{r})\bigg\}\\ \nonumber
	&\qquad\le O(1)\Bigg\{
	\max_{1\le\ell\le D}
	\bigg| \frac{h_{\ell,t+1}(\SSPIN{p}\SSPIN{r})}
		{h_{\ell,t}(\SSPIN{p}\SSPIN{r})}-1
	\bigg|\Bigg\}\Bigg\{
	\sum_{\ell=1}^D h_{\ell,t}(\SSPIN{p}\SSPIN{r})
	\Bigg\}\Bigg/
	\exp\Bigg\{
	\sum_{\ell=1}^D h_{\ell,t}(\SSPIN{p}\SSPIN{r})
	\Bigg\} \\
	&\qquad\stackrel{\eqref{e:rr.induct}}{\le}
	O\Bigg( \frac{\gamma^2}{\exp(\gamma^2)}\Bigg)
	\Bigg\{
	\max_{1\le\ell\le D}
	\bigg| \frac{h_{\ell,t+1}(\SSPIN{p}\SSPIN{r})}
		{h_{\ell,t}(\SSPIN{p}\SSPIN{r})}-1
	\bigg|\Bigg\}
	\stackrel{\eqref{e:update.rule.h}}{=}
	O\bigg( \frac{\gamma^2}{\exp(\gamma^2)}\bigg)
	\max_{1\le\ell\le D}
	\bigg| \frac{\mu_\ell(\SSPIN{p}\SSPIN{r})}{\mu_{\ell,t}(\SSPIN{p}\SSPIN{r})} -1
	\bigg|
	\stackrel{\eqref{e:rr.induct}}{\le}
	\frac{2^{-k\epsilon_3}}{2^{k\epsilon_3(t+1)/3}}\,.
	\label{e:d.xi.d.h}
	\end{align}

\label{l:ryUnforced}
Let $\epsilon_2$ be a small absolute constant. Fix $x\in\set{\SPIN{+},\SPIN{-}}$ and $\tau\in\set{\SSPIN{y},\SSPIN{g}}$, and let $v$ be a variable of type $\bm{T}$. Suppose we are given $\omega\in\bm{I}_0$ with marginal $\pi$ such that
	\begin{equation}\label{e:ryUnforced.condition} 
	\sum_{e\in\delta v(x)}\pi_e\Big(
		\sigma^1=\SSPIN{r}\,\Big|\,
	\sigma\in\set{\SSPIN{r}\tau,\SSPIN{b}\tau}\Big)
	\ge k\epsilon_2\,,\end{equation}
where $\pi_e\equiv\pi_{\bm{t}}$ for an edge $e$ of type $\bm{t}$. Let $\Omega$ be the maximizer of \eqref{e:Psi.of.Omega} that is consistent with $\omega$, and let $\bm{\varpi}_{\bm{L},j}$ be the resulting joint distribution of $(\sigma,\upsilon)$. Then there exists a positive absolute constant $\epsilon_3$ (depending only on $\epsilon_2$) such that for every edge $e\in\delta v(x)$ we have
	\[\bm{\varpi}_{\bm{L},j}\Big(
		\upsilon^1=\SPIN{v}
		\,\Big|\,
		\sigma=\SSPIN{r}\tau\Big)
		\ge 1-\frac1{2^{k\epsilon_3}}\]
for $j=j(\bm{t})$ and all clause types $\bm{L}$ such that 
$\bm{L}(j)=\bm{t}$.
The same holds if we exchange the two copies $i=1,2$.

\begin{proof}
The proof is very similar to (but simpler than) that of Lemma~\ref{l:rrUnforced}, and we omit the details.
\end{proof}

\label{l:ForcedRR}
If the clause type $\bm{L}$ is nice
and diverse (Definition~\ref{d:diverse}), then
	\[
	\bm{\varpi}_{\bm{L},j}(\upsilon=\SPIN{v}\SPIN{v})
	\le \frac1{2^{k(1+\epsilon_4)}}\]
for all $1\le j\le k(\bm{L})$, where $\epsilon_4$ is an absolute constant.

\begin{proof} Throughout the proof, $\epsilon_4$ denotes a small positive number, whose value may change from one occurrence to the next, but ultimately is taken as an absolute constant. Fix $\bm{L},j$, and let $\Xi$ denote the empirical measure of configurations $(\Sigma_e,\smash{\vec{\sigma}}_{(\delta v\cup\delta a)\setminus e})$ over all $e=(av)$ such that $\bm{L}_a=\bm{L}$ and $j(v;a)=j$. In the proof below we assume without loss of generality that the edge $e$ has label $\SPIN{L}_e=\SPIN{+}$.\smallskip

\noindent\bemph{Step 1. Reduction to entropy maximization for a conditional measure.} Let $\SPIN{V}$ denote the subset of all valid configurations $(\Sigma_e,\smash{\vec{\sigma}}_{(\delta v\cup\delta a)\setminus e})$ that have $\Sigma_e\in\set{\SSPIN{w},\SPIN{v}}^2$. Define the conditional measure
	\[
	\mu\Big(\Sigma_e,\smash{\vec{\sigma}}_{(\delta v\cup\delta a)\setminus e}\Big)
	\equiv
	\Xi\bigg(\Sigma_e,\smash{\vec{\sigma}}_{(\delta v\cup\delta a)\setminus e}\,\bigg|\, \SPIN{V}\bigg)\,.
	\]
Note the marginals of $\mu$ must be close to those of the original measure $\Xi$, since Lemma~\ref{l:lotsOfAs} gives
	\begin{equation}\label{e:mu.close.to.Xi}
	\Xi(\SPIN{V})
	\ge
	\bm{\varpi}_{\bm{L},j}(\varsigma=\SSPIN{w}\SSPIN{w})
	\ge 1-O\bigg(\frac{k^2}{2^k}\bigg)\,.\end{equation}
The measure $\mu$ maximizes entropy subject to the marginal distributions of $\sigma_{e'}$ for $e'\ne e$,
as well as of $(\Sigma_e)^i$ for $i=1,2$. By the method of Lagrange multipliers, we can express
	\begin{equation}\label{e:mu.two.sided.tree}
	\mu\Big(\Sigma_e,\smash{\vec{\sigma}}_{(\delta v\cup\delta a)\setminus e}\Big)
	\cong 
	\Bigg\{\prod_{i=1,2} (b_e)^i((\Sigma_e)^i)\Bigg\}
	\Bigg\{
	\prod_{e'\in(\delta v \cup \delta a)\setminus e}
	b_{e'}(\sigma_{e'})\Bigg\}
	\mathbf{1}_{\SPIN{V}}\,,
	\end{equation}
where we fix $(b_e)^i(\SSPIN{w})\equiv1$ for both $i=1,2$.
For $x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$, let us write
$(\Sigma_e,\smash{\vec{\sigma}}_{\delta v\setminus e})\sim x$
if $(\Sigma_e,\smash{\vec{\sigma}}_{\delta v\setminus e})$ is consistent with frozen spin $x_v=x$. Note that for $\Sigma_e\in\set{\SSPIN{w},\SPIN{v}}^2$, we have
	\[
	\bigg\{\smash{\vec{\sigma}}_{\delta v\setminus e}
	: (\Sigma_e,\smash{\vec{\sigma}}_{\delta v\setminus e})\sim x
	\bigg\}
	= S(x) \equiv \prod_{i=1,2} S^i(x^i)\,,
	\]
where $S^i(x^i)$ \bemph{does not depend on $\Sigma_e$}. For instance, for all $\Sigma_e\in\set{\SSPIN{w},\SPIN{v}}^2$,
	\[
	\bigg\{\smash{\vec{\sigma}}_{\delta v\setminus e}
	: (\Sigma_e,\smash{\vec{\sigma}}_{\delta v\setminus e})
	\sim \SPIN{+}\SPIN{+}
	\bigg\}
	=\prod_{i=1,2}
	\overbrace{\Bigg\{(\smash{\vec{\sigma}}_{\delta v\setminus e})^i
	: (\smash{\vec{\sigma}}_{\delta v(\SPIN{-})})^i
		\equiv\SSPIN{y},
	(\smash{\vec{\sigma}}_{\delta v(\SPIN{+})\setminus e})^i
		\equiv \SSPIN{p},
	\sum_{e'\in \delta v(\SPIN{+})\setminus e}
	\Ind{(\sigma_{e'})^i=\SSPIN{r}}\ge1
	\Bigg\}}^{S^i(\SPIN{+})}\,.
	\]
Consequently, the marginal of \eqref{e:mu.two.sided.tree}
on $(x_v,\Sigma_e,\smash{\vec{\sigma}}_{\delta a\setminus e})$ can be written as
	\begin{equation}\label{e:ForcedRR.mu.of.beta}
	\mu(x_v,\Sigma_e,\smash{\vec{\sigma}}_{\delta a\setminus e})
	=\frac{\mathbf{1}_{\SPIN{V}}}Z
	\Bigg\{\prod_{i=1,2} (b_e)^i((\Sigma_e)^i)\Bigg\}
	\overbrace{
	\Bigg\{\sum_{\smash{\vec{\sigma}}_{\delta v\setminus e} \in S(x_v)}
	\prod_{e'\in\delta v\setminus e}
	b_{e'}(\sigma_{e'})
	\Bigg\}}^{\textup{denote this }b_v(x_v)}
	\Bigg\{ \prod_{e'\in \delta a\setminus e}
	b_{e'}(\sigma_{e'})\Bigg\}\,,\end{equation}
where $Z$ is the normalizing constant. We next turn to the construction and estimation of the weights in \eqref{e:ForcedRR.mu.of.beta}.\smallskip

\noindent\bemph{Step 2. Initialization of Lagrangian weights.} We will construct weights $b_t\to b$ in the limit $t\to\infty$. At $t=0$, on the variable $v$ and on the edges $\delta a\setminus e$, we put
	{\setlength{\jot}{0pt}\begin{alignat}{2}
	\nonumber
	b_{v,0}(x)
		&\equiv \mu_v(x)
		\equiv \mu(x_v=x)\quad
		&&\textup{for 
		$x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$,} \\
	b_{e',0}(\sigma)
		&\equiv \mu_{e'}(\sigma)
		\equiv \mu( \sigma_{e'}=\sigma )\quad
		&&\textup{for 
		$\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$
		and $e'\in\delta a\setminus e$.}
	\label{e:vv.lemma.initialization}
		\end{alignat}}
Abbreviate $K\equiv k(\bm{L})$. On the central edge $e=(av)$, for $i=1,2$ we put
	\[(b_{e,0})^i( (\Sigma_e)^i )
		\equiv
		\frac{(\mu_e)^i( (\Sigma_e)^i)}
			{ 1/ (2^K)^{\Ind{(\Sigma_e)^i=\SPIN{v}}} }\,.
		\]
Let $\mu_t$ be defined as $\mu$ in \eqref{e:ForcedRR.mu.of.beta}, but with $b_t$ in place of $b$, and normalizing constant $Z_t$. We begin by estimating the marginals at time $t=0$. Recalling the notation $\SSPIN{u}\equiv\set{\SSPIN{y},\SSPIN{c}}$, we have
	\[
	Z_0\mu_{e,0}(\SSPIN{w}\SSPIN{w})
	= (\mu_e)^1(\SSPIN{w})(\mu_e)^2(\SSPIN{w})
	\Bigg\{\prod_{e'\in\delta a\setminus e}
	\mu_{e'}(\SSPIN{u}\SSPIN{u})\Bigg\}
	\Bigg\{ 1 - O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}
	= (\mu_e)^1(\SSPIN{w})(\mu_e)^2(\SSPIN{w})
	\Bigg\{ 1 - O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}\,,
	\]
where the estimate uses \eqref{e:mu.close.to.Xi} and the assumption that $\bm{L}$ is nice, which implies
(together with the judicious condition) $\Xi_{e'}(\SSPIN{u}\SSPIN{u})\ge 1-O(2^{-k})$ for all $e'\in\delta a$. (In the above calculation, the $O(k^2/2^k)$ error comes from the fact that among the configurations $\smash{\vec{\sigma}}_{\delta a\setminus e}$ with $\sigma_{e'}\in\SSPIN{u}\SSPIN{u}$ for all $e'$, some will not be compatible with $\sigma_e=\SSPIN{w}\SSPIN{w}$ because they will have too few $\SSPIN{c}$ spins.) Next recall that (as noted in the proof of Lemma~\ref{l:lotsOfAsDiverse}) if $\bm{L}$ is both nice and diverse, then Lemma~\ref{l:indifferent} implies \eqref{e:diverse.clause}, which says that $\omega_{\bm{L},j}(\SSPIN{y}\SSPIN{b})\ge1/65$ for at least $k/10$ indices $1\le j\le k(\bm{L})$. Recall also that \eqref{e:mu.close.to.Xi} implies that the marginals of $\mu$ are close to those of the original measure $\Xi$, so \eqref{e:diverse.clause} implies
	\begin{equation}\label{e:diverse.clause.consequence}
	\min\Bigg\{
	\sum_{j=1}^{k(\bm{L})}
	\mathbf{1}\bigg\{
	\mu_j(\SSPIN{y}\SSPIN{b})\ge\frac1{66}
	\bigg\},
	\sum_{j=1}^{k(\bm{L})}
	\mathbf{1}\bigg\{
	\mu_j(\SSPIN{b}\SSPIN{y})\ge\frac1{66}
	\bigg\}
	\Bigg\} \ge \frac{k}{10}\,.\end{equation}
It follows using \eqref{e:diverse.clause.consequence} that 
	\begin{align*}
	Z_0\mu_{e,0}(\SPIN{v}\SSPIN{w})
	&=
	(\mu_e)^1(\SPIN{v})(\mu_e)^2(\SSPIN{w})
	\frac{\mu_v(\SPIN{+}) }{1/2}
	\Bigg\{\prod_{e'\in\delta a\setminus e}
	\frac{\mu_{e'}(\SSPIN{y}\SSPIN{u})}{1/2}
	\Bigg\}
	\Bigg\{ 1 - O\bigg(\frac1{2^{k\epsilon_4}}\bigg)\Bigg\}\\
	&=
	(\mu_e)^1(\SPIN{v})(\mu_e)^2(\SSPIN{w})
	\Bigg\{ 1 - O\bigg(\frac1{2^{k\epsilon_4}}\bigg)
	\Bigg\}\,,
	\end{align*}
where the factors of $1/2$ come from the $2^K$ term in the definition of $(b_{e,0})^1(\SPIN{v})$. Lastly,
	\begin{equation}\label{e:ForcedRR.init.pair.mgl.on.edge}
	Z_0\mu_{e,0}(\SPIN{v}\SPIN{v})
	=\overbrace{
	\frac{(\mu_e)^1(\SPIN{v})}{1/2^K}
	\frac{(\mu_e)^2(\SPIN{v})}{1/2^K}
	}^{O(1)}
	\overbrace{\mu_v(\SPIN{+}\SPIN{+})
	\Bigg\{\prod_{e'\in\delta a\setminus e}
	\mu_{e'}(\SSPIN{y}\SSPIN{y})
	\Bigg\}}^{\textup{at most $2^{-k(1+\epsilon_4)}$
		by \eqref{e:diverse.clause.consequence}}}
	\le 
	O\bigg(
	\frac{\min\set{(\mu_e)^1(\SPIN{v}),(\mu_e)^2(\SPIN{v})}}
		{2^{k\epsilon_4}}
	\bigg)\,.
	\end{equation}
The above estimates imply that the single-copy marginals of $\mu_{e,0}$ are close to those of $\mu_e$: more precisely, we have
	\begin{equation}\label{e:ForcedRR.initial.marginals.on.edge}
	\bigg|
	\frac{(\mu_{e,0})^i(\Sigma^i)}{(\mu_e)^i(\Sigma^i)}-1
	\bigg|
	\le
	\begin{cases}
	k^{O(1)}/2^k &\textup{if $\Sigma^i=\SSPIN{w}$,}\\
	O(2^{-k\epsilon_4}) &\textup{if $\Sigma^i=\SPIN{v}$,}\\
	\end{cases}
	\end{equation}
for both $i=1,2$. We then turn to estimating the marginals at $t=0$ on the edges of $\delta a\setminus e$. For $e'\in \delta a\setminus e$ and $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$, we can represent the marginal probability of $\sigma$ on $e'$ as
	\begin{equation}\label{e:conditional.rep.on.eprime}
	\mu_{e',0}(\sigma)
	=\sum_{\Sigma\in\set{\SSPIN{w},\SSPIN{r}}^2}
	\mu_{e,0}(\Sigma)
	\mu_0\Big(\sigma_{e'}=\sigma\,
		\Big|\,\Sigma_e=\Sigma\Big)\,.
	\end{equation}
The term $\mu_{e,0}(\Sigma)$ was just estimated above,
while the conditional probability 
$\mu_0(\sigma_{e'}=\sigma\,|\,\Sigma_e=\Sigma)$ can be obtained from the representation \eqref{e:ForcedRR.mu.of.beta}. For instance, for each $e'\in\delta a\setminus e$, we have
	\[
	\mu_0\Big(\sigma_{e'}=\SSPIN{y}\SSPIN{y}\,
		\Big|\,\Sigma_e=\SPIN{v}\SSPIN{w}\Big)
	\stackrel{\eqref{e:ForcedRR.mu.of.beta}}{=}
	\frac{\displaystyle 
	\mu_{e'}(\SSPIN{y}\SSPIN{y})
	\prod_{e''\in\delta a\setminus\set{e,e'}}
	\mu_{e''}(\SSPIN{y}\SSPIN{u})}
	{\displaystyle \mu_{e'}(\SSPIN{y}\SSPIN{u}) 
	\prod_{e''\in\delta a\setminus\set{e,e'}}
	\mu_{e''}(\SSPIN{y}\SSPIN{u})}
	\Bigg\{1-O\bigg(\frac1{2^{k\epsilon_4}}\bigg)\Bigg\}
	= \frac{\mu_{e'}(\SSPIN{y}\SSPIN{y})}{1/2}
		\Bigg\{1-O\bigg(\frac1{2^{k\epsilon_4}}\bigg)\Bigg\}\,,
	\]
where the last estimate uses that $e'$ is a nice edge, so $\mu_{e''}(\SSPIN{y}\SSPIN{u})$ is close to $1/2$. Similarly,
	\[\mu_0\Big(\sigma_{e'}=\SSPIN{y}\SSPIN{y}\,
		\Big|\,\Sigma_e=\SSPIN{w}\SSPIN{w}\Big)
	\stackrel{\eqref{e:ForcedRR.mu.of.beta}}{=}
	\frac{\mu_{e'}(\SSPIN{y}\SSPIN{y})}{\mu_{e'}(\SSPIN{u}\SSPIN{u})}
	\Bigg\{1-O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}
	=\mu_{e'}(\SSPIN{y}\SSPIN{y})
	\Bigg\{1-O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}\,.
	\]
Lastly we have $\mu_0(\sigma_{e'}=\SSPIN{y}\SSPIN{y}\,|\,\Sigma_e=\SPIN{v}\SPIN{v})=1$. Substituting the last few estimates into \eqref{e:conditional.rep.on.eprime} gives
	\begin{align*}
	\mu_{e',0}(\SSPIN{y}\SSPIN{y})
	&\stackrel{\eqref{e:conditional.rep.on.eprime}}{=}
	\mu_{e,0}(\SPIN{v}\SPIN{v})
	+\mu_{e,0}\Big(\set{\SPIN{v}\SSPIN{w},\SSPIN{w}\SPIN{v}}\Big)
	\frac{\mu_{e'}(\SSPIN{y}\SSPIN{y})}{1/2}
		\Bigg\{1-O\bigg(\frac1{2^{k\epsilon_4}}\bigg)\Bigg\}
	+\mu_{e,0}(\SSPIN{w}\SSPIN{w}) 
	\mu_{e'}(\SSPIN{y}\SSPIN{y})
	\Bigg\{1-O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}\\
	&\stackrel{\eqref{e:ForcedRR.init.pair.mgl.on.edge}}{=}
	\mu_{e'}(\SSPIN{y}\SSPIN{y})\Bigg\{
	O\bigg(\frac1{2^{k(1+\epsilon_4)}}\bigg)
	+O\bigg( \frac1{2^k}\bigg)
	+ 1-O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}
	=\mu_{e'}(\SSPIN{y}\SSPIN{y})\Bigg\{ 1-O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}\,.
	\end{align*}
By similar (but simpler) calculations, the same estimate holds for the other elements $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$. Lastly, we estimate the marginal law at $t=0$ for the frozen spin $x_v$, using a similar conditioning as in \eqref{e:conditional.rep.on.eprime}. To this end, note that
	\[
	\mu_0\Big(x_v=x\,\Big|\,\Sigma_e=\SSPIN{w}\SSPIN{w}\Big)
	\stackrel{\eqref{e:ForcedRR.mu.of.beta}}{=}
	\frac{\displaystyle b_{v,0}(x)
	\prod_{i=1,2}(b_{e,0})^i(\SSPIN{w})}{
	\displaystyle
	\sum_{x'\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2}
	b_{v,0}(x')
	\prod_{i=1,2}(b_{e,0})^i(\SSPIN{w})}
	\stackrel{\eqref{e:vv.lemma.initialization}}{=}
	\mu_v(x)
	\]
for any $x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$. Likewise we have
	\[
	\mu_0\Big(x_v=x\,\Big|\,\Sigma_e=\SPIN{v}\SSPIN{w}\Big)
	\stackrel{\eqref{e:ForcedRR.mu.of.beta}}{=}
	\frac{\Ind{x^1=\SPIN{+}} b_{v,0}(x)
		(b_{e,0})^1(\SPIN{v})(b_{e,0})^2(\SSPIN{w})}
	{\displaystyle\sum_{x'\in\set{\SPIN{+}}
		\times\set{\SPIN{-},\SPIN{+},\SPIN{f}}}
		b_{v,0}(x')
		(b_{e,0})^1(\SPIN{v})(b_{e,0})^2(\SSPIN{w})}
	\stackrel{\eqref{e:vv.lemma.initialization}}{=}
	\frac{\mu_v(x)}{(\mu_v)^1(\SPIN{+})}
	\Ind{x^1=\SPIN{+}}\,,
	\] 
and a similar expression holds for the case $\Sigma_e=\SSPIN{w}\SSPIN{r}$. Lastly, note that
$\mu_0(x_v=x\,\Big|\,\Sigma_e=\SPIN{v}\SPIN{v})
=\Ind{x=\SPIN{+}\SPIN{+}}$. Substituting these into \eqref{e:conditional.rep.on.eprime} gives 
	\begin{align*}
	\mu_{v,0}(x)
	&\stackrel{\eqref{e:conditional.rep.on.eprime}}{=}
	\mu_{e,0}(\SPIN{v}\SPIN{v})\Ind{x=\SPIN{+}\SPIN{+}}
	+ \mu_{e,0}(\SPIN{v}\SSPIN{w})\frac{\mu_v(x)}
		{(\mu_v)^1(\SPIN{+})}
		{\Ind{x^1=\SPIN{+}}}
	+ \mu_{e,0}(\SSPIN{w}\SPIN{v})\frac{\mu_v(x)}
		{(\mu_v)^2(\SPIN{+})}
		{\Ind{x^2=\SPIN{+}}}
	+\mu_{e,0}(\SSPIN{w}\SSPIN{w}) \mu_v(x)\\
	&\stackrel{\eqref{e:ForcedRR.init.pair.mgl.on.edge}}{=}
	\mu_v(x)
	\Bigg\{
	O\bigg(\frac{\Ind{x=\SPIN{+}\SPIN{+}}}{2^{k(1+\epsilon_4)}}\bigg)
	+O\bigg(\frac{\Ind{x^1=\SPIN{+}}
		+ \Ind{x^2=\SPIN{+}}}{2^k}\bigg)
	+1-O\bigg(\frac{k^2}{2^k}\bigg)
	\Bigg\}
	=\mu_v(x)\Bigg\{
	1-O\bigg(\frac{k^2}{2^k}\bigg)
	\Bigg\}\,.
	\end{align*}
To summarize the last few estimates, we have shown that at $t=0$ we have 
	\begin{equation}\label{e:ForcedRR.initial.marginals.off.edge}
	\begin{pmatrix}
	\displaystyle\bigg\|\frac{\mu_{v,0}}{\mu_v}-1\bigg\|_\infty
	+
	\sum_{i=1,2}
	\bigg|\frac{(\mu_{e,0})^i(\SSPIN{w})}
		{(\mu_e)^i(\SSPIN{w})}-1\bigg|
	+
	\sum_{e'\in\delta a\setminus v}
	\bigg\|\frac{\mu_{e',0}}{\mu_{e'}}-1\bigg\|_\infty
	\\
	\displaystyle\sum_{i=1,2} \bigg|\frac{(\mu_{e,0})^i(\SPIN{v})}
		{(\mu_e)^i(\SPIN{v})}-1\bigg|
		\end{pmatrix}
	\le k^{O(1)}
	 \begin{pmatrix}
		2^{-k}\\ 2^{-k\epsilon_4} \end{pmatrix}\,.
	\end{equation}
We now turn to the construction of the sequence $b_t\to b_\infty\equiv b$, where we recall that $b$ denotes the limiting weights in \eqref{e:ForcedRR.mu.of.beta} that give the solution to the constrained entropy maximization problem.\smallskip

\noindent\bemph{Step 3. Iterative construction and covariance estimates.} For each $t\ge0$, suppose we have the weights $b_t$, which define the measure $\mu_t$. We then define the weights at time $t+1$ by setting
	\begin{equation}\label{e:update.rule.on.central.edge}
	\frac{b_{v,t+1}(x)}{b_{v,t}(x)}
		=\frac{\mu_v(x)}{\mu_{v,t}(x)}\,,\quad
	\frac{b_{e',t+1}(\sigma)}{b_{e',t}(\sigma)}
		=\frac{\mu_{e'}(\sigma)}{\mu_{e',t}(\sigma)}
			\,,\quad
	\frac{(b_{e,t+1})^i(\Sigma^i)}{(b_{e,t})^i(\Sigma^i)}
		=\frac{\mu_e(\Sigma^i)}{\mu_{e,t}(\Sigma^i)}
	\end{equation}
for all $x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$,
 $e'\in\delta a\setminus e$,
 $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$, 
 $i=1,2$, and $\Sigma^i\in\set{\SSPIN{w},\SPIN{v}}$. We will show by induction that for all $t\ge0$ we have the bound
	\begin{equation}\label{e:tree.a.v.induct}
	\begin{pmatrix} \displaystyle
	\bigg\|
		\frac{\mu_{v,t}}{\mu_v}
		-1\bigg\|_\infty
	+\sum_{i=1,2}
	\bigg|\frac{(\mu_{e,t})^i(\SSPIN{w})}
		{(\mu_e)^i(\SSPIN{w})}-1\bigg|
	+\sum_{e'\in\delta a\setminus e}
	\bigg\| \frac{\mu_{e',t}}{\mu_{e'}}-1\bigg\|_\infty\\
	\displaystyle \sum_{i=1,2}
		\bigg|\frac{(\mu_{e,t})^i(\SPIN{v})}
		{(\mu_e)^i(\SPIN{v})}-1\bigg|
	\end{pmatrix}
	\le \frac{k^{O(1)}}{(2^{k\epsilon_4})^{t/2}}
	\begin{pmatrix}2^{-k}\\2^{-k\epsilon_4}
		\end{pmatrix}\,,
	\end{equation}
where the base case $t=0$ follows from \eqref{e:ForcedRR.initial.marginals.off.edge}.
Note that
\eqref{e:update.rule.on.central.edge} and \eqref{e:tree.a.v.induct}
together imply
	\begin{equation}\label{e:induct.consequence.on.sum.b}
	\begin{pmatrix}
	\displaystyle \Bigg\{
		\bigg\|\frac{b_{v,t+1}}{b_{v,t}}-1\bigg\|_\infty
		+\sum_{i=1,2}
		\bigg|\frac{(b_{e',t+1})^i(\SSPIN{w})}
			{(b_{e',t})^i(\SSPIN{w})}
			-1\bigg|
		+\sum_{e'\in\delta a\setminus e}
		\bigg\|\frac{b_{e',t+1}}{b_{e',t}}-1\bigg\|_\infty
		\Bigg\}\\
	\displaystyle\sum_{i=1,2}
		\bigg|\frac{(b_{e',t+1})^i(\SPIN{v})}
			{(b_{e',t})^i(\SPIN{v})}
			-1\bigg|
	\end{pmatrix}
	\le \frac{k^{O(1)}}{(2^{k\epsilon_4})^{t/2}}
	\begin{pmatrix}2^{-k}\\2^{-k\epsilon_4}
		\end{pmatrix}\,,
	\end{equation}
Towards the proof of \eqref{e:tree.a.v.induct},
we estimate covariances under the measure $\mu_t$. First, for all $x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$ we have 	\begin{align*}
	\frac{Z_t \mu_t(x_v=x,(\Sigma_e)^1=\SSPIN{w})}
		{\mu_v(x) (\mu_e)^1(\SSPIN{w})}
	&=\frac{b_{v,t}(x)
	(b_{e,t})^1(\SSPIN{w})}{\mu_v(x) (\mu_e)^1(\SSPIN{w})}
	\Bigg\{
	(b_{e,t})^2(\SSPIN{w})
	\prod_{e'\in\delta a\setminus e}
		b_{e',t}(\SSPIN{u}\SSPIN{u})
		\bigg(1-\frac{k^{O(1)}}{2^k}\bigg)\\
	&\qquad\qquad\qquad
		+\Ind{x^2=\SPIN{+}}(b_{e,t})^2(\SPIN{v})
		\prod_{e'}b_{e',t}(\SSPIN{u}\SSPIN{y})
		\bigg(1-\frac{O(1)}{2^{k\epsilon_4}}\bigg)
	\Bigg\}\\
	&=\frac{b_{v,t}(x)
	(b_{e,t})^1(\SSPIN{w})}{\mu_v(x) (\mu_e)^1(\SSPIN{w})}
	\Bigg\{1-\frac{k^{O(1)}}{2^k}\Bigg\}
	\stackrel{\eqref{e:induct.consequence.on.sum.b}}{=}
	1-\frac{k^{O(1)}}{2^k}\,.
	\end{align*}
In combination with \eqref{e:tree.a.v.induct}, this implies that for all $x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$ and $i=1,2$ we have
	\[\Bigg|
	\frac{\mathrm{Cov}_{\mu_t}(
		\Ind{x_v=x},
		\Ind{(\Sigma_e)^i=\SSPIN{w}})}
		{\mu_v(x) (\mu_e)^i(\SSPIN{w})}\Bigg|
	=\Bigg| \frac{\mu_t(x_v=x,(\Sigma_e)^1=\SSPIN{w})}
		{\mu_v(x) (\mu_e)^1(\SSPIN{w})}
		-\frac{\mu_{v,t}(x) (\mu_{e,t})^1(\SSPIN{w})}
		{\mu_v(x) (\mu_e)^1(\SSPIN{w})}
		\Bigg|
	\le \frac{k^{O(1)}}{2^k}\,.
	\]
Next, for $e'\in\delta a\setminus e$ and
$\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$, we calculate
	\begin{align*}
	\frac{Z_t \mu_t((\Sigma_e)^1=\SSPIN{w},
		\sigma_{e'}=\sigma)}
		{(\mu_e)^1(\SSPIN{w})\mu_{e'}(\sigma)}
	&=
	\frac{(b_{e,t})^1(\SSPIN{w})b_{e',t}(\sigma)}
		{(\mu_e)^1(\SSPIN{w})\mu_{e'}(\sigma)}
	\Bigg\{
	(b_{e,t})^2(\SSPIN{w})
	\prod_{e''\in\delta a\setminus\set{e,e'}}
	b_{e'',t}(\SSPIN{u}\SSPIN{u})
	\bigg(1-\frac{k^{O(1)}}{2^k}\bigg) \\
	&\qquad\qquad\qquad
	+\Ind{\sigma^2=\SSPIN{y}}
	(b_{e,t})^2(\SPIN{v})
	(b_{v,t})^2(\SPIN{+})
	\prod_{e''\in\delta a\setminus\set{e,e'}}
	b_{e'',t}(\SSPIN{u}\SSPIN{y})
	\bigg(1-\frac{O(1)}{2^{k\epsilon_4}}\bigg)
	\Bigg\}\\
	&=	\frac{(b_{e,t})^1(\SSPIN{w})b_{e',t}(\sigma)}
		{(\mu_e)^1(\SSPIN{w})\mu_{e'}(\sigma)}
	\Bigg\{1- \frac{k^{O(1)}}{2^k}\Bigg\}
	\stackrel{\eqref{e:induct.consequence.on.sum.b}}{=}
	1- \frac{k^{O(1)}}{2^k}\,.
	\end{align*}
This implies that for all $e'\in\delta a\setminus e$ and $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$, we have
	\[
	\frac{\mathrm{Cov}_{\mu_t}(
		\Ind{(\Sigma_e)^i=\SSPIN{w}},
		\Ind{\sigma_{e'}=\sigma})}
		{(\mu_e)^i(\SSPIN{w})
		\mu_{e'}(\sigma)
		 }
		\le\frac{k^{O(1)}}{2^k}\,.
	\]
Similar calculations for the case $(\Sigma_e)^i=\SPIN{v}$ give 
	\begin{align*}
	\frac{\mathrm{Cov}_{\mu_t}(\Ind{x_v=x},
		\Ind{(\Sigma_e)^i=\SPIN{v}})}
		{\mu_v(x)
		(\mu_e)^i(\SPIN{v})}
	&\le O(1)\,,\\
	\frac{\mathrm{Cov}_{\mu_t}(
		\Ind{(\Sigma_e)^i=\SPIN{v}},
		\Ind{\sigma_{e'}=\sigma})}
			{(\mu_e)^i(\SPIN{v})
		\mu_{e'}(\sigma)}
	&\le O(1)\,,
	\end{align*}
for all $x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$,
 $e'\in\delta a\setminus e$, and $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$. Next, on the edge $e=(av)$, we have
 	\[
	\frac{Z_t\mu_{e,t}(\SSPIN{w}\SSPIN{w})}
		{(\mu_e)^1(\SSPIN{w})(\mu_e)^2(\SSPIN{w})}
	= \frac{(b_{e,t})^1(\SSPIN{w})(b_{e,t})^2(\SSPIN{w})}
		{(\mu_e)^1(\SSPIN{w})(\mu_e)^2(\SSPIN{w})}
	\prod_{e'\in\delta a\setminus e}
		b_{e',t}(\SSPIN{u}\SSPIN{u})
	\Bigg\{1-\frac{k^{O(1)}}{2^k}\Bigg\}
	\stackrel{\eqref{e:induct.consequence.on.sum.b}}{=}
	1- \frac{k^{O(1)}}{2^k}\,.
	\]
Next, using the diversity bound
\eqref{e:diverse.clause.consequence}, we also have
	\begin{align*}
	\frac{Z_t\mu_{e,t}(\SPIN{v}\SSPIN{w})}
		{(\mu_e)^1(\SPIN{v})(\mu_e)^2(\SSPIN{w})}
	&\stackrel{\eqref{e:diverse.clause.consequence}}{=} 
	\frac{(b_{e,t})^1(\SPIN{v})(b_{e,t})^2(\SSPIN{w})}
		{(\mu_e)^1(\SPIN{v})(\mu_e)^2(\SSPIN{w})}
	(b_{v,t})^1(\SPIN{+}) 
	\prod_{e'\in\delta a\setminus e}
		b_{e',t}(\SSPIN{y}\SSPIN{u})
	\Bigg\{1-\frac{O(1)}{2^{k\epsilon_4}}\Bigg\} \\
	&
	\stackrel{\eqref{e:induct.consequence.on.sum.b}}{=}
	\Bigg\{1-\frac{O(1)}{2^{k\epsilon_4}}\Bigg\}
	2^K (b_{v,t})^1(\SPIN{+}) 
	\prod_{e'\in\delta a\setminus e}
		b_{e',t}(\SSPIN{y}\SSPIN{u})
	\stackrel{\eqref{e:induct.consequence.on.sum.b}}{=}
	1-\frac{O(1)}{2^{k\epsilon_4}}\,,\\
	\frac{Z_t\mu_{e,t}(\SPIN{v}\SPIN{v})}
		{(\mu_e)^1(\SPIN{v})(\mu_e)^2(\SPIN{v})}
	&= \frac{(b_{e,t})^1(\SPIN{v})(b_{e,t})^2(\SPIN{v})}
		{(\mu_e)^1(\SPIN{v})(\mu_e)^2(\SPIN{v})}
	\mu_v(\SPIN{+}\SPIN{+})
	\prod_{e'\in\delta v\setminus e}
	b_{e',t}(\SSPIN{y}\SSPIN{y})\\
	&\stackrel{\eqref{e:induct.consequence.on.sum.b}}{=} 2^K \cdot 2^K\cdot
	\mu_v(\SPIN{+}\SPIN{+})
	\prod_{e'\in\delta v\setminus e}
	b_{e',t}(\SSPIN{y}\SSPIN{y})
	\stackrel{\eqref{e:diverse.clause.consequence}}{\le }
	O\bigg( \frac{2^k}{2^{k\epsilon_4}}\bigg)
	\,.\end{align*}
The last few estimates combined imply
	\[
	\frac{\mathrm{Cov}_{\mu_t}(\Ind{(\Sigma_e)^1=\Sigma^1},
	\Ind{(\Sigma_e)^2=\Sigma^2})}
		{(\mu_e)^1(\Sigma^1)
		(\mu_e)^2(\Sigma^2)}
	\le k^{O(1)} \begin{cases}
	2^{-k}&\textup{if $\Sigma=\SSPIN{w}\SSPIN{w}$,}\\
	2^{-k\epsilon_4}&\textup{if $\Sigma\in\set{\SPIN{v}\SSPIN{w},
		\SSPIN{w}\SPIN{v}}$,}\\
	2^{k(1-\epsilon_4)}
	&\textup{if $\Sigma=\SPIN{v}\SPIN{v}$.}
	\end{cases}
	\]
Lastly, it is straightforward to verify (details omitted) that
	\[\frac{\mathrm{Cov}_{\mu_t}(
		\Ind{x_v=x},
		\Ind{\sigma_{e'}=\sigma})}
			{ \mu_v(x) \mu_{e'}(\sigma)}
	\le \frac{k^{O(1)}}{2^k}
	\]
for all 
 $x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$,
$e'\in\delta a \setminus e$, and $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$.\smallskip

\noindent\bemph{Step 4. Estimates on Lagrangian weights.}
Now recall from 
\eqref{e:derivative.is.covariance}
that derivatives of $\mu_t$-marginals with respect to $b_t$ can be expressed as covariance. Let $\tilde{\mu}_{t+1}$ be defined by
	\[
	\tilde{\mu}_{t+1}
	\Big(x_v,\Sigma_e,\smash{\vec{\sigma}}_{\delta a\setminus e}\Big)	
	=
	\frac1{\tilde{Z}_{t+1}}
	b_{v,t}(x)
	(b_{e,t+1})^1((\Sigma_e)^1)
	(b_{e,t})^2((\Sigma_e)^2)
	\prod_{e'\in\delta a\setminus e}
		b_{e',t}(\sigma_{e'})\,,
	\]
where $\tilde{Z}_{t+1}$ is the normalizing constant. It follows from the update rule \eqref{e:update.rule.on.central.edge} that
the marginal of $\tilde{\mu}_{t+1}$ on $(\Sigma_e)^1$
is exactly the desired marginal $(\mu_e)^1$. Consequently,
	\begin{align*}
	\delta_{t+1}(\Sigma^1) &\equiv \bigg|
	\frac{(\mu_{e,t+1})^1(\Sigma^1)}{(\mu_e)^1(\Sigma^1)}-1
	\bigg|
	=\bigg|
	\frac{(\mu_{e,t+1})^1(\Sigma^1)}
		{(\tilde{\mu}_{e,t+1})^1(\Sigma^1)}-1\bigg|
	\\
	&\le
	\frac1{(\mu_e)^1(\Sigma^1)}
	O\Bigg(
	\sum_x
	\frac{\partial\mu_{e,t+1}(\Sigma^1)}
		{\partial\ln b_{v,t+1}(x)}
	\bigg| \frac{b_{v,t+1}(x)}{b_{v,t}(x)}-1\bigg|
	+\sum_{\Sigma^2}
	\frac{\partial\mu_{e,t+1}(\Sigma^1)}
		{\partial\ln (b_{e,t+1})^2(\Sigma^2)}
	\bigg| \frac{(b_{e,t+1})^2(\Sigma^2)}
		{(b_{e,t})^2(\Sigma^2)}
	-1\bigg|
	\\
	&\qquad\qquad\qquad\qquad\qquad\qquad\qquad
	+\sum_{e',\sigma}
	\frac{\partial\mu_{e,t+1}(\Sigma^1)}
		{\partial\ln b_{e',t+1}(\sigma)}
		\bigg|
		\frac{b_{e',t+1}(\sigma)}
			{b_{e',t}(\sigma)}-1\bigg|
	\Bigg)\,.
	\end{align*}
Substituting the preceding covariance estimates into the last bound and applying \eqref{e:induct.consequence.on.sum.b} gives
	\begin{align*}
	\delta_{t+1}(\SSPIN{w})
	&\le
	k^{O(1)}\Bigg\{
	\frac1{2^k}
	\cdot
	\frac{1}{2^k(2^{k\epsilon_4/2})^t}
	+	\frac1{2^{k\epsilon_4}} \cdot
	(\mu_e)^2(\SPIN{v})
	\cdot
	\bigg|\frac{(b_{e,t+1})^2(\SPIN{v})}
		{(b_{e,t})^2(\SPIN{v})}-1 \bigg|
	\Bigg\}\\
	&\le k^{O(1)}\Bigg\{
	\frac1{2^k}
	\cdot
	\frac{1}{2^k(2^{k\epsilon_4/2})^t}
	+	\frac1{2^{k\epsilon_4}}
	\cdot \frac1{2^k}
	\cdot \frac1{2^{k\epsilon_4}((2^{k\epsilon_4/2})^t}
	\Bigg\}
	\le \frac{k^{O(1)}}{2^k(2^{k\epsilon_4/2})^{t+2}}\,,\\
	\delta_{t+1}(\SPIN{v})
	&\le
	k^{O(1)}\Bigg\{
	\frac1{2^{k\epsilon_4}((2^{k\epsilon_4/2})^t}
	+ 2^{k(1-\epsilon_4)}
	\cdot(\mu_e)^2(\SPIN{v})
	\cdot \frac1{2^{k\epsilon_4}((2^{k\epsilon_4/2})^t}
	\Bigg\}
	\le 
	\frac{k^{O(1)}}{2^{k\epsilon_4}(2^{k\epsilon_4/2})^{t+2}}\,.
	\end{align*}
This verifies the inductive hypothesis \eqref{e:tree.a.v.induct} for the quantities
	\[
	\delta_{t+1}(\Sigma^i)
	= \bigg|\frac{(\mu_{e,t+1})^i(\Sigma^i)}
		{(\mu_e)^i(\Sigma^i)}-1\bigg|\,.
	\]
The remaining estimates in \eqref{e:tree.a.v.induct} follow by similar calculations (details omitted). It follows that as $t\to\infty$ the weights $b_t$ converge to the desired limiting weights $b_\infty\equiv b$ that define the optimal measure $\mu$ in \eqref{e:ForcedRR.mu.of.beta}. It then follows from the bound \eqref{e:induct.consequence.on.sum.b} that
	\begin{align*}
	\mu_e(\SPIN{v}\SPIN{v})
	&\stackrel{\eqref{e:ForcedRR.mu.of.beta}}{=}
	O\Bigg(
	b_v(\SPIN{+}\SPIN{+})
	\Bigg\{\prod_{i=1,2} (b_e)^i(\SPIN{v})\Bigg\}
	\Bigg\{ \prod_{e'\in\delta a\setminus e}
		b_{e'}(\SSPIN{y}\SSPIN{y})\Bigg\}
		\Bigg)\\
	&\stackrel{\eqref{e:induct.consequence.on.sum.b}}{=}
	O\Bigg(
	\mu_v(\SPIN{+}\SPIN{+})
	\prod_{i=1,2}\Big(
	(\mu_e)^i(\SPIN{v}) 2^K\Big)
	\prod_{e'\in\delta a\setminus e}
		\mu_{e'}(\SSPIN{y}\SSPIN{y})\Bigg)
	\stackrel{\eqref{e:diverse.clause.consequence}}{\le}
	\frac1{2^{k(1+\epsilon_4)}}\,,
	\end{align*}
as claimed.
\end{proof}

 Throughout the proof, $\epsilon_4$ denotes a small positive number, whose value may change from one occurrence to the next, but ultimately is taken as an absolute constant. Fix $\bm{L},j$, and let $\Xi$ denote the empirical measure of configurations $(\Sigma_e,\smash{\vec{\sigma}}_{(\delta v\cup\delta a)\setminus e})$ over all $e=(av)$ such that $\bm{L}_a=\bm{L}$ and $j(v;a)=j$. In the proof below we assume without loss of generality that the edge $e$ has label $\SPIN{L}_e=\SPIN{+}$.\smallskip

\noindent\bemph{Step 1. Reduction to entropy maximization for a conditional measure.} Let $\SPIN{V}$ denote the subset of all valid configurations $(\Sigma_e,\smash{\vec{\sigma}}_{(\delta v\cup\delta a)\setminus e})$ that have $\Sigma_e\in\set{\SSPIN{w},\SPIN{v}}^2$. Define the conditional measure
	\[
	\mu\Big(\Sigma_e,\smash{\vec{\sigma}}_{(\delta v\cup\delta a)\setminus e}\Big)
	\equiv
	\Xi\bigg(\Sigma_e,\smash{\vec{\sigma}}_{(\delta v\cup\delta a)\setminus e}\,\bigg|\, \SPIN{V}\bigg)\,.
	\]
Note the marginals of $\mu$ must be close to those of the original measure $\Xi$, since Lemma~\ref{l:lotsOfAs} gives
	\begin{equation}\label{e:mu.close.to.Xi}
	\Xi(\SPIN{V})
	\ge
	\bm{\varpi}_{\bm{L},j}(\varsigma=\SSPIN{w}\SSPIN{w})
	\ge 1-O\bigg(\frac{k^2}{2^k}\bigg)\,.\end{equation}
The measure $\mu$ maximizes entropy subject to the marginal distributions of $\sigma_{e'}$ for $e'\ne e$,
as well as of $(\Sigma_e)^i$ for $i=1,2$. By the method of Lagrange multipliers, we can express
	\begin{equation}\label{e:mu.two.sided.tree}
	\mu\Big(\Sigma_e,\smash{\vec{\sigma}}_{(\delta v\cup\delta a)\setminus e}\Big)
	\cong 
	\Bigg\{\prod_{i=1,2} (b_e)^i((\Sigma_e)^i)\Bigg\}
	\Bigg\{
	\prod_{e'\in(\delta v \cup \delta a)\setminus e}
	b_{e'}(\sigma_{e'})\Bigg\}
	\mathbf{1}_{\SPIN{V}}\,,
	\end{equation}
where we fix $(b_e)^i(\SSPIN{w})\equiv1$ for both $i=1,2$.
For $x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$, let us write
$(\Sigma_e,\smash{\vec{\sigma}}_{\delta v\setminus e})\sim x$
if $(\Sigma_e,\smash{\vec{\sigma}}_{\delta v\setminus e})$ is consistent with frozen spin $x_v=x$. Note that for $\Sigma_e\in\set{\SSPIN{w},\SPIN{v}}^2$, we have
	\[
	\bigg\{\smash{\vec{\sigma}}_{\delta v\setminus e}
	: (\Sigma_e,\smash{\vec{\sigma}}_{\delta v\setminus e})\sim x
	\bigg\}
	= S(x) \equiv \prod_{i=1,2} S^i(x^i)\,,
	\]
where $S^i(x^i)$ \bemph{does not depend on $\Sigma_e$}. For instance, for all $\Sigma_e\in\set{\SSPIN{w},\SPIN{v}}^2$,
	\[
	\bigg\{\smash{\vec{\sigma}}_{\delta v\setminus e}
	: (\Sigma_e,\smash{\vec{\sigma}}_{\delta v\setminus e})
	\sim \SPIN{+}\SPIN{+}
	\bigg\}
	=\prod_{i=1,2}
	\overbrace{\Bigg\{(\smash{\vec{\sigma}}_{\delta v\setminus e})^i
	: (\smash{\vec{\sigma}}_{\delta v(\SPIN{-})})^i
		\equiv\SSPIN{y},
	(\smash{\vec{\sigma}}_{\delta v(\SPIN{+})\setminus e})^i
		\equiv \SSPIN{p},
	\sum_{e'\in \delta v(\SPIN{+})\setminus e}
	\Ind{(\sigma_{e'})^i=\SSPIN{r}}\ge1
	\Bigg\}}^{S^i(\SPIN{+})}\,.
	\]
Consequently, the marginal of \eqref{e:mu.two.sided.tree}
on $(x_v,\Sigma_e,\smash{\vec{\sigma}}_{\delta a\setminus e})$ can be written as
	\begin{equation}\label{e:ForcedRR.mu.of.beta}
	\mu(x_v,\Sigma_e,\smash{\vec{\sigma}}_{\delta a\setminus e})
	=\frac{\mathbf{1}_{\SPIN{V}}}Z
	\Bigg\{\prod_{i=1,2} (b_e)^i((\Sigma_e)^i)\Bigg\}
	\overbrace{
	\Bigg\{\sum_{\smash{\vec{\sigma}}_{\delta v\setminus e} \in S(x_v)}
	\prod_{e'\in\delta v\setminus e}
	b_{e'}(\sigma_{e'})
	\Bigg\}}^{\textup{denote this }b_v(x_v)}
	\Bigg\{ \prod_{e'\in \delta a\setminus e}
	b_{e'}(\sigma_{e'})\Bigg\}\,,\end{equation}
where $Z$ is the normalizing constant. We next turn to the construction and estimation of the weights in \eqref{e:ForcedRR.mu.of.beta}.\smallskip

\noindent\bemph{Step 2. Initialization of Lagrangian weights.} We will construct weights $b_t\to b$ in the limit $t\to\infty$. At $t=0$, on the variable $v$ and on the edges $\delta a\setminus e$, we put
	{\setlength{\jot}{0pt}\begin{alignat}{2}
	\nonumber
	b_{v,0}(x)
		&\equiv \mu_v(x)
		\equiv \mu(x_v=x)\quad
		&&\textup{for 
		$x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$,} \\
	b_{e',0}(\sigma)
		&\equiv \mu_{e'}(\sigma)
		\equiv \mu( \sigma_{e'}=\sigma )\quad
		&&\textup{for 
		$\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$
		and $e'\in\delta a\setminus e$.}
	\label{e:vv.lemma.initialization}
		\end{alignat}}
Abbreviate $K\equiv k(\bm{L})$. On the central edge $e=(av)$, for $i=1,2$ we put
	\[(b_{e,0})^i( (\Sigma_e)^i )
		\equiv
		\frac{(\mu_e)^i( (\Sigma_e)^i)}
			{ 1/ (2^K)^{\Ind{(\Sigma_e)^i=\SPIN{v}}} }\,.
		\]
Let $\mu_t$ be defined as $\mu$ in \eqref{e:ForcedRR.mu.of.beta}, but with $b_t$ in place of $b$, and normalizing constant $Z_t$. We begin by estimating the marginals at time $t=0$. Recalling the notation $\SSPIN{u}\equiv\set{\SSPIN{y},\SSPIN{c}}$, we have
	\[
	Z_0\mu_{e,0}(\SSPIN{w}\SSPIN{w})
	= (\mu_e)^1(\SSPIN{w})(\mu_e)^2(\SSPIN{w})
	\Bigg\{\prod_{e'\in\delta a\setminus e}
	\mu_{e'}(\SSPIN{u}\SSPIN{u})\Bigg\}
	\Bigg\{ 1 - O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}
	= (\mu_e)^1(\SSPIN{w})(\mu_e)^2(\SSPIN{w})
	\Bigg\{ 1 - O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}\,,
	\]
where the estimate uses \eqref{e:mu.close.to.Xi} and the assumption that $\bm{L}$ is nice, which implies
(together with the judicious condition) $\Xi_{e'}(\SSPIN{u}\SSPIN{u})\ge 1-O(2^{-k})$ for all $e'\in\delta a$. (In the above calculation, the $O(k^2/2^k)$ error comes from the fact that among the configurations $\smash{\vec{\sigma}}_{\delta a\setminus e}$ with $\sigma_{e'}\in\SSPIN{u}\SSPIN{u}$ for all $e'$, some will not be compatible with $\sigma_e=\SSPIN{w}\SSPIN{w}$ because they will have too few $\SSPIN{c}$ spins.) Next recall that (as noted in the proof of Lemma~\ref{l:lotsOfAsDiverse}) if $\bm{L}$ is both nice and diverse, then Lemma~\ref{l:indifferent} implies \eqref{e:diverse.clause}, which says that $\omega_{\bm{L},j}(\SSPIN{y}\SSPIN{b})\ge1/65$ for at least $k/10$ indices $1\le j\le k(\bm{L})$. Recall also that \eqref{e:mu.close.to.Xi} implies that the marginals of $\mu$ are close to those of the original measure $\Xi$, so \eqref{e:diverse.clause} implies
	\begin{equation}\label{e:diverse.clause.consequence}
	\min\Bigg\{
	\sum_{j=1}^{k(\bm{L})}
	\mathbf{1}\bigg\{
	\mu_j(\SSPIN{y}\SSPIN{b})\ge\frac1{66}
	\bigg\},
	\sum_{j=1}^{k(\bm{L})}
	\mathbf{1}\bigg\{
	\mu_j(\SSPIN{b}\SSPIN{y})\ge\frac1{66}
	\bigg\}
	\Bigg\} \ge \frac{k}{10}\,.\end{equation}
It follows using \eqref{e:diverse.clause.consequence} that 
	\begin{align*}
	Z_0\mu_{e,0}(\SPIN{v}\SSPIN{w})
	&=
	(\mu_e)^1(\SPIN{v})(\mu_e)^2(\SSPIN{w})
	\frac{\mu_v(\SPIN{+}) }{1/2}
	\Bigg\{\prod_{e'\in\delta a\setminus e}
	\frac{\mu_{e'}(\SSPIN{y}\SSPIN{u})}{1/2}
	\Bigg\}
	\Bigg\{ 1 - O\bigg(\frac1{2^{k\epsilon_4}}\bigg)\Bigg\}\\
	&=
	(\mu_e)^1(\SPIN{v})(\mu_e)^2(\SSPIN{w})
	\Bigg\{ 1 - O\bigg(\frac1{2^{k\epsilon_4}}\bigg)
	\Bigg\}\,,
	\end{align*}
where the factors of $1/2$ come from the $2^K$ term in the definition of $(b_{e,0})^1(\SPIN{v})$. Lastly,
	\begin{equation}\label{e:ForcedRR.init.pair.mgl.on.edge}
	Z_0\mu_{e,0}(\SPIN{v}\SPIN{v})
	=\overbrace{
	\frac{(\mu_e)^1(\SPIN{v})}{1/2^K}
	\frac{(\mu_e)^2(\SPIN{v})}{1/2^K}
	}^{O(1)}
	\overbrace{\mu_v(\SPIN{+}\SPIN{+})
	\Bigg\{\prod_{e'\in\delta a\setminus e}
	\mu_{e'}(\SSPIN{y}\SSPIN{y})
	\Bigg\}}^{\textup{at most $2^{-k(1+\epsilon_4)}$
		by \eqref{e:diverse.clause.consequence}}}
	\le 
	O\bigg(
	\frac{\min\set{(\mu_e)^1(\SPIN{v}),(\mu_e)^2(\SPIN{v})}}
		{2^{k\epsilon_4}}
	\bigg)\,.
	\end{equation}
The above estimates imply that the single-copy marginals of $\mu_{e,0}$ are close to those of $\mu_e$: more precisely, we have
	\begin{equation}\label{e:ForcedRR.initial.marginals.on.edge}
	\bigg|
	\frac{(\mu_{e,0})^i(\Sigma^i)}{(\mu_e)^i(\Sigma^i)}-1
	\bigg|
	\le
	\begin{cases}
	k^{O(1)}/2^k &\textup{if $\Sigma^i=\SSPIN{w}$,}\\
	O(2^{-k\epsilon_4}) &\textup{if $\Sigma^i=\SPIN{v}$,}\\
	\end{cases}
	\end{equation}
for both $i=1,2$. We then turn to estimating the marginals at $t=0$ on the edges of $\delta a\setminus e$. For $e'\in \delta a\setminus e$ and $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$, we can represent the marginal probability of $\sigma$ on $e'$ as
	\begin{equation}\label{e:conditional.rep.on.eprime}
	\mu_{e',0}(\sigma)
	=\sum_{\Sigma\in\set{\SSPIN{w},\SSPIN{r}}^2}
	\mu_{e,0}(\Sigma)
	\mu_0\Big(\sigma_{e'}=\sigma\,
		\Big|\,\Sigma_e=\Sigma\Big)\,.
	\end{equation}
The term $\mu_{e,0}(\Sigma)$ was just estimated above,
while the conditional probability 
$\mu_0(\sigma_{e'}=\sigma\,|\,\Sigma_e=\Sigma)$ can be obtained from the representation \eqref{e:ForcedRR.mu.of.beta}. For instance, for each $e'\in\delta a\setminus e$, we have
	\[
	\mu_0\Big(\sigma_{e'}=\SSPIN{y}\SSPIN{y}\,
		\Big|\,\Sigma_e=\SPIN{v}\SSPIN{w}\Big)
	\stackrel{\eqref{e:ForcedRR.mu.of.beta}}{=}
	\frac{\displaystyle 
	\mu_{e'}(\SSPIN{y}\SSPIN{y})
	\prod_{e''\in\delta a\setminus\set{e,e'}}
	\mu_{e''}(\SSPIN{y}\SSPIN{u})}
	{\displaystyle \mu_{e'}(\SSPIN{y}\SSPIN{u}) 
	\prod_{e''\in\delta a\setminus\set{e,e'}}
	\mu_{e''}(\SSPIN{y}\SSPIN{u})}
	\Bigg\{1-O\bigg(\frac1{2^{k\epsilon_4}}\bigg)\Bigg\}
	= \frac{\mu_{e'}(\SSPIN{y}\SSPIN{y})}{1/2}
		\Bigg\{1-O\bigg(\frac1{2^{k\epsilon_4}}\bigg)\Bigg\}\,,
	\]
where the last estimate uses that $e'$ is a nice edge, so $\mu_{e''}(\SSPIN{y}\SSPIN{u})$ is close to $1/2$. Similarly,
	\[\mu_0\Big(\sigma_{e'}=\SSPIN{y}\SSPIN{y}\,
		\Big|\,\Sigma_e=\SSPIN{w}\SSPIN{w}\Big)
	\stackrel{\eqref{e:ForcedRR.mu.of.beta}}{=}
	\frac{\mu_{e'}(\SSPIN{y}\SSPIN{y})}{\mu_{e'}(\SSPIN{u}\SSPIN{u})}
	\Bigg\{1-O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}
	=\mu_{e'}(\SSPIN{y}\SSPIN{y})
	\Bigg\{1-O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}\,.
	\]
Lastly we have $\mu_0(\sigma_{e'}=\SSPIN{y}\SSPIN{y}\,|\,\Sigma_e=\SPIN{v}\SPIN{v})=1$. Substituting the last few estimates into \eqref{e:conditional.rep.on.eprime} gives
	\begin{align*}
	\mu_{e',0}(\SSPIN{y}\SSPIN{y})
	&\stackrel{\eqref{e:conditional.rep.on.eprime}}{=}
	\mu_{e,0}(\SPIN{v}\SPIN{v})
	+\mu_{e,0}\Big(\set{\SPIN{v}\SSPIN{w},\SSPIN{w}\SPIN{v}}\Big)
	\frac{\mu_{e'}(\SSPIN{y}\SSPIN{y})}{1/2}
		\Bigg\{1-O\bigg(\frac1{2^{k\epsilon_4}}\bigg)\Bigg\}
	+\mu_{e,0}(\SSPIN{w}\SSPIN{w}) 
	\mu_{e'}(\SSPIN{y}\SSPIN{y})
	\Bigg\{1-O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}\\
	&\stackrel{\eqref{e:ForcedRR.init.pair.mgl.on.edge}}{=}
	\mu_{e'}(\SSPIN{y}\SSPIN{y})\Bigg\{
	O\bigg(\frac1{2^{k(1+\epsilon_4)}}\bigg)
	+O\bigg( \frac1{2^k}\bigg)
	+ 1-O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}
	=\mu_{e'}(\SSPIN{y}\SSPIN{y})\Bigg\{ 1-O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}\,.
	\end{align*}
By similar (but simpler) calculations, the same estimate holds for the other elements $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$. Lastly, we estimate the marginal law at $t=0$ for the frozen spin $x_v$, using a similar conditioning as in \eqref{e:conditional.rep.on.eprime}. To this end, note that
	\[
	\mu_0\Big(x_v=x\,\Big|\,\Sigma_e=\SSPIN{w}\SSPIN{w}\Big)
	\stackrel{\eqref{e:ForcedRR.mu.of.beta}}{=}
	\frac{\displaystyle b_{v,0}(x)
	\prod_{i=1,2}(b_{e,0})^i(\SSPIN{w})}{
	\displaystyle
	\sum_{x'\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2}
	b_{v,0}(x')
	\prod_{i=1,2}(b_{e,0})^i(\SSPIN{w})}
	\stackrel{\eqref{e:vv.lemma.initialization}}{=}
	\mu_v(x)
	\]
for any $x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$. Likewise we have
	\[
	\mu_0\Big(x_v=x\,\Big|\,\Sigma_e=\SPIN{v}\SSPIN{w}\Big)
	\stackrel{\eqref{e:ForcedRR.mu.of.beta}}{=}
	\frac{\Ind{x^1=\SPIN{+}} b_{v,0}(x)
		(b_{e,0})^1(\SPIN{v})(b_{e,0})^2(\SSPIN{w})}
	{\displaystyle\sum_{x'\in\set{\SPIN{+}}
		\times\set{\SPIN{-},\SPIN{+},\SPIN{f}}}
		b_{v,0}(x')
		(b_{e,0})^1(\SPIN{v})(b_{e,0})^2(\SSPIN{w})}
	\stackrel{\eqref{e:vv.lemma.initialization}}{=}
	\frac{\mu_v(x)}{(\mu_v)^1(\SPIN{+})}
	\Ind{x^1=\SPIN{+}}\,,
	\] 
and a similar expression holds for the case $\Sigma_e=\SSPIN{w}\SSPIN{r}$. Lastly, note that
$\mu_0(x_v=x\,\Big|\,\Sigma_e=\SPIN{v}\SPIN{v})
=\Ind{x=\SPIN{+}\SPIN{+}}$. Substituting these into \eqref{e:conditional.rep.on.eprime} gives 
	\begin{align*}
	\mu_{v,0}(x)
	&\stackrel{\eqref{e:conditional.rep.on.eprime}}{=}
	\mu_{e,0}(\SPIN{v}\SPIN{v})\Ind{x=\SPIN{+}\SPIN{+}}
	+ \mu_{e,0}(\SPIN{v}\SSPIN{w})\frac{\mu_v(x)}
		{(\mu_v)^1(\SPIN{+})}
		{\Ind{x^1=\SPIN{+}}}
	+ \mu_{e,0}(\SSPIN{w}\SPIN{v})\frac{\mu_v(x)}
		{(\mu_v)^2(\SPIN{+})}
		{\Ind{x^2=\SPIN{+}}}
	+\mu_{e,0}(\SSPIN{w}\SSPIN{w}) \mu_v(x)\\
	&\stackrel{\eqref{e:ForcedRR.init.pair.mgl.on.edge}}{=}
	\mu_v(x)
	\Bigg\{
	O\bigg(\frac{\Ind{x=\SPIN{+}\SPIN{+}}}{2^{k(1+\epsilon_4)}}\bigg)
	+O\bigg(\frac{\Ind{x^1=\SPIN{+}}
		+ \Ind{x^2=\SPIN{+}}}{2^k}\bigg)
	+1-O\bigg(\frac{k^2}{2^k}\bigg)
	\Bigg\}
	=\mu_v(x)\Bigg\{
	1-O\bigg(\frac{k^2}{2^k}\bigg)
	\Bigg\}\,.
	\end{align*}
To summarize the last few estimates, we have shown that at $t=0$ we have 
	\begin{equation}\label{e:ForcedRR.initial.marginals.off.edge}
	\begin{pmatrix}
	\displaystyle\bigg\|\frac{\mu_{v,0}}{\mu_v}-1\bigg\|_\infty
	+
	\sum_{i=1,2}
	\bigg|\frac{(\mu_{e,0})^i(\SSPIN{w})}
		{(\mu_e)^i(\SSPIN{w})}-1\bigg|
	+
	\sum_{e'\in\delta a\setminus v}
	\bigg\|\frac{\mu_{e',0}}{\mu_{e'}}-1\bigg\|_\infty
	\\
	\displaystyle\sum_{i=1,2} \bigg|\frac{(\mu_{e,0})^i(\SPIN{v})}
		{(\mu_e)^i(\SPIN{v})}-1\bigg|
		\end{pmatrix}
	\le k^{O(1)}
	 \begin{pmatrix}
		2^{-k}\\ 2^{-k\epsilon_4} \end{pmatrix}\,.
	\end{equation}
We now turn to the construction of the sequence $b_t\to b_\infty\equiv b$, where we recall that $b$ denotes the limiting weights in \eqref{e:ForcedRR.mu.of.beta} that give the solution to the constrained entropy maximization problem.\smallskip

\noindent\bemph{Step 3. Iterative construction and covariance estimates.} For each $t\ge0$, suppose we have the weights $b_t$, which define the measure $\mu_t$. We then define the weights at time $t+1$ by setting
	\begin{equation}\label{e:update.rule.on.central.edge}
	\frac{b_{v,t+1}(x)}{b_{v,t}(x)}
		=\frac{\mu_v(x)}{\mu_{v,t}(x)}\,,\quad
	\frac{b_{e',t+1}(\sigma)}{b_{e',t}(\sigma)}
		=\frac{\mu_{e'}(\sigma)}{\mu_{e',t}(\sigma)}
			\,,\quad
	\frac{(b_{e,t+1})^i(\Sigma^i)}{(b_{e,t})^i(\Sigma^i)}
		=\frac{\mu_e(\Sigma^i)}{\mu_{e,t}(\Sigma^i)}
	\end{equation}
for all $x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$,
 $e'\in\delta a\setminus e$,
 $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$, 
 $i=1,2$, and $\Sigma^i\in\set{\SSPIN{w},\SPIN{v}}$. We will show by induction that for all $t\ge0$ we have the bound
	\begin{equation}\label{e:tree.a.v.induct}
	\begin{pmatrix} \displaystyle
	\bigg\|
		\frac{\mu_{v,t}}{\mu_v}
		-1\bigg\|_\infty
	+\sum_{i=1,2}
	\bigg|\frac{(\mu_{e,t})^i(\SSPIN{w})}
		{(\mu_e)^i(\SSPIN{w})}-1\bigg|
	+\sum_{e'\in\delta a\setminus e}
	\bigg\| \frac{\mu_{e',t}}{\mu_{e'}}-1\bigg\|_\infty\\
	\displaystyle \sum_{i=1,2}
		\bigg|\frac{(\mu_{e,t})^i(\SPIN{v})}
		{(\mu_e)^i(\SPIN{v})}-1\bigg|
	\end{pmatrix}
	\le \frac{k^{O(1)}}{(2^{k\epsilon_4})^{t/2}}
	\begin{pmatrix}2^{-k}\\2^{-k\epsilon_4}
		\end{pmatrix}\,,
	\end{equation}
where the base case $t=0$ follows from \eqref{e:ForcedRR.initial.marginals.off.edge}.
Note that
\eqref{e:update.rule.on.central.edge} and \eqref{e:tree.a.v.induct}
together imply
	\begin{equation}\label{e:induct.consequence.on.sum.b}
	\begin{pmatrix}
	\displaystyle \Bigg\{
		\bigg\|\frac{b_{v,t+1}}{b_{v,t}}-1\bigg\|_\infty
		+\sum_{i=1,2}
		\bigg|\frac{(b_{e',t+1})^i(\SSPIN{w})}
			{(b_{e',t})^i(\SSPIN{w})}
			-1\bigg|
		+\sum_{e'\in\delta a\setminus e}
		\bigg\|\frac{b_{e',t+1}}{b_{e',t}}-1\bigg\|_\infty
		\Bigg\}\\
	\displaystyle\sum_{i=1,2}
		\bigg|\frac{(b_{e',t+1})^i(\SPIN{v})}
			{(b_{e',t})^i(\SPIN{v})}
			-1\bigg|
	\end{pmatrix}
	\le \frac{k^{O(1)}}{(2^{k\epsilon_4})^{t/2}}
	\begin{pmatrix}2^{-k}\\2^{-k\epsilon_4}
		\end{pmatrix}\,,
	\end{equation}
Towards the proof of \eqref{e:tree.a.v.induct},
we estimate covariances under the measure $\mu_t$. First, for all $x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$ we have 	\begin{align*}
	\frac{Z_t \mu_t(x_v=x,(\Sigma_e)^1=\SSPIN{w})}
		{\mu_v(x) (\mu_e)^1(\SSPIN{w})}
	&=\frac{b_{v,t}(x)
	(b_{e,t})^1(\SSPIN{w})}{\mu_v(x) (\mu_e)^1(\SSPIN{w})}
	\Bigg\{
	(b_{e,t})^2(\SSPIN{w})
	\prod_{e'\in\delta a\setminus e}
		b_{e',t}(\SSPIN{u}\SSPIN{u})
		\bigg(1-\frac{k^{O(1)}}{2^k}\bigg)\\
	&\qquad\qquad\qquad
		+\Ind{x^2=\SPIN{+}}(b_{e,t})^2(\SPIN{v})
		\prod_{e'}b_{e',t}(\SSPIN{u}\SSPIN{y})
		\bigg(1-\frac{O(1)}{2^{k\epsilon_4}}\bigg)
	\Bigg\}\\
	&=\frac{b_{v,t}(x)
	(b_{e,t})^1(\SSPIN{w})}{\mu_v(x) (\mu_e)^1(\SSPIN{w})}
	\Bigg\{1-\frac{k^{O(1)}}{2^k}\Bigg\}
	\stackrel{\eqref{e:induct.consequence.on.sum.b}}{=}
	1-\frac{k^{O(1)}}{2^k}\,.
	\end{align*}
In combination with \eqref{e:tree.a.v.induct}, this implies that for all $x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$ and $i=1,2$ we have
	\[\Bigg|
	\frac{\mathrm{Cov}_{\mu_t}(
		\Ind{x_v=x},
		\Ind{(\Sigma_e)^i=\SSPIN{w}})}
		{\mu_v(x) (\mu_e)^i(\SSPIN{w})}\Bigg|
	=\Bigg| \frac{\mu_t(x_v=x,(\Sigma_e)^1=\SSPIN{w})}
		{\mu_v(x) (\mu_e)^1(\SSPIN{w})}
		-\frac{\mu_{v,t}(x) (\mu_{e,t})^1(\SSPIN{w})}
		{\mu_v(x) (\mu_e)^1(\SSPIN{w})}
		\Bigg|
	\le \frac{k^{O(1)}}{2^k}\,.
	\]
Next, for $e'\in\delta a\setminus e$ and
$\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$, we calculate
	\begin{align*}
	\frac{Z_t \mu_t((\Sigma_e)^1=\SSPIN{w},
		\sigma_{e'}=\sigma)}
		{(\mu_e)^1(\SSPIN{w})\mu_{e'}(\sigma)}
	&=
	\frac{(b_{e,t})^1(\SSPIN{w})b_{e',t}(\sigma)}
		{(\mu_e)^1(\SSPIN{w})\mu_{e'}(\sigma)}
	\Bigg\{
	(b_{e,t})^2(\SSPIN{w})
	\prod_{e''\in\delta a\setminus\set{e,e'}}
	b_{e'',t}(\SSPIN{u}\SSPIN{u})
	\bigg(1-\frac{k^{O(1)}}{2^k}\bigg) \\
	&\qquad\qquad\qquad
	+\Ind{\sigma^2=\SSPIN{y}}
	(b_{e,t})^2(\SPIN{v})
	(b_{v,t})^2(\SPIN{+})
	\prod_{e''\in\delta a\setminus\set{e,e'}}
	b_{e'',t}(\SSPIN{u}\SSPIN{y})
	\bigg(1-\frac{O(1)}{2^{k\epsilon_4}}\bigg)
	\Bigg\}\\
	&=	\frac{(b_{e,t})^1(\SSPIN{w})b_{e',t}(\sigma)}
		{(\mu_e)^1(\SSPIN{w})\mu_{e'}(\sigma)}
	\Bigg\{1- \frac{k^{O(1)}}{2^k}\Bigg\}
	\stackrel{\eqref{e:induct.consequence.on.sum.b}}{=}
	1- \frac{k^{O(1)}}{2^k}\,.
	\end{align*}
This implies that for all $e'\in\delta a\setminus e$ and $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$, we have
	\[
	\frac{\mathrm{Cov}_{\mu_t}(
		\Ind{(\Sigma_e)^i=\SSPIN{w}},
		\Ind{\sigma_{e'}=\sigma})}
		{(\mu_e)^i(\SSPIN{w})
		\mu_{e'}(\sigma)
		 }
		\le\frac{k^{O(1)}}{2^k}\,.
	\]
Similar calculations for the case $(\Sigma_e)^i=\SPIN{v}$ give 
	\begin{align*}
	\frac{\mathrm{Cov}_{\mu_t}(\Ind{x_v=x},
		\Ind{(\Sigma_e)^i=\SPIN{v}})}
		{\mu_v(x)
		(\mu_e)^i(\SPIN{v})}
	&\le O(1)\,,\\
	\frac{\mathrm{Cov}_{\mu_t}(
		\Ind{(\Sigma_e)^i=\SPIN{v}},
		\Ind{\sigma_{e'}=\sigma})}
			{(\mu_e)^i(\SPIN{v})
		\mu_{e'}(\sigma)}
	&\le O(1)\,,
	\end{align*}
for all $x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$,
 $e'\in\delta a\setminus e$, and $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$. Next, on the edge $e=(av)$, we have
 	\[
	\frac{Z_t\mu_{e,t}(\SSPIN{w}\SSPIN{w})}
		{(\mu_e)^1(\SSPIN{w})(\mu_e)^2(\SSPIN{w})}
	= \frac{(b_{e,t})^1(\SSPIN{w})(b_{e,t})^2(\SSPIN{w})}
		{(\mu_e)^1(\SSPIN{w})(\mu_e)^2(\SSPIN{w})}
	\prod_{e'\in\delta a\setminus e}
		b_{e',t}(\SSPIN{u}\SSPIN{u})
	\Bigg\{1-\frac{k^{O(1)}}{2^k}\Bigg\}
	\stackrel{\eqref{e:induct.consequence.on.sum.b}}{=}
	1- \frac{k^{O(1)}}{2^k}\,.
	\]
Next, using the diversity bound
\eqref{e:diverse.clause.consequence}, we also have
	\begin{align*}
	\frac{Z_t\mu_{e,t}(\SPIN{v}\SSPIN{w})}
		{(\mu_e)^1(\SPIN{v})(\mu_e)^2(\SSPIN{w})}
	&\stackrel{\eqref{e:diverse.clause.consequence}}{=} 
	\frac{(b_{e,t})^1(\SPIN{v})(b_{e,t})^2(\SSPIN{w})}
		{(\mu_e)^1(\SPIN{v})(\mu_e)^2(\SSPIN{w})}
	(b_{v,t})^1(\SPIN{+}) 
	\prod_{e'\in\delta a\setminus e}
		b_{e',t}(\SSPIN{y}\SSPIN{u})
	\Bigg\{1-\frac{O(1)}{2^{k\epsilon_4}}\Bigg\} \\
	&
	\stackrel{\eqref{e:induct.consequence.on.sum.b}}{=}
	\Bigg\{1-\frac{O(1)}{2^{k\epsilon_4}}\Bigg\}
	2^K (b_{v,t})^1(\SPIN{+}) 
	\prod_{e'\in\delta a\setminus e}
		b_{e',t}(\SSPIN{y}\SSPIN{u})
	\stackrel{\eqref{e:induct.consequence.on.sum.b}}{=}
	1-\frac{O(1)}{2^{k\epsilon_4}}\,,\\
	\frac{Z_t\mu_{e,t}(\SPIN{v}\SPIN{v})}
		{(\mu_e)^1(\SPIN{v})(\mu_e)^2(\SPIN{v})}
	&= \frac{(b_{e,t})^1(\SPIN{v})(b_{e,t})^2(\SPIN{v})}
		{(\mu_e)^1(\SPIN{v})(\mu_e)^2(\SPIN{v})}
	\mu_v(\SPIN{+}\SPIN{+})
	\prod_{e'\in\delta v\setminus e}
	b_{e',t}(\SSPIN{y}\SSPIN{y})\\
	&\stackrel{\eqref{e:induct.consequence.on.sum.b}}{=} 2^K \cdot 2^K\cdot
	\mu_v(\SPIN{+}\SPIN{+})
	\prod_{e'\in\delta v\setminus e}
	b_{e',t}(\SSPIN{y}\SSPIN{y})
	\stackrel{\eqref{e:diverse.clause.consequence}}{\le }
	O\bigg( \frac{2^k}{2^{k\epsilon_4}}\bigg)
	\,.\end{align*}
The last few estimates combined imply
	\[
	\frac{\mathrm{Cov}_{\mu_t}(\Ind{(\Sigma_e)^1=\Sigma^1},
	\Ind{(\Sigma_e)^2=\Sigma^2})}
		{(\mu_e)^1(\Sigma^1)
		(\mu_e)^2(\Sigma^2)}
	\le k^{O(1)} \begin{cases}
	2^{-k}&\textup{if $\Sigma=\SSPIN{w}\SSPIN{w}$,}\\
	2^{-k\epsilon_4}&\textup{if $\Sigma\in\set{\SPIN{v}\SSPIN{w},
		\SSPIN{w}\SPIN{v}}$,}\\
	2^{k(1-\epsilon_4)}
	&\textup{if $\Sigma=\SPIN{v}\SPIN{v}$.}
	\end{cases}
	\]
Lastly, it is straightforward to verify (details omitted) that
	\[\frac{\mathrm{Cov}_{\mu_t}(
		\Ind{x_v=x},
		\Ind{\sigma_{e'}=\sigma})}
			{ \mu_v(x) \mu_{e'}(\sigma)}
	\le \frac{k^{O(1)}}{2^k}
	\]
for all 
 $x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$,
$e'\in\delta a \setminus e$, and $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$.\smallskip

\noindent\bemph{Step 4. Estimates on Lagrangian weights.}
Now recall from 
\eqref{e:derivative.is.covariance}
that derivatives of $\mu_t$-marginals with respect to $b_t$ can be expressed as covariance. Let $\tilde{\mu}_{t+1}$ be defined by
	\[
	\tilde{\mu}_{t+1}
	\Big(x_v,\Sigma_e,\smash{\vec{\sigma}}_{\delta a\setminus e}\Big)	
	=
	\frac1{\tilde{Z}_{t+1}}
	b_{v,t}(x)
	(b_{e,t+1})^1((\Sigma_e)^1)
	(b_{e,t})^2((\Sigma_e)^2)
	\prod_{e'\in\delta a\setminus e}
		b_{e',t}(\sigma_{e'})\,,
	\]
where $\tilde{Z}_{t+1}$ is the normalizing constant. It follows from the update rule \eqref{e:update.rule.on.central.edge} that
the marginal of $\tilde{\mu}_{t+1}$ on $(\Sigma_e)^1$
is exactly the desired marginal $(\mu_e)^1$. Consequently,
	\begin{align*}
	\delta_{t+1}(\Sigma^1) &\equiv \bigg|
	\frac{(\mu_{e,t+1})^1(\Sigma^1)}{(\mu_e)^1(\Sigma^1)}-1
	\bigg|
	=\bigg|
	\frac{(\mu_{e,t+1})^1(\Sigma^1)}
		{(\tilde{\mu}_{e,t+1})^1(\Sigma^1)}-1\bigg|
	\\
	&\le
	\frac1{(\mu_e)^1(\Sigma^1)}
	O\Bigg(
	\sum_x
	\frac{\partial\mu_{e,t+1}(\Sigma^1)}
		{\partial\ln b_{v,t+1}(x)}
	\bigg| \frac{b_{v,t+1}(x)}{b_{v,t}(x)}-1\bigg|
	+\sum_{\Sigma^2}
	\frac{\partial\mu_{e,t+1}(\Sigma^1)}
		{\partial\ln (b_{e,t+1})^2(\Sigma^2)}
	\bigg| \frac{(b_{e,t+1})^2(\Sigma^2)}
		{(b_{e,t})^2(\Sigma^2)}
	-1\bigg|
	\\
	&\qquad\qquad\qquad\qquad\qquad\qquad\qquad
	+\sum_{e',\sigma}
	\frac{\partial\mu_{e,t+1}(\Sigma^1)}
		{\partial\ln b_{e',t+1}(\sigma)}
		\bigg|
		\frac{b_{e',t+1}(\sigma)}
			{b_{e',t}(\sigma)}-1\bigg|
	\Bigg)\,.
	\end{align*}
Substituting the preceding covariance estimates into the last bound and applying \eqref{e:induct.consequence.on.sum.b} gives
	\begin{align*}
	\delta_{t+1}(\SSPIN{w})
	&\le
	k^{O(1)}\Bigg\{
	\frac1{2^k}
	\cdot
	\frac{1}{2^k(2^{k\epsilon_4/2})^t}
	+	\frac1{2^{k\epsilon_4}} \cdot
	(\mu_e)^2(\SPIN{v})
	\cdot
	\bigg|\frac{(b_{e,t+1})^2(\SPIN{v})}
		{(b_{e,t})^2(\SPIN{v})}-1 \bigg|
	\Bigg\}\\
	&\le k^{O(1)}\Bigg\{
	\frac1{2^k}
	\cdot
	\frac{1}{2^k(2^{k\epsilon_4/2})^t}
	+	\frac1{2^{k\epsilon_4}}
	\cdot \frac1{2^k}
	\cdot \frac1{2^{k\epsilon_4}((2^{k\epsilon_4/2})^t}
	\Bigg\}
	\le \frac{k^{O(1)}}{2^k(2^{k\epsilon_4/2})^{t+2}}\,,\\
	\delta_{t+1}(\SPIN{v})
	&\le
	k^{O(1)}\Bigg\{
	\frac1{2^{k\epsilon_4}((2^{k\epsilon_4/2})^t}
	+ 2^{k(1-\epsilon_4)}
	\cdot(\mu_e)^2(\SPIN{v})
	\cdot \frac1{2^{k\epsilon_4}((2^{k\epsilon_4/2})^t}
	\Bigg\}
	\le 
	\frac{k^{O(1)}}{2^{k\epsilon_4}(2^{k\epsilon_4/2})^{t+2}}\,.
	\end{align*}
This verifies the inductive hypothesis \eqref{e:tree.a.v.induct} for the quantities
	\[
	\delta_{t+1}(\Sigma^i)
	= \bigg|\frac{(\mu_{e,t+1})^i(\Sigma^i)}
		{(\mu_e)^i(\Sigma^i)}-1\bigg|\,.
	\]
The remaining estimates in \eqref{e:tree.a.v.induct} follow by similar calculations (details omitted). It follows that as $t\to\infty$ the weights $b_t$ converge to the desired limiting weights $b_\infty\equiv b$ that define the optimal measure $\mu$ in \eqref{e:ForcedRR.mu.of.beta}. It then follows from the bound \eqref{e:induct.consequence.on.sum.b} that
	\begin{align*}
	\mu_e(\SPIN{v}\SPIN{v})
	&\stackrel{\eqref{e:ForcedRR.mu.of.beta}}{=}
	O\Bigg(
	b_v(\SPIN{+}\SPIN{+})
	\Bigg\{\prod_{i=1,2} (b_e)^i(\SPIN{v})\Bigg\}
	\Bigg\{ \prod_{e'\in\delta a\setminus e}
		b_{e'}(\SSPIN{y}\SSPIN{y})\Bigg\}
		\Bigg)\\
	&\stackrel{\eqref{e:induct.consequence.on.sum.b}}{=}
	O\Bigg(
	\mu_v(\SPIN{+}\SPIN{+})
	\prod_{i=1,2}\Big(
	(\mu_e)^i(\SPIN{v}) 2^K\Big)
	\prod_{e'\in\delta a\setminus e}
		\mu_{e'}(\SSPIN{y}\SSPIN{y})\Bigg)
	\stackrel{\eqref{e:diverse.clause.consequence}}{\le}
	\frac1{2^{k(1+\epsilon_4)}}\,,
	\end{align*}
as claimed.

\begin{equation}\label{e:mu.two.sided.tree}
	\mu\Big(\Sigma_e,\smash{\vec{\sigma}}_{(\delta v\cup\delta a)\setminus e}\Big)
