\label{l:large11Case}
Suppose $v$ is a non-defective variable of type $\bm{T}$, satisfying the bounds $\pi_v(\SPIN{+}\SPIN{+})
	=\pi_{\bm{T}}(\SPIN{+}\SPIN{+})\ge 2^{-k/16}$ and
	\begin{equation}\label{e:notDiverse.small}
	\cancel{\mathbb{D}}(v)
	\stackrel{\eqref{e:exp.num.nondiv.nbr.clauses}}{=}
	\sum_{\bm{t}\in\bm{T}}\sum_{\bm{L}}
	\Ind{\bm{L}\notin\mathbb{D}}
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t})
	\le 2^k\,.
	\end{equation}
Then, for every edge $e\in\delta v(\SPIN{+})$, we have (with $\epsilon_4$ as in Lemma~\ref{l:ForcedRR}) the bound
	\[
	\max_{\bm{L},j}
	\bigg\{\omega_{\bm{L},j}(\SSPIN{r}\SSPIN{r})
	: 
	\textup{$\bm{L}\in\mathbb{D}$
	with $\bm{L}(j)=\bm{t}_e$}
	\bigg\}
	\le \frac1{2^{k(1+\epsilon_4)}}\,.
	\]
The same statement holds if we replace $\SPIN{+}$ with $\SPIN{-}$ throughout.


\begin{proof} We claim that
	\begin{equation}\label{enotEnoughReds}
	\min\Bigg\{
	\sum_{ e \in\delta v(\SPIN{+})} 
		\pi_e\Big( \set{\SSPIN{r}\SSPIN{r},\SSPIN{r}\SSPIN{b}}\Big),
	\sum_{ e \in\delta v(\SPIN{+})} 
		\pi_e\Big( \set{\SSPIN{r}\SSPIN{r},\SSPIN{b}\SSPIN{r}}\Big)
	\Bigg\}
	\ge \frac{k \pi_v(\SPIN{+}\SPIN{+})}{300}\,.
	\end{equation}
Let us first note that
\eqref{enotEnoughReds} implies the result of the lemma: indeed, if \eqref{enotEnoughReds} holds,
then condition
\eqref{e:assumption.rr.avg} of Lemma~\ref{l:rrUnforced} is satisfied with $\epsilon_2=1/300$, and applying that lemma gives
	\[
	\omega_{\bm{L},j}(\SSPIN{r}\SSPIN{r})
	\le \frac{\bm{\varpi}_{\bm{L},j}(\upsilon=\SPIN{v}\SPIN{v})}
		{1- 2^{-k\epsilon_3}}
	\le O\Big( \bm{\varpi}_{\bm{L},j}
		(\upsilon=\SPIN{v}\SPIN{v})\Big)
	\]
for $j=j(\bm{t})$ and all $\bm{L}$ such that $\bm{L}(j)=\bm{t}$.
If in addition $\bm{L}\in\mathbb{D}$, then
combining with Lemma~\ref{l:ForcedRR} gives
	\[
	\omega_{\bm{L},j}(\SSPIN{r}\SSPIN{r})
	\le O\Big( \bm{\varpi}_{\bm{L},j}
		(\upsilon=\SPIN{v}\SPIN{v})\Big)
	\le O\bigg( \frac1{2^{k(1+\epsilon_4)}}\bigg)\,.
	\]
Thus it suffices to prove \eqref{enotEnoughReds}.\smallskip


\noindent\bemph{Step 1. Preliminary bounds.}
 For $e\in\delta v(\SPIN{+})$ we have $\pi_e(\SSPIN{b}\SSPIN{b})= \pi_v(\SPIN{+}\SPIN{+})-O(2^{-k})\ge 2^{-k/15}$, so Lemma~\ref{l:indifferent} gives
	\[
	\omega_{\bm{L},j}(\SSPIN{b}\SSPIN{b})
	\ge \frac{\pi_e(\SSPIN{b}\SSPIN{b})}8
	\ge \frac18
	\Bigg\{ \pi_v(\SPIN{+}\SPIN{+})
		-O\bigg(\frac1{2^k}\bigg)
		\Bigg\}
	\]
for all $\bm{L},j$ with $\bm{L}(j)=\bm{t}_e$. Combining with
Lemma~\ref{l:lotsOfAs} gives
	\begin{equation}\label{e:large11Case.many.bb.ww}
	\bm{\varpi}_{\bm{L},j}
		\Bigg(
		\hspace{-3pt}\begin{array}{c}\sigma=\SSPIN{b}\SSPIN{b},\\
		\Sigma=\SSPIN{w}\SSPIN{w}\end{array}\hspace{-3pt}
		\Bigg)
	\ge \omega_{\bm{L},j}(\SSPIN{b}\SSPIN{b})
		-O\bigg(\frac{k^2}{2^k}\bigg)
	\ge 
	\omega_{\bm{L},j}(\SSPIN{b}\SSPIN{b})
	\Big\{ 1-o_k(1)\Big\}
	\,.\end{equation}
Suppose for contradiction that \eqref{enotEnoughReds} fails. Since $v$ is non-defective, it must also be nice (Definition~\ref{d:nice}), so
	\[
	\sum_{e\in\delta v(\SPIN{+})}
	\pi_e\Big(\set{\SSPIN{r}\SSPIN{y},\SSPIN{r}\SSPIN{g}}\Big)
	\ge \sum_{e\in\delta v(\SPIN{+})}
	(\pi_e)^1(\SSPIN{r}) - 
		\frac{k \pi_v(\SPIN{+}\SPIN{+})}{300}
	\ge \frac{k 2^{k-1} \ln 2}{2^k}
		\Big\{1-o_k(1)\Big\}
	- \frac{ k \pi_v(\SPIN{+}\SPIN{+})}{300}
	\ge \frac{k}{3}\,.
	\]
Therefore, it holds for some
$\tau\in\set{\SSPIN{y},\SSPIN{g}}$ that 
	\begin{equation}\label{e:too.many.ry}
	\sum_{e\in\delta v(\SPIN{+})}
	\pi_e(\SSPIN{r}\tau) \ge \frac{k}{6}
	\end{equation}
--- suppose this is the case for $\tau=\SSPIN{y}$. 
Then Lemma~\ref{l:ryUnforced} 
(whose condition 
\eqref{e:ryUnforced.condition} 
is satisfied, due to
\eqref{e:too.many.ry}) gives
	\[\bm{\varpi}_{\bm{L},j}
	\Bigg(\hspace{-3pt}
		\begin{array}{c}\sigma=\SSPIN{r}\SSPIN{y},\\
		\upsilon^1=\SPIN{v}\end{array}\hspace{-3pt}
		\Bigg) 
	\ge \omega_{\bm{L},j}(\SSPIN{r}\SSPIN{y})
	\bigg\{ 1-\frac1{2^{k\epsilon_3}}\bigg\}
	\]
for all $e\in\delta v(\SPIN{+})$
and all $\bm{L}(j)=\bm{t}_e$. If $\bm{L}$ is also diverse, then combining with Lemma~\ref{l:lotsOfAsDiverse} gives 
	\begin{equation}\label{e:lbd.movable.red.white}
	\bm{\varpi}_{\bm{L},j}
		\Bigg(
		\hspace{-3pt}
		\begin{array}{c}\sigma=\SSPIN{r}\SSPIN{y},\\
		\Sigma=\SPIN{v}\SSPIN{w}
		\end{array}\hspace{-3pt}
		\Bigg) 
	\ge \bm{\varpi}_{\bm{L},j}\Bigg(\hspace{-3pt}
		\begin{array}{c}\sigma=\SSPIN{r}\SSPIN{y},\\
		\upsilon^1=\SPIN{v}\end{array}\hspace{-3pt}
		\Bigg) 
	-\bm{\varpi}_{\bm{L},j}\Bigg(
		\hspace{-3pt}
		\begin{array}{c}
		\sigma=\SSPIN{r}\SSPIN{y},\\
		\varsigma^1\ne\SSPIN{w},
		\varsigma^2\ne\SSPIN{w}
		\end{array}\hspace{-3pt}
		\Bigg)
	\ge \bm{\varpi}_{\bm{L},j}(\SSPIN{r}\SSPIN{y})
		\bigg\{ 1-\frac1{2^{k\epsilon_3}}\bigg\}
		-\frac1{2^{k(1+\epsilon_1)}}\,.\end{equation}
Note that \eqref{e:lbd.movable.red.white} used the assumption that $v$ is non-defective, which implies that $\bm{L}$ is nice (i.e., neighbors only nice variables) whenever $\bm{L}(j)=\bm{t}_e$ for $e\in\delta v$. We now define a probability measure $\bm{\pi}$ on the space of pairs $(e,\bm{L})$, where $e\in\delta v(\SPIN{+})$ and $\bm{t}_e\in\bm{L}$, such that
	\begin{equation}\label{e:defn.bm.pi}
	\bm{\pi}(e,\bm{L})
	\equiv
	\frac{\Ind{e\in\delta v(\SPIN{+})}}
		{|\delta v(\SPIN{+})|}
		\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)\,.
	\end{equation}
We can equivalently regard $\bm{\pi}$ as a probability measure on pairs $(\bm{t},\bm{L})$ where $\bm{t}=\bm{t}_e$. Now, on this probability space, define the random variable
	\[X\equiv X(e,\bm{L})
	\equiv 
	\Ind{\bm{L}\in\mathbb{D}}
	\frac{\omega_{\bm{L},j}(\SSPIN{r}\SSPIN{y})}
	{{}_\star\hspace{-1pt}\pi_e(\SSPIN{r})}
	\equiv X(\bm{t},\bm{L})\,,\]
and note that $0\le X\le 1$ with probability one.
The expectation of $X$ with respect to $\bm{\pi}$ is
	\begin{align*}
	\mathbf{E}_{\bm{\pi}} X
	&\stackrel{\eqref{e:defn.bm.pi}}{=}
		\frac1{|\delta v(\SPIN{+})|}
	\Bigg\{ \sum_{e\in\delta v(\SPIN{+})}
	\sum_{\bm{L}}
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
	\frac{\omega_{\bm{L},j}(\SSPIN{r}\SSPIN{y})}
	{{}_\star\hspace{-1pt}\pi_e(\SSPIN{r})}
	-O\Bigg(
	\sum_{e\in\delta v(\SPIN{+})}
	\sum_{\bm{L}}\Ind{\bm{L}\notin\mathbb{D}}
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)\Bigg)
	\Bigg\}\\
	&\stackrel{\eqref{e:notDiverse.small}}{\ge}
	\frac1{|\delta v(\SPIN{+})|} \sum_{e\in\delta v(\SPIN{+})}
	\sum_{\bm{L}}
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
	\frac{\omega_{\bm{L},j}(\SSPIN{r}\SSPIN{y})}{{}_\star\hspace{-1pt}\pi_e(\SSPIN{r})}
	- \frac1k
	=\frac1{|\delta v(\SPIN{+})|} \sum_{e\in\delta v(\SPIN{+})}
	\frac{\pi_e(\SSPIN{r}\SSPIN{y})}{{}_\star\hspace{-1pt}\pi_e(\SSPIN{r})}
	- \frac1k\\
	&\stackrel{\eqref{e:too.many.ry}}{\ge} 
	\Big\{ 1-o_k(1)\Big\}
	\frac{2^{k-1} \cdot k/6}{k 2^{k-1}\ln2}
	\ge \frac15\,.
	\end{align*}
On the other hand, since we noted above that $0\le X\le 1$, we have
	\[
	\mathbf{E}_{\bm{\pi}} X
	\le \bm{\pi}\bigg(X \ge \frac1{10}\bigg)
	+ \frac1{10}
	\Bigg\{1-\bm{\pi}\bigg(X \ge \frac1{10}\bigg)\Bigg\}\,,
	\]
and rearranging gives
$\bm{\pi}(X \ge 1/10)\ge 1/9$. On the event $X(e,\bm{L})\ge1/10$, it follows from \eqref{e:lbd.movable.red.white} that
	\begin{equation}\label{e:large11Case.many.ry.moveable}
	\bm{\varpi}_{\bm{L},j}
	\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma=\SSPIN{r}\SSPIN{y},\\
		\Sigma=\SPIN{v}\SSPIN{w}\end{array}\hspace{-3pt}
		\Bigg)
	\ge \omega_{\bm{L},j}(\SSPIN{r}\SSPIN{y})
	\Big\{1-o_k(1)\Big\}\,.\end{equation}
In the next step we will perform a switching argument between \eqref{e:large11Case.many.bb.ww}
and \eqref{e:large11Case.many.ry.moveable}.\smallskip


\noindent\bemph{Step 2. Edge switching argument.} Let $\mathscr{G}=(V,F,E)$ be any (processed) $\textup{$k$-\textsc{sat}}$ graph. Fix a clause type $\bm{L}$ and index $1\le j\le k(\bm{L})$, and let $E(\bm{L},j)$ denote the subset of all edges
$e=(av)\in E$ such that $\bm{L}_a=\bm{L}$ and $j(\bm{t}_e)=j$. Suppose $\smash{\vec{\sigma}}$ is a valid pair coloring on $\mathscr{G}$, and let $\smash{\vec{\Sigma}}$ be the corresponding configuration from Definition~\ref{d:white.violet}. Suppose we have two edges $e=(av)$ and $e'=(a'v')$ in $E(\bm{L},j)$, such that
	\[
	\mathbf{X}_{av} \equiv
	\begin{pmatrix} \sigma_{av}\\
		\Sigma_{av}\end{pmatrix}
	= \begin{pmatrix} \SSPIN{b}\SSPIN{b} \\
		\SSPIN{w}\SSPIN{w}\end{pmatrix}
	\equiv A_1\,,\quad
	\mathbf{X}_{a'v'}
	\equiv\begin{pmatrix} \sigma_{a'v'}\\
		\Sigma_{a'v'}\end{pmatrix}
	= \begin{pmatrix} \SSPIN{r}\SSPIN{y} \\
		\SPIN{v}\SSPIN{w}\end{pmatrix}
	\equiv A_2\,.
	\]
If we cut the edges $e,e'$ and form new edges 
$(a'v)$, $(av')$, then a valid configuration
$(\smash{\vec{\sigma}}',\smash{\vec{\Sigma}}')$ on the switched graph $\mathscr{G}'$ is given by setting
	\[\mathbf{X}_{a'v}
	\equiv\begin{pmatrix} \sigma_{a'v}\\
		\Sigma_{a'v}\end{pmatrix}
	= \begin{pmatrix}
		\SSPIN{r}\SSPIN{b}\\ \SPIN{v}\SSPIN{w}\end{pmatrix}
