keeping all other colors unchanged. Moreover, the switching preserves all single-copy marginals, 
so $\smash{\vec{\sigma}}'$ is a judicious configuration on $\mathscr{G}'$.
If $X(\bm{t},\bm{L})\ge1/10$ for $\bm{t}=\bm{L}(j)$, then
	\begin{align*}
	p(A_1)
	&\equiv
	\frac{|\set{e \in E(\bm{L},j) : \mathbf{X}_{av}=A_1}|}
		{|E(\bm{L},j)|}
	\stackrel{\eqref{e:large11Case.many.bb.ww}}
	{\ge} \bigg\{1-o_k(1)\bigg\}
	\omega_{\bm{L},j}(\SSPIN{b}\SSPIN{b})\,,\\
	p(A_2)
	&\equiv
	\frac{|\set{e \in E(\bm{L},j) : \mathbf{X}_{av}=A_2}|}
		{|E(\bm{L},j)|}
	\stackrel{\eqref{e:large11Case.many.ry.moveable}}{\ge}\bigg\{1-o_k(1)\bigg\}
	\omega_{\bm{L},j}(\SSPIN{r}\SSPIN{y})\,.\end{align*}
Suppose $\bm{\varpi}$ (the empirical measure on the augmented spins $(\sigma,\Sigma)$) gives the maximal 
second moment contribution $\mathbb{E}_{\mathscr{D}}\bm{Z}^2(\bm{\varpi})$, 
subject to the restriction that its projection $\omega$ lies in $I_0$. Let $\bm{\Omega}$ denote the space of all (valid) pairs $(\mathscr{G},\smash{\vec{\sigma}})$ that are 
consistent with this $\bm{\varpi}$, and consider the probability measure
	\[
	\mathbf{P}(\mathscr{G},\smash{\vec{\sigma}})
	= \frac{\mathbb{P}_{\mathscr{D}}(\mathscr{G}) \Ind{(\mathscr{G},\smash{\vec{\sigma}})\in\bm{\Omega}}}
		{\mathbb{E}_{\mathscr{D}} \bm{Z}^2(\bm{\varpi})}\,.
	\]
Let $(\mathscr{G},\smash{\vec{\sigma}})\in\bm{\Omega}$ be sampled according to measure $\mathbf{P}$, and define the subsets of edges
	\begin{align*}
	E_A&\equiv E_A(\mathscr{G},\smash{\vec{\sigma}})
	\equiv
	\bigg\{e\in E(\bm{L},j): \bm{X}_e \in\set{A_1,A_2}\bigg\}\,,\\
	E_B&\equiv E_B(\mathscr{G},\smash{\vec{\sigma}})
	\equiv
	\bigg\{e\in E(\bm{L},j): \bm{X}_e \in\set{B_1,B_2}\bigg\}\,.
