	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e) 
	\omega_{\bm{L},j}(\SSPIN{r}\SSPIN{b})\\
	&= |\delta v(\SPIN{+})|
	\bm{\pi}\bigg(X \ge \frac1{10}\bigg) 
	\frac{\pi_v(\SPIN{+}\SPIN{+})
	{}_\star\hspace{-1pt}\pi_e(\SSPIN{r})}{11}
	\ge \frac{k2^{k-1}\ln2}{9[1-o_k(1)]}
	\frac{\pi_v(\SPIN{+}\SPIN{+})}{11 \cdot 2^k}
	\ge \frac{k \pi_v(\SPIN{+}\SPIN{+})}{300}\,,
