		&= {}_\star\hspace{-1pt}\pi_e(\sigma^i)
		\quad&&\textup{for all $\bm{L}$
			and all $\sigma^i\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$,}\\
	\label{e:final.D.L.varsigma}
	\mathbf{P}(\varsigma_e=\varsigma\,|\,\bm{L}_e=\bm{L})
		&= \bm{\zeta}_e(\varsigma\,|\,\bm{L})
		\quad&&\textup{for all $\bm{L}$
		and all $\varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2$,}

	\end{alignat}

\begin{align*}
	{}_\star\hspace{-1pt}\zeta_e(\SSPIN{r})
	&\cong {}_\star\hspace{-1pt}\dot{q}_e(\SSPIN{r})
		\Bigg\{
		\prod_{e'\in\delta v\setminus e}
		{}_\star\hspace{-1pt}\dot{q}_{e'}(\SSPIN{y})
		\Bigg\}\,,\\
	{}_\star\hspace{-1pt}\zeta_e(\SSPIN{y})
	&\cong 
	\dot{q}_e(\SSPIN{y})
	\Bigg\{
	\sum_{e'\in\delta v\setminus e}
		\dot{q}_{e'}(\SSPIN{r})
	\prod_{e''\in\delta v\setminus \set{e,e'}}
	\dot{q}_{e''}(\SSPIN{y})\Bigg\}\,,\\
	{}_\star\hspace{-1pt}\zeta_e(\SSPIN{c})
	&\cong 
	\dot{q}_e(\SSPIN{c})
	\Bigg\{
	\sum_{e'\in\delta v\setminus e}
		\dot{q}_{e'}(\SSPIN{c})
		\prod_{e''\in\delta v\setminus \set{e,e'}}
		\dot{q}_{e''}(\SSPIN{y})\Bigg\}\,,\\
	{}_\star\hspace{-1pt}\zeta_e(\SSPIN{w})
	&\cong {}_\star\hspace{-1pt}\dot{q}_e(\set{\SSPIN{y},\SSPIN{c}})
	\prod_{e'\in\delta v\setminus e}
	{}_\star\hspace{-1pt}\dot{q}_{e'}(\set{\SSPIN{y},\SSPIN{c}})
	\Bigg( 1-\frac{k^{O(1)}}{2^k}\Bigg)\,,
	\end{align*}

\begin{align}\label{e:ZETA.bstar}
	\begin{pmatrix}
	{}_\star b(\SSPIN{r})\\
	{}_\star b(\SSPIN{y})\\
	{}_\star b(\SSPIN{g})={}_\star b(\SSPIN{b})
	\equiv{}_\star b(\SSPIN{c})
	\end{pmatrix}
	&= 
	\begin{pmatrix}
	1\\
	[{}_\star\hspace{-1pt}\pi(\SSPIN{y})-{}_\star\hspace{-1pt}\zeta(\SSPIN{y})]/{}_\star\hspace{-1pt}\dot{q}(\SSPIN{y})\\
	[{}_\star\hspace{-1pt}\pi(\SSPIN{c})-{}_\star\hspace{-1pt}\zeta(\SSPIN{c})]/{}_\star\hspace{-1pt}\dot{q}(\SSPIN{c})
	\end{pmatrix}
	\stackrel{\eqref{e:ZETA.zetastar}}{=} 
	\begin{pmatrix}
	\Theta(1)\\ \Theta(1) \\ \Theta(1)
	\end{pmatrix}\,,\\
	\label{e:ZETA.xstar}
	\begin{pmatrix}
	{}_\star x(\SSPIN{r})\\
	{}_\star x(\SSPIN{y})\\
	{}_\star x(\SSPIN{c})\\
	{}_\star x(\SSPIN{w})
	\end{pmatrix}
	&=\begin{pmatrix}
	{}_\star\hspace{-1pt}\pi(\SSPIN{r})/{}_\star\hspace{-1pt}\dot{q}(\SSPIN{r})\\
	{}_\star\hspace{-1pt}\zeta(\SSPIN{y})/[{}_\star\hspace{-1pt}\pi(\SSPIN{y})-{}_\star\hspace{-1pt}\zeta(\SSPIN{y})]\\
	{}_\star\hspace{-1pt}\zeta(\SSPIN{c})/[{}_\star\hspace{-1pt}\pi(\SSPIN{c})-{}_\star\hspace{-1pt}\zeta(\SSPIN{c})]\\
	1
	\end{pmatrix}
	\stackrel{\eqref{e:ZETA.zetastar}}{=} 
	\begin{pmatrix}
	\Theta(1/2^k)\\
	\Theta(k/2^k)\\
	\Theta(k/2^k)\\ 1
	\end{pmatrix}
	\,.\end{align}

\label{l:single.edge.sigma.varsigma} In this lemma we take $\sigma$ in the reduced alphabet $\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$. We continue to take $\varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2$. We write $\sigma\sim\varsigma$ to indicate compatibility: if $\sigma^i=\SSPIN{r}$ then $\varsigma^i=\SSPIN{r}$; if $\sigma^i\in\set{\SSPIN{y},\SSPIN{c}}$ then $\varsigma^i\in\set{\sigma^i,\SSPIN{w}}$. On edge $e$ let $\mu_0$ be a probability measure on pairs $(\sigma,\varsigma)$ with $\sigma\sim\varsigma$, of the form
	\[
	\mu_0(\sigma,\varsigma)
	=\frac{\Ind{\sigma\sim\varsigma}}{z_0}
	\dot{q}(\sigma) 
	(b_0)^1(\sigma^1)(b_0)^2(\sigma^2)
	x_0(\varsigma)\,,
	\]
such that $\mu(\sigma^i=\tau)={}_\star\hspace{-1pt}\pi_e(\tau)$ for both $i=1,2$ and all $\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}$. Assume that ${}_\star\hspace{-1pt}\pi_e$ is nice in the sense of Definition~\ref{d:nice}, that $\dot{q}(\sigma)=\Theta(1)$ for all $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$, and that
$b^i(\tau)=\Theta(1)$ for $i=1,2$ and all $\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}$. Let $\zeta_0$ denote the marginal law of $\varsigma$ under $\mu_0$. Let $\zeta$ be another probability measure over $\varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2$ whose single-copy marginals satisfy
$\zeta^1(\SSPIN{r})={}_\star\hspace{-1pt}\pi_e(\SSPIN{r})=\zeta^2(\SSPIN{r})$.
Assume that 
	\begin{align}\label{e:ZETA.assume.ww}
	\max\bigg\{ 1-\zeta_0(\SSPIN{w}\SSPIN{w}),
	1-\zeta(\SSPIN{w}\SSPIN{w})\bigg\}
	&\le \frac{k^{O(1)}}{2^k}\,,\\
	\hat{\iota} \equiv
	\frac{k^4}{4^k} + \max\bigg\{
	\zeta_0(\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2),
	\zeta(\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2)
	\bigg\}
	&\le \frac1{2^{k(1+\epsilon)}}\,.
	\label{e:ZETA.assume.iota}
	\end{align}
Assume moreover that we have parameters
$\delta \le O(1)$ and $\ddot{\delta}\le 2^{k(1-\epsilon)}$ such that
	\begin{align}
	\label{e:ZETA.delta.error}
	\max
	\Bigg\{
	\Big|\zeta(\varsigma)-\zeta_0(\varsigma)\Big|
	: \varsigma\in\set{
	\SSPIN{r}\SSPIN{w},\SSPIN{y}\SSPIN{w},\SSPIN{c}\SSPIN{w},
	\SSPIN{w}\SSPIN{r},\SSPIN{w}\SSPIN{y},\SSPIN{w}\SSPIN{c}}
	\Bigg\}
	&\le \frac{k^{O(1)}\delta}{2^k}\,,\\
	\label{e:ZETA.delta.error.hat.iota}
	\max
	\Bigg\{
	\Big|\zeta(\varsigma)-\zeta_0(\varsigma)\Big|
	: \varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2
	\Bigg\}
	&\le \hat{\iota} \delta\,, \\
	\label{e:ZETA.delta.error.mult.rr}
	\bigg|
		\frac{\zeta(\SSPIN{r}\SSPIN{r})}
		{\zeta_0(\SSPIN{r}\SSPIN{r})}-1\bigg|
	&\le\ddot{\delta}\,.
	\end{align}
Then there exist weights $(b_{3/4})^1$, $(b_{3/4})^2$, $x_{3/4}$ such that under the corresponding measure $\mu_{3/4}$ (see \eqref{e:ZETA.mu.t}) the spin $\varsigma$ has marginal $\zeta_{3/4}=\zeta$. Moreover, if we let $\hat{z}_t$ be the normalizing constant such that
	\[
	\hat{q}_t(\sigma)
	= \frac1{\hat{z}_t}
	(b_t)^1(\sigma^1)(b_t)^2(\sigma^2)
	\sum_{\varsigma:\varsigma\sim\sigma}
	x_t(\varsigma)
	\]
is a probability measure,
then the new weights can be chosen such that the error between $\hat{q}_0$ and $\hat{q}_{3/4}$ is very small:
	\[
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\hat{q}_0,\hat{q}_{3/4})
	\le k^{O(1)} \begin{pmatrix}
	\hat{\iota} & 0 \\ 2^k\hat{\iota} &0 \\ 1& 1
	\end{pmatrix}
	\begin{pmatrix}
	\delta \\ \ddot{\delta}
	\end{pmatrix}\,,\]
using the notation of 
Definition~\ref{d:clause.rel.error}.


\begin{proof} We begin with some easy observations.
By the assumption that $\dot{q}=\Theta(1)$ 
and $b^i=\Theta(1)$, we have
	\[
	\mu_0(\sigma,\varsigma)
	=
	\frac{\Ind{\sigma\sim\varsigma} }{z_0}
	\Theta(1)
	x(\varsigma)\,.
	\]
It then follows from \eqref{e:ZETA.assume.ww}
and \eqref{e:ZETA.assume.iota} that
$x(\SSPIN{w}\SSPIN{w})/z_0\ge 1-k^{O(1)}/2^k$, while
	\begin{align*}
	\max\Bigg\{
	\frac{x(\varsigma)}{z_0}
	: \varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2
		\setminus\set{\SSPIN{w}\SSPIN{w}}
	\Bigg\}
	&\le
	\frac{k^{O(1)}}{2^k}\,,\\
	\max\Bigg\{
	\frac{x(\varsigma)}{z_0}
	: \varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2
	\Bigg\} 
	\le O(\hat{\iota})
	&\le \frac{O(1)}{2^{k(1+\epsilon)}}\,.
	\end{align*}
This implies that $\mu_0(\sigma)=\Theta(1)$ for all $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$, since in this case
	\[
	\mu_0(\sigma)
	=\frac1{z_0}\bigg\{ \Theta(1) 
	x(\SSPIN{w}\SSPIN{w}) + \frac{k^{O(1)}}{2^k}\bigg\}
	=\Theta(1)\,.
	\]
Next, by the assumption that ${}_\star\hspace{-1pt}\pi_e$ is nice and $\mu_0$ is judicious, we have
	\[
	\frac{\Theta(1)}{2^k}
	= {}_\star\hspace{-1pt}\pi_e(\SSPIN{r})
	= \mu_0(\sigma^1=\SSPIN{r})
	= \frac{\Theta(1)}{z_0}
	\sum_{\vartheta\in \set{\SSPIN{r}}\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}}
	x(\vartheta)
	= \frac{\Theta(1)x(\SSPIN{r}\SSPIN{w})}{z_0}
	+ \frac{O(1)}{2^{k(1+\epsilon)}}\,,
	\]
which shows that $x(\SSPIN{r}\SSPIN{w})=\Theta(2^{-k})$. It follows from this that 
	\[
	\mu_0(\sigma=\vartheta)
	= \frac{\Theta(1)}{2^k}
	\quad\textup{for all }
	\vartheta\in\set{\SSPIN{r}\SSPIN{y},\SSPIN{r}\SSPIN{c},
		\SSPIN{y}\SSPIN{r},\SSPIN{c}\SSPIN{r}}\,.
	\]
Lastly, we note that \eqref{e:ZETA.assume.iota} directly implies
$\mu_0(\sigma=\SSPIN{r}\SSPIN{r})
=\zeta_0(\SSPIN{r}\SSPIN{r}) \le 2^{-k(1+\epsilon)}$. In summary we have seen that the assumptions of the lemma imply
	\begin{equation}\label{e:ZETA.mu.zero.estimates}
	\mu_0(\sigma=\vartheta)
	= \begin{cases}
	\Theta(1) & \textup{if $\SSPIN{r}[\vartheta]=0$,}\\
	\Theta(2^{-k}) & \textup{if $\SSPIN{r}[\vartheta]=1$,}\\
	O(2^{-k(1+\epsilon)})
	& \textup{if $\SSPIN{r}[\vartheta]=2$,}
	\end{cases}\end{equation}
for $\vartheta\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$.\smallskip


\noindent\bemph{Part 1. Description of update procedure.} We will define a sequence of weights $(b_t)^i$, $x_t$ ending with the desired weights at $t= 3/4$. For each $t$ denote the corresponding measure
	\begin{equation}\label{e:ZETA.mu.t}
	\mu_t(\sigma,\varsigma)
	=\frac{\Ind{\sigma\sim\varsigma}}{z_t}
	\dot{q}(\sigma) 
	(b_t)^1(\sigma^1)(b_t)^2(\sigma^2)
	x_t(\varsigma)\,,\end{equation}
with $z_t$ the normalizing constant. 
Let $\zeta_t$ denote the marginal law of $\varsigma$ under $\mu_t$.
\begin{enumerate}[(a)]
\item \label{i:ZETA.update.yw}
\textit{Time $t=0$ to $t=1/4$.} First adjust the weight on $\varsigma=\SSPIN{y}\SSPIN{w}$: set
	\begin{align}
	\label{e:ZETA.update.yw.b}
	\frac{(b_{1/4})^1(\SSPIN{y})}{(b_0)^1(\SSPIN{y})}
	&= \frac{\mu_0(\sigma^1=\SSPIN{y})-\zeta(\SSPIN{y}\SSPIN{w})}
	{\mu_0(\sigma^1=\SSPIN{y})-\mu_0(\varsigma=\SSPIN{y}\SSPIN{w})}
	\,,\\
	\frac{x_{1/4}(\SSPIN{y}\SSPIN{w})}{x_0(\SSPIN{y}\SSPIN{w})}
	&= \frac{\mu_0(\sigma^1=\SSPIN{y})
	-\mu_0(\varsigma=\SSPIN{y}\SSPIN{w})}
		{\mu_0(\sigma^1=\SSPIN{y})-\zeta(\SSPIN{y}\SSPIN{w})}
	\frac{\zeta(\SSPIN{y}\SSPIN{w})}{\mu_0(\varsigma=\SSPIN{y}\SSPIN{w})}\,.
	\label{e:ZETA.update.yw.x}
	\end{align}
We call \eqref{e:ZETA.update.yw.b} and \eqref{e:ZETA.update.yw.x} the \bemph{$\SSPIN{y}\SSPIN{w}$-update}. At the same time also make the updates
\eqref{e:ZETA.update.yw.b}
and \eqref{e:ZETA.update.yw.x}
with $\SSPIN{c}$ in place of $\SSPIN{y}$,
to define new weights
$(b_{1/4})^1(\SSPIN{c})$ and $x_{1/4}(\SSPIN{c}\SSPIN{w})$
--- we call this the \bemph{$\SSPIN{c}\SSPIN{w}$-update}.
Keep all the other weights unchanged, that is,
$(b_{1/4})^1(\SSPIN{r})=(b_0)^1(\SSPIN{r})$,
$(b_{1/4})^2(\tau)=(b_0)^1(\tau)$ for all $\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}$, and $x_{1/4}(\varsigma)=x_0(\varsigma)$ for all $\varsigma \notin\set{\SSPIN{y}\SSPIN{w},\SSPIN{c}\SSPIN{w}}$.



\item \label{i:ZETA.update.wy}
Time $t=1/4$ to $t=1/2$. Perform the analogous update in the second copy: for the \bemph{$\SSPIN{w}\SSPIN{y}$-update}, set
	\begin{align*}
	\frac{(b_{1/2})^2(\SSPIN{y})}{(b_{1/4})^2(\SSPIN{y})}
	&= \frac{\mu_{1/4}(\sigma^2=\SSPIN{y})-\zeta(\SSPIN{w}\SSPIN{y})}
	{\mu_{1/4}(\sigma^2=\SSPIN{y})
	-\mu_{1/4}(\varsigma=\SSPIN{w}\SSPIN{y})}
	\,,\\
	\frac{x_{1/2}(\SSPIN{w}\SSPIN{y})}{x_{1/4}(\SSPIN{w}\SSPIN{y})}
	&= \frac{\mu_{1/4}(\sigma^2=\SSPIN{y})
	-\mu_{1/4}(\varsigma=\SSPIN{w}\SSPIN{y})}
		{\mu_{1/4}(\sigma^2=\SSPIN{y})-\zeta(\SSPIN{w}\SSPIN{y})}
	\frac{\zeta(\SSPIN{w}\SSPIN{y})}
	{\mu_{1/4}(\varsigma=\SSPIN{w}\SSPIN{y})}\,.
	\end{align*}
Likewise make the \bemph{$\SSPIN{w}\SSPIN{c}$-update}, to define new weights $(b_{1/2})^2(\SSPIN{c})$ and $x_{1/2}(\SSPIN{w}\SSPIN{c})$. Again, keep all the other weights unchanged.

\item \label{i:ZETA.update.x.only} Time $t=1/2$ to $t=3/4$. Finally, for all $\varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2$, update
	\[
	\frac{x_{3/4}(\varsigma)}{x_{1/2}(\varsigma)}
	= \frac{\zeta(\varsigma)}{\zeta_{1/2}(\varsigma)}\,.
	\]
Leave the $b$-weights unchanged, that is,
$(b_{3/4})^i(\tau)=(b_{1/2})^i(\tau)$
for $i=1,2$ and all $\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}$.
\end{enumerate}
We begin with a simple observation about the first update, from $t=0$ to $t=1/4$. At time $t=0$, the non-normalized weight on the event $\set{\sigma^1=\SSPIN{y}}$ is given by $z_0\mu_0(\sigma^1=\SSPIN{y})$. At time $t=1/4$, the non-normalized weight on the same event is
	\begin{align}\nonumber
	z_{1/4}\mu_{1/4}(\sigma^1=\SSPIN{y})
	&= z_0\frac{(b_{1/4})^1(\SSPIN{y})}{(b_0)^1(\SSPIN{y})}
	\Bigg(
	\mu_0(\sigma^1=\SSPIN{y},\varsigma\ne\SSPIN{y}\SSPIN{w})
	+\mu_0(\varsigma=\SSPIN{y}\SSPIN{w})
	\frac{x_{1/4}(\SSPIN{y}\SSPIN{w})}{x_0(\SSPIN{y}\SSPIN{w})}
	\Bigg)
	\\
	&= 
	z_0 \Bigg\{
	\Big(\mu_0(\sigma^1=\SSPIN{y})-\zeta(\SSPIN{y}\SSPIN{w})\Big)
	+ \zeta(\SSPIN{y}\SSPIN{w})
	 \Bigg\}
	= z_0 \mu_0(\sigma^1=\SSPIN{y})\,,
	\label{e:ZETA.same.normalization}
	\end{align}
and likewise
$z_{1/4}\mu_{1/4}(\sigma^1=\SSPIN{c})=
z_0 \mu_0(\sigma^1=\SSPIN{c})$. The weight of the event $\set{\sigma^1=\SSPIN{r}}$ remains unchanged, so altogether we have $z_{1/4}=z_0$. For the same reason $z_{1/2}=z_{1/4}$. We now turn to analyzing the effect of these updates on the $\sigma$-marginal.\smallskip

\noindent\bemph{Part~2. Effect of update \eqref{i:ZETA.update.yw} on $\sigma$-marginal.}
The first change in the $b$-weights can be bounded as
	\begin{align}\nonumber
	\bigg|\frac{(b_{1/4})^1(\SSPIN{y})}{(b_0)^1(\SSPIN{y})}-1\bigg|
	&\stackrel{\eqref{e:ZETA.update.yw.b}}{=}
	\bigg|\frac{\mu_0(\sigma^1=\SSPIN{y})-\zeta(\SSPIN{y}\SSPIN{w})}
	{\mu_0(\sigma^1=\SSPIN{y})-\mu_0(\varsigma=\SSPIN{y}\SSPIN{w})}-1\bigg|
	\stackrel{\eqref{e:ZETA.delta.error}}{=}
	\bigg|\frac{\mu_0(\sigma^1=\SSPIN{y})-\zeta(\SSPIN{y}\SSPIN{w})}
	{\mu_0(\sigma^1=\SSPIN{y})-\zeta(\SSPIN{y}\SSPIN{w})
		- k^{O(1)} \delta/2^k}-1\bigg|\\
	&\stackrel{\eqref{e:ZETA.assume.ww}}{=}
	\bigg|\frac{\mu_0(\sigma^1=\SSPIN{y})
		- k^{O(1)}\delta/2^k}
	{\mu_0(\sigma^1=\SSPIN{y})
		- k^{O(1)} \delta/2^k}-1\bigg|
	\le \frac{k^{O(1)} \delta}{2^k}
	\label{e:ZETA.b.x.error}
	\end{align}
--- the last estimate above uses the assumption that ${}_\star\hspace{-1pt}\pi_e$ is nice, which implies that ${}_\star\hspace{-1pt}\pi_e(\SSPIN{y})=\Theta(1)$.
Now, note it follows from \eqref{e:ZETA.same.normalization} that it does not make a difference if the $\SSPIN{y}\SSPIN{w}$-update and $\SSPIN{c}\SSPIN{w}$-update are done simultaneously or in sequence. Suppose for this part of the proof that we make only the $\SSPIN{y}\SSPIN{w}$-update (i.e., only \eqref{e:ZETA.update.yw.b} and \eqref{e:ZETA.update.yw.x}), without making the $\SSPIN{c}\SSPIN{w}$-update. Let $\mu_{1/8}$ denote the measure that results, and define the signed measure $\Gamma\equiv\Gamma_{1/8}\equiv\mu_{1/8}-\mu_0$; we now proceed to bound $\Gamma$. The event $\set{\varsigma=\SSPIN{y}\SSPIN{w}}$ is affected by both the $b$- and $x$-updates: 
	\begin{align}\nonumber
	\Big|\Gamma(\varsigma=\SSPIN{y}\SSPIN{w})\Big|
	&\equiv\Big|\zeta_{1/8}(\SSPIN{y}\SSPIN{w})
		-\zeta_0(\SSPIN{y}\SSPIN{w})\Big|
	=\zeta_0(\SSPIN{y}\SSPIN{w})
	\Bigg| 
	\frac{(b_{1/4})^1(\SSPIN{y})}{(b_0)^1(\SSPIN{y})}
	\frac{x_{1/4}(\SSPIN{y}\SSPIN{w})}{x_0(\SSPIN{y}\SSPIN{w})}-1\Bigg|
	\stackrel{\eqref{e:ZETA.update.yw.x}}{=}
	\Bigg| \zeta(\SSPIN{y}\SSPIN{w})
	\frac{(b_{1/4})^1(\SSPIN{y})}{(b_0)^1(\SSPIN{y})}
	-\zeta_0(\SSPIN{y}\SSPIN{w})\Bigg|
	\\ \nonumber
	&\stackrel{\eqref{e:ZETA.update.yw.x}}{=}
	\bigg|
	\frac{\mu_0(\sigma^1=\SSPIN{y})
	-\mu_0(\varsigma=\SSPIN{y}\SSPIN{w})}
		{\mu_0(\sigma^1=\SSPIN{y})-\zeta(\SSPIN{y}\SSPIN{w})}
	\zeta(\SSPIN{y}\SSPIN{w})
	-\zeta_0(\SSPIN{y}\SSPIN{w})
	\bigg|\stackrel{\eqref{e:ZETA.b.x.error}}{=}
	\bigg|
	\bigg(1 + \frac{k^{O(1)}\delta}{2^k}
	 \bigg) \zeta(\SSPIN{y}\SSPIN{w})-\zeta_0(\SSPIN{y}\SSPIN{w})
	\bigg|\\
	&\stackrel{\eqref{e:ZETA.assume.ww}}{=} \bigg|
	\zeta(\SSPIN{y}\SSPIN{w})-\zeta_0(\SSPIN{y}\SSPIN{w})
	+ \frac{k^{O(1)}\delta}{4^k}
	\bigg|
	\stackrel{\eqref{e:ZETA.delta.error}}{\le }
	\frac{k^{O(1)}\delta}{2^k}\,.
	\label{e:ZETA.x.error.add}
	\end{align}
Next let us consider events that are only affected by the $b$-update: using \eqref{e:ZETA.b.x.error} gives
	\begin{align*}
	\Bigg|\Gamma\Bigg(\hspace{-3pt}\begin{array}{c}
	\sigma=\SSPIN{y}\SSPIN{y},\\
	\varsigma=\SSPIN{y}\SSPIN{y}
	\end{array}\hspace{-3pt}\Bigg)\Bigg|
	&=\mu_0\Bigg(\hspace{-3pt}\begin{array}{c}
	\sigma=\SSPIN{y}\SSPIN{y},\\
	\varsigma=\SSPIN{y}\SSPIN{y}
	\end{array}\hspace{-3pt}\Bigg)\cdot
	\Bigg|
	\frac{(b_{1/4})^1(\SSPIN{y})}{(b_0)^1(\SSPIN{y})}-1 
	\Bigg|
	\stackrel{\eqref{e:ZETA.assume.iota}}{\le} 
	\frac{k^{O(1)} \hat{\iota} \delta}{2^k} \,,\\
	\Bigg|\Gamma
	\Bigg(\hspace{-3pt}\begin{array}{c}
	\sigma=\SSPIN{y}\SSPIN{y},\\
	\varsigma=\SSPIN{w}\SSPIN{y}
	\end{array}\hspace{-3pt}\Bigg)\Bigg|
	&=\mu_0\Bigg(\hspace{-3pt}\begin{array}{c}
	\sigma=\SSPIN{y}\SSPIN{y},\\
	\varsigma=\SSPIN{w}\SSPIN{y}
	\end{array}\hspace{-3pt}\Bigg)\cdot
	\Bigg|
	\frac{(b_{1/4})^1(\SSPIN{y})}{(b_0)^1(\SSPIN{y})}-1\Bigg|
	\stackrel{\eqref{e:ZETA.assume.ww}}{\le} 
	\frac{k^{O(1)} \delta}{4^k}\,.
	\end{align*}
Similarly, for any $\vartheta\in\set{\SSPIN{y},\SSPIN{w}}\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}$ we have,
again using \eqref{e:ZETA.b.x.error}, that
	\begin{equation}\label{e:ZETA.sigma.one.yellow.varsigma}
	\Bigg|\Gamma\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma^1=\SSPIN{y},\\
		\varsigma=\vartheta
		\end{array}\hspace{-3pt}\Bigg)\Bigg|
	=\mu_0\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma^1=\SSPIN{y},\\
		\varsigma=\vartheta
		\end{array}\hspace{-3pt}\Bigg)
	\cdot\Bigg|
		\frac{(b_{1/4})^1(\SSPIN{y})}{(b_0)^1(\SSPIN{y})}-1
		\Bigg|
	\stackrel{\eqref{e:ZETA.assume.ww}}{\le} 
	\frac{k^{O(1)} \delta}{4^k}\,.
	\end{equation}
As a consequence, for any $\vartheta\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2\setminus\set{\SSPIN{y}\SSPIN{w},\SSPIN{w}\SSPIN{w}}$ we have
	\begin{equation}\label{e:ZETA.at.most.b.update}
	\Big|\Gamma(\varsigma=\vartheta)
\Big|
	=\Bigg| \Gamma
		\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma^1=\SSPIN{y},\\
		\varsigma=\vartheta
		\end{array}\hspace{-3pt}\Bigg)
	+\overbrace{\Gamma
		\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma^1\ne\SSPIN{y},\\
		\varsigma=\vartheta
		\end{array}\hspace{-3pt}\Bigg)}^\textup{zero}
		\Bigg|
	\stackrel{\eqref{e:ZETA.sigma.one.yellow.varsigma}}{\le}
	\frac{k^{O(1)} \delta}{4^k}\,.
	\end{equation}
Similarly we also have the bound
	\begin{equation}\label{e:ZETA.combined.ww.yw}
	\Bigg|
	\Gamma\Bigg(
		\hspace{-3pt}\begin{array}{c}\sigma^1=\SSPIN{y},\\
		\varsigma\in\set{\SSPIN{w}\SSPIN{w},\SSPIN{y}\SSPIN{w}}
		\end{array}\hspace{-3pt}\Bigg)\Bigg|
	=\Bigg| \overbrace{
	\Gamma(\sigma^1=\SSPIN{y})
	}^\textup{zero by
		\eqref{e:ZETA.same.normalization}}
	{} - \Gamma\Bigg(
		\hspace{-3pt}\begin{array}{c}\sigma^1=\SSPIN{y},\\
		\varsigma
		\in\set{\SSPIN{y},\SSPIN{w}}
		\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}
		\end{array}\hspace{-3pt}\Bigg)
	\Bigg|
	\stackrel{\eqref{e:ZETA.sigma.one.yellow.varsigma}}{\le}
	\frac{k^{O(1)}\delta}{4^k}\,.
	\end{equation}
Next we note that under both $\mu_0$ and $\mu_{1/4}$, the conditional probability of $\sigma^2$ given $\sigma^1=\SSPIN{y}$ and $\varsigma$ is given by
	\[
	\mu_t\Bigg(\sigma^2=\SSPIN{y}\,\Bigg|\,
		\hspace{-3pt}\begin{array}{c}\sigma^1=\SSPIN{y},\\
		\varsigma=\vartheta\end{array}\hspace{-3pt}\Bigg)
	=\begin{cases}
	1 & \textup{if $\vartheta\in
		\set{\SSPIN{y}\SSPIN{y},\SSPIN{w}\SSPIN{y}}$,}\\
	\displaystyle\frac{\dot{q}(\SSPIN{y}\SSPIN{y})(b_0)^2(\SSPIN{y})}
		{\dot{q}(\SSPIN{y}\SSPIN{y})(b_0)^2(\SSPIN{y})
			+\dot{q}(\SSPIN{y}\SSPIN{c})(b_0)^2(\SSPIN{c})}
	\le O(1)
	&\textup{if $\vartheta\in
		\set{\SSPIN{y}\SSPIN{w},\SSPIN{w}\SSPIN{w}}$,}
	\end{cases}
	\]
for both $t=0$ and $t=1/4$. It follows that
	\[
	\Big|\Gamma(\sigma=\SSPIN{y}\SSPIN{y})\Big|
	=\Bigg|
	\underbrace{\Gamma\Bigg(\hspace{-3pt}\begin{array}{c}\sigma^1=\SSPIN{y},\\
		\varsigma\in\set{\SSPIN{y}\SSPIN{y},\SSPIN{w}\SSPIN{y}}\end{array}\hspace{-3pt}\Bigg)
		}_{\textup{bounded by \eqref{e:ZETA.sigma.one.yellow.varsigma}}}
		\cdot1
		+
	\underbrace{
	\Gamma\Bigg(\hspace{-3pt}\begin{array}{c}
	\sigma^1=\SSPIN{y},\\
	\varsigma\in\set{\SSPIN{w}\SSPIN{w},\SSPIN{y}\SSPIN{w}}
	\end{array}\hspace{-3pt}\Bigg)
	}_{\textup{bounded by \eqref{e:ZETA.combined.ww.yw}}}
	\cdot O(1)
		\Bigg|
	\le \frac{k^{O(1)}\delta}{4^k}\,.
	\]
Similar arguments (details omitted) can be used to bound $\Gamma(\sigma=\vartheta)$ for all $\vartheta\in\set{\SSPIN{y},\SSPIN{c}}^2$, so altogether we have
	\begin{equation}\label{e:ZETA.change.in.sigma.cysquared}
	\max\Bigg\{
	\Big| \Gamma(\sigma=\vartheta)\Big|
	:\vartheta\in\set{\SSPIN{y},\SSPIN{c}}^2
	\Bigg\}
	\le \frac{k^{O(1)}\delta}{4^k}\,.
	\end{equation}
Lastly we note that $\Gamma(\sigma^1=\SSPIN{r})=0$, while
	\begin{equation}\label{e:ZETA.yw.update.doesnt.change.red.mgl}
	\Big|\Gamma(\sigma^2=\SSPIN{r})\Big|
	=\Bigg|\Gamma\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma^1=\SSPIN{y},\\
		\sigma^2=\SSPIN{r}\end{array}\hspace{-3pt}
		\Bigg)
	+\underbrace{
	\Gamma\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma^1\ne\SSPIN{y},\\
		\sigma^2=\SSPIN{r}\end{array}\hspace{-3pt}
		\Bigg)
	}_\textup{zero}
	\Bigg|
	\stackrel{\eqref{e:ZETA.at.most.b.update}}{\le}
	\frac{k^{O(1)} \delta}{4^k}\,.\end{equation}
This concludes our analysis of the effect of 
\eqref{e:ZETA.update.yw.b} and \eqref{e:ZETA.update.yw.x} alone on the $\sigma$-marginal.\smallskip

\noindent\bemph{Part 3. Effect of updates \eqref{i:ZETA.update.yw} and \eqref{i:ZETA.update.wy} on $\sigma$-marginal.} Recall that $\mu_{1/2}$ is the measure that results after completing updates \eqref{i:ZETA.update.yw} and \eqref{i:ZETA.update.wy}, and denote the signed measure $\Delta\equiv\mu_{1/2}-\mu_0$. Recall that \eqref{e:ZETA.change.in.sigma.cysquared} bounds $|(\mu_{1/8}-\mu_0)(\sigma=\vartheta)|$ for all $\vartheta\in\set{\SSPIN{y},\SSPIN{c}}^2$, where from time $t=0$ to time $t=1/8$ we perform only the $\SSPIN{y}\SSPIN{w}$-update.
From time $t=1/8$ to time $t=1/2$ we perform analogously the $\SSPIN{c}\SSPIN{w}$-, $\SSPIN{w}\SSPIN{y}$-, and $\SSPIN{w}\SSPIN{c}$-updates, for which the analogous estimate holds. Therefore
	\[\max\Bigg\{\Big|\Delta(\sigma=\vartheta)\Big|
	:\vartheta\in\set{\SSPIN{y},\SSPIN{c}}^2\Bigg\}
	\le \frac{k^{O(1)}\delta}{4^k}\,.\]
On the other hand, the $\set{\sigma=\SSPIN{r}\SSPIN{r}}$ event is completely unaffected by updates
\eqref{i:ZETA.update.yw} and \eqref{i:ZETA.update.wy},
so $\Delta(\sigma=\SSPIN{r}\SSPIN{r})=0$. It remains to 
estimate $\Delta(\sigma=\vartheta)$ for $\vartheta\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$ with $\SSPIN{r}[\vartheta]=1$. To this end we note that for any $\vartheta\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$, the event $\set{\varsigma=\vartheta}$ is affected only by the $b$-updates, so
	\begin{equation}\label{e:ZETA.bound.add.error.RYCsq}
	\Delta(\varsigma=\vartheta)
	\stackrel{\eqref{e:ZETA.b.x.error}}{=}
	\frac{k^{O(1)}\delta}{2^k}
	\zeta_0(\vartheta)
	\stackrel{\eqref{e:ZETA.assume.iota}}{\le}
	\frac{k^{O(1)} \hat{\iota} \delta}{2^k}
	\stackrel{\eqref{e:ZETA.assume.iota}}{\le}
	\frac{k^{O(1)} \delta}{2^{k(2+\epsilon)}}
	\,.\end{equation}
By combining \eqref{e:ZETA.bound.add.error.RYCsq} with \eqref{e:ZETA.yw.update.doesnt.change.red.mgl} we obtain 
	\begin{equation}\label{e:ZETA.varsigma.rw.better.estimate}
	\Big| \Delta(\varsigma=\SSPIN{r}\SSPIN{w})\Big|
	=\bigg|
	\Delta(\sigma^1=\SSPIN{r})
	-\Delta(\varsigma\in
		\set{\SSPIN{r}}\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}})
	\bigg|
	\le \bigg(\frac1{2^k} + \hat{\iota} \bigg)
	\frac{k^{O(1)}\delta}{2^k} 
	\stackrel{\eqref{e:ZETA.assume.iota}}{\le} 
	\frac{k^{O(1)}\delta}{4^k} 
	\,.\end{equation}
The probability of $\sigma=\SSPIN{r}\SSPIN{y}$
conditional on $\varsigma=\SSPIN{r}\SSPIN{w}$ is given by
	\begin{equation}\label{e:ZETA.ry.given.rw}
	\mu_{1/2}\Big(\sigma=\SSPIN{r}\SSPIN{y}
		\,\Big|\,\varsigma=\SSPIN{r}\SSPIN{w}\Big)
	=\frac{\dot{q}(\SSPIN{r}\SSPIN{y}) (b_{1/2})^2(\SSPIN{y})}
		{\dot{q}(\SSPIN{r}\SSPIN{y}) (b_{1/2})^2(\SSPIN{y})
		+\dot{q}(\SSPIN{r}\SSPIN{c}) (b_{1/2})^2(\SSPIN{c})}
	\stackrel{\eqref{e:ZETA.b.x.error}}{=}
	\mu_0\Big(\sigma=\SSPIN{r}\SSPIN{y}\,
		\Big|\,\varsigma=\SSPIN{r}\SSPIN{w}
		\Big)
	\Bigg\{1 + \frac{k^{O(1)} \delta}{2^k}\Bigg\}\,.
	\end{equation}
Meanwhile $\mu_{1/2}(\sigma=\SSPIN{r}\SSPIN{y}\,|\,\varsigma=\SSPIN{r}\SSPIN{y})=1$. Combining the last few estimates gives
	\begin{align*}
	\mu_{1/2}(\sigma=\SSPIN{r}\SSPIN{y})
	&=\overbrace{
		\Bigg\{ \mu_{1/2}(\varsigma=\SSPIN{r}\SSPIN{w})
		\cdot\mu_{1/2}\Big(\sigma=\SSPIN{r}\SSPIN{y}
			\,\Big|\,\varsigma=\SSPIN{r}\SSPIN{w}\Big)\Bigg\}
		}^{\textup{estimate by
			\eqref{e:ZETA.varsigma.rw.better.estimate}
			and \eqref{e:ZETA.ry.given.rw}}}
		+
		\overbrace{\Bigg\{
		\mu_{1/2}(\varsigma=\SSPIN{r}\SSPIN{y})\cdot1\Bigg\}
		}^{\textup{estimate by \eqref{e:ZETA.bound.add.error.RYCsq}}}\\
	&=\Bigg\{ \mu_0(\varsigma=\SSPIN{r}\SSPIN{w})
	+ \frac{k^{O(1)}\delta}{4^k} 
	\Bigg\}
	\mu_0(\sigma=\SSPIN{r}\SSPIN{y}\,|\,\varsigma=\SSPIN{r}\SSPIN{w})
	\Bigg\{1 + \frac{k^{O(1)} \delta}{2^k}\Bigg\}
	+\Bigg\{
	\mu_0(\varsigma=\SSPIN{r}\SSPIN{y})+
		\frac{k^{O(1)}\hat{\iota}\delta}{2^k}\Bigg\}\\
	&\stackrel{\eqref{e:ZETA.assume.ww}}{=}
	\mu_0(\sigma=\SSPIN{r}\SSPIN{y})
	+ \bigg(\frac1{2^k} + \hat{\iota} \bigg)
	\frac{k^{O(1)}\delta}{2^k} 
	\stackrel{\eqref{e:ZETA.assume.iota}}{=} 
	\mu_0(\sigma=\SSPIN{r}\SSPIN{y})+
	\frac{k^{O(1)}\delta}{4^k}\,.
	\end{align*}
The analogous estimate holds for the event $\set{\sigma=\vartheta}$ for all $\vartheta\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$ with $\SSPIN{r}[\vartheta]=1$. Altogether, if we write $\omega_t$ for the marginal law of $\sigma$ under $\mu_t$, then we have
	\begin{equation}\label{e:ZETA.crelerr.a.b}
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\omega_0,\omega_{1/2})
	\le k^{O(1)} \begin{pmatrix}
	4^{-k} \\ 2^{-k} \\ 0
	\end{pmatrix} \delta\,,\end{equation}
having made use of \eqref{e:ZETA.mu.zero.estimates}.
\smallskip

\noindent\bemph{Part 4. Effect of updates \eqref{i:ZETA.update.yw} and \eqref{i:ZETA.update.wy} on $\varsigma$-marginal.} Recall that $\zeta_t$ denotes the marginal law of $\varsigma$ under $\mu_t$. 
Update \eqref{i:ZETA.update.yw} results in 
$\zeta_{1/4}(\varsigma)=\zeta(\varsigma)$
for $\varsigma\in\set{\SSPIN{y}\SSPIN{w},\SSPIN{c}\SSPIN{w}}$. Update \eqref{i:ZETA.update.wy} 
results in $\zeta_{1/2}(\varsigma)=\zeta(\varsigma)$
for $\varsigma\in\set{\SSPIN{w}\SSPIN{y},\SSPIN{w}\SSPIN{c}}$, but it need not hold that
$\zeta_{1/2}(\varsigma)=\zeta(\varsigma)$
for $\varsigma\in\set{\SSPIN{y}\SSPIN{w},\SSPIN{c}\SSPIN{w}}$.
However we claim that the discrepancy is very small. 
Recall that as a consequence of \eqref{e:ZETA.same.normalization} we have $z_0=z_{1/4}=z_{1/2}$. Therefore
	\begin{align*}
	\mu_{1/2}(\varsigma=\SSPIN{y}\SSPIN{w})
	&\stackrel{\eqref{e:ZETA.mu.t}}{=}
	\frac1{z_{1/2}}
	x_{1/2}(\SSPIN{y}\SSPIN{w})
	(b_{1/2})^1(\SSPIN{y})
	\Bigg\{ \dot{q}(\SSPIN{y}\SSPIN{y})(b_{1/2})^2(\SSPIN{y})
	+\dot{q}(\SSPIN{y}\SSPIN{c})(b_{1/2})^2(\SSPIN{c})
	\Bigg\} \\
	&\stackrel{\eqref{e:ZETA.b.x.error}}{=}
	\frac1{z_{1/4}}
	x_{1/4}(\SSPIN{y}\SSPIN{w})
	(b_{1/4})^1(\SSPIN{y})
	\Bigg\{\dot{q}(\SSPIN{y}\SSPIN{y})(b_{1/4})^2(\SSPIN{y})
	+\dot{q}(\SSPIN{y}\SSPIN{c})(b_{1/4})^2(\SSPIN{c})
	\Bigg\}
	\Bigg\{1 + \frac{k^{O(1)}\delta}{2^k}\Bigg\}\\
	&\stackrel{\eqref{e:ZETA.mu.t}}{=}
	\mu_{1/4}(\varsigma=\SSPIN{y}\SSPIN{w})
	\Bigg\{1 + \frac{k^{O(1)}\delta}{2^k}\Bigg\}
	\stackrel{\eqref{e:ZETA.assume.ww}}{=} 
	\zeta(\SSPIN{y}\SSPIN{w})
	+ \frac{k^{O(1)}\delta}{4^k}\,.
	\end{align*}
The analogous estimate holds for $\varsigma=\SSPIN{c}\SSPIN{w}$.
Denote the signed measure $\Upsilon\equiv\zeta_{1/2}-\zeta$; the above can be rewritten as
	\begin{equation}\label{e:ZETA.yw.error.after.four.updates}
	\max\Bigg\{
	\Big|\Upsilon(\SSPIN{y}\SSPIN{w}) \Big|,
	\Big|\Upsilon(\SSPIN{c}\SSPIN{w}) \Big|\Bigg\}
	=
	\Big|(\zeta_{1/2}-\zeta)(\SSPIN{y}\SSPIN{w}) \Big|
	\le \frac{k^{O(1)}\delta}{4^k}\,.
	\end{equation}
Next, for all $\vartheta\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$ we have
	\begin{equation}\label{e:ZETA.rycsq.error.after.four.updates}
	\Big|\Upsilon(\vartheta)\Big|
	=\bigg| (\zeta_{1/2}-\zeta_0)(\vartheta)
	+(\zeta_0-\zeta)(\vartheta)\bigg|
	\stackrel{\eqref{e:ZETA.bound.add.error.RYCsq}}
		{\le}
	\frac{k^{O(1)} \hat{\iota} \delta}{2^k}
	+\Big| (\zeta_0-\zeta)(\vartheta)\Big|
	\stackrel{\eqref{e:ZETA.delta.error.hat.iota}}
		{\le}
		O(\hat{\iota}\delta)\,.\end{equation}
Recall that $\mu_0(\sigma^i=\SSPIN{r})={}_\star\hspace{-1pt}\pi_e(\SSPIN{r})=\zeta^i(\SSPIN{r})$
for $i=1,2$. Therefore, using
\eqref{e:ZETA.varsigma.rw.better.estimate} 
and \eqref{e:ZETA.rycsq.error.after.four.updates}, we have
	\begin{equation}\label{e:ZETA.varsigma.rw.zeta.error}
	\Upsilon(\SSPIN{r}\SSPIN{w})
	=\Bigg|(\mu_{1/2}-\mu_0)(\sigma^1=\SSPIN{r})
	-\sum_{\vartheta\in\set{\SSPIN{r}}\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}}
	\Upsilon(\vartheta)\Bigg|
	\le\bigg( \frac{1}{4^k}
		+ \hat{\iota} \bigg) k^{O(1)} \delta
	\stackrel{\eqref{e:ZETA.assume.iota}}{\le} 
	k^{O(1)}\hat{\iota}\delta \,.\end{equation}
Combining
\eqref{e:ZETA.yw.error.after.four.updates},
\eqref{e:ZETA.rycsq.error.after.four.updates}, and \eqref{e:ZETA.varsigma.rw.zeta.error} gives
	\begin{equation}\label{e:ZETA.varsigma.ww.zeta.error}
	\Big|\Upsilon(\SSPIN{w}\SSPIN{w})\Big|
	= \Bigg|-\Upsilon
		\Bigg(\hspace{-3pt}\begin{array}{c}(\set{\SSPIN{w}}\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}})\\
		\cup(	\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}\times\set{\SSPIN{w}})
		\end{array}\hspace{-3pt}
		\Bigg)
	-\Upsilon\Big(\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2\Big)
	\Bigg|
	\le
	\bigg(\frac1{4^k} + \hat{\iota} \bigg)
		k^{O(1)}\delta
	\stackrel{\eqref{e:ZETA.assume.iota}}{\le} 
	k^{O(1)}\hat{\iota}\delta\,.
	\end{equation}
This concludes our analysis of updates \eqref{i:ZETA.update.yw} and \eqref{i:ZETA.update.wy}.\smallskip

\noindent\bemph{Part 5. Effect of update \eqref{i:ZETA.update.x.only}.} It is clear that we will have $\zeta_{3/4}=\zeta$, so it remains to understand the effect of update \eqref{i:ZETA.update.x.only} on the $\sigma$-marginal. 
Note that since the $b$-weights remain the same during update \eqref{i:ZETA.update.x.only}, the conditional probabilities of $\sigma$ given $\varsigma$ remain unchanged between times $t=1/2$ and $t=3/4$. Thus we have
	\[
	\mu_{3/4}(\sigma=\SSPIN{y}\SSPIN{y})
	= \sum_{\vartheta\in\set{\SSPIN{y},\SSPIN{w}}^2}
	\mu_{3/4}(\varsigma=\vartheta)
	\mu_{1/2}(\sigma=\SSPIN{y}\SSPIN{y}\,|\,\varsigma=\vartheta)
	= \mu_{1/2}(\sigma=\SSPIN{y}\SSPIN{y})
	+ k^{O(1)} \hat{\iota}\delta\,,
	\]
where the last estimate uses
\eqref{e:ZETA.yw.error.after.four.updates}, 
\eqref{e:ZETA.rycsq.error.after.four.updates},
and \eqref{e:ZETA.varsigma.ww.zeta.error}. The analogous bound holds for $\set{\sigma=\vartheta}$ for each $\vartheta\in\set{\SSPIN{y},\SSPIN{c}}^2$. Similarly we also have
	\[\mu_{3/4}(\sigma=\SSPIN{r}\SSPIN{y})
	=\Bigg\{ \mu_{3/4}(\varsigma=\SSPIN{r}\SSPIN{w})
	\mu_{1/2}\Big(\sigma=\SSPIN{r}\SSPIN{y}\,\Big|\,\varsigma=\SSPIN{r}\SSPIN{w}\Big)\Bigg\}
	+ \mu_{3/4}(\varsigma=\SSPIN{r}\SSPIN{y})
	\stackrel{\eqref{e:ZETA.varsigma.rw.zeta.error}}{=}
	\mu_{3/4}(\sigma=\SSPIN{r}\SSPIN{y})
	+ k^{O(1)}\hat{\iota}\delta\,,\]
and the analogous bound holds for all $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$ with $\SSPIN{r}[\sigma]=1$.
Lastly, for the case $\sigma=\SSPIN{r}\SSPIN{r}$, we note that
	\[
	\frac{\mu_{3/4}(\sigma=\SSPIN{r}\SSPIN{r})}
		{\mu_{1/2}(\sigma=\SSPIN{r}\SSPIN{r})}
	= \frac{\mu_{3/4}(\varsigma=\SSPIN{r}\SSPIN{r})}
		{\mu_0(\varsigma=\SSPIN{r}\SSPIN{r})}
	=\frac{\zeta(\SSPIN{r}\SSPIN{r})}
		{\zeta_0(\SSPIN{r}\SSPIN{r})}
	\stackrel{\eqref{e:ZETA.delta.error.mult.rr}}{=}
	 1 + O(\ddot{\delta})\,.
	\]
Combining the above estimates with 
\eqref{e:ZETA.mu.zero.estimates} and 
\eqref{e:ZETA.crelerr.a.b} gives
	\[
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\omega_0,\omega_{3/4})
	\le
	k^{O(1)} \begin{pmatrix}
	\hat{\iota} & 0 \\ 2^k\hat{\iota}&0 \\ 1&1
	\end{pmatrix}
	\begin{pmatrix} \delta \\ \ddot{\delta}
		\end{pmatrix} \,.
	\]
This can be translated to a similar error bound for the clause-to-variable messages via the relation
	\[
	\hat{q}_t(\sigma)
	=\frac{ \omega_t(\sigma)/\dot{q}(\sigma)}
		{\sum_{\sigma'}
		\omega_t(\sigma')/\dot{q}(\sigma')}\,.
	\]
The claimed result follows.
\end{proof}

 We begin with some easy observations.
By the assumption that $\dot{q}=\Theta(1)$ 
and $b^i=\Theta(1)$, we have
	\[
	\mu_0(\sigma,\varsigma)
	=
	\frac{\Ind{\sigma\sim\varsigma} }{z_0}
	\Theta(1)
	x(\varsigma)\,.
	\]
It then follows from \eqref{e:ZETA.assume.ww}
and \eqref{e:ZETA.assume.iota} that
$x(\SSPIN{w}\SSPIN{w})/z_0\ge 1-k^{O(1)}/2^k$, while
	\begin{align*}
	\max\Bigg\{
	\frac{x(\varsigma)}{z_0}
	: \varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2
		\setminus\set{\SSPIN{w}\SSPIN{w}}
	\Bigg\}
	&\le
	\frac{k^{O(1)}}{2^k}\,,\\
	\max\Bigg\{
	\frac{x(\varsigma)}{z_0}
	: \varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2
	\Bigg\} 
	\le O(\hat{\iota})
	&\le \frac{O(1)}{2^{k(1+\epsilon)}}\,.
	\end{align*}
This implies that $\mu_0(\sigma)=\Theta(1)$ for all $\sigma\in\set{\SSPIN{y},\SSPIN{c}}^2$, since in this case
	\[
	\mu_0(\sigma)
	=\frac1{z_0}\bigg\{ \Theta(1) 
	x(\SSPIN{w}\SSPIN{w}) + \frac{k^{O(1)}}{2^k}\bigg\}
	=\Theta(1)\,.
	\]
Next, by the assumption that ${}_\star\hspace{-1pt}\pi_e$ is nice and $\mu_0$ is judicious, we have
	\[
	\frac{\Theta(1)}{2^k}
	= {}_\star\hspace{-1pt}\pi_e(\SSPIN{r})
	= \mu_0(\sigma^1=\SSPIN{r})
	= \frac{\Theta(1)}{z_0}
	\sum_{\vartheta\in \set{\SSPIN{r}}\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}}
	x(\vartheta)
	= \frac{\Theta(1)x(\SSPIN{r}\SSPIN{w})}{z_0}
	+ \frac{O(1)}{2^{k(1+\epsilon)}}\,,
	\]
which shows that $x(\SSPIN{r}\SSPIN{w})=\Theta(2^{-k})$. It follows from this that 
	\[
	\mu_0(\sigma=\vartheta)
	= \frac{\Theta(1)}{2^k}
	\quad\textup{for all }
	\vartheta\in\set{\SSPIN{r}\SSPIN{y},\SSPIN{r}\SSPIN{c},
		\SSPIN{y}\SSPIN{r},\SSPIN{c}\SSPIN{r}}\,.
	\]
Lastly, we note that \eqref{e:ZETA.assume.iota} directly implies
$\mu_0(\sigma=\SSPIN{r}\SSPIN{r})
=\zeta_0(\SSPIN{r}\SSPIN{r}) \le 2^{-k(1+\epsilon)}$. In summary we have seen that the assumptions of the lemma imply
	\begin{equation}\label{e:ZETA.mu.zero.estimates}
	\mu_0(\sigma=\vartheta)
	= \begin{cases}
	\Theta(1) & \textup{if $\SSPIN{r}[\vartheta]=0$,}\\
	\Theta(2^{-k}) & \textup{if $\SSPIN{r}[\vartheta]=1$,}\\
	O(2^{-k(1+\epsilon)})
	& \textup{if $\SSPIN{r}[\vartheta]=2$,}
	\end{cases}\end{equation}
for $\vartheta\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$.\smallskip


\noindent\bemph{Part 1. Description of update procedure.} We will define a sequence of weights $(b_t)^i$, $x_t$ ending with the desired weights at $t= 3/4$. For each $t$ denote the corresponding measure
	\begin{equation}\label{e:ZETA.mu.t}
	\mu_t(\sigma,\varsigma)
	=\frac{\Ind{\sigma\sim\varsigma}}{z_t}
	\dot{q}(\sigma) 
	(b_t)^1(\sigma^1)(b_t)^2(\sigma^2)
	x_t(\varsigma)\,,\end{equation}
with $z_t$ the normalizing constant. 
Let $\zeta_t$ denote the marginal law of $\varsigma$ under $\mu_t$.
\begin{enumerate}[(a)]
\item \label{i:ZETA.update.yw}
\textit{Time $t=0$ to $t=1/4$.} First adjust the weight on $\varsigma=\SSPIN{y}\SSPIN{w}$: set
	\begin{align}
	\label{e:ZETA.update.yw.b}
	\frac{(b_{1/4})^1(\SSPIN{y})}{(b_0)^1(\SSPIN{y})}
	&= \frac{\mu_0(\sigma^1=\SSPIN{y})-\zeta(\SSPIN{y}\SSPIN{w})}
	{\mu_0(\sigma^1=\SSPIN{y})-\mu_0(\varsigma=\SSPIN{y}\SSPIN{w})}
	\,,\\
	\frac{x_{1/4}(\SSPIN{y}\SSPIN{w})}{x_0(\SSPIN{y}\SSPIN{w})}
	&= \frac{\mu_0(\sigma^1=\SSPIN{y})
	-\mu_0(\varsigma=\SSPIN{y}\SSPIN{w})}
		{\mu_0(\sigma^1=\SSPIN{y})-\zeta(\SSPIN{y}\SSPIN{w})}
	\frac{\zeta(\SSPIN{y}\SSPIN{w})}{\mu_0(\varsigma=\SSPIN{y}\SSPIN{w})}\,.
	\label{e:ZETA.update.yw.x}
	\end{align}
We call \eqref{e:ZETA.update.yw.b} and \eqref{e:ZETA.update.yw.x} the \bemph{$\SSPIN{y}\SSPIN{w}$-update}. At the same time also make the updates
\eqref{e:ZETA.update.yw.b}
and \eqref{e:ZETA.update.yw.x}
with $\SSPIN{c}$ in place of $\SSPIN{y}$,
to define new weights
$(b_{1/4})^1(\SSPIN{c})$ and $x_{1/4}(\SSPIN{c}\SSPIN{w})$
--- we call this the \bemph{$\SSPIN{c}\SSPIN{w}$-update}.
Keep all the other weights unchanged, that is,
$(b_{1/4})^1(\SSPIN{r})=(b_0)^1(\SSPIN{r})$,
$(b_{1/4})^2(\tau)=(b_0)^1(\tau)$ for all $\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}$, and $x_{1/4}(\varsigma)=x_0(\varsigma)$ for all $\varsigma \notin\set{\SSPIN{y}\SSPIN{w},\SSPIN{c}\SSPIN{w}}$.



\item \label{i:ZETA.update.wy}
Time $t=1/4$ to $t=1/2$. Perform the analogous update in the second copy: for the \bemph{$\SSPIN{w}\SSPIN{y}$-update}, set
	\begin{align*}
	\frac{(b_{1/2})^2(\SSPIN{y})}{(b_{1/4})^2(\SSPIN{y})}
	&= \frac{\mu_{1/4}(\sigma^2=\SSPIN{y})-\zeta(\SSPIN{w}\SSPIN{y})}
	{\mu_{1/4}(\sigma^2=\SSPIN{y})
	-\mu_{1/4}(\varsigma=\SSPIN{w}\SSPIN{y})}
	\,,\\
	\frac{x_{1/2}(\SSPIN{w}\SSPIN{y})}{x_{1/4}(\SSPIN{w}\SSPIN{y})}
	&= \frac{\mu_{1/4}(\sigma^2=\SSPIN{y})
	-\mu_{1/4}(\varsigma=\SSPIN{w}\SSPIN{y})}
		{\mu_{1/4}(\sigma^2=\SSPIN{y})-\zeta(\SSPIN{w}\SSPIN{y})}
	\frac{\zeta(\SSPIN{w}\SSPIN{y})}
	{\mu_{1/4}(\varsigma=\SSPIN{w}\SSPIN{y})}\,.
	\end{align*}
Likewise make the \bemph{$\SSPIN{w}\SSPIN{c}$-update}, to define new weights $(b_{1/2})^2(\SSPIN{c})$ and $x_{1/2}(\SSPIN{w}\SSPIN{c})$. Again, keep all the other weights unchanged.

\item \label{i:ZETA.update.x.only} Time $t=1/2$ to $t=3/4$. Finally, for all $\varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2$, update
	\[
	\frac{x_{3/4}(\varsigma)}{x_{1/2}(\varsigma)}
	= \frac{\zeta(\varsigma)}{\zeta_{1/2}(\varsigma)}\,.
	\]
Leave the $b$-weights unchanged, that is,
$(b_{3/4})^i(\tau)=(b_{1/2})^i(\tau)$
for $i=1,2$ and all $\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}$.
\end{enumerate}
We begin with a simple observation about the first update, from $t=0$ to $t=1/4$. At time $t=0$, the non-normalized weight on the event $\set{\sigma^1=\SSPIN{y}}$ is given by $z_0\mu_0(\sigma^1=\SSPIN{y})$. At time $t=1/4$, the non-normalized weight on the same event is
	\begin{align}\nonumber
	z_{1/4}\mu_{1/4}(\sigma^1=\SSPIN{y})
	&= z_0\frac{(b_{1/4})^1(\SSPIN{y})}{(b_0)^1(\SSPIN{y})}
	\Bigg(
	\mu_0(\sigma^1=\SSPIN{y},\varsigma\ne\SSPIN{y}\SSPIN{w})
	+\mu_0(\varsigma=\SSPIN{y}\SSPIN{w})
	\frac{x_{1/4}(\SSPIN{y}\SSPIN{w})}{x_0(\SSPIN{y}\SSPIN{w})}
	\Bigg)
	\\
	&= 
	z_0 \Bigg\{
	\Big(\mu_0(\sigma^1=\SSPIN{y})-\zeta(\SSPIN{y}\SSPIN{w})\Big)
	+ \zeta(\SSPIN{y}\SSPIN{w})
	 \Bigg\}
	= z_0 \mu_0(\sigma^1=\SSPIN{y})\,,
	\label{e:ZETA.same.normalization}
	\end{align}
and likewise
$z_{1/4}\mu_{1/4}(\sigma^1=\SSPIN{c})=
z_0 \mu_0(\sigma^1=\SSPIN{c})$. The weight of the event $\set{\sigma^1=\SSPIN{r}}$ remains unchanged, so altogether we have $z_{1/4}=z_0$. For the same reason $z_{1/2}=z_{1/4}$. We now turn to analyzing the effect of these updates on the $\sigma$-marginal.\smallskip

\noindent\bemph{Part~2. Effect of update \eqref{i:ZETA.update.yw} on $\sigma$-marginal.}
The first change in the $b$-weights can be bounded as
	\begin{align}\nonumber
	\bigg|\frac{(b_{1/4})^1(\SSPIN{y})}{(b_0)^1(\SSPIN{y})}-1\bigg|
	&\stackrel{\eqref{e:ZETA.update.yw.b}}{=}
	\bigg|\frac{\mu_0(\sigma^1=\SSPIN{y})-\zeta(\SSPIN{y}\SSPIN{w})}
	{\mu_0(\sigma^1=\SSPIN{y})-\mu_0(\varsigma=\SSPIN{y}\SSPIN{w})}-1\bigg|
	\stackrel{\eqref{e:ZETA.delta.error}}{=}
	\bigg|\frac{\mu_0(\sigma^1=\SSPIN{y})-\zeta(\SSPIN{y}\SSPIN{w})}
	{\mu_0(\sigma^1=\SSPIN{y})-\zeta(\SSPIN{y}\SSPIN{w})
		- k^{O(1)} \delta/2^k}-1\bigg|\\
	&\stackrel{\eqref{e:ZETA.assume.ww}}{=}
	\bigg|\frac{\mu_0(\sigma^1=\SSPIN{y})
		- k^{O(1)}\delta/2^k}
	{\mu_0(\sigma^1=\SSPIN{y})
		- k^{O(1)} \delta/2^k}-1\bigg|
	\le \frac{k^{O(1)} \delta}{2^k}
	\label{e:ZETA.b.x.error}
	\end{align}
--- the last estimate above uses the assumption that ${}_\star\hspace{-1pt}\pi_e$ is nice, which implies that ${}_\star\hspace{-1pt}\pi_e(\SSPIN{y})=\Theta(1)$.
Now, note it follows from \eqref{e:ZETA.same.normalization} that it does not make a difference if the $\SSPIN{y}\SSPIN{w}$-update and $\SSPIN{c}\SSPIN{w}$-update are done simultaneously or in sequence. Suppose for this part of the proof that we make only the $\SSPIN{y}\SSPIN{w}$-update (i.e., only \eqref{e:ZETA.update.yw.b} and \eqref{e:ZETA.update.yw.x}), without making the $\SSPIN{c}\SSPIN{w}$-update. Let $\mu_{1/8}$ denote the measure that results, and define the signed measure $\Gamma\equiv\Gamma_{1/8}\equiv\mu_{1/8}-\mu_0$; we now proceed to bound $\Gamma$. The event $\set{\varsigma=\SSPIN{y}\SSPIN{w}}$ is affected by both the $b$- and $x$-updates: 
	\begin{align}\nonumber
	\Big|\Gamma(\varsigma=\SSPIN{y}\SSPIN{w})\Big|
	&\equiv\Big|\zeta_{1/8}(\SSPIN{y}\SSPIN{w})
		-\zeta_0(\SSPIN{y}\SSPIN{w})\Big|
	=\zeta_0(\SSPIN{y}\SSPIN{w})
	\Bigg| 
	\frac{(b_{1/4})^1(\SSPIN{y})}{(b_0)^1(\SSPIN{y})}
	\frac{x_{1/4}(\SSPIN{y}\SSPIN{w})}{x_0(\SSPIN{y}\SSPIN{w})}-1\Bigg|
	\stackrel{\eqref{e:ZETA.update.yw.x}}{=}
	\Bigg| \zeta(\SSPIN{y}\SSPIN{w})
	\frac{(b_{1/4})^1(\SSPIN{y})}{(b_0)^1(\SSPIN{y})}
	-\zeta_0(\SSPIN{y}\SSPIN{w})\Bigg|
	\\ \nonumber
	&\stackrel{\eqref{e:ZETA.update.yw.x}}{=}
	\bigg|
	\frac{\mu_0(\sigma^1=\SSPIN{y})
	-\mu_0(\varsigma=\SSPIN{y}\SSPIN{w})}
		{\mu_0(\sigma^1=\SSPIN{y})-\zeta(\SSPIN{y}\SSPIN{w})}
	\zeta(\SSPIN{y}\SSPIN{w})
	-\zeta_0(\SSPIN{y}\SSPIN{w})
	\bigg|\stackrel{\eqref{e:ZETA.b.x.error}}{=}
	\bigg|
	\bigg(1 + \frac{k^{O(1)}\delta}{2^k}
	 \bigg) \zeta(\SSPIN{y}\SSPIN{w})-\zeta_0(\SSPIN{y}\SSPIN{w})
	\bigg|\\
	&\stackrel{\eqref{e:ZETA.assume.ww}}{=} \bigg|
	\zeta(\SSPIN{y}\SSPIN{w})-\zeta_0(\SSPIN{y}\SSPIN{w})
	+ \frac{k^{O(1)}\delta}{4^k}
	\bigg|
	\stackrel{\eqref{e:ZETA.delta.error}}{\le }
	\frac{k^{O(1)}\delta}{2^k}\,.
	\label{e:ZETA.x.error.add}
	\end{align}
Next let us consider events that are only affected by the $b$-update: using \eqref{e:ZETA.b.x.error} gives
	\begin{align*}
	\Bigg|\Gamma\Bigg(\hspace{-3pt}\begin{array}{c}
	\sigma=\SSPIN{y}\SSPIN{y},\\
	\varsigma=\SSPIN{y}\SSPIN{y}
	\end{array}\hspace{-3pt}\Bigg)\Bigg|
	&=\mu_0\Bigg(\hspace{-3pt}\begin{array}{c}
	\sigma=\SSPIN{y}\SSPIN{y},\\
	\varsigma=\SSPIN{y}\SSPIN{y}
	\end{array}\hspace{-3pt}\Bigg)\cdot
	\Bigg|
	\frac{(b_{1/4})^1(\SSPIN{y})}{(b_0)^1(\SSPIN{y})}-1 
	\Bigg|
	\stackrel{\eqref{e:ZETA.assume.iota}}{\le} 
	\frac{k^{O(1)} \hat{\iota} \delta}{2^k} \,,\\
	\Bigg|\Gamma
	\Bigg(\hspace{-3pt}\begin{array}{c}
	\sigma=\SSPIN{y}\SSPIN{y},\\
	\varsigma=\SSPIN{w}\SSPIN{y}
	\end{array}\hspace{-3pt}\Bigg)\Bigg|
	&=\mu_0\Bigg(\hspace{-3pt}\begin{array}{c}
	\sigma=\SSPIN{y}\SSPIN{y},\\
	\varsigma=\SSPIN{w}\SSPIN{y}
	\end{array}\hspace{-3pt}\Bigg)\cdot
	\Bigg|
	\frac{(b_{1/4})^1(\SSPIN{y})}{(b_0)^1(\SSPIN{y})}-1\Bigg|
	\stackrel{\eqref{e:ZETA.assume.ww}}{\le} 
	\frac{k^{O(1)} \delta}{4^k}\,.
	\end{align*}
Similarly, for any $\vartheta\in\set{\SSPIN{y},\SSPIN{w}}\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}$ we have,
again using \eqref{e:ZETA.b.x.error}, that
	\begin{equation}\label{e:ZETA.sigma.one.yellow.varsigma}
	\Bigg|\Gamma\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma^1=\SSPIN{y},\\
		\varsigma=\vartheta
		\end{array}\hspace{-3pt}\Bigg)\Bigg|
	=\mu_0\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma^1=\SSPIN{y},\\
		\varsigma=\vartheta
		\end{array}\hspace{-3pt}\Bigg)
	\cdot\Bigg|
		\frac{(b_{1/4})^1(\SSPIN{y})}{(b_0)^1(\SSPIN{y})}-1
		\Bigg|
	\stackrel{\eqref{e:ZETA.assume.ww}}{\le} 
	\frac{k^{O(1)} \delta}{4^k}\,.
	\end{equation}
As a consequence, for any $\vartheta\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2\setminus\set{\SSPIN{y}\SSPIN{w},\SSPIN{w}\SSPIN{w}}$ we have
	\begin{equation}\label{e:ZETA.at.most.b.update}
	\Big|\Gamma(\varsigma=\vartheta)
\Big|
	=\Bigg| \Gamma
		\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma^1=\SSPIN{y},\\
		\varsigma=\vartheta
		\end{array}\hspace{-3pt}\Bigg)
	+\overbrace{\Gamma
		\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma^1\ne\SSPIN{y},\\
		\varsigma=\vartheta
		\end{array}\hspace{-3pt}\Bigg)}^\textup{zero}
		\Bigg|
	\stackrel{\eqref{e:ZETA.sigma.one.yellow.varsigma}}{\le}
	\frac{k^{O(1)} \delta}{4^k}\,.
	\end{equation}
Similarly we also have the bound
	\begin{equation}\label{e:ZETA.combined.ww.yw}
	\Bigg|
	\Gamma\Bigg(
		\hspace{-3pt}\begin{array}{c}\sigma^1=\SSPIN{y},\\
		\varsigma\in\set{\SSPIN{w}\SSPIN{w},\SSPIN{y}\SSPIN{w}}
		\end{array}\hspace{-3pt}\Bigg)\Bigg|
	=\Bigg| \overbrace{
	\Gamma(\sigma^1=\SSPIN{y})
	}^\textup{zero by
		\eqref{e:ZETA.same.normalization}}
	{} - \Gamma\Bigg(
		\hspace{-3pt}\begin{array}{c}\sigma^1=\SSPIN{y},\\
		\varsigma
		\in\set{\SSPIN{y},\SSPIN{w}}
		\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}
		\end{array}\hspace{-3pt}\Bigg)
	\Bigg|
	\stackrel{\eqref{e:ZETA.sigma.one.yellow.varsigma}}{\le}
	\frac{k^{O(1)}\delta}{4^k}\,.
	\end{equation}
Next we note that under both $\mu_0$ and $\mu_{1/4}$, the conditional probability of $\sigma^2$ given $\sigma^1=\SSPIN{y}$ and $\varsigma$ is given by
	\[
	\mu_t\Bigg(\sigma^2=\SSPIN{y}\,\Bigg|\,
		\hspace{-3pt}\begin{array}{c}\sigma^1=\SSPIN{y},\\
		\varsigma=\vartheta\end{array}\hspace{-3pt}\Bigg)
	=\begin{cases}
	1 & \textup{if $\vartheta\in
		\set{\SSPIN{y}\SSPIN{y},\SSPIN{w}\SSPIN{y}}$,}\\
	\displaystyle\frac{\dot{q}(\SSPIN{y}\SSPIN{y})(b_0)^2(\SSPIN{y})}
		{\dot{q}(\SSPIN{y}\SSPIN{y})(b_0)^2(\SSPIN{y})
			+\dot{q}(\SSPIN{y}\SSPIN{c})(b_0)^2(\SSPIN{c})}
	\le O(1)
	&\textup{if $\vartheta\in
		\set{\SSPIN{y}\SSPIN{w},\SSPIN{w}\SSPIN{w}}$,}
	\end{cases}
	\]
for both $t=0$ and $t=1/4$. It follows that
	\[
	\Big|\Gamma(\sigma=\SSPIN{y}\SSPIN{y})\Big|
	=\Bigg|
	\underbrace{\Gamma\Bigg(\hspace{-3pt}\begin{array}{c}\sigma^1=\SSPIN{y},\\
		\varsigma\in\set{\SSPIN{y}\SSPIN{y},\SSPIN{w}\SSPIN{y}}\end{array}\hspace{-3pt}\Bigg)
		}_{\textup{bounded by \eqref{e:ZETA.sigma.one.yellow.varsigma}}}
		\cdot1
		+
	\underbrace{
	\Gamma\Bigg(\hspace{-3pt}\begin{array}{c}
	\sigma^1=\SSPIN{y},\\
	\varsigma\in\set{\SSPIN{w}\SSPIN{w},\SSPIN{y}\SSPIN{w}}
	\end{array}\hspace{-3pt}\Bigg)
	}_{\textup{bounded by \eqref{e:ZETA.combined.ww.yw}}}
	\cdot O(1)
		\Bigg|
	\le \frac{k^{O(1)}\delta}{4^k}\,.
	\]
Similar arguments (details omitted) can be used to bound $\Gamma(\sigma=\vartheta)$ for all $\vartheta\in\set{\SSPIN{y},\SSPIN{c}}^2$, so altogether we have
	\begin{equation}\label{e:ZETA.change.in.sigma.cysquared}
	\max\Bigg\{
	\Big| \Gamma(\sigma=\vartheta)\Big|
	:\vartheta\in\set{\SSPIN{y},\SSPIN{c}}^2
	\Bigg\}
	\le \frac{k^{O(1)}\delta}{4^k}\,.
	\end{equation}
Lastly we note that $\Gamma(\sigma^1=\SSPIN{r})=0$, while
	\begin{equation}\label{e:ZETA.yw.update.doesnt.change.red.mgl}
	\Big|\Gamma(\sigma^2=\SSPIN{r})\Big|
	=\Bigg|\Gamma\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma^1=\SSPIN{y},\\
		\sigma^2=\SSPIN{r}\end{array}\hspace{-3pt}
		\Bigg)
	+\underbrace{
	\Gamma\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma^1\ne\SSPIN{y},\\
		\sigma^2=\SSPIN{r}\end{array}\hspace{-3pt}
		\Bigg)
	}_\textup{zero}
	\Bigg|
	\stackrel{\eqref{e:ZETA.at.most.b.update}}{\le}
	\frac{k^{O(1)} \delta}{4^k}\,.\end{equation}
This concludes our analysis of the effect of 
\eqref{e:ZETA.update.yw.b} and \eqref{e:ZETA.update.yw.x} alone on the $\sigma$-marginal.\smallskip

\noindent\bemph{Part 3. Effect of updates \eqref{i:ZETA.update.yw} and \eqref{i:ZETA.update.wy} on $\sigma$-marginal.} Recall that $\mu_{1/2}$ is the measure that results after completing updates \eqref{i:ZETA.update.yw} and \eqref{i:ZETA.update.wy}, and denote the signed measure $\Delta\equiv\mu_{1/2}-\mu_0$. Recall that \eqref{e:ZETA.change.in.sigma.cysquared} bounds $|(\mu_{1/8}-\mu_0)(\sigma=\vartheta)|$ for all $\vartheta\in\set{\SSPIN{y},\SSPIN{c}}^2$, where from time $t=0$ to time $t=1/8$ we perform only the $\SSPIN{y}\SSPIN{w}$-update.
From time $t=1/8$ to time $t=1/2$ we perform analogously the $\SSPIN{c}\SSPIN{w}$-, $\SSPIN{w}\SSPIN{y}$-, and $\SSPIN{w}\SSPIN{c}$-updates, for which the analogous estimate holds. Therefore
	\[\max\Bigg\{\Big|\Delta(\sigma=\vartheta)\Big|
	:\vartheta\in\set{\SSPIN{y},\SSPIN{c}}^2\Bigg\}
	\le \frac{k^{O(1)}\delta}{4^k}\,.\]
On the other hand, the $\set{\sigma=\SSPIN{r}\SSPIN{r}}$ event is completely unaffected by updates
\eqref{i:ZETA.update.yw} and \eqref{i:ZETA.update.wy},
so $\Delta(\sigma=\SSPIN{r}\SSPIN{r})=0$. It remains to 
estimate $\Delta(\sigma=\vartheta)$ for $\vartheta\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$ with $\SSPIN{r}[\vartheta]=1$. To this end we note that for any $\vartheta\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$, the event $\set{\varsigma=\vartheta}$ is affected only by the $b$-updates, so
	\begin{equation}\label{e:ZETA.bound.add.error.RYCsq}
	\Delta(\varsigma=\vartheta)
	\stackrel{\eqref{e:ZETA.b.x.error}}{=}
	\frac{k^{O(1)}\delta}{2^k}
	\zeta_0(\vartheta)
	\stackrel{\eqref{e:ZETA.assume.iota}}{\le}
	\frac{k^{O(1)} \hat{\iota} \delta}{2^k}
	\stackrel{\eqref{e:ZETA.assume.iota}}{\le}
	\frac{k^{O(1)} \delta}{2^{k(2+\epsilon)}}
	\,.\end{equation}
By combining \eqref{e:ZETA.bound.add.error.RYCsq} with \eqref{e:ZETA.yw.update.doesnt.change.red.mgl} we obtain 
	\begin{equation}\label{e:ZETA.varsigma.rw.better.estimate}
	\Big| \Delta(\varsigma=\SSPIN{r}\SSPIN{w})\Big|
	=\bigg|
	\Delta(\sigma^1=\SSPIN{r})
	-\Delta(\varsigma\in
		\set{\SSPIN{r}}\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}})
	\bigg|
	\le \bigg(\frac1{2^k} + \hat{\iota} \bigg)
	\frac{k^{O(1)}\delta}{2^k} 
	\stackrel{\eqref{e:ZETA.assume.iota}}{\le} 
	\frac{k^{O(1)}\delta}{4^k} 
	\,.\end{equation}
The probability of $\sigma=\SSPIN{r}\SSPIN{y}$
conditional on $\varsigma=\SSPIN{r}\SSPIN{w}$ is given by
	\begin{equation}\label{e:ZETA.ry.given.rw}
	\mu_{1/2}\Big(\sigma=\SSPIN{r}\SSPIN{y}
		\,\Big|\,\varsigma=\SSPIN{r}\SSPIN{w}\Big)
	=\frac{\dot{q}(\SSPIN{r}\SSPIN{y}) (b_{1/2})^2(\SSPIN{y})}
		{\dot{q}(\SSPIN{r}\SSPIN{y}) (b_{1/2})^2(\SSPIN{y})
		+\dot{q}(\SSPIN{r}\SSPIN{c}) (b_{1/2})^2(\SSPIN{c})}
	\stackrel{\eqref{e:ZETA.b.x.error}}{=}
	\mu_0\Big(\sigma=\SSPIN{r}\SSPIN{y}\,
		\Big|\,\varsigma=\SSPIN{r}\SSPIN{w}
		\Big)
	\Bigg\{1 + \frac{k^{O(1)} \delta}{2^k}\Bigg\}\,.
	\end{equation}
Meanwhile $\mu_{1/2}(\sigma=\SSPIN{r}\SSPIN{y}\,|\,\varsigma=\SSPIN{r}\SSPIN{y})=1$. Combining the last few estimates gives
	\begin{align*}
	\mu_{1/2}(\sigma=\SSPIN{r}\SSPIN{y})
	&=\overbrace{
		\Bigg\{ \mu_{1/2}(\varsigma=\SSPIN{r}\SSPIN{w})
		\cdot\mu_{1/2}\Big(\sigma=\SSPIN{r}\SSPIN{y}
			\,\Big|\,\varsigma=\SSPIN{r}\SSPIN{w}\Big)\Bigg\}
		}^{\textup{estimate by
			\eqref{e:ZETA.varsigma.rw.better.estimate}
			and \eqref{e:ZETA.ry.given.rw}}}
		+
		\overbrace{\Bigg\{
		\mu_{1/2}(\varsigma=\SSPIN{r}\SSPIN{y})\cdot1\Bigg\}
		}^{\textup{estimate by \eqref{e:ZETA.bound.add.error.RYCsq}}}\\
	&=\Bigg\{ \mu_0(\varsigma=\SSPIN{r}\SSPIN{w})
	+ \frac{k^{O(1)}\delta}{4^k} 
	\Bigg\}
	\mu_0(\sigma=\SSPIN{r}\SSPIN{y}\,|\,\varsigma=\SSPIN{r}\SSPIN{w})
	\Bigg\{1 + \frac{k^{O(1)} \delta}{2^k}\Bigg\}
	+\Bigg\{
	\mu_0(\varsigma=\SSPIN{r}\SSPIN{y})+
		\frac{k^{O(1)}\hat{\iota}\delta}{2^k}\Bigg\}\\
	&\stackrel{\eqref{e:ZETA.assume.ww}}{=}
	\mu_0(\sigma=\SSPIN{r}\SSPIN{y})
	+ \bigg(\frac1{2^k} + \hat{\iota} \bigg)
	\frac{k^{O(1)}\delta}{2^k} 
	\stackrel{\eqref{e:ZETA.assume.iota}}{=} 
	\mu_0(\sigma=\SSPIN{r}\SSPIN{y})+
	\frac{k^{O(1)}\delta}{4^k}\,.
	\end{align*}
The analogous estimate holds for the event $\set{\sigma=\vartheta}$ for all $\vartheta\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$ with $\SSPIN{r}[\vartheta]=1$. Altogether, if we write $\omega_t$ for the marginal law of $\sigma$ under $\mu_t$, then we have
	\begin{equation}\label{e:ZETA.crelerr.a.b}
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\omega_0,\omega_{1/2})
	\le k^{O(1)} \begin{pmatrix}
	4^{-k} \\ 2^{-k} \\ 0
	\end{pmatrix} \delta\,,\end{equation}
having made use of \eqref{e:ZETA.mu.zero.estimates}.
\smallskip

\noindent\bemph{Part 4. Effect of updates \eqref{i:ZETA.update.yw} and \eqref{i:ZETA.update.wy} on $\varsigma$-marginal.} Recall that $\zeta_t$ denotes the marginal law of $\varsigma$ under $\mu_t$. 
Update \eqref{i:ZETA.update.yw} results in 
$\zeta_{1/4}(\varsigma)=\zeta(\varsigma)$
for $\varsigma\in\set{\SSPIN{y}\SSPIN{w},\SSPIN{c}\SSPIN{w}}$. Update \eqref{i:ZETA.update.wy} 
results in $\zeta_{1/2}(\varsigma)=\zeta(\varsigma)$
for $\varsigma\in\set{\SSPIN{w}\SSPIN{y},\SSPIN{w}\SSPIN{c}}$, but it need not hold that
$\zeta_{1/2}(\varsigma)=\zeta(\varsigma)$
for $\varsigma\in\set{\SSPIN{y}\SSPIN{w},\SSPIN{c}\SSPIN{w}}$.
However we claim that the discrepancy is very small. 
Recall that as a consequence of \eqref{e:ZETA.same.normalization} we have $z_0=z_{1/4}=z_{1/2}$. Therefore
	\begin{align*}
	\mu_{1/2}(\varsigma=\SSPIN{y}\SSPIN{w})
	&\stackrel{\eqref{e:ZETA.mu.t}}{=}
	\frac1{z_{1/2}}
	x_{1/2}(\SSPIN{y}\SSPIN{w})
	(b_{1/2})^1(\SSPIN{y})
	\Bigg\{ \dot{q}(\SSPIN{y}\SSPIN{y})(b_{1/2})^2(\SSPIN{y})
	+\dot{q}(\SSPIN{y}\SSPIN{c})(b_{1/2})^2(\SSPIN{c})
	\Bigg\} \\
	&\stackrel{\eqref{e:ZETA.b.x.error}}{=}
	\frac1{z_{1/4}}
	x_{1/4}(\SSPIN{y}\SSPIN{w})
	(b_{1/4})^1(\SSPIN{y})
	\Bigg\{\dot{q}(\SSPIN{y}\SSPIN{y})(b_{1/4})^2(\SSPIN{y})
	+\dot{q}(\SSPIN{y}\SSPIN{c})(b_{1/4})^2(\SSPIN{c})
	\Bigg\}
	\Bigg\{1 + \frac{k^{O(1)}\delta}{2^k}\Bigg\}\\
	&\stackrel{\eqref{e:ZETA.mu.t}}{=}
	\mu_{1/4}(\varsigma=\SSPIN{y}\SSPIN{w})
	\Bigg\{1 + \frac{k^{O(1)}\delta}{2^k}\Bigg\}
	\stackrel{\eqref{e:ZETA.assume.ww}}{=} 
	\zeta(\SSPIN{y}\SSPIN{w})
	+ \frac{k^{O(1)}\delta}{4^k}\,.
	\end{align*}
The analogous estimate holds for $\varsigma=\SSPIN{c}\SSPIN{w}$.
Denote the signed measure $\Upsilon\equiv\zeta_{1/2}-\zeta$; the above can be rewritten as
	\begin{equation}\label{e:ZETA.yw.error.after.four.updates}
	\max\Bigg\{
	\Big|\Upsilon(\SSPIN{y}\SSPIN{w}) \Big|,
	\Big|\Upsilon(\SSPIN{c}\SSPIN{w}) \Big|\Bigg\}
	=
	\Big|(\zeta_{1/2}-\zeta)(\SSPIN{y}\SSPIN{w}) \Big|
	\le \frac{k^{O(1)}\delta}{4^k}\,.
	\end{equation}
Next, for all $\vartheta\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$ we have
	\begin{equation}\label{e:ZETA.rycsq.error.after.four.updates}
	\Big|\Upsilon(\vartheta)\Big|
	=\bigg| (\zeta_{1/2}-\zeta_0)(\vartheta)
	+(\zeta_0-\zeta)(\vartheta)\bigg|
	\stackrel{\eqref{e:ZETA.bound.add.error.RYCsq}}
		{\le}
	\frac{k^{O(1)} \hat{\iota} \delta}{2^k}
	+\Big| (\zeta_0-\zeta)(\vartheta)\Big|
	\stackrel{\eqref{e:ZETA.delta.error.hat.iota}}
		{\le}
		O(\hat{\iota}\delta)\,.\end{equation}
Recall that $\mu_0(\sigma^i=\SSPIN{r})={}_\star\hspace{-1pt}\pi_e(\SSPIN{r})=\zeta^i(\SSPIN{r})$
for $i=1,2$. Therefore, using
\eqref{e:ZETA.varsigma.rw.better.estimate} 
and \eqref{e:ZETA.rycsq.error.after.four.updates}, we have
	\begin{equation}\label{e:ZETA.varsigma.rw.zeta.error}
	\Upsilon(\SSPIN{r}\SSPIN{w})
	=\Bigg|(\mu_{1/2}-\mu_0)(\sigma^1=\SSPIN{r})
	-\sum_{\vartheta\in\set{\SSPIN{r}}\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}}
	\Upsilon(\vartheta)\Bigg|
	\le\bigg( \frac{1}{4^k}
		+ \hat{\iota} \bigg) k^{O(1)} \delta
	\stackrel{\eqref{e:ZETA.assume.iota}}{\le} 
	k^{O(1)}\hat{\iota}\delta \,.\end{equation}
Combining
\eqref{e:ZETA.yw.error.after.four.updates},
\eqref{e:ZETA.rycsq.error.after.four.updates}, and \eqref{e:ZETA.varsigma.rw.zeta.error} gives
	\begin{equation}\label{e:ZETA.varsigma.ww.zeta.error}
	\Big|\Upsilon(\SSPIN{w}\SSPIN{w})\Big|
	= \Bigg|-\Upsilon
		\Bigg(\hspace{-3pt}\begin{array}{c}(\set{\SSPIN{w}}\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}})\\
		\cup(	\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}\times\set{\SSPIN{w}})
		\end{array}\hspace{-3pt}
		\Bigg)
	-\Upsilon\Big(\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2\Big)
	\Bigg|
	\le
	\bigg(\frac1{4^k} + \hat{\iota} \bigg)
		k^{O(1)}\delta
	\stackrel{\eqref{e:ZETA.assume.iota}}{\le} 
	k^{O(1)}\hat{\iota}\delta\,.
	\end{equation}
This concludes our analysis of updates \eqref{i:ZETA.update.yw} and \eqref{i:ZETA.update.wy}.\smallskip

\noindent\bemph{Part 5. Effect of update \eqref{i:ZETA.update.x.only}.} It is clear that we will have $\zeta_{3/4}=\zeta$, so it remains to understand the effect of update \eqref{i:ZETA.update.x.only} on the $\sigma$-marginal. 
Note that since the $b$-weights remain the same during update \eqref{i:ZETA.update.x.only}, the conditional probabilities of $\sigma$ given $\varsigma$ remain unchanged between times $t=1/2$ and $t=3/4$. Thus we have
	\[
	\mu_{3/4}(\sigma=\SSPIN{y}\SSPIN{y})
	= \sum_{\vartheta\in\set{\SSPIN{y},\SSPIN{w}}^2}
	\mu_{3/4}(\varsigma=\vartheta)
	\mu_{1/2}(\sigma=\SSPIN{y}\SSPIN{y}\,|\,\varsigma=\vartheta)
	= \mu_{1/2}(\sigma=\SSPIN{y}\SSPIN{y})
	+ k^{O(1)} \hat{\iota}\delta\,,
	\]
where the last estimate uses
\eqref{e:ZETA.yw.error.after.four.updates}, 
\eqref{e:ZETA.rycsq.error.after.four.updates},
and \eqref{e:ZETA.varsigma.ww.zeta.error}. The analogous bound holds for $\set{\sigma=\vartheta}$ for each $\vartheta\in\set{\SSPIN{y},\SSPIN{c}}^2$. Similarly we also have
	\[\mu_{3/4}(\sigma=\SSPIN{r}\SSPIN{y})
	=\Bigg\{ \mu_{3/4}(\varsigma=\SSPIN{r}\SSPIN{w})
	\mu_{1/2}\Big(\sigma=\SSPIN{r}\SSPIN{y}\,\Big|\,\varsigma=\SSPIN{r}\SSPIN{w}\Big)\Bigg\}
	+ \mu_{3/4}(\varsigma=\SSPIN{r}\SSPIN{y})
	\stackrel{\eqref{e:ZETA.varsigma.rw.zeta.error}}{=}
	\mu_{3/4}(\sigma=\SSPIN{r}\SSPIN{y})
	+ k^{O(1)}\hat{\iota}\delta\,,\]
and the analogous bound holds for all $\sigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$ with $\SSPIN{r}[\sigma]=1$.
Lastly, for the case $\sigma=\SSPIN{r}\SSPIN{r}$, we note that
	\[
	\frac{\mu_{3/4}(\sigma=\SSPIN{r}\SSPIN{r})}
		{\mu_{1/2}(\sigma=\SSPIN{r}\SSPIN{r})}
	= \frac{\mu_{3/4}(\varsigma=\SSPIN{r}\SSPIN{r})}
		{\mu_0(\varsigma=\SSPIN{r}\SSPIN{r})}
	=\frac{\zeta(\SSPIN{r}\SSPIN{r})}
		{\zeta_0(\SSPIN{r}\SSPIN{r})}
	\stackrel{\eqref{e:ZETA.delta.error.mult.rr}}{=}
	 1 + O(\ddot{\delta})\,.
	\]
Combining the above estimates with 
\eqref{e:ZETA.mu.zero.estimates} and 
\eqref{e:ZETA.crelerr.a.b} gives
	\[
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\omega_0,\omega_{3/4})
	\le
	k^{O(1)} \begin{pmatrix}
	\hat{\iota} & 0 \\ 2^k\hat{\iota}&0 \\ 1&1
	\end{pmatrix}
	\begin{pmatrix} \delta \\ \ddot{\delta}
		\end{pmatrix} \,.
	\]
This can be translated to a similar error bound for the clause-to-variable messages via the relation
	\[
	\hat{q}_t(\sigma)
	=\frac{ \omega_t(\sigma)/\dot{q}(\sigma)}
		{\sum_{\sigma'}
		\omega_t(\sigma')/\dot{q}(\sigma')}\,.
	\]
The claimed result follows.

\label{p:DIVERSE.VAR}
For any $\epsilon_\infty>0$ there exists $k_0<\infty$ large enough (depending only on $\epsilon_\infty$) such that the following holds for all $k\ge k_0$. Suppose $v$ is a non-defective variable such that (in the notation of Lemma~\ref{l:large11Case})
	\begin{equation}\label{e:assumption.notD.notL}
	\max\Big\{\cancel{\mathbb{D}}(v),
		\cancel{\mathbb{L}}(v)\Big\}
		\le \frac{2^k}{2^{k\epsilon_\infty}}\,.
	\end{equation}
Then $v$ is diverse (Definition~\ref{d:diverse}), and furthermore $\pi_v$ satisfies the estimate
	\begin{equation}\label{eq:diverseVariableCondition}
	\max\Bigg\{\bigg|\pi_v(x)-\frac14\bigg|
	: x\in\set{\SPIN{-},\SPIN{+}}^2
	\Bigg\}\le\frac1{100}\,.\end{equation}

\begin{proof} Without loss of generality we can assume that $\epsilon_\infty$ is much smaller than the other constants 
$\epsilon_1,\epsilon_2,\epsilon_3,\epsilon_4,\epsilon_\circ$ appearing in this section.

We will prove the result by contradiction, so let $v$ be a variable of type $\bm{T}$ which satisfies the conditions of the proposition, but for which the estimate~\eqref{eq:diverseVariableCondition} fails to hold. It will be used repeatedly in the proof that since $v$ is non-defective (Definition~\ref{d:j.defective}), it must be nice, and all clause types neighboring to $v$ must also be nice (Definition~\ref{d:nice}). As in \eqref{e:uX.notation} and \eqref{e:cal.X} we let $X_e\equiv(\sigma_e,\varsigma_e)$. We also denote $\mathcal{X}_e\equiv(X_e,\bm{L}_e)$. We consider the law $\mathbf{P}$ of the random variable 
	\[
	\mathcal{X} \equiv \mathcal{X}_v \equiv (\mathcal{X}_e)_{e\in\delta v}
	\equiv (\smash{\vec{X}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	\equiv\bigg((X_e)_{e\in\delta v}, 
	(\bm{L}_e)_{e\in\delta v}\bigg)\,.\]
The measure $\mathbf{P}$ must maximize entropy subject to the following constraints (cf.\ \eqref{e:final.D.L.clause}--\eqref{e:final.D.L.varsigma}):
for all $e\in\delta v$, 
	{\setlength{\jot}{0pt}\begin{alignat}{2}
	\mathbf{P}(\bm{L}_e=\bm{L})
	&=\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
	\quad&&\textup{for all $\bm{L}$,}
	\label{e:D.L.diverse.clause} \\ 
	\mathbf{P}(\sigma^i_e=\sigma^i \,|\,
		\bm{L}_e=\bm{L})
	&= {}_\star\hspace{-1pt}\pi_e(\sigma^i)
	\quad&&\textup{for all $\bm{L}$ and
		 all $\sigma^i\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$,}
	\label{e:D.L.diverse.judicious} \\
	\mathbf{P}(\varsigma_e=\varsigma
		\,|\,\bm{L}_e=\bm{L})
	&=\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	\quad&&\textup{for all $\bm{L}$
		and all $\varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2$.}
	\label{e:D.L.diverse.varsigma}
	\end{alignat}}
Via a series of transformations of the measure $\mathbf{P}$ we will construct another distribution $\mathbf{P}^f$ satisfying the same constraints
\eqref{e:D.L.diverse.clause}--\eqref{e:D.L.diverse.varsigma} but with higher entropy, yielding the required contradiction. The remainder of the proof is outlined as follows:
\begin{enumerate}[--]
\item In \hyperlink{l:DIVERSE.product.Pa}{Part 1}
we define a measure $\mathbf{P}^a$ satisfying
constraints \eqref{e:D.L.diverse.clause}, \eqref{e:D.L.diverse.judicious}, and 
\eqref{eq:relaxedZetaConstraint}, where
\eqref{eq:relaxedZetaConstraint} is a relaxation of
\eqref{e:D.L.diverse.varsigma}. We show that $\mathbf{P}^a$ has a simple explicit form, and has substantially larger entropy than $\mathbf{P}$ (see \eqref{e:rel.ent.diverse.absolute.lbd} below).


\item In \hyperlink{l:DIDERSE.Pa.bounds}{Part 2} we prove probabilistic estimates on various quantities under the measure $\mathbf{P}^a$. Let $\mathcal{X}^a$ denote a sample from $\mathbf{P}^a$; in the rest of the proof we transform $\mathcal{X}^a$ without changing its frozen spin $x=x^a\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$.

\item In \hyperlink{l:DIVERSE.Pb}{Part 3} we transform $\mathcal{X}^a$ into $\mathcal{X}^b$, and in \hyperlink{l:DIVERSE.Pc}{Part 4} we transform $\mathcal{X}^b$ into $\mathcal{X}^c$. In these transformations, $(\varsigma_e)^i$ can only change between \SPIN{red} and \SPIN{white}, so any $(\varsigma_e)^i\in\set{\SSPIN{y},\SSPIN{c}}$ remains unchanged. The transformations combined will guarantee (see \eqref{e:DIVERSE.hat.E.nonempty} below) that in the configuration $\mathcal{X}^c$, if $x=x^c$ has $x^i=z\in\set{\SPIN{-},\SPIN{+}}$, then some $e\in\delta v(z)$ will have $(\sigma^{c,i})_e=\SSPIN{r}$, $(\sigma^c)_e\ne\SSPIN{r}\SSPIN{r}$, and $(\bm{L}^c)_e\in\mathbb{D}\cap\mathbb{L}$. The condition \eqref{e:DIVERSE.hat.E.nonempty} will allow more flexibility to change spins from non-\SPIN{white} to \SPIN{white} in the following step. The law $\mathbf{P}^c$ of $\mathcal{X}^c$ satisfies
\eqref{e:D.L.diverse.clause}, but need not satisfy
\eqref{e:D.L.diverse.judicious} or \eqref{e:D.L.diverse.varsigma}, in particular, it can have less than the correct density of \SPIN{red} spins (see \eqref{eq:Xc.red.marginal.div}
and \eqref{eq:Xc.red.marginal.div2}).

\item In \hyperlink{l:DIVERSE.Pd}{Part 5} we transform $\mathcal{X}^c$ to $\mathcal{X}^d$ by changing $(\varsigma^{c,i})_e\ne\SSPIN{w}$ to $(\varsigma^{d,i})_e=\SSPIN{w}$ in some cases --- the condition \eqref{e:DIVERSE.hat.E.nonempty} from the previous step allows more flexibility to do this without invalidating the configuration. The goal of this step is to create enough \SPIN{white} spins which can be altered in the next step to ensure that the constraints \eqref{e:D.L.diverse.judicious} or \eqref{e:D.L.diverse.varsigma} will be satisfied.
At the same time, we cannot change too many spins to \SPIN{white}, since this could result in too much decrease in entropy.

\item In \hyperlink{l:DIVERSE.Pe}{Part 6} we transform
$\mathcal{X}^d$ to $\mathcal{X}^f$, where we use $\mathcal{X}^f$ rather than $\mathcal{X}^e$ to avoid confusion with edge labels $e\in\delta v$. In this final step we change
 $(\varsigma^{d,i})_e=\SSPIN{w}$
to $(\varsigma^{f,i})_e\ne\SSPIN{w}$ in some cases, such that the law $\mathbf{P}^f$ of $\mathcal{X}^f$ satisfies the original constraints
\eqref{e:D.L.diverse.clause}--\eqref{e:D.L.diverse.varsigma}
(see \eqref{e:DIVERSE.final.msr.sat.varsigma} below).
Finally we show that $\mathbf{P}^f$ does not have much smaller entropy than $\mathbf{P}^a$, and as a result must have substantially larger entropy than $\mathbf{P}$, giving the contradiction.
\end{enumerate}
We now turn to the details of the transformation.\smallskip




\noindent\bemph{\hypertarget{l:DIVERSE.product.Pa}{Part 1}. Product solution $\mathbf{P}^a$ for relaxed constraints.} Let $\mathbf{P}^a$ be the probability measure over configurations $\mathcal{X}$ which maximizes entropy subject to the constraints \eqref{e:D.L.diverse.clause}, \eqref{e:D.L.diverse.judicious}, and (in place of \eqref{e:D.L.diverse.varsigma})
	\begin{equation}\label{eq:relaxedZetaConstraint}
	\mathbf{P}^a(\varsigma_e^i=\varsigma^i
			\,|\,\bm{L}_e=\bm{L})
		=\bm{\zeta}_e(\varsigma^i\,|\,\bm{L})
		\quad\textup{for all $\bm{L}$
			and all
			$\varsigma^i\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}$.}
	\end{equation}
Let us note that the law $\mathbf{P}^a$ has a quite simple form: by the method of Lagrange multipliers, it must be expressible as
(cf.\ \eqref{e:final.D.L.Lagrangian.form})
	\begin{equation}\label{e:DIVERSE.P.a.Lagrangian.form}
	\mathbf{P}^a\Big(
	\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\varsigma}}_{\delta v},
	\smash{\vec{\bm{L}}}_{\delta v} \Big)
	\cong \psi_v(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e\in\delta v}
	\Bigg\{
	\Ind{\sigma_e\sim\varsigma_e}
	\psi_e(\bm{L}_e)
	\prod_{i=1,2}
	\bigg[
	(\beta_e)^i((\sigma_e)^i\,|\,\bm{L}_e)
	(\chi_e)^i( (\varsigma_e)^i\,|\,\bm{L}_e)
	\bigg]
	\Bigg\}\,,
	\end{equation}
where $\psi_v(\smash{\vec{\sigma}}_{\delta v})$ is parametrized as in
\eqref{e:non.compound.weight.functional.form} from Definition~\ref{d:param.weights.Augmented}. A valid solution is given by simply setting $\psi_v\equiv1$,
$\psi_e(\bm{L})=\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)$,
and (cf.\ \eqref{e:ZETA.bstar} and \eqref{e:ZETA.xstar})
	\begin{align*}
	\begin{pmatrix}
	(\beta_e)^i(\SSPIN{r}\,|\,\bm{L})\\
	(\beta_e)^i(\SSPIN{y}\,|\,\bm{L})\\
	(\beta_e)^i(\SSPIN{g}\,|\,\bm{L})
	=(\beta_e)^i(\SSPIN{b}\,|\,\bm{L})\equiv(\beta_e)^i(\SSPIN{c}\,|\,\bm{L})
	\end{pmatrix}
	&= 
	\begin{pmatrix}
	1\\
	[{}_\star\hspace{-1pt}\pi_e(\SSPIN{y})-(\bm{\zeta}_e)^i(\SSPIN{y}\,|\,\bm{L})]/{}_\star\hspace{-1pt}\dot{q}_e(\SSPIN{y})\\
	[{}_\star\hspace{-1pt}\pi_e(\SSPIN{c})-(\bm{\zeta}_e)^i(\SSPIN{c}\,|\,\bm{L})]/{}_\star\hspace{-1pt}\dot{q}_e(\SSPIN{c})
	\end{pmatrix}
	\stackrel{\eqref{e:ZETA.zetastar}}{=} 
	\begin{pmatrix}
	\Theta(1)\\ \Theta(1) \\ \Theta(1)
	\end{pmatrix}\,,\\

	\begin{pmatrix}
	(\chi_e)^i(\SSPIN{r}\,|\,\bm{L})\\
	(\chi_e)^i(\SSPIN{y}\,|\,\bm{L})\\
	(\chi_e)^i(\SSPIN{c}\,|\,\bm{L})\\
	(\chi_e)^i(\SSPIN{w}\,|\,\bm{L})
	\end{pmatrix}
	&=\begin{pmatrix}
	{}_\star\hspace{-1pt}\pi_e(\SSPIN{r})/{}_\star\hspace{-1pt}\dot{q}_e(\SSPIN{r})\\
	(\bm{\zeta}_e)^i(\SSPIN{y}\,|\,\bm{L})
		/[{}_\star\hspace{-1pt}\pi_e(\SSPIN{y})-(\bm{\zeta}_e)^i(\SSPIN{y}\,|\,\bm{L})]\\
	(\bm{\zeta}_e)^i(\SSPIN{c}\,|\,\bm{L})
	/[{}_\star\hspace{-1pt}\pi_e(\SSPIN{c})
		-(\bm{\zeta}_e)^i(\SSPIN{c}\,|\,\bm{L})]\\
	1
	\end{pmatrix}
	\stackrel{\eqref{e:ZETA.zetastar}}{=} 
	\begin{pmatrix}
	\Theta(1/2^k)\\
	O(k^2/2^k)\\
	O(k^2/2^k)\\
	1
	\end{pmatrix}
	\,,\end{align*}
where the estimates on
$(\bm{\zeta}_e)^i(\tau\,|\,\bm{L})$
for $\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}$ come from Lemma~\ref{l:lotsOfAs}. Note that for $e\in\delta v$, $\bm{L}=\bm{L}_e$, $i=1,2$, and $\sigma^i\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$ we have
	\begin{equation}\label{e:product.zeta.msg.simplification}
	(\hat{q}_e)^i(\sigma^i\,|\,\bm{L})\equiv
	(\beta_e)^i(\sigma^i\,|\,\bm{L})
	\sum_{\varsigma^i}
	\Ind{\varsigma^i \sim \sigma^i}
	(\chi_e)^i(\varsigma^i\,|\,\bm{L})
	= \frac{{}_\star\hspace{-1pt}\pi_e(\sigma^i)}{{}_\star\hspace{-1pt}\dot{q}_e(\sigma^i)}\,,
	\end{equation}
where we emphasize that the right-hand side of \eqref{e:product.zeta.msg.simplification} does not depend on $\bm{L}$. Indeed,
	\[
	(\hat{q}_e)^i(\SSPIN{r}\,|\,\bm{L})
	= (\beta_e)^i(\SSPIN{r}\,|\,\bm{L})
	(\chi_e)^i(\SSPIN{r}\,|\,\bm{L})
	= \frac{{}_\star\hspace{-1pt}\pi_e(\SSPIN{r})}{{}_\star\hspace{-1pt}\dot{q}_e(\SSPIN{r})}\,,
	\]
which verifies \eqref{e:product.zeta.msg.simplification} for the case $\sigma^i=\SSPIN{r}$. Next,
	\begin{align*}
	(\hat{q}_e)^i(\SSPIN{y}\,|\,\bm{L})
	&= (\beta_e)^i(\SSPIN{y}\,|\,\bm{L})
	\bigg(
	(\chi_e)^i(\SSPIN{y}\,|\,\bm{L})
	+(\chi_e)^i(\SSPIN{w}\,|\,\bm{L})\bigg)\\
	&= \frac{{}_\star\hspace{-1pt}\pi_e(\SSPIN{y})-(\bm{\zeta}_e)^i(\SSPIN{y}\,|\,\bm{L})}
		{{}_\star\hspace{-1pt}\dot{q}_e(\SSPIN{y})}
	\cdot\Bigg\{
	\frac{(\bm{\zeta}_e)^i(\SSPIN{y}\,|\,\bm{L})}
		{{}_\star\hspace{-1pt}\pi_e(\SSPIN{y})-(\bm{\zeta}_e)^i(\SSPIN{y}\,|\,\bm{L})}+1
	\Bigg\}
	= \frac{{}_\star\hspace{-1pt}\pi_e(\SSPIN{y})}{{}_\star\hspace{-1pt}\dot{q}_e(\SSPIN{y})}\,,
	\end{align*}
which verifies \eqref{e:product.zeta.msg.simplification} for the case $\sigma^i=\SSPIN{y}$. A similar calculation gives
\eqref{e:product.zeta.msg.simplification} for $\sigma^i\in\set{\SSPIN{g},\SSPIN{b}}$. It follows from \eqref{e:product.zeta.msg.simplification},
together with the identity ${}_\star\hspace{-1pt}\pi_e(\tau)/{}_\star\hspace{-1pt}\dot{q}_e(\tau) \cong {}_\star\hspace{-1pt}\hat{q}_e(\tau)$,
that the marginal of \eqref{e:DIVERSE.P.a.Lagrangian.form} over
$(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})$ is given by
	\begin{align}\nonumber
	\mathbf{P}^a\Big(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v}\Big)
	&\cong
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e\in\delta v}\Bigg\{
	\pi_{\mathscr{D}}(\bm{L}_e\,|\,\bm{t}_e)
	\prod_{i=1,2}
	{}_\star\hspace{-1pt}\hat{q}_e((\sigma_e)^i)\Bigg\} \\
	& \cong
	{}_\star\hspace{-1pt}\dot{\nu}_v((\smash{\vec{\sigma}}_{\delta v})^1)
	{}_\star\hspace{-1pt}\dot{\nu}_v((\smash{\vec{\sigma}}_{\delta v})^2)
	\prod_{e\in\delta v}
	\pi_{\mathscr{D}}(\bm{L}_e\,|\,\bm{t}_e)
	\,,\label{eq:productForm}
	\end{align}
where ${}_\star\hspace{-1pt}\dot{\nu}_v$ is as in 
\eqref{e:opt.variable.tuple.measure.star}. In particular, we see that under $\mathbf{P}^a$,
the random variables $(\smash{\vec{\sigma}}_{\delta v})^1$, $(\smash{\vec{\sigma}}_{\delta v})^2$, and $\smash{\vec{\bm{L}}}_e$ (for $e\in\delta v$) are mutually independent. Moreover, conditional on $(\smash{\vec{\sigma}},\smash{\vec{\bm{L}}})_{\delta v}$, 
the $(\varsigma_e)^i$ are all independent from one another, with conditional laws depending only on
 $(\bm{L}_e,(\sigma_e)^i)$. If $(\sigma_e)^i=\SSPIN{r}$ then $(\varsigma_e)^i= \SSPIN{r} $ also. 
If $(\sigma_e)^i=\SSPIN{y}$ then $(\varsigma_e)^i\in\set{\SSPIN{y},\SSPIN{w}}$; and the conditional probability of 
$(\varsigma_e)^i=\SSPIN{y}$ is given by
	\begin{equation}\label{eq:ColouringProbs.yel}
	\mathbf{P}^a
	\bigg( (\varsigma_e)^i= \SSPIN{y}
	\,\bigg|\,
	\bm{L}_e=\bm{L}, (\sigma_e)^i=\SSPIN{y}
	\bigg)
	= \frac{(\chi_e)^i(\SSPIN{y}\,|\,\bm{L})}
	{(\chi_e)^i(\SSPIN{y}\,|\,\bm{L})+(\chi_e)^i(\SSPIN{w}\,|\,\bm{L})}
	= \frac{(\bm{\zeta}_e)^i(\SSPIN{y}\,|\,\bm{L})}
		{{}_\star\hspace{-1pt}\pi_e(\SSPIN{y})}
	\le O\bigg(\frac{k^2}{2^k}\bigg)\,,
	\end{equation}
where the last inequality follows by
Lemma~\ref{l:lotsOfAs}. Similarly, if $(\sigma_e)^i =\tau\in\set{\SSPIN{g},\SSPIN{b}}$ then
$(\varsigma_e)^i\in\set{\SSPIN{c},\SSPIN{w}}$; and the conditional probability of $(\varsigma_e)^i=\SSPIN{c}$ is given by
	\begin{equation}\label{eq:ColouringProbs.cya}
	\mathbf{P}^a
	\bigg( (\varsigma_e)^i=\SSPIN{c}
	\,\bigg|\,
	\bm{L}_e=\bm{L}, (\sigma_e)^i=\tau
	\bigg)
	= \frac{(\bm{\zeta}_e)^i(\SSPIN{c}\,|\,\bm{L})}
		{{}_\star\hspace{-1pt}\pi_e(\SSPIN{b})+{}_\star\hspace{-1pt}\pi_e(\SSPIN{g})}
	\le O\bigg(\frac{k^2}{2^k}\bigg)
	\end{equation}
for $\tau\in\set{\SSPIN{g},\SSPIN{b}}$. The independence between the two copies $i=1,2$ gives furthermore
	\begin{equation}\label{e:DIVERSE.Pa.RYCsq}
	\mathbf{P}^a\bigg(\varsigma_e\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	= \prod_{i=1}^2 \mathbf{P}^a\bigg(
		(\varsigma_e)^i\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg) 
	\le O\bigg( \frac{k^4}{4^k}\bigg)\,.
	\end{equation}
Note also that if $x=x_v\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$ is the frozen spin, then $x^1$ and $x^2$ are independent under $\mathbf{P}^a$, and the marginal law of each $x^i$ is determined by the ${}_\star\hspace{-1pt}\pi_e$ for $e\in\delta v$.
Since we assumed that $v$ is non-defective, it follows that
	\begin{equation}\label{eq:diverseVariableCondition.a}
	\max\Bigg\{
	\bigg|\mathbf{P}^a\Big( x =z \Big)
		 -\frac14\bigg|
		: z\in\set{\SPIN{-},\SPIN{+}}^2
		\Bigg\} =o_k(1)\,.
	\end{equation}
If $\mathbf{P}'$ is any other probability measure satisfying the same constraints as $\mathbf{P}^a$ (namely \eqref{e:D.L.diverse.clause}, \eqref{e:D.L.diverse.judicious}, and \eqref{eq:relaxedZetaConstraint}), then
it follows by the same derivation as
for \eqref{e:relative.entropy.with.Lagrangian} that
the relative entropy between $\mathbf{P}'$ and $\mathbf{P}^a$ 
satisfies
	\begin{equation}\label{e:relent.a.b.transform}
	\mathcal{H}(\mathbf{P}'\,|\,\mathbf{P}^a)
	= \bigg\langle \mathbf{P}',\ln \frac{\mathbf{P}'}{\mathbf{P}^a}
		\bigg\rangle
	=\mathcal{H}(\mathbf{P}^a) -\mathcal{H}(\mathbf{P}')\,.
	\end{equation}
Now suppose that $x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$ is the frozen spin corresponding to $\mathcal{X}\sim\mathbf{P}$ (meaning that its law fails condition \eqref{eq:diverseVariableCondition}), while $x^a\equiv(x^{a,1},x^{a,2})\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$ is the frozen spin corresponding to $\mathcal{X}^a\sim\mathbf{P}^a$ (so that its law satisfies condition 
\eqref{eq:diverseVariableCondition.a}). Therefore we obtain
	\begin{equation}\label{e:rel.ent.diverse.absolute.lbd}
	\mathcal{H}(\mathbf{P}\,|\,\mathbf{P}^a) \ge
	\mathcal{D}_\textup{KL}(x\,|\,x^a)
	\ge \frac1{10^6}\,.
	\end{equation}
It follows by combining the last few calculations that
	\begin{equation}\label{eq:a.opt.EntComp}
	\mathcal{H}(\mathbf{P}^a)
	\stackrel{\eqref{e:relent.a.b.transform}}{=}
	\mathcal{H}(\mathbf{P})
	+\mathcal{H}(\mathbf{P}\,|\,\mathbf{P}^a)
	\stackrel{\eqref{e:rel.ent.diverse.absolute.lbd}}{\ge}
	\mathcal{H}(\mathbf{P})
	+\frac1{10^6}\,.
	\end{equation}
In the remainder of the proof we will make a sequence of transformations, from $\mathbf{P}^a$ to $\mathbf{P}^b$ and so on, until we arrive at a measure
$\mathbf{P}^f$ that satisfies the original constraints \eqref{e:D.L.diverse.clause}--\eqref{e:D.L.diverse.varsigma}. We will show that
none of the transformations substantially reduce the entropy. Thus the final measure $\mathbf{P}^f$
will have similar entropy as $\mathbf{P}^a$, and hence will have greater entropy than $\mathbf{P}$ by \eqref{e:rel.ent.diverse.absolute.lbd}. But we assumed $\mathbf{P}$ to be the measure of maximal entropy satisfying constraints \eqref{e:D.L.diverse.clause}--\eqref{e:D.L.diverse.varsigma}, so this will give the desired contradiction. The measures $\mathbf{P}^a$ through $\mathbf{P}^f$ will all be coupled together, and the frozen spin $x$ will be left unchanged throughout the transformations.\smallskip

\noindent\bemph{\hypertarget{l:DIDERSE.Pa.bounds}{Part 2}. Bounds on $\mathbf{P}^a$.} Using the assumed bound \eqref{e:assumption.notD.notL} on $\cancel{\mathbb{D}}(v)$ and $\cancel{\mathbb{L}}(v)$, we can select a subset of four distinct edges incident to $v$,
	\begin{equation}\label{e:four.distinct.edges}
	\bm{E}\equiv
	\bigg\{e^{\SPIN{+},1},e^{\SPIN{+},2},
	e^{\SPIN{-},1},e^{\SPIN{-},2}\bigg\}
	\subset \delta v\,,\end{equation}
where $e^{\SPIN{+},i}\in\delta v(\SPIN{+})$,
and $e^{\SPIN{-},i}\in\delta v(\SPIN{-})$,
such that each $e\in\bm{E}$ satisfies
	\begin{equation}\label{eq:bEdefin}
	\sum_{\bm{L}}
		\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e) 
		\Ind{\bm{L}\in \mathbb{D}\cap\mathbb{L}}
		\ge\frac12\,.\end{equation}
For a configuration $\mathcal{X}$ as in \eqref{e:cal.X}, we define the following quantities:
	\begin{align*}
\mathfrak{R}^i&\equiv
	\mathfrak{R}^i(\mathcal{X})
	\equiv \sum_{e\in\delta v\setminus \bm{E}}
	\mathbf{1}\Big\{
	(\sigma_e)^i=\SSPIN{r}
	\Big\}\,,\\
\mathfrak{H}
	&\equiv\mathfrak{H}(\mathcal{X})
	\equiv\sum_{e\in\delta v\setminus \bm{E}} 
	\sum_{i=1,2}
	\mathbf{1}\Big\{
	(\varsigma_e)^i\in\{\SSPIN{r},\SSPIN{y},\SSPIN{c}\}
	\Big\}\,,\\
	\mathfrak{W}
	&\equiv \mathfrak{W}(\mathcal{X})
	\equiv\sum_{e\in\delta v\setminus \bm{E}} 
		\mathbf{1}\Big\{
		\varsigma_e=\SSPIN{w}\SSPIN{w},
		\bm{L}_e \in \mathbb{D}\cap\mathbb{L}
		\Big\}\,,\\
	T&\equiv T(\mathcal{X})
		\equiv\mathbf{1}
		\bigg\{\mathfrak{W}(\mathcal{X})
			\le \bigg(1-\frac1{k^{10}}\bigg)
				|\delta v|\bigg\}\,.
	\end{align*}
We now prove some straightforward probabilistic bounds (under the measure $\mathbf{P}^a$) for the above quantities. For $e\in\delta v$ let $R_e$ denote independent Bernoulli random variables with
	\begin{equation}\label{e:DIVERSE.Re}
	\mathbb{P}(R_e=1) 
	= \frac{{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{r})}{{}_\star\hspace{-1pt}\hat{q}_e(\set{\SSPIN{r},\SSPIN{b}})}
	= \Theta\bigg(\frac1{2^k}\bigg)\,.\end{equation}
We see from \eqref{eq:productForm} that under $\mathbf{P}^a(\cdot\,|\,x^i=\SPIN{+})$, the total number of edges $e\in\delta v$ with $(\sigma_e)^i=\SSPIN{r}$ is equidistributed as the sum of $R_e$ over $e\in\delta v(\SPIN{+})$, conditioned on that sum being strictly positive. Therefore
	\begin{align}\nonumber
	\mathbf{P}^a\Bigg(
		\sum_{i=1,2}\mathfrak{R}^i\ge
		\frac{k^3}{2} \Bigg)
	&\le \mathbf{P}^a \Bigg(
	\sum_{i=1,2}
	\sum_{e\in\delta v} \Ind{(\sigma_e)^i=\SSPIN{r}}
	\ge \frac{k^3}{2} \Bigg)
	\le O(1)\max_{z\in\set{\SPIN{-},\SPIN{+}}}
	\Bigg\{
	\frac{\mathbb{P}( \sum_{e\in\delta v(z)} R_e \ge k^3/4)}
		{\mathbb{P}(\sum_{e\in\delta v(z)} R_e \ge1)}
		\Bigg\}\\
	&\le\frac{\exp(-\Omega(k^3\ln k))
	}{1-o_k(1)}
	\le \frac1{\exp(\Omega(k^3\ln k))}\,,
	\label{eq:frakR.bound}
	\end{align}
where the second-to-last inequality follows by a Chernoff bound. Next recall from \eqref{eq:ColouringProbs.yel} and 
\eqref{eq:ColouringProbs.cya} that
under $\mathbf{P}^a$, conditional on 
$(\sigma_e)^i\in\set{\SSPIN{y},\SSPIN{g},\SSPIN{b}}$, the chance for $(\varsigma_e)^i\in\set{\SSPIN{y},\SSPIN{c}}$
is $O(k^2/2^k)$. Thus, under $\mathbf{P}^a$,
the total number of edges $e$ with $(\varsigma_e)^i\in\set{\SSPIN{y},\SSPIN{c}}$ for either $i=1,2$ is stochastically dominated by a binomial random variable with $\Theta(k2^k)$ trials
and success probability $\Theta(1/2^k)$. It follows by another Chernoff bound, and by combining with \eqref{eq:frakR.bound}, that
	\begin{equation}\label{e:frakH.bound}
	\mathbf{P}^a\Big(\mathfrak{H} \ge k^3\Big)
	\le \mathbf{P}^a\Bigg(
		\sum_{e\in\delta v}\sum_{i=1,2}
		\mathbf{1}\Big\{
		(\varsigma_e)^i\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}
		\Big\} \ge k^3
		\Bigg)
	\le\frac1{\exp(\Omega(k^3\ln k))}\,.\end{equation}
Next recall from \eqref{eq:productForm}
that the $\bm{L}_e$ for $e\in\delta v$ are mutually independent under $\mathbf{P}^a$. The assumption \eqref{e:assumption.notD.notL} bounds the expected number (under $\mathbf{P}^a$) of edges $e\in\delta v$ with $\bm{L}_e\notin\mathbb{D}\cap\mathbb{L}$. It follows by Azuma's inequality that
	\begin{equation}\label{eq:nonDiverseLightBound}
	\mathbf{P}^a
	\Bigg(\sum_{e\in\delta v}
	\Ind{\bm{L}_e\notin\mathbb{D}\cap\mathbb{L}}
	\ge \frac{k2^k}{2^{k\epsilon_\infty}} \Bigg)
	\le 
	\frac1{\exp (\Omega(2^{k(1-2\epsilon_\infty)}k))}\,.\end{equation}
Combining with \eqref{e:frakH.bound}, 
and recalling the definitions of $\mathfrak{W}$ and $T$, we obtain
	\begin{align}\nonumber
	\mathbf{P}^a(T=1) &=
	\mathbf{P}^a\Bigg(\mathfrak{W}
		\le \bigg(1-\frac1{k^{10}}\bigg)
		|\delta v|
		 \Bigg)\\
	&\le
	\mathbf{P}^a
	\Bigg(
	\max\bigg\{ \mathfrak{H} 
	,\sum_{e\in\delta v}
	\Ind{\bm{L}_e\notin\mathbb{D}\cap\mathbb{L}}
	\bigg\} \ge
	\frac{|\delta v|}{3k^{10}}\Bigg)
	\le \frac1{\exp(\Omega(k^3\ln k))}\,.
	\label{eq:T2Bound}
	\end{align}
Recall from \eqref{e:four.distinct.edges} the choice of four distinct edges $\bm{E}$ from $\delta v$. 
For each $e\in\bm{E}$ define
	\begin{equation}\label{e:DIVERSE.Gm}
	\Gamma(e)\equiv 
	\begin{cases}
	1&\textup{if $T(\mathcal{X}^a)=1$, 
		$e=e^{\SPIN{+},i}$, and $x^{a,i}=\SPIN{+}$,}\\
	1&\textup{if $T(\mathcal{X}^a)=1$, 
		$e=e^{\SPIN{-},i}$, and $x^{a,i}=\SPIN{-}$,}\\
	0&\textup{otherwise.}
	\end{cases}\end{equation}
In the first transformation (described below), given $\mathcal{X}^a$ we will construct a modified configuration $\mathcal{X}^b$ in which $(\sigma_e)^i=\SSPIN{r}$ and $\bm{L}_e\in\mathbb{D}\cap\mathbb{L}$ whenever 
$e=e^{\SPIN{\textpm},i}$ with $\Gamma(e)=1$. (This ensures that a frozen spin $x^i\in\set{\SPIN{-},\SPIN{+}}$ has at least one incident $\SPIN{red}$ edge in $\delta v(x^i)$, and gives more flexibility to adjust the colors on the other incident edges.) For $e\in\bm{E}$ and $z\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$ define
	\begin{equation}\label{e:DIVERSE.p.z.e.ubd}
	p_z(e)
	\equiv\mathbf{P}^a(\Gamma(e)=1,x=z)
	\le \mathbf{P}^a(T=1)
	\stackrel{\eqref{eq:T2Bound}}{\le}
	\frac{1}{\exp(\Omega(k^3\ln k))}\,.
	\end{equation}
Note the definition of $\Gamma(e)$ implies
$p_z(e^{\SPIN{+},i})=0$ if $z^i\ne\SPIN{+}$, and likewise
$p_z(e^{\SPIN{-},i})=0$ if $z^i\ne\SPIN{-}$. For $e\in\bm{E}$ we also let
	\[r_z(e)
	\equiv
	\mathbf{P}^a\bigg(
	\bm{L}_e\in\mathbb{D}\cap\mathbb{L},
	x=z,(\sigma_e)^i=\SSPIN{r},\sigma_e\ne\SSPIN{r}\SSPIN{r},
	\mathfrak{R}^i\ge2, T=0
	\bigg)\,.
	\]
Note having $(\sigma_e)^i=\SSPIN{r}$ necessitates $x^i=\SPIN{+}$, so 
$r_z(e^{\SPIN{+},i})=0$ if $z^i\ne\SPIN{+}$
and $r_z(e^{\SPIN{-},i})=0$ if $z^i\ne\SPIN{-}$. In all other cases we claim that $r_z(e)\ge \Omega(1)/4^k$. Without loss of generality it suffices to consider the case $e=e^{\SPIN{+},1}$ and $z\in\set{\SPIN{+}}\times\set{\SPIN{-},\SPIN{+},\SPIN{f}}$. In this case, recalling the bound
\eqref{eq:T2Bound} gives
	\[
	r_z(e)
	\ge
	\mathbf{P}^a\bigg(
	\bm{L}_e\in\mathbb{D}\cap\mathbb{L},
	x^2=z^2,\sigma_e\in\set{\SSPIN{r}}
		\times\set{\SSPIN{y},\SSPIN{g},\SSPIN{b}},
		\mathfrak{R}^i\ge2
	\bigg)
	-\frac1{\exp(\Omega(k^3\ln k))}\,.\]
Next recall from \eqref{eq:productForm} that $(\smash{\vec{\sigma}}_{\delta v})^1$, $(\smash{\vec{\sigma}}_{\delta v})^2$, and $\bm{L}_e$ ($e\in\delta v$) are mutually independent under $\mathbf{P}^a$. It follows by straightforward calculations that for any $\bm{L}$ we have
	\[
	\mathbf{P}^a\bigg(
	\mathfrak{R}^i\ge2
	\,\bigg|\,\bm{L}_e=\bm{L},
	x^2=z^2,\sigma_e\in\set{\SSPIN{r}}
		\times\set{\SSPIN{y},\SSPIN{g},\SSPIN{b}}\bigg)
	\ge 1-o_k(1)\,.
	\]
Combining with \eqref{eq:bEdefin} gives
	\begin{equation}\label{eq:rzBound}
	r_z(e)
	\ge
	\frac{1-o_k(1)}{2}
	\mathbf{P}^a\bigg(
	(\sigma_e)^1=\SSPIN{r}
	\bigg)
	\mathbf{P}^a\bigg(x^2=z^2,
	(\sigma_e)^2\ne\SSPIN{r}
	\bigg)-\frac1{\exp(\Omega(k^3\ln k))}
	\ge \frac{\Omega(1)}{4^k}\,,\end{equation}
as claimed. It follows by comparing \eqref{e:DIVERSE.p.z.e.ubd} with \eqref{eq:rzBound} that $p_z(e)/r_z(e)=o_k(1)$. For $e\in\bm{E}$,
we define Bernoulli random variables $\Xi(e)$ such that if $r_z(e)=0$ then $\Xi(e)\equiv0$, and otherwise if $e=e^{\SPIN{\textpm},i}$ with $r_z(e)>0$ then
	\begin{equation}\label{e:DIVERSE.def.Xi}
	\mathbf{P}^a\bigg(
	\Xi(e) = 1 \,\bigg|\, x=z,
		\mathcal{X}^a=\mathcal{X}\bigg)
	= \frac{p_z(e)}{r_z(e)}
	\mathbf{1}\bigg\{
	\bm{L}_e \in \mathbb{D}\cap \mathbb{L}, x=z,
	(\sigma_e)^i=\SSPIN{r},
	\sigma_e\ne\SSPIN{r}\SSPIN{r}, 
	\mathfrak{R}^i\geq 2,T=0
	\bigg\}\end{equation}
(for all possible values of $z,\mathcal{X}$). It then follows from the definition of $r_z(e)$ that for all $z\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$ we have
	\begin{equation}\label{eq:GammaXiEquality2}
	\mathbf{P}^a\bigg(
	\Xi(e) = 1,x=z\bigg)
	=p_z(e) =\mathbf{P}^a\bigg(
	\Gamma(e) = 1,x=z\bigg)\,,\end{equation}
and consequently $\mathbf{P}^a(\Xi(e) = 1)=\mathbf{P}^a(\Gamma(e) = 1)$. Further, by the independence properties of $\mathbf{P}^a$ that we see from the expression \eqref{eq:productForm}, we have
	\begin{equation}\label{eq:cond.L.Xi}
	\mathbf{P}^a\Bigg(
		\bm{L}_e=\bm{L}
		\,\Bigg|\, \Xi(e) = 1, \Big(\sigma_e,
			\big(\sigma_{e'},\varsigma_{e'},\bm{L}_{e'}\big)_{e'\in
				\delta v\setminus e}\Big)
				\Bigg)
	= \pi_{\mathscr{D}}\Big(\bm{L}\,
		\Big|\,\bm{t}_e, \bm{L}_e \in \mathbb{D}\cap \mathbb{L}
		\Big)\,.\end{equation}
This concludes our estimates on $\mathbf{P}^a$, and we now turn to the construction of $\mathbf{P}^b$.\smallskip

\noindent\bemph{\hypertarget{l:DIVERSE.Pb}{Part 3}. Construction of $\mathbf{P}^b$.} Recall \eqref{e:four.distinct.edges} that $\bm{E}$ is a subset of four distinct edges in $\delta v$. In the above we defined Bernoulli random variables $\Gamma(e)$ and $\Xi(e)$ for $e\in\bm{E}$. Recall moreover that $\Gamma(e)=1$ can only occur on the event $T=T(\mathcal{X}^a)=1$, while $\Xi(e)=1$ can only occur on the event $T=T(\mathcal{X}^a)=0$, so in particular we can never have $\Gamma(e)=\Xi(e)=1$. In the construction we will essentially ``swap'' the events $\Gamma(e)=1$ and $\Xi(e)=1$.
To make this precise, recall that we write $\mathcal{X}_e\equiv(\sigma_e,\varsigma_e,\bm{L}_e)$. Given $\mathcal{X}^a\sim\mathbf{P}^a$, we let $\mathcal{X}^b$ be defined as follows:
\begin{enumerate}[--]
\item If $e\in\delta v\setminus\bm{E}$ then set $(\mathcal{X}^b)_e=(\mathcal{X}^a)_e$.
\item If $e\in\bm{E}$ with $\Gamma(e)=\Xi(e)=0$ then we also set $(\mathcal{X}^b)_e=(\mathcal{X}^a)_e$.
\item If $e\in\bm{E}$ with $\Gamma(e)=1$ (hence $\Xi(e)=0$),
and $x_v=z$, then we let $(\mathcal{X}^b)_e$ be sampled from the law
	\begin{equation}\label{e:swap.Gamma.Xi.1}
	\mathbf{P}^b\bigg(\mathcal{X}_e\in\cdot \,\bigg|\, x_v=z,\Gamma(e)=1\bigg)
	=\mathbf{P}^a\bigg(\mathcal{X}_e\in\cdot \,\bigg|\, x_v=z,\Xi(e)=1\bigg)\,.
	\end{equation}
\item If $e\in\bm{E}$ with $\Xi(e)=1$ (hence $\Gamma(e)=0$),
and $x_v=z$, then we let 
$(\mathcal{X}^b)_e$ be sampled from the law
	\begin{equation}\label{e:swap.Gamma.Xi.2}
	\mathbf{P}^b\bigg(\mathcal{X}_e\in\cdot \,\bigg|\, x_v=z,\Xi(e)=1\bigg)
	=\mathbf{P}^a\bigg(\mathcal{X}_e\in\cdot \,\bigg|\, x_v=z,\Gamma(e)=1\bigg)\,.
	\end{equation}
\end{enumerate}
This results in a valid configuration $\mathcal{X}^b$ which has the same frozen spin as $\mathcal{X}^a$, that is, $x^a=x^b\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$. For the sake of concreteness, we give two examples of the above construction:
\begin{enumerate}[(a)]
\item \textit{Example on event $T=1$.} Suppose we have $\mathcal{X}^a\sim\mathbf{P}^a$ with frozen spin $x^a=\SPIN{+}\SPIN{+}$, such that $T=T(\mathcal{X}^a)=1$. In this case it follows from the definition \eqref{e:DIVERSE.Gm} of $\Gamma(e)$ that $\Gamma(e^{\SPIN{+},1})=\Gamma(e^{\SPIN{+},2})=1$. Since $x^a=\SPIN{+}\SPIN{+}$, we must have $(\sigma^a)_e\in\set{\SSPIN{r},\SSPIN{b}}^2$ for $e\in\set{e^{\SPIN{+},1},e^{\SPIN{+},2}}$. The resampling step \eqref{e:swap.Gamma.Xi.1} results in a modified configuration $\mathcal{X}^b$. It follows from the definition \eqref{e:DIVERSE.def.Xi} of $\Xi(e)$ that in the modified configuration,
	{\setlength{\jot}{0pt}\begin{align*}
	&\textup{$(\sigma^b)_e=\SSPIN{r}\SSPIN{b}$ for $e = e^{\SPIN{+},1}$,}\\
	&\textup{$(\sigma^b)_e=\SSPIN{b}\SSPIN{r}$ for $e = e^{\SPIN{+},2}$.}
	\end{align*}}
Thus, for $e=e^{\SPIN{\textpm},i}$ with $\Gamma(e)=1$,
the procedure \eqref{e:swap.Gamma.Xi.1} makes
$(\sigma_e)^i$ marginally more likely to be $\SPIN{red}$,
but makes $\sigma_e$ less likely to be $\SSPIN{r}\SSPIN{r}$.

\item \textit{Example on event $T=0$.} 
Suppose we have $\mathcal{X}^a\sim\mathbf{P}^a$ with frozen spin $x^a=\SPIN{+}\SPIN{+}$, such that $T=T(\mathcal{X}^a)=0$. Recalling \eqref{e:DIVERSE.def.Xi}, suppose that we have $\Xi(e^{\SPIN{+},1})=1$
while $\Xi(e^{\SPIN{+},2})=0$. In particular, this means for $e=e^{\SPIN{+},1}$ we must have $(\sigma^a)_e=\SSPIN{r}\SSPIN{b}$. The resampling step \eqref{e:swap.Gamma.Xi.2} results in a modified configuration $\mathcal{X}^b$. It follows from the definition \eqref{e:DIVERSE.Gm} of $\Gamma(e)$ that in the modified configuration we must have $(\sigma^b)_e \in \set{\SSPIN{r},\SSPIN{b}}^2$
for $e=e^{\SPIN{+},1}$. Thus, for $e=e^{\SPIN{\textpm},i}$ with $\Xi(e)=1$,
the procedure \eqref{e:swap.Gamma.Xi.2}
makes $(\sigma_e)^i$ marginally less likely to be $\SPIN{red}$,
but makes $\sigma_e$ more likely to be $\SSPIN{r}\SSPIN{r}$.
\end{enumerate}
We let $\mathbb{P}$ denote the joint law of $(\mathcal{X}^a,\mathcal{X}^b)$, and let $\mathbf{P}^b$ denote the marginal law of $\mathcal{X}^b$. Note that $\mathbf{P}^a$ and $\mathbf{P}^b$ have the same edge marginals: for $e\in\delta v\setminus \bm{E}$ it is clear that $(\mathcal{X}^a)_e$ and $(\mathcal{X}^b)_e$ have the same marginal law, since in the coupling we set $(\mathcal{X}^b)_e=(\mathcal{X}^a)_e$.
For $e\in\bm{E}$, we have
	{\setlength{\jot}{0pt}\begin{align}\nonumber
	&\mathbf{P}^b(\mathcal{X}_e\in\cdot\,|\, x_v=z,
		\Gamma(e)+\Xi(e)=1) \\ \nonumber
	&=\mathbf{P}^a(\Gamma(e)=1\,|\,x_v=z)
	\mathbf{P}^b(\mathcal{X}_e\in\cdot\,|\, x_v=z,\Gamma(e)=1)
	+\mathbf{P}^a(\Xi(e)=1\,|\,x_v=z)
	\mathbf{P}^b(\mathcal{X}_e\in\cdot\,|\, x_v=z,\Xi(e)=1)\\ \nonumber
	&=
	\mathbf{P}^a(\Xi(e)=1\,|\,x_v=z)
	\mathbf{P}^a(\mathcal{X}_e\in\cdot\,|\, x_v=z,\Xi(e)=1)
	+\mathbf{P}^a(\Gamma(e)=1\,|\,x_v=z)
	\mathbf{P}^a(\mathcal{X}_e\in\cdot\,|\, x_v=z,\Gamma(e)=1)\\
	&=\mathbf{P}^a(\mathcal{X}_e\in\cdot\,|\, x_v=z,
		\Gamma(e)+\Xi(e)=1)\,,
	\label{e:DIVERSE.ab.same.mgls}
	\end{align}}
where the transition to the third line uses \eqref{eq:GammaXiEquality2}, \eqref{e:swap.Gamma.Xi.1}, and \eqref{e:swap.Gamma.Xi.2}. This verifies that $\mathbf{P}^b(\mathcal{X}_e\in\cdot)=\mathbf{P}^a(\mathcal{X}_e\in\cdot)$ for all $e\in\delta v$, so the measure $\mathbf{P}^b$ again satisfies the constraints \eqref{e:D.L.diverse.clause}, \eqref{e:D.L.diverse.judicious}, and \eqref{eq:relaxedZetaConstraint}.
We now compare the entropy of $\mathbf{P}^a$ and $\mathbf{P}^b$. As above, denote $T=T(\mathcal{X}^a)$. Write $\bm{E}_a\equiv\set{e\in\bm{E}:\Gamma(e)+\Xi(e)=1}$. Denote $\mathcal{X}\equiv(\mathcal{Y},\mathcal{Z})$ where
	{\setlength{\jot}{0pt}\begin{align*}
	\mathcal{Y}&\equiv (\mathcal{X}_e : e\in\bm{E}_a)\,,\\
	\mathcal{Z}&\equiv (\mathcal{X}_e : e\in\delta v\setminus\bm{E}_a)\,.
	\end{align*}}
If $\bm{E}_a=\varnothing$ then $\mathcal{Y}$ is the null vector. Likewise denote $\smash{\vec{X}}_{\delta v}\equiv (Y,Z)$
where $Y\equiv (X_e:e\in\bm{E}_a)$. We then have
	{\setlength{\jot}{0pt}\begin{align}\nonumber
	\mathcal{H}(\mathcal{X}^b) 
	&\ge\mathcal{H}(T,\bm{E}_a,\mathcal{Z}^b)
		+\mathcal{H}( \mathcal{Y}^b\,|\, T,\bm{E}_a,\mathcal{Z}^b)
		-\mathcal{H}(T)-\mathcal{H}(\bm{E}_a)\\
	&=\mathcal{H}(T,\bm{E}_a,\mathcal{Z}^b)
		+\mathcal{H}( (\smash{\vec{\bm{L}}}^b)_{\bm{E}_a}\,|\, T,\bm{E}_a,\mathcal{Z}^b)
		+\mathcal{H}( Y^b\,|\, T,\bm{E}_a,\mathcal{Z}^b,(\smash{\vec{\bm{L}}}^b)_{\bm{E}_a})
		-\mathcal{H}(T)-\mathcal{H}(\bm{E}_a)
	\label{eq:EntDecompB}\,,\\ \nonumber
	\mathcal{H}(\mathcal{X}^a) 
	&\le \mathcal{H}(T,\bm{E}_a,\mathcal{Z}^a) +
		\mathcal{H}(\mathcal{Y}^a\,|\,T,\bm{E}_a,\mathcal{Z}^a)\\
	&= \mathcal{H}(T,\bm{E}_a,\mathcal{Z}^a)
		+\mathcal{H}((\smash{\vec{\bm{L}}}^a)_{\bm{E}_a}\,|\,T,\bm{E}_a,\mathcal{Z}^a)
		+\mathcal{H}(Y^a\,|\,T,\bm{E}_a,\mathcal{Z}^a,(\smash{\vec{\bm{L}}}^a)_{\bm{E}_a})
		\,.
	\label{eq:EntDecompA}
	\end{align}}
Recall that the edges outside $\bm{E}_a$ are left unchanged by the transformation from $\mathcal{X}^a$ to $\mathcal{X}^b$, so
	\begin{equation}\label{e:DIVERSE.non.swapped.part}
	\mathcal{H}\bigg(T,\bm{E}_a,\mathcal{Z}^b\bigg)
	=\mathcal{H}\bigg(T,\bm{E}_a,\mathcal{Z}^a\bigg)\,.\end{equation}
Next, \eqref{eq:T2Bound} and \eqref{eq:GammaXiEquality2} together imply that
	\[
	\mathbf{P}^a(\bm{E}_a\ne\varnothing) 
	\le O\Big( \mathbf{P}^a(T=1)\Big)
	\le O\bigg( \frac{1}{\exp(\Omega(k^3\ln k))}
		\bigg)\,,\]
from which it follows that
	\begin{equation}\label{eq:sigma.T.Ent}
	\max\bigg\{\mathcal{H}(T),\mathcal{H}(\bm{E}_a),
		\mathcal{H}(Y^a\,|\,\bm{E}_a),
		\mathcal{H}(Y^b\,|\,\bm{E}_a)
		\bigg\} = o_k(1)\,.\end{equation}
We emphasize that in \eqref{eq:sigma.T.Ent} we must put $Y^a$ and $Y^b$ rather than $\mathcal{Y}^a$ and $\mathcal{Y}^b$:
this is because $Y$ consists of spins
$X_e$ which take only $O(1)$ possibilities, while $\mathcal{Y}$ consists of spins $\mathcal{X}_e=(X_e,\bm{L}_e)$ which take a large number of possibilities (indeed, growing with the neighborhood radius $R$ of \eqref{e:radii}) and therefore can have large conditional entropy given $\bm{E}_a$. To deal with the clause types $\bm{L}_e$ we note that
	\begin{align}\nonumber
	&\mathcal{H}\bigg( 
	(\smash{\vec{\bm{L}}}^a)_{\bm{E}_a}
	\,\bigg|\,
	\bm{E}_a,T, \mathcal{Z}^a\bigg) \\ \nonumber
 	&\stackrel{\eqref{eq:cond.L.Xi}}{=}
	\sum_{e\in \bm{E}}
	\Bigg\{
	\mathbf{P}^a(\Gamma(e)=1)
		\mathcal{H}\Big(\pi_{\mathscr{D}}(\cdot\,|\,\bm{t}_e)\Big)
	+\mathbf{P}^a(\Xi(e)=1)
	\mathcal{H}\Big(\pi_{\mathscr{D}}(\cdot
	\,|\,\bm{t}_e, \bm{L}_e \in \mathbb{D}\cap\mathbb{L})\Big)\\ \nonumber
	&\stackrel{\eqref{eq:GammaXiEquality2}}{=} \sum_{e\in \bm{E}}
	\Bigg\{
	\mathbf{P}^b(\Gamma(e)=1)
		\mathcal{H}\Big(\pi_{\mathscr{D}}(\cdot\,|\,\bm{t}_e)\Big)
	+\mathbf{P}^b(\Xi(e)=1)
	\mathcal{H}\Big(\pi_{\mathscr{D}}(\cdot
	\,|\,\bm{t}_e, \bm{L}_e \in \mathbb{D}\cap \mathbb{L})\Big)
	\Bigg\}\\
	&\stackrel{\eqref{eq:cond.L.Xi}}{=}
	\mathcal{H}\bigg( 
	(\smash{\vec{\bm{L}}}^b)_{\bm{E}_a}
	\,\bigg|\,
	\bm{E}_a,T,\mathcal{Z}^b
	\bigg)\,. \label{eq:L.EntopyEquality}
	\end{align}
Combining \eqref{eq:sigma.T.Ent} and \eqref{eq:L.EntopyEquality} gives 
	\begin{align}\nonumber
	&\bigg| \mathcal{H}\Big( \mathcal{Y}^a 
		\,\Big|\, \bm{E}_a,T,\mathcal{Z}^a\Big)- 
	\mathcal{H}\Big( \mathcal{Y}^b
		\,\Big|\, \bm{E}_a,T,\mathcal{Z}^b\Big)\bigg| \\ \nonumber
	&=
	\bigg|\mathcal{H}\Big( (\smash{\vec{\bm{L}}}^a)_{\bm{E}_a}\,\Big|\, \bm{E}_a,T,\mathcal{Z}^a\Big)
	-\mathcal{H}\Big( (\smash{\vec{\bm{L}}}^b)_{\bm{E}_a}\,\Big|\, \bm{E}_a,T,\mathcal{Z}^b\Big)\\
	\nonumber
	&\qquad+\mathcal{H}\Big( Y^a \,\Big|\, \bm{E}_a,T,\mathcal{Z}^a,(\smash{\vec{\bm{L}}}^a)_{\bm{E}_a}\Big)
	-\mathcal{H}\Big( Y^b \,\Big|\, \bm{E}_a,T,\mathcal{Z}^b,(\smash{\vec{\bm{L}}}^b)_{\bm{E}_a}\Big)
	\bigg|\\ 
	&\stackrel{\eqref{eq:L.EntopyEquality}}{=}
	\bigg|\mathcal{H}\Big( Y^a \,\Big|\, \bm{E}_a,T,\mathcal{Z}^a,(\smash{\vec{\bm{L}}}^a)_{\bm{E}_a}\Big)
	-\mathcal{H}\Big( Y^b \,\Big|\, \bm{E}_a,T,\mathcal{Z}^b,(\smash{\vec{\bm{L}}}^b)_{\bm{E}_a}\Big)\bigg|
	\stackrel{\eqref{eq:sigma.T.Ent}}{=} o_k(1)\,.
	\label{eq:EprimeEntopy}
	\end{align}
Finally, combining \eqref{eq:EntDecompB}, \eqref{eq:EntDecompA}, \eqref{e:DIVERSE.non.swapped.part},
\eqref{eq:sigma.T.Ent}, and \eqref{eq:EprimeEntopy} gives
	\begin{equation}\label{eq:A.to.B.Ent.Comp}
	\mathcal{H}(\mathbf{P}^b)-\mathcal{H}(\mathbf{P}^a)
	=\mathcal{H}(\mathcal{X}^b) - \mathcal{H}(\mathcal{X}^a)
	\ge o_k(1)\,.
	\end{equation}
This concludes our analysis of the measure $\mathbf{P}^b$.\smallskip

\noindent\bemph{\hypertarget{l:DIVERSE.Pc}{Part 4}. Construction of $\mathbf{P}^c$.}
Given a configuration $\mathcal{X}$, for 
$z\in\set{\SPIN{-},\SPIN{+}}$ and
$i=1,2$ let
	\begin{equation}\label{e:DIVERSE.hat.E}
	\hat{\bm{E}}^{z,i}
	\equiv \hat{\bm{E}}^{z,i}(\mathcal{X})
	\equiv \bigg\{ e\in\delta v(z):
	(\sigma_e)^i=\SSPIN{r},\sigma_e\ne\SSPIN{r}\SSPIN{r},
	\bm{L}_e\in\mathbb{D}\cap\mathbb{L}\bigg\}\,.
	\end{equation}
Write $\hat{\bm{E}}^i\equiv
\hat{\bm{E}}^{\SPIN{-},i}\cup\hat{\bm{E}}^{\SPIN{+},i}$.
Note that $\hat{\bm{E}}^1\cap\hat{\bm{E}}^2=\varnothing$. Recall from \eqref{e:four.distinct.edges} the definition of $\bm{E}$, and for $z\in\set{\SPIN{-},\SPIN{+}}$ let
	\[
	\acute{\bm{E}}^z
	\equiv \acute{\bm{E}}^z(\mathcal{X})
	\equiv\bigg\{e\in\delta v(z)\setminus\bm{E}
	: \varsigma_e=\SSPIN{w}\SSPIN{w},\bm{L}_e\in\mathbb{D}\cap\mathbb{L}\bigg\}\,.
	\]
(The sets $\acute{\bm{E}}^\SPIN{\textpm}(\mathcal{X}^a)$
are disjoint from $\bm{E}$, but
the sets $\hat{\bm{E}}^i$ can intersect $\bm{E}$.) We construct $\mathcal{X}^c$ as follows:
\begin{enumerate}[(II-2)]
\item[\hypertarget{i:DIVERSE.I1}{(I-1)}] On the event $\set{\mathcal{X}^a=\mathcal{X}^b,T(\mathcal{X}^a)=0,|\hat{\bm{E}}^1(\mathcal{X}^a)|\ge2}$,
choose $\hat{e}^1$ uniformly at random from $\hat{\bm{E}}^1(\mathcal{X}^a)$. For $e=\hat{e}^1$, set 
$(\mathcal{X}^c)_e=(\mathcal{X}^b)_e$ with probability $1-2^{-k\epsilon_\infty/2}$. With the remaining probability $2^{-k\epsilon_\infty/2}$ let $(\mathcal{X}^c)_e$ 
for $e=\hat{e}^1$
be defined by
	{\setlength{\jot}{0pt}\begin{align*}
	(\sigma^{c,1},\varsigma^{c,1})_e
	&=(\SSPIN{b},\SSPIN{w})\,,\\
	(\sigma^{c,2},\varsigma^{c,2},\bm{L}^c)_e
	&=(\sigma^{b,2},\varsigma^{b,2},\bm{L}^b)_e
	\end{align*}}
Let $p^{\textup{I},1}(e,\bm{L})$ denote the probability that edge $e$ has clause type $\bm{L}$ and is changed by the above:
	\begin{equation}\label{e:DIVERSE.def.p.I1}
	p^{\textup{I},1}(e,\bm{L})
	= \frac1{2^{k\epsilon_\infty/2}}
	\mathbb{E}
	\Bigg(
	\frac{\Ind{e\in\hat{\bm{E}}^1(\mathcal{X}^a)}}
		{|\hat{\bm{E}}^1(\mathcal{X}^a)|};
	(\bm{L}^a)_e=\bm{L},
	\mathcal{X}^a=\mathcal{X}^b,T(\mathcal{X}^a)=0,
	|\hat{\bm{E}}^1(\mathcal{X}^a)|\ge2
	\Bigg)\,,\end{equation}
where $\mathbb{E}$ denotes expectation with respect to the joint law $\mathbb{P}$ of $(\mathcal{X}^a,\mathcal{X}^b)$. 

\item[\hypertarget{i:DIVERSE.I2}{(I-2)}]
On the event $\set{\mathcal{X}^a=\mathcal{X}^b,T(\mathcal{X}^a)=0,|\hat{\bm{E}}^2(\mathcal{X}^a)|\ge2}$, perform the analogue of 
\hyperlink{i:DIVERSE.I1}{(I-1)} switching the roles of the two copies, and define the corresponding probability $p^{\textup{I},2}(e,\bm{L})$.

\item[\hypertarget{i:DIVERSE.II1}{(II-1)}] 
On the event $\set{x^{a,1}\in\set{\SPIN{-},\SPIN{+}},
T(\mathcal{X}^a)=0,|\hat{\bm{E}}^1(\mathcal{X}^a)|\le1}$, choose $\acute{e}^1$ uniformly at random from $\acute{\bm{E}}^{x^1}(\mathcal{X}^a)$. (Note the condition $T(\mathcal{X}^a)=0$ guarantees that the sets $\acute{\bm{E}}^{\SPIN{\textpm}}(\mathcal{X}^a)$ are both large, so it is possible to choose $\acute{e}^1$.) Let $(\mathcal{X}^c)_e$ for $e=\acute{e}^1$ be defined by
	{\setlength{\jot}{0pt}\begin{align*}
	(\sigma^{c,1},\varsigma^{c,1})_e
	&= (\SSPIN{r},\SSPIN{r})\,,\\
	(\sigma^{c,2},\varsigma^{c,2},\bm{L}^c)_e
		&=(\sigma^{b,2},\varsigma^{b,2},\bm{L}^b)_e
		\,.
	\end{align*}}
Let $p^{\textup{II},1}(e,\bm{L})$ denote the probability that edge $e$ has clause type $\bm{L}$ and is changed by the above:
	\begin{equation}\label{e:DIVERSE.def.p.II1}
	p^{\textup{II},1}(e,\bm{L})
	= \sum_{z\in\set{\SPIN{-},\SPIN{+}}}
	\mathbb{E}\Bigg(
	\frac{\Ind{e\in\acute{E}^z(\mathcal{X}^a)}}
		{|\acute{E}^z(\mathcal{X}^a)|}
	; (\bm{L}^a)_e=\bm{L}, x^{a,1}=z,
	T(\mathcal{X}^a)=0,
	|\hat{\bm{E}}^1(\mathcal{X}^a)|\le1
	\Bigg)\,,
	\end{equation}
where again $\mathbb{E}$ denotes expectation with respect to the joint law $\mathbb{P}$ of $(\mathcal{X}^a,\mathcal{X}^b)$. 
\item[\hypertarget{i:DIVERSE.II2}{(II-2)}] 
Lastly, on the event
$\set{x^{a,2}\in\set{\SPIN{-},\SPIN{+}},T(\mathcal{X}^a)=0,|\hat{\bm{E}}^2(\mathcal{X}^a)|\le1}$,
perform the analogue of \hyperlink{i:DIVERSE.II1}{(II-1)} switching the roles of the two copies, with the modification that if \hyperlink{i:DIVERSE.II1}{(II-1)} already occurred, then $\acute{e}^2$ is chosen uniformly at random from $\acute{\bm{E}}(\mathcal{X}^a)^2\setminus\set{\acute{e}^2}$. Define the corresponding probability $p^{\textup{II},2}(e,\bm{L})$.
\end{enumerate}
We point out that
steps \hyperlink{i:DIVERSE.I1}{(I-1)}
and \hyperlink{i:DIVERSE.I2}{(I-2)}
can only occur if $\mathcal{X}^a=\mathcal{X}^b$,
but steps 
\hyperlink{i:DIVERSE.II1}{(II-1)}
and \hyperlink{i:DIVERSE.II2}{(II-2)}
can occur even in the case
$\mathcal{X}^a\ne\mathcal{X}^b$. Note also that \hyperlink{i:DIVERSE.I1}{(I-1)} and \hyperlink{i:DIVERSE.II1}{(II-1)}
 cannot both occur, and likewise \hyperlink{i:DIVERSE.I2}{(I-2)} and 
 \hyperlink{i:DIVERSE.II2}{(II-2)}
 cannot both occur. To finish the construction, for all edges $e\in\delta v$ which were not chosen as $\hat{e}^i$ or $\acute{e}^i$ in any of the above steps, set $(\mathcal{X}^c)_e=(\mathcal{X}^b)_e$. Note that the frozen spin has not changed, $x=x^a=x^b=x^c\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$. Moreover we have $(\bm{L}^b)_e=(\bm{L}^c)_e$ for all $e\in\delta v$. It is straightforward to verify that the resulting $\mathcal{X}^c$ is a valid configuration with the same frozen spin, $x^b=x^c\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$.
Moreover, we observe that the construction so far guarantees 
	\begin{equation}\label{e:DIVERSE.hat.E.nonempty} 
	\hat{\bm{E}}^{z,i}(\mathcal{X}^c)\ne\varnothing
	\quad\textup{whenever}\quad
	x^{c,i}=z\in\set{\SPIN{-},\SPIN{+}}\,,
	\end{equation}
for $\hat{\bm{E}}^{z,i}$ as defined by \eqref{e:DIVERSE.hat.E}. Indeed, if $x=x^c$
has in the first copy $x^1=z\in\set{\SPIN{-},\SPIN{+}}$, we have these cases:
\begin{enumerate}[--]
\item Suppose $T(\mathcal{X}^a)=1$. It follows from \eqref{e:DIVERSE.Gm} that we will have $\Gamma(e)=1$ for $e=e^{z,1}\in\bm{E}$. In this case the resampling step 
\eqref{e:swap.Gamma.Xi.1} and the definition 
\eqref{e:DIVERSE.def.Xi}
of $\Xi(e)$ results in
a modified configuration $\mathcal{X}^b$ such that
 $e$ belongs to $\hat{\bm{E}}^{z,1}(\mathcal{X}^b)$.
(If $x^2=y\in\set{\SPIN{-},\SPIN{+}}$ then we may also have $\Gamma(e^{y,2})=1$, in which case the set $\hat{\bm{E}}^{y,2}$ also increases going from $\mathcal{X}^a$ to $\mathcal{X}^b$, but this is not relevant to the current considerations.)
Then steps \hyperlink{i:DIVERSE.I1}{(I-1)}
and \hyperlink{i:DIVERSE.I2}{(I-2)} do not occur
because $\mathcal{X}^a\ne\mathcal{X}^b$,
and steps 
\hyperlink{i:DIVERSE.II1}{(II-1)}
and \hyperlink{i:DIVERSE.II2}{(II-2)}
do not occur because $T(\mathcal{X}^a)=1$.
It follows that 
	\[|\hat{\bm{E}}^{z,1}(\mathcal{X}^c)|
	=|\hat{\bm{E}}^{z,1}(\mathcal{X}^b)|
	\ge|\hat{\bm{E}}^{z,1}(\mathcal{X}^a)|+1
	\ge1\,,\]
since $e=e^{z,1}\in\hat{\bm{E}}^{z,1}(\mathcal{X}^b)\setminus 
\hat{\bm{E}}^{z,1}(\mathcal{X}^a)$.

\item Suppose $T(\mathcal{X}^a)=0$, $\mathcal{X}^a=\mathcal{X}^b$, and $|\hat{\bm{E}}^1(\mathcal{X}^a)|\ge2$. In this case, the only way for an edge $e$ to belong to $\hat{\bm{E}}^1(\mathcal{X}^a)=\hat{\bm{E}}^1(\mathcal{X}^b)$ and not to $\hat{\bm{E}}^1(\mathcal{X}^c)$ is if $e$ is chosen as $\hat{e}^1$ in step \hyperlink{i:DIVERSE.I1}{(I-1)}. It follows that
	\[
	|\hat{\bm{E}}^1(\mathcal{X}^c)|
	\ge |\hat{\bm{E}}^1(\mathcal{X}^b)|-1
	= |\hat{\bm{E}}^1(\mathcal{X}^a)|-1
	\ge1\,.
	\]

\item Suppose $T(\mathcal{X}^a)=0$, $\mathcal{X}^a\ne\mathcal{X}^b$, and $|\hat{\bm{E}}^1(\mathcal{X}^a)|\ge2$. 
In this case, we see from \eqref{e:DIVERSE.def.Xi}
that we may have $\Xi(e)=1$
for $e=e^{z,1}$. This means $e\in\hat{\bm{E}}^1(\mathcal{X}^a)$, and the resampling step \eqref{e:swap.Gamma.Xi.2} results in $\mathcal{X}^b$ such that $e\notin\hat{\bm{E}}^1(\mathcal{X}^b)$. (If $x^2=y\in\set{\SPIN{-},\SPIN{+}}$ then we may also have $\Xi(e^{y,2})=1$, in which case the set 
$\hat{\bm{E}}^{y,2}$
also decreases going from $\mathcal{X}^a$ to $\mathcal{X}^b$, but this is not relevant to the current considerations since the $\hat{\bm{E}}^i$ are disjoint.) Then steps \hyperlink{i:DIVERSE.I1}{(I-1)}
and \hyperlink{i:DIVERSE.I2}{(I-2)} do not occur
because $\mathcal{X}^a\ne\mathcal{X}^b$, and steps
\hyperlink{i:DIVERSE.II1}{(II-1)}
and \hyperlink{i:DIVERSE.II2}{(II-2)}
do not occur because $|\hat{\bm{E}}^1(\mathcal{X}^a)|\ge2$.
It follows that
	\[
	|\hat{\bm{E}}^1(\mathcal{X}^c)|
	=|\hat{\bm{E}}^1(\mathcal{X}^b)|
	\ge|\hat{\bm{E}}^1(\mathcal{X}^a)|-1\ge1\,.
	\]

\item Suppose $T(\mathcal{X}^a)=0$ and $|\hat{\bm{E}}^1(\mathcal{X}^a)|\le1$. In this case, step 
\hyperlink{i:DIVERSE.II1}{(II-1)}
occurs and results in 
a configuration $\mathcal{X}^c$ such that
$\hat{\bm{E}}^1(\mathcal{X}^c)$ contains $\hat{e}^1$, and so is nonempty.
\end{enumerate}
This verifies the property \eqref{e:DIVERSE.hat.E.nonempty}, which will be used
in later steps of the proof. We now let $\mathbb{P}$ denote the joint law of
 $(\mathcal{X}^a,\mathcal{X}^b,\mathcal{X}^c)$, and let $\mathbf{P}^c$ denote the marginal law of $\mathcal{X}^c$. 

We first estimate the probability $p^{\textup{I},1}(e,\bm{L})$ from \eqref{e:DIVERSE.def.p.I1}. For an upper bound, note in order for $e\in\hat{\bm{E}}^1(\mathcal{X})$ we must have $(\sigma_e)^1=\SSPIN{r}$, so for all clause types $\bm{L}$ we have
	\begin{equation}\label{e:DIVERSE.p.I1.ubd.indiv}
	p^{\textup{I},1}(e,\bm{L})
	\le
	\frac{\mathbf{P}^a( \bm{L}_e=\bm{L}, (\sigma_e)^1=\SSPIN{r} )}
		{2^{k\epsilon_\infty/2}}
	= \frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
		\cdot {}_\star\hspace{-1pt}\pi_e(\SSPIN{r})}
		{2^{k\epsilon_\infty/2}}\,.\end{equation}
Next, since the total probability that \hyperlink{i:DIVERSE.I1}{(I-1)} occurs is at most $2^{-k\epsilon_\infty/2}$, we can also bound
	\begin{equation}\label{e:DIVERSE.p.I1.ubd}
	\sum_{e\in\delta v}\sum_{\bm{L}} 
	p^{\textup{I},1}(e,\bm{L})
	\le \frac1{2^{k\epsilon_\infty/2}}\,.\end{equation}
Next we note that $p^{\textup{I},1}(e,\bm{L})=0$ if $\bm{L}\notin\mathbb{D}\cap\mathbb{L}$. In the case $\bm{L}\in\mathbb{D}\cap\mathbb{L}$ we will derive a lower bound on $p^{\textup{I},1}(e,\bm{L})$. Recall $R_e$ from \eqref{e:DIVERSE.Re}, and let $S_e$ be an independent copy of $R_e$. By similar considerations as for \eqref{eq:frakR.bound}, we have
	\begin{equation}\label{e:DIVERSE.tildefrakR.intermediate.rr}
	\mathbf{P}^a\Bigg(
	\ddot{\mathfrak{r}}(\mathcal{X})
	\equiv
	\sum_{e\in\delta v} \Ind{\sigma_e=\SSPIN{r}\SSPIN{r}}
	\ge k^{1/2}\Bigg)
	\le O(1)
	\max_{z\in\set{\SPIN{-},\SPIN{+}}}\Bigg\{
	\frac{\mathbb{P}(\sum_{e\in\delta v(z)}
		R_e S_e \ge k^{1/2})}
	{\mathbb{P}(\sum_{e\in\delta v(z)} R_e\ge1)^2}\Bigg\}
	\le \frac1{\exp(\Omega(k^{3/2}))}\,.\end{equation}
Next, for $e\in\delta v$, let $G_e$ denote independent Bernoulli random variables with
	\[\mathbb{P}(G_e=1)
	=\mathbf{P}^a(\bm{L}_e\in\mathbb{D}\cap\mathbb{L})
	=\sum_{\bm{L}}
		\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
		\Ind{\bm{L}\in\mathbb{D}\cap\mathbb{L}}\,.\]
For $z\in\set{\SPIN{-},\SPIN{+}}$ and any fixed $e\in\delta v(z)$, on the event $\set{(\sigma_e)^1=\SSPIN{r}}$ we have
	\begin{equation}\label{e:DIVERSE.tilde.r.i.lbd}
	(\mathfrak{r}_e)^1(\mathcal{X})
	\equiv
	\sum_{e'\in\delta v(z)\setminus e}
	\mathbf{1}\bigg\{(\sigma_{e'})^1=\SSPIN{r},
		\bm{L}_{e'} \in \mathbb{D}\cap\mathbb{L}
	\bigg\}
	\ge \Big|\hat{\bm{E}}^1(\mathcal{X})\setminus
		\set{e}\Big|
	\ge (\mathfrak{r}_e)^1(\mathcal{X}) 
	- \ddot{\mathfrak{r}}(\mathcal{X})\,,\end{equation}
where $\ddot{\mathfrak{r}}(\mathcal{X})$ was defined on the left-hand side of \eqref{e:DIVERSE.tildefrakR.intermediate.rr}. By similar considerations as for \eqref{eq:frakR.bound} and \eqref{e:DIVERSE.tildefrakR.intermediate.rr}, we can express
	\[
	\mathbf{P}^a\Bigg(
	(\mathfrak{r}_e)^1 \le \frac{k}{3}
	\,\Bigg|\, (\sigma_e)^1=\SSPIN{r}\Bigg)
	=\mathbb{P}\Bigg(
	 \sum_{e'\in\delta v(z)\setminus e}
	 R_{e'} G_{e'} \le \frac{k}{3}\Bigg)\,.
	\]
To bound this last probability, note that
for both $z\in\set{\SPIN{-},\SPIN{+}}$ we have
	\begin{align*}
	&\mathrm{Var}\Bigg( \sum_{e'\in\delta v(z)\setminus e}
	R_{e'} G_{e'}\Bigg)
	\le \mathbb{E}\Bigg( \sum_{e'\in\delta v(z)\setminus e}
	R_{e'} G_{e'}\Bigg)
	=\sum_{e'\in\delta v(z)\setminus e}
	\mathbb{E} R_{e'}
	-\sum_{e'\in\delta v(z)\setminus e}
	(\mathbb{E} R_{e'}) \mathbb{E}(1-G_{e'})\\
	&\qquad=
	\bigg(1-o_k(1)\bigg) \frac{k\ln 2}{2}
	-\sum_{e'\in\delta v(z)\setminus e}
	(\mathbb{E} R_{e'}) \mathbb{E}(1-G_{e'}) 
	\stackrel{\eqref{e:assumption.notD.notL}}{=}
	\bigg(1-o_k(1)\bigg) \frac{k\ln 2}{2}\,.
	\end{align*}
We can use this last estimate together with Bernstein's inequality to bound
	\begin{equation}\label{e:DIVERSE.bernstein}
	\mathbf{P}^a\Bigg(
	(\mathfrak{r}_e)^1 \le \frac{k}{3}
	\,\Bigg|\, (\sigma_e)^1=\SSPIN{r}\Bigg)
	=\mathbb{P}\Bigg(
	 \sum_{e'\in\delta v(z)\setminus e}
	 R_{e'} G_{e'} \le \frac{k}{3}\Bigg)
	\le \frac1{\exp(\Omega(k))}\,.\end{equation}
On the other hand, by similar arguments as for \eqref{eq:frakR.bound}, we can bound
	\[
	\mathbf{P}^a\Bigg(
	(\mathfrak{r}_e)^1 \ge k
	\,\Bigg|\, (\sigma_e)^1=\SSPIN{r}\Bigg)
	\le \mathbb{P}\Bigg( \sum_{e'\in\delta v(z)\setminus e}
		R_{e'} \ge k\Bigg)
	\le \frac1{\exp(\Omega(k\ln k))}\,.
	\]
Combining the last two bounds gives
	\begin{equation}\label{e:DIVERSE.tildefrakR.intermediate.red}
	\mathbf{P}^a\Bigg(
	(\mathfrak{r}_e)^1 \in
		\bigg[\frac{k}{3},k\bigg]
	\,\Bigg|\, (\sigma_e)^1=\SSPIN{r}\Bigg)
	\ge1- \frac1{\exp(\Omega(k))}\,.
	\end{equation}
Returning to \eqref{e:DIVERSE.def.p.I1}, 
for $\bm{L}\in\mathbb{D}\cap\mathbb{L}$ we can lower bound
	\begin{align*}
	p^{\textup{I},1}(e,\bm{L}) 
	&\ge \frac1{2^{k\epsilon_\infty/2} \cdot 2k}
	\mathbf{P}^a\Bigg(
	\bm{L}_e=\bm{L},
	(\sigma_e)^1=\SSPIN{r},
	(\sigma_e)^2\ne\SSPIN{r},
	(\mathfrak{r}_e)^1 \in \bigg[\frac{k}{3},k\bigg]
	\Bigg)\\
	&\qquad-\Bigg\{\mathbf{P}^a(T=1)
	+\mathbb{P}(\mathcal{X}^a\ne \mathcal{X}^b)
	+\mathbf{P}^a(\ddot{\mathfrak{r}}\ge k^{1/2})
		\Bigg\}\,.\end{align*}
In the above we used the assumption that $\bm{L}\in\mathbb{D}\cap\mathbb{L}$, so if
$(\sigma_e)^1=\SSPIN{r}$ and $(\sigma_e)^2\ne\SSPIN{r}$
then $e\in\hat{\bm{E}}^1$.
We also used that if $(\mathfrak{r}_e)^1 \ge k/3$
and $\ddot{\mathfrak{r}}\le k^{1/2}$, then
certainly \eqref{e:DIVERSE.tilde.r.i.lbd} implies $|\hat{\bm{E}}^1|\ge2$, as is required for step (I-1) to occur. Lastly we used that if
$(\mathfrak{r}_e)^1 \le k$, then 
it follows from \eqref{e:DIVERSE.tilde.r.i.lbd} that $|\hat{\bm{E}}^1|\le k+1$, so edge $e$ has probability at least $1/(k+1) \ge 1/(2k)$ to be chosen as $\hat{e}^1$. Now recall from the previous construction that
$\mathbb{P}(\mathcal{X}^a\ne \mathcal{X}^b)
\le O(\mathbf{P}^a(T=1))$, so applying \eqref{eq:T2Bound} and \eqref{e:DIVERSE.tildefrakR.intermediate.rr} gives
	\begin{align*}
	p^{\textup{I},1}(e,\bm{L}) 
	\ge \frac1{2^{k\epsilon_\infty/2} \cdot 2k}
	\mathbf{P}^a\Bigg(
	\bm{L}_e=\bm{L},
	(\sigma_e)^1=\SSPIN{r},
	(\sigma_e)^2\ne\SSPIN{r},
	(\mathfrak{r}_e)^1 \in \bigg[\frac{k}{3},k\bigg]
	\Bigg)
	-\frac1{\exp(\Omega(k^{3/2}))}\,.
	\end{align*}
It then follows (again using the independence properties of $\mathbf{P}^a$) that
	\begin{align}\nonumber
	p^{\textup{I},1}(e,\bm{L}) 
	&\stackrel{\eqref{eq:productForm}}{\ge}
	\frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
		{2^{k\epsilon_\infty/2} \cdot 2k}
	\mathbf{P}^a\Big((\sigma_e)^1=\SSPIN{r}\Big)
	\mathbf{P}^a\Big((\sigma_e)^2\ne\SSPIN{r}\Big)
	\mathbf{P}^a\Bigg(
	(\mathfrak{r}_e)^1 \in \bigg[\frac{k}{3},k\bigg]
	\,\Bigg|\,
	(\sigma_e)^1=\SSPIN{r}
	\Bigg) \\
	&\stackrel{\eqref{e:DIVERSE.tildefrakR.intermediate.red}}{\ge}
	\frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
		{2^{k\epsilon_\infty/2} \cdot 2k}
	\cdot \frac{1-o_k(1)}{2^k}\,,
	\label{e:DIVERSE.p.I.final.lbd}\end{align}
as long as $\bm{L}\in\mathbb{D}\cap\mathbb{L}$. This concludes our analysis of $p^{\textup{I},1}(e,\bm{L})$. Clearly, 
\eqref{e:DIVERSE.p.I1.ubd} and \eqref{e:DIVERSE.p.I.final.lbd} also hold for 
$p^{\textup{I},2}(e,\bm{L})$.


We next prove an upper bound on the probability 
$p^{\textup{II},1}(e,\bm{L})$ from
\eqref{e:DIVERSE.def.p.II1}. Recall that the condition $T(\mathcal{X}^a)=0$ implies 
$|\acute{\bm{E}}^z(\mathcal{X}^a)| = \Theta(k2^k)$
for both $z\in\set{\SPIN{-},\SPIN{+}}$.
It follows that we can upper bound \eqref{e:DIVERSE.def.p.II1} as
	\[
	p^{\textup{II},1}(e,\bm{L})
	\le
	O\bigg(\frac1{k2^k}\bigg)
	\cdot
	\mathbf{P}^a\bigg(\bm{L}_e=\bm{L},
	|\hat{\bm{E}}^1(\mathcal{X}^a)|\le1
	\bigg)
	\le
	O\bigg(\frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}{k2^k}\bigg)
	\cdot\mathbf{P}^a\bigg(
		|\hat{\bm{E}}^1(\mathcal{X}^a)
		\setminus\set{e}|\le1
		\bigg)\,.\]
Recall from
\eqref{e:DIVERSE.tilde.r.i.lbd} 
that $|\hat{\bm{E}}^1(\mathcal{X}^a)\setminus\set{e}| \le (\mathfrak{r}_e)^1(\mathcal{X}^a)$. Then, arguing similarly as for 
\eqref{e:DIVERSE.bernstein}, 
for each $z\in\set{\SPIN{-},\SPIN{+}}$
we can apply Bernstein's inequality to upper bound
	\begin{align*}
	&\mathbf{P}^a\Bigg(
	(\mathfrak{r}_e)^1
	=
	\sum_{e'\in\delta v(z)\setminus e}
	\mathbf{1}\Big\{(\sigma_{e'})^1=\SSPIN{r},
	\bm{L}_{e'}\in\mathbb{D}\cap\mathbb{L}
	\Big\} \le1
	\,\Bigg|\, x^1=z\Bigg) \\
	&\qquad= \frac{\mathbb{P}(\sum_{e'
		\in\delta v(z)\setminus e} R_{e'} G_{e'}
			\le1)}
		{\mathbb{P}(\sum_{e'\in\delta v(z)} R_{e'}\ge1)}
	\le \frac1{\exp(k c_0)}\,,
	\end{align*}
for a positive absolute constant $c_0$.
On the other hand, if $(\mathfrak{r}_e)^1\ge2$, in order for $|\hat{\bm{E}}^1(\mathcal{X}^a)\setminus\set{e}|\le1$ it must be that
$(\sigma^{a,2})_{e'}=\SSPIN{r}$ for all but at most one of the edges $e'$ contributing to $(\mathfrak{r}_e)^1$, which has chance $O(2^{-k})$. Then
	\[
	\mathbf{P}^a\bigg(
		\hat{\bm{E}}^1(\mathcal{X}^a)
		\setminus\set{e}=\varnothing\bigg)
	\le
	\mathbf{P}^a \bigg((\mathfrak{r}_e)^1\le1\bigg)
	+\underbrace{\mathbf{P}^a\bigg(
	(\mathfrak{r}_e)^1\ge2,
	|\hat{\bm{E}}^1(\mathcal{X}^a)
		\setminus\set{e}| \le1
		\bigg)}_{O(1/2^k)}
	\le \frac1{\exp(k c_0)}\,.\]
Substituting into the above expression for
$p^{\textup{II},1}(e,\bm{L})$ gives
	\begin{equation}\label{e:DIVERSE.p.II.final.ubd}
	p^{\textup{II},1}(e,\bm{L})
	\le \frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
		{2^{k(1+c_0)}}\,.
	\end{equation}
A similar bound holds for $p^{\textup{II},2}(e,\bm{L})$, and this concludes our analysis of $p^{\textup{II},1}(e,\bm{L})$.

We now turn to estimating the entropy of $\mathbf{P}^c$. Let $\bm{E}_b$ be the (random) subset of edges $e\in\delta v$ for which $(\mathcal{X}^b)_e\ne(\mathcal{X}^c)_e$, or equivalently $(X^b)_e\ne(X^c)_e$. It follows by combining \eqref{e:DIVERSE.p.I1.ubd} and \eqref{e:DIVERSE.p.II.final.ubd} that
	\begin{equation}\label{e:DIVERSE.expected.bc.change}
	\mathbb{E}(|\bm{E}_b|)
	\le \sum_{e\in\delta v}\sum_{\bm{L}}\sum_{i=1,2}
		\bigg(
		p^{\textup{I},i}(e,\bm{L})
		+p^{\textup{II},i}(e,\bm{L})\bigg)
	\le O\bigg( \frac1{2^{k\epsilon_\infty/2}}\bigg)\,.\end{equation}
We write $\mathcal{H}(\bm{E}_b)$ to denote the entropy of the random variable $\bm{E}_b$, and we write $H(p)\equiv -p\ln p-(1-p)\ln (1-p)$ to denote the binary entropy function evaluated at $p\in[0,1]$. Then
	\begin{equation}\label{e:DIVERSE.bc.ent.Estar}
	\mathcal{H}(\bm{E}_b)
	\le \sum_{e\in\delta v} \mathcal{H}( \Ind{e\in\bm{E}_b} )
	\le |\delta v|
	H\bigg( \frac{ \mathbb{E}(|\bm{E}_b|) }{|\delta v|}\bigg)
	\stackrel{\eqref{e:DIVERSE.expected.bc.change}}{=} 
	o_k(1)\,,
	\end{equation}
where the second step used Jensen's inequality and the concavity of the binary entropy function. Now decompose $\smash{\vec{X}}_{\delta v}\equiv (U,W)$ where $U\equiv(X_e:e\in\bm{E}_b)$. 
Note if $\bm{E}_b$ is given, then $U^b$ takes at most $O(1)$ distinct values, so it follows from \eqref{e:DIVERSE.bc.ent.Estar} that the conditional entropy of $U^b$ given $\bm{E}_b$ is small, that is,
$\mathcal{H}(U^b \,|\, \bm{E}_b)=o_k(1)$. Then, since $\mathcal{X}^b$ can be determined as a function of $(\mathcal{X}^c,\bm{E}_b,U^b)$, we have
	\begin{equation}\label{eq:cXb.cXc.entropyComp}
	\mathcal{H}(\mathcal{X}^b)
	\le \mathcal{H}(\mathcal{X}^c) +
	\bigg( \mathcal{H}(\bm{E}_b) + \mathcal{H}(U^b \,|\, \bm{E}_b)\bigg)
	\stackrel{\eqref{e:DIVERSE.bc.ent.Estar}}{\le}
	\mathcal{H}(\mathcal{X}^c) + o_k(1)\,.
	\end{equation}
This verifies that the entropy of $\mathbf{P}^c$ is not much smaller than that of $\mathbf{P}^b$.

We finally estimate how the transformation from $\mathbf{P}^b$ to $\mathbf{P}^c$ affects the edge marginals. Recall that steps \hyperlink{i:DIVERSE.I1}{(I-1)} and 
\hyperlink{i:DIVERSE.I2}{(I-2)} can change $(\varsigma_e)^i$
from $\SPIN{red}$ to $\SPIN{white}$, and the probability of such a change is lower bounded by \eqref{e:DIVERSE.p.I.final.lbd}. Meanwhile, steps
\hyperlink{i:DIVERSE.II1}{(II-1)} and 
\hyperlink{i:DIVERSE.II2}{(II-2)} 
can change $(\varsigma_e)^i$ from $\SPIN{white}$ to $\SPIN{red}$,
and the probability of such a change is upper bounded by \eqref{e:DIVERSE.p.II.final.ubd}.
It follows that for $\bm{L}\in\mathbb{D}\cap\mathbb{L}$,
	\begin{align}\nonumber
	&\mathbf{P}^c\bigg( (\sigma_e)^i=\SSPIN{r}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\le
	\mathbf{P}^b\bigg( (\sigma_e)^i=\SSPIN{r}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	+\sum_{i=1,2}
	\frac{p^{\textup{II},i}(e,\bm{L})- p^{\textup{I},i}(e,\bm{L})}
		{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
	\\
	\qquad&\le
	\mathbf{P}^b\bigg( (\sigma_e)^i=\SSPIN{r}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	+ O\bigg( \frac{1}{2^{k(1+c_0)}}\bigg)
	-\Omega\bigg( \frac{1}{k 2^{k(1+\epsilon_\infty/2)}}\bigg)
	\le
	{}_\star\hspace{-1pt}\pi_e(\SSPIN{r})
	-\Omega\bigg( \frac{1}{k 2^{k(1+\epsilon_\infty/2)}}\bigg)\,,
	\label{eq:Xc.red.marginal.div}
	\end{align}
where the last step also used our earlier observation
\eqref{e:DIVERSE.ab.same.mgls} that $\mathbf{P}^b$ has the same edge marginals as $\mathbf{P}^a$. On the other hand, since the probability of
\hyperlink{i:DIVERSE.I1}{(I-1)} or
\hyperlink{i:DIVERSE.I2}{(I-2)} is upper bounded by \eqref{e:DIVERSE.p.I1.ubd.indiv}, we also have
	\begin{equation}\label{eq:Xc.red.marginal.div2}
	\mathbf{P}^c\bigg( (\sigma_e)^i=\SSPIN{r}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\ge
	\mathbf{P}^b\bigg( (\sigma_e)^i=\SSPIN{r}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	-\sum_{i=1,2}
	\frac{p^{\textup{I},i}(e,\bm{L})}{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
	\ge{}_\star\hspace{-1pt}\pi_e(\SSPIN{r})- 
	O\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)\end{equation}
for all $\bm{L}\in\mathbb{D}\cap\mathbb{L}$. In the case $(\bm{L}^b)\notin \mathbb{D}\cap\mathbb{L}$ we always set $(\mathcal{X}^c)_e=(\mathcal{X}^b)_e$,
so 
	\begin{equation}\label{eq:Xc.red.marginal.notdiv}
	\mathbf{P}^c\bigg( (\sigma_e)^i=\SSPIN{r}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	=
	\mathbf{P}^b\bigg( (\sigma_e)^i=\SSPIN{r}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\end{equation}
for all $\bm{L}\notin\mathbb{D}\cap\mathbb{L}$. Finally, since we did not yet change any spin with $(\varsigma_e)^i\in\set{\SSPIN{y},\SSPIN{c}}$
or $\varsigma_e\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$, we have
	{\setlength{\jot}{0pt}\begin{align}
	\label{eq:Xc.col.marginal.zeta.mgl}
	\mathbf{P}^c((\varsigma_e)^i=\tau\,|\, \bm{L}_e=\bm{L})
	&=(\bm{\zeta}_e)^i(\tau\,|\,\bm{L})
	\textup{ for all }\tau\in\set{\SSPIN{y},\SSPIN{c}}, \\
	\mathbf{P}^c(\varsigma_e\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2\,|\, \bm{L}_e=\bm{L})
	&= \mathbf{P}^a(\varsigma_e\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2\,|\, \bm{L}_e=\bm{L})
	\le O(k^4/4^k)
	\label{eq:Xc.col.marginal}
	\end{align}}
for all $\bm{L}$, where the final bound uses \eqref{e:DIVERSE.Pa.RYCsq}.\smallskip

\noindent\bemph{\hypertarget{l:DIVERSE.Pd}{Part 5}. Construction of $\mathbf{P}^d$.} We now construct $\mathcal{X}^d$ from $\mathcal{X}^c$. We will leave the clause type unchanged, $(\bm{L}^d)_e=(\bm{L}^c)_e$ for all $e\in\delta v$. We change some edges from non-\SPIN{white} to \SPIN{white}, according to the following rules.
\begin{enumerate}[(A)]
\item If $\bm{L}\not\in\mathbb{D}\cap\mathbb{L}$ and $(\varsigma^c)_e\ne\SSPIN{w}\SSPIN{w}$, then set $(\varsigma^d)_e=\SSPIN{w}\SSPIN{w}$, and
for $i=1,2$ set
	\[
	(\sigma^{d,i})_e
	=\begin{cases}
	\SSPIN{b} &\textup{if $(\sigma^{c,i})_e=\SSPIN{r}$,}\\
	(\sigma^{c,i})_e &\textup{otherwise.}
	\end{cases}
	\]
\item If $\bm{L}\in\mathbb{D}\cap\mathbb{L}$ then modify the spin on $e$ as follows:
\begin{enumerate}[(i)]
\item If $(\varsigma^c)_e=\SSPIN{r}\SSPIN{r}$ then set
$(\sigma^d,\varsigma^d)_e=(\SSPIN{b}\SSPIN{b},\SSPIN{w}\SSPIN{w})$.

\item If $(\varsigma^c)_e\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2\setminus\set{\SSPIN{r}\SSPIN{r}}$ then set
$(\sigma^d)_e=(\sigma^c)_e$, and for $i=1,2$ set
	\[
	(\varsigma^{d,i})_e
	=\begin{cases}
	\SSPIN{r}&\textup{if $(\sigma^{c,i})_e=\SSPIN{r}$,}\\
	\SSPIN{w}&\textup{otherwise.}
	\end{cases}
	\]

\item If $(\varsigma^c)_e\in\set{\SSPIN{y},\SSPIN{c}}\times\set{\SSPIN{w}}$ then set
$(\sigma^d)_e=(\sigma^c)_e$. For $\tau=(\varsigma^{c,1})_e\in\set{\SSPIN{y},\SSPIN{c}}$ define the quantity
	\[\theta=
	(\theta_e)^1(\tau\,|\,\bm{L})
	\equiv\min\bigg\{1, \frac{2^{-k(1+\epsilon_\infty/2)} }
		{(\bm{\zeta}_e)^1(\tau \,|\,\bm{L})}\bigg\}\,.
	\]
Set
 $(\varsigma^d)_e=\SSPIN{w}\SSPIN{w}$ with probability $\theta$. With the remaining probability $1-\theta$ leave $(\varsigma^d)_e$ unchanged.
If $(\varsigma^c)_e\in\set{\SSPIN{w}}\times\set{\SSPIN{y},\SSPIN{c}}$ then perform the analogous procedure with the roles of the two copies switched.

\item Lastly, if $(\varsigma^c)_e=\SSPIN{w}\SSPIN{w}$ then set
$(X^d)_e=(\sigma^d,\varsigma^d)_e=(\sigma^c,\varsigma^c)_e=(X^c)_e$.
\end{enumerate}
\end{enumerate}
Note that property \eqref{e:DIVERSE.hat.E.nonempty}
of $\mathcal{X}^c$ ensures that the above transformation results in a valid configuration $\mathcal{X}^d$
with the same frozen spin, $x^c=x^d\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$. 
Since the transformation does not add any \SPIN{red} spins, for $\bm{L}\in\mathbb{D}\cap\mathbb{L}$ we can bound
	\begin{align*}
	&\mathbf{P}^d\bigg(\varsigma_e=\SSPIN{r}\SSPIN{w}\,\bigg|\,\bm{L}_e=\bm{L}\bigg)
	\le\mathbf{P}^c\bigg(\varsigma_e=\SSPIN{r}\SSPIN{w}\,\bigg|\,\bm{L}_e=\bm{L}\bigg)
	\stackrel{\eqref{eq:Xc.red.marginal.div}}{\le} {}_\star\hspace{-1pt}\pi_e(\SSPIN{r})
	-\Omega\bigg( \frac{1}{k 2^{k(1+\epsilon_\infty/2)}}\bigg)\\
	&\qquad=\zeta_e(\SSPIN{r}\SSPIN{w}\,|\,\bm{L})
	+\zeta_e(\set{\SSPIN{r}}\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}\,|\,\bm{L})
	-\Omega\bigg( \frac{1}{k 2^{k(1+\epsilon_\infty/2)}}\bigg)\\
	&\qquad\stackrel{\odot}{\le}
	\zeta_e(\SSPIN{r}\SSPIN{w}\,|\,\bm{L})
	+O\bigg( \frac1{2^{k(1+\epsilon_\circ)}}\bigg)
	-\Omega\bigg( \frac{1}{k 2^{k(1+\epsilon_\infty/2)}}\bigg)
	\le \zeta_e(\SSPIN{r}\SSPIN{w}\,|\,\bm{L})\,.
	\end{align*}
The inequality marked $\odot$ above follows from Lemma~\ref{l:lotsOfAsDiverse} and the assumption $\bm{L}\in\mathbb{D}\cap\mathbb{L}$, with $\epsilon_\circ$ as in Definition~\ref{d:heavy}, and recalling that we took $\epsilon_\infty\le\epsilon_\circ$. For a lower bound, we note that for the case $\bm{L}\in\mathbb{D}\cap\mathbb{L}$, the above transformation removes \SPIN{red} spins only in the case $(\sigma^c)_e=\SSPIN{r}\SSPIN{r}$. It follows that, for all $\bm{L}\in\mathbb{D}\cap\mathbb{L}$, we have
	\begin{align*}
	&\mathbf{P}^d\bigg( (\varsigma_e)^1=\SSPIN{r}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\ge \mathbf{P}^c\bigg( (\varsigma_e)^1=\SSPIN{r}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
		-\mathbf{P}^c\bigg(
		\sigma_e=\SSPIN{r}\SSPIN{r}\,\bigg|\, \bm{L}_e=\bm{L}\bigg) \\
	&\stackrel{\eqref{e:DIVERSE.Pa.RYCsq}}{\ge} \mathbf{P}^c\bigg( (\varsigma_e)^1=\SSPIN{r}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
		- O\bigg( \frac{k^4}{4^k} \bigg)
	\stackrel{\eqref{eq:Xc.red.marginal.div2}}{\ge}
	 {}_\star\hspace{-1pt}\pi_e(\SSPIN{r}) 
	 -O\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)
	 - O\bigg( \frac{k^4}{4^k} \bigg) \\
	&\ge\zeta_e(\varsigma=\SSPIN{r}\SSPIN{w}\,|\,\bm{L})
		- O\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)\,.
	\end{align*}
Similar bounds hold if we exchange the roles of the two copies, so we also have
	\[\zeta_e(\SSPIN{w}\SSPIN{r}\,|\,\bm{L})
		- O\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)
	\le\mathbf{P}^d\bigg(\varsigma_e=\SSPIN{w}\SSPIN{r}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\le \zeta_e(\SSPIN{w}\SSPIN{r}\,|\,\bm{L})\]
for all $\bm{L}\in\mathbb{D}\cap\mathbb{L}$. 
For $\bm{L}\in\mathbb{D}\cap\mathbb{L}$ 
and $\tau\in\set{\SSPIN{y},\SSPIN{c}}$ we also have
	\begin{align*}
	&\mathbf{P}^d\bigg(\varsigma_e=\tau\SSPIN{w}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\le
	\Big(1-(\theta_e)^1(\tau)\Big)
	\mathbf{P}^c\bigg((\varsigma_e)^1=\tau
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\stackrel{\eqref{eq:Xc.col.marginal.zeta.mgl}}{=}
	\Big(1-(\theta_e)^1(\tau)\Big)
	(\bm{\zeta}_e)^i(\tau\,|\,\bm{L})\\
	&\qquad=\max\bigg\{0,
		(\bm{\zeta}_e)^i(\tau\,|\,\bm{L})-\frac1{2^{k(1+\epsilon_\infty/2)}}
	\bigg\}
	=\max\bigg\{0,
		\bm{\zeta}_e(\tau\SSPIN{w}\,|\,\bm{L})
		+\bm{\zeta}_e(\tau\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}\,|\,\bm{L})
		-\frac1{2^{k(1+\epsilon_\infty/2)}}
	\bigg\}\\
	&\qquad\le \bm{\zeta}_e(\tau\SSPIN{w}\,|\,\bm{L})
		+O\bigg( \frac1{2^{k(1+\epsilon_\circ)}}\bigg)
		-\frac1{2^{k(1+\epsilon_\infty/2)}}
	\le \bm{\zeta}_e(\tau\SSPIN{w}\,|\,\bm{L})
		-\Theta\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)\,,
	\end{align*}	
where the transition to the last line is by another application of Lemma~\ref{l:lotsOfAsDiverse}, again using that $\bm{L}\in\mathbb{D}\cap\mathbb{L}$. For a lower bound on the same quantity, we have
for all $\bm{L}\in\mathbb{D}\cap\mathbb{L}$ and $\tau\in\set{\SSPIN{y},\SSPIN{c}}$ that
	\begin{align*}
	&\mathbf{P}^d\bigg(\varsigma_e=\tau\SSPIN{w}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\ge\Big(1-(\theta_e)^1(\tau)\Big)
	\bigg\{
	\mathbf{P}^c\bigg( (\varsigma_e)^1=\tau
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	-\mathbf{P}^c\bigg( \varsigma_e\in\set{\tau}\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)\bigg\}\\
	&\qquad\stackrel{\eqref{eq:Xc.col.marginal}}{\ge}
		\Big(1-(\theta_e)^1(\tau)\Big)
	\mathbf{P}^c\bigg( (\varsigma_e)^1=\tau
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
		-O\bigg(\frac{k^4}{4^k}\bigg)\\
	&\qquad\stackrel{\eqref{eq:Xc.col.marginal.zeta.mgl}}{=}
	\max\bigg\{0,
		\bm{\zeta}_e(\tau\SSPIN{w}\,|\,\bm{L})
		+\bm{\zeta}_e(\tau\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}\,|\,\bm{L})
		-\frac1{2^{k(1+\epsilon_\infty/2)}}
	\bigg\}-O\bigg(\frac{k^4}{4^k}\bigg)
	\ge \bm{\zeta}_e(\tau\SSPIN{w}\,|\,\bm{L})
	-\Theta\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)\,.
	\end{align*}
Finally, the above procedure never yields $(\varsigma^d)_e\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$, so
for all $\bm{L}\in\mathbb{D}\cap\mathbb{L}$
and all $\varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$ we have
	\[
	\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	\ge 0 = \mathbf{P}^d\bigg(\varsigma_e=\varsigma
		\,\bigg|\,\bm{L}_e=\bm{L}\bigg)
	\ge \bm{\zeta}_e(\varsigma\,|\,\bm{L})
		-\Theta\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)\,,
	\]
where the last inequality again uses Lemma~\ref{l:lotsOfAsDiverse}. In summary, in the above we have shown
	\begin{equation}\label{e:DIVERSE.cd.zeta.mgl}
	\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	\ge \mathbf{P}^d\bigg(\varsigma_e=\varsigma
		\,\bigg|\,\bm{L}_e=\bm{L}\bigg)
	\ge \bm{\zeta}_e(\varsigma\,|\,\bm{L})
		-\Theta\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)
		\end{equation}
for all $\bm{L}\in\mathbb{D}\cap\mathbb{L}$
and all $\varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2\setminus\set{\SSPIN{w}\SSPIN{w}}$. On the other hand, for $\bm{L}\notin\mathbb{D}\cap\mathbb{L}$ we have
	\begin{equation}\label{e:DIVERSE.cd.zeta.mgl.notDL}
	\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	\ge0=
	\mathbf{P}^d\bigg(\varsigma_e=\varsigma
		\,\bigg|\,\bm{L}_e=\bm{L}\bigg)
	\ge \bm{\zeta}_e(\varsigma\,|\,\bm{L})
	- O\bigg( \frac{k^2}{2^k}\bigg)
	\end{equation}
for all $\varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2\setminus\set{\SSPIN{w}\SSPIN{w}}$, where the last inequality is by Lemma~\ref{l:lotsOfAs}.

We now turn to estimating the entropy of $\mathbf{P}^d$. To this end, let $\bm{E}_c$ denote the subset of edges $e\in\delta v$ for which $(\mathcal{X}^d)_e\ne(\mathcal{X}^c)_e$, or equivalently $(X^d)_e\ne(X^c)_e$. Note that if 
$(\varsigma^{c,i})_e\ne\SSPIN{w}$
and $(\varsigma^{d,i})_e\ne\SSPIN{w}$,
then $(\varsigma^{c,i})_e=(\varsigma^{d,i})_e$
so $e\notin\bm{E}_c$.
If $e\in\bm{E}_c$ then
the above procedure must transform
$(\varsigma^{c,i})_e\ne\SSPIN{w}$ into $(\varsigma^{d,i})_e=\SSPIN{w}$ for at least one index $i=1,2$, so we can bound
	\begin{align*}
	&\mathbb{P}(e\in \bm{E}_c\,\bigg|\,\bm{L}_e=\bm{L})
	\le \sum_{i=1,2}
	\bigg\{ \mathbf{P}^c\Big( (\varsigma_e)^i\ne\SSPIN{w}
		\,\Big|\,\bm{L}_e=\bm{L}\Big)
	-\mathbf{P}^d\Big( (\varsigma_e)^i\ne\SSPIN{w}
		\,\Big|\,\bm{L}_e=\bm{L}\Big)\bigg\}\\
	&\qquad\le
	\sum_{i=1,2}\bigg\{
	(\bm{\zeta}_e)^i\Big(\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}
		\,\Big|\,\bm{L}\Big)
	-\mathbf{P}^d\Big( (\varsigma_e)^i\ne\SSPIN{w}
		\,\Big|\,\bm{L}\Big)\bigg\}
	\le O(1)\sum_{\varsigma\ne\SSPIN{w}\SSPIN{w}}
		\bigg|
		\bm{\zeta}_e(\varsigma\,|\,\bm{L})
		- \mathbf{P}^d\Big(\varsigma_e=\varsigma
			\,\Big|\,\bm{L}_e=\bm{L}\Big)
		\bigg|\,,
	\end{align*}
where the transition to the second line follows by combining \eqref{eq:Xc.red.marginal.div} and \eqref{eq:Xc.col.marginal.zeta.mgl}. Applying
\eqref{e:DIVERSE.cd.zeta.mgl} and \eqref{e:DIVERSE.cd.zeta.mgl.notDL} gives
	\begin{align}\nonumber
	\mathbb{E}(|\bm{E}_c|)
	&\le
	O(1)\sum_{e\in\delta v}
		\sum_{\varsigma\ne\SSPIN{w}\SSPIN{w}}
		\bigg\{
		\frac{\mathbf{P}^c(\bm{L}_e\in\mathbb{D}\cap\mathbb{L})}
			{2^{k(1+\epsilon_\infty/2)}}
		+\frac{\mathbf{P}^c(\bm{L}_e\notin\mathbb{D}\cap\mathbb{L})}
			{2^k/k^2}\bigg\}\\
	&\le O\bigg(\frac{k}{2^{k\epsilon_\infty/2}}
	+ \frac{\cancel{\mathbb{D}}(v)+\cancel{\mathbb{L}}(v)}
		{2^k/k^2}\bigg)
	\stackrel{\eqref{e:assumption.notD.notL}}{\le}
	O\bigg(\frac{k^2}{2^{k\epsilon_\infty/2}}\bigg)\,,
	\label{e:DIVERSE.Ec.bound}\end{align}
similarly to the estimate
\eqref{e:DIVERSE.expected.bc.change} from the previous transformation. It follows by the same argument as for \eqref{eq:cXb.cXc.entropyComp} that
	\begin{equation}\label{eq:cXc.cXd.entropyComp}
	\mathcal{H}(\mathbf{P}^c) 
	=\mathcal{H}(\mathcal{X}^c) 
	\le \mathcal{H}(\mathcal{X}^d) + o_k(1)
	= \mathcal{H}(\mathbf{P}^d) + o_k(1).
	\end{equation}
This concludes our analysis of the measure $\mathbf{P}^d$.\smallskip

\noindent\bemph{\hypertarget{l:DIVERSE.Pe}{Part 6}. Construction of $\mathbf{P}^f$.}
In the final step of the proof we construct $\mathcal{X}^f$ from $\mathcal{X}^d$, where we have chosen the notation $\mathcal{X}^f$ rather than $\mathcal{X}^e$ to avoid confusion with edge labels $e\in\delta v$. For $\sigma\in\set{\SSPIN{y},\SSPIN{b}}^2$ we define subsets $A^\sigma$ of $
\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2$ as follows:
	{\setlength{\jot}{0pt}\begin{align*}
	A^{\SSPIN{b}\SSPIN{b}}&=\set{(\SSPIN{r}\SSPIN{r},\SSPIN{r}\SSPIN{r}),
		(\SSPIN{b}\SSPIN{r},\SSPIN{w}\SSPIN{r}),(\SSPIN{b}\SSPIN{r},\SSPIN{c}\SSPIN{r}),
		(\SSPIN{r}\SSPIN{b},\SSPIN{r}\SSPIN{w}),(\SSPIN{r}\SSPIN{b},\SSPIN{r}\SSPIN{c}),
		(\SSPIN{b}\SSPIN{b},\SSPIN{w}\SSPIN{c}),(\SSPIN{b}\SSPIN{b},\SSPIN{c}\SSPIN{w}),
		(\SSPIN{b}\SSPIN{b},\SSPIN{c}\SSPIN{c})}\,,\\
	A^{\SSPIN{b}\SSPIN{y}}&=\set{
		(\SSPIN{r}\SSPIN{y},\SSPIN{r}\SSPIN{y}),
		(\SSPIN{b}\SSPIN{y},\SSPIN{w}\SSPIN{y}),
		(\SSPIN{b}\SSPIN{y},\SSPIN{c}\SSPIN{y})
		}\,,\\
	A^{\SSPIN{y}\SSPIN{b}}&=\set{
		(\SSPIN{y}\SSPIN{r},\SSPIN{y}\SSPIN{r}),
		(\SSPIN{y}\SSPIN{b},\SSPIN{y}\SSPIN{w}),
		(\SSPIN{y}\SSPIN{b},\SSPIN{y}\SSPIN{c})
		}\,,\\
A^{\SSPIN{y}\SSPIN{y}}&=\{(\SSPIN{y}\SSPIN{y},\SSPIN{y}\SSPIN{y})\}\,.
\end{align*}}
Note that for each $\sigma\in\set{\SSPIN{y},\SSPIN{b}}^2$ and every $(\sigma',\varsigma')\in A^\sigma$ we have the compatibility relation $\sigma'\sim\varsigma'$; and the spins $\sigma,\sigma'$ correspond to the same frozen spin $x\in\set{\SPIN{-},\SPIN{+}}^2$. Moreover, for each $\varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2\setminus\set{\SSPIN{w}\SSPIN{w}}$ 
there is exactly one spin $\sigma\equiv\sigma^f(\varsigma)\in\set{\SSPIN{y},\SSPIN{b}}^2$ such that 
$(\sigma',\varsigma)\in A^\sigma$ for some $\sigma'$.
We then define distributions $\xi^\sigma(\cdot\,|\,\bm{L})$ over pairs $X\equiv (\sigma,\varsigma)\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2$ by setting
	\begin{equation}\label{e:DIVERSE.xi.defn}
	\xi^\sigma((\sigma,\varsigma)\,|\,\bm{L})
	=\frac{\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	-\mathbf{P}^d(\varsigma_e = \varsigma \,|\, \bm{L}_e=\bm{L})}{\mathbf{P}^d(\sigma_e = \sigma, \varsigma_e= \SSPIN{w}\SSPIN{w}
		\,|\, \bm{L}_e=\bm{L} )}
	\end{equation}
for all $(\sigma,\varsigma)\in A^\sigma$, and assigning the remaining probability to the event $\set{(\sigma,\varsigma)=(\sigma,\SSPIN{w}\SSPIN{w})}$. To see that these distributions are well-defined, note that on the right-hand side of \eqref{e:DIVERSE.xi.defn}, the denominator is $\Theta(1)$, while \eqref{e:DIVERSE.cd.zeta.mgl} and \eqref{e:DIVERSE.cd.zeta.mgl.notDL} together imply that the numerator is nonnegative and small. It follows that
	\[
	\xi^\sigma((\sigma,\SSPIN{w}\SSPIN{w})\,|\,\bm{L})
	= 1-\sum_{X'\in A^\sigma}
		\xi^\sigma(X'\,|\,\bm{L})
	\in[0,1]\,,
	\]
so $\xi^\sigma(\cdot\,|\,\bm{L})$ is a valid probability measure over $A^\sigma \cup \set{(\sigma,\SSPIN{w}\SSPIN{w})}$. In the final transformation, given $\mathcal{X}^d$, for each $e\in\delta v$ we set $(\bm{L}^f)_e=(\bm{L}^d)_e$. If $(\sigma^d)_e\in\set{\SSPIN{y},\SSPIN{b}}^2$ and $(\varsigma^d)_e=\SSPIN{w}\SSPIN{w}$, then we let $(X^f)_e$ be a sample from $\xi^\sigma(\cdot\,|\,(\bm{L}^d)_e)$. In all other cases we let $(X^f)_e=(X^d)_e$. It is straightforward to verify that this results in a valid configuration $\mathcal{X}^f$ with the same frozen spin,
$x^f=x^d\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$. For each $\varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2\setminus\set{\SSPIN{w}\SSPIN{w}}$,
	\begin{align}\nonumber
	&\mathbf{P}^f\Big(\varsigma_e=\varsigma\,\Big|\,\bm{L}_e=\bm{L}\Big)
	= \mathbf{P}^d\Big(\varsigma_e=\varsigma\,\Big|\,\bm{L}_e=\bm{L}\Big)
	+ \sum_{\sigma: \sigma=\sigma^f(\varsigma)}
	\mathbf{P}^d\Big(
	\sigma_e=\sigma,
	\varsigma_e=\SSPIN{w}\SSPIN{w}
	\,\Big|\,\bm{L}_e=\bm{L}\Big)
	\xi^\sigma( (\sigma,\varsigma) \,|\,\bm{L})\\
	&\qquad\stackrel{\eqref{e:DIVERSE.xi.defn}}{=}
	\mathbf{P}^d\Big(\varsigma_e=\varsigma\,\Big|\,\bm{L}_e=\bm{L}\Big)
	+ \bigg\{ \bm{\zeta}_e(\varsigma\,|\,\bm{L})
	-\mathbf{P}^d\Big(\varsigma_e=\varsigma\,\Big|\,\bm{L}_e=\bm{L}\Big)\bigg\}
	=\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	\,,\label{e:DIVERSE.final.msr.sat.varsigma}
	\end{align}
so $\mathbf{P}^f$ satisfies condition
\eqref{e:D.L.diverse.varsigma}. On the other hand, since $x^a=x^f\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$, we have
	\[
	\mathbf{P}^f\Big( x^i=z\,\Big|\,\bm{L}_e=\bm{L}\Big)
	=\mathbf{P}^a\Big( x^i=z\,\Big|\,\bm{L}_e=\bm{L}\Big)
	\stackrel{\eqref{eq:productForm}}{=} \begin{cases}
	{}_\star\hspace{-1pt}\pi_e(\set{\SSPIN{r},\SSPIN{b}})
	&\textup{if $z\in\set{\SPIN{-},\SPIN{+}}$
		and $e\in\delta v(z)$,}\\
	{}_\star\hspace{-1pt}\pi_e(\SSPIN{y})
	&\textup{if $z\in\set{\SPIN{-},\SPIN{+}}$
		and $e\in\delta v(\SPIN{-} z)$,}\\
	{}_\star\hspace{-1pt}\pi_e(\SSPIN{g}) 
	&\textup{if $z=\SPIN{f}$.}
	\end{cases}
	\]
Moreover, since $(\varsigma_e)^i=\SSPIN{r}$ if and only if $(\sigma_e)^i=\SSPIN{r}$, it follows that
	\[
	\mathbf{P}^f\Big( (\sigma_e)^i=\SSPIN{r}\,\Big|\,\bm{L}_e=\bm{L}\Big)
	\stackrel{\eqref{e:DIVERSE.final.msr.sat.varsigma}}{=}
	(\bm{\zeta}_e)^i(\SSPIN{r}\,|\,\bm{L})
	= {}_\star\hspace{-1pt}\pi_e(\SSPIN{r})\,.
	\]
It follows from the last two displays combined that $\mathbf{P}^f$ satisfies condition~\eqref{e:D.L.diverse.judicious}.
Lastly, since $(\bm{L}^a)_e=(\bm{L}^f)_e$ for all $e$, 
and $\mathbf{P}^a$ satisfied condition \eqref{e:D.L.diverse.clause} by construction,
we can conclude that $\mathbf{P}^f$ also satisfies 
condition~\eqref{e:D.L.diverse.clause}.

We now estimate the entropy of $\mathbf{P}^f$.
Let $\bm{E}_d$ denote the subset of edges $e\in\delta v$ for which $(\mathcal{X}^d)_e\ne(\mathcal{X}^f)_d$. For any edge in $e\in \bm{E}_d$ we must have $(\varsigma^d)_e=\SSPIN{w}\SSPIN{w}$ and $(\varsigma^f)_e\ne\SSPIN{w}\SSPIN{w}$. As a result we can bound
	\begin{align*}
	\mathbb{E}(|\bm{E}_d|)
	&\le \sum_{e\in \delta v}
	\bigg(
	\mathbf{P}^f(\varsigma_e\ne\SSPIN{w}\SSPIN{w})
	- \mathbf{P}^d(\varsigma_e\ne\SSPIN{w}\SSPIN{w})
	\bigg)
	= \sum_{e\in \delta v}
	\sum_{\varsigma\ne\SSPIN{w}\SSPIN{w}}\bigg(
	 \bm{\zeta}_e(\varsigma)
	 - \mathbf{P}^d(\varsigma_e=\varsigma)
	 \bigg) \le 
	 O\bigg( \frac{k^2}{2^{k \epsilon_\infty/2}}\bigg)\,,
\end{align*}
using the same reasoning as for \eqref{e:DIVERSE.Ec.bound}. It then follows by the argument of~\eqref{eq:cXb.cXc.entropyComp} that
	\begin{equation}\label{eq:cXd.cXe.entropyComp}
	\mathcal{H}(\mathbf{P}^d)\le \mathcal{H}(\mathbf{P}^f) + o_k(1)\,.\end{equation}
Combining equations~\eqref{eq:A.to.B.Ent.Comp}, \eqref{eq:cXb.cXc.entropyComp}, \eqref{eq:cXc.cXd.entropyComp},\eqref{eq:cXd.cXe.entropyComp},
and \eqref{eq:a.opt.EntComp} gives
	\[
	\mathcal{H}(\mathbf{P}^f)
	\ge \mathcal{H}(\mathbf{P}^a) - o_k(1)
	\stackrel{\eqref{eq:a.opt.EntComp}}{\ge}
	\mathcal{H}(\mathbf{P}) + \frac1{10^6} - o_k(1)\,.
	\]
This contradicts the assumption that $\mathbf{P}$ is the maximal-entropy measure satisfying constraints
\eqref{e:D.L.diverse.clause}--\eqref{e:D.L.diverse.varsigma}, thereby concluding the proof of the proposition.
\end{proof}

 Without loss of generality we can assume that $\epsilon_\infty$ is much smaller than the other constants 
$\epsilon_1,\epsilon_2,\epsilon_3,\epsilon_4,\epsilon_\circ$ appearing in this section.

We will prove the result by contradiction, so let $v$ be a variable of type $\bm{T}$ which satisfies the conditions of the proposition, but for which the estimate~\eqref{eq:diverseVariableCondition} fails to hold. It will be used repeatedly in the proof that since $v$ is non-defective (Definition~\ref{d:j.defective}), it must be nice, and all clause types neighboring to $v$ must also be nice (Definition~\ref{d:nice}). As in \eqref{e:uX.notation} and \eqref{e:cal.X} we let $X_e\equiv(\sigma_e,\varsigma_e)$. We also denote $\mathcal{X}_e\equiv(X_e,\bm{L}_e)$. We consider the law $\mathbf{P}$ of the random variable 
	\[
	\mathcal{X} \equiv \mathcal{X}_v \equiv (\mathcal{X}_e)_{e\in\delta v}
	\equiv (\smash{\vec{X}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})
	\equiv\bigg((X_e)_{e\in\delta v}, 
	(\bm{L}_e)_{e\in\delta v}\bigg)\,.\]
The measure $\mathbf{P}$ must maximize entropy subject to the following constraints (cf.\ \eqref{e:final.D.L.clause}--\eqref{e:final.D.L.varsigma}):
for all $e\in\delta v$, 
	{\setlength{\jot}{0pt}\begin{alignat}{2}
	\mathbf{P}(\bm{L}_e=\bm{L})
	&=\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
	\quad&&\textup{for all $\bm{L}$,}
	\label{e:D.L.diverse.clause} \\ 
	\mathbf{P}(\sigma^i_e=\sigma^i \,|\,
		\bm{L}_e=\bm{L})
	&= {}_\star\hspace{-1pt}\pi_e(\sigma^i)
	\quad&&\textup{for all $\bm{L}$ and
		 all $\sigma^i\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$,}
	\label{e:D.L.diverse.judicious} \\
	\mathbf{P}(\varsigma_e=\varsigma
		\,|\,\bm{L}_e=\bm{L})
	&=\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	\quad&&\textup{for all $\bm{L}$
		and all $\varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2$.}
	\label{e:D.L.diverse.varsigma}
	\end{alignat}}
Via a series of transformations of the measure $\mathbf{P}$ we will construct another distribution $\mathbf{P}^f$ satisfying the same constraints
\eqref{e:D.L.diverse.clause}--\eqref{e:D.L.diverse.varsigma} but with higher entropy, yielding the required contradiction. The remainder of the proof is outlined as follows:
\begin{enumerate}[--]
\item In \hyperlink{l:DIVERSE.product.Pa}{Part 1}
we define a measure $\mathbf{P}^a$ satisfying
constraints \eqref{e:D.L.diverse.clause}, \eqref{e:D.L.diverse.judicious}, and 
\eqref{eq:relaxedZetaConstraint}, where
\eqref{eq:relaxedZetaConstraint} is a relaxation of
\eqref{e:D.L.diverse.varsigma}. We show that $\mathbf{P}^a$ has a simple explicit form, and has substantially larger entropy than $\mathbf{P}$ (see \eqref{e:rel.ent.diverse.absolute.lbd} below).


\item In \hyperlink{l:DIDERSE.Pa.bounds}{Part 2} we prove probabilistic estimates on various quantities under the measure $\mathbf{P}^a$. Let $\mathcal{X}^a$ denote a sample from $\mathbf{P}^a$; in the rest of the proof we transform $\mathcal{X}^a$ without changing its frozen spin $x=x^a\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$.

\item In \hyperlink{l:DIVERSE.Pb}{Part 3} we transform $\mathcal{X}^a$ into $\mathcal{X}^b$, and in \hyperlink{l:DIVERSE.Pc}{Part 4} we transform $\mathcal{X}^b$ into $\mathcal{X}^c$. In these transformations, $(\varsigma_e)^i$ can only change between \SPIN{red} and \SPIN{white}, so any $(\varsigma_e)^i\in\set{\SSPIN{y},\SSPIN{c}}$ remains unchanged. The transformations combined will guarantee (see \eqref{e:DIVERSE.hat.E.nonempty} below) that in the configuration $\mathcal{X}^c$, if $x=x^c$ has $x^i=z\in\set{\SPIN{-},\SPIN{+}}$, then some $e\in\delta v(z)$ will have $(\sigma^{c,i})_e=\SSPIN{r}$, $(\sigma^c)_e\ne\SSPIN{r}\SSPIN{r}$, and $(\bm{L}^c)_e\in\mathbb{D}\cap\mathbb{L}$. The condition \eqref{e:DIVERSE.hat.E.nonempty} will allow more flexibility to change spins from non-\SPIN{white} to \SPIN{white} in the following step. The law $\mathbf{P}^c$ of $\mathcal{X}^c$ satisfies
\eqref{e:D.L.diverse.clause}, but need not satisfy
\eqref{e:D.L.diverse.judicious} or \eqref{e:D.L.diverse.varsigma}, in particular, it can have less than the correct density of \SPIN{red} spins (see \eqref{eq:Xc.red.marginal.div}
and \eqref{eq:Xc.red.marginal.div2}).

\item In \hyperlink{l:DIVERSE.Pd}{Part 5} we transform $\mathcal{X}^c$ to $\mathcal{X}^d$ by changing $(\varsigma^{c,i})_e\ne\SSPIN{w}$ to $(\varsigma^{d,i})_e=\SSPIN{w}$ in some cases --- the condition \eqref{e:DIVERSE.hat.E.nonempty} from the previous step allows more flexibility to do this without invalidating the configuration. The goal of this step is to create enough \SPIN{white} spins which can be altered in the next step to ensure that the constraints \eqref{e:D.L.diverse.judicious} or \eqref{e:D.L.diverse.varsigma} will be satisfied.
At the same time, we cannot change too many spins to \SPIN{white}, since this could result in too much decrease in entropy.

\item In \hyperlink{l:DIVERSE.Pe}{Part 6} we transform
$\mathcal{X}^d$ to $\mathcal{X}^f$, where we use $\mathcal{X}^f$ rather than $\mathcal{X}^e$ to avoid confusion with edge labels $e\in\delta v$. In this final step we change
 $(\varsigma^{d,i})_e=\SSPIN{w}$
to $(\varsigma^{f,i})_e\ne\SSPIN{w}$ in some cases, such that the law $\mathbf{P}^f$ of $\mathcal{X}^f$ satisfies the original constraints
\eqref{e:D.L.diverse.clause}--\eqref{e:D.L.diverse.varsigma}
(see \eqref{e:DIVERSE.final.msr.sat.varsigma} below).
Finally we show that $\mathbf{P}^f$ does not have much smaller entropy than $\mathbf{P}^a$, and as a result must have substantially larger entropy than $\mathbf{P}$, giving the contradiction.
\end{enumerate}
We now turn to the details of the transformation.\smallskip




\noindent\bemph{\hypertarget{l:DIVERSE.product.Pa}{Part 1}. Product solution $\mathbf{P}^a$ for relaxed constraints.} Let $\mathbf{P}^a$ be the probability measure over configurations $\mathcal{X}$ which maximizes entropy subject to the constraints \eqref{e:D.L.diverse.clause}, \eqref{e:D.L.diverse.judicious}, and (in place of \eqref{e:D.L.diverse.varsigma})
	\begin{equation}\label{eq:relaxedZetaConstraint}
	\mathbf{P}^a(\varsigma_e^i=\varsigma^i
			\,|\,\bm{L}_e=\bm{L})
		=\bm{\zeta}_e(\varsigma^i\,|\,\bm{L})
		\quad\textup{for all $\bm{L}$
			and all
			$\varsigma^i\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}$.}
	\end{equation}
Let us note that the law $\mathbf{P}^a$ has a quite simple form: by the method of Lagrange multipliers, it must be expressible as
(cf.\ \eqref{e:final.D.L.Lagrangian.form})
	\begin{equation}\label{e:DIVERSE.P.a.Lagrangian.form}
	\mathbf{P}^a\Big(
	\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\varsigma}}_{\delta v},
	\smash{\vec{\bm{L}}}_{\delta v} \Big)
	\cong \psi_v(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e\in\delta v}
	\Bigg\{
	\Ind{\sigma_e\sim\varsigma_e}
	\psi_e(\bm{L}_e)
	\prod_{i=1,2}
	\bigg[
	(\beta_e)^i((\sigma_e)^i\,|\,\bm{L}_e)
	(\chi_e)^i( (\varsigma_e)^i\,|\,\bm{L}_e)
	\bigg]
	\Bigg\}\,,
	\end{equation}
where $\psi_v(\smash{\vec{\sigma}}_{\delta v})$ is parametrized as in
\eqref{e:non.compound.weight.functional.form} from Definition~\ref{d:param.weights.Augmented}. A valid solution is given by simply setting $\psi_v\equiv1$,
$\psi_e(\bm{L})=\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)$,
and (cf.\ \eqref{e:ZETA.bstar} and \eqref{e:ZETA.xstar})
	\begin{align*}
	\begin{pmatrix}
	(\beta_e)^i(\SSPIN{r}\,|\,\bm{L})\\
	(\beta_e)^i(\SSPIN{y}\,|\,\bm{L})\\
	(\beta_e)^i(\SSPIN{g}\,|\,\bm{L})
	=(\beta_e)^i(\SSPIN{b}\,|\,\bm{L})\equiv(\beta_e)^i(\SSPIN{c}\,|\,\bm{L})
	\end{pmatrix}
	&= 
	\begin{pmatrix}
	1\\
	[{}_\star\hspace{-1pt}\pi_e(\SSPIN{y})-(\bm{\zeta}_e)^i(\SSPIN{y}\,|\,\bm{L})]/{}_\star\hspace{-1pt}\dot{q}_e(\SSPIN{y})\\
	[{}_\star\hspace{-1pt}\pi_e(\SSPIN{c})-(\bm{\zeta}_e)^i(\SSPIN{c}\,|\,\bm{L})]/{}_\star\hspace{-1pt}\dot{q}_e(\SSPIN{c})
	\end{pmatrix}
	\stackrel{\eqref{e:ZETA.zetastar}}{=} 
	\begin{pmatrix}
	\Theta(1)\\ \Theta(1) \\ \Theta(1)
	\end{pmatrix}\,,\\

	\begin{pmatrix}
	(\chi_e)^i(\SSPIN{r}\,|\,\bm{L})\\
	(\chi_e)^i(\SSPIN{y}\,|\,\bm{L})\\
	(\chi_e)^i(\SSPIN{c}\,|\,\bm{L})\\
	(\chi_e)^i(\SSPIN{w}\,|\,\bm{L})
	\end{pmatrix}
	&=\begin{pmatrix}
	{}_\star\hspace{-1pt}\pi_e(\SSPIN{r})/{}_\star\hspace{-1pt}\dot{q}_e(\SSPIN{r})\\
	(\bm{\zeta}_e)^i(\SSPIN{y}\,|\,\bm{L})
		/[{}_\star\hspace{-1pt}\pi_e(\SSPIN{y})-(\bm{\zeta}_e)^i(\SSPIN{y}\,|\,\bm{L})]\\
	(\bm{\zeta}_e)^i(\SSPIN{c}\,|\,\bm{L})
	/[{}_\star\hspace{-1pt}\pi_e(\SSPIN{c})
		-(\bm{\zeta}_e)^i(\SSPIN{c}\,|\,\bm{L})]\\
	1
	\end{pmatrix}
	\stackrel{\eqref{e:ZETA.zetastar}}{=} 
	\begin{pmatrix}
	\Theta(1/2^k)\\
	O(k^2/2^k)\\
	O(k^2/2^k)\\
	1
	\end{pmatrix}
	\,,\end{align*}
where the estimates on
$(\bm{\zeta}_e)^i(\tau\,|\,\bm{L})$
for $\tau\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}$ come from Lemma~\ref{l:lotsOfAs}. Note that for $e\in\delta v$, $\bm{L}=\bm{L}_e$, $i=1,2$, and $\sigma^i\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$ we have
	\begin{equation}\label{e:product.zeta.msg.simplification}
	(\hat{q}_e)^i(\sigma^i\,|\,\bm{L})\equiv
	(\beta_e)^i(\sigma^i\,|\,\bm{L})
	\sum_{\varsigma^i}
	\Ind{\varsigma^i \sim \sigma^i}
	(\chi_e)^i(\varsigma^i\,|\,\bm{L})
	= \frac{{}_\star\hspace{-1pt}\pi_e(\sigma^i)}{{}_\star\hspace{-1pt}\dot{q}_e(\sigma^i)}\,,
	\end{equation}
where we emphasize that the right-hand side of \eqref{e:product.zeta.msg.simplification} does not depend on $\bm{L}$. Indeed,
	\[
	(\hat{q}_e)^i(\SSPIN{r}\,|\,\bm{L})
	= (\beta_e)^i(\SSPIN{r}\,|\,\bm{L})
	(\chi_e)^i(\SSPIN{r}\,|\,\bm{L})
	= \frac{{}_\star\hspace{-1pt}\pi_e(\SSPIN{r})}{{}_\star\hspace{-1pt}\dot{q}_e(\SSPIN{r})}\,,
	\]
which verifies \eqref{e:product.zeta.msg.simplification} for the case $\sigma^i=\SSPIN{r}$. Next,
	\begin{align*}
	(\hat{q}_e)^i(\SSPIN{y}\,|\,\bm{L})
	&= (\beta_e)^i(\SSPIN{y}\,|\,\bm{L})
	\bigg(
	(\chi_e)^i(\SSPIN{y}\,|\,\bm{L})
	+(\chi_e)^i(\SSPIN{w}\,|\,\bm{L})\bigg)\\
	&= \frac{{}_\star\hspace{-1pt}\pi_e(\SSPIN{y})-(\bm{\zeta}_e)^i(\SSPIN{y}\,|\,\bm{L})}
		{{}_\star\hspace{-1pt}\dot{q}_e(\SSPIN{y})}
	\cdot\Bigg\{
	\frac{(\bm{\zeta}_e)^i(\SSPIN{y}\,|\,\bm{L})}
		{{}_\star\hspace{-1pt}\pi_e(\SSPIN{y})-(\bm{\zeta}_e)^i(\SSPIN{y}\,|\,\bm{L})}+1
	\Bigg\}
	= \frac{{}_\star\hspace{-1pt}\pi_e(\SSPIN{y})}{{}_\star\hspace{-1pt}\dot{q}_e(\SSPIN{y})}\,,
	\end{align*}
which verifies \eqref{e:product.zeta.msg.simplification} for the case $\sigma^i=\SSPIN{y}$. A similar calculation gives
\eqref{e:product.zeta.msg.simplification} for $\sigma^i\in\set{\SSPIN{g},\SSPIN{b}}$. It follows from \eqref{e:product.zeta.msg.simplification},
together with the identity ${}_\star\hspace{-1pt}\pi_e(\tau)/{}_\star\hspace{-1pt}\dot{q}_e(\tau) \cong {}_\star\hspace{-1pt}\hat{q}_e(\tau)$,
that the marginal of \eqref{e:DIVERSE.P.a.Lagrangian.form} over
$(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v})$ is given by
	\begin{align}\nonumber
	\mathbf{P}^a\Big(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v}\Big)
	&\cong
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e\in\delta v}\Bigg\{
	\pi_{\mathscr{D}}(\bm{L}_e\,|\,\bm{t}_e)
	\prod_{i=1,2}
	{}_\star\hspace{-1pt}\hat{q}_e((\sigma_e)^i)\Bigg\} \\
	& \cong
	{}_\star\hspace{-1pt}\dot{\nu}_v((\smash{\vec{\sigma}}_{\delta v})^1)
	{}_\star\hspace{-1pt}\dot{\nu}_v((\smash{\vec{\sigma}}_{\delta v})^2)
	\prod_{e\in\delta v}
	\pi_{\mathscr{D}}(\bm{L}_e\,|\,\bm{t}_e)
	\,,\label{eq:productForm}
	\end{align}
where ${}_\star\hspace{-1pt}\dot{\nu}_v$ is as in 
\eqref{e:opt.variable.tuple.measure.star}. In particular, we see that under $\mathbf{P}^a$,
the random variables $(\smash{\vec{\sigma}}_{\delta v})^1$, $(\smash{\vec{\sigma}}_{\delta v})^2$, and $\smash{\vec{\bm{L}}}_e$ (for $e\in\delta v$) are mutually independent. Moreover, conditional on $(\smash{\vec{\sigma}},\smash{\vec{\bm{L}}})_{\delta v}$, 
the $(\varsigma_e)^i$ are all independent from one another, with conditional laws depending only on
 $(\bm{L}_e,(\sigma_e)^i)$. If $(\sigma_e)^i=\SSPIN{r}$ then $(\varsigma_e)^i= \SSPIN{r} $ also. 
If $(\sigma_e)^i=\SSPIN{y}$ then $(\varsigma_e)^i\in\set{\SSPIN{y},\SSPIN{w}}$; and the conditional probability of 
$(\varsigma_e)^i=\SSPIN{y}$ is given by
	\begin{equation}\label{eq:ColouringProbs.yel}
	\mathbf{P}^a
	\bigg( (\varsigma_e)^i= \SSPIN{y}
	\,\bigg|\,
	\bm{L}_e=\bm{L}, (\sigma_e)^i=\SSPIN{y}
	\bigg)
	= \frac{(\chi_e)^i(\SSPIN{y}\,|\,\bm{L})}
	{(\chi_e)^i(\SSPIN{y}\,|\,\bm{L})+(\chi_e)^i(\SSPIN{w}\,|\,\bm{L})}
	= \frac{(\bm{\zeta}_e)^i(\SSPIN{y}\,|\,\bm{L})}
		{{}_\star\hspace{-1pt}\pi_e(\SSPIN{y})}
	\le O\bigg(\frac{k^2}{2^k}\bigg)\,,
	\end{equation}
where the last inequality follows by
Lemma~\ref{l:lotsOfAs}. Similarly, if $(\sigma_e)^i =\tau\in\set{\SSPIN{g},\SSPIN{b}}$ then
$(\varsigma_e)^i\in\set{\SSPIN{c},\SSPIN{w}}$; and the conditional probability of $(\varsigma_e)^i=\SSPIN{c}$ is given by
	\begin{equation}\label{eq:ColouringProbs.cya}
	\mathbf{P}^a
	\bigg( (\varsigma_e)^i=\SSPIN{c}
	\,\bigg|\,
	\bm{L}_e=\bm{L}, (\sigma_e)^i=\tau
	\bigg)
	= \frac{(\bm{\zeta}_e)^i(\SSPIN{c}\,|\,\bm{L})}
		{{}_\star\hspace{-1pt}\pi_e(\SSPIN{b})+{}_\star\hspace{-1pt}\pi_e(\SSPIN{g})}
	\le O\bigg(\frac{k^2}{2^k}\bigg)
	\end{equation}
for $\tau\in\set{\SSPIN{g},\SSPIN{b}}$. The independence between the two copies $i=1,2$ gives furthermore
	\begin{equation}\label{e:DIVERSE.Pa.RYCsq}
	\mathbf{P}^a\bigg(\varsigma_e\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	= \prod_{i=1}^2 \mathbf{P}^a\bigg(
		(\varsigma_e)^i\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg) 
	\le O\bigg( \frac{k^4}{4^k}\bigg)\,.
	\end{equation}
Note also that if $x=x_v\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$ is the frozen spin, then $x^1$ and $x^2$ are independent under $\mathbf{P}^a$, and the marginal law of each $x^i$ is determined by the ${}_\star\hspace{-1pt}\pi_e$ for $e\in\delta v$.
Since we assumed that $v$ is non-defective, it follows that
	\begin{equation}\label{eq:diverseVariableCondition.a}
	\max\Bigg\{
	\bigg|\mathbf{P}^a\Big( x =z \Big)
		 -\frac14\bigg|
		: z\in\set{\SPIN{-},\SPIN{+}}^2
		\Bigg\} =o_k(1)\,.
	\end{equation}
If $\mathbf{P}'$ is any other probability measure satisfying the same constraints as $\mathbf{P}^a$ (namely \eqref{e:D.L.diverse.clause}, \eqref{e:D.L.diverse.judicious}, and \eqref{eq:relaxedZetaConstraint}), then
it follows by the same derivation as
for \eqref{e:relative.entropy.with.Lagrangian} that
the relative entropy between $\mathbf{P}'$ and $\mathbf{P}^a$ 
satisfies
	\begin{equation}\label{e:relent.a.b.transform}
	\mathcal{H}(\mathbf{P}'\,|\,\mathbf{P}^a)
	= \bigg\langle \mathbf{P}',\ln \frac{\mathbf{P}'}{\mathbf{P}^a}
		\bigg\rangle
	=\mathcal{H}(\mathbf{P}^a) -\mathcal{H}(\mathbf{P}')\,.
	\end{equation}
Now suppose that $x\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$ is the frozen spin corresponding to $\mathcal{X}\sim\mathbf{P}$ (meaning that its law fails condition \eqref{eq:diverseVariableCondition}), while $x^a\equiv(x^{a,1},x^{a,2})\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$ is the frozen spin corresponding to $\mathcal{X}^a\sim\mathbf{P}^a$ (so that its law satisfies condition 
\eqref{eq:diverseVariableCondition.a}). Therefore we obtain
	\begin{equation}\label{e:rel.ent.diverse.absolute.lbd}
	\mathcal{H}(\mathbf{P}\,|\,\mathbf{P}^a) \ge
	\mathcal{D}_\textup{KL}(x\,|\,x^a)
	\ge \frac1{10^6}\,.
	\end{equation}
It follows by combining the last few calculations that
	\begin{equation}\label{eq:a.opt.EntComp}
	\mathcal{H}(\mathbf{P}^a)
	\stackrel{\eqref{e:relent.a.b.transform}}{=}
	\mathcal{H}(\mathbf{P})
	+\mathcal{H}(\mathbf{P}\,|\,\mathbf{P}^a)
	\stackrel{\eqref{e:rel.ent.diverse.absolute.lbd}}{\ge}
	\mathcal{H}(\mathbf{P})
	+\frac1{10^6}\,.
	\end{equation}
In the remainder of the proof we will make a sequence of transformations, from $\mathbf{P}^a$ to $\mathbf{P}^b$ and so on, until we arrive at a measure
$\mathbf{P}^f$ that satisfies the original constraints \eqref{e:D.L.diverse.clause}--\eqref{e:D.L.diverse.varsigma}. We will show that
none of the transformations substantially reduce the entropy. Thus the final measure $\mathbf{P}^f$
will have similar entropy as $\mathbf{P}^a$, and hence will have greater entropy than $\mathbf{P}$ by \eqref{e:rel.ent.diverse.absolute.lbd}. But we assumed $\mathbf{P}$ to be the measure of maximal entropy satisfying constraints \eqref{e:D.L.diverse.clause}--\eqref{e:D.L.diverse.varsigma}, so this will give the desired contradiction. The measures $\mathbf{P}^a$ through $\mathbf{P}^f$ will all be coupled together, and the frozen spin $x$ will be left unchanged throughout the transformations.\smallskip

\noindent\bemph{\hypertarget{l:DIDERSE.Pa.bounds}{Part 2}. Bounds on $\mathbf{P}^a$.} Using the assumed bound \eqref{e:assumption.notD.notL} on $\cancel{\mathbb{D}}(v)$ and $\cancel{\mathbb{L}}(v)$, we can select a subset of four distinct edges incident to $v$,
	\begin{equation}\label{e:four.distinct.edges}
	\bm{E}\equiv
	\bigg\{e^{\SPIN{+},1},e^{\SPIN{+},2},
	e^{\SPIN{-},1},e^{\SPIN{-},2}\bigg\}
	\subset \delta v\,,\end{equation}
where $e^{\SPIN{+},i}\in\delta v(\SPIN{+})$,
and $e^{\SPIN{-},i}\in\delta v(\SPIN{-})$,
such that each $e\in\bm{E}$ satisfies
	\begin{equation}\label{eq:bEdefin}
	\sum_{\bm{L}}
		\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e) 
		\Ind{\bm{L}\in \mathbb{D}\cap\mathbb{L}}
		\ge\frac12\,.\end{equation}
For a configuration $\mathcal{X}$ as in \eqref{e:cal.X}, we define the following quantities:
	\begin{align*}
\mathfrak{R}^i&\equiv
	\mathfrak{R}^i(\mathcal{X})
	\equiv \sum_{e\in\delta v\setminus \bm{E}}
	\mathbf{1}\Big\{
	(\sigma_e)^i=\SSPIN{r}
	\Big\}\,,\\
\mathfrak{H}
	&\equiv\mathfrak{H}(\mathcal{X})
	\equiv\sum_{e\in\delta v\setminus \bm{E}} 
	\sum_{i=1,2}
	\mathbf{1}\Big\{
	(\varsigma_e)^i\in\{\SSPIN{r},\SSPIN{y},\SSPIN{c}\}
	\Big\}\,,\\
	\mathfrak{W}
	&\equiv \mathfrak{W}(\mathcal{X})
	\equiv\sum_{e\in\delta v\setminus \bm{E}} 
		\mathbf{1}\Big\{
		\varsigma_e=\SSPIN{w}\SSPIN{w},
		\bm{L}_e \in \mathbb{D}\cap\mathbb{L}
		\Big\}\,,\\
	T&\equiv T(\mathcal{X})
		\equiv\mathbf{1}
		\bigg\{\mathfrak{W}(\mathcal{X})
			\le \bigg(1-\frac1{k^{10}}\bigg)
				|\delta v|\bigg\}\,.
	\end{align*}
We now prove some straightforward probabilistic bounds (under the measure $\mathbf{P}^a$) for the above quantities. For $e\in\delta v$ let $R_e$ denote independent Bernoulli random variables with
	\begin{equation}\label{e:DIVERSE.Re}
	\mathbb{P}(R_e=1) 
	= \frac{{}_\star\hspace{-1pt}\hat{q}_e(\SSPIN{r})}{{}_\star\hspace{-1pt}\hat{q}_e(\set{\SSPIN{r},\SSPIN{b}})}
	= \Theta\bigg(\frac1{2^k}\bigg)\,.\end{equation}
We see from \eqref{eq:productForm} that under $\mathbf{P}^a(\cdot\,|\,x^i=\SPIN{+})$, the total number of edges $e\in\delta v$ with $(\sigma_e)^i=\SSPIN{r}$ is equidistributed as the sum of $R_e$ over $e\in\delta v(\SPIN{+})$, conditioned on that sum being strictly positive. Therefore
	\begin{align}\nonumber
	\mathbf{P}^a\Bigg(
		\sum_{i=1,2}\mathfrak{R}^i\ge
		\frac{k^3}{2} \Bigg)
	&\le \mathbf{P}^a \Bigg(
	\sum_{i=1,2}
	\sum_{e\in\delta v} \Ind{(\sigma_e)^i=\SSPIN{r}}
	\ge \frac{k^3}{2} \Bigg)
	\le O(1)\max_{z\in\set{\SPIN{-},\SPIN{+}}}
	\Bigg\{
	\frac{\mathbb{P}( \sum_{e\in\delta v(z)} R_e \ge k^3/4)}
		{\mathbb{P}(\sum_{e\in\delta v(z)} R_e \ge1)}
		\Bigg\}\\
	&\le\frac{\exp(-\Omega(k^3\ln k))
	}{1-o_k(1)}
	\le \frac1{\exp(\Omega(k^3\ln k))}\,,
	\label{eq:frakR.bound}
	\end{align}
where the second-to-last inequality follows by a Chernoff bound. Next recall from \eqref{eq:ColouringProbs.yel} and 
\eqref{eq:ColouringProbs.cya} that
under $\mathbf{P}^a$, conditional on 
$(\sigma_e)^i\in\set{\SSPIN{y},\SSPIN{g},\SSPIN{b}}$, the chance for $(\varsigma_e)^i\in\set{\SSPIN{y},\SSPIN{c}}$
is $O(k^2/2^k)$. Thus, under $\mathbf{P}^a$,
the total number of edges $e$ with $(\varsigma_e)^i\in\set{\SSPIN{y},\SSPIN{c}}$ for either $i=1,2$ is stochastically dominated by a binomial random variable with $\Theta(k2^k)$ trials
and success probability $\Theta(1/2^k)$. It follows by another Chernoff bound, and by combining with \eqref{eq:frakR.bound}, that
	\begin{equation}\label{e:frakH.bound}
	\mathbf{P}^a\Big(\mathfrak{H} \ge k^3\Big)
	\le \mathbf{P}^a\Bigg(
		\sum_{e\in\delta v}\sum_{i=1,2}
		\mathbf{1}\Big\{
		(\varsigma_e)^i\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}
		\Big\} \ge k^3
		\Bigg)
	\le\frac1{\exp(\Omega(k^3\ln k))}\,.\end{equation}
Next recall from \eqref{eq:productForm}
that the $\bm{L}_e$ for $e\in\delta v$ are mutually independent under $\mathbf{P}^a$. The assumption \eqref{e:assumption.notD.notL} bounds the expected number (under $\mathbf{P}^a$) of edges $e\in\delta v$ with $\bm{L}_e\notin\mathbb{D}\cap\mathbb{L}$. It follows by Azuma's inequality that
	\begin{equation}\label{eq:nonDiverseLightBound}
	\mathbf{P}^a
	\Bigg(\sum_{e\in\delta v}
	\Ind{\bm{L}_e\notin\mathbb{D}\cap\mathbb{L}}
	\ge \frac{k2^k}{2^{k\epsilon_\infty}} \Bigg)
	\le 
	\frac1{\exp (\Omega(2^{k(1-2\epsilon_\infty)}k))}\,.\end{equation}
Combining with \eqref{e:frakH.bound}, 
and recalling the definitions of $\mathfrak{W}$ and $T$, we obtain
	\begin{align}\nonumber
	\mathbf{P}^a(T=1) &=
	\mathbf{P}^a\Bigg(\mathfrak{W}
		\le \bigg(1-\frac1{k^{10}}\bigg)
		|\delta v|
		 \Bigg)\\
	&\le
	\mathbf{P}^a
	\Bigg(
	\max\bigg\{ \mathfrak{H} 
	,\sum_{e\in\delta v}
	\Ind{\bm{L}_e\notin\mathbb{D}\cap\mathbb{L}}
	\bigg\} \ge
	\frac{|\delta v|}{3k^{10}}\Bigg)
	\le \frac1{\exp(\Omega(k^3\ln k))}\,.
	\label{eq:T2Bound}
	\end{align}
Recall from \eqref{e:four.distinct.edges} the choice of four distinct edges $\bm{E}$ from $\delta v$. 
For each $e\in\bm{E}$ define
	\begin{equation}\label{e:DIVERSE.Gm}
	\Gamma(e)\equiv 
	\begin{cases}
	1&\textup{if $T(\mathcal{X}^a)=1$, 
		$e=e^{\SPIN{+},i}$, and $x^{a,i}=\SPIN{+}$,}\\
	1&\textup{if $T(\mathcal{X}^a)=1$, 
		$e=e^{\SPIN{-},i}$, and $x^{a,i}=\SPIN{-}$,}\\
	0&\textup{otherwise.}
	\end{cases}\end{equation}
In the first transformation (described below), given $\mathcal{X}^a$ we will construct a modified configuration $\mathcal{X}^b$ in which $(\sigma_e)^i=\SSPIN{r}$ and $\bm{L}_e\in\mathbb{D}\cap\mathbb{L}$ whenever 
$e=e^{\SPIN{\textpm},i}$ with $\Gamma(e)=1$. (This ensures that a frozen spin $x^i\in\set{\SPIN{-},\SPIN{+}}$ has at least one incident $\SPIN{red}$ edge in $\delta v(x^i)$, and gives more flexibility to adjust the colors on the other incident edges.) For $e\in\bm{E}$ and $z\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$ define
	\begin{equation}\label{e:DIVERSE.p.z.e.ubd}
	p_z(e)
	\equiv\mathbf{P}^a(\Gamma(e)=1,x=z)
	\le \mathbf{P}^a(T=1)
	\stackrel{\eqref{eq:T2Bound}}{\le}
	\frac{1}{\exp(\Omega(k^3\ln k))}\,.
	\end{equation}
Note the definition of $\Gamma(e)$ implies
$p_z(e^{\SPIN{+},i})=0$ if $z^i\ne\SPIN{+}$, and likewise
$p_z(e^{\SPIN{-},i})=0$ if $z^i\ne\SPIN{-}$. For $e\in\bm{E}$ we also let
	\[r_z(e)
	\equiv
	\mathbf{P}^a\bigg(
	\bm{L}_e\in\mathbb{D}\cap\mathbb{L},
	x=z,(\sigma_e)^i=\SSPIN{r},\sigma_e\ne\SSPIN{r}\SSPIN{r},
	\mathfrak{R}^i\ge2, T=0
	\bigg)\,.
	\]
Note having $(\sigma_e)^i=\SSPIN{r}$ necessitates $x^i=\SPIN{+}$, so 
$r_z(e^{\SPIN{+},i})=0$ if $z^i\ne\SPIN{+}$
and $r_z(e^{\SPIN{-},i})=0$ if $z^i\ne\SPIN{-}$. In all other cases we claim that $r_z(e)\ge \Omega(1)/4^k$. Without loss of generality it suffices to consider the case $e=e^{\SPIN{+},1}$ and $z\in\set{\SPIN{+}}\times\set{\SPIN{-},\SPIN{+},\SPIN{f}}$. In this case, recalling the bound
\eqref{eq:T2Bound} gives
	\[
	r_z(e)
	\ge
	\mathbf{P}^a\bigg(
	\bm{L}_e\in\mathbb{D}\cap\mathbb{L},
	x^2=z^2,\sigma_e\in\set{\SSPIN{r}}
		\times\set{\SSPIN{y},\SSPIN{g},\SSPIN{b}},
		\mathfrak{R}^i\ge2
	\bigg)
	-\frac1{\exp(\Omega(k^3\ln k))}\,.\]
Next recall from \eqref{eq:productForm} that $(\smash{\vec{\sigma}}_{\delta v})^1$, $(\smash{\vec{\sigma}}_{\delta v})^2$, and $\bm{L}_e$ ($e\in\delta v$) are mutually independent under $\mathbf{P}^a$. It follows by straightforward calculations that for any $\bm{L}$ we have
	\[
	\mathbf{P}^a\bigg(
	\mathfrak{R}^i\ge2
	\,\bigg|\,\bm{L}_e=\bm{L},
	x^2=z^2,\sigma_e\in\set{\SSPIN{r}}
		\times\set{\SSPIN{y},\SSPIN{g},\SSPIN{b}}\bigg)
	\ge 1-o_k(1)\,.
	\]
Combining with \eqref{eq:bEdefin} gives
	\begin{equation}\label{eq:rzBound}
	r_z(e)
	\ge
	\frac{1-o_k(1)}{2}
	\mathbf{P}^a\bigg(
	(\sigma_e)^1=\SSPIN{r}
	\bigg)
	\mathbf{P}^a\bigg(x^2=z^2,
	(\sigma_e)^2\ne\SSPIN{r}
	\bigg)-\frac1{\exp(\Omega(k^3\ln k))}
	\ge \frac{\Omega(1)}{4^k}\,,\end{equation}
as claimed. It follows by comparing \eqref{e:DIVERSE.p.z.e.ubd} with \eqref{eq:rzBound} that $p_z(e)/r_z(e)=o_k(1)$. For $e\in\bm{E}$,
we define Bernoulli random variables $\Xi(e)$ such that if $r_z(e)=0$ then $\Xi(e)\equiv0$, and otherwise if $e=e^{\SPIN{\textpm},i}$ with $r_z(e)>0$ then
	\begin{equation}\label{e:DIVERSE.def.Xi}
	\mathbf{P}^a\bigg(
	\Xi(e) = 1 \,\bigg|\, x=z,
		\mathcal{X}^a=\mathcal{X}\bigg)
	= \frac{p_z(e)}{r_z(e)}
	\mathbf{1}\bigg\{
	\bm{L}_e \in \mathbb{D}\cap \mathbb{L}, x=z,
	(\sigma_e)^i=\SSPIN{r},
	\sigma_e\ne\SSPIN{r}\SSPIN{r}, 
	\mathfrak{R}^i\geq 2,T=0
	\bigg\}\end{equation}
(for all possible values of $z,\mathcal{X}$). It then follows from the definition of $r_z(e)$ that for all $z\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$ we have
	\begin{equation}\label{eq:GammaXiEquality2}
	\mathbf{P}^a\bigg(
	\Xi(e) = 1,x=z\bigg)
	=p_z(e) =\mathbf{P}^a\bigg(
	\Gamma(e) = 1,x=z\bigg)\,,\end{equation}
and consequently $\mathbf{P}^a(\Xi(e) = 1)=\mathbf{P}^a(\Gamma(e) = 1)$. Further, by the independence properties of $\mathbf{P}^a$ that we see from the expression \eqref{eq:productForm}, we have
	\begin{equation}\label{eq:cond.L.Xi}
	\mathbf{P}^a\Bigg(
		\bm{L}_e=\bm{L}
		\,\Bigg|\, \Xi(e) = 1, \Big(\sigma_e,
			\big(\sigma_{e'},\varsigma_{e'},\bm{L}_{e'}\big)_{e'\in
				\delta v\setminus e}\Big)
				\Bigg)
	= \pi_{\mathscr{D}}\Big(\bm{L}\,
		\Big|\,\bm{t}_e, \bm{L}_e \in \mathbb{D}\cap \mathbb{L}
		\Big)\,.\end{equation}
This concludes our estimates on $\mathbf{P}^a$, and we now turn to the construction of $\mathbf{P}^b$.\smallskip

\noindent\bemph{\hypertarget{l:DIVERSE.Pb}{Part 3}. Construction of $\mathbf{P}^b$.} Recall \eqref{e:four.distinct.edges} that $\bm{E}$ is a subset of four distinct edges in $\delta v$. In the above we defined Bernoulli random variables $\Gamma(e)$ and $\Xi(e)$ for $e\in\bm{E}$. Recall moreover that $\Gamma(e)=1$ can only occur on the event $T=T(\mathcal{X}^a)=1$, while $\Xi(e)=1$ can only occur on the event $T=T(\mathcal{X}^a)=0$, so in particular we can never have $\Gamma(e)=\Xi(e)=1$. In the construction we will essentially ``swap'' the events $\Gamma(e)=1$ and $\Xi(e)=1$.
To make this precise, recall that we write $\mathcal{X}_e\equiv(\sigma_e,\varsigma_e,\bm{L}_e)$. Given $\mathcal{X}^a\sim\mathbf{P}^a$, we let $\mathcal{X}^b$ be defined as follows:
\begin{enumerate}[--]
\item If $e\in\delta v\setminus\bm{E}$ then set $(\mathcal{X}^b)_e=(\mathcal{X}^a)_e$.
\item If $e\in\bm{E}$ with $\Gamma(e)=\Xi(e)=0$ then we also set $(\mathcal{X}^b)_e=(\mathcal{X}^a)_e$.
\item If $e\in\bm{E}$ with $\Gamma(e)=1$ (hence $\Xi(e)=0$),
and $x_v=z$, then we let $(\mathcal{X}^b)_e$ be sampled from the law
	\begin{equation}\label{e:swap.Gamma.Xi.1}
	\mathbf{P}^b\bigg(\mathcal{X}_e\in\cdot \,\bigg|\, x_v=z,\Gamma(e)=1\bigg)
	=\mathbf{P}^a\bigg(\mathcal{X}_e\in\cdot \,\bigg|\, x_v=z,\Xi(e)=1\bigg)\,.
	\end{equation}
\item If $e\in\bm{E}$ with $\Xi(e)=1$ (hence $\Gamma(e)=0$),
and $x_v=z$, then we let 
$(\mathcal{X}^b)_e$ be sampled from the law
	\begin{equation}\label{e:swap.Gamma.Xi.2}
	\mathbf{P}^b\bigg(\mathcal{X}_e\in\cdot \,\bigg|\, x_v=z,\Xi(e)=1\bigg)
	=\mathbf{P}^a\bigg(\mathcal{X}_e\in\cdot \,\bigg|\, x_v=z,\Gamma(e)=1\bigg)\,.
	\end{equation}
\end{enumerate}
This results in a valid configuration $\mathcal{X}^b$ which has the same frozen spin as $\mathcal{X}^a$, that is, $x^a=x^b\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$. For the sake of concreteness, we give two examples of the above construction:
\begin{enumerate}[(a)]
\item \textit{Example on event $T=1$.} Suppose we have $\mathcal{X}^a\sim\mathbf{P}^a$ with frozen spin $x^a=\SPIN{+}\SPIN{+}$, such that $T=T(\mathcal{X}^a)=1$. In this case it follows from the definition \eqref{e:DIVERSE.Gm} of $\Gamma(e)$ that $\Gamma(e^{\SPIN{+},1})=\Gamma(e^{\SPIN{+},2})=1$. Since $x^a=\SPIN{+}\SPIN{+}$, we must have $(\sigma^a)_e\in\set{\SSPIN{r},\SSPIN{b}}^2$ for $e\in\set{e^{\SPIN{+},1},e^{\SPIN{+},2}}$. The resampling step \eqref{e:swap.Gamma.Xi.1} results in a modified configuration $\mathcal{X}^b$. It follows from the definition \eqref{e:DIVERSE.def.Xi} of $\Xi(e)$ that in the modified configuration,
	{\setlength{\jot}{0pt}\begin{align*}
	&\textup{$(\sigma^b)_e=\SSPIN{r}\SSPIN{b}$ for $e = e^{\SPIN{+},1}$,}\\
	&\textup{$(\sigma^b)_e=\SSPIN{b}\SSPIN{r}$ for $e = e^{\SPIN{+},2}$.}
	\end{align*}}
Thus, for $e=e^{\SPIN{\textpm},i}$ with $\Gamma(e)=1$,
the procedure \eqref{e:swap.Gamma.Xi.1} makes
$(\sigma_e)^i$ marginally more likely to be $\SPIN{red}$,
but makes $\sigma_e$ less likely to be $\SSPIN{r}\SSPIN{r}$.

\item \textit{Example on event $T=0$.} 
Suppose we have $\mathcal{X}^a\sim\mathbf{P}^a$ with frozen spin $x^a=\SPIN{+}\SPIN{+}$, such that $T=T(\mathcal{X}^a)=0$. Recalling \eqref{e:DIVERSE.def.Xi}, suppose that we have $\Xi(e^{\SPIN{+},1})=1$
while $\Xi(e^{\SPIN{+},2})=0$. In particular, this means for $e=e^{\SPIN{+},1}$ we must have $(\sigma^a)_e=\SSPIN{r}\SSPIN{b}$. The resampling step \eqref{e:swap.Gamma.Xi.2} results in a modified configuration $\mathcal{X}^b$. It follows from the definition \eqref{e:DIVERSE.Gm} of $\Gamma(e)$ that in the modified configuration we must have $(\sigma^b)_e \in \set{\SSPIN{r},\SSPIN{b}}^2$
for $e=e^{\SPIN{+},1}$. Thus, for $e=e^{\SPIN{\textpm},i}$ with $\Xi(e)=1$,
the procedure \eqref{e:swap.Gamma.Xi.2}
makes $(\sigma_e)^i$ marginally less likely to be $\SPIN{red}$,
but makes $\sigma_e$ more likely to be $\SSPIN{r}\SSPIN{r}$.
\end{enumerate}
We let $\mathbb{P}$ denote the joint law of $(\mathcal{X}^a,\mathcal{X}^b)$, and let $\mathbf{P}^b$ denote the marginal law of $\mathcal{X}^b$. Note that $\mathbf{P}^a$ and $\mathbf{P}^b$ have the same edge marginals: for $e\in\delta v\setminus \bm{E}$ it is clear that $(\mathcal{X}^a)_e$ and $(\mathcal{X}^b)_e$ have the same marginal law, since in the coupling we set $(\mathcal{X}^b)_e=(\mathcal{X}^a)_e$.
For $e\in\bm{E}$, we have
	{\setlength{\jot}{0pt}\begin{align}\nonumber
	&\mathbf{P}^b(\mathcal{X}_e\in\cdot\,|\, x_v=z,
		\Gamma(e)+\Xi(e)=1) \\ \nonumber
	&=\mathbf{P}^a(\Gamma(e)=1\,|\,x_v=z)
	\mathbf{P}^b(\mathcal{X}_e\in\cdot\,|\, x_v=z,\Gamma(e)=1)
	+\mathbf{P}^a(\Xi(e)=1\,|\,x_v=z)
	\mathbf{P}^b(\mathcal{X}_e\in\cdot\,|\, x_v=z,\Xi(e)=1)\\ \nonumber
	&=
	\mathbf{P}^a(\Xi(e)=1\,|\,x_v=z)
	\mathbf{P}^a(\mathcal{X}_e\in\cdot\,|\, x_v=z,\Xi(e)=1)
	+\mathbf{P}^a(\Gamma(e)=1\,|\,x_v=z)
	\mathbf{P}^a(\mathcal{X}_e\in\cdot\,|\, x_v=z,\Gamma(e)=1)\\
	&=\mathbf{P}^a(\mathcal{X}_e\in\cdot\,|\, x_v=z,
		\Gamma(e)+\Xi(e)=1)\,,
	\label{e:DIVERSE.ab.same.mgls}
	\end{align}}
where the transition to the third line uses \eqref{eq:GammaXiEquality2}, \eqref{e:swap.Gamma.Xi.1}, and \eqref{e:swap.Gamma.Xi.2}. This verifies that $\mathbf{P}^b(\mathcal{X}_e\in\cdot)=\mathbf{P}^a(\mathcal{X}_e\in\cdot)$ for all $e\in\delta v$, so the measure $\mathbf{P}^b$ again satisfies the constraints \eqref{e:D.L.diverse.clause}, \eqref{e:D.L.diverse.judicious}, and \eqref{eq:relaxedZetaConstraint}.
We now compare the entropy of $\mathbf{P}^a$ and $\mathbf{P}^b$. As above, denote $T=T(\mathcal{X}^a)$. Write $\bm{E}_a\equiv\set{e\in\bm{E}:\Gamma(e)+\Xi(e)=1}$. Denote $\mathcal{X}\equiv(\mathcal{Y},\mathcal{Z})$ where
	{\setlength{\jot}{0pt}\begin{align*}
	\mathcal{Y}&\equiv (\mathcal{X}_e : e\in\bm{E}_a)\,,\\
	\mathcal{Z}&\equiv (\mathcal{X}_e : e\in\delta v\setminus\bm{E}_a)\,.
	\end{align*}}
If $\bm{E}_a=\varnothing$ then $\mathcal{Y}$ is the null vector. Likewise denote $\smash{\vec{X}}_{\delta v}\equiv (Y,Z)$
where $Y\equiv (X_e:e\in\bm{E}_a)$. We then have
	{\setlength{\jot}{0pt}\begin{align}\nonumber
	\mathcal{H}(\mathcal{X}^b) 
	&\ge\mathcal{H}(T,\bm{E}_a,\mathcal{Z}^b)
		+\mathcal{H}( \mathcal{Y}^b\,|\, T,\bm{E}_a,\mathcal{Z}^b)
		-\mathcal{H}(T)-\mathcal{H}(\bm{E}_a)\\
	&=\mathcal{H}(T,\bm{E}_a,\mathcal{Z}^b)
		+\mathcal{H}( (\smash{\vec{\bm{L}}}^b)_{\bm{E}_a}\,|\, T,\bm{E}_a,\mathcal{Z}^b)
		+\mathcal{H}( Y^b\,|\, T,\bm{E}_a,\mathcal{Z}^b,(\smash{\vec{\bm{L}}}^b)_{\bm{E}_a})
		-\mathcal{H}(T)-\mathcal{H}(\bm{E}_a)
	\label{eq:EntDecompB}\,,\\ \nonumber
	\mathcal{H}(\mathcal{X}^a) 
	&\le \mathcal{H}(T,\bm{E}_a,\mathcal{Z}^a) +
		\mathcal{H}(\mathcal{Y}^a\,|\,T,\bm{E}_a,\mathcal{Z}^a)\\
	&= \mathcal{H}(T,\bm{E}_a,\mathcal{Z}^a)
		+\mathcal{H}((\smash{\vec{\bm{L}}}^a)_{\bm{E}_a}\,|\,T,\bm{E}_a,\mathcal{Z}^a)
		+\mathcal{H}(Y^a\,|\,T,\bm{E}_a,\mathcal{Z}^a,(\smash{\vec{\bm{L}}}^a)_{\bm{E}_a})
		\,.
	\label{eq:EntDecompA}
	\end{align}}
Recall that the edges outside $\bm{E}_a$ are left unchanged by the transformation from $\mathcal{X}^a$ to $\mathcal{X}^b$, so
	\begin{equation}\label{e:DIVERSE.non.swapped.part}
	\mathcal{H}\bigg(T,\bm{E}_a,\mathcal{Z}^b\bigg)
	=\mathcal{H}\bigg(T,\bm{E}_a,\mathcal{Z}^a\bigg)\,.\end{equation}
Next, \eqref{eq:T2Bound} and \eqref{eq:GammaXiEquality2} together imply that
	\[
	\mathbf{P}^a(\bm{E}_a\ne\varnothing) 
	\le O\Big( \mathbf{P}^a(T=1)\Big)
	\le O\bigg( \frac{1}{\exp(\Omega(k^3\ln k))}
		\bigg)\,,\]
from which it follows that
	\begin{equation}\label{eq:sigma.T.Ent}
	\max\bigg\{\mathcal{H}(T),\mathcal{H}(\bm{E}_a),
		\mathcal{H}(Y^a\,|\,\bm{E}_a),
		\mathcal{H}(Y^b\,|\,\bm{E}_a)
		\bigg\} = o_k(1)\,.\end{equation}
We emphasize that in \eqref{eq:sigma.T.Ent} we must put $Y^a$ and $Y^b$ rather than $\mathcal{Y}^a$ and $\mathcal{Y}^b$:
this is because $Y$ consists of spins
$X_e$ which take only $O(1)$ possibilities, while $\mathcal{Y}$ consists of spins $\mathcal{X}_e=(X_e,\bm{L}_e)$ which take a large number of possibilities (indeed, growing with the neighborhood radius $R$ of \eqref{e:radii}) and therefore can have large conditional entropy given $\bm{E}_a$. To deal with the clause types $\bm{L}_e$ we note that
	\begin{align}\nonumber
	&\mathcal{H}\bigg( 
	(\smash{\vec{\bm{L}}}^a)_{\bm{E}_a}
	\,\bigg|\,
	\bm{E}_a,T, \mathcal{Z}^a\bigg) \\ \nonumber
 	&\stackrel{\eqref{eq:cond.L.Xi}}{=}
	\sum_{e\in \bm{E}}
	\Bigg\{
	\mathbf{P}^a(\Gamma(e)=1)
		\mathcal{H}\Big(\pi_{\mathscr{D}}(\cdot\,|\,\bm{t}_e)\Big)
	+\mathbf{P}^a(\Xi(e)=1)
	\mathcal{H}\Big(\pi_{\mathscr{D}}(\cdot
	\,|\,\bm{t}_e, \bm{L}_e \in \mathbb{D}\cap\mathbb{L})\Big)\\ \nonumber
	&\stackrel{\eqref{eq:GammaXiEquality2}}{=} \sum_{e\in \bm{E}}
	\Bigg\{
	\mathbf{P}^b(\Gamma(e)=1)
		\mathcal{H}\Big(\pi_{\mathscr{D}}(\cdot\,|\,\bm{t}_e)\Big)
	+\mathbf{P}^b(\Xi(e)=1)
	\mathcal{H}\Big(\pi_{\mathscr{D}}(\cdot
	\,|\,\bm{t}_e, \bm{L}_e \in \mathbb{D}\cap \mathbb{L})\Big)
	\Bigg\}\\
	&\stackrel{\eqref{eq:cond.L.Xi}}{=}
	\mathcal{H}\bigg( 
	(\smash{\vec{\bm{L}}}^b)_{\bm{E}_a}
	\,\bigg|\,
	\bm{E}_a,T,\mathcal{Z}^b
	\bigg)\,. \label{eq:L.EntopyEquality}
	\end{align}
Combining \eqref{eq:sigma.T.Ent} and \eqref{eq:L.EntopyEquality} gives 
	\begin{align}\nonumber
	&\bigg| \mathcal{H}\Big( \mathcal{Y}^a 
		\,\Big|\, \bm{E}_a,T,\mathcal{Z}^a\Big)- 
	\mathcal{H}\Big( \mathcal{Y}^b
		\,\Big|\, \bm{E}_a,T,\mathcal{Z}^b\Big)\bigg| \\ \nonumber
	&=
	\bigg|\mathcal{H}\Big( (\smash{\vec{\bm{L}}}^a)_{\bm{E}_a}\,\Big|\, \bm{E}_a,T,\mathcal{Z}^a\Big)
	-\mathcal{H}\Big( (\smash{\vec{\bm{L}}}^b)_{\bm{E}_a}\,\Big|\, \bm{E}_a,T,\mathcal{Z}^b\Big)\\
	\nonumber
	&\qquad+\mathcal{H}\Big( Y^a \,\Big|\, \bm{E}_a,T,\mathcal{Z}^a,(\smash{\vec{\bm{L}}}^a)_{\bm{E}_a}\Big)
	-\mathcal{H}\Big( Y^b \,\Big|\, \bm{E}_a,T,\mathcal{Z}^b,(\smash{\vec{\bm{L}}}^b)_{\bm{E}_a}\Big)
	\bigg|\\ 
	&\stackrel{\eqref{eq:L.EntopyEquality}}{=}
	\bigg|\mathcal{H}\Big( Y^a \,\Big|\, \bm{E}_a,T,\mathcal{Z}^a,(\smash{\vec{\bm{L}}}^a)_{\bm{E}_a}\Big)
	-\mathcal{H}\Big( Y^b \,\Big|\, \bm{E}_a,T,\mathcal{Z}^b,(\smash{\vec{\bm{L}}}^b)_{\bm{E}_a}\Big)\bigg|
	\stackrel{\eqref{eq:sigma.T.Ent}}{=} o_k(1)\,.
	\label{eq:EprimeEntopy}
	\end{align}
Finally, combining \eqref{eq:EntDecompB}, \eqref{eq:EntDecompA}, \eqref{e:DIVERSE.non.swapped.part},
\eqref{eq:sigma.T.Ent}, and \eqref{eq:EprimeEntopy} gives
	\begin{equation}\label{eq:A.to.B.Ent.Comp}
	\mathcal{H}(\mathbf{P}^b)-\mathcal{H}(\mathbf{P}^a)
	=\mathcal{H}(\mathcal{X}^b) - \mathcal{H}(\mathcal{X}^a)
	\ge o_k(1)\,.
	\end{equation}
This concludes our analysis of the measure $\mathbf{P}^b$.\smallskip

\noindent\bemph{\hypertarget{l:DIVERSE.Pc}{Part 4}. Construction of $\mathbf{P}^c$.}
Given a configuration $\mathcal{X}$, for 
$z\in\set{\SPIN{-},\SPIN{+}}$ and
$i=1,2$ let
	\begin{equation}\label{e:DIVERSE.hat.E}
	\hat{\bm{E}}^{z,i}
	\equiv \hat{\bm{E}}^{z,i}(\mathcal{X})
	\equiv \bigg\{ e\in\delta v(z):
	(\sigma_e)^i=\SSPIN{r},\sigma_e\ne\SSPIN{r}\SSPIN{r},
	\bm{L}_e\in\mathbb{D}\cap\mathbb{L}\bigg\}\,.
	\end{equation}
Write $\hat{\bm{E}}^i\equiv
\hat{\bm{E}}^{\SPIN{-},i}\cup\hat{\bm{E}}^{\SPIN{+},i}$.
Note that $\hat{\bm{E}}^1\cap\hat{\bm{E}}^2=\varnothing$. Recall from \eqref{e:four.distinct.edges} the definition of $\bm{E}$, and for $z\in\set{\SPIN{-},\SPIN{+}}$ let
	\[
	\acute{\bm{E}}^z
	\equiv \acute{\bm{E}}^z(\mathcal{X})
	\equiv\bigg\{e\in\delta v(z)\setminus\bm{E}
	: \varsigma_e=\SSPIN{w}\SSPIN{w},\bm{L}_e\in\mathbb{D}\cap\mathbb{L}\bigg\}\,.
	\]
(The sets $\acute{\bm{E}}^\SPIN{\textpm}(\mathcal{X}^a)$
are disjoint from $\bm{E}$, but
the sets $\hat{\bm{E}}^i$ can intersect $\bm{E}$.) We construct $\mathcal{X}^c$ as follows:
\begin{enumerate}[(II-2)]
\item[\hypertarget{i:DIVERSE.I1}{(I-1)}] On the event $\set{\mathcal{X}^a=\mathcal{X}^b,T(\mathcal{X}^a)=0,|\hat{\bm{E}}^1(\mathcal{X}^a)|\ge2}$,
choose $\hat{e}^1$ uniformly at random from $\hat{\bm{E}}^1(\mathcal{X}^a)$. For $e=\hat{e}^1$, set 
$(\mathcal{X}^c)_e=(\mathcal{X}^b)_e$ with probability $1-2^{-k\epsilon_\infty/2}$. With the remaining probability $2^{-k\epsilon_\infty/2}$ let $(\mathcal{X}^c)_e$ 
for $e=\hat{e}^1$
be defined by
	{\setlength{\jot}{0pt}\begin{align*}
	(\sigma^{c,1},\varsigma^{c,1})_e
	&=(\SSPIN{b},\SSPIN{w})\,,\\
	(\sigma^{c,2},\varsigma^{c,2},\bm{L}^c)_e
	&=(\sigma^{b,2},\varsigma^{b,2},\bm{L}^b)_e
	\end{align*}}
Let $p^{\textup{I},1}(e,\bm{L})$ denote the probability that edge $e$ has clause type $\bm{L}$ and is changed by the above:
	\begin{equation}\label{e:DIVERSE.def.p.I1}
	p^{\textup{I},1}(e,\bm{L})
	= \frac1{2^{k\epsilon_\infty/2}}
	\mathbb{E}
	\Bigg(
	\frac{\Ind{e\in\hat{\bm{E}}^1(\mathcal{X}^a)}}
		{|\hat{\bm{E}}^1(\mathcal{X}^a)|};
	(\bm{L}^a)_e=\bm{L},
	\mathcal{X}^a=\mathcal{X}^b,T(\mathcal{X}^a)=0,
	|\hat{\bm{E}}^1(\mathcal{X}^a)|\ge2
	\Bigg)\,,\end{equation}
where $\mathbb{E}$ denotes expectation with respect to the joint law $\mathbb{P}$ of $(\mathcal{X}^a,\mathcal{X}^b)$. 

\item[\hypertarget{i:DIVERSE.I2}{(I-2)}]
On the event $\set{\mathcal{X}^a=\mathcal{X}^b,T(\mathcal{X}^a)=0,|\hat{\bm{E}}^2(\mathcal{X}^a)|\ge2}$, perform the analogue of 
\hyperlink{i:DIVERSE.I1}{(I-1)} switching the roles of the two copies, and define the corresponding probability $p^{\textup{I},2}(e,\bm{L})$.

\item[\hypertarget{i:DIVERSE.II1}{(II-1)}] 
On the event $\set{x^{a,1}\in\set{\SPIN{-},\SPIN{+}},
T(\mathcal{X}^a)=0,|\hat{\bm{E}}^1(\mathcal{X}^a)|\le1}$, choose $\acute{e}^1$ uniformly at random from $\acute{\bm{E}}^{x^1}(\mathcal{X}^a)$. (Note the condition $T(\mathcal{X}^a)=0$ guarantees that the sets $\acute{\bm{E}}^{\SPIN{\textpm}}(\mathcal{X}^a)$ are both large, so it is possible to choose $\acute{e}^1$.) Let $(\mathcal{X}^c)_e$ for $e=\acute{e}^1$ be defined by
	{\setlength{\jot}{0pt}\begin{align*}
	(\sigma^{c,1},\varsigma^{c,1})_e
	&= (\SSPIN{r},\SSPIN{r})\,,\\
	(\sigma^{c,2},\varsigma^{c,2},\bm{L}^c)_e
		&=(\sigma^{b,2},\varsigma^{b,2},\bm{L}^b)_e
		\,.
	\end{align*}}
Let $p^{\textup{II},1}(e,\bm{L})$ denote the probability that edge $e$ has clause type $\bm{L}$ and is changed by the above:
	\begin{equation}\label{e:DIVERSE.def.p.II1}
	p^{\textup{II},1}(e,\bm{L})
	= \sum_{z\in\set{\SPIN{-},\SPIN{+}}}
	\mathbb{E}\Bigg(
	\frac{\Ind{e\in\acute{E}^z(\mathcal{X}^a)}}
		{|\acute{E}^z(\mathcal{X}^a)|}
	; (\bm{L}^a)_e=\bm{L}, x^{a,1}=z,
	T(\mathcal{X}^a)=0,
	|\hat{\bm{E}}^1(\mathcal{X}^a)|\le1
	\Bigg)\,,
	\end{equation}
where again $\mathbb{E}$ denotes expectation with respect to the joint law $\mathbb{P}$ of $(\mathcal{X}^a,\mathcal{X}^b)$. 
\item[\hypertarget{i:DIVERSE.II2}{(II-2)}] 
Lastly, on the event
$\set{x^{a,2}\in\set{\SPIN{-},\SPIN{+}},T(\mathcal{X}^a)=0,|\hat{\bm{E}}^2(\mathcal{X}^a)|\le1}$,
perform the analogue of \hyperlink{i:DIVERSE.II1}{(II-1)} switching the roles of the two copies, with the modification that if \hyperlink{i:DIVERSE.II1}{(II-1)} already occurred, then $\acute{e}^2$ is chosen uniformly at random from $\acute{\bm{E}}(\mathcal{X}^a)^2\setminus\set{\acute{e}^2}$. Define the corresponding probability $p^{\textup{II},2}(e,\bm{L})$.
\end{enumerate}
We point out that
steps \hyperlink{i:DIVERSE.I1}{(I-1)}
and \hyperlink{i:DIVERSE.I2}{(I-2)}
can only occur if $\mathcal{X}^a=\mathcal{X}^b$,
but steps 
\hyperlink{i:DIVERSE.II1}{(II-1)}
and \hyperlink{i:DIVERSE.II2}{(II-2)}
can occur even in the case
$\mathcal{X}^a\ne\mathcal{X}^b$. Note also that \hyperlink{i:DIVERSE.I1}{(I-1)} and \hyperlink{i:DIVERSE.II1}{(II-1)}
 cannot both occur, and likewise \hyperlink{i:DIVERSE.I2}{(I-2)} and 
 \hyperlink{i:DIVERSE.II2}{(II-2)}
 cannot both occur. To finish the construction, for all edges $e\in\delta v$ which were not chosen as $\hat{e}^i$ or $\acute{e}^i$ in any of the above steps, set $(\mathcal{X}^c)_e=(\mathcal{X}^b)_e$. Note that the frozen spin has not changed, $x=x^a=x^b=x^c\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$. Moreover we have $(\bm{L}^b)_e=(\bm{L}^c)_e$ for all $e\in\delta v$. It is straightforward to verify that the resulting $\mathcal{X}^c$ is a valid configuration with the same frozen spin, $x^b=x^c\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$.
Moreover, we observe that the construction so far guarantees 
	\begin{equation}\label{e:DIVERSE.hat.E.nonempty} 
	\hat{\bm{E}}^{z,i}(\mathcal{X}^c)\ne\varnothing
	\quad\textup{whenever}\quad
	x^{c,i}=z\in\set{\SPIN{-},\SPIN{+}}\,,
	\end{equation}
for $\hat{\bm{E}}^{z,i}$ as defined by \eqref{e:DIVERSE.hat.E}. Indeed, if $x=x^c$
has in the first copy $x^1=z\in\set{\SPIN{-},\SPIN{+}}$, we have these cases:
\begin{enumerate}[--]
\item Suppose $T(\mathcal{X}^a)=1$. It follows from \eqref{e:DIVERSE.Gm} that we will have $\Gamma(e)=1$ for $e=e^{z,1}\in\bm{E}$. In this case the resampling step 
\eqref{e:swap.Gamma.Xi.1} and the definition 
\eqref{e:DIVERSE.def.Xi}
of $\Xi(e)$ results in
a modified configuration $\mathcal{X}^b$ such that
 $e$ belongs to $\hat{\bm{E}}^{z,1}(\mathcal{X}^b)$.
(If $x^2=y\in\set{\SPIN{-},\SPIN{+}}$ then we may also have $\Gamma(e^{y,2})=1$, in which case the set $\hat{\bm{E}}^{y,2}$ also increases going from $\mathcal{X}^a$ to $\mathcal{X}^b$, but this is not relevant to the current considerations.)
Then steps \hyperlink{i:DIVERSE.I1}{(I-1)}
and \hyperlink{i:DIVERSE.I2}{(I-2)} do not occur
because $\mathcal{X}^a\ne\mathcal{X}^b$,
and steps 
\hyperlink{i:DIVERSE.II1}{(II-1)}
and \hyperlink{i:DIVERSE.II2}{(II-2)}
do not occur because $T(\mathcal{X}^a)=1$.
It follows that 
	\[|\hat{\bm{E}}^{z,1}(\mathcal{X}^c)|
	=|\hat{\bm{E}}^{z,1}(\mathcal{X}^b)|
	\ge|\hat{\bm{E}}^{z,1}(\mathcal{X}^a)|+1
	\ge1\,,\]
since $e=e^{z,1}\in\hat{\bm{E}}^{z,1}(\mathcal{X}^b)\setminus 
\hat{\bm{E}}^{z,1}(\mathcal{X}^a)$.

\item Suppose $T(\mathcal{X}^a)=0$, $\mathcal{X}^a=\mathcal{X}^b$, and $|\hat{\bm{E}}^1(\mathcal{X}^a)|\ge2$. In this case, the only way for an edge $e$ to belong to $\hat{\bm{E}}^1(\mathcal{X}^a)=\hat{\bm{E}}^1(\mathcal{X}^b)$ and not to $\hat{\bm{E}}^1(\mathcal{X}^c)$ is if $e$ is chosen as $\hat{e}^1$ in step \hyperlink{i:DIVERSE.I1}{(I-1)}. It follows that
	\[
	|\hat{\bm{E}}^1(\mathcal{X}^c)|
	\ge |\hat{\bm{E}}^1(\mathcal{X}^b)|-1
	= |\hat{\bm{E}}^1(\mathcal{X}^a)|-1
	\ge1\,.
	\]

\item Suppose $T(\mathcal{X}^a)=0$, $\mathcal{X}^a\ne\mathcal{X}^b$, and $|\hat{\bm{E}}^1(\mathcal{X}^a)|\ge2$. 
In this case, we see from \eqref{e:DIVERSE.def.Xi}
that we may have $\Xi(e)=1$
for $e=e^{z,1}$. This means $e\in\hat{\bm{E}}^1(\mathcal{X}^a)$, and the resampling step \eqref{e:swap.Gamma.Xi.2} results in $\mathcal{X}^b$ such that $e\notin\hat{\bm{E}}^1(\mathcal{X}^b)$. (If $x^2=y\in\set{\SPIN{-},\SPIN{+}}$ then we may also have $\Xi(e^{y,2})=1$, in which case the set 
$\hat{\bm{E}}^{y,2}$
also decreases going from $\mathcal{X}^a$ to $\mathcal{X}^b$, but this is not relevant to the current considerations since the $\hat{\bm{E}}^i$ are disjoint.) Then steps \hyperlink{i:DIVERSE.I1}{(I-1)}
and \hyperlink{i:DIVERSE.I2}{(I-2)} do not occur
because $\mathcal{X}^a\ne\mathcal{X}^b$, and steps
\hyperlink{i:DIVERSE.II1}{(II-1)}
and \hyperlink{i:DIVERSE.II2}{(II-2)}
do not occur because $|\hat{\bm{E}}^1(\mathcal{X}^a)|\ge2$.
It follows that
	\[
	|\hat{\bm{E}}^1(\mathcal{X}^c)|
	=|\hat{\bm{E}}^1(\mathcal{X}^b)|
	\ge|\hat{\bm{E}}^1(\mathcal{X}^a)|-1\ge1\,.
	\]

\item Suppose $T(\mathcal{X}^a)=0$ and $|\hat{\bm{E}}^1(\mathcal{X}^a)|\le1$. In this case, step 
\hyperlink{i:DIVERSE.II1}{(II-1)}
occurs and results in 
a configuration $\mathcal{X}^c$ such that
$\hat{\bm{E}}^1(\mathcal{X}^c)$ contains $\hat{e}^1$, and so is nonempty.
\end{enumerate}
This verifies the property \eqref{e:DIVERSE.hat.E.nonempty}, which will be used
in later steps of the proof. We now let $\mathbb{P}$ denote the joint law of
 $(\mathcal{X}^a,\mathcal{X}^b,\mathcal{X}^c)$, and let $\mathbf{P}^c$ denote the marginal law of $\mathcal{X}^c$. 

We first estimate the probability $p^{\textup{I},1}(e,\bm{L})$ from \eqref{e:DIVERSE.def.p.I1}. For an upper bound, note in order for $e\in\hat{\bm{E}}^1(\mathcal{X})$ we must have $(\sigma_e)^1=\SSPIN{r}$, so for all clause types $\bm{L}$ we have
	\begin{equation}\label{e:DIVERSE.p.I1.ubd.indiv}
	p^{\textup{I},1}(e,\bm{L})
	\le
	\frac{\mathbf{P}^a( \bm{L}_e=\bm{L}, (\sigma_e)^1=\SSPIN{r} )}
		{2^{k\epsilon_\infty/2}}
	= \frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
		\cdot {}_\star\hspace{-1pt}\pi_e(\SSPIN{r})}
		{2^{k\epsilon_\infty/2}}\,.\end{equation}
Next, since the total probability that \hyperlink{i:DIVERSE.I1}{(I-1)} occurs is at most $2^{-k\epsilon_\infty/2}$, we can also bound
	\begin{equation}\label{e:DIVERSE.p.I1.ubd}
	\sum_{e\in\delta v}\sum_{\bm{L}} 
	p^{\textup{I},1}(e,\bm{L})
	\le \frac1{2^{k\epsilon_\infty/2}}\,.\end{equation}
Next we note that $p^{\textup{I},1}(e,\bm{L})=0$ if $\bm{L}\notin\mathbb{D}\cap\mathbb{L}$. In the case $\bm{L}\in\mathbb{D}\cap\mathbb{L}$ we will derive a lower bound on $p^{\textup{I},1}(e,\bm{L})$. Recall $R_e$ from \eqref{e:DIVERSE.Re}, and let $S_e$ be an independent copy of $R_e$. By similar considerations as for \eqref{eq:frakR.bound}, we have
	\begin{equation}\label{e:DIVERSE.tildefrakR.intermediate.rr}
	\mathbf{P}^a\Bigg(
	\ddot{\mathfrak{r}}(\mathcal{X})
	\equiv
	\sum_{e\in\delta v} \Ind{\sigma_e=\SSPIN{r}\SSPIN{r}}
	\ge k^{1/2}\Bigg)
	\le O(1)
	\max_{z\in\set{\SPIN{-},\SPIN{+}}}\Bigg\{
	\frac{\mathbb{P}(\sum_{e\in\delta v(z)}
		R_e S_e \ge k^{1/2})}
	{\mathbb{P}(\sum_{e\in\delta v(z)} R_e\ge1)^2}\Bigg\}
	\le \frac1{\exp(\Omega(k^{3/2}))}\,.\end{equation}
Next, for $e\in\delta v$, let $G_e$ denote independent Bernoulli random variables with
	\[\mathbb{P}(G_e=1)
	=\mathbf{P}^a(\bm{L}_e\in\mathbb{D}\cap\mathbb{L})
	=\sum_{\bm{L}}
		\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
		\Ind{\bm{L}\in\mathbb{D}\cap\mathbb{L}}\,.\]
For $z\in\set{\SPIN{-},\SPIN{+}}$ and any fixed $e\in\delta v(z)$, on the event $\set{(\sigma_e)^1=\SSPIN{r}}$ we have
	\begin{equation}\label{e:DIVERSE.tilde.r.i.lbd}
	(\mathfrak{r}_e)^1(\mathcal{X})
	\equiv
	\sum_{e'\in\delta v(z)\setminus e}
	\mathbf{1}\bigg\{(\sigma_{e'})^1=\SSPIN{r},
		\bm{L}_{e'} \in \mathbb{D}\cap\mathbb{L}
	\bigg\}
	\ge \Big|\hat{\bm{E}}^1(\mathcal{X})\setminus
		\set{e}\Big|
	\ge (\mathfrak{r}_e)^1(\mathcal{X}) 
	- \ddot{\mathfrak{r}}(\mathcal{X})\,,\end{equation}
where $\ddot{\mathfrak{r}}(\mathcal{X})$ was defined on the left-hand side of \eqref{e:DIVERSE.tildefrakR.intermediate.rr}. By similar considerations as for \eqref{eq:frakR.bound} and \eqref{e:DIVERSE.tildefrakR.intermediate.rr}, we can express
	\[
	\mathbf{P}^a\Bigg(
	(\mathfrak{r}_e)^1 \le \frac{k}{3}
	\,\Bigg|\, (\sigma_e)^1=\SSPIN{r}\Bigg)
	=\mathbb{P}\Bigg(
	 \sum_{e'\in\delta v(z)\setminus e}
	 R_{e'} G_{e'} \le \frac{k}{3}\Bigg)\,.
	\]
To bound this last probability, note that
for both $z\in\set{\SPIN{-},\SPIN{+}}$ we have
	\begin{align*}
	&\mathrm{Var}\Bigg( \sum_{e'\in\delta v(z)\setminus e}
	R_{e'} G_{e'}\Bigg)
	\le \mathbb{E}\Bigg( \sum_{e'\in\delta v(z)\setminus e}
	R_{e'} G_{e'}\Bigg)
	=\sum_{e'\in\delta v(z)\setminus e}
	\mathbb{E} R_{e'}
	-\sum_{e'\in\delta v(z)\setminus e}
	(\mathbb{E} R_{e'}) \mathbb{E}(1-G_{e'})\\
	&\qquad=
	\bigg(1-o_k(1)\bigg) \frac{k\ln 2}{2}
	-\sum_{e'\in\delta v(z)\setminus e}
	(\mathbb{E} R_{e'}) \mathbb{E}(1-G_{e'}) 
	\stackrel{\eqref{e:assumption.notD.notL}}{=}
	\bigg(1-o_k(1)\bigg) \frac{k\ln 2}{2}\,.
	\end{align*}
We can use this last estimate together with Bernstein's inequality to bound
	\begin{equation}\label{e:DIVERSE.bernstein}
	\mathbf{P}^a\Bigg(
	(\mathfrak{r}_e)^1 \le \frac{k}{3}
	\,\Bigg|\, (\sigma_e)^1=\SSPIN{r}\Bigg)
	=\mathbb{P}\Bigg(
	 \sum_{e'\in\delta v(z)\setminus e}
	 R_{e'} G_{e'} \le \frac{k}{3}\Bigg)
	\le \frac1{\exp(\Omega(k))}\,.\end{equation}
On the other hand, by similar arguments as for \eqref{eq:frakR.bound}, we can bound
	\[
	\mathbf{P}^a\Bigg(
	(\mathfrak{r}_e)^1 \ge k
	\,\Bigg|\, (\sigma_e)^1=\SSPIN{r}\Bigg)
	\le \mathbb{P}\Bigg( \sum_{e'\in\delta v(z)\setminus e}
		R_{e'} \ge k\Bigg)
	\le \frac1{\exp(\Omega(k\ln k))}\,.
	\]
Combining the last two bounds gives
	\begin{equation}\label{e:DIVERSE.tildefrakR.intermediate.red}
	\mathbf{P}^a\Bigg(
	(\mathfrak{r}_e)^1 \in
		\bigg[\frac{k}{3},k\bigg]
	\,\Bigg|\, (\sigma_e)^1=\SSPIN{r}\Bigg)
	\ge1- \frac1{\exp(\Omega(k))}\,.
	\end{equation}
Returning to \eqref{e:DIVERSE.def.p.I1}, 
for $\bm{L}\in\mathbb{D}\cap\mathbb{L}$ we can lower bound
	\begin{align*}
	p^{\textup{I},1}(e,\bm{L}) 
	&\ge \frac1{2^{k\epsilon_\infty/2} \cdot 2k}
	\mathbf{P}^a\Bigg(
	\bm{L}_e=\bm{L},
	(\sigma_e)^1=\SSPIN{r},
	(\sigma_e)^2\ne\SSPIN{r},
	(\mathfrak{r}_e)^1 \in \bigg[\frac{k}{3},k\bigg]
	\Bigg)\\
	&\qquad-\Bigg\{\mathbf{P}^a(T=1)
	+\mathbb{P}(\mathcal{X}^a\ne \mathcal{X}^b)
	+\mathbf{P}^a(\ddot{\mathfrak{r}}\ge k^{1/2})
		\Bigg\}\,.\end{align*}
In the above we used the assumption that $\bm{L}\in\mathbb{D}\cap\mathbb{L}$, so if
$(\sigma_e)^1=\SSPIN{r}$ and $(\sigma_e)^2\ne\SSPIN{r}$
then $e\in\hat{\bm{E}}^1$.
We also used that if $(\mathfrak{r}_e)^1 \ge k/3$
and $\ddot{\mathfrak{r}}\le k^{1/2}$, then
certainly \eqref{e:DIVERSE.tilde.r.i.lbd} implies $|\hat{\bm{E}}^1|\ge2$, as is required for step (I-1) to occur. Lastly we used that if
$(\mathfrak{r}_e)^1 \le k$, then 
it follows from \eqref{e:DIVERSE.tilde.r.i.lbd} that $|\hat{\bm{E}}^1|\le k+1$, so edge $e$ has probability at least $1/(k+1) \ge 1/(2k)$ to be chosen as $\hat{e}^1$. Now recall from the previous construction that
$\mathbb{P}(\mathcal{X}^a\ne \mathcal{X}^b)
\le O(\mathbf{P}^a(T=1))$, so applying \eqref{eq:T2Bound} and \eqref{e:DIVERSE.tildefrakR.intermediate.rr} gives
	\begin{align*}
	p^{\textup{I},1}(e,\bm{L}) 
	\ge \frac1{2^{k\epsilon_\infty/2} \cdot 2k}
	\mathbf{P}^a\Bigg(
	\bm{L}_e=\bm{L},
	(\sigma_e)^1=\SSPIN{r},
	(\sigma_e)^2\ne\SSPIN{r},
	(\mathfrak{r}_e)^1 \in \bigg[\frac{k}{3},k\bigg]
	\Bigg)
	-\frac1{\exp(\Omega(k^{3/2}))}\,.
	\end{align*}
It then follows (again using the independence properties of $\mathbf{P}^a$) that
	\begin{align}\nonumber
	p^{\textup{I},1}(e,\bm{L}) 
	&\stackrel{\eqref{eq:productForm}}{\ge}
	\frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
		{2^{k\epsilon_\infty/2} \cdot 2k}
	\mathbf{P}^a\Big((\sigma_e)^1=\SSPIN{r}\Big)
	\mathbf{P}^a\Big((\sigma_e)^2\ne\SSPIN{r}\Big)
	\mathbf{P}^a\Bigg(
	(\mathfrak{r}_e)^1 \in \bigg[\frac{k}{3},k\bigg]
	\,\Bigg|\,
	(\sigma_e)^1=\SSPIN{r}
	\Bigg) \\
	&\stackrel{\eqref{e:DIVERSE.tildefrakR.intermediate.red}}{\ge}
	\frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
		{2^{k\epsilon_\infty/2} \cdot 2k}
	\cdot \frac{1-o_k(1)}{2^k}\,,
	\label{e:DIVERSE.p.I.final.lbd}\end{align}
as long as $\bm{L}\in\mathbb{D}\cap\mathbb{L}$. This concludes our analysis of $p^{\textup{I},1}(e,\bm{L})$. Clearly, 
\eqref{e:DIVERSE.p.I1.ubd} and \eqref{e:DIVERSE.p.I.final.lbd} also hold for 
$p^{\textup{I},2}(e,\bm{L})$.


We next prove an upper bound on the probability 
$p^{\textup{II},1}(e,\bm{L})$ from
\eqref{e:DIVERSE.def.p.II1}. Recall that the condition $T(\mathcal{X}^a)=0$ implies 
$|\acute{\bm{E}}^z(\mathcal{X}^a)| = \Theta(k2^k)$
for both $z\in\set{\SPIN{-},\SPIN{+}}$.
It follows that we can upper bound \eqref{e:DIVERSE.def.p.II1} as
	\[
	p^{\textup{II},1}(e,\bm{L})
	\le
	O\bigg(\frac1{k2^k}\bigg)
	\cdot
	\mathbf{P}^a\bigg(\bm{L}_e=\bm{L},
	|\hat{\bm{E}}^1(\mathcal{X}^a)|\le1
	\bigg)
	\le
	O\bigg(\frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}{k2^k}\bigg)
	\cdot\mathbf{P}^a\bigg(
		|\hat{\bm{E}}^1(\mathcal{X}^a)
		\setminus\set{e}|\le1
		\bigg)\,.\]
Recall from
\eqref{e:DIVERSE.tilde.r.i.lbd} 
that $|\hat{\bm{E}}^1(\mathcal{X}^a)\setminus\set{e}| \le (\mathfrak{r}_e)^1(\mathcal{X}^a)$. Then, arguing similarly as for 
\eqref{e:DIVERSE.bernstein}, 
for each $z\in\set{\SPIN{-},\SPIN{+}}$
we can apply Bernstein's inequality to upper bound
	\begin{align*}
	&\mathbf{P}^a\Bigg(
	(\mathfrak{r}_e)^1
	=
	\sum_{e'\in\delta v(z)\setminus e}
	\mathbf{1}\Big\{(\sigma_{e'})^1=\SSPIN{r},
	\bm{L}_{e'}\in\mathbb{D}\cap\mathbb{L}
	\Big\} \le1
	\,\Bigg|\, x^1=z\Bigg) \\
	&\qquad= \frac{\mathbb{P}(\sum_{e'
		\in\delta v(z)\setminus e} R_{e'} G_{e'}
			\le1)}
		{\mathbb{P}(\sum_{e'\in\delta v(z)} R_{e'}\ge1)}
	\le \frac1{\exp(k c_0)}\,,
	\end{align*}
for a positive absolute constant $c_0$.
On the other hand, if $(\mathfrak{r}_e)^1\ge2$, in order for $|\hat{\bm{E}}^1(\mathcal{X}^a)\setminus\set{e}|\le1$ it must be that
$(\sigma^{a,2})_{e'}=\SSPIN{r}$ for all but at most one of the edges $e'$ contributing to $(\mathfrak{r}_e)^1$, which has chance $O(2^{-k})$. Then
	\[
	\mathbf{P}^a\bigg(
		\hat{\bm{E}}^1(\mathcal{X}^a)
		\setminus\set{e}=\varnothing\bigg)
	\le
	\mathbf{P}^a \bigg((\mathfrak{r}_e)^1\le1\bigg)
	+\underbrace{\mathbf{P}^a\bigg(
	(\mathfrak{r}_e)^1\ge2,
	|\hat{\bm{E}}^1(\mathcal{X}^a)
		\setminus\set{e}| \le1
		\bigg)}_{O(1/2^k)}
	\le \frac1{\exp(k c_0)}\,.\]
Substituting into the above expression for
$p^{\textup{II},1}(e,\bm{L})$ gives
	\begin{equation}\label{e:DIVERSE.p.II.final.ubd}
	p^{\textup{II},1}(e,\bm{L})
	\le \frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
		{2^{k(1+c_0)}}\,.
	\end{equation}
A similar bound holds for $p^{\textup{II},2}(e,\bm{L})$, and this concludes our analysis of $p^{\textup{II},1}(e,\bm{L})$.

We now turn to estimating the entropy of $\mathbf{P}^c$. Let $\bm{E}_b$ be the (random) subset of edges $e\in\delta v$ for which $(\mathcal{X}^b)_e\ne(\mathcal{X}^c)_e$, or equivalently $(X^b)_e\ne(X^c)_e$. It follows by combining \eqref{e:DIVERSE.p.I1.ubd} and \eqref{e:DIVERSE.p.II.final.ubd} that
	\begin{equation}\label{e:DIVERSE.expected.bc.change}
	\mathbb{E}(|\bm{E}_b|)
	\le \sum_{e\in\delta v}\sum_{\bm{L}}\sum_{i=1,2}
		\bigg(
		p^{\textup{I},i}(e,\bm{L})
		+p^{\textup{II},i}(e,\bm{L})\bigg)
	\le O\bigg( \frac1{2^{k\epsilon_\infty/2}}\bigg)\,.\end{equation}
We write $\mathcal{H}(\bm{E}_b)$ to denote the entropy of the random variable $\bm{E}_b$, and we write $H(p)\equiv -p\ln p-(1-p)\ln (1-p)$ to denote the binary entropy function evaluated at $p\in[0,1]$. Then
	\begin{equation}\label{e:DIVERSE.bc.ent.Estar}
	\mathcal{H}(\bm{E}_b)
	\le \sum_{e\in\delta v} \mathcal{H}( \Ind{e\in\bm{E}_b} )
	\le |\delta v|
	H\bigg( \frac{ \mathbb{E}(|\bm{E}_b|) }{|\delta v|}\bigg)
	\stackrel{\eqref{e:DIVERSE.expected.bc.change}}{=} 
	o_k(1)\,,
	\end{equation}
where the second step used Jensen's inequality and the concavity of the binary entropy function. Now decompose $\smash{\vec{X}}_{\delta v}\equiv (U,W)$ where $U\equiv(X_e:e\in\bm{E}_b)$. 
Note if $\bm{E}_b$ is given, then $U^b$ takes at most $O(1)$ distinct values, so it follows from \eqref{e:DIVERSE.bc.ent.Estar} that the conditional entropy of $U^b$ given $\bm{E}_b$ is small, that is,
$\mathcal{H}(U^b \,|\, \bm{E}_b)=o_k(1)$. Then, since $\mathcal{X}^b$ can be determined as a function of $(\mathcal{X}^c,\bm{E}_b,U^b)$, we have
	\begin{equation}\label{eq:cXb.cXc.entropyComp}
	\mathcal{H}(\mathcal{X}^b)
	\le \mathcal{H}(\mathcal{X}^c) +
	\bigg( \mathcal{H}(\bm{E}_b) + \mathcal{H}(U^b \,|\, \bm{E}_b)\bigg)
	\stackrel{\eqref{e:DIVERSE.bc.ent.Estar}}{\le}
	\mathcal{H}(\mathcal{X}^c) + o_k(1)\,.
	\end{equation}
This verifies that the entropy of $\mathbf{P}^c$ is not much smaller than that of $\mathbf{P}^b$.

We finally estimate how the transformation from $\mathbf{P}^b$ to $\mathbf{P}^c$ affects the edge marginals. Recall that steps \hyperlink{i:DIVERSE.I1}{(I-1)} and 
\hyperlink{i:DIVERSE.I2}{(I-2)} can change $(\varsigma_e)^i$
from $\SPIN{red}$ to $\SPIN{white}$, and the probability of such a change is lower bounded by \eqref{e:DIVERSE.p.I.final.lbd}. Meanwhile, steps
\hyperlink{i:DIVERSE.II1}{(II-1)} and 
\hyperlink{i:DIVERSE.II2}{(II-2)} 
can change $(\varsigma_e)^i$ from $\SPIN{white}$ to $\SPIN{red}$,
and the probability of such a change is upper bounded by \eqref{e:DIVERSE.p.II.final.ubd}.
It follows that for $\bm{L}\in\mathbb{D}\cap\mathbb{L}$,
	\begin{align}\nonumber
	&\mathbf{P}^c\bigg( (\sigma_e)^i=\SSPIN{r}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\le
	\mathbf{P}^b\bigg( (\sigma_e)^i=\SSPIN{r}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	+\sum_{i=1,2}
	\frac{p^{\textup{II},i}(e,\bm{L})- p^{\textup{I},i}(e,\bm{L})}
		{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
	\\
	\qquad&\le
	\mathbf{P}^b\bigg( (\sigma_e)^i=\SSPIN{r}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	+ O\bigg( \frac{1}{2^{k(1+c_0)}}\bigg)
	-\Omega\bigg( \frac{1}{k 2^{k(1+\epsilon_\infty/2)}}\bigg)
	\le
	{}_\star\hspace{-1pt}\pi_e(\SSPIN{r})
	-\Omega\bigg( \frac{1}{k 2^{k(1+\epsilon_\infty/2)}}\bigg)\,,
	\label{eq:Xc.red.marginal.div}
	\end{align}
where the last step also used our earlier observation
\eqref{e:DIVERSE.ab.same.mgls} that $\mathbf{P}^b$ has the same edge marginals as $\mathbf{P}^a$. On the other hand, since the probability of
\hyperlink{i:DIVERSE.I1}{(I-1)} or
\hyperlink{i:DIVERSE.I2}{(I-2)} is upper bounded by \eqref{e:DIVERSE.p.I1.ubd.indiv}, we also have
	\begin{equation}\label{eq:Xc.red.marginal.div2}
	\mathbf{P}^c\bigg( (\sigma_e)^i=\SSPIN{r}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\ge
	\mathbf{P}^b\bigg( (\sigma_e)^i=\SSPIN{r}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	-\sum_{i=1,2}
	\frac{p^{\textup{I},i}(e,\bm{L})}{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
	\ge{}_\star\hspace{-1pt}\pi_e(\SSPIN{r})- 
	O\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)\end{equation}
for all $\bm{L}\in\mathbb{D}\cap\mathbb{L}$. In the case $(\bm{L}^b)\notin \mathbb{D}\cap\mathbb{L}$ we always set $(\mathcal{X}^c)_e=(\mathcal{X}^b)_e$,
so 
	\begin{equation}\label{eq:Xc.red.marginal.notdiv}
	\mathbf{P}^c\bigg( (\sigma_e)^i=\SSPIN{r}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	=
	\mathbf{P}^b\bigg( (\sigma_e)^i=\SSPIN{r}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\end{equation}
for all $\bm{L}\notin\mathbb{D}\cap\mathbb{L}$. Finally, since we did not yet change any spin with $(\varsigma_e)^i\in\set{\SSPIN{y},\SSPIN{c}}$
or $\varsigma_e\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$, we have
	{\setlength{\jot}{0pt}\begin{align}
	\label{eq:Xc.col.marginal.zeta.mgl}
	\mathbf{P}^c((\varsigma_e)^i=\tau\,|\, \bm{L}_e=\bm{L})
	&=(\bm{\zeta}_e)^i(\tau\,|\,\bm{L})
	\textup{ for all }\tau\in\set{\SSPIN{y},\SSPIN{c}}, \\
	\mathbf{P}^c(\varsigma_e\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2\,|\, \bm{L}_e=\bm{L})
	&= \mathbf{P}^a(\varsigma_e\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2\,|\, \bm{L}_e=\bm{L})
	\le O(k^4/4^k)
	\label{eq:Xc.col.marginal}
	\end{align}}
for all $\bm{L}$, where the final bound uses \eqref{e:DIVERSE.Pa.RYCsq}.\smallskip

\noindent\bemph{\hypertarget{l:DIVERSE.Pd}{Part 5}. Construction of $\mathbf{P}^d$.} We now construct $\mathcal{X}^d$ from $\mathcal{X}^c$. We will leave the clause type unchanged, $(\bm{L}^d)_e=(\bm{L}^c)_e$ for all $e\in\delta v$. We change some edges from non-\SPIN{white} to \SPIN{white}, according to the following rules.
\begin{enumerate}[(A)]
\item If $\bm{L}\not\in\mathbb{D}\cap\mathbb{L}$ and $(\varsigma^c)_e\ne\SSPIN{w}\SSPIN{w}$, then set $(\varsigma^d)_e=\SSPIN{w}\SSPIN{w}$, and
for $i=1,2$ set
	\[
	(\sigma^{d,i})_e
	=\begin{cases}
	\SSPIN{b} &\textup{if $(\sigma^{c,i})_e=\SSPIN{r}$,}\\
	(\sigma^{c,i})_e &\textup{otherwise.}
	\end{cases}
	\]
\item If $\bm{L}\in\mathbb{D}\cap\mathbb{L}$ then modify the spin on $e$ as follows:
\begin{enumerate}[(i)]
\item If $(\varsigma^c)_e=\SSPIN{r}\SSPIN{r}$ then set
$(\sigma^d,\varsigma^d)_e=(\SSPIN{b}\SSPIN{b},\SSPIN{w}\SSPIN{w})$.

\item If $(\varsigma^c)_e\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2\setminus\set{\SSPIN{r}\SSPIN{r}}$ then set
$(\sigma^d)_e=(\sigma^c)_e$, and for $i=1,2$ set
	\[
	(\varsigma^{d,i})_e
	=\begin{cases}
	\SSPIN{r}&\textup{if $(\sigma^{c,i})_e=\SSPIN{r}$,}\\
	\SSPIN{w}&\textup{otherwise.}
	\end{cases}
	\]

\item If $(\varsigma^c)_e\in\set{\SSPIN{y},\SSPIN{c}}\times\set{\SSPIN{w}}$ then set
$(\sigma^d)_e=(\sigma^c)_e$. For $\tau=(\varsigma^{c,1})_e\in\set{\SSPIN{y},\SSPIN{c}}$ define the quantity
	\[\theta=
	(\theta_e)^1(\tau\,|\,\bm{L})
	\equiv\min\bigg\{1, \frac{2^{-k(1+\epsilon_\infty/2)} }
		{(\bm{\zeta}_e)^1(\tau \,|\,\bm{L})}\bigg\}\,.
	\]
Set
 $(\varsigma^d)_e=\SSPIN{w}\SSPIN{w}$ with probability $\theta$. With the remaining probability $1-\theta$ leave $(\varsigma^d)_e$ unchanged.
If $(\varsigma^c)_e\in\set{\SSPIN{w}}\times\set{\SSPIN{y},\SSPIN{c}}$ then perform the analogous procedure with the roles of the two copies switched.

\item Lastly, if $(\varsigma^c)_e=\SSPIN{w}\SSPIN{w}$ then set
$(X^d)_e=(\sigma^d,\varsigma^d)_e=(\sigma^c,\varsigma^c)_e=(X^c)_e$.
\end{enumerate}
\end{enumerate}
Note that property \eqref{e:DIVERSE.hat.E.nonempty}
of $\mathcal{X}^c$ ensures that the above transformation results in a valid configuration $\mathcal{X}^d$
with the same frozen spin, $x^c=x^d\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$. 
Since the transformation does not add any \SPIN{red} spins, for $\bm{L}\in\mathbb{D}\cap\mathbb{L}$ we can bound
	\begin{align*}
	&\mathbf{P}^d\bigg(\varsigma_e=\SSPIN{r}\SSPIN{w}\,\bigg|\,\bm{L}_e=\bm{L}\bigg)
	\le\mathbf{P}^c\bigg(\varsigma_e=\SSPIN{r}\SSPIN{w}\,\bigg|\,\bm{L}_e=\bm{L}\bigg)
	\stackrel{\eqref{eq:Xc.red.marginal.div}}{\le} {}_\star\hspace{-1pt}\pi_e(\SSPIN{r})
	-\Omega\bigg( \frac{1}{k 2^{k(1+\epsilon_\infty/2)}}\bigg)\\
	&\qquad=\zeta_e(\SSPIN{r}\SSPIN{w}\,|\,\bm{L})
	+\zeta_e(\set{\SSPIN{r}}\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}\,|\,\bm{L})
	-\Omega\bigg( \frac{1}{k 2^{k(1+\epsilon_\infty/2)}}\bigg)\\
	&\qquad\stackrel{\odot}{\le}
	\zeta_e(\SSPIN{r}\SSPIN{w}\,|\,\bm{L})
	+O\bigg( \frac1{2^{k(1+\epsilon_\circ)}}\bigg)
	-\Omega\bigg( \frac{1}{k 2^{k(1+\epsilon_\infty/2)}}\bigg)
	\le \zeta_e(\SSPIN{r}\SSPIN{w}\,|\,\bm{L})\,.
	\end{align*}
The inequality marked $\odot$ above follows from Lemma~\ref{l:lotsOfAsDiverse} and the assumption $\bm{L}\in\mathbb{D}\cap\mathbb{L}$, with $\epsilon_\circ$ as in Definition~\ref{d:heavy}, and recalling that we took $\epsilon_\infty\le\epsilon_\circ$. For a lower bound, we note that for the case $\bm{L}\in\mathbb{D}\cap\mathbb{L}$, the above transformation removes \SPIN{red} spins only in the case $(\sigma^c)_e=\SSPIN{r}\SSPIN{r}$. It follows that, for all $\bm{L}\in\mathbb{D}\cap\mathbb{L}$, we have
	\begin{align*}
	&\mathbf{P}^d\bigg( (\varsigma_e)^1=\SSPIN{r}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\ge \mathbf{P}^c\bigg( (\varsigma_e)^1=\SSPIN{r}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
		-\mathbf{P}^c\bigg(
		\sigma_e=\SSPIN{r}\SSPIN{r}\,\bigg|\, \bm{L}_e=\bm{L}\bigg) \\
	&\stackrel{\eqref{e:DIVERSE.Pa.RYCsq}}{\ge} \mathbf{P}^c\bigg( (\varsigma_e)^1=\SSPIN{r}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
		- O\bigg( \frac{k^4}{4^k} \bigg)
	\stackrel{\eqref{eq:Xc.red.marginal.div2}}{\ge}
	 {}_\star\hspace{-1pt}\pi_e(\SSPIN{r}) 
	 -O\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)
	 - O\bigg( \frac{k^4}{4^k} \bigg) \\
	&\ge\zeta_e(\varsigma=\SSPIN{r}\SSPIN{w}\,|\,\bm{L})
		- O\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)\,.
	\end{align*}
Similar bounds hold if we exchange the roles of the two copies, so we also have
	\[\zeta_e(\SSPIN{w}\SSPIN{r}\,|\,\bm{L})
		- O\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)
	\le\mathbf{P}^d\bigg(\varsigma_e=\SSPIN{w}\SSPIN{r}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\le \zeta_e(\SSPIN{w}\SSPIN{r}\,|\,\bm{L})\]
for all $\bm{L}\in\mathbb{D}\cap\mathbb{L}$. 
For $\bm{L}\in\mathbb{D}\cap\mathbb{L}$ 
and $\tau\in\set{\SSPIN{y},\SSPIN{c}}$ we also have
	\begin{align*}
	&\mathbf{P}^d\bigg(\varsigma_e=\tau\SSPIN{w}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\le
	\Big(1-(\theta_e)^1(\tau)\Big)
	\mathbf{P}^c\bigg((\varsigma_e)^1=\tau
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\stackrel{\eqref{eq:Xc.col.marginal.zeta.mgl}}{=}
	\Big(1-(\theta_e)^1(\tau)\Big)
	(\bm{\zeta}_e)^i(\tau\,|\,\bm{L})\\
	&\qquad=\max\bigg\{0,
		(\bm{\zeta}_e)^i(\tau\,|\,\bm{L})-\frac1{2^{k(1+\epsilon_\infty/2)}}
	\bigg\}
	=\max\bigg\{0,
		\bm{\zeta}_e(\tau\SSPIN{w}\,|\,\bm{L})
		+\bm{\zeta}_e(\tau\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}\,|\,\bm{L})
		-\frac1{2^{k(1+\epsilon_\infty/2)}}
	\bigg\}\\
	&\qquad\le \bm{\zeta}_e(\tau\SSPIN{w}\,|\,\bm{L})
		+O\bigg( \frac1{2^{k(1+\epsilon_\circ)}}\bigg)
		-\frac1{2^{k(1+\epsilon_\infty/2)}}
	\le \bm{\zeta}_e(\tau\SSPIN{w}\,|\,\bm{L})
		-\Theta\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)\,,
	\end{align*}	
where the transition to the last line is by another application of Lemma~\ref{l:lotsOfAsDiverse}, again using that $\bm{L}\in\mathbb{D}\cap\mathbb{L}$. For a lower bound on the same quantity, we have
for all $\bm{L}\in\mathbb{D}\cap\mathbb{L}$ and $\tau\in\set{\SSPIN{y},\SSPIN{c}}$ that
	\begin{align*}
	&\mathbf{P}^d\bigg(\varsigma_e=\tau\SSPIN{w}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\ge\Big(1-(\theta_e)^1(\tau)\Big)
	\bigg\{
	\mathbf{P}^c\bigg( (\varsigma_e)^1=\tau
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	-\mathbf{P}^c\bigg( \varsigma_e\in\set{\tau}\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)\bigg\}\\
	&\qquad\stackrel{\eqref{eq:Xc.col.marginal}}{\ge}
		\Big(1-(\theta_e)^1(\tau)\Big)
	\mathbf{P}^c\bigg( (\varsigma_e)^1=\tau
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
		-O\bigg(\frac{k^4}{4^k}\bigg)\\
	&\qquad\stackrel{\eqref{eq:Xc.col.marginal.zeta.mgl}}{=}
	\max\bigg\{0,
		\bm{\zeta}_e(\tau\SSPIN{w}\,|\,\bm{L})
		+\bm{\zeta}_e(\tau\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}\,|\,\bm{L})
		-\frac1{2^{k(1+\epsilon_\infty/2)}}
	\bigg\}-O\bigg(\frac{k^4}{4^k}\bigg)
	\ge \bm{\zeta}_e(\tau\SSPIN{w}\,|\,\bm{L})
	-\Theta\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)\,.
	\end{align*}
Finally, the above procedure never yields $(\varsigma^d)_e\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$, so
for all $\bm{L}\in\mathbb{D}\cap\mathbb{L}$
and all $\varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}^2$ we have
	\[
	\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	\ge 0 = \mathbf{P}^d\bigg(\varsigma_e=\varsigma
		\,\bigg|\,\bm{L}_e=\bm{L}\bigg)
	\ge \bm{\zeta}_e(\varsigma\,|\,\bm{L})
		-\Theta\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)\,,
	\]
where the last inequality again uses Lemma~\ref{l:lotsOfAsDiverse}. In summary, in the above we have shown
	\begin{equation}\label{e:DIVERSE.cd.zeta.mgl}
	\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	\ge \mathbf{P}^d\bigg(\varsigma_e=\varsigma
		\,\bigg|\,\bm{L}_e=\bm{L}\bigg)
	\ge \bm{\zeta}_e(\varsigma\,|\,\bm{L})
		-\Theta\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)
		\end{equation}
for all $\bm{L}\in\mathbb{D}\cap\mathbb{L}$
and all $\varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2\setminus\set{\SSPIN{w}\SSPIN{w}}$. On the other hand, for $\bm{L}\notin\mathbb{D}\cap\mathbb{L}$ we have
	\begin{equation}\label{e:DIVERSE.cd.zeta.mgl.notDL}
	\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	\ge0=
	\mathbf{P}^d\bigg(\varsigma_e=\varsigma
		\,\bigg|\,\bm{L}_e=\bm{L}\bigg)
	\ge \bm{\zeta}_e(\varsigma\,|\,\bm{L})
	- O\bigg( \frac{k^2}{2^k}\bigg)
	\end{equation}
for all $\varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2\setminus\set{\SSPIN{w}\SSPIN{w}}$, where the last inequality is by Lemma~\ref{l:lotsOfAs}.

We now turn to estimating the entropy of $\mathbf{P}^d$. To this end, let $\bm{E}_c$ denote the subset of edges $e\in\delta v$ for which $(\mathcal{X}^d)_e\ne(\mathcal{X}^c)_e$, or equivalently $(X^d)_e\ne(X^c)_e$. Note that if 
$(\varsigma^{c,i})_e\ne\SSPIN{w}$
and $(\varsigma^{d,i})_e\ne\SSPIN{w}$,
then $(\varsigma^{c,i})_e=(\varsigma^{d,i})_e$
so $e\notin\bm{E}_c$.
If $e\in\bm{E}_c$ then
the above procedure must transform
$(\varsigma^{c,i})_e\ne\SSPIN{w}$ into $(\varsigma^{d,i})_e=\SSPIN{w}$ for at least one index $i=1,2$, so we can bound
	\begin{align*}
	&\mathbb{P}(e\in \bm{E}_c\,\bigg|\,\bm{L}_e=\bm{L})
	\le \sum_{i=1,2}
	\bigg\{ \mathbf{P}^c\Big( (\varsigma_e)^i\ne\SSPIN{w}
		\,\Big|\,\bm{L}_e=\bm{L}\Big)
	-\mathbf{P}^d\Big( (\varsigma_e)^i\ne\SSPIN{w}
		\,\Big|\,\bm{L}_e=\bm{L}\Big)\bigg\}\\
	&\qquad\le
	\sum_{i=1,2}\bigg\{
	(\bm{\zeta}_e)^i\Big(\set{\SSPIN{r},\SSPIN{y},\SSPIN{c}}
		\,\Big|\,\bm{L}\Big)
	-\mathbf{P}^d\Big( (\varsigma_e)^i\ne\SSPIN{w}
		\,\Big|\,\bm{L}\Big)\bigg\}
	\le O(1)\sum_{\varsigma\ne\SSPIN{w}\SSPIN{w}}
		\bigg|
		\bm{\zeta}_e(\varsigma\,|\,\bm{L})
		- \mathbf{P}^d\Big(\varsigma_e=\varsigma
			\,\Big|\,\bm{L}_e=\bm{L}\Big)
		\bigg|\,,
	\end{align*}
where the transition to the second line follows by combining \eqref{eq:Xc.red.marginal.div} and \eqref{eq:Xc.col.marginal.zeta.mgl}. Applying
\eqref{e:DIVERSE.cd.zeta.mgl} and \eqref{e:DIVERSE.cd.zeta.mgl.notDL} gives
	\begin{align}\nonumber
	\mathbb{E}(|\bm{E}_c|)
	&\le
	O(1)\sum_{e\in\delta v}
		\sum_{\varsigma\ne\SSPIN{w}\SSPIN{w}}
		\bigg\{
		\frac{\mathbf{P}^c(\bm{L}_e\in\mathbb{D}\cap\mathbb{L})}
			{2^{k(1+\epsilon_\infty/2)}}
		+\frac{\mathbf{P}^c(\bm{L}_e\notin\mathbb{D}\cap\mathbb{L})}
			{2^k/k^2}\bigg\}\\
	&\le O\bigg(\frac{k}{2^{k\epsilon_\infty/2}}
	+ \frac{\cancel{\mathbb{D}}(v)+\cancel{\mathbb{L}}(v)}
		{2^k/k^2}\bigg)
	\stackrel{\eqref{e:assumption.notD.notL}}{\le}
	O\bigg(\frac{k^2}{2^{k\epsilon_\infty/2}}\bigg)\,,
	\label{e:DIVERSE.Ec.bound}\end{align}
similarly to the estimate
\eqref{e:DIVERSE.expected.bc.change} from the previous transformation. It follows by the same argument as for \eqref{eq:cXb.cXc.entropyComp} that
	\begin{equation}\label{eq:cXc.cXd.entropyComp}
	\mathcal{H}(\mathbf{P}^c) 
	=\mathcal{H}(\mathcal{X}^c) 
	\le \mathcal{H}(\mathcal{X}^d) + o_k(1)
	= \mathcal{H}(\mathbf{P}^d) + o_k(1).
	\end{equation}
This concludes our analysis of the measure $\mathbf{P}^d$.\smallskip

\noindent\bemph{\hypertarget{l:DIVERSE.Pe}{Part 6}. Construction of $\mathbf{P}^f$.}
In the final step of the proof we construct $\mathcal{X}^f$ from $\mathcal{X}^d$, where we have chosen the notation $\mathcal{X}^f$ rather than $\mathcal{X}^e$ to avoid confusion with edge labels $e\in\delta v$. For $\sigma\in\set{\SSPIN{y},\SSPIN{b}}^2$ we define subsets $A^\sigma$ of $
\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2$ as follows:
	{\setlength{\jot}{0pt}\begin{align*}
	A^{\SSPIN{b}\SSPIN{b}}&=\set{(\SSPIN{r}\SSPIN{r},\SSPIN{r}\SSPIN{r}),
		(\SSPIN{b}\SSPIN{r},\SSPIN{w}\SSPIN{r}),(\SSPIN{b}\SSPIN{r},\SSPIN{c}\SSPIN{r}),
		(\SSPIN{r}\SSPIN{b},\SSPIN{r}\SSPIN{w}),(\SSPIN{r}\SSPIN{b},\SSPIN{r}\SSPIN{c}),
		(\SSPIN{b}\SSPIN{b},\SSPIN{w}\SSPIN{c}),(\SSPIN{b}\SSPIN{b},\SSPIN{c}\SSPIN{w}),
		(\SSPIN{b}\SSPIN{b},\SSPIN{c}\SSPIN{c})}\,,\\
	A^{\SSPIN{b}\SSPIN{y}}&=\set{
		(\SSPIN{r}\SSPIN{y},\SSPIN{r}\SSPIN{y}),
		(\SSPIN{b}\SSPIN{y},\SSPIN{w}\SSPIN{y}),
		(\SSPIN{b}\SSPIN{y},\SSPIN{c}\SSPIN{y})
		}\,,\\
	A^{\SSPIN{y}\SSPIN{b}}&=\set{
		(\SSPIN{y}\SSPIN{r},\SSPIN{y}\SSPIN{r}),
		(\SSPIN{y}\SSPIN{b},\SSPIN{y}\SSPIN{w}),
		(\SSPIN{y}\SSPIN{b},\SSPIN{y}\SSPIN{c})
		}\,,\\
A^{\SSPIN{y}\SSPIN{y}}&=\{(\SSPIN{y}\SSPIN{y},\SSPIN{y}\SSPIN{y})\}\,.
\end{align*}}
Note that for each $\sigma\in\set{\SSPIN{y},\SSPIN{b}}^2$ and every $(\sigma',\varsigma')\in A^\sigma$ we have the compatibility relation $\sigma'\sim\varsigma'$; and the spins $\sigma,\sigma'$ correspond to the same frozen spin $x\in\set{\SPIN{-},\SPIN{+}}^2$. Moreover, for each $\varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2\setminus\set{\SSPIN{w}\SSPIN{w}}$ 
there is exactly one spin $\sigma\equiv\sigma^f(\varsigma)\in\set{\SSPIN{y},\SSPIN{b}}^2$ such that 
$(\sigma',\varsigma)\in A^\sigma$ for some $\sigma'$.
We then define distributions $\xi^\sigma(\cdot\,|\,\bm{L})$ over pairs $X\equiv (\sigma,\varsigma)\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}^2\times\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2$ by setting
	\begin{equation}\label{e:DIVERSE.xi.defn}
	\xi^\sigma((\sigma,\varsigma)\,|\,\bm{L})
	=\frac{\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	-\mathbf{P}^d(\varsigma_e = \varsigma \,|\, \bm{L}_e=\bm{L})}{\mathbf{P}^d(\sigma_e = \sigma, \varsigma_e= \SSPIN{w}\SSPIN{w}
		\,|\, \bm{L}_e=\bm{L} )}
	\end{equation}
for all $(\sigma,\varsigma)\in A^\sigma$, and assigning the remaining probability to the event $\set{(\sigma,\varsigma)=(\sigma,\SSPIN{w}\SSPIN{w})}$. To see that these distributions are well-defined, note that on the right-hand side of \eqref{e:DIVERSE.xi.defn}, the denominator is $\Theta(1)$, while \eqref{e:DIVERSE.cd.zeta.mgl} and \eqref{e:DIVERSE.cd.zeta.mgl.notDL} together imply that the numerator is nonnegative and small. It follows that
	\[
	\xi^\sigma((\sigma,\SSPIN{w}\SSPIN{w})\,|\,\bm{L})
	= 1-\sum_{X'\in A^\sigma}
		\xi^\sigma(X'\,|\,\bm{L})
	\in[0,1]\,,
	\]
so $\xi^\sigma(\cdot\,|\,\bm{L})$ is a valid probability measure over $A^\sigma \cup \set{(\sigma,\SSPIN{w}\SSPIN{w})}$. In the final transformation, given $\mathcal{X}^d$, for each $e\in\delta v$ we set $(\bm{L}^f)_e=(\bm{L}^d)_e$. If $(\sigma^d)_e\in\set{\SSPIN{y},\SSPIN{b}}^2$ and $(\varsigma^d)_e=\SSPIN{w}\SSPIN{w}$, then we let $(X^f)_e$ be a sample from $\xi^\sigma(\cdot\,|\,(\bm{L}^d)_e)$. In all other cases we let $(X^f)_e=(X^d)_e$. It is straightforward to verify that this results in a valid configuration $\mathcal{X}^f$ with the same frozen spin,
$x^f=x^d\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$. For each $\varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2\setminus\set{\SSPIN{w}\SSPIN{w}}$,
	\begin{align}\nonumber
	&\mathbf{P}^f\Big(\varsigma_e=\varsigma\,\Big|\,\bm{L}_e=\bm{L}\Big)
	= \mathbf{P}^d\Big(\varsigma_e=\varsigma\,\Big|\,\bm{L}_e=\bm{L}\Big)
	+ \sum_{\sigma: \sigma=\sigma^f(\varsigma)}
	\mathbf{P}^d\Big(
	\sigma_e=\sigma,
	\varsigma_e=\SSPIN{w}\SSPIN{w}
	\,\Big|\,\bm{L}_e=\bm{L}\Big)
	\xi^\sigma( (\sigma,\varsigma) \,|\,\bm{L})\\
	&\qquad\stackrel{\eqref{e:DIVERSE.xi.defn}}{=}
	\mathbf{P}^d\Big(\varsigma_e=\varsigma\,\Big|\,\bm{L}_e=\bm{L}\Big)
	+ \bigg\{ \bm{\zeta}_e(\varsigma\,|\,\bm{L})
	-\mathbf{P}^d\Big(\varsigma_e=\varsigma\,\Big|\,\bm{L}_e=\bm{L}\Big)\bigg\}
	=\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	\,,\label{e:DIVERSE.final.msr.sat.varsigma}
	\end{align}
so $\mathbf{P}^f$ satisfies condition
\eqref{e:D.L.diverse.varsigma}. On the other hand, since $x^a=x^f\in\set{\SPIN{-},\SPIN{+},\SPIN{f}}^2$, we have
	\[
	\mathbf{P}^f\Big( x^i=z\,\Big|\,\bm{L}_e=\bm{L}\Big)
	=\mathbf{P}^a\Big( x^i=z\,\Big|\,\bm{L}_e=\bm{L}\Big)
	\stackrel{\eqref{eq:productForm}}{=} \begin{cases}
	{}_\star\hspace{-1pt}\pi_e(\set{\SSPIN{r},\SSPIN{b}})
	&\textup{if $z\in\set{\SPIN{-},\SPIN{+}}$
		and $e\in\delta v(z)$,}\\
	{}_\star\hspace{-1pt}\pi_e(\SSPIN{y})
	&\textup{if $z\in\set{\SPIN{-},\SPIN{+}}$
		and $e\in\delta v(\SPIN{-} z)$,}\\
	{}_\star\hspace{-1pt}\pi_e(\SSPIN{g}) 
	&\textup{if $z=\SPIN{f}$.}
	\end{cases}
	\]
Moreover, since $(\varsigma_e)^i=\SSPIN{r}$ if and only if $(\sigma_e)^i=\SSPIN{r}$, it follows that
	\[
	\mathbf{P}^f\Big( (\sigma_e)^i=\SSPIN{r}\,\Big|\,\bm{L}_e=\bm{L}\Big)
	\stackrel{\eqref{e:DIVERSE.final.msr.sat.varsigma}}{=}
	(\bm{\zeta}_e)^i(\SSPIN{r}\,|\,\bm{L})
	= {}_\star\hspace{-1pt}\pi_e(\SSPIN{r})\,.
	\]
It follows from the last two displays combined that $\mathbf{P}^f$ satisfies condition~\eqref{e:D.L.diverse.judicious}.
Lastly, since $(\bm{L}^a)_e=(\bm{L}^f)_e$ for all $e$, 
and $\mathbf{P}^a$ satisfied condition \eqref{e:D.L.diverse.clause} by construction,
we can conclude that $\mathbf{P}^f$ also satisfies 
condition~\eqref{e:D.L.diverse.clause}.

We now estimate the entropy of $\mathbf{P}^f$.
Let $\bm{E}_d$ denote the subset of edges $e\in\delta v$ for which $(\mathcal{X}^d)_e\ne(\mathcal{X}^f)_d$. For any edge in $e\in \bm{E}_d$ we must have $(\varsigma^d)_e=\SSPIN{w}\SSPIN{w}$ and $(\varsigma^f)_e\ne\SSPIN{w}\SSPIN{w}$. As a result we can bound
	\begin{align*}
	\mathbb{E}(|\bm{E}_d|)
	&\le \sum_{e\in \delta v}
	\bigg(
	\mathbf{P}^f(\varsigma_e\ne\SSPIN{w}\SSPIN{w})
	- \mathbf{P}^d(\varsigma_e\ne\SSPIN{w}\SSPIN{w})
	\bigg)
	= \sum_{e\in \delta v}
	\sum_{\varsigma\ne\SSPIN{w}\SSPIN{w}}\bigg(
	 \bm{\zeta}_e(\varsigma)
	 - \mathbf{P}^d(\varsigma_e=\varsigma)
	 \bigg) \le 
	 O\bigg( \frac{k^2}{2^{k \epsilon_\infty/2}}\bigg)\,,
\end{align*}
using the same reasoning as for \eqref{e:DIVERSE.Ec.bound}. It then follows by the argument of~\eqref{eq:cXb.cXc.entropyComp} that
	\begin{equation}\label{eq:cXd.cXe.entropyComp}
	\mathcal{H}(\mathbf{P}^d)\le \mathcal{H}(\mathbf{P}^f) + o_k(1)\,.\end{equation}
Combining equations~\eqref{eq:A.to.B.Ent.Comp}, \eqref{eq:cXb.cXc.entropyComp}, \eqref{eq:cXc.cXd.entropyComp},\eqref{eq:cXd.cXe.entropyComp},
and \eqref{eq:a.opt.EntComp} gives
	\[
	\mathcal{H}(\mathbf{P}^f)
	\ge \mathcal{H}(\mathbf{P}^a) - o_k(1)
	\stackrel{\eqref{eq:a.opt.EntComp}}{\ge}
	\mathcal{H}(\mathbf{P}) + \frac1{10^6} - o_k(1)\,.
	\]
This contradicts the assumption that $\mathbf{P}$ is the maximal-entropy measure satisfying constraints
\eqref{e:D.L.diverse.clause}--\eqref{e:D.L.diverse.varsigma}, thereby concluding the proof of the proposition.

\begin{alignat}{2}
	\mathbf{P}(\bm{L}_e=\bm{L})
	&=\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
	\quad&&\textup{for all $\bm{L}$,}
	\label{e:D.L.diverse.clause} \\ 
	\mathbf{P}(\sigma^i_e=\sigma^i \,|\,
		\bm{L}_e=\bm{L})
	&= {}_\star\hspace{-1pt}\pi_e(\sigma^i)
	\quad&&\textup{for all $\bm{L}$ and
		 all $\sigma^i\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{g},\SSPIN{b}}$,}
	\label{e:D.L.diverse.judicious} \\
	\mathbf{P}(\varsigma_e=\varsigma
		\,|\,\bm{L}_e=\bm{L})
	&=\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	\quad&&\textup{for all $\bm{L}$
		and all $\varsigma\in\set{\SSPIN{r},\SSPIN{y},\SSPIN{c},\SSPIN{w}}^2$.}
	\label{e:D.L.diverse.varsigma}
	\end{alignat}

\begin{align}\nonumber
	\mathbf{P}^a\Big(\smash{\vec{\sigma}}_{\delta v},\smash{\vec{\bm{L}}}_{\delta v}\Big)
	&\cong
	\varphi_v(\smash{\vec{\sigma}}_{\delta v})
	\prod_{e\in\delta v}\Bigg\{
	\pi_{\mathscr{D}}(\bm{L}_e\,|\,\bm{t}_e)
	\prod_{i=1,2}
	{}_\star\hspace{-1pt}\hat{q}_e((\sigma_e)^i)\Bigg\} \\
	& \cong
	{}_\star\hspace{-1pt}\dot{\nu}_v((\smash{\vec{\sigma}}_{\delta v})^1)
	{}_\star\hspace{-1pt}\dot{\nu}_v((\smash{\vec{\sigma}}_{\delta v})^2)
