\label{p:noNonDiverse} On the event that $\mathscr{D}$ expands on type-subsets (Definition~\ref{d:expansion}), all non-defective variables are diverse (Definition~\ref{d:diverse}); and all strongly 
non-defective clauses are light (Definition~\ref{d:heavy}).


\begin{proof} Since we have restricted to $\omega\in\bm{I}_0$ (as has been the case throughout this section), the total number of variables $v$ with frozen spin 
$x_v\in\set{\SPIN{+}\SPIN{+},\SPIN{-}\SPIN{-}}$ is close to $n/2$, in any pair frozen configuration that is consistent with $\omega$. Let $S'$ denote the set of all non-diverse variables: then
	\begin{equation}\label{e:diverse.Markov}
	|S'|
	= \sum_{v\in V}
	\mathbf{1}\bigg\{
	\pi_v(\set{\SPIN{+}\SPIN{+},\SPIN{-}\SPIN{-}}) > \frac34 
	\bigg\}
	\le \frac43
	\sum_{v\in V}
	\pi_v(\set{\SPIN{+}\SPIN{+},\SPIN{-}\SPIN{-}})
	\le \frac{3n}{4}
	\end{equation}
(where the last inequality uses the above observation on the number of variables with $x_v\in\set{\SPIN{+}\SPIN{+},\SPIN{-}\SPIN{-}}$).

Let $\cancel{\mathbb{D}}\subseteq F$ denote the set of non-diverse clauses; it follows from Definitions~\ref{d:diverse}~and~\ref{d:expansion} that $\cancel{\mathbb{D}}\subseteq F_\bullet(S')$. Now let $S\subseteq S'$ denote the subset of non-diverse variables that are non-defective (Definition~\ref{d:j.defective}), so we see from the above that
$|S| \le |S'| \le 3n/4$. Recall from Remark~\ref{r:defective.clauses}
that a clause is termed strongly non-defective if it neighbors only non-defective variables. Let $N\subseteq\cancel{\mathbb{D}}$ denote the set of non-diverse clauses that are strongly non-defective; it follows that $N\subseteq F_\bullet(S)$. Then, on the event that $\mathscr{D}$ expands on type-subsets, it follows from Definition~\ref{d:expansion} that
	\begin{equation}\label{e:diverseClauseBound}
	|N|
	\le \left\{\hspace{-6pt}\begin{array}{rl}
		n 2^{29k/30} & 
		\text{if }|S|/n \le 4/5\,.\\
		|S| &\text{if } |S|/n \le 1/16\,.
		\end{array}\right.\end{equation}
Next let $\cancel{\mathbb{L}}\subseteq F$ denote the set of all heavy clauses, and let $H\subseteq\cancel{\mathbb{L}}$ denote the subset of heavy clauses that are strongly non-defective. By Proposition~\ref{p:DIVERSE.VAR}, if $v$ is non-defective but not diverse, then
	\[
	\frac{2^k}{2^{k\epsilon_\infty}}<
	\max\Big\{\cancel{\mathbb{D}}(v),
		\cancel{\mathbb{L}}(v)\Big\}
	\le \cancel{\mathbb{D}}(v)
		+ \cancel{\mathbb{L}}(v)\,,
	\]
where we can take $\epsilon_\infty$ to be much smaller than all the other constants $\epsilon$ in this section. Summing the above over all $v\in S$,
and recalling the definitions
of $\cancel{\mathbb{D}}(v)$ and $\cancel{\mathbb{L}}(v)$
from Definitions~\ref{d:diverse}~and~\ref{d:heavy}, we obtain
	\begin{equation}\label{e:noNonDiverse.S.leq.N.H}
	\frac{2^k |S|}{2^{k\epsilon_\infty}} 
	< \sum_{v\in S}
	\sum_{e\in\delta v}
	\sum_{\bm{L}}
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
	\bigg(
	\Ind{\bm{L}\in\cancel{\mathbb{D}}
		\cup \cancel{\mathbb{L}}}\bigg)
	\le \Big(|N| + |H|\Big)k + |S|\,,
	\end{equation}
where the right-hand side of \eqref{e:noNonDiverse.S.leq.N.H} is obtained as follows: the contribution from the case of strongly non-defective clause types $\bm{L}$ is bounded by the term $(|N|+|H|)k$, where the factor $k$ accounts for the fact that one clause can neighbor up to $k$ variables. As for the case where $\bm{L}$ fails to be strongly non-defective, we recall from Remark~\ref{r:defective.clauses} that each $v\in S$ neighbors at most one such clause, so the contribution from this case is bounded by the term $|S|$. 

Now note that \eqref{e:diverseClauseBound} bounds $|N|$ in terms of $|S|$, while \eqref{e:noNonDiverse.S.leq.N.H} bounds $|S|$ in terms of $|N|$ and $|H|$. We will close the loop by bounding $|H|$ in terms of $|N|$. In fact we will bound $|E_H|$ where $E_H$ is a subset of edges defined as follows: for any edge $e=(av)$ where $\bm{L}_a=\bm{L}$ and $j=j(\bm{t}_e)$, write $\omega_e\equiv\omega_{\bm{L},j}$. Then let
	\[
	E_H
	\equiv\bigg\{
	e=(av): \textup{$a$ is a strongly non-defective clause
		and }\omega_e(\SSPIN{r}\SSPIN{r})
		\ge \frac1{2^{k(1+\epsilon_\circ)}}
	\bigg\}\,.
	\]
Note that a clause belongs to $H$ if and only if it lies incident to $E_H$, so $|H|\le |E_H|$. We will bound
	\[
	|E_H|
	\le \sum_{i=0}^2 |E_H(U_i)|
	\]
where $E_H(U_i)$ denotes the subset of edges in $E_H$ that are incident to $U_i$, and $(U_0,U_1,U_2)$ gives a partition of the set of all non-defective variables: 
	{\setlength{\jot}{0pt}\begin{align*}
	U_0 &\equiv
	\set{\text{non-defective variables $v$}:
		\cancel{\mathbb{D}}(v)
		\le 2^{k(1-\epsilon_\infty)},
		\cancel{\mathbb{L}}(v)
		\le 2^{k(1-\epsilon_\infty)}
		}\,,\\
	U_1 &\equiv
	\set{\text{non-defective variables $v$}:
		\cancel{\mathbb{D}}(v)
		\le 2^{k(1-\epsilon_\infty)},
		\cancel{\mathbb{L}}(v)
		> 2^{k(1-\epsilon_\infty)}
		}\,,\\
	U_2 &\equiv
	\set{\text{non-defective variables $v$}:
		\cancel{\mathbb{D}}(v)
		> 2^{k(1-\epsilon_\infty)}	}\,.
	\end{align*}}
It follows from Proposition~\ref{p:DIVERSE.VAR} that
if $v\in U_0$ then $v$ is diverse, and moreover that $\pi_v(x)$ is close to $1/4$ for each $x\in\set{\SPIN{-},\SPIN{+}}^2$. Thus each $v\in U_0$ satisfies the conditions of Lemma~\ref{l:large11Case} --- in particular, Lemma~\ref{l:large11Case} has a condition $\pi_v(\SPIN{+}\SPIN{+})\ge 2^{-k/16}$ which is certainly guaranteed if $\pi_v(\SPIN{+}\SPIN{+})$ is close to $1/4$.
It follows by Lemma~\ref{l:large11Case} that an edge $e=(av)$ with $v\in U_0$ cannot belong to $E_H$ unless the clause $a$ is non-diverse, which means $a\in N$. Therefore
	\[
	|E_H(U_0)| \le \bigg|\Big\{
		(av) \in E_H : a\in N\Big\}\bigg|
	\le |N|k\,.
	\]
Next, similarly to \eqref{e:noNonDiverse.S.leq.N.H} we have the bound
	\begin{equation}\label{e:EPSAP.U.one.bound}
	\frac{2^k |U_1|}{2^{k\epsilon_\infty}}
	<
	\sum_{v\in U_1} \cancel{\mathbb{L}}(v)
	\le |H|k + |U_1| \,.
	\end{equation}
For $v\in U_1$, applying Corollary~\ref{c:RRFreq} gives
	\begin{equation}\label{e:EPSAP.avg.heavy.bound}
	\sum_{e\in\delta v}
	\sum_{\bm{L}\in\mathbb{D}}
	\pi(\bm{L}|\bm{t}_e)
	\mathbf{1}\Bigg\{ \omega_{\bm{L},j}(\SSPIN{r}\SSPIN{r})
	\ge \frac1{2^{k(1+\epsilon_\circ)} }\Bigg\}
	\le \frac{{k^2}
		2^{k(1+\epsilon_\circ)}}{2^{k\epsilon_4}}
	\le \frac{2^k}{2^{k\epsilon_\circ}}\,,\end{equation}
where the last bound holds because we took $\epsilon_\circ$ to be much smaller than $\epsilon_4$. Combining with the preceding upper bound on $|U_1|$ gives
	\begin{align*}
	|E_H(U_1)|
	&\le
	\bigg|\Big\{ (av) : a\in N\Big\}\bigg|
	+\bigg|\Big\{ (av)\in E_H : v\in U_1,
		a\in\mathbb{D}\Big\}\bigg|\\
	&\stackrel{\eqref{e:EPSAP.avg.heavy.bound}}{\le}
	|N|k
	+|U_1| \frac{2^k}{2^{k\epsilon_\circ}}
	\stackrel{\eqref{e:EPSAP.U.one.bound}}{\le}
	|N|k
	+|H| \frac{2^{k\epsilon_\infty}}{2^{k\epsilon_\circ}} k
		\bigg(1+o_k(1)\bigg)\,.
	\end{align*}
Finally, similarly to \eqref{e:noNonDiverse.S.leq.N.H} and \eqref{e:EPSAP.U.one.bound} we have
	\begin{equation}\label{e:EPSAP.U.two.bound}
	\frac{2^k|U_2| }{2^{k\epsilon_\infty}}
	< \sum_{v\in U_2} \cancel{\mathbb{D}}(v)
	\le |N|k + |U_2|\,,\end{equation}
from which it follows that
	\[
	|E_H(U_2)|
	\le \bigg|\Big\{(av) : v\in U_2\Big\}\bigg|
	\le |U_2| 2^k k^2
	\stackrel{\eqref{e:EPSAP.U.two.bound}}{\le}
	|N| 2^{k\epsilon_\infty}k^3 
	\bigg(1+o_k(1)\bigg)\,.\]
Combining the above bounds gives
	\[|H| \le \sum_{i=0}^2 |E_H(U_i)| 
	\le |N| 2^{k\epsilon_\infty} k^4
		+ |H| \frac{2^{k\epsilon_\infty}}{2^{k\epsilon_\circ}} k^2
	\le
	|N| 2^{k\epsilon_\infty}k^4
	+ \frac{|H|}{2^{k\epsilon_\circ/2}}
	\,,\]
where the last bound holds since we took $\epsilon_\infty$ to be much smaller than $\epsilon_\circ$, as discussed above. Rearranging gives
$|H| \le O(1) |N| 2^{k\epsilon_\infty}k^4$, and combining
with \eqref{e:noNonDiverse.S.leq.N.H} gives
	\[
	|S|
	\stackrel{\eqref{e:noNonDiverse.S.leq.N.H}}{\le}
	O(1)
	\Big(|N|+|H|\Big) \frac{2^{k\epsilon_\infty}}{2^k} k
	\le \frac{|N| k^{O(1)}}{2^{k(1-2\epsilon_\infty)}}\,.
	\]
Together with the expansion bound 
\eqref{e:diverseClauseBound}
(which can be applied, since we saw earlier that $|S| \le 3n/4$), we see that the only possibility is for $|S|=|N|=0$. This implies $|H|=0$ and concludes the proof.
\end{proof}

