\label{cor-X-hat-X}
Let $0\le \ddot{\alpha}-\dot{\alpha} \le \exp(-2^k)$.
Let $\vec{a}$ be as in \eqref{e:array.coupled.trees.a}, except that the entries are independent samples from $\mu(\dot{\alpha},\ddot{\alpha})$ rather than from
$\mu^{\ell-1}(\dot{\alpha},\ddot{\alpha})$. Then, with the same notation as before, we have
	\begin{align*}
	\mathbb{E}\bigg(
	\mathbb{E}[\ddot{X}_i-\dot{X}_i \,|\,\dot{T} ]^2\bigg)
	&\le \frac{(\ddot{\alpha}-\dot{\alpha})^2}
		{2^{5k} / k^{O(1)}}\,,\\
	\mathbb{E}\bigg(
		\mathbb{E}\Big[ 
		(\ddot{X}_i-\dot{X}_i)^2
		\,\Big|\,\dot{T} \Big]^2
		\bigg)
	&\le \frac{(\ddot{\alpha}-\dot{\alpha})^2}
		{2^{8k} / k^{O(1)}}\end{align*}
for all $1\le i\le \dot{d}=\dot{d}^\SPIN{+}+\dot{d}^\SPIN{-}$.

\begin{proof}
With the same notation as before, we can expand
	\[
	\ddot{X}_i-\dot{X}_i
	=\overbrace{\Bigg\{
		\sum_{j=1}^{k-1}
		\frac{u_i[j](\ddot{\eta}_{ij}-\dot{\eta}_{ij})}
			{1-u_i[j]\dot{\eta}_{ij}}
			\Bigg\}}^{\textup{denote this }\mathbf{x}_1}
	{}+{}\overbrace{
	O\Bigg( \sum_{j=1}^{k-1}
		\Big(\frac{u_i[j](\ddot{\eta}_{ij}
			-\dot{\eta}_{ij})}
			{1-u_i[j]}\Big)^2
		\Bigg)
	}^{\textup{denote this }\mathbf{x}_2}\,.
	\]
For the quadratic term,
applying Lemma~\ref{lem-Q-monotone-coupling-prelim} 
(in the limit $\ell\to\infty$) gives
	\[\mathbb{E}\Big(
		\mathbb{E}[\mathbf{x}_2\,|\,\dot{T}]^2\Big)
	\le \frac{(\ddot{\alpha}-\dot{\alpha})^2}{
		 2^{8k}/k^{O(1)}}\,.
	\]
For the linear term, applying
 Lemma~\ref{lem-coupling-Q-Q-prime} 
 gives
	\[
	\mathbb{E}\Big(\mathbb{E}[\mathbf{x}_1\,|\,\dot{T}]^2\Big)
	\le k\,
	\mathbb{E} \Bigg( \sum_{j=1}^{k-1}
		\mathbb{E}\bigg[\frac{u[j]}{1-u[j]}
			\,\bigg|\, \dot{T}\bigg]^2
		\,\mathbb{E}\Big[ \ddot{\eta}_j-\dot{\eta}_j
			\,\Big|\, \dot{T}\Big]^2
			\Bigg)
	\le \frac{ (\ddot{\alpha}-\dot{\alpha})^2}
		{2^{5k} /k^{O(1)}}\,.
	\]
Combining these gives the first assertion.
Similar calculations give
	\[
	\mathbb{E}\Big(\mathbb{E}[ (\ddot{X}_i-\dot{X}_i)^2
		\,|\,\dot{T} ]^2\Big)
	\le
	k^{O(1)}
	\mathbb{E} \Bigg( \sum_{j=1}^{k-1}
		\mathbb{E}\bigg[ \Big(\frac{u[j]}{1-u[j]}\Big)^2
			\,\bigg|\, \dot{T}\bigg]^2
		\,\mathbb{E}\Big[ (\ddot{\eta}_j-\dot{\eta}_j)^2
			\,\Big|\, \dot{T}\Big]^2\Bigg)
	\le\frac{ (\ddot{\alpha}-\dot{\alpha})^2}
		{2^{8k} /k^{O(1)}}\,.
	\]
This gives the second assertion.
\end{proof}

