Let $\alpha_\textup{lbd}\le \dot{\alpha}\le\ddot{\alpha}\le\alpha_\textup{ubd}$ with $\ddot{\alpha}-\dot{\alpha} \le \exp(-2^k)$.
Our goal is to upper bound the difference
$\Phi(\ddot{\alpha})-\Phi(\dot{\alpha})$ where $\Phi$ is the $\textup{1-\textsc{rsb}}$ free energy defined by 
\eqref{e:phi.alpha}. To this end, define the function
	\[
	G(x,y)
	\equiv \ln\bigg(
	\frac1{e^x}+\frac1{e^y}-\frac1{e^{x+y}}
	\bigg)\,,
	\]
and note that $\Phi(\alpha)=\Phi_1(\alpha)+(k-1)\Phi_2(\alpha)$ where
	\begin{align}\nonumber
	\Phi_1(\alpha)
	&\equiv
	\mathbb{E} \ln(
	\frac1{\exp(\Sigma^\SPIN{+})}
	+\frac1{\exp(\Sigma^\SPIN{-})}
	-\frac1{\exp(\Sigma^\SPIN{+}+\Sigma^\SPIN{-})}
		)
	= \mathbb{E} G(\Sigma^\SPIN{+},\Sigma^\SPIN{-})\,,\\
	\label{e:def.X.prime}
	\Phi_2(\alpha)
	&\equiv -\alpha\,\mathbb{E}\ln 
		\bigg( 1- \prod_{j=1}^k \eta_j\bigg)
	\equiv \alpha \, \mathbb{E} X'\,.
	\end{align}
We define $\tilde{\Sigma}^\SPIN{\textpm}$ as in the proof of Lemma~\ref{lem-Q-monotone-coupling-prelim}, and decompose (similarly to \eqref{e:diff.eta.terms})
	\[
	\Phi_1(\ddot{\alpha})
	-\Phi_1(\dot{\alpha})
	=\overbrace{\mathbb{E} \bigg(
		G(\ddot{\Sigma}^\SPIN{+},\ddot{\Sigma}^\SPIN{-})
		-G(\tilde{\Sigma}^\SPIN{+},\tilde{\Sigma}^\SPIN{-})
		\bigg)}^{\textup{denote this }\mathbf{G}}
	{}+{}\overbrace{\mathbb{E}\bigg(
	G(\tilde{\Sigma}^\SPIN{+},\tilde{\Sigma}^\SPIN{-})
	-G(\dot{\Sigma}^\SPIN{+},\dot{\Sigma}^\SPIN{-})
	\bigg)}^{\textup{denote this }\mathbf{g}}\,.
	\]
We further decompose
	\[
	\mathbf{g}
	=
	\mathbb{E} \Bigg( \overbrace{\bigg\{
	G(\tilde{\Sigma}^\SPIN{+},\tilde{\Sigma}^\SPIN{-})
	-G(\tilde{\Sigma}^\SPIN{+},\dot{\Sigma}^\SPIN{-})
	\bigg\}}^{\textup{denote this }\mathbf{g}^\SPIN{-}}
	+\overbrace{\bigg\{
	G(\tilde{\Sigma}^\SPIN{+},\dot{\Sigma}^\SPIN{-})
	-G(\dot{\Sigma}^\SPIN{+},\dot{\Sigma}^\SPIN{-})
	\bigg\}}^{\textup{denote this }\mathbf{g}^\SPIN{+}}
	\Bigg)\,.
	\]
It is easily checked that
$|G_x|\le1$ and $|G_{xx}|\le1$, so
	\[
	\mathbf{g}^\SPIN{+}
	=\overbrace{\Bigg\{
	\sum_{i=1}^{\dot{d}^\SPIN{+}}
		G_x\Big(\Sigma^\SPIN{+}[i] + \dot{X}^\SPIN{+}_i,
			\dot{\Sigma}^\SPIN{-}\Big)
		\cdot
		\Big( \ddot{X}^\SPIN{+}_i - \dot{X}^\SPIN{+}_i \Big)
		\Bigg\} }^{\textup{denote this }\mathbf{g}_x}
	{}+{}\overbrace{
	O\Bigg( \sum_{i=1}^{\dot{d}^\SPIN{+}}
		\Big(
		\ddot{X}^\SPIN{+}_i - \dot{X}^\SPIN{+}_i
		\Big)^2\Bigg)}
		^{\textup{denote this }\mathbf{g}_{xx}}.
	\]
Applying Corollary~\ref{cor-X-hat-X}
gives
	\[
	(\mathbb{E}\mathbf{g}^\SPIN{+})^2
	\le 2\,
	\mathbb{E}\bigg(
	\mathbb{E}[ \mathbf{g}_x\,|\,\dot{T}]^2
	+\mathbb{E}[ \mathbf{g}_{xx}\,|\,\dot{T}]^2
	\bigg)
	\le 
	 \frac{(\ddot{\alpha}-\dot{\alpha})^2}
		{2^{3k}/k^{O(1)}}
	+ \frac{(\ddot{\alpha}-\dot{\alpha})^2}
		{2^{6k}/k^{O(1)}}
	\le \frac{(\ddot{\alpha}-\dot{\alpha})^2}
		{2^{3k}/k^{O(1)}}\,.
	\]
Similar bounds hold for $\mathbf{g}^\SPIN{-}$, so we conclude
	\[|\mathbf{g}|
	=\bigg|
	\mathbb{E}\Big(\mathbf{g}^\SPIN{-}+\mathbf{g}^\SPIN{-}\Big)
	\bigg|
	\le
	\frac{\ddot{\alpha}-\dot{\alpha}}
		{2^{3k/2}/k^{O(1)}}\,.\]
It remains to estimate $\mathbf{G}$. This is similar to the analysis of $\mathbf{A}$
in the proof of Lemma~\ref{lem-coupling-Q-Q-prime}: write $\delta\equiv\ddot{d}-\dot{d}=\delta^\SPIN{+}+\delta^\SPIN{-}$ for the difference in root degrees between $\dot{T}$ and $\ddot{T}$. When $\delta=0$ we have simply $\mathbf{G}=0$. The expected contribution from the event $\delta\ge2$ is negligible. It remains to consider the case $\delta=1$. Without loss of generality, take the case that $\delta^\SPIN{+}=1$ and $\delta^\SPIN{-}=0$: 
	\begin{align*}
	\mathbf{G}_{1,0}
	&\equiv\mathbb{E}\Bigg[
	G(\ddot{\Sigma}^\SPIN{+},\ddot{\Sigma}^\SPIN{-})
	-G(\tilde{\Sigma}^\SPIN{+},\tilde{\Sigma}^\SPIN{-})
	; (\delta^\SPIN{+},\delta^\SPIN{-})=(1,0)\Bigg]\\
	&=\mathbb{E}\Bigg[
	G(\tilde{\Sigma}^\SPIN{+}
		+ \ddot{X}_{\ddot{d}^\SPIN{+}},
		\tilde{\Sigma}^\SPIN{-})
	-G(\tilde{\Sigma}^\SPIN{+},\tilde{\Sigma}^\SPIN{-})
	; (\delta^\SPIN{+},\delta^\SPIN{-})=(1,0)\Bigg]\\
	&= -\frac12 \cdot
	\frac{k (\ddot{\alpha}-\dot{\alpha})}{2} \cdot
	\frac{1+O(2^{-k/20})}
			{2^{k-1}}\,,
	\end{align*}
where the last estimate uses Lemma~\ref{l:X.tail.bounds}
and the fact that the partial derivative $G_x(\tilde{\Sigma}^\SPIN{+},\tilde{\Sigma}^\SPIN{-})$
 is well concentrated around $-1/2$. Altogether we conclude
 	\[\Phi_1(\ddot{\alpha})
	-\Phi_1(\dot{\alpha})
	= - \frac{k(\ddot{\alpha}-\dot{\alpha}) }{2^k
		} 
		\Bigg\{ 1 + \frac{O(1)}{2^{k/20}}
	\Bigg\}\,.
	\]
Next, let $\dot{X}'$ and $\ddot{X}'$ be defined analogously to $X'$ in 
\eqref{e:def.X.prime}, but using the messages $\dot{\eta}_j$ and $\ddot{\eta}_j$. Then
	\[
	\Phi_2(\ddot{\alpha})-\Phi_2(\dot{\alpha})
	=
	\overbrace{\bigg\{
	(\ddot{\alpha}-\dot{\alpha})
	\cdot \mathbb{E}\dot{X}'
	\bigg\}}^{\textup{denote this }\mathbf{h}_{21}}
	+
	\overbrace{\bigg\{
	\ddot{\alpha}\,\mathbb{E}(\ddot{X}'-\dot{X}')
	\bigg\}}^{\textup{denote this }\mathbf{h}_{22}}
	\,.
	\]
A trivial modification of Corollary~\ref{cor-X-hat-X}
gives 
	\[
	(\mathbb{E}\mathbf{h}_{22})^2
	\le
	\frac{\ddot{\alpha}^2
	(\ddot{\alpha}-\dot{\alpha})
	}{2^{5k}/k^{O(1)}}
	\le\frac{(\ddot{\alpha}-\dot{\alpha})
	}{2^{3k}/k^{O(1)}}\,.
	\]
On the other hand, a trivial modification of bounds from Lemma~\ref{l:X.tail.bounds} (with $k$ in place of $k-1$) gives
	\[\mathbb{E}\mathbf{h}_{21}
	= \frac{\ddot{\alpha}-\dot{\alpha}}{2^k}
	\Bigg\{ 1 + \frac{O(1)}{2^{k/20}}
	\Bigg\}
	\,.\]
Combining the above estimates gives finally
	\[
	\Phi(\ddot{\alpha})
		-\Phi(\dot{\alpha})
	=\Bigg\{
	 - \frac{k(\ddot{\alpha}-\dot{\alpha}) }{2^k
		} 
	+\frac{(k-1)(\ddot{\alpha}-\dot{\alpha})}{2^k}
	\Bigg\}
	\Bigg\{ 1 + \frac{O(1)}{2^{k/20}}
	\Bigg\}
	= - \frac{\ddot{\alpha}-\dot{\alpha} }{2^k
		} 
		\Bigg\{ 1 + \frac{O(k)}{2^{k/20}}
	\Bigg\}\,.
	\]
This proves that $\Phi$ is strictly decreasing 
on the interval $\alpha_\textup{lbd}\le\alpha\le\alpha_\textup{ubd}$, as desired.
